DELIMITER ;;
CREATE DEFINER=`root`@`localhost` FUNCTION `fn_GetParentgroup`(grp smallint(6),company int,lvl int,cn char(1) ) RETURNS varchar(50) CHARSET latin1
BEGIN

declare gname varchar(50);

declare retval varchar(50);

declare RetGrp int;

declare g0 int;

declare g1 int;

declare g2 int;

declare g3 int;

declare g4 int;



declare n0 varchar(50);

declare n1 varchar(50);

declare n2 varchar(50);

declare n3 varchar(50);

declare n4 varchar(50);

declare v_finished int default 0;





declare GroupCode cursor for

select ifnull(g5.grp_code,0) gc0, g5.grp_name gn0,

ifnull(g4.grp_code,0) gc1 , g4.grp_name  gn1,

ifnull(g3.grp_code,0) gc2, g3.grp_name gn2,

ifnull(g2.grp_code,0) gc3, g2.grp_name gn3,

ifnull(g1.grp_code,0) gc4, g1.grp_name gn4

from 

acc_group_master g1 

left join acc_group_master g2 ON

    g1.grp_parent_code = g2.grp_code

    and g2.grp_comp_code=company

left join acc_group_master g3 ON

    g2.grp_parent_code = g3.grp_code

    and g3.grp_comp_code=company

left join acc_group_master g4 ON

    g3.grp_parent_code = g4.grp_code

    and g4.grp_comp_code=company

left join acc_group_master g5 ON

    g4.grp_parent_code = g5.grp_code

    and g5.grp_comp_code=company

where g1.grp_comp_code=company

 and g1.grp_code=grp;







OPEN GroupCode;



FETCH FROM GroupCode  into g0,n0,g1,n1,g2,n2,g3,n3,g4,n4 ;

close GroupCode;



case lvl

     when 0 then

    -- set RetGrp = if(g0=0,g1,if(g1=0,g2,if(g2=0,g3,if(g3=0,g4,g0))));

       set RetGrp = if(g0>0,g0,g1);

       set RetGrp = if(RetGrp>0,RetGrp,g2);

       set RetGrp = if(RetGrp>0,RetGrp,g3);

       set RetGrp = if(RetGrp>0,RetGrp,g4);

       set RetGrp = if(RetGrp>0,RetGrp,grp);

     when 1 then

     -- set RetGrp = if(g1=0,g2,if(g2=0,g3,if(g3=0,g4,g1)));

       set RetGrp = if(g1>0,g1,g2);

       set RetGrp = if(RetGrp>0,RetGrp,g3);

       set RetGrp = if(RetGrp>0,RetGrp,g4);

       set RetGrp = if(RetGrp>0,RetGrp,grp);

     when 2 then

     -- set RetGrp = if(g2=0,g3,if(g3=0,g4,g2));

       set RetGrp = if(g2>0,g2,g3);

       set RetGrp = if(RetGrp>0,RetGrp,g4);

       set RetGrp = if(RetGrp>0,RetGrp,grp);

     when 3 then

     -- set RetGrp = if(g3=0,g4,g3);

       set RetGrp = if(g3>0,g3,g4);

       set RetGrp = if(RetGrp>0,RetGrp,grp);

     when 4 then

     -- set RetGrp = if(g4=0,grp,g4);

       set RetGrp = if(g4>0,g4,grp);

end case;

set retval = RetGrp;

if (cn='N') then

set gname = (select grp_name from acc_group_master where grp_code = RetGrp and grp_comp_code = company);

set retval = gname;

end if;



RETURN retval;

END ;;
DELIMITER ;
