CREATE DEFINER=`root`@`localhost` FUNCTION `fn_GetPL`(compcode int,finid int,fmdate datetime,todate datetime) RETURNS decimal(11,0)
BEGIN

declare Income decimal;

declare Expense decimal;

declare pl decimal;

set Income = (select 

sum(Obdebit)-sum(Obcredit)+sum(debit)-sum(credit) 

from

 (

 select  led_name,led_grp_code as grpcode,1 as accref_comp_code,curbal_finid as accref_finid,

curbal_led_code as acctran_led_code,curbal_obdbamt as Obdebit, curbal_obcramt as Obcredit,

0 as debit,0 as credit,grp_name,grp_type,grp_pl_type,fn_GetParentgroup(grp_code,grp_comp_code,0,'N') as grpname 

from acc_current_balance,acc_ledger_master,acc_group_master where 

curbal_finid=finid and (curbal_obdbamt+curbal_obcramt)>0 and curbal_led_code = led_code

and led_comp_code=compcode  and led_grp_code = grp_code and grp_type not in ('B')  and

led_comp_code = grp_comp_code and grp_type='I'

union all 

 select led_name,led_grp_code as grpcode,accref_comp_code,accref_finid,acctran_led_code,

0 as Obdebit, 0 as Obcredit,

acctran_dbamt as debit,acctran_cramt as credit,grp_name,grp_type,grp_pl_type,

fn_GetParentgroup(grp_code,grp_comp_code,0,'N') as grpname  

from acc_ref,acc_tran,acc_ledger_master,acc_group_master where 

accref_comp_code=compcode and accref_seqno = acctran_accref_seqno and

accref_finid= finid and

accref_voudate>=fmdate and accref_voudate<=todate and 

acctran_led_code = led_code and led_grp_code = grp_code and grp_type not in ('B')  and

led_comp_code = grp_comp_code and grp_type='I'

) tt);



-- expense

set Expense = (select 

sum(Obdebit)-sum(Obcredit)+sum(debit)-sum(credit) 

from

 (

 select  led_name,led_grp_code as grpcode,1 as accref_comp_code,curbal_finid as accref_finid,

curbal_led_code as acctran_led_code,curbal_obdbamt as Obdebit, curbal_obcramt as Obcredit,

0 as debit,0 as credit,grp_name,grp_type,grp_pl_type,fn_GetParentgroup(grp_code,grp_comp_code,0,'N') as grpname 

from acc_current_balance,acc_ledger_master,acc_group_master where 

curbal_finid=finid and (curbal_obdbamt+curbal_obcramt)>0 and curbal_led_code = led_code

and led_comp_code=compcode  and led_grp_code = grp_code and grp_type not in ('B')  and

led_comp_code = grp_comp_code and grp_type='E'

union all 

 select led_name,led_grp_code as grpcode,accref_comp_code,accref_finid,acctran_led_code,

0 as Obdebit, 0 as Obcredit,

acctran_dbamt as debit,acctran_cramt as credit,grp_name,grp_type,grp_pl_type,

fn_GetParentgroup(grp_code,grp_comp_code,0,'N') as grpname  

from acc_ref,acc_tran,acc_ledger_master,acc_group_master where 

accref_comp_code=compcode and accref_seqno = acctran_accref_seqno and

accref_finid= finid and

accref_voudate>=fmdate and accref_voudate<=todate and 

acctran_led_code = led_code and led_grp_code = grp_code and grp_type not in ('B')  and

led_comp_code = grp_comp_code and grp_type='E'

) tt);



set pl = ((abs(Income)-Expense)*-1);



RETURN pl;

END ;;
DELIMITER ;
