invh_cgst_amt as CgstVal,
invh_igst_amt as IgstVal,
'0.00' AS CesVal,0.00 AS StCesVal,
'0.00' AS Discount,
 invh_tcs_amt as  OthChrg,
 invh_roff as RndOffAmt,
 invh_netamt as InvVal,
  invh_netamt as TotInvValFc,
  '' as "Nm",'' AS "AccDet",'' AS "Mode",'' AS "FinInsBr",'' AS "PayTerm",'' AS "PayInstr",
0.00 AS "CrTrn",0.00 AS "DirDr",invh_crd_days AS "CrDay",'' AS "PaidAmt",'' AS "PaymtDue",'' AS "InvRm",
DATE_FORMAT(a.invh_date,'%d/%m/%Y')  as "InvStDt",
DATE_FORMAT(a.invh_date,'%d/%m/%Y')  as "InvEndDt",
'' AS InvNo,'' AS "InvDt",'' AS "OthRefNo",'' AS "RecAdvRef" ,
'' AS "RecAdvRefr",'' AS "RecAdvDt",'' AS "TendRefr",
'' AS "ContrRefr",'' AS "ExtRefr",'' AS "ProjRefr",'' AS "PORefr",'' AS "PORefDt",'' AS "Url",'' AS "Docs",'' AS "Info",
'' AS "ShipBNo",'' AS "ShipBDt",'' AS "Port",'N' AS "RefClm",'' AS "ForCur",'' AS "CntCode",'' AS "TransId",'' AS "TransName",'' AS "TransMode"
,'' AS "Distance",'' AS "TransDocNo",'' AS "TransDocDt",'N' AS "VehNo",'' AS "VehType",'' ExpDuty,
case when invh_delivery_statecode = 0 then state_codeno else delivery_state_codeno end as Pos, 
invh_netamt as TotInvVal
 from    
    trnsal_invoice_header a,
	massal_customer b,
    mas_state c ,
    mas_delivery_state d , mas_dealer e,mas_company f
    WHERE
    invh_comp_code = 1  AND invh_fincode > 22 
	AND invh_comp_code = company_code
    AND cust_state = state_code 
    AND invh_delivery_statecode = delivery_state_code
    AND invh_party = cust_code   
    AND cust_dealer = dealer_code   
    AND invh_date >= '2022-10-01' 
    AND E_inv_confirm = "Y" 
    and (a.U_TCSSTatus='' or (a.U_TCSSTatus='E' and a.U_Reupload='Y'));
END ;;
