     massal_variety d, masprd_variety e, masprd_type f  , mas_state g 
    , mas_delivery_state h , mas_dealer i
WHERE
        invh_comp_code = 1  AND invh_fincode > 22
        AND b.invt_var = d.var_code and d.var_grpcode = e.var_groupcode and e.var_typecode =  f.vargrp_type_code
        AND cust_state = g.state_code 
