CREATE DEFINER=`root`@`%` PROCEDURE `20231206@AIS_EInvoiceIntegration_LoadInvoiceHeader`(IN Cancelled CHAR(5))
BEGIN
SELECT  'https://gsp.adaequare.com/enriched/ei/api' As EInvURLName 
,'API_SRIHARI_2017' as EInvUserName,'Srihari_2021' as EInvPassword ,    
invh_invrefno as DocEntry,invh_invrefno as DocNum,'13' as ObjType,'33AALCS4958D1Z7' as GSTIN,
'trnsal_invoice_header' as TableName,'1.01' as Version,'' as IRN ,'GST' as TaxSch, 'B2B' as SupTyp , 'N' As RegRev,
'null' As ECMGSTIN,'N' AS IgstOnIntra, 'INV' AS  TYP,invh_invrefno as No, DATE_FORMAT(a.invh_date,'%d/%m/%Y')  as  Dt,
company_gst as SellerGstin,
company_name as SellerLglNm, company_name as  SellerTrdNm,
company_add1 as SellerAddr1,
company_add2  as SellerAddr2,
company_add3 as  SellerLoc,
company_zipcode as SellerPin,
'33'  as SellerStcd,
company_contact as SellerPh,
company_email as SellerEm,
cust_gstin as BuyerGstin,
cust_name as BuyerLglNm,
cust_name as BuyerTrdNm,
state_codeno as BuyerPOS,
cust_add1 as BuyerAddr1,
left(concat(cust_add2,cust_add3),100) as BuyerAddr2,
cust_city as BuyerLoc,
cust_zip as BuyerPin,
state_codeno as BuyerStcd,
left(cust_phone,10) as BuyerPh,
case when cust_email = ''  then 'noemailid@gmail.com' else rtrim(ltrim(cust_email)) end  as BuyerEm,
/*company_name as DispNm,
company_add1 as DispAddr1,
company_add2  as DispAddr2,
company_add3 as  DispLoc,
company_zipcode as DispPin,
'33'  as DispStcd,*/
'' as DispNm,
'' as DispAddr1,
''  as DispAddr2,
'' as  DispLoc,
'' as DispPin,
''  as DispStcd,
case when invh_delivery_gst = '' then '' else invh_delivery_gst end as ShipGstin, 
case when invh_delivery_add1 = '' then '' else invh_delivery_add1 end as ShipLglNm, 
case when invh_delivery_add1 = '' then '' else invh_delivery_add1 end as ShipTrdNm, 
case when invh_delivery_add2 = '' then '' else invh_delivery_add2 end as ShipAddr1, 
case when invh_delivery_add3 = '' then '' else invh_delivery_add3 end as ShipAddr2, 
case when invh_delivery_city = '' then '' else invh_delivery_city end as ShipLoc, 
case when invh_delivery_pin = '' then '' else invh_delivery_pin end as ShipPin, 
case when invh_delivery_statecode = 0 then '' else delivery_state_codeno end as ShipStcd, 
/*
'' as ShipGstin, 
'' as ShipLglNm, 
'' as ShipTrdNm, 
'' as ShipAddr1, 
'' as ShipAddr2, 
'' as ShipLoc, 
'' as ShipPin, 
'' as ShipStcd,
*/
invh_taxableamt as AssVal,
invh_sgst_amt as SgstVal,
invh_cgst_amt as CgstVal,
invh_igst_amt as IgstVal,
'0.00' AS CesVal,0.00 AS StCesVal,
'0.00' AS Discount,
 invh_tcs_amt as  OthChrg,
 invh_roff as RndOffAmt,
 invh_netamt as InvVal,
  invh_netamt as TotInvValFc,
  '' as "Nm",'' AS "AccDet",'' AS "Mode",'' AS "FinInsBr",'' AS "PayTerm",'' AS "PayInstr",
0.00 AS "CrTrn",0.00 AS "DirDr",invh_crd_days AS "CrDay",'' AS "PaidAmt",'' AS "PaymtDue",'' AS "InvRm",
DATE_FORMAT(a.invh_date,'%d/%m/%Y')  as "InvStDt",
DATE_FORMAT(a.invh_date,'%d/%m/%Y')  as "InvEndDt",
'' AS InvNo,'' AS "InvDt",'' AS "OthRefNo",'' AS "RecAdvRef" ,
'' AS "RecAdvRefr",'' AS "RecAdvDt",'' AS "TendRefr",
'' AS "ContrRefr",'' AS "ExtRefr",'' AS "ProjRefr",'' AS "PORefr",'' AS "PORefDt",'' AS "Url",'' AS "Docs",'' AS "Info",
'' AS "ShipBNo",'' AS "ShipBDt",'' AS "Port",'N' AS "RefClm",'' AS "ForCur",'' AS "CntCode",'' AS "TransId",'' AS "TransName",'' AS "TransMode"
,'' AS "Distance",'' AS "TransDocNo",'' AS "TransDocDt",'N' AS "VehNo",'' AS "VehType",'' ExpDuty,
case when invh_delivery_statecode = 0 then state_codeno else delivery_state_codeno end as Pos, 
invh_netamt as TotInvVal
 from    
    trnsal_invoice_header a,
	massal_customer b,
    mas_state c ,
    mas_delivery_state d , mas_dealer e,mas_company f
    WHERE
    invh_comp_code = 1  AND invh_fincode > 22 
	AND invh_comp_code = company_code
    AND cust_state = state_code 
    AND invh_delivery_statecode = delivery_state_code
    AND invh_party = cust_code   
    AND cust_dealer = dealer_code   
    AND invh_date >= '2022-10-01' 
    AND E_inv_confirm = "Y" 
    and (a.U_TCSSTatus='' or (a.U_TCSSTatus='E' and a.U_Reupload='Y'));
END ;;
DELIMITER ;
