  '' as "Nm",'' AS "AccDet",'' AS "Mode",'' AS "FinInsBr",'' AS "PayTerm",'' AS "PayInstr",
0.00 AS "CrTrn",0.00 AS "DirDr",0 AS "CrDay",'' AS "PaidAmt",'' AS "PaymtDue",'' AS "InvRm",
DATE_FORMAT(a.os_date,'%d/%m/%Y')  as "InvStDt",
DATE_FORMAT(a.os_date,'%d/%m/%Y')  as "InvEndDt",
'' AS InvNo,'' AS "InvDt",'' AS "OthRefNo",'' AS "RecAdvRef" ,
'' AS "RecAdvRefr",'' AS "RecAdvDt",'' AS "TendRefr",
'' AS "ContrRefr",'' AS "ExtRefr",'' AS "ProjRefr",'' AS "PORefr",'' AS "PORefDt",'' AS "Url",'' AS "Docs",'' AS "Info",
'' AS "ShipBNo",'' AS "ShipBDt",'' AS "Port",'N' AS "RefClm",'' AS "ForCur",'' AS "CntCode",'' AS "TransId",'' AS "TransName",'' AS "TransMode"
,'' AS "Distance",'' AS "TransDocNo",'' AS "TransDocDt",'N' AS "VehNo",'' AS "VehType",'' ExpDuty,
state_codeno as Pos, 
os_netamt as TotInvVal
 from     (
    select os_compcode, os_fincode, os_seqno, os_docno, os_state_type, os_invno, os_date, os_custcode, 
    sum(os_value) os_value, sum(os_others) os_others,  sum(os_taxable) os_taxable,sum(os_cgst) os_cgst , sum(os_sgst) os_sgst, sum(os_igst) os_igst, sum(os_rounding) os_rounding, sum(os_netamt) os_netamt, os_paymode, os_transport, os_vehno, os_remarks, os_ourref, os_partyref, os_accupd, os_acvou_no, os_acvou_date, os_acc_seqno, os_invtime, os_cancel, U_irnno, U_EWBNo, U_ewayreq, U_ReUpload, U_QR, U_TCSStatus, U_AckNo, U_AckDate, U_eInvCancel, U_CLReason, U_CLRemarks, U_EBCLRemarks, U_EBCLReason, U_EWayBillNo, U_EWayBillDt, U_ewbCancel, U_EWayVTilDt, U_EWBStatus, E_inv_confirm, invh_invrefno, invh_ewaybillno, sum(os_tcsamt) os_tcsamt from trn_other_sales where os_compcode = 1 and os_fincode >= 24 
    group by os_compcode, os_fincode, os_seqno, os_docno, os_state_type, os_invno, os_date, os_custcode,
    os_paymode, os_transport, os_vehno, os_remarks, os_ourref, os_partyref, os_accupd, os_acvou_no, os_acvou_date, os_acc_seqno, os_invtime, os_cancel, U_irnno, U_EWBNo, U_ewayreq, U_ReUpload, U_QR, U_TCSStatus, U_AckNo, U_AckDate, U_eInvCancel, U_CLReason, U_CLRemarks, U_EBCLRemarks, U_EBCLReason, U_EWayBillNo, U_EWayBillDt, U_ewbCancel, U_EWayVTilDt, U_EWBStatus, E_inv_confirm, invh_invrefno, invh_ewaybillno    
    ) a,
	massal_customer b,
    mas_state c ,
    mas_company f
    WHERE
    os_compcode = 1  AND os_fincode > 22 
    AND os_compcode = company_code
    AND cust_state = state_code 
    AND cust_gst_type = 'R'   --  Registered Suppliers Tag
    AND os_custcode = cust_code   
    AND os_date  >= '2024-07-02' 
    AND E_inv_confirm = "Y" 
    AND (a.U_TCSSTatus='' or (a.U_TCSSTatus='E' and a.U_Reupload='Y'));
END ;;
DELIMITER ;
