CREATE DEFINER=`root`@`%` PROCEDURE `@AIS_EInvoiceIntegration_LoadInvoiceItemDetails`(IN DocEntry nVARCHAR(200), IN ObjType CHAR(10))
BEGIN

SET @count:=0;
SET @count1:=0;
SET @count2:=0;
SELECT  
(@count:=@count+1) AS SlNo, 
    concat(var_desc , " - ", case when var_unit = 1 then cast(var_size2 as CHAR)  else concat(var_size1  , "X", var_size2)  end   ,case when var_inchcm = "I" then " Inch " else " CM " end, (case when var_shade = 'NS' then 'NAT' when var_shade = 'GY' then 'GYT' when var_shade = 'DP' then 'DP' when var_shade = 'SY' then 'SHYS' when var_shade = 'GB' then 'GB'  when var_shade = 'BB' then 'BB'  when var_shade = 'SHVV+' then 'VV' else var_shade end)) as PrdDesc,
    'N' as IsServc,
    var_tariffno as HsnCd,
   -- cast(invh_tcs_amt  / invh_totwt * invt_wt   as decimal(18,2)) + Cast(  (invt_taxable + (invt_taxable  * (invh_igst_per /100))+ (invt_taxable  * (invh_cgst_per /100)) + (invt_taxable  * (invh_sgst_per /100))) as Decimal(18,2))   As TotItemVal,  
    Cast(  (invt_taxable + (invt_taxable  * (invh_igst_per /100))+ (invt_taxable  * (invh_cgst_per /100)) + (invt_taxable  * (invh_sgst_per /100))) as Decimal(18,2))   As TotItemVal,  
--    (cast(invh_tcs_amt  / invh_totwt * invt_wt   as decimal(18,2))  + Cast(  (invt_taxable + (invt_taxable  * (invh_igst_per /100))+ (invt_taxable  * (invh_cgst_per /100)) + (invt_taxable  * (invh_sgst_per /100))) as Decimal(18,2)))   As TotItemVal,  
      '0.00' as "Barcde",
    Cast(invt_wt/1000 as decimal(18,3)) as Qty,
	0.00 AS "FreeQty",
    'MTS' AS "UNIT",
    invt_urate+ invh_frt_rate as UNITPRICE,
    invt_taxable as  TotAmt,
    0.00 AS "DISCOUNT",0.00 AS "PreTaxVal",
    invt_taxable as "ASSAMT",
    cast(invh_cgst_per + invh_sgst_per+ invh_igst_per as decimal(18,2)) as  GstRt,
    cast(invt_taxable  * invh_igst_per /100 as decimal(18,2))   as "IgstAmt",
    cast(invt_taxable  * invh_cgst_per /100 as decimal(18,2))   as "CgstAmt",
    cast(invt_taxable  * invh_sgst_per /100 as decimal(18,2))   as "SgstAmt",
    0.00 AS  "CesRt",0.00 AS "CesAmt",0.00 AS  "CesNonAdvlAmt",0.00 AS  "StateCesRt",0.00 AS "StateCesAmt",0.00 AS  "StateCesNonAdvlAmt",
    -- cast(invh_tcs_amt  * invh_tcs_per /100 as decimal(18,2))   as "OthChrg",
--     cast(invh_tcs_amt  / invh_totwt * invt_wt   as decimal(18,2))   as "OthChrg",
      0   as "OthChrg",
    '1' AS OrdInlineRef,'21' AS "OrgCntry",'1' AS "PrdSlNo",
    '' AS "Nm",
    '' AS "ExpDt",'' AS "WrDt",'' AS "Nm",'' AS "Val"
FROM

    trnsal_invoice_header a,
    trnsal_invoice_trailer b,
	massal_customer c,
     massal_variety d, masprd_variety e, masprd_type f  , mas_state g 
    , mas_delivery_state h , mas_dealer i
WHERE
        invh_comp_code = 1  AND invh_fincode > 22
        AND b.invt_var = d.var_code and d.var_grpcode = e.var_groupcode and e.var_typecode =  f.vargrp_type_code
        AND cust_state = g.state_code 
         AND invh_delivery_statecode = h.delivery_state_code
        AND invh_party = cust_code   
        AND cust_dealer = dealer_code   
        AND invh_seqno = invt_seqno
        AND E_inv_confirm = "Y" 
		AND invh_fincode = invt_fincode 
        AND invh_comp_code = invt_compcode
		AND invh_date >= '2024-07-02' 
   AND a.invh_invrefno = DocEntry
   -- 
   union all
   
   -- DEBIT / CREDIT NOTE
   

SELECT  
(@count1:=@count1+1) AS SlNo, 
 case when dbcr_type = "CNG" then "Credit Note" else "Debit Note" end  as PrdDesc,
    'N' as IsServc,
    dbcr_hsncode as HsnCd,
    Cast(  (dbcrt_taxable + (dbcrt_taxable  * (dbcrt_igstper /100))+ (dbcrt_taxable  * (dbcrt_cgstper /100)) + (dbcrt_taxable  * (dbcrt_sgstper /100))) as Decimal(18,2))   As TotItemVal,  
    '0.00' as "Barcde",
    Cast(0 as decimal(18,3)) as Qty,
	0.00 AS "FreeQty",
    'MTS' AS "UNIT",
    0 as UNITPRICE,
    dbcrt_taxable as  TotAmt,
    0.00 AS "DISCOUNT",0.00 AS "PreTaxVal",
    dbcrt_taxable as "ASSAMT",
    cast(dbcrt_cgstper + dbcrt_sgstper+ dbcrt_igstper as decimal(18,2)) as  GstRt,
    cast(dbcrt_taxable  * dbcrt_igstper /100 as decimal(18,2))   as "IgstAmt",
    cast(dbcrt_taxable  * dbcrt_cgstper /100 as decimal(18,2))   as "CgstAmt",
    cast(dbcrt_taxable  * dbcrt_sgstper /100 as decimal(18,2))   as "SgstAmt",
    0.00 AS  "CesRt",0.00 AS "CesAmt",0.00 AS  "CesNonAdvlAmt",0.00 AS  "StateCesRt",0.00 AS "StateCesAmt",0.00 AS  "StateCesNonAdvlAmt",
      0   as "OthChrg",
    '1' AS OrdInlineRef,'21' AS "OrgCntry",'1' AS "PrdSlNo",
    '' AS "Nm",
    '' AS "ExpDt",'' AS "WrDt",'' AS "Nm",'' AS "Val"
FROM

    acc_dbcrnote_header a,
    acc_dbcrnote_trailer b,
	massal_customer c,
    mas_state d 
WHERE
        dbcr_comp_code = 1  AND dbcr_finid >= 23        
        AND dbcr_type in ('CNG','SDN')
        AND cust_state = state_code  
        AND dbcr_partycode = cust_code  
        AND (dbcr_party_type = 'C' or dbcr_party_type = 'S')
        AND dbcr_seqno = dbcrt_seqno
	    AND dbcr_date >= '2024-07-06'
        AND dbcr_vouno = DocEntry
        AND E_inv_confirm = "Y" 
    AND (a.U_TCSSTatus='' or (a.U_TCSSTatus='E' and a.U_Reupload='Y'))
      -- 
   union all
   
   -- OTHER SALES
   
-- SET @count:=0;
SELECT  
(@count2:=@count2+1) AS SlNo, 
    salitem_name as PrdDesc,
    'N' as IsServc,
    salitem_hsn as HsnCd,
    cast(  (os_taxable + (os_taxable  * (os_cgstper /100))+ (os_taxable  * (os_sgstper /100)) + (os_taxable  * (os_igstper /100))) as Decimal(18,2))   As TotItemVal,  
    '0.00' as "Barcde",
    Cast(os_qty as decimal(18,3)) as Qty,
    0.00 AS "FreeQty",
    'MTS' AS "UNIT",
    os_rate  as UNITPRICE,
    os_taxable as  TotAmt,
    0.00 AS "DISCOUNT",0.00 AS "PreTaxVal",
    os_taxable as "ASSAMT",
    cast(os_cgstper + os_sgstper+ os_igstper as decimal(18,2)) as  GstRt,
    cast(os_taxable  * os_igstper /100 as decimal(18,2))   as "IgstAmt",
    cast(os_taxable  * os_cgstper /100 as decimal(18,2))   as "CgstAmt",
    cast(os_taxable  * os_sgstper /100 as decimal(18,2))   as "SgstAmt",

    0.00 AS  "CesRt",0.00 AS "CesAmt",0.00 AS  "CesNonAdvlAmt",0.00 AS  "StateCesRt",0.00 AS "StateCesAmt",0.00 AS  "StateCesNonAdvlAmt",

      0   as "OthChrg",
    '1' AS OrdInlineRef,'21' AS "OrgCntry",'1' AS "PrdSlNo",
    '' AS "Nm",
    '' AS "ExpDt",'' AS "WrDt",'' AS "Nm",'' AS "Val"
FROM

    trn_other_sales a,
	massal_customer b,
    mas_othersales_item_master  c , mas_state d 
WHERE
        os_compcode = 1  AND os_fincode > 22
        AND a.os_item = c.salitem_code 
        AND cust_state = d.state_code 
    AND cust_gst_type = 'R'   --  Registered Suppliers Tag
    AND os_custcode = cust_code  
        AND E_inv_confirm = "Y" 
	    AND os_date >= '2024-07-02'
        AND a.os_invno = DocEntry
        AND (a.U_TCSSTatus='' or (a.U_TCSSTatus='E' and a.U_Reupload='Y'));
   End ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
