CREATE DEFINER=`root`@`%` PROCEDURE `@AIS_TCSIntegration_LoadCancelEInvHeader`(IN Cancelled Char(5))
begin
  
SELECT Q.*,'https://gsp.adaequare.com/enriched/ei/api' As EInvURLName,
'API_SRIHARI_2017' as EInvUserName
,'Srihari_2021' as EInvPassword from (
 
 
SELECT   
T0.invh_invrefno as DocEntry ,'13' as ObjType ,'trnsal_invoice_header' As TableName,
T0.invh_invrefno as DocNum, 
'33AALCS4958D1Z7' AS 'GSTIN',
'' AS 'VERSION',U_irnno AS  Irn ,T0.U_CLReason as cnlrsn,T0.U_CLRemarks as cnlrem
FROM trnsal_invoice_header  T0
Where  U_eInvCancel='Y' and
T0.invh_date>='20201019' and U_TcsStatus='S'
  and U_ReUpload ='Y' 
   )Q  ;
 End ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
