CREATE DEFINER=`root`@`%` PROCEDURE `@AIS_TCSIntegration_LoadCancelEWayBillHeader`(in Cancelled varchar(200))
BEGIN
 
SELECT Q.*,'https://gsp.adaequare.com/enriched/ei/api' as EWBURLName
,'API_SRIHARI_2017' As EWbUserName,'Srihari_2021' As EWbPassword
from (
 SELECT   
T0.invh_invrefno as DocEntry ,'13' ObjType ,'trnsal_invoice_header' As TableName,T0.invh_invrefno as DocNum, 
'33AALCS4958D1Z7'
AS 'GSTIN',
'' AS 'VERSION',T0.U_EWayBillNo AS  ewbNo ,T0.U_EBCLReason as cancelRsnCode,T0.U_EBCLRemarks as cancelRmrk
FROM trnsal_invoice_header  T0

Where  U_ewbCancel='Y' and
T0.invh_date>='2022-06-02' and U_TcsStatus='S' 

  and U_ReUpload ='Y'  and   T0.U_EWayBillNo !=''
  -- and 1=2
  
   )Q;
 

END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
