DELIMITER ;;
CREATE DEFINER=`root`@`%` PROCEDURE `@AIS_TCSIntegration_LoadEWayBillHeader`(IN Cancelled CHAR(5))
BEGIN
SELECT 'https://www.alankitgst.com/eInvoiceGateway/eiewb/v1.03/ewaybill' As EWBURLName 
,'API_SRIHARI_2024' as EWBUserName,'Hari@1234' as EWBPassword , 'AL8C6k4J6N1j1Z4Y7n' as SubscriptionKey,   
invh_invrefno as DocEntry,invh_invrefno as DocNum,'13' as ObjType, 
'33AALCS4958D1Z7' as GSTIN,'trnsal_invoice_header' as TableName,'' as version, a.U_irnno as  Irn,
'1' as TransMode,invh_transportGST AS  Transid,invh_transportname as TransName,invh_distance as Distance 
 ,invh_invrefno as TrnDocNO,DATE_FORMAT(a.invh_date,'%d/%m/%Y') as TrnDocDt,
 ifnull(invh_vehi_no,'0.00') as Vehno,
  'R' as Vehtype ,
company_name as ShipFrom_Addr1,
left(concat(company_add1,company_add2),100) as ShipFrom_Addr2,'KEELANMARAI NADU' as ShipFrom_Loc,
company_zipcode as ShipFrom_Pin,'33' AS ShipFrom_Stcd,
cust_name as ShipTo_Addr1,left(concat(cust_add1,cust_add2,cust_add3),100) AS  ShipTo_Addr2,
cust_city as  ShipTo_Loc,cust_zip AS  ShipTo_Pin,state_codeno As ShipTo_Stcd 

FROM 
    trnsal_invoice_header a,
	massal_customer b,
    mas_state c ,
    mas_delivery_state d , mas_dealer e,mas_company f
WHERE
    invh_comp_code = 1  AND invh_fincode >= 22 
	AND invh_comp_code = company_code
    AND cust_state = state_code 
    AND invh_delivery_statecode = delivery_state_code
    AND invh_party = cust_code   
    AND cust_dealer = dealer_code 
    and U_irnno !=''
     and U_EWayBillNo=''
    and  a.invh_date >= '2024-06-01' 
    AND invh_invrefno != 'OS/347/22-23' --
     and (a.U_EWBStatus='' or (a.U_EWBStatus='E' and a.U_Reupload='Y'))
    
    -- 
    union all
    --  OTHER SALES - 
    
    SELECT 'https://www.alankitgst.com/eInvoiceGateway/eiewb/v1.03/ewaybill' As EWBURLName 
,'API_SRIHARI_2024' as EWBUserName,'Hari@1234' as EWBPassword ,  'AL8C6k4J6N1j1Z4Y7n' as SubscriptionKey,  
os_invno as DocEntry,os_invno as DocNum,'13' as ObjType, 
'33AALCS4958D1Z7' as GSTIN,'trn_other_sales' as TableName,'' as version, a.U_irnno as  Irn,
'1' as TransMode,'' AS  Transid,'' as TransName,cust_distance as Distance 
 ,os_invno as TrnDocNO,DATE_FORMAT(a.os_date,'%d/%m/%Y') as TrnDocDt,
 ifnull(os_vehno,'0.00') as Vehno,
  'R' as Vehtype ,
company_name as ShipFrom_Addr1,
left(concat(company_add1,company_add2),100) as ShipFrom_Addr2,'KEELANMARAI NADU' as ShipFrom_Loc,
company_zipcode as ShipFrom_Pin,'33' AS ShipFrom_Stcd,
cust_name as ShipTo_Addr1,left(concat(cust_add1,cust_add2,cust_add3),100) AS  ShipTo_Addr2,
cust_city as  ShipTo_Loc,cust_zip AS  ShipTo_Pin,state_codeno As ShipTo_Stcd 

FROM 
    trn_other_sales a,
    massal_customer b,
    mas_state c ,
    mas_company d
WHERE
    os_compcode = 1  AND os_fincode >= 23
    AND os_compcode = company_code
    AND cust_state = state_code 
    AND os_custcode = cust_code   
    AND U_irnno !=''
    AND U_EWayBillNo=''
    AND a.os_date >= '2024-06-01' 
    AND (a.U_EWBStatus='' or (a.U_EWBStatus='E' and a.U_Reupload='Y'));
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `accsprepbalancesheet` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`%` PROCEDURE `accsprepbalancesheet`(finid int,

compcode int,

fromdate datetime,

todate datetime)
BEGIN

select 

led_name,(sum(Obdebit)-sum(Obcredit)+sum(debit)-sum(credit))*(-1) as closing,

grp_name,grpname,led_type

from

 (

 select  led_name,led_grp_code as grpcode,1 as accref_comp_code,curbal_finid as accref_finid,

curbal_led_code as acctran_led_code,curbal_obdbamt as Obdebit, curbal_obcramt as Obcredit,

