CREATE DEFINER=`root`@`%` PROCEDURE `accspreptrialbalanceclosing_Ledger_Monthwise`(
finyear int,

compcode int,

fromdate datetime,

todate datetime ,

ledgercode int,finfirstdate date
)
BEGIN
 if  finfirstdate = fromdate then
   select sum(debit) debit,sum(credit) credit ,  month , priority  from (  
  select 0 debit,0 credit , 4 month , 1 priority  
  union all
  select 0 debit,0 credit , 5 month , 2 priority  
  union all
  select 0 debit,0 credit , 6 month , 3 priority 
  union all
  select 0 debit,0 credit , 7 month , 4 priority  
  union all
  select 0 debit,0 credit , 8 month , 5 priority 
  union all
  select 0 debit,0 credit , 9 month, 6 priority       
  union all
  select 0 debit,0 credit , 10 month, 7 priority   
  union all
  select 0 debit,0 credit , 11 month, 8 priority   
  union all
  select 0 debit,0 credit , 12 month, 9 priority  
  union all
  select 0 debit,0 credit , 1 month  , 10 priority 
  union all
  select 0 debit,0 credit , 2 month , 11 priority
  union all
  select 0 debit,0 credit , 3 month , 12 priority  
  union all
select * from (
select   
  sum(atn.acctran_dbamt)   as debit,   
  sum(atn.acctran_cramt)   as credit,   
  month(arf.accref_voudate)  as month , 
  case when month(arf.accref_voudate) = 4 then 1 else
  case when month(arf.accref_voudate) = 5 then 2 else
  case when month(arf.accref_voudate) = 6 then 3 else
  case when month(arf.accref_voudate) = 7 then 4 else
  case when month(arf.accref_voudate) = 8 then 5 else
  case when month(arf.accref_voudate) = 9 then 6 else  
  case when month(arf.accref_voudate) = 10 then 7 else
  case when month(arf.accref_voudate) = 11 then 8 else
  case when month(arf.accref_voudate) = 12 then 9 else
  case when month(arf.accref_voudate) = 1 then 10 else
  case when month(arf.accref_voudate) = 2 then 11 else
  case when month(arf.accref_voudate) = 3 then 12     
  end end end end end end  end end end  end end end as priority
 from  acc_ref arf,   
  acc_tran atn  
 where  arf.accref_comp_code  =  compcode and   
  arf.accref_finid =  finyear and     
  arf.accref_vou_type not in ('OB') and  
  arf.accref_seqno  =  atn.acctran_accref_seqno and   
  atn.acctran_led_code  =  ledgercode  and   accref_voudate  > '2023-03-31'
 group by  year(arf.accref_voudate),  
   month(arf.accref_voudate) , priority  
 order by  year(arf.accref_voudate),  
   month(arf.accref_voudate) 
  )a1 
  )aa2 group by month,priority order by priority;
 else
   select sum(debit) debit,sum(credit) credit ,  month , priority  from (  
  select 0 debit,0 credit , 4 month , 1 priority  
  union all
  select 0 debit,0 credit , 5 month , 2 priority  
  union all
  select 0 debit,0 credit , 6 month , 3 priority 
  union all
  select 0 debit,0 credit , 7 month , 4 priority  
  union all
  select 0 debit,0 credit , 8 month , 5 priority 
  union all
  select 0 debit,0 credit , 9 month, 6 priority       
  union all
  select 0 debit,0 credit , 10 month, 7 priority   
  union all
  select 0 debit,0 credit , 11 month, 8 priority   
  union all
  select 0 debit,0 credit , 12 month, 9 priority  
  union all
  select 0 debit,0 credit , 1 month  , 10 priority 
  union all
  select 0 debit,0 credit , 2 month , 11 priority
  union all
  select 0 debit,0 credit , 3 month , 12 priority  
  union all
select * from (
select   
  sum(atn.acctran_dbamt)   as debit,   
  sum(atn.acctran_cramt)   as credit,   
  month(arf.accref_voudate)  as month , 
  case when month(arf.accref_voudate) = 4 then 1 else
  case when month(arf.accref_voudate) = 5 then 2 else
  case when month(arf.accref_voudate) = 6 then 3 else
  case when month(arf.accref_voudate) = 7 then 4 else
  case when month(arf.accref_voudate) = 8 then 5 else
  case when month(arf.accref_voudate) = 9 then 6 else  
  case when month(arf.accref_voudate) = 10 then 7 else
  case when month(arf.accref_voudate) = 11 then 8 else
  case when month(arf.accref_voudate) = 12 then 9 else
  case when month(arf.accref_voudate) = 1 then 10 else
  case when month(arf.accref_voudate) = 2 then 11 else
  case when month(arf.accref_voudate) = 3 then 12     
  end end end end end end  end end end  end end end as priority
 from  acc_ref arf,   
  acc_tran atn  
 where  arf.accref_comp_code  =  compcode and   
  arf.accref_finid =  finyear and     
  arf.accref_vou_type not in ('OB') and  
  arf.accref_seqno  =  atn.acctran_accref_seqno and   
  atn.acctran_led_code  =  ledgercode  and   accref_voudate  >=  fromdate and   accref_voudate  <=  todate 
 group by  year(arf.accref_voudate),  
   month(arf.accref_voudate) , priority  
 order by  year(arf.accref_voudate),  
   month(arf.accref_voudate) 
  )a1 
  )aa2 where debit + credit > 0 group by month,priority order by priority;
 end if;
END ;;
DELIMITER ;
