    max(acctrail_inv_value) acctrail_inv_value, max(acctrail_adj_value) acctrail_adj_value, max(acctrail_crdays) acctrail_crdays, duedate, oddays, acctrail_amtmode, accref_voudate,sum(adjamt) adjamt
     from (
     select  accref_seqno ,grp_name,grp_code,cust_name,acctrail_led_code,accref_vouno, acctrail_inv_no,  acctrail_inv_date, acctrail_inv_value, acctrail_adj_value, 
	 acctrail_crdays ,  DATE_FORMAT(DATE_ADD(accref_voudate, INTERVAL acctrail_crdays DAY) ,'%d-%m-%Y') as  duedate,
	 DATEDIFF( todate , DATE_ADD(accref_voudate, INTERVAL acctrail_crdays DAY))  as oddays,acctrail_amtmode,accref_voudate , 0 as adjamt
	 from acc_ref ref  left join acc_trail trail 
	 on ref.accref_seqno = trail.acctrail_accref_seqno join massal_customer mas 
	  join  acc_group_master grp on mas.cust_acc_group = grp.grp_code
	 on trail.acctrail_led_code = mas.cust_code  and acctrail_inv_value > acctrail_adj_value and acctrail_led_code = ledcode  and mas.cust_type != 'G'
	 where accref_comp_code = compcode and accref_voudate <= todate 
     -- and accref_vou_type in ('EXP','PSP','PLW','PPF','PIW','PIC','PSC','PDE','PUR','GJV','BKP','PGS','PFU','OPB')   

    union all
    
     	select  ref_adjseqno accref_seqno , grp.grp_name,grp.grp_code,cust_name,acctrail_led_code, ref_adjvouno ref_adjvouno,
                 acctrail_inv_no,  acctrail_inv_date, acctrail_inv_value, acctrail_adj_value,acctrail_crdays , 
      			   DATE_FORMAT(DATE_ADD(accref_voudate, INTERVAL acctrail_crdays DAY) ,'%d-%m-%Y') as  duedate,
				 DATEDIFF( todate, DATE_ADD(accref_voudate, INTERVAL acctrail_crdays DAY))  as oddays,acctrail_amtmode,
		        accref_voudate,  ref_adjamount  adjamt
				from acc_adjustments ref  left join acc_trail trail 
				 on ref.ref_adjseqno = trail.acctrail_accref_seqno join massal_customer mas 
				 on trail.acctrail_led_code = mas.cust_code  and acctrail_led_code = ledcode  
				 join acc_group_master grp on mas.cust_acc_group = grp.grp_code  
                join  acc_group_master maingrp on  grp.grp_code = maingrp.grp_code 
			    join acc_ref on accref_seqno = acctrail_accref_seqno and trail.acctrail_led_code = ref_ledcode
                 where ref_compcode = compcode and accref_voudate <= todate and ref_docdate > todate  -- and ref_adjvoutype != 'GSI' 
) a1                 
group by accref_seqno, grp_name, grp_code, cust_name, acctrail_led_code, accref_vouno, acctrail_inv_no, acctrail_inv_date, duedate,oddays,acctrail_amtmode, accref_voudate
) a2                 
group by accref_seqno, grp_name, grp_code, cust_name, acctrail_led_code, accref_vouno, acctrail_inv_no, acctrail_inv_date, duedate,oddays,acctrail_amtmode, accref_voudate
     )a1   order by accref_voudate asc , acctrail_inv_no; -- order by  grp_name,grp_code,accref_seqno;
 else 
 	 select *,
	case when oddays<= agedays1 then  acctrail_inv_value- acctrail_adj_value else 0 end as Agegrp1,
	case when oddays > agedays1 and  oddays<= agedays2 then  acctrail_inv_value- acctrail_adj_value else 0 end as Agegrp2,
	case when oddays > agedays2 and  oddays<= agedays3 then  acctrail_inv_value- acctrail_adj_value else 0 end as Agegrp3,
	case when oddays > agedays3 and  oddays<= agedays4 then  acctrail_inv_value- acctrail_adj_value else 0 end as Agegrp4,
	case when oddays > agedays4 then  acctrail_inv_value- acctrail_adj_value else 0 end as Agegrp5

	  from (
      
                select accref_seqno, grp_name, grp_code, cust_name, acctrail_led_code, accref_vouno, acctrail_inv_no, acctrail_inv_date, 
    max(acctrail_inv_value) acctrail_inv_value, max(acctrail_adj_value-adjamt) acctrail_adj_value , max(acctrail_crdays) acctrail_crdays, duedate, oddays, acctrail_amtmode, accref_voudate,sum(adjamt) adjamt
     from (
	     select accref_seqno, grp_name, grp_code, cust_name, acctrail_led_code, accref_vouno, acctrail_inv_no, acctrail_inv_date, 
    max(acctrail_inv_value) acctrail_inv_value, max(acctrail_adj_value) acctrail_adj_value, max(acctrail_crdays) acctrail_crdays, duedate, oddays, acctrail_amtmode, accref_voudate,sum(adjamt) adjamt
     from (
	 select  accref_seqno ,grp_name,grp_code,cust_name,acctrail_led_code,accref_vouno, acctrail_inv_no,  acctrail_inv_date, acctrail_inv_value, acctrail_adj_value, 
	 acctrail_crdays ,  DATE_FORMAT(DATE_ADD(accref_voudate, INTERVAL acctrail_crdays DAY) ,'%d-%m-%Y') as  duedate,
	 DATEDIFF( todate , DATE_ADD(accref_voudate, INTERVAL acctrail_crdays DAY))  as oddays,acctrail_amtmode,accref_voudate, 0 adjamt
	 from acc_ref ref  left join acc_trail trail 
	 on ref.accref_seqno = trail.acctrail_accref_seqno join massal_customer mas 
	  join  acc_group_master grp on mas.cust_acc_group = grp.grp_code
	 on trail.acctrail_led_code = mas.cust_code  and acctrail_inv_value > acctrail_adj_value and cust_acc_group = ledcode  and mas.cust_type != 'G'
	 where accref_comp_code = compcode and accref_voudate <= todate 
     -- and accref_vou_type in ('EXP','PSP','PLW','PPF','PIW','PIC','PSC','PDE','PUR','GJV','BKP','PGS','PFU','DNG','CNG') 

union all
    
     	select  ref_adjseqno accref_seqno , grp.grp_name,grp.grp_code,cust_name,acctrail_led_code, ref_adjvouno ref_adjvouno,
                 acctrail_inv_no,  acctrail_inv_date, acctrail_inv_value, acctrail_adj_value,acctrail_crdays , 
      			   DATE_FORMAT(DATE_ADD(accref_voudate, INTERVAL acctrail_crdays DAY) ,'%d-%m-%Y') as  duedate,
				 DATEDIFF( todate, DATE_ADD(accref_voudate, INTERVAL acctrail_crdays DAY))  as oddays,acctrail_amtmode,
		         accref_voudate,  ref_adjamount  adjamt
				from acc_adjustments ref  left join acc_trail trail 
				 on ref.ref_adjseqno = trail.acctrail_accref_seqno join massal_customer mas 
				 on trail.acctrail_led_code = mas.cust_code   and mas.cust_acc_group = ledcode
				 join acc_group_master grp on mas.cust_acc_group = grp.grp_code  
                join  acc_group_master maingrp on  grp.grp_code = maingrp.grp_code 
			    join acc_ref on accref_seqno = acctrail_accref_seqno and trail.acctrail_led_code = ref_ledcode          
                 where ref_compcode = compcode and -- ref_docdate <= todate and ref_docdate > todate 
                 accref_voudate <= todate and ref_docdate > todate -- and ref_adjvoutype != 'GSI' 
) a1                 
group by accref_seqno, grp_name, grp_code, cust_name, acctrail_led_code, accref_vouno, acctrail_inv_no, acctrail_inv_date, duedate,oddays,acctrail_amtmode, accref_voudate

) a2                 
group by accref_seqno, grp_name, grp_code, cust_name, acctrail_led_code, accref_vouno, acctrail_inv_no, acctrail_inv_date, duedate,oddays,acctrail_amtmode, accref_voudate     
     )a1   order by accref_voudate asc , acctrail_inv_no ; -- order by  grp_name,grp_code,accref_seqno;
 end if;

END ;;
