CREATE DEFINER=`root`@`%` PROCEDURE `accsp_rep_ap_billwisedue_11032025_evening`(compcode int,fromdate date,todate date,ledcode int,repopt varchar(1) )
BEGIN
 if repopt = 'A' then
	 select *,
	case when oddays<= 30 then  acctrail_inv_value- acctrail_adj_value else 0 end as Agegrp1,
	case when oddays > 30 and  oddays<= 60 then  acctrail_inv_value- acctrail_adj_value else 0 end as Agegrp2,
	case when oddays > 60 and  oddays<= 90 then  acctrail_inv_value- acctrail_adj_value else 0 end as Agegrp3,
