	case when oddays > 180 then  acctrail_inv_value- acctrail_adj_value else 0 end as Agegrp5

	  from (
	 select accref_seqno , grp.grp_name,grp.grp_code,cust_name,acctrail_led_code,accref_vouno, acctrail_inv_no,  acctrail_inv_date, acctrail_inv_value, acctrail_adj_value, 
	 acctrail_crdays ,  DATE_FORMAT(DATE_ADD(accref_voudate, INTERVAL acctrail_crdays DAY) ,'%d-%m-%Y') as  duedate,
	 DATEDIFF( todate, DATE_ADD(accref_voudate, INTERVAL acctrail_crdays DAY))  as oddays,acctrail_amtmode,accref_voudate
	 from acc_ref ref  left join acc_trail trail 
