	  join  acc_group_master grp on mas.cust_acc_group = grp.grp_code
	  join  acc_group_master maingrp on  grp.grp_code = maingrp.grp_code  and maingrp.grp_code   in (SELECT grp_code FROM acc_group_master where grp_parent_code = 51)
	 on trail.acctrail_led_code = mas.cust_code  and acctrail_inv_value > acctrail_adj_value and mas.cust_type != 'G'
	 where accref_comp_code = compcode and accref_voudate <= todate   order by  cust_name,accref_voudate
      )a1  ; --     grp.grp_name,grp.grp_code,accref_seqno; 
 elseif repopt = 'P' then
 	 select *,
	case when oddays<= 30 then  acctrail_inv_value- acctrail_adj_value else 0 end as Agegrp1,
