	 on trail.acctrail_led_code = mas.cust_code  and acctrail_inv_value > acctrail_adj_value and cust_acc_group = ledcode  and mas.cust_type != 'G'
	 where accref_comp_code = compcode and accref_voudate <= todate 
     -- and accref_vou_type in ('EXP','PSP','PLW','PPF','PIW','PIC','PSC','PDE','PUR','GJV','BKP','PGS','PFU','DNG','CNG') 
     order by  cust_name,accref_voudate  )a1  ; -- order by  grp_name,grp_code,accref_seqno;
 end if;

