CREATE DEFINER=`root`@`%` PROCEDURE `accsp_rep_ar_billwisedue`(compcode int,fromdate date,todate date,ledcode int,alloutstanding int,grpcode int,dueopt varchar(5))
BEGIN


if dueopt = "PT" then
	if grpcode = 0 then
		 if ledcode  = 0 then
			 if alloutstanding = 1 then
             
select grp_name, cust_name, acctrail_led_code, accref_voudate, acctrail_inv_no, acctrail_inv_date, sum(acctrail_inv_value) acctrail_inv_value, sum(acctrail_adj_value-adjamt) acctrail_adj_value, sum(adjamt) adjamt, acctrail_crdays, acctrail_gracedays, duedate, oddays, acctrail_amtmode, accref_seqno, accref_vouno
from (             
select grp_name, cust_name, acctrail_led_code, accref_voudate, acctrail_inv_no, acctrail_inv_date, max(acctrail_inv_value) acctrail_inv_value, max(acctrail_adj_value) acctrail_adj_value, sum(adjamt) adjamt, acctrail_crdays, acctrail_gracedays, duedate, oddays, acctrail_amtmode, accref_seqno, accref_vouno
from (
				 select grp_name,cust_name,acctrail_led_code, accref_voudate,acctrail_inv_no,  acctrail_inv_date, acctrail_inv_value, acctrail_adj_value, 0 adjamt,
				 acctrail_crdays , acctrail_gracedays , DATE_FORMAT(DATE_ADD(acctrail_inv_date, INTERVAL acctrail_crdays DAY) ,'%d-%m-%Y') as  duedate,
				 DATEDIFF( todate, DATE_ADD(acctrail_inv_date, INTERVAL acctrail_crdays DAY))  as oddays,acctrail_amtmode,accref_seqno,accref_vouno
				 from acc_ref ref  left join acc_trail trail 
				 on ref.accref_seqno = trail.acctrail_accref_seqno join massal_customer mas 
				 on trail.acctrail_led_code = mas.cust_code  and acctrail_inv_value > acctrail_adj_value -- and mas.cust_type = 'C'
				left join acc_group_master grp on mas.cust_acc_group = grp.grp_code
				 where accref_comp_code = compcode and accref_voudate <= todate  
                 
                 union all 
                 
				 select grp_name,cust_name,acctrail_led_code, ref_docdate accref_voudate,acctrail_inv_no,  acctrail_inv_date, acctrail_inv_value, acctrail_adj_value,  ref_adjamount  adjamt, 
				 acctrail_crdays , acctrail_gracedays , DATE_FORMAT(DATE_ADD(acctrail_inv_date, INTERVAL acctrail_crdays DAY) ,'%d-%m-%Y') as  duedate,
				 DATEDIFF( todate, DATE_ADD(acctrail_inv_date, INTERVAL acctrail_crdays DAY))  as oddays,acctrail_amtmode, ref_adjseqno accref_seqno, ref_adjvouno accref_vouno
				 from acc_adjustments ref  left join acc_trail trail 
				 on ref.ref_adjseqno = trail.acctrail_accref_seqno join massal_customer mas 
				 on trail.acctrail_led_code = mas.cust_code  
				left join acc_group_master grp on mas.cust_acc_group = grp.grp_code				 
                 where ref_compcode = compcode and ref_adjvoudate  <= todate  and ref_docdate > todate and ref_adjvoutype = 'GSI' 
) a1 group by
grp_name, cust_name, acctrail_led_code, accref_voudate, acctrail_inv_no, acctrail_inv_date, acctrail_crdays, acctrail_gracedays, duedate, oddays, acctrail_amtmode, accref_seqno, accref_vouno
) aa1 group by
grp_name, cust_name, acctrail_led_code, accref_voudate, acctrail_inv_no, acctrail_inv_date, acctrail_crdays, acctrail_gracedays, duedate, oddays, acctrail_amtmode, accref_seqno, accref_vouno
 order by accref_voudate asc , acctrail_inv_no;  
                 
-- end                  				 
                 
			 else

select grp_name, cust_name, acctrail_led_code, accref_voudate, acctrail_inv_no, acctrail_inv_date, sum(acctrail_inv_value) acctrail_inv_value, sum(acctrail_adj_value-adjamt) acctrail_adj_value, sum(adjamt) adjamt, acctrail_crdays, acctrail_gracedays, duedate, oddays, acctrail_amtmode, accref_seqno, accref_vouno
from (
select grp_name, cust_name, acctrail_led_code, accref_voudate, acctrail_inv_no, acctrail_inv_date, max(acctrail_inv_value) acctrail_inv_value, max(acctrail_adj_value) acctrail_adj_value, sum(adjamt) adjamt, acctrail_crdays, acctrail_gracedays, duedate, oddays, acctrail_amtmode, accref_seqno, accref_vouno
from (
				 select grp_name,cust_name,acctrail_led_code, accref_voudate,acctrail_inv_no,  acctrail_inv_date, acctrail_inv_value, acctrail_adj_value, 0 adjamt,
				 acctrail_crdays , acctrail_gracedays ,  DATE_FORMAT(DATE_ADD(acctrail_inv_date, INTERVAL acctrail_crdays DAY) ,'%d-%m-%Y') as  duedate,
				 DATEDIFF( todate, DATE_ADD(acctrail_inv_date, INTERVAL acctrail_crdays DAY)) as oddays,acctrail_amtmode,accref_seqno,accref_vouno
				 from acc_ref ref  left join acc_trail trail 
