				left join acc_group_master grp on mas.cust_acc_group = grp.grp_code				 
                 where ref_compcode = compcode and ref_adjvoudate  <= todate  and ref_docdate > todate and ref_adjvoutype = 'GSI'                                   

) a1 group by
grp_name, cust_name, acctrail_led_code, accref_voudate, acctrail_inv_no, acctrail_inv_date, acctrail_crdays, acctrail_gracedays, duedate, oddays, acctrail_amtmode, accref_seqno, accref_vouno
) aa1 group by
grp_name, cust_name, acctrail_led_code, accref_voudate, acctrail_inv_no, acctrail_inv_date, acctrail_crdays, acctrail_gracedays, duedate, oddays, acctrail_amtmode, accref_seqno, accref_vouno
 order by accref_voudate asc , acctrail_inv_no;                   
-- end               
             
		 else
         select grp_name, cust_name, acctrail_led_code, accref_voudate, acctrail_inv_no, acctrail_inv_date, sum(acctrail_inv_value) acctrail_inv_value, sum(acctrail_adj_value-adjamt) acctrail_adj_value, sum(adjamt) adjamt, acctrail_crdays, acctrail_gracedays, duedate, oddays, acctrail_amtmode, accref_seqno, accref_vouno
from (
  select grp_name, cust_name, acctrail_led_code, accref_voudate, acctrail_inv_no, acctrail_inv_date, max(acctrail_inv_value) acctrail_inv_value, max(acctrail_adj_value) acctrail_adj_value, sum(adjamt) adjamt, acctrail_crdays, acctrail_gracedays, duedate, oddays, acctrail_amtmode, accref_seqno, accref_vouno
from (                
			 select grp_name,cust_name,acctrail_led_code, accref_voudate,acctrail_inv_no,  acctrail_inv_date, acctrail_inv_value, acctrail_adj_value, 0 adjamt,
