		 if alloutstanding = 1 then
			 select grp_name,cust_name,acctrail_led_code, accref_voudate,acctrail_inv_no,  acctrail_inv_date, acctrail_inv_value, acctrail_adj_value, 
			 acctrail_crdays , acctrail_gracedays ,  DATE_FORMAT(DATE_ADD(acctrail_inv_date, INTERVAL acctrail_crdays DAY) ,'%d-%m-%Y') as  duedate,
			 DATEDIFF( todate, DATE_ADD(acctrail_inv_date, INTERVAL acctrail_crdays DAY))  as oddays,acctrail_amtmode,accref_seqno,accref_vouno
			 from acc_ref ref  left join acc_trail trail 
			 on ref.accref_seqno = trail.acctrail_accref_seqno join massal_customer mas 
			 on trail.acctrail_led_code = mas.cust_code  and acctrail_inv_value > acctrail_adj_value  and mas.cust_type = 'C'
			left join acc_group_master grp on mas.cust_acc_group = grp.grp_code  
			 where accref_comp_code = compcode and accref_voudate <= todate and mas.cust_acc_group = grpcode  order by accref_voudate,acctrail_inv_date; 
		 else
			 select grp_name,cust_name,acctrail_led_code, accref_voudate,acctrail_inv_no,  acctrail_inv_date, acctrail_inv_value, acctrail_adj_value, 
			 acctrail_crdays , acctrail_gracedays ,  DATE_FORMAT(DATE_ADD(acctrail_inv_date, INTERVAL acctrail_crdays DAY) ,'%d-%m-%Y') as  duedate,
			 DATEDIFF( todate, DATE_ADD(acctrail_inv_date, INTERVAL acctrail_crdays DAY))  as oddays,acctrail_amtmode,accref_seqno,accref_vouno
			 from acc_ref ref  left join acc_trail trail 
			 on ref.accref_seqno = trail.acctrail_accref_seqno join massal_customer mas 
			 on trail.acctrail_led_code = mas.cust_code  and acctrail_inv_value > acctrail_adj_value  and mas.cust_type = 'C'
			 left join acc_group_master grp on mas.cust_acc_group = grp.grp_code  
			 where accref_comp_code = compcode and accref_voudate <= todate -- and acctrail_amtmode = 'D'
			 -- and (accref_vou_type = 'GSI' or left(accref_vou_type,2) = 'DN'  or left(accref_payref_no,2) = 'DB')  
			 and  DATEDIFF( todate, DATE_ADD(acctrail_inv_date, INTERVAL acctrail_crdays DAY)) +2  > 0 and mas.cust_acc_group = grpcode    order by accref_voudate,acctrail_inv_date;
		 end if;
	else
		 if alloutstanding = 1 then
			 select grp_name,cust_name,acctrail_led_code, accref_voudate,acctrail_inv_no,  acctrail_inv_date, acctrail_inv_value, acctrail_adj_value, 
