				 left join acc_group_master grp on mas.cust_acc_group = grp.grp_code
				 where accref_comp_code = compcode and accref_voudate <= todate and acctrail_amtmode = 'D' and  DATEDIFF( todate, DATE_ADD(acctrail_inv_date, INTERVAL acctrail_crdays + acctrail_gracedays  DAY)) +2  > 0
				 -- and (accref_vou_type = 'GSI' or left(accref_vou_type,2) = 'DN'  or left(accref_payref_no,2) = 'DB')  
				 order by accref_voudate,acctrail_inv_date;
