				 where accref_comp_code = compcode and accref_voudate <=  todate   order by accref_voudate,acctrail_inv_date; 
			 else
					 select grp_name,cust_name,acctrail_led_code, accref_voudate,acctrail_inv_no,  acctrail_inv_date, acctrail_inv_value, acctrail_adj_value, 
					 acctrail_crdays , acctrail_gracedays ,  DATE_FORMAT(DATE_ADD(acctrail_inv_date, INTERVAL acctrail_crdays + acctrail_gracedays  DAY) ,'%d-%m-%Y') as  duedate,
					 DATEDIFF( todate, DATE_ADD(acctrail_inv_date, INTERVAL acctrail_crdays + acctrail_gracedays  DAY))   as oddays,acctrail_amtmode,accref_seqno,accref_vouno
					 from acc_ref ref  left join acc_trail trail 
