CREATE DEFINER=`root`@`%` PROCEDURE `accsp_rep_ar_billwisedueSMS`(compcode int,fromdate date,todate date,ledcode int)
BEGIN
            select grp_name,cust_name as led_name,acctrail_led_code, acctrail_inv_no,  acctrail_inv_date, acctrail_inv_value, acctrail_adj_value, 
			 acctrail_crdays ,  DATE_FORMAT(DATE_ADD(acctrail_inv_date, INTERVAL acctrail_crdays DAY) ,'%d-%m-%Y') as  duedate,
			 DATEDIFF( todate, DATE_ADD(acctrail_inv_date, INTERVAL acctrail_crdays DAY))  as oddays,acctrail_amtmode,accref_seqno,accref_vouno,cust_email
			 from acc_ref ref  left join acc_trail trail 
			 on ref.accref_seqno = trail.acctrail_accref_seqno join massal_customer mas 
			 on trail.acctrail_led_code = mas.cust_code  and acctrail_inv_value > acctrail_adj_value and acctrail_led_code = ledcode  and mas.cust_type = 'C'
             left join acc_group_master grp on mas.cust_acc_group = grp.grp_code   
 		     where accref_comp_code = compcode and accref_voudate <= todate and acctrail_amtmode = 'D'
             -- and (accref_vou_type = 'GSI' or left(accref_vou_type,2) = 'DN' or left(accref_payref_no,2) = 'DB' ) 
            and  DATEDIFF( todate, DATE_ADD(acctrail_inv_date, INTERVAL acctrail_crdays DAY))   > 0 order by accref_seqno;
            
/*
			 select grp_name,cust_name as led_name,acctrail_led_code, acctrail_inv_no,  acctrail_inv_date, acctrail_inv_value, acctrail_adj_value, 
			 acctrail_crdays ,  DATE_FORMAT(DATE_ADD(acctrail_inv_date, INTERVAL acctrail_crdays DAY) ,'%d-%m-%Y') as  duedate,
			 DATEDIFF( todate, DATE_ADD(acctrail_inv_date, INTERVAL acctrail_crdays DAY))  as oddays,acctrail_amtmode,accref_seqno,accref_vouno,cust_email
			 from acc_ref ref  left join acc_trail trail 
			 on ref.accref_seqno = trail.acctrail_accref_seqno join acc_ledger_master mas 
			 on trail.acctrail_led_code = mas.led_code  and acctrail_inv_value > acctrail_adj_value and acctrail_led_code = ledcode  and mas.led_type = 'C'
             left join acc_group_master grp on mas.acc_group_master = grp.grp_code   
 		     where accref_comp_code = compcode and accref_voudate <=  todate and acctrail_amtmode = 'D'
             -- and (accref_vou_type = 'GSI' or left(accref_vou_type,2) = 'DN' or left(accref_payref_no,2) = 'DB' ) 
            and  DATEDIFF( todate, DATE_ADD(acctrail_inv_date, INTERVAL acctrail_crdays DAY))   > 0 order by accref_seqno;
            */
END ;;
