CREATE DEFINER=`root`@`%` PROCEDURE `accsp_rep_ar_billwise_overdue`(compcode int,fromdate date,todate date,ledcode int)
BEGIN

		 select led_name,acctrail_led_code, acctrail_inv_no,  acctrail_inv_date, acctrail_inv_value, acctrail_adj_value, 
		 acctrail_crdays ,  DATE_FORMAT(DATE_ADD(acctrail_inv_date, INTERVAL acctrail_crdays DAY) ,'%d-%m-%Y') as  duedate,
		 DATEDIFF( todate, DATE_ADD(acctrail_inv_date, INTERVAL acctrail_crdays DAY))  as oddays,acctrail_amtmode,accref_seqno,accref_vouno
		 from acc_ref ref  left join acc_trail trail 
		 on ref.accref_seqno = trail.acctrail_accref_seqno join acc_ledger_master mas 
		 on trail.acctrail_led_code = mas.led_code  and acctrail_inv_value > acctrail_adj_value  and mas.led_type = 'C'
		 where accref_comp_code = compcode and accref_voudate between fromdate and todate and accref_vou_type = 'GSI'  order by accref_seqno;

END ;;
