CREATE DEFINER=`root`@`%` PROCEDURE `accsp_rep_ar_collection`(compcode int,fromdate date,todate date)
BEGIN
select a1.* ,a3.repr_code,a3.repr_name  from (
select led_name,acctrail_led_code,accref_vouno,accref_voudate,acctran_cramt, refpartyinvno,refpartyinvdate,refamount
 from acc_ref ref left join acc_tran trn
 on ref.accref_seqno = trn.acctran_accref_seqno
 left join acc_recpay_ref adj 
 on ref.accref_seqno = adj.refbankseqno
 left join acc_trail trail 
 on adj.refinvseqno = trail.acctrail_accref_seqno
 join acc_ledger_master mas
 on trn.acctran_led_code = mas.led_code and led_type = 'C' and acctran_cramt > 0 
 where accref_comp_code = compcode  and accref_voudate between fromdate and todate and accref_vou_type in ('BKR','CIR')  
 ) a1 , massal_customer  a2 , massal_repr a3  where acctrail_led_code = cust_led_code and cust_repr  = repr_code;
END ;;
