CREATE DEFINER=`root`@`%` PROCEDURE `accsp_rep_ar_paymentpeformance`(
compcode int,fromdate date,todate date,ledcode int)
BEGIN
select * from 
(select accref_seqno,accref_vouno,accref_voudate,accref_paymode, accref_payref_no , accref_payref_date ,acctran_totamt,
 ref_invno refpartyinvno,ref_invdate refpartyinvdate, ref_adjvouno refpurchaseno, ref_adjamount refamount,acctrail_crdays+acctrail_gracedays acctrail_crdays,acctrail_inv_value,cust_code,cust_name,
 DATEDIFF( accref_voudate, ref_invdate) as noofdays , DATEDIFF( accref_voudate, ref_invdate)-(acctrail_crdays+acctrail_gracedays) as daysfromduedate
 from acc_ref ref left join acc_tran trn
 on ref.accref_seqno = trn.acctran_accref_seqno
 left join acc_adjustments adj 
 on ref.accref_seqno = adj.ref_docseqno
 left join acc_trail trail 
 on adj.ref_adjseqno = trail.acctrail_accref_seqno 
 join massal_customer mas
 on trn.acctran_led_code = mas.cust_code and cust_type = 'C' and acctran_cramt > 0 and trn.acctran_led_code = ledcode
 where accref_comp_code = compcode and accref_voudate between fromdate and todate and accref_vou_type in ('BKR')  and acctrail_inv_value = acctrail_adj_value order by refpartyinvdate desc)a1; 
END ;;
DELIMITER ;
