CREATE DEFINER=`root`@`%` PROCEDURE `accsp_rep_cash_vouprint`(compcode int,fincode int,seqno int)
BEGIN
select * from (
select a1.* ,a2.cashbankname from (
select * from acc_ref ref 
 left join acc_tran trn on ref.accref_seqno = trn.acctran_accref_seqno 
 left join acc_trail trail on ref.accref_seqno = trail.acctrail_accref_seqno  and trn.acctran_led_code = trail.acctrail_led_code
 join massal_customer mas
 on trn.acctran_led_code = mas.cust_code
    left join acc_adjustments adj  on ref.accref_seqno = adj.ref_docseqno and acctran_led_code = ref_ledcode
    where accref_comp_code = compcode  and accref_finid =  fincode and  accref_seqno  = seqno 
 and
   acctran_serialno <> 
 (select  max(acctran_serialno) from acc_ref ref   join acc_tran trn on ref.accref_seqno = trn.acctran_accref_seqno  and accref_comp_code = compcode  and accref_finid =  fincode  and accref_seqno = seqno)
 ) a1 left join 
 (select  accref_seqno, cust_name cashbankname from acc_ref ref 
 left join acc_tran trn on ref.accref_seqno = trn.acctran_accref_seqno
  join massal_customer mas
 on trn.acctran_led_code = mas.cust_code 
 where accref_comp_code = compcode  and accref_finid =  fincode and  accref_seqno  = seqno
 and
   acctran_serialno = 
 (select  max(acctran_serialno) from acc_ref ref   join acc_tran trn on ref.accref_seqno = trn.acctran_accref_seqno 
 and accref_comp_code = compcode and accref_finid =  fincode  and accref_seqno = seqno) ) a2 on a1.accref_seqno = a2.accref_seqno
 )c1
   join 
 ( select * from acc_voucher_logs ,userMaster where accvou_userid = usr_code and  accvou_seqno= seqno and accvou_slno in 
 ( select max(accvou_slno)  from acc_voucher_logs where accvou_seqno= seqno )) d1 on d1.accvou_seqno = c1.accref_seqno ;  
 
   
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
