DELIMITER ;;
CREATE DEFINER=`root`@`%` PROCEDURE `accsp_rep_cash_vouprint29052024`(compcode int,fincode int,vouno varchar(15))
BEGIN

select * from (
select * from acc_ref ref 
 left join acc_tran trn on ref.accref_seqno = trn.acctran_accref_seqno 
 left join acc_trail trail on ref.accref_seqno = trail.acctrail_accref_seqno  and trn.acctran_led_code = trail.acctrail_led_code
 join massal_customer mas
 on trn.acctran_led_code = mas.cust_code
    left join acc_adjustments adj  on ref.accref_seqno = adj.ref_docseqno
   left join acc_voucher_logs vlog on  ref.accref_seqno = vlog.accvou_seqno
   left join userMaster usr on vlog.accvou_userid = usr.usr_code 
 where accref_comp_code = compcode  and accref_finid =  fincode and  accref_vouno  = vouno
 and
   acctran_serialno <> 
 (select  max(acctran_serialno) from acc_ref ref   join acc_tran trn on ref.accref_seqno = trn.acctran_accref_seqno  and accref_comp_code = compcode  and accref_finid =  fincode  and accref_vouno = vouno)
 ) a1 left join 
 (select  accref_seqno, cust_name cashbankname from acc_ref ref 
 left join acc_tran trn on ref.accref_seqno = trn.acctran_accref_seqno
  join massal_customer mas
 on trn.acctran_led_code = mas.cust_code 
 where accref_comp_code = compcode  and accref_finid =  fincode and  accref_vouno  = vouno
 and
   acctran_serialno = 
 (select  max(acctran_serialno) from acc_ref ref   join acc_tran trn on ref.accref_seqno = trn.acctran_accref_seqno 
 and accref_comp_code = compcode and accref_finid =  fincode  and accref_vouno = vouno) ) a2 on a1.accref_seqno = a2.accref_seqno
 ; 
END ;;
DELIMITER ;
