CREATE DEFINER=`root`@`%` PROCEDURE `accsp_rep_cndn_vouprint`(compcode int,fincode int,vouno varchar(12))
BEGIN
select * from 
(select * from acc_ref ref 
 left join  acc_tran trn on ref.accref_seqno = trn.acctran_accref_seqno
 left join acc_trail trail on ref.accref_seqno = trail.acctrail_accref_seqno
 join acc_ledger_master mas
 on trn.acctran_led_code = mas.led_code  and  trn.acctran_cramt  > 0
  left join acc_recpay_ref adj  on ref.accref_seqno = adj.refbankseqno
  left join acc_voucher_logs vlog on  ref.accref_seqno = vlog.accvou_seqno
  left join userMaster usr on vlog.accvou_userid = usr_code 
 where accref_comp_code = compcode and accref_finid =  fincode and  accref_vouno = vouno
 ) a1  left join  
 (
 select accref_comp_code rcompcode ,accref_finid rfincode,accref_vouno rvoucherno ,led_name ledgername,  acctran_dbamt dbamt from acc_ref ref 
 left join  acc_tran trn on ref.accref_seqno = trn.acctran_accref_seqno
 left join acc_trail trail on ref.accref_seqno = trail.acctrail_accref_seqno
 join acc_ledger_master mas
 on trn.acctran_led_code = mas.led_code  and  trn.acctran_dbamt  > 0
  left join acc_recpay_ref adj  on ref.accref_seqno = adj.refbankseqno
  left join acc_voucher_logs vlog on  ref.accref_seqno = vlog.accvou_seqno
  left join userMaster usr on vlog.accvou_userid = usr_code 
 where accref_comp_code = compcode  and accref_finid =  fincode and  accref_vouno = vouno) b1
 on accref_comp_code = rcompcode and  accref_finid = rfincode and  accref_vouno  = rvoucherno;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
