DELIMITER ;;
CREATE DEFINER=`root`@`%` PROCEDURE `accsp_rep_crdit_note_vouprint`(compcode int,fincode int,vouno varchar(15))
BEGIN
select * from (
select h.*,t.* ,c.* ,dbcrledger.cust_code debit_credit_ledcode,  dbcrledger.cust_name debit_credit_ledname
,igstledger.cust_code igst_ledcode,  igstledger.cust_name igst_ledname
,cgstledger.cust_code cgst_ledcode,  cgstledger.cust_name cgst_ledname
,sgstledger.cust_code sgst_ledcode,  sgstledger.cust_name sgst_ledname,
tcsledger.cust_name tcs_ledname,othledger.cust_name other_ledname,usr.*,ref.*,ms.*
from acc_dbcrnote_header h  join 
(

select dbcrt_seqno,  GROUP_CONCAT(dbcrt_inv_no SEPARATOR ', ')  inv_no , 
dbcrt_igstledcode,dbcrt_cgstledcode,dbcrt_sgstledcode ,dbcrt_otherledcode, sum(dbcrt_grossvalue)  dbcrt_grossvalue,
dbcrt_tcsledcode,
sum(dbcrt_value)  dbcrt_value,
sum(dbcrt_taxable)  dbcrt_taxable,
sum(dbcrt_igstvalue)  dbcrt_igstvalue,
sum(dbcrt_cgstvalue)  dbcrt_cgstvalue,
sum(dbcrt_sgstvalue)  dbcrt_sgstvalue,
sum(dbcrt_otheramt)  dbcrt_otheramt,
max(dbcrt_igstper)  dbcrt_igstper,
max(dbcrt_cgstper)  dbcrt_cgstper,
max(dbcrt_sgstper)  dbcrt_sgstper,
sum(dbcrt_tcsvalue)  dbcrt_tcsvalue,
max(dbcrt_rounding)  dbcrt_rounding

from acc_dbcrnote_trailer , acc_dbcrnote_header where  dbcr_seqno = dbcrt_seqno and dbcr_comp_code = compcode and dbcr_finid = fincode and dbcr_vouno = vouno group by  dbcrt_seqno,dbcrt_inv_no,dbcrt_igstledcode,dbcrt_cgstledcode,dbcrt_sgstledcode,dbcrt_otherledcode
 )t 
 on dbcr_seqno = dbcrt_seqno and dbcr_comp_code = compcode and dbcr_finid = fincode and dbcr_vouno = vouno
join massal_customer c on  dbcr_partycode = c.cust_code
join massal_customer dbcrledger  on   dbcrledger.cust_code = h.dbcr_ledcode
join massal_customer igstledger  on   igstledger.cust_code = t.dbcrt_igstledcode
join massal_customer cgstledger  on   cgstledger.cust_code = t.dbcrt_cgstledcode
join massal_customer sgstledger  on   sgstledger.cust_code = t.dbcrt_sgstledcode 
join massal_customer tcsledger   on   tcsledger.cust_code = t.dbcrt_tcsledcode 
join massal_customer othledger   on   othledger.cust_code = t.dbcrt_otherledcode 
left join userMaster usr on h.dbcr_userid = usr.usr_code
left join acc_ref ref on ref.accref_seqno = h.dbcr_accseqno
join mas_state ms where  ms.state_code = c.cust_state ) a1; 

END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
