CREATE DEFINER=`root`@`%` PROCEDURE `accsp_rep_DebitNote_vouprint`(compcode int,fincode int,seqno int)
BEGIN
select * from (
 select * , cust_name ledgername from (
select * from acc_ref ref 
 left join acc_tran trn on ref.accref_seqno = trn.acctran_accref_seqno 
 join massal_customer mas on trn.acctran_led_code = mas.cust_code 
 join mas_state state on state_code = cust_state
 where accref_comp_code = compcode  and accref_finid =  fincode and  accref_seqno  = seqno
 ) a1
 left join 
 ( select * from acc_voucher_logs ,userMaster where accvou_userid = usr_code and  accvou_seqno= seqno and accvou_slno in 
 ( select max(accvou_slno)  from acc_voucher_logs where accvou_seqno= seqno )) d1 on d1.accvou_seqno = a1.accref_seqno   
)aa1; 
END ;;
