CREATE DEFINER=`root`@`%` PROCEDURE `accsp_rep_group_payment_allparties`(compcode int,fromdate date,todate date)
BEGIN
select  grp_name,cust_acc_group,cust_code,cust_name,sum(acctran_dbamt) as paidamt  from acc_ref ref left join acc_tran trn
 on ref.accref_seqno = trn.acctran_accref_seqno
 join massal_customer mas
 on trn.acctran_led_code = mas.cust_code and  acctran_dbamt > 0 
 join acc_group_master grp
 on mas.cust_acc_group = grp.grp_code and grp.grp_parent_code = 51
 where accref_comp_code = compcode and accref_voudate between  fromdate and todate and accref_vou_type in ('BKP','CHP')  
 group by grp_name,cust_acc_group,cust_code,cust_name order by grp_name , cust_name;
END ;;
DELIMITER ;
