CREATE DEFINER=`root`@`%` PROCEDURE `accsp_rep_jv_vouprint`(compcode int,fincode int,vouno varchar(12))
BEGIN
/*
select * from
(
select * from acc_ref ref 
 left join acc_tran trn on ref.accref_seqno = trn.acctran_accref_seqno
 join massal_customer mas
 on trn.acctran_led_code = mas.cust_code  -- and acctrail_serialno =1
   where accref_comp_code = compcode  and accref_finid =  fincode and accref_vouno  = vouno
  ) a1 left join  acc_voucher_logs b1 on a1.accref_seqno = accvou_seqno and accvou_slno = 1
  left join userMaster usr on b1.accvou_userid = usr.usr_code
  left join acc_adjustments adj on a1.accref_seqno = adj.ref_docseqno and  a1.acctran_led_code = adj.ref_ledcode ;  
  */
  
  select * from
(
select * from acc_ref ref 
 left join acc_tran trn on ref.accref_seqno = trn.acctran_accref_seqno
 join massal_customer mas
 on trn.acctran_led_code = mas.cust_code  -- and acctrail_serialno =1
   where accref_comp_code = compcode  and accref_finid =  fincode and accref_vouno  =  vouno and acctran_cramt > 0
  ) a1 left join  acc_voucher_logs b1 on a1.accref_seqno = accvou_seqno and accvou_slno = 1
  left join userMaster usr on b1.accvou_userid = usr.usr_code
  left join acc_adjustments adj on a1.accref_seqno = adj.ref_docseqno and  a1.acctran_led_code = adj.ref_ledcode and ref_adjvoutype = 'GSI'   
  
  union all

select * from
(
select * from acc_ref ref 
 left join acc_tran trn on ref.accref_seqno = trn.acctran_accref_seqno
 join massal_customer mas
 on trn.acctran_led_code = mas.cust_code  -- and acctrail_serialno =1
   where accref_comp_code = compcode and accref_finid =  fincode and accref_vouno  = vouno and acctran_dbamt > 0
  ) a1 left join  acc_voucher_logs b1 on a1.accref_seqno = accvou_seqno and accvou_slno = 1
  left join userMaster usr on b1.accvou_userid = usr.usr_code
  left join acc_adjustments adj on a1.accref_seqno = adj.ref_docseqno and  a1.acctran_led_code = adj.ref_ledcode and ref_adjvoutype <> 'GSI' ;  
    
  
  
END ;;
DELIMITER ;
