CREATE DEFINER=`root`@`%` PROCEDURE `accsp_rep_Party_Bills_collections`(compcode int,fromdate date,todate date,ledcode int)
BEGIN
select * from (
 select cust_name,acctrail_led_code,accref_vouno,accref_voudate,acctran_cramt, ref_invno refpartyinvno,ref_invdate refpartyinvdate, ref_adjamount refamount
 from acc_ref ref left join acc_tran trn
 on ref.accref_seqno = trn.acctran_accref_seqno
 left join acc_adjustments adj 
 on ref.accref_seqno = adj.ref_docseqno
 left join acc_trail trail 
 on adj.ref_invno = trail.acctrail_accref_seqno
 join massal_customer mas
 on trn.acctran_led_code = mas.cust_code and cust_type = 'C' and acctran_cramt > 0  and trn.acctran_led_code = ledcode 
 where accref_comp_code = compcode  and accref_voudate between fromdate and todate and accref_vou_type in ('BKR','CIR','BRK') ) a1
 ;
   END ;;
DELIMITER ;
