CREATE DEFINER=`root`@`%` PROCEDURE `accsp_rep_party_datewise_payments`(compcode int,fromdate date,todate date,ledcode int)
BEGIN
 select  accref_seqno,cust_name,acctran_led_code,accref_vouno,accref_voudate,acctran_dbamt, ref_invno,ref_invdate,ref_adjamount
 from acc_ref ref left join acc_tran trn
 on ref.accref_seqno = trn.acctran_accref_seqno
 left join acc_adjustments adj 
 on ref.accref_seqno = adj.ref_docseqno
 left join acc_trail trail 
 on adj.ref_docseqno = trail.acctrail_accref_seqno
 join massal_customer mas
 on trn.acctran_led_code = mas.cust_code and acctran_dbamt > 0  and trn.acctran_led_code = ledcode 
 where accref_comp_code = compcode  and accref_voudate between fromdate and todate and accref_vou_type in ('BKP','CHP') order by accref_voudate;
 
/*
select cust_name,acctran_led_code,accref_vouno,accref_voudate,acctran_dbamt, refpartyinvno,refpartyinvdate,refamount
 from acc_ref ref left join acc_tran trn
 on ref.accref_seqno = trn.acctran_accref_seqno
 left join acc_recpay_ref adj 
 on ref.accref_seqno = adj.ref_docseqno
 left join acc_trail trail 
 on adj.refinvseqno = trail.acctrail_accref_seqno
 join massal_customer mas
 on trn.acctran_led_code = mas.cust_code and acctran_dbamt > 0  and trn.acctran_led_code = ledcode 
 where accref_comp_code = compcode  and accref_voudate between fromdate and todate and accref_vou_type in ('BKP','CHP') order by accref_voudate;
 */
   END ;;
