/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`%` PROCEDURE `accsp_rep_payable_billwisedue`(compcode int,fromdate date,todate date,ledcode int)
BEGIN
 select led_name,acctrail_led_code,accref_vouno, acctrail_inv_no,  acctrail_inv_date, acctrail_inv_value, acctrail_adj_value, 
 acctrail_crdays ,  DATE_FORMAT(DATE_ADD(acctrail_inv_date, INTERVAL acctrail_crdays DAY) ,'%d-%m-%Y') as  duedate,
 DATEDIFF( curdate(), DATE_ADD(acctrail_inv_date, INTERVAL acctrail_crdays DAY))  as oddays
 from acc_ref ref  left join acc_trail trail 
 on ref.accref_seqno = trail.acctrail_accref_seqno join acc_ledger_master mas
 on  mas.led_type = 'S' and trail.acctrail_led_code = mas.led_code  and acctrail_inv_value > acctrail_adj_value and acctrail_led_code = ledcode 
 where accref_comp_code = compcode and accref_voudate between fromdate and todate  order by accref_seqno; 
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
