/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`%` PROCEDURE `accsp_rep_profitandloss`(finid int,
compcode int,
fromdate date,
todate date)
BEGIN

select 

acctran_led_code,led_name,curbal_obdbamt,curbal_obcramt,debit,
credit,closing,
 maingrp, subgrp, subgrp2,
grp0,grp1, grp2, grp3,grp4,
cust_type,grp_type, grp_pl_type  

from

 (
select 

acctran_led_code,cust_name led_name,sum(Obdebit) as curbal_obdbamt,sum(Obcredit) as curbal_obcramt,sum(debit) as debit,

sum(credit) as credit,sum(Obdebit)-sum(Obcredit)+sum(debit)-sum(credit) as closing,
 maingrp, subgrp, subgrp2
-- grpcode as grp
-- fn_GetParentgroup(grpcode,compcode,0,'C') as grp
 ,fn_GetParentgroup(grpcode,1,0,'N') as grp0

, fn_GetParentgroup(grpcode,1,1,'N') as grp1

, fn_GetParentgroup(grpcode,1,2,'N') as grp2,fn_GetParentgroup(grpcode,1,3,'N') as grp3,

 fn_GetParentgroup(grpcode,1,4,'N') as grp4,
cust_type,grp_type, grp_pl_type  

from

 (

 select  cust_name,cust_acc_group as grpcode,curbal_comp_code as accref_comp_code,curbal_finid as accref_finid,

curbal_led_code as acctran_led_code,curbal_obdbamt as Obdebit, curbal_obcramt as Obcredit,

0 as debit,0 as credit ,cust_type, d.grp_code as maingrp,  c.grp_code as subgrp ,  b.grp_code as subgrp2 ,d.grp_type, d.grp_pl_type  

from acc_current_balance cb ,massal_customer a ,acc_group_master  b  ,acc_group_master  c ,acc_group_master  d where 
 a.cust_acc_group = b.grp_code 
and b.grp_parent_code = c.grp_code 
and c.grp_parent_code = d.grp_code 
and curbal_finid= finid and (curbal_obdbamt+curbal_obcramt)>0 and curbal_led_code = cust_code
and curbal_comp_code = compcode   and d.grp_type = 'P'

union all 

 select cust_name,cust_acc_group as grpcode,accref_comp_code,accref_finid,acctran_led_code,
0 as Obdebit, 0 as Obcredit,
acctran_dbamt as debit,acctran_cramt as credit ,cust_type, d.grp_code as maingrp,  c.grp_code as subgrp,  b.grp_code as subgrp2,d.grp_type, d.grp_pl_type  
from acc_ref ar ,acc_tran at ,massal_customer a 
,acc_group_master  b  ,acc_group_master  c ,acc_group_master  d  where 
a.cust_acc_group = b.grp_code 
and b.grp_parent_code = c.grp_code 
and c.grp_parent_code = d.grp_code 
and accref_comp_code =  compcode and accref_seqno = acctran_accref_seqno and
accref_finid=  finid  and
accref_voudate > '2022-08-31'  and
accref_voudate>= fromdate  and accref_voudate<= todate and 
acctran_led_code = cust_code and d.grp_type = 'P'
) tt

group by cust_name,acctran_led_code ,cust_type , maingrp, subgrp, subgrp2 , grp0, grp1, grp2, grp3, grp4,grp_type, grp_pl_type

having sum(Obdebit)-sum(Obcredit)+sum(debit)-sum(credit)<>0

order by maingrp, subgrp, subgrp2,cust_name,grp_type, grp_pl_type
)a1
;  
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
