CREATE DEFINER=`root`@`%` PROCEDURE `accsp_rep_Rep_Datewise_collections`(compcode int,fromdate date,todate date,repcode int)
BEGIN

select  cust_name,cust_code,accref_vouno,accref_voudate,sum(acctran_cramt) collamt from (
select * from acc_ref ref left join acc_tran trn
 on ref.accref_seqno = trn.acctran_accref_seqno
 join massal_customer  mas
 on trn.acctran_led_code = mas.cust_code and cust_type = 'C' and acctran_cramt > 0 
 join massal_repr on  cust_repr  = repr_code 
 where accref_comp_code = compcode and  cust_repr  = repcode and accref_voudate between  fromdate and todate and accref_vou_type in ('BKR','CHR')  
 ) a1 
group by  cust_name,cust_code,accref_vouno,accref_voudate  order by accref_voudate,accref_vouno;
 
