/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`%` PROCEDURE `accsp_rep_vouprint`(compcode int,fincode int,vouno varchar(12))
BEGIN
select * from
(select * from acc_ref ref 
 left join acc_tran trn on ref.accref_seqno = trn.acctran_accref_seqno
 left join acc_trail trail on ref.accref_seqno = trail.acctrail_accref_seqno and trn.acctran_led_code = trail.acctrail_led_code 
 join acc_ledger_master mas
 on trn.acctran_led_code = mas.led_code 
  left join acc_recpay_ref adj  on ref.accref_seqno = adj.refbankseqno
  -- left join acc_voucher_logs vlog on  ref.accref_seqno = vlog.accvou_seqno
  -- left join userMaster usr on vlog.accvou_userid = usr.usr_code 
  where accref_comp_code = compcode  and accref_finid =  fincode and accref_vouno  = vouno 
  ) a1 left join  acc_voucher_logs b1 on a1.accref_seqno = accvou_seqno and accvou_slno = 1
  left join userMaster usr on b1.accvou_userid = usr.usr_code;
  
/*
select * from acc_ref ref 
 left join acc_tran trn on ref.accref_seqno = trn.acctran_accref_seqno
 left join acc_trail trail on ref.accref_seqno = trail.acctrail_accref_seqno and trn.acctran_led_code = trail.acctrail_led_code 
 join acc_ledger_master mas
 on trn.acctran_led_code = mas.led_code 
  left join acc_recpay_ref adj  on ref.accref_seqno = adj.refbankseqno
  -- left join acc_voucher_logs vlog on  ref.accref_seqno = vlog.accvou_seqno
  -- left join userMaster usr on vlog.accvou_userid = usr.usr_code 
  where accref_comp_code = compcode  and accref_finid =  fincode  and accref_vouno  = vouno;  
  */
END ;;
DELIMITER ;
