CREATE DEFINER=`root`@`%` PROCEDURE `accsp_trial_balance_json`(
finid int,
compcode int,
fromdate date,
todate date
)
BEGIN
SET SESSION group_concat_max_len = 18446744073709551615;

   select concat('[',GROUP_CONCAT(ledger6),']') tbjson from (
   select 
   '1' as grptype,   concat( '{ "ledgername":"',maingroupname,'","DebitAmount":"',tdebit,'",','"CreditAmount":"',tcredit,'",',ledger5,'}' ) ledger6  from 
   (
   select maingroupname,sum(debit) totaldebit,sum(credit) totalcredit,case when sum(debit) > sum(credit) then sum(debit) - sum(credit) else 0 end  tdebit,case when sum(credit)  > sum(debit)  then sum(credit) - sum(debit) else 0 end  tcredit ,  concat('"children":[',GROUP_CONCAT(ledger4),']') ledger5  from 
 (

      select maingroupname,sum(l1debit) debit,sum(l1credit) credit, CONCAT( '{ "ledgername":"',subgroupname,'","DebitAmount":"',l1debit,'",','"CreditAmount":"',l1credit,'",',ledger3,'}') ledger4 from 
(
     select maingroupname,sum(l2debit) l1totdebit,sum(l2credit) l1totcredit,
     case when sum(l2debit) > sum(l2credit) then sum(l2debit) - sum(l2credit) else 0 end  l1debit,case when sum(l2credit)  > sum(l2debit)  then sum(l2credit) - sum(l2debit) else 0 end  l1credit, 
     subgroupname, concat('"children":[',GROUP_CONCAT(ledger2),']') ledger3 from 
--   select maingroupname,sum(l2debit) l1debit,sum(l2credit) l1credit, subgroupname, concat('"children":[',GROUP_CONCAT(ledger2),']') ledger3 from 
  (
 -- select maingroupname,subgroupname ,sum(l3debit) l2debit,sum(l3credit) l2credit,  concat( '"children":[{ "ledgername":"',GROUP_CONCAT(subgrouplevel3),'", ','"DebitAmount":"',l3debit,'",','"CreditAmount":"',l3credit,'",',ledger,"}]") ledger2 from 
 select maingroupname,subgroupname ,sum(l3debit) l2debit,sum(l3credit) l2credit,  concat( '{ "ledgername":"',GROUP_CONCAT(subgrouplevel3),'", ','"DebitAmount":"',l3debit,'",','"CreditAmount":"',l3credit,'",',ledger,"}") ledger2 from 
 (
  select  maingroupname,subgroupname,subgrouplevel3,sum(debit) l3totdebit,sum(credit) l3totcredit, 
  case when sum(debit) > sum(credit) then sum(debit) - sum(credit) else 0 end  l3debit,
  case when sum(credit)  > sum(debit)  then sum(credit) - sum(debit) else 0 end  l3credit, 
  concat( '"children":[',GROUP_CONCAT(led),"]") ledger
  from (

select  
maingrp, maingroupname,subgrp, subgroupname,subgrp2,subgrouplevel3, debit, credit , '1' as ledgrp, concat('{"ledgername":"','      ',led_name,'",','"DebitAmount":"',debit,'",','"CreditAmount":"',credit,'","leaf":"true"}') led

 from
(
select maingrp, maingroupname,subgrp, subgroupname,subgrp2,subgrouplevel3,led_name ,led_code,closing , case when closing > 0 then closing else 0 end as debit , case when closing < 0 then -closing else 0 end as credit 
from
(
select maingrp,a2.grp_name maingroupname,subgrp,a3.grp_name subgroupname,subgrp2,a4.grp_name subgrouplevel3,led_name,led_code,sum(Obdebit)-sum(Obcredit)+sum(debit)-sum(credit)  closing 
from

 (

 select  led_code, led_name,led_grp_code as grpcode,curbal_comp_code as accref_comp_code,curbal_finid as accref_finid,

curbal_led_code as acctran_led_code,curbal_obdbamt as Obdebit, curbal_obcramt as Obcredit,

0 as debit,0 as credit ,led_type, d.grp_code as maingrp,  c.grp_code as subgrp ,  b.grp_code as subgrp2

from acc_current_balance cb ,acc_ledger_master a ,acc_group_master  b  ,acc_group_master  c ,acc_group_master  d where 
 a.led_grp_code = b.grp_code 
and b.grp_parent_code = c.grp_code 
and c.grp_parent_code = d.grp_code 
and curbal_finid=finid and (curbal_obdbamt+curbal_obcramt)>0 and curbal_led_code = led_code
and curbal_comp_code =compcode   

union all 

 select led_code, led_name,led_grp_code as grpcode,accref_comp_code,accref_finid,acctran_led_code,
acctran_dbamt as Obdebit, acctran_cramt as Obcredit,
0 as debit,0 as credit ,led_type, d.grp_code as maingrp,  c.grp_code as subgrp,  b.grp_code as subgrp2
from acc_ref ar ,acc_tran at ,acc_ledger_master a 
,acc_group_master  b  ,acc_group_master  c ,acc_group_master  d  where 
a.led_grp_code = b.grp_code 
and b.grp_parent_code = c.grp_code 
and c.grp_parent_code = d.grp_code 
and accref_comp_code=compcode and accref_seqno = acctran_accref_seqno and
accref_finid= finid and
accref_voudate > '2022-08-31'  and
accref_voudate < fromdate and 
acctran_led_code = led_code   

union all 

 select led_code, led_name,led_grp_code as grpcode,accref_comp_code,accref_finid,acctran_led_code,
0 as Obdebit, 0 as Obcredit,
acctran_dbamt as debit,acctran_cramt as credit ,led_type, d.grp_code as maingrp,  c.grp_code as subgrp,  b.grp_code as subgrp2
from acc_ref ar ,acc_tran at ,acc_ledger_master a 
,acc_group_master  b  ,acc_group_master  c ,acc_group_master  d  where 
a.led_grp_code = b.grp_code 
and b.grp_parent_code = c.grp_code 
and c.grp_parent_code = d.grp_code 
and accref_comp_code=compcode and accref_seqno = acctran_accref_seqno and
accref_finid= finid and
accref_voudate > '2022-08-31'  and
accref_voudate>=fromdate and accref_voudate<=todate and 
acctran_led_code = led_code  
) tt  ,  acc_group_master a2 , acc_group_master a3  , acc_group_master a4  where tt.maingrp = a2.grp_code and tt.subgrp = a3.grp_code  and tt.subgrp2 = a4.grp_code 
group by maingrp,a2.grp_name,subgrp,a3.grp_name,subgrp2,a4.grp_name,led_name,led_code
having closing <> 0 order by maingrp,a2.grp_name,a3.grp_name,a4.grp_name 
) a1 
 ) aa2  
 ) aa1  group by  maingroupname,subgroupname,subgrouplevel3,ledgrp
 ) aa3  group by  maingroupname,subgroupname,subgrouplevel3
 ) aa4  group by  maingroupname,subgroupname
 ) aa5 group by maingroupname,subgroupname
  ) aa6 group by maingroupname
  ) aa7
  )aa8 group by grptype;
END ;;
DELIMITER ;
