CREATE DEFINER=`root`@`localhost` PROCEDURE `acc_sp_pendingBills`(
	compcode	tinyint,
	finid		tinyint,
	ledcode 	integer
)
select 		
            acctrail_inv_no AS invno, 
			acctrail_inv_date AS invdate, 
            acctrail_inv_value AS invamt, 
			acctrail_adj_value AS adjamt, 
            acctrail_inv_value - acctrail_adj_value AS pendingamt,             
			acctrail_led_code,
			accref_comp_code ,
            accref_finid, 
            accref_seqno ,accref_vouno ,accref_vou_type
            from acc_ref ,  acc_trail where  accref_comp_code = compcode and  accref_seqno = acctrail_accref_seqno and acctrail_led_code = ledcode and  acctrail_inv_value > acctrail_adj_value order by  acctrail_inv_date ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `acc_sp_rep_bankbook1` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
