/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`%` PROCEDURE `acc_sp_rep_bankbook1`(

	ledcode	integer,	compcode	tinyint,	finid		tinyint,	fromdate	datetime,
	todate	datetime,	ledname	varchar(650)

)
BEGIN
select	x.*, z.*, ifnull(w.led_code,0) as led_code1, ifnull(w.finid,0) as finid1, ifnull(w.tran_dbamt,0) as tran_dbamt,    
		ifnull(w.tran_cramt,0) as tran_cramt, y.acctran_led_code, y.led_prefix,	y.acctran_dbamt, y.acctran_cramt,
		y.acctran_totamt as amount  
 	from 
		(select	a.accref_finid, a.accref_comp_code,	a.accref_seqno,	a.accref_vouno,	a.accref_voudate,a.accref_vou_type,      
			ifnull(c.acctrail_inv_no,0) as acctrail_inv_no,
			ifnull(c.acctrail_inv_date,DATE_FORMAT('1900-01-01','%Y-%m-%d')) as acctrail_inv_date,
			ifnull(d.led_code,0) as led_code, ifnull(d.led_name,'') as led_name,
			max(b.acctran_cramt) as totcramt, max(b.acctran_dbamt) as totdbamt,
			max(b.acctran_totamt) as totamt, a.accref_narration, a.accref_bank_name,	a.accref_paymode,
			a.accref_payref_no,	a.accref_payref_date        
		from 	acc_ref a inner join
			acc_company_master on comp_code = a.accref_comp_code
            inner join
			acc_tran b on a.accref_seqno = 	b.acctran_accref_seqno 
            left outer join	acc_trail c on b.acctran_accref_seqno = c.acctrail_accref_seqno and 
				b.acctran_led_code = c.acctrail_led_code 
			inner join acc_ledger_master d on b.acctran_led_code 	= 	d.led_code
  		where 	a.accref_finid 		= 	finid and 
			accref_comp_code 		= 	compcode and       
  			a.accref_seqno in       
  			(select	accref_seqno from 	acc_ref, acc_tran 
			where 	accref_finid 	= 	finid and 
				accref_comp_code 	= 	compcode and       
  				 acctran_led_code 	= 	ledcode and 
				accref_seqno 		= 	acctran_accref_seqno) and       
				b.acctran_led_code 		<> 	 ledcode and 
				a.accref_voudate 		>= 	fromdate and 
				a.accref_voudate 		<= 	todate 
  		group by a.accref_finid, a.accref_seqno, a.accref_vouno, a.accref_voudate, a.accref_vou_type, c.acctrail_inv_no,
			c.acctrail_inv_date, d.led_code, d.led_name, b.acctran_totamt, a.accref_narration, a.accref_bank_name,
			a.accref_paymode, a.accref_payref_no, a.accref_payref_date) x inner join     
		(select 
			acctran_accref_seqno, max(acctran_totamt) as totamt 
		from 	
			acc_tran, acc_ref
		where 	accref_finid 	= 	finid and
			accref_comp_code	=	compcode and 
			acctran_led_code	<>	 ledcode and 
			accref_seqno		=	acctran_accref_seqno and
			accref_seqno		=	acctran_accref_seqno 
		group by acctran_accref_seqno
		) v on x.accref_seqno		=	v.acctran_accref_seqno inner join
  		(select ifnull(accref_finid,0) as accref_finid,	ifnull(accref_seqno,0) as accref_seqno,
			ifnull(accref_vouno,0) as accref_vouno,	ifnull(accref_voudate,DATE_FORMAT('1900-01-01','%Y-%m-%d')) as accref_voudate,
			ifnull(accref_vou_type,'') as accref_vou_type,	ifnull(acctran_led_code,0) as acctran_led_code,      
	  		ifnull(acctran_dbamt,0) as acctran_dbamt, ifnull(acctran_cramt,0) as acctran_cramt,
			ifnull(acctran_totamt,0) as acctran_totamt,	ifnull(led_prefix,'') as led_prefix
	  	from 	acc_ref, acc_tran, acc_ledger_master 
		where 	accref_comp_code 	= 	compcode and 
			accref_finid 		= 	finid and       
  			 acctran_led_code 	= 	ledcode and 
			accref_seqno 		= 	acctran_accref_seqno and
			acctran_led_code	=	led_code
		) y on x.accref_seqno 		= 	y.accref_seqno 
        inner join
  		(select ifnull(curbal_led_code,0) as led_code2, ifnull(curbal_finid,0)  as finid,    
   			ifnull(curbal_obdbamt,0)  as ob_dbamt, ifnull(curbal_obcramt,0)  as ob_cramt    
   		from  	acc_current_balance     
		where   curbal_led_code = 	ledcode and     
        	curbal_finid 		= 	finid and
            curbal_comp_code    =   compcode
		) z on y.acctran_led_code 	= 	z.led_code2 and 
  		 x.accref_finid 		= 	z.finid left outer join
  		(select ifnull(acctran_led_code,0) as led_code,    
   			ifnull(accref_finid,0) as finid,    
   			sum(ifnull(acctran_dbamt,0)) as tran_dbamt,    
   			sum(ifnull(acctran_cramt,0)) as tran_cramt     
   		from  	acc_tran, acc_ref    
   		where  	acctran_accref_seqno 	= 	accref_seqno and     
   			accref_finid 		= 	finid and     
   			accref_comp_code 	= 	compcode and     
   			 acctran_led_code 	= 	ledcode and 
			accref_voudate 		< 	fromdate and     
   			accref_vou_type 	not in 	('OB','UB','BA','','CA')    
  		group by acctran_led_code, accref_finid) w on z.led_code2 = w.led_code and 
  		   x.accref_finid 		= 	w.finid and
		   y.acctran_led_code = w.led_code
  	Where 	
		x.accref_vou_type 	not in 	('OB','UB','BA','CA','') and       
  		x.accref_voudate 	>= 	fromdate and 
		x.accref_voudate 	<= 	todate and 
		x.totamt		=	v.totamt
union all
	select 0,0,0,'',DATE_FORMAT('1900-01-01','%Y-%m-%d'),'','',DATE_FORMAT('1900-01-01','%Y-%m-%d'),0,'',0,0,0,'','','','',DATE_FORMAT('1900-01-01','%Y-%m-%d'),a.*,b.*,0,'',0,0,0
	from 
	(
		select 	ifnull(curbal_led_code,0)  as led_code,	ifnull(curbal_finid,0)  as finid,    
   			ifnull(curbal_obdbamt,0)  as ob_dbamt, ifnull(curbal_obcramt,0)  as ob_cramt    
		from  	acc_current_balance     
		where  	 curbal_led_code = 	ledcode and 
        	curbal_finid 		= 	finid and
            curbal_comp_code    =   compcode ) a left outer join  		
	(
		select 	ifnull(acctran_led_code,0) as led_code,    
   			ifnull(accref_finid,0) as finid,    
   			ifnull(sum(acctran_dbamt),0) as tran_dbamt,    
   			ifnull(sum(acctran_cramt),0) as tran_cramt     
   		from  	acc_tran,    
   			acc_ref    
   		where  	acctran_accref_seqno 	= 	accref_seqno and     
   			accref_finid 		= 	finid and     
   			accref_comp_code 	= 	compcode and     
   			 acctran_led_code 	= 	ledcode and 
			accref_voudate 		< 	fromdate and     
   			accref_vou_type 	not in 	('OB','UB','BA','','CA')    
  		group by acctran_led_code,
			accref_finid) b on a.led_code = b.led_code and a.finid = b.finid ;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `acc_sp_rep_bankbooknew` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
