/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`%` PROCEDURE `acc_sp_rep_bankbooknew`(
compcode int,
fromdate DATETIME,
todate DATETIME,
reptype char(1),
selledcode varchar(500)
)
BEGIN
if(reptype = 'G') then
	SELECT
    a.accref_finid,  a.accref_seqno, a.accref_vouno, a.accref_voudate AS accref_voudate,
    a.accref_vou_type, IFNULL(c.acctrail_inv_no, '') AS acctrail_inv_no,
    c.acctrail_inv_date AS acctrail_inv_date, d.led_code, d.led_name,
    sum(b.acctran_cramt) AS totcramt, sum(b.acctran_dbamt) AS totdbamt,
    a.accref_narration, a.accref_bank_name,
    a.accref_paymode,
    a.accref_payref_no,
    a.accref_payref_date AS accref_payref_date
	FROM
    acc_ref a
        INNER JOIN
    acc_tran b ON a.accref_seqno = b.acctran_accref_seqno
        LEFT OUTER JOIN
    acc_trail c ON b.acctran_accref_seqno = c.acctrail_accref_seqno
        AND b.acctran_led_code = c.acctrail_led_code
        AND a.accref_seqno = c.acctrail_accref_seqno
        INNER JOIN
    acc_ledger_master d ON b.acctran_led_code = d.led_code
	WHERE
    a.accref_voudate>=fromdate and a.accref_voudate<=todate 
        AND accref_comp_code = compcode and 
        case when reptype = 'A' then led_grp_code like '%' else find_in_set(led_grp_code,selledcode) end 
		group by accref_seqno,acctran_serialno order by accref_seqno,acctran_serialno asc;
else
	SELECT
		a.accref_finid,
		a.accref_seqno,
		a.accref_vouno,
		a.accref_voudate AS accref_voudate,
		a.accref_vou_type,
		IFNULL(c.acctrail_inv_no, '') AS acctrail_inv_no,
		c.acctrail_inv_date AS acctrail_inv_date,
		d.led_code,
		d.led_name,
		sum(b.acctran_cramt) AS totcramt,
		sum(b.acctran_dbamt) AS totdbamt,
		a.accref_narration,
		a.accref_bank_name,
		a.accref_paymode,
		a.accref_payref_no,
		a.accref_payref_date AS accref_payref_date
	FROM
		acc_ref a
			INNER JOIN
		acc_tran b ON a.accref_seqno = b.acctran_accref_seqno
			LEFT OUTER JOIN
		acc_trail c ON b.acctran_accref_seqno = c.acctrail_accref_seqno
			AND b.acctran_led_code = c.acctrail_led_code
			AND a.accref_seqno = c.acctrail_accref_seqno
			INNER JOIN
		acc_ledger_master d ON b.acctran_led_code = d.led_code
	WHERE
		a.accref_voudate>=fromdate and a.accref_voudate<=todate 
			AND accref_comp_code = compcode and 
	case when reptype = 'A' then led_code like '%' else find_in_set(led_code,selledcode) end 		
	group by accref_seqno,acctran_serialno order by accref_seqno,acctran_serialno asc;
end if;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `acc_sp_rep_bank_book_reconciliation` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`%` PROCEDURE `acc_sp_rep_bank_book_reconciliation`(
	ledcode	integer, compcode	tinyint,	fincode		tinyint ,
	todate	date  
    
)
BEGIN
-- Step 1: Get opening balances for ledger ledcode
WITH base_opening AS (
    SELECT 
        ledcode AS ledgercode,
        curbal_obdbamt AS opening_debit,
        curbal_obcramt AS opening_credit
    FROM acc_current_balance 
    WHERE curbal_led_code = ledcode 
      AND curbal_comp_code = compcode  
      AND curbal_finid = fincode 

    UNION ALL

    SELECT 
        ledcode AS ledgercode,
        SUM(acctran_dbamt) AS opening_debit,
        SUM(acctran_cramt) AS opening_credit
    FROM acc_ref 
    JOIN acc_tran 
        ON acctran_accref_seqno = acc_ref.accref_seqno  
        AND acctran_led_code = ledcode
    WHERE acc_ref.accref_comp_code = compcode  
      AND acc_ref.accref_finid = fincode  
      AND acc_ref.accref_voudate <= todate 
),

-- Step 2: Get unreconciled voucher entries on other ledgers (linked to ledcode vouchers)
unreconciled_related AS (
    SELECT 
        acc_ref.accref_seqno,accref_paymode,accref_payref_no,accref_payref_date,
        acctran_led_code AS other_ledger,
        acctran_dbamt acctran_cramt,
        acctran_cramt acctran_dbamt,
        acc_ref.accref_voudate, accref_vouno
    FROM acc_ref 
    JOIN acc_tran 
        ON acctran_accref_seqno = acc_ref.accref_seqno  
        AND acctran_led_code != ledcode
    WHERE acc_ref.accref_comp_code = compcode  
      AND acc_ref.accref_finid >= 24  
      AND acc_ref.accref_vou_type IN ('BKP', 'BKR')
      AND acc_ref.accref_voudate <= todate 
      AND acc_ref.accref_recon_date IS NULL
      AND acc_ref.accref_seqno IN (
          SELECT acc_ref.accref_seqno 
          FROM acc_ref 
          JOIN acc_tran 
              ON acctran_accref_seqno = acc_ref.accref_seqno  
              AND acctran_led_code = ledcode
          WHERE acc_ref.accref_comp_code = compcode 
            AND acc_ref.accref_finid >= 24  
            AND acc_ref.accref_vou_type IN ('BKP', 'BKR')
            AND acc_ref.accref_voudate <= todate 
            AND acc_ref.accref_recon_date IS NULL
      )
)

-- Step 3: Join and final output
SELECT 
    bo.ledgercode,
    SUM(bo.opening_debit) AS opening_debit,
    SUM(bo.opening_credit) AS opening_credit,
    SUM(bo.opening_credit) - SUM(bo.opening_debit) AS closing,
    ur.other_ledger,
    ur.accref_seqno,
    ur.acctran_dbamt,
    ur.acctran_cramt,
	ur.accref_vouno,
    ur.accref_voudate,
    cust_name,accref_paymode,accref_payref_no,accref_payref_date
FROM base_opening bo
LEFT JOIN unreconciled_related ur
    ON bo.ledgercode = ledcode  -- Static match, useful for attaching rows
join massal_customer where cust_code = other_ledger    
GROUP BY 
    bo.ledgercode,
    ur.other_ledger,
    ur.accref_seqno,
    ur.acctran_dbamt,
    ur.acctran_cramt,
    ur.accref_vouno,
    ur.accref_voudate,
    cust_name,accref_paymode,accref_payref_no,accref_payref_date
ORDER BY ur.accref_voudate , accref_seqno;

END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `acc_sp_rep_cashbank_book` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`%` PROCEDURE `acc_sp_rep_cashbank_book`(
	ledcode	integer, compcode	tinyint,	finid		tinyint ,
    finstartdate	date,
	fromdate	date,
	todate	date  
    -- , pledcode int
)
BEGIN
select * from (
select  accref_seqno, accref_vouno,accref_comp_code,accref_voudate,accref_narration,
		acctran_led_code,cr acctran_dbamt ,dr acctran_cramt,accref_payref_no,accref_payref_date, ledcode2,
		yropdebit,  yropcredit, trnobdebit, trnobcreit,cust_name from
 (
select acc_ref.accref_seqno, acc_ref.accref_vouno,acc_ref.accref_comp_code,acc_ref.accref_voudate,
		acc_ref.accref_narration,acc_tran.acctran_led_code,acc_tran.acctran_dbamt dr,acc_tran.acctran_cramt cr,
        acc_ref.accref_payref_no,acc_ref.accref_payref_date, ledcode as ledcode2
 from acc_ref 
	inner join acc_tran on  acc_tran.acctran_accref_seqno = acc_ref.accref_seqno 
		and acc_tran.acctran_led_code <> ledcode
	inner join acc_tran trn2 on  trn2.acctran_accref_seqno = acc_ref.accref_seqno 
		and trn2.acctran_led_code = ledcode              
 where acc_ref.accref_comp_code = compcode   and acc_ref.accref_finid = finid 
		and  acc_ref.accref_voudate >= fromdate  and  acc_ref.accref_voudate <= todate
		and  acc_ref.accref_vouno in 
        (select acc_ref.accref_vouno from acc_ref 
			inner join acc_tran on  acctran_accref_seqno = acc_ref.accref_seqno 
            and acctran_led_code = ledcode
			where   acc_ref.accref_comp_code = compcode and acc_ref.accref_finid = finid 
            and acc_ref.accref_voudate >= fromdate and  acc_ref.accref_voudate <=  todate  
		group by acc_ref.accref_vouno)
		) a  INNER JOIN 
        (select   j.cur_led_code,sum(yropdebit) as yropdebit ,  
			sum(yropcredit) as yropcredit,sum(trnobdebit) as trnobdebit,sum(trnobcreit) as trnobcreit
			from (
				select  ledcode cur_led_code,0 as yropdebit ,  0 as yropcredit,
					sum(acctran_dbamt) as trnobdebit, sum(acctran_cramt) as trnobcreit 
                from acc_ref  inner join acc_tran on   
					acctran_accref_seqno = acc_ref.accref_seqno and acctran_led_code = ledcode
				where acc_ref.accref_comp_code = compcode  and acc_ref.accref_finid = finid and  
					acc_ref.accref_voudate >= finstartdate and  acc_ref.accref_voudate  < fromdate
				union all 
				(select acc_current_balance.curbal_led_code cur_led_code, max(curbal_obdbamt) yropdebit , 
						max(curbal_obcramt) yropcredit,0 as trnobdebit,0 as trnobcreit 
				from acc_current_balance 
				where acc_current_balance.curbal_led_code = ledcode and acc_current_balance.curbal_comp_code = compcode 
                and acc_current_balance.curbal_finid= finid group by cur_led_code )) j  group by  cur_led_code LIMIT 1
		) a1  ON a1.cur_led_code = a.ledcode2 
		INNER JOIN massal_customer b ON  a.acctran_led_code = b.cust_code order by accref_voudate,accref_seqno
 ) aa1;               
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `acc_sp_rep_cashbank_book_Datewise` */;
