CREATE DEFINER=`root`@`%` PROCEDURE `acc_sp_rep_collection_payment`(
compcode	tinyint,	startdate	date, enddate date	 
)
BEGIN
select accref_seqno,accref_voudate, cust_name,accref_vouno,accref_vou_type,
 concat( DATE_FORMAT(accref_voudate, '%d-%m-%Y') , ' - ' , accref_vouno , ' - ' , cust_name   , ' - ' , acctran_cramt  ) as heading,acctran_dbamt,acctran_cramt,  ref_invno ,  DATE_FORMAT(ref_invdate, '%d-%m-%Y') ref_invdate ,ref_adjamount , ref_paymt_terms, ref_adj_days
  from acc_ref ref left join acc_tran trn
 on ref.accref_seqno = trn.acctran_accref_seqno
 left outer join acc_adjustments adj on ref_compcode = accref_comp_code and acctran_accref_seqno = ref_docseqno and acctran_led_code = ref_ledcode
 join massal_customer led on led.cust_code = trn.acctran_led_code
 where   accref_comp_code = compcode and accref_voudate between startdate and enddate and accref_vou_type in('CHR','BKR')  order by accref_seqno ;
END ;;
DELIMITER ;
