CREATE DEFINER=`root`@`%` PROCEDURE `acc_sp_rep_dbcrnote_register`(

	voutype	varchar(3),

	fromdate	date,

	todate	date,

	compcode	tinyint

)
BEGIN
if voutype = 'PWP' or  voutype = 'PIW' or  voutype = 'PLW' then

select * from 

	(

	select distinct

		acc_ref.accref_seqno,

		acc_ref.accref_vouno,

		acc_ref.accref_vou_type,

		acc_ref.accref_voudate,

		acc_ref.accref_narration,

		 acc_tran.acctran_dbamt,

		 acc_tran.acctran_cramt,

		acc_tran.acctran_totamt,

		massal_customer.cust_code,

	  	acc_trail.acctrail_inv_no,

		acc_trail.acctrail_inv_date,cust_name , 
        acctran_serialno

	from 	acc_ref,

		acc_tran,

		acc_trail,

		massal_customer

	where 	acc_ref.accref_seqno 		= 	acc_tran.acctran_accref_seqno and

		acc_tran.acctran_accref_seqno 	= 	acc_trail.acctrail_accref_seqno and 

		acc_tran.acctran_led_code 	= 	massal_customer.cust_code and 

	-- acc_ref.accref_comp_code	=	massal_customer.led_comp_code and

		acc_ref.accref_vou_type in ('PLW','PIW','PWP') and

		acc_ref.accref_voudate 		>= 	fromdate and 

		acc_ref.accref_voudate 		<= 	todate and

		acc_ref.accref_comp_code	=	compcode

	UNION

		select 	distinct

		acc_ref.accref_seqno,

		acc_ref.accref_vouno,

		acc_ref.accref_vou_type,

		acc_ref.accref_voudate,

		acc_ref.accref_narration,

		 acc_tran.acctran_dbamt,

		 acc_tran.acctran_cramt,

		acc_tran.acctran_totamt,

		massal_customer.cust_code,'' as acctrail_inv_no,

	  ''  as acctrail_inv_date,cust_name,
		acctran_serialno

	from 	acc_ref,

		acc_tran,

		massal_customer

	where 	acc_ref.accref_seqno 		= 	acc_tran.acctran_accref_seqno and

		acc_tran.acctran_led_code 	= 	massal_customer.cust_code and 

	-- 	acc_ref.accref_comp_code	=	massal_customer.led_comp_code and

