CREATE DEFINER=`root`@`%` PROCEDURE `acc_sp_rep_ledger`(
	ledcode	varchar(200),	compcode	tinyint,	finid		tinyint,	fromdate	datetime,
	todate	datetime,	ledname	varchar(650),ledtype varchar(1)
    )
BEGIN
if ledtype = 'G' then
	select * from
	(
	select * from 
	(
	select curbal_led_code  , curbal_obdbamt , curbal_obcramt from acc_current_balance  where find_in_set(curbal_led_code,ledcode) and  curbal_comp_code = compcode  and curbal_finid  = finid   ) op
	left join
	(
	select   acctran_led_code , sum(acctran_dbamt) as trn_opdr  , sum(acctran_cramt) as trn_opcr  from acc_ref a ,acc_tran b  where accref_comp_code = compcode  and accref_finid = finid     and accref_seqno  = acctran_accref_seqno  and   accref_voudate  <  fromdate  and find_in_set(acctran_led_code,ledcode)  group by accref_comp_code,accref_finid,acctran_led_code
	) trnop
	on  op.curbal_led_code = trnop.acctran_led_code

	) trnop
	left join 
	(
	 select  accref_seqno,accref_vouno ,accref_vou_type accref_voutype, accref_voudate, accref_payref_no, accref_payref_date, accref_narration, acctran_led_code ,  acctran_dbamt , acctran_cramt  , accref_paymode  
	from acc_ref a ,acc_tran b  where accref_comp_code = compcode  and accref_finid  = finid    and accref_seqno  = acctran_accref_seqno  and   accref_voudate  >= fromdate and  accref_voudate  <=  todate  and acctran_totamt > 0 and find_in_set(acctran_led_code,ledcode) 

	 ) trn
	on trnop.curbal_led_code = trn.acctran_led_code 

	left join
	(
   select  m1.* from 
   (
  	select  accref_vou_type,  acctran_accref_seqno,acctran_serialno,acctran_led_code ledgercode,cust_name ledgername ,cust_type ,acctran_dbamt dbamt,acctran_cramt cramt from 
	 acc_ref a ,acc_tran b , massal_customer c where accref_comp_code = compcode 
	 and accref_finid  = finid     and accref_seqno  = acctran_accref_seqno   and accref_voudate  >= fromdate  and  accref_voudate  <=  todate  and acctran_led_code = cust_code   
	and acctran_led_code not in (ledcode) and accref_seqno in (
	select  accref_seqno from acc_ref a ,acc_tran b  where accref_comp_code = compcode  and accref_finid  = finid     and accref_seqno  = acctran_accref_seqno   and accref_voudate  >= fromdate and  accref_voudate  <=  todate   and find_in_set(acctran_led_code,ledcode))
    ) m1
    join
    (select accref_seqno seqno , min(acctran_serialno) slno from 
	acc_ref a ,acc_tran b , massal_customer c where accref_comp_code = compcode 
	and accref_finid  = finid     and accref_seqno  = acctran_accref_seqno   and accref_voudate  >= fromdate  and  accref_voudate  <=  todate  and acctran_led_code = cust_code  and acctran_totamt > 0
	and acctran_led_code not in (ledcode) and accref_seqno in (
	select  accref_seqno
	from acc_ref a ,acc_tran b  where accref_comp_code = compcode  and accref_finid  = finid     and accref_seqno  = acctran_accref_seqno   and accref_voudate  >= fromdate and  accref_voudate  <=  todate  and acctran_totamt > 0 and find_in_set(acctran_led_code,ledcode))
    group by accref_seqno ) t1 on acctran_accref_seqno = seqno and acctran_serialno = slno
   
	)
	 as led1
	on  led1.acctran_accref_seqno = trn.accref_seqno 
	left join 
	(select cust_name partyledger, cust_code from massal_customer) as led2
	 on led2.cust_code = trnop.curbal_led_code
	 ORDER by accref_voudate,accref_vouno;

else

 	select * from
	(
	select * from 
	(
	select curbal_led_code  , curbal_obdbamt , curbal_obcramt from acc_current_balance  where find_in_set(curbal_led_code,ledcode) and  curbal_comp_code = compcode  and curbal_finid  = finid    ) op
	left join
	(
	select   acctran_led_code , sum(acctran_dbamt) as trn_opdr  , sum(acctran_cramt) as trn_opcr  from acc_ref a ,acc_tran b  where accref_comp_code = compcode  and accref_finid = finid      and accref_seqno  = acctran_accref_seqno  and   accref_voudate  <  fromdate  and acctran_totamt > 0 and find_in_set(acctran_led_code,ledcode)  group by accref_comp_code,accref_finid,acctran_led_code
	) trnop
	on  op.curbal_led_code = trnop.acctran_led_code

	) trnop
	left join 
	(
	 select  accref_seqno,accref_vouno ,accref_vou_type , accref_voudate, accref_payref_no, accref_payref_date, accref_narration, acctran_led_code ,  acctran_dbamt , acctran_cramt  , accref_paymode  
	from acc_ref a ,acc_tran b  where accref_comp_code = compcode  and accref_finid  = finid     and accref_seqno  = acctran_accref_seqno  and   accref_voudate  >= fromdate and  accref_voudate  <=  todate  and acctran_totamt > 0 and find_in_set(acctran_led_code,ledcode) 

	 ) trn
	on trnop.curbal_led_code = trn.acctran_led_code 

	left join
	(
   select  m1.* from 
   (
  	select  accref_vou_type accref_voutype ,  acctran_accref_seqno,acctran_serialno,acctran_led_code ledgercode,cust_name ledgername ,cust_type ,acctran_dbamt dbamt,acctran_cramt cramt from 
	 acc_ref a ,acc_tran b , massal_customer c where accref_comp_code = compcode 
	 and accref_finid  = finid     and accref_seqno  = acctran_accref_seqno   and accref_voudate  >= fromdate  and  accref_voudate  <=  todate  and acctran_led_code = cust_code   and cust_type = 'G'    
	and acctran_totamt > 0 and acctran_led_code not in (ledcode) and accref_seqno in (
	select  accref_seqno from acc_ref a ,acc_tran b  where accref_comp_code = compcode  and accref_finid  = finid     and accref_seqno  = acctran_accref_seqno   and accref_voudate  >= fromdate and  accref_voudate  <=  todate   and find_in_set(acctran_led_code,ledcode))
    ) m1
    join
    (select accref_seqno seqno , min(acctran_serialno) slno from 
	acc_ref a ,acc_tran b , massal_customer c where accref_comp_code = compcode 
	and accref_finid  = finid     and accref_seqno  = acctran_accref_seqno   and accref_voudate  >= fromdate  and  accref_voudate  <=  todate  and acctran_led_code = cust_code   and cust_type = 'G'        
	and acctran_led_code not in (ledcode) and accref_seqno in (
	select  accref_seqno
	from acc_ref a ,acc_tran b  where accref_comp_code = compcode  and accref_finid  = finid     and accref_seqno  = acctran_accref_seqno   and accref_voudate  >= fromdate and  accref_voudate  <=  todate  and acctran_totamt > 0 and find_in_set(acctran_led_code,ledcode))
    group by accref_seqno ) t1 on acctran_accref_seqno = seqno and acctran_serialno = slno  
		)
	 as led1
	on  led1.acctran_accref_seqno = trn.accref_seqno 
	left join 
	(select cust_name partyledger, cust_code from massal_customer) as led2
	 on led2.cust_code = trnop.curbal_led_code
	 ORDER by accref_voudate,accref_vouno;

end if;     
END ;;
