 select  accref_seqno,accref_vouno ,accref_vou_type, accref_voudate, accref_payref_no, accref_payref_date, accref_narration, acctran_led_code ,  acctran_dbamt , acctran_cramt  , accref_paymode  
from acc_ref a ,acc_tran b  where accref_comp_code = compcode  and accref_finid  = finid    and accref_seqno  = acctran_accref_seqno  and   accref_voudate  >= fromdate and  accref_voudate  <=  todate   and find_in_set(acctran_led_code,ledcode) 

