CREATE DEFINER=`root`@`%` PROCEDURE `acc_sp_rep_ledgers_credit`(compcode tinyint,fincode tinyint,	fromdate date,
	todate	date,	ledcode int)
BEGIN
select * from 
(select curbal_led_code  , curbal_obcramt from acc_current_balance  where find_in_set(curbal_led_code,ledcode) and  curbal_comp_code = compcode and curbal_finid  = fincode) op
left join
(select   acctran_led_code , sum(acctran_cramt) as trn_opcr  from acc_ref a ,acc_tran b  where accref_comp_code = compcode and accref_finid = fincode and accref_seqno  = acctran_accref_seqno  and  accref_voudate  > '2022-08-31' and   accref_voudate  <  fromdate and find_in_set(acctran_led_code,ledcode) and acctran_cramt > 0  group by accref_comp_code,accref_finid,acctran_led_code) trnop
on  op.curbal_led_code = trnop.acctran_led_code
left join
(select  accref_seqno,accref_vouno ,accref_vou_type, accref_voudate, accref_payref_no, accref_payref_date, accref_narration, acctran_led_code ,  acctran_cramt  from acc_ref a ,acc_tran b  where accref_comp_code = compcode and accref_finid  = fincode and accref_seqno  = acctran_accref_seqno  and   accref_voudate  > '2022-08-31' and accref_voudate  >= fromdate and  accref_voudate  <=  todate and find_in_set(acctran_led_code,ledcode) and acctran_cramt > 0 ) trn
on op.curbal_led_code = trn.acctran_led_code ;
END ;;
