DELIMITER ;;
CREATE DEFINER=`root`@`%` PROCEDURE `acc_sp_rep_ledgers_debit`(compcode tinyint,fincode tinyint,	fromdate date,
	todate	date,	ledcode int)
BEGIN
select * from 
(select curbal_led_code  , curbal_obdbamt from acc_current_balance  where find_in_set(curbal_led_code,ledcode) and  curbal_comp_code = compcode and curbal_finid  = fincode) op
left join
(select   acctran_led_code , sum(acctran_dbamt) as trn_opdr  from acc_ref a ,acc_tran b  where accref_comp_code = compcode and accref_finid = fincode and accref_seqno  = acctran_accref_seqno  and  accref_voudate  > '2022-08-31' and   accref_voudate  <  fromdate and find_in_set(acctran_led_code,ledcode) and acctran_dbamt > 0  group by accref_comp_code,accref_finid,acctran_led_code) trnop
on  op.curbal_led_code = trnop.acctran_led_code
left join
(select  accref_seqno,accref_vouno ,accref_vou_type, accref_voudate, accref_payref_no, accref_payref_date, accref_narration, acctran_led_code ,  acctran_dbamt  from acc_ref a ,acc_tran b  where accref_comp_code = compcode and accref_finid  = fincode and accref_seqno  = acctran_accref_seqno  and   accref_voudate  > '2022-08-31' and accref_voudate  >= fromdate and  accref_voudate  <=  todate and find_in_set(acctran_led_code,ledcode) and acctran_dbamt > 0 ) trn
on op.curbal_led_code = trn.acctran_led_code ;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `acc_sp_rep_ledger_17052025` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`%` PROCEDURE `acc_sp_rep_ledger_17052025`(
	ledcode	varchar(200),	compcode	tinyint,	finid		tinyint,	fromdate	datetime,
	todate	datetime,	ledname	varchar(650),ledtype varchar(1)
    )
BEGIN
if ledtype = 'G' then
	select * from
	(
	select * from 
	(
	select curbal_led_code  , curbal_obdbamt , curbal_obcramt from acc_current_balance  where find_in_set(curbal_led_code,ledcode) and  curbal_comp_code = compcode  and curbal_finid  = finid   ) op
	left join
	(
	select   acctran_led_code , sum(acctran_dbamt) as trn_opdr  , sum(acctran_cramt) as trn_opcr  from acc_ref a ,acc_tran b  where accref_comp_code = compcode  and accref_finid = finid     and accref_seqno  = acctran_accref_seqno  and   accref_voudate  <  fromdate  and find_in_set(acctran_led_code,ledcode)  group by accref_comp_code,accref_finid,acctran_led_code
	) trnop
	on  op.curbal_led_code = trnop.acctran_led_code

	) trnop
	left join 
	(
	 select  accref_seqno,accref_vouno ,accref_vou_type, accref_voudate, accref_payref_no, accref_payref_date, accref_narration, acctran_led_code ,  acctran_dbamt , acctran_cramt  , accref_paymode  
	from acc_ref a ,acc_tran b  where accref_comp_code = compcode  and accref_finid  = finid    and accref_seqno  = acctran_accref_seqno  and   accref_voudate  >= fromdate and  accref_voudate  <=  todate   and find_in_set(acctran_led_code,ledcode) 

	 ) trn
	on trnop.curbal_led_code = trn.acctran_led_code 

	left join
	(
	select  accref_vou_type,  acctran_accref_seqno,acctran_serialno,acctran_led_code ledgercode,cust_name ledgername ,cust_type ,acctran_dbamt dbamt,acctran_cramt cramt from 
	 acc_ref a ,acc_tran b , massal_customer c where accref_comp_code = compcode 
	 and accref_finid  = finid    and accref_seqno  = acctran_accref_seqno   and accref_voudate  >= fromdate  and  accref_voudate  <=  todate  and acctran_led_code = cust_code   and cust_type != 'G'  
	and acctran_led_code not in (ledcode) and  acctran_serialno in (
	select  acctran_serialno from 
	 acc_ref a ,acc_tran b , massal_customer c where accref_comp_code = compcode 
	 and accref_finid  = finid    and accref_seqno  = acctran_accref_seqno   and accref_voudate  >= fromdate  and  accref_voudate  <=  todate  and acctran_led_code = cust_code    and cust_type != 'G' 
	and acctran_led_code not in (ledcode) and accref_seqno in (
	 select  accref_seqno
	from acc_ref a ,acc_tran b  where accref_comp_code = compcode  and accref_finid  = finid    and accref_seqno  = acctran_accref_seqno   and accref_voudate  >= fromdate and  accref_voudate  <=  todate   and find_in_set(acctran_led_code,ledcode) 
	)
	) and accref_seqno in (
	 select  accref_seqno
	from acc_ref a ,acc_tran b  where accref_comp_code = compcode  and accref_finid  = finid    and accref_seqno  = acctran_accref_seqno   and accref_voudate  >= fromdate and  accref_voudate  <=  todate   and find_in_set(acctran_led_code,ledcode) 
	)

	)
	 as led1
	on  led1.acctran_accref_seqno = trn.accref_seqno 
	left join 
	(select cust_name partyledger, cust_code from massal_customer) as led2
	 on led2.cust_code = trnop.curbal_led_code
	 ORDER by accref_voudate,accref_vouno;

else
 	select * from
	(
	select * from 
	(
	select curbal_led_code  , curbal_obdbamt , curbal_obcramt from acc_current_balance  where find_in_set(curbal_led_code,ledcode) and  curbal_comp_code = compcode  and curbal_finid  = finid   ) op
	left join
	(
	select   acctran_led_code , sum(acctran_dbamt) as trn_opdr  , sum(acctran_cramt) as trn_opcr  from acc_ref a ,acc_tran b  where accref_comp_code = compcode  and accref_finid = finid     and accref_seqno  = acctran_accref_seqno  and   accref_voudate  <  fromdate  and find_in_set(acctran_led_code,ledcode)  group by accref_comp_code,accref_finid,acctran_led_code
	) trnop
	on  op.curbal_led_code = trnop.acctran_led_code

	) trnop
	left join 
	(
	 select  accref_seqno,accref_vouno ,accref_vou_type, accref_voudate, accref_payref_no, accref_payref_date, accref_narration, acctran_led_code ,  acctran_dbamt , acctran_cramt  , accref_paymode  
	from acc_ref a ,acc_tran b  where accref_comp_code = compcode  and accref_finid  = finid    and accref_seqno  = acctran_accref_seqno  and   accref_voudate  >= fromdate and  accref_voudate  <=  todate   and find_in_set(acctran_led_code,ledcode) 

	 ) trn
	on trnop.curbal_led_code = trn.acctran_led_code 

	left join
	(
	select  accref_vou_type,  acctran_accref_seqno,acctran_serialno,acctran_led_code ledgercode,cust_name ledgername ,cust_type ,acctran_dbamt dbamt,acctran_cramt cramt from 
	 acc_ref a ,acc_tran b , massal_customer c where accref_comp_code = compcode 
	 and accref_finid  = finid    and accref_seqno  = acctran_accref_seqno   and accref_voudate  >= fromdate  and  accref_voudate  <=  todate  and acctran_led_code = cust_code   and cust_type = 'G'  
	and acctran_led_code not in (ledcode) and  acctran_serialno in (
	select  min(acctran_serialno) slno from 
	 acc_ref a ,acc_tran b , massal_customer c where accref_comp_code = compcode 
	 and accref_finid  = finid    and accref_seqno  = acctran_accref_seqno   and accref_voudate  >= fromdate  and  accref_voudate  <=  todate  and acctran_led_code = cust_code    and cust_type = 'G'    
	and acctran_led_code not in (ledcode) and accref_seqno in (
	 select  accref_seqno
	from acc_ref a ,acc_tran b  where accref_comp_code = compcode  and accref_finid  = finid    and accref_seqno  = acctran_accref_seqno   and accref_voudate  >= fromdate and  accref_voudate  <=  todate   and find_in_set(acctran_led_code,ledcode) 
	)
	) and accref_seqno in (
	 select  accref_seqno
	from acc_ref a ,acc_tran b  where accref_comp_code = compcode  and accref_finid  = finid    and accref_seqno  = acctran_accref_seqno   and accref_voudate  >= fromdate and  accref_voudate  <=  todate   and find_in_set(acctran_led_code,ledcode) 
	)

	)
	 as led1
	on  led1.acctran_accref_seqno = trn.accref_seqno 
	left join 
	(select cust_name partyledger, cust_code from massal_customer) as led2
	 on led2.cust_code = trnop.curbal_led_code
	 ORDER by accref_voudate,accref_vouno;

end if;     
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
