CREATE DEFINER=`root`@`%` PROCEDURE `acc_sp_rep_ledger_closing_balance`(ledcode int,compcode int,	finid int,fromdate date,
	todate	date)
BEGIN

select acctran_led_code , 
sum(opdr) opdr, sum(opcr) opcr, sum(trn_opdr) trn_opdr , sum(trn_opcr) trn_opcr, sum(trn_dr) trn_dr, sum(trn_cr) trn_cr ,sum(trn_sales) as trn_sales 

from 
(
select curbal_led_code  acctran_led_code , curbal_obdbamt opdr , curbal_obcramt opcr, 0 as trn_opdr, 0 as trn_opcr , 0 as trn_dr,0 as trn_cr  ,0 as trn_sales  from acc_current_balance  where find_in_set(curbal_led_code,ledcode) and  curbal_comp_code = compcode and curbal_finid  = finid
union all
select   acctran_led_code ,0 as opdr,0 as opcr, sum(acctran_dbamt) as trn_opdr  , sum(acctran_cramt) as trn_opcr , 0 as trn_dr,0 as trn_cr ,0 as trn_sales from acc_ref a ,acc_tran b  where accref_comp_code = compcode and accref_finid = finid and accref_seqno  = acctran_accref_seqno  and  accref_voudate  > '2022-08-31' and   accref_voudate  <  fromdate and find_in_set(acctran_led_code,ledcode)  group by accref_comp_code,accref_finid,acctran_led_code
union all
select   acctran_led_code ,0 as opdr,0 as opcr, 0 as trn_opdr, 0 as trn_opcr , sum(acctran_dbamt) as trn_dr  , sum(acctran_cramt) as trn_cr ,0 as trn_sales  from acc_ref a ,acc_tran b  where accref_comp_code = compcode and accref_finid = finid and accref_seqno  = acctran_accref_seqno  and  accref_voudate  > '2022-08-31' and   accref_voudate  >= fromdate and  accref_voudate  <=  todate  and find_in_set(acctran_led_code,ledcode)  group by accref_comp_code,accref_finid,acctran_led_code
union all
select   acctran_led_code ,0 as opdr,0 as opcr, 0 as trn_opdr, 0 as trn_opcr , 0 as trn_dr  , 0 as trn_cr , sum(acctran_dbamt) as trn_sales from acc_ref a ,acc_tran b  where accref_comp_code = compcode and accref_finid = finid and accref_seqno  = acctran_accref_seqno  and  accref_voudate  > '2022-08-31' and   accref_voudate  >= fromdate and  accref_voudate  <=  todate  and find_in_set(acctran_led_code,ledcode)  and accref_vou_type = 'GSI'  group by accref_comp_code,accref_finid,acctran_led_code
)  a1 group by  acctran_led_code;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
