CREATE DEFINER=`root`@`%` PROCEDURE `acc_sp_rep_selaccountref`(
compcode integer,  
finyear integer,  
voucherno varchar(60)  
)
BEGIN
 select * from acc_ref   
 where  accref_vouno   =  voucherno and   
  accref_comp_code  =  compcode and   
  accref_finid   =  finyear;
END ;;
DELIMITER ;
