CREATE DEFINER=`root`@`%` PROCEDURE `acc_sp_rep_voucher_Party_Amount`(
	voutype	varchar(3),
	fromdate	date,
	todate	date,
	compcode	tinyint
)
BEGIN
if voutype = 'PWP' or  voutype = 'PIW' or  voutype = 'PLW' then
	select distinct
		acc_ref.accref_seqno,
		acc_ref.accref_vouno,
		acc_ref.accref_vou_type,
		acc_ref.accref_voudate,
		acc_ref.accref_narration,
		 acc_tran.acctran_dbamt,
		 acc_tran.acctran_cramt,
 		acc_tran.acctran_totamt,
		massal_customer.cust_code,
	  	acc_trail.acctrail_inv_no,
		acc_trail.acctrail_inv_date,cust_name , 
        acctran_serialno
	from 	acc_ref,
		acc_tran,
		acc_trail,
		massal_customer
	where 	acc_ref.accref_seqno 		= 	acc_tran.acctran_accref_seqno and
		acc_tran.acctran_accref_seqno 	= 	acc_trail.acctrail_accref_seqno and 
		acc_tran.acctran_led_code 	= 	massal_customer.cust_code and 
		acc_ref.accref_vou_type in  ('PLW','PIW','PWP') and
		acc_ref.accref_voudate 		>= 	fromdate and 
		acc_ref.accref_voudate 		<= 	todate and
        acctran_cramt > 0 and acctran_led_code <> 1859 and 
		acc_ref.accref_comp_code	=	compcode;
else
    if voutype = 'PUR' then
	select distinct
		acc_ref.accref_seqno,
		acc_ref.accref_vouno,
		acc_ref.accref_vou_type,
		acc_ref.accref_voudate,
		acc_ref.accref_narration,
		 acc_tran.acctran_dbamt,
		 acc_tran.acctran_cramt,
 		acc_tran.acctran_totamt,
		massal_customer.cust_code,
	  	acc_trail.acctrail_inv_no,
		acc_trail.acctrail_inv_date,cust_name , 
        acctran_serialno
	from 	acc_ref,
		acc_tran,
		acc_trail,
		massal_customer
	where 	acc_ref.accref_seqno 		= 	acc_tran.acctran_accref_seqno and
		acc_tran.acctran_accref_seqno 	= 	acc_trail.acctrail_accref_seqno and 
		acc_tran.acctran_led_code 	= 	massal_customer.cust_code and 
		acc_ref.accref_vou_type in  ('PDE','PFU','PGS','PIC','PIW','PWP')  and
		acc_ref.accref_voudate 		>= 	fromdate and 
		acc_ref.accref_voudate 		<= 	todate and
        acctran_cramt > 0 and acctran_led_code <> 1859 and 
		acc_ref.accref_comp_code	=	compcode;
 else
 	select distinct
		acc_ref.accref_seqno,
		acc_ref.accref_vouno,
		acc_ref.accref_vou_type,
		acc_ref.accref_voudate,
		acc_ref.accref_narration,
		 acc_tran.acctran_dbamt,
		 acc_tran.acctran_cramt,
 		acc_tran.acctran_totamt,
		massal_customer.cust_code,
	  	acc_trail.acctrail_inv_no,
		acc_trail.acctrail_inv_date,cust_name , 
        acctran_serialno
	from 	acc_ref,
		acc_tran,
		acc_trail,
		massal_customer
	where 	acc_ref.accref_seqno 		= 	acc_tran.acctran_accref_seqno and
		acc_tran.acctran_accref_seqno 	= 	acc_trail.acctrail_accref_seqno and 
		acc_tran.acctran_led_code 	= 	massal_customer.cust_code and 
		acc_ref.accref_vou_type  = voutype  and
		acc_ref.accref_voudate 		>= 	fromdate and 
		acc_ref.accref_voudate 		<= 	todate and
        acctran_cramt > 0 and acctran_led_code <> 1859 and 
		acc_ref.accref_comp_code	=	compcode;
 end if;
 end if;

END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
