CREATE DEFINER=`root`@`localhost` PROCEDURE `acc_sp_trn_selacc_debit_billdetails`(

	compcode	tinyint,
	finid		tinyint,
	ledcode 	integer

)
select 	

		acctrail_accref_seqno,
		acctrail_inv_no,
		accref_vou_type,
		acctrail_inv_date,
		acctrail_inv_value,
		acctrail_adj_value 
	from 	acc_trail,
          	acc_ref

	where 	acc_ref.accref_seqno 		= 	acc_trail.acctrail_accref_seqno  and
  		acc_trail.acctrail_accref_seqno = 	acc_ref.accref_seqno and 
		acc_ref.accref_comp_code 	= 	compcode and
		acc_ref.accref_finid 		= 	finid and
	    acc_ref.accref_vou_type in ('GSI','PU','EXP','ES','EC','OPB' ) and
		acc_trail.acctrail_led_code	= 	ledcode ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
