DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `acc_sp_trn_selacc_payment_billdetails`(
	compcode	tinyint,
	finid		tinyint,
	ledcode 	integer
)
select 
            acc_ref.accref_seqno,
            acc_ref.accref_vou_type,
            acc_ref.accref_vouno,
            DATE_FORMAT(acc_ref.accref_voudate, '%Y-%m-%d') AS accref_voudate,
            acc_ref.accref_comp_code,
            acc_ref.accref_finid,
            acc_trail.acctrail_inv_no,
		     acctrail_crdays , 
            DATE_FORMAT(acc_trail.acctrail_inv_date, '%Y-%m-%d') AS acctrail_inv_date,
            acc_trail.acctrail_inv_value,
            acc_trail.acctrail_adj_value,acctrail_led_code , cust_ref,acctrail_amtmode

    FROM
        acc_ref
    INNER JOIN acc_trail ON acc_ref.accref_seqno = acc_trail.acctrail_accref_seqno
	INNER JOIN massal_customer ON cust_code = acctrail_led_code
    WHERE
        acc_ref.accref_comp_code = compcode
            AND acc_ref.accref_finid <= finid
--            AND acc_ref.accref_vou_type NOT IN ('OPB' , 'UB', '', 'CA', 'CIP', 'DNG', 'DNN')
            and  acc_trail.acctrail_inv_value >  acc_trail.acctrail_adj_value
            AND acc_trail.acctrail_led_code = ledcode 
            AND acctrail_amtmode = "C"
ORDER BY acctrail_inv_date,acctrail_inv_no ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `acc_sp_trn_selacc_receipt_billdetails` */;
