CREATE DEFINER=`root`@`%` PROCEDURE `acc_sp_trn_selbilladjustment_payment`(  
	ledcode 	integer,  
	compcode 	tinyint  
)
select 	

		acctrail_accref_seqno, accref_vouno ,
		acctrail_inv_no,
		accref_vou_type,
		acctrail_inv_date,
		acctrail_inv_value,
		acctrail_adj_value ,acctrail_amtmode
	from 	acc_trail,
          	acc_ref
	where 	acc_ref.accref_seqno 		= 	acc_trail.acctrail_accref_seqno  and
  		acc_trail.acctrail_accref_seqno = 	acc_ref.accref_seqno and 
		acc_ref.accref_comp_code 	= 	compcode and
	    acctrail_amtmode = "D"  and acctrail_inv_value > acctrail_adj_value  and accref_vou_type in ('BKP','GJV','DNG','DNN','CHP') and
		acc_trail.acctrail_led_code	= 	ledcode  order by acctrail_inv_date,accref_vouno ;;
DELIMITER ;
