CREATE DEFINER=`root`@`localhost` PROCEDURE `acc_sp_trn_selcurbalance_paymentled`(	

	compcode	tinyint,

	finyear	tinyint,

	ledgercode	integer

)
select

		sum(obcredit)-sum(debit)+sum(credit) as curbalcr,

		sum(obdebit)+sum(debit)-sum(credit)  as curbaldb

	from

	(

	select 

		sum(atn.acctran_dbamt) 		as debit, 

		sum(atn.acctran_cramt) 		as credit,

		0 as obdebit,

		0 as obcredit

	from 	acc_ref arf, 

		    acc_tran atn

	where 	arf.accref_comp_code 	= 	compcode and 

		arf.accref_finid	<=	finyear and 

		arf.accref_vou_type not in ('OB','UB','BA','PP','PR','PT') and

		arf.accref_seqno 	= 	atn.acctran_accref_seqno and 

		atn.acctran_led_code 	= 	ledgercode	

	group by 	year(arf.accref_voudate)

	union

	select 

		0 as debit,

		0 as credit,

		sum(curbal_obdbamt) as obdebit,

		sum(curbal_obcramt) as obcredit

	from acc_current_balance 

	where 	curbal_finid 	=	finyear and 

		curbal_led_code in 

		( 

			select 

				led_code 

			from 	acc_ledger_master 

			where 	led_comp_code 	= 	compcode and 

				led_code = ledgercode

		)

	)x ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
