/*!50003 DROP PROCEDURE IF EXISTS `acc_sp_trn_selob_billdetails_balance` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `acc_sp_trn_selob_billdetails_balance`(

	compcode	tinyint,

	finid		tinyint,

	ledcode 	integer

)
select     

		a.*, b.*

	from         

	(

		select * from acc_ob_billdetails 

	where 	ob_comp_code 	= 	compcode and

		ob_fin_id 	>=11 and 

		ob_adjamt 	< 	ob_totamt  and

		ob_led_code 	= 	ledcode)a 

		 LEFT OUTER JOIN

	(

		SELECT     

			acctrail_inv_value AS dbcr_invvalue, 

			acctrail_adj_value AS dbcr_adjvalue, 

			acc_tran.acctran_led_code AS dbcr_ledcode, 

                        acc_trail.acctrail_inv_no AS dbcr_invno, 

			acc_trail.acctrail_inv_date AS dbcr_invdate, 

			acc_ref.accref_comp_code AS dbcr_compcode, 

                        acc_ref.accref_finid AS dbcr_finid

                from          

			acc_trail, 

			acc_tran, 

			acc_ref

                where      

			acc_ref.accref_seqno = acc_tran.acctran_accref_seqno AND 

			acc_tran.acctran_accref_seqno = acc_trail.acctrail_accref_seqno AND 

                        acc_trail.acctrail_accref_seqno = acc_ref.accref_seqno AND 

			acc_ref.accref_comp_code = compcode AND 

			acc_ref.accref_finid >= finid AND 

                        acc_ref.accref_vou_type = 'CN' AND 

			acc_tran.acctran_led_code = ledcode) b 

	ON 

		a.ob_ref_date = b.dbcr_invdate AND 

                a.ob_comp_code = b.dbcr_compcode AND 

		a.ob_fin_id = b.dbcr_finid AND 

		a.ob_ref_no = b.dbcr_invno

	order by a.ob_ref_date ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
