CREATE DEFINER=`root`@`localhost` PROCEDURE `acc_sp_trn_selvoucher_no`(
	accreffinid		tinyint,
	accrefcomp_code	tinyint,
	accrefvou_type	varchar(3)

)
select 

		accref_seqno,
		accref_vouno 
	from  	acc_ref
	where	accref_vou_type = 	accrefvou_type  and
		accref_finid 		= 	accreffinid and
		accref_comp_code 	= 	accrefcomp_code
	    order by convert(substring(accref_vouno,5),signed) desc ;;
