CREATE DEFINER=`root`@`%` PROCEDURE `acc_sp_trn_updcurbal_recpay_seqno`(
acc_type  varchar(3),  
recpay_seqno integer,  
led_code integer,  
fin_id  tinyint,
compcode  tinyint 
)
BEGIN
if acc_type = 'REC'  then
 update  acc_current_balance   
 set  curbal_rec_seqno  =  recpay_seqno  
 where  curbal_led_code  =  led_code  and curbal_comp_code = compcode and curbal_finid = fin_id;  
 
else if acc_type = 'PAY' then

 update  acc_current_balance   
 set  curbal_pay_seqno  =  recpay_seqno  
 where  curbal_led_code  =  led_code   and curbal_comp_code = compcode and   
  curbal_finid   =  fin_id;
end if;
end if;
END ;;
DELIMITER ;
