DELIMITER ;;
CREATE DEFINER=`root`@`%` PROCEDURE `OLDaccspreptrialbalance`(

finid int,

compcode int,

fromdate date,

todate date

)
BEGIN

select 

acctran_led_code,led_name,sum(Obdebit) as curbal_obdbamt,sum(Obcredit) as curbal_obcramt,sum(debit) as debit,

sum(credit) as credit,sum(Obdebit)-sum(Obcredit)+sum(debit)-sum(credit) as closing,

fn_GetParentgroup(grpcode,compcode,0,'C') as grp,fn_GetParentgroup(grpcode,compcode,0,'N') as grp0, fn_GetParentgroup(grpcode,compcode,1,'N') as grp1,

fn_GetParentgroup(grpcode,compcode,2,'N') as grp2,fn_GetParentgroup(grpcode,compcode,3,'N') as grp3,

fn_GetParentgroup(grpcode,compcode,4,'N') as grp4

from

 (

 -- select  led_name,led_grp_code as grpcode, 1 as accref_comp_code,curbal_finid as accref_finid,
select  led_name,led_grp_code as grpcode, curbal_comp_code as accref_comp_code,curbal_finid as accref_finid,
curbal_led_code as acctran_led_code,curbal_obdbamt as Obdebit, curbal_obcramt as Obcredit,

0 as debit,0 as credit 

from acc_current_balance,acc_ledger_master where 

curbal_finid=finid and (curbal_obdbamt+curbal_obcramt)>0 and curbal_led_code = led_code

-- and led_comp_code=compcode 
and curbal_comp_code=compcode 
union all 

 select led_name,led_grp_code as grpcode,accref_comp_code,accref_finid,acctran_led_code,

0 as Obdebit, 0 as Obcredit,

acctran_dbamt as debit,acctran_cramt as credit 

from acc_ref,acc_tran,acc_ledger_master where 

accref_comp_code=compcode and accref_seqno = acctran_accref_seqno and

accref_finid= finid and

accref_voudate>=fromdate and accref_voudate<=todate and 

acctran_led_code = led_code

) tt

group by acctran_led_code 

order by grp,led_name;

END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
