CREATE DEFINER=`root`@`%` PROCEDURE `OLDsprep_despatchpending`(compcode int ,fincode int  , IN sono varchar(100) ,opt int)
BEGIN
if opt = 1 then
set @qry = '
select * from trnsal_finish_stock , trnsal_order_header , massal_customer,
massal_variety , masprd_variety ,masprd_type
where
stk_comp_code = ordh_comp_code and 
stk_finyear <= ordh_fincode and
stk_sono = ordh_sono and 
ordh_party = cust_code and stk_destag = '' and
stk_var_code = var_code and
var_grpcode = var_groupcode  and
vargrp_type_code = var_typecode and
stk_comp_code = 1 and stk_finyear <= 22 and ';
set @qry = concat(@qry,' stk_sono in  (',sono,')');
prepare stmt from @qry;
execute stmt;
deallocate prepare stmt;
else
select * from trnsal_finish_stock , trnsal_order_header , massal_customer,
massal_variety , masprd_variety ,masprd_type
where
stk_comp_code = ordh_comp_code and
stk_finyear <= ordh_fincode and
stk_sono = ordh_sono and 
ordh_party = cust_code and stk_destag = '' and
stk_var_code = var_code and
var_grpcode = var_groupcode  and
vargrp_type_code = var_typecode and
stk_comp_code = compcode  and stk_finyear <= fincode;
end if;

END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `spacc_anna` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`%` PROCEDURE `spacc_anna`(
    IN compcode INT,
    IN fromdate DATE,
    IN todate DATE,
    IN ledcode INT,
    IN repopt VARCHAR(1),
    IN agedays1 INT,
    IN agedays2 INT,
    IN agedays3 INT,
    IN agedays4 INT
)
BEGIN

SELECT *,
    CASE WHEN oddays <= agedays1 THEN acctrail_inv_value - acctrail_adj_value + adjamt ELSE 0 END AS Agegrp1,
    CASE WHEN oddays > agedays1 AND oddays <= agedays2 THEN acctrail_inv_value - acctrail_adj_value + adjamt ELSE 0 END AS Agegrp2,
    CASE WHEN oddays > agedays2 AND oddays <= agedays3 THEN acctrail_inv_value - acctrail_adj_value + adjamt ELSE 0 END AS Agegrp3,
    CASE WHEN oddays > agedays3 AND oddays <= agedays4 THEN acctrail_inv_value - acctrail_adj_value + adjamt ELSE 0 END AS Agegrp4,
    CASE WHEN oddays > agedays4 THEN acctrail_inv_value - acctrail_adj_value + adjamt ELSE 0 END AS Agegrp5
FROM (

    SELECT accref_seqno, grp_name, grp_code, cust_name, acctrail_led_code, accref_vouno,
           acctrail_inv_no, acctrail_inv_date,
           MAX(acctrail_inv_value) AS acctrail_inv_value,
           MAX(acctrail_adj_value - adjamt) AS acctrail_adj_value,
           MAX(acctrail_crdays) AS acctrail_crdays,
           duedate, oddays, acctrail_amtmode, accref_voudate,
           SUM(adjamt) AS adjamt
    FROM (

        SELECT accref_seqno, grp_name, grp_code, cust_name, acctrail_led_code, accref_vouno,
               acctrail_inv_no, acctrail_inv_date,
               MAX(acctrail_inv_value) AS acctrail_inv_value,
               MAX(acctrail_adj_value) AS acctrail_adj_value,
               MAX(acctrail_crdays) AS acctrail_crdays,
               duedate, oddays, acctrail_amtmode, accref_voudate,
               SUM(adjamt) AS adjamt
        FROM (

            -- ==========================
            -- Main invoice data
            -- ==========================
            SELECT ref.accref_seqno, grp.grp_name, grp.grp_code, mas.cust_name, trail.acctrail_led_code,
                   ref.accref_vouno, trail.acctrail_inv_no, trail.acctrail_inv_date,
                   trail.acctrail_inv_value, trail.acctrail_adj_value, trail.acctrail_crdays,
                   DATE_FORMAT(DATE_ADD(ref.accref_voudate, INTERVAL trail.acctrail_crdays DAY), '%d-%m-%Y') AS duedate,
                   DATEDIFF(todate, DATE_ADD(ref.accref_voudate, INTERVAL trail.acctrail_crdays DAY)) AS oddays,
                   trail.acctrail_amtmode, ref.accref_voudate,
                   0 AS adjamt
            FROM acc_ref ref
            LEFT JOIN acc_trail trail ON ref.accref_seqno = trail.acctrail_accref_seqno
            JOIN massal_customer mas ON trail.acctrail_led_code = mas.cust_code and case when repopt = 'P' then trail.acctrail_led_code = ledcode end
            JOIN acc_group_master grp ON mas.cust_acc_group = grp.grp_code
            JOIN acc_group_master maingrp ON grp.grp_code = maingrp.grp_code  and case when repopt = 'G' then   mas.cust_acc_group = ledcode end
            AND maingrp.grp_code IN (SELECT grp_code FROM acc_group_master WHERE grp_parent_code = 51)
            WHERE trail.acctrail_inv_value > trail.acctrail_adj_value
              AND mas.cust_type != 'G'
              AND ref.accref_comp_code = compcode
              AND ref.accref_voudate <= todate


            UNION ALL

            -- ==========================
            -- Adjustments data
            -- ==========================
            SELECT adj.ref_adjseqno AS accref_seqno, grp.grp_name, grp.grp_code, mas.cust_name, trail.acctrail_led_code,
                   adj.ref_adjvouno AS accref_vouno, trail.acctrail_inv_no, trail.acctrail_inv_date,
                   trail.acctrail_inv_value, trail.acctrail_adj_value, trail.acctrail_crdays,
                   DATE_FORMAT(DATE_ADD(ref2.accref_voudate, INTERVAL trail.acctrail_crdays DAY), '%d-%m-%Y') AS duedate,
                   DATEDIFF(todate, DATE_ADD(ref2.accref_voudate, INTERVAL trail.acctrail_crdays DAY)) AS oddays,
                   trail.acctrail_amtmode, ref2.accref_voudate,
                   adj.ref_adjamount AS adjamt
            FROM acc_adjustments adj
            LEFT JOIN acc_trail trail ON adj.ref_adjseqno = trail.acctrail_accref_seqno
            JOIN massal_customer mas ON trail.acctrail_led_code = mas.cust_code  and case when repopt = 'P' then trail.acctrail_led_code = ledcode end 
            JOIN acc_group_master grp ON mas.cust_acc_group = grp.grp_code
            JOIN acc_group_master maingrp ON grp.grp_code = maingrp.grp_code 
                AND maingrp.grp_code IN (SELECT grp_code FROM acc_group_master WHERE grp_parent_code = 51)
            JOIN acc_ref ref2 ON ref2.accref_seqno = trail.acctrail_accref_seqno
                              AND trail.acctrail_led_code = adj.ref_ledcode
            WHERE adj.ref_compcode = compcode
              AND ref2.accref_voudate <= todate
              AND (adj.ref_docdate > todate OR adj.ref_adjvoudate > todate)

        ) AS a1
        GROUP BY accref_seqno, grp_name, grp_code, cust_name, acctrail_led_code,
                 accref_vouno, acctrail_inv_no, acctrail_inv_date, duedate, oddays,
                 acctrail_amtmode, accref_voudate

    ) AS a2
    GROUP BY accref_seqno, grp_name, grp_code, cust_name, acctrail_led_code,
             accref_vouno, acctrail_inv_no, acctrail_inv_date, duedate, oddays,
             acctrail_amtmode, accref_voudate

) AS ab1



ORDER BY accref_voudate ASC, acctrail_inv_no;

END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
