/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`%` PROCEDURE `spacc_GSTR_2B`(rmonth int, ryear int, compcode tinyint,fromdate date,todate date)
BEGIN

 delete from GSTR_2B where gst_2b_month = rmonth and  gst_2b_year = ryear and  accrefno >0;
 
insert into GSTR_2B 

 select rmonth,ryear,rech_acc_seqno  accrefno , cust_ref, cust_gstin,  rech_no vouno, rech_date voudate, rech_billno billno,
rech_billdate billdate, rech_totalamount  invamt, rech_itemvalue  taxable  , rech_cgst_amt cgstamt,
 rech_sgst_amt sgstamt, rech_igst_amt igstamt, 0 cessamt,0,0,0,0,0,0 from trnrm_receipt_header,
massal_customer where rech_sup_code = cust_code and rech_compcode = 1 and rech_date between  fromdate and  todate and rech_cgst_amt+rech_sgst_amt+rech_igst_amt > 0


 union all
 
 
select rmonth,ryear,rech_acc_seqno  accrefno , cust_ref, cust_gstin,  rech_no vouno, rech_date voudate, rech_billno billno,
rech_billdate billdate, rech_totalamount  invamt, rech_itemvalue  taxable  , rech_cgst_amt cgstamt,
 rech_sgst_amt sgstamt, rech_igst_amt igstamt, rech_cess_amount cessamt,0,0,0,0,0,0  from trnfu_receipt_header,
massal_customer where rech_sup_code = cust_code and rech_compcode = 1 and rech_date between  fromdate and  todate  and rech_cgst_amt+rech_sgst_amt+rech_igst_amt > 0


 union all
 

 select rmonth,ryear,minh_acc_seqno  accrefno , cust_ref, cust_gstin, minh_minno vouno,minh_mindate voudate,minh_bill_no as billno,
 minh_bill_date billdate, max(minh_value) as invamt,  sum(mint_value) taxable,  sum(mint_cgst_amt) cgstamt,  sum(mint_sgst_amt) sgstamt,  sum(mint_igst_amt) igstamt , 0 cessamt ,0,0,0,0,0,0 
 from trnpur_min_header h, trnpur_min_trailer t, massal_customer c ,maspur_item_header i , mas_uom u where 
mint_item_code = item_code and item_uom = uom_code  and
minh_sup_code = cust_code and minh_comp_code = mint_comp_code and  minh_fin_code = mint_fin_code and minh_minno = mint_minno
and minh_comp_code = 1 and minh_mindate between fromdate and  todate  and mint_cgst_amt+mint_sgst_amt+mint_igst_amt > 0
 group by minh_acc_seqno , cust_ref, cust_gstin,minh_minno,minh_mindate, minh_bill_no,minh_bill_date


union all

 select rmonth,ryear,eh_seqno  accrefno , cust_ref, cust_gstin,
 eh_expvouno vouno , eh_voudate voudate, 
 eh_refno as billno ,  eh_refdate billdate, 
 eh_totalamount as invamt,
 eh_taxable taxable , eh_cgstamount cgstamt, eh_sgstamount sgstamt , eh_igstamount igstamt , 0 cessamt ,0,0,0,0,0,0  from acc_expenses_header,massal_customer where 
 eh_compcode = 1 and  eh_voudate between fromdate and  todate and eh_partycode = cust_code
 and eh_cgstamount+eh_sgstamount+eh_igstamount > 0 
 union all
 
 select 
rmonth,ryear,
accrefno,  cust_ref, cust_gstin, vouno, voudate, billno, billdate, 
sum(invamt) invamt, sum(taxable) taxable, sum(cgstamt) cgstamt, sum(sgstamt) sgstamt, sum(igstamt) igstamt, sum(cessamT) cessamt ,0,0,0,0,0,0 from
(
select   'S'  ledtype,  accref_seqno accrefno, cust_ref, cust_gstin, accref_vouno vouno , accref_voudate voudate, accref_payref_no billno, accref_payref_date billdate, acctran_totamt invamt, 0 taxable,0  cgstamt,0 sgstamt,0  igstamt , 0 cessamt
from acc_ref ,  acc_tran , massal_customer  where accref_seqno = acctran_accref_seqno and  acctran_led_code = cust_code 
and accref_vou_type in ('GJV','CHP') and  accref_comp_code = 1 and accref_voudate between fromdate and todate and cust_code !=1859 and  accref_seqno in 
(
select accref_seqno acseqno from acc_ref ,  acc_tran , massal_customer where accref_seqno = acctran_accref_seqno 
and accref_vou_type in ('GJV','CHP') and  accref_comp_code = 1 and  accref_voudate between fromdate and todate and  acctran_led_code = cust_code and cust_acc_group = 46
group by accref_seqno
)and cust_type = 'S' 

union all




select 'S'  ledtype, 
accrefno,  cust_ref, cust_gstin, vouno, voudate, billno, billdate, 
sum(invamt) invamt, sum(taxable) taxable, sum(cgstamt) cgstamt, sum(sgstamt) sgstamt, sum(igstamt) igstamt, sum(cessamT) cessamt
 from (

select   
    accref_seqno accrefno,  accref_vouno vouno , accref_voudate voudate, accref_payref_no billno, accref_payref_date billdate, 0 invamt,
  max(acctran_totamt)  taxable,0  cgstamt,0 sgstamt,0  igstamt , 0 cessamt
from acc_ref ,  acc_tran , massal_customer  where accref_seqno = acctran_accref_seqno and  acctran_led_code = cust_code 
and accref_vou_type in ('GJV','CHP') and  accref_comp_code = 1 and  accref_voudate between fromdate and todate and cust_code !=1859 and  accref_seqno in 
(
select accref_seqno acseqno from acc_ref ,  acc_tran , massal_customer where accref_seqno = acctran_accref_seqno 
and accref_vou_type in ('GJV','CHP') and  accref_comp_code = 1 and  accref_voudate between fromdate and todate and  acctran_led_code = cust_code and cust_acc_group = 46
group by accref_seqno
)and cust_type = 'G' and cust_acc_group != 46
 group by accref_seqno,accref_vouno, accref_vouno ,accref_voudate,accref_payref_no,accref_payref_date
 
 union all
  
  select 
  accrefno, vouno, voudate, billno, billdate, sum(invamt) invamt, sum(taxable) taxable, sum(cgstamt) cgstamt, sum(sgstamt) sgstamt, sum(igstamt) igstamt, 0 cessamt
  from (
select accref_seqno accrefno, cust_ref, accref_vouno vouno , accref_voudate voudate, accref_payref_no billno, accref_payref_date billdate, 0 invamt,  0 taxable,
   case when cust_ref like '%INP%CGST%' then   max(acctran_totamt) else 0 end as cgstamt,
   case when cust_ref like '%INP%SGST%' then   max(acctran_totamt) else 0 end as sgstamt,
   case when cust_ref like '%INP%IGST%' then  max(acctran_totamt) else 0 end as igstamt 
from acc_ref ,  acc_tran , massal_customer  where accref_seqno = acctran_accref_seqno and  acctran_led_code = cust_code 
and accref_vou_type in ('GJV','CHP') and  accref_comp_code = 1 and  accref_voudate between fromdate and todate and cust_code !=1859 and  accref_seqno in 
(
select accref_seqno acseqno from acc_ref ,  acc_tran , massal_customer where accref_seqno = acctran_accref_seqno 
and accref_vou_type in ('GJV','CHP') and  accref_comp_code = 1 and  accref_voudate between fromdate and todate and  acctran_led_code = cust_code and cust_acc_group = 46
group by accref_seqno
)and cust_type = 'G' and cust_acc_group = 46
 group by accref_seqno , cust_ref, accref_vouno ,accref_voudate,accref_payref_no,accref_payref_date
) a1  group by accrefno, vouno, voudate, billno, billdate

) jv1 , acc_tran , massal_customer  where accrefno = acctran_accref_seqno and  acctran_led_code = cust_code and cust_type != 'G'
group by accrefno,  cust_ref, cust_gstin, vouno, voudate, billno, billdate
) jv2  where cgstamt+sgstamt+igstamt > 0  group by accrefno,  cust_ref, cust_gstin, vouno, voudate, billno, billdate order by  cust_gstin, voudate,billdate;

select * from GSTR_2B where gst_2b_month = rmonth and  gst_2b_year = ryear and  accrefno >0 order by cust_gstin,voudate;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `spacc_GSTR_2B_Excess` */;
