CREATE DEFINER=`root`@`%` PROCEDURE `spacc_GSTR_2B_NotTallied_List`(rmonth int, ryear int)
BEGIN
-- select * from GSTR_2B where  gst_2b_month = rmonth and  gst_2b_year = ryear and  ( invamt <> gst_2b_invamt or  taxable <> gst_2b_taxable  or  cgstamt <> gst_2b_cgstamt or  sgstamt <> gst_2b_sgstamt or igstamt  <> gst_2b_igstamt or cessamt <> gst_2b_cessamt);

select * from GSTR_2B where  gst_2b_month = rmonth and  gst_2b_year = ryear and  (cgstamt <> gst_2b_cgstamt or  sgstamt <> gst_2b_sgstamt or igstamt  <> gst_2b_igstamt or cessamt <> gst_2b_cessamt ) order by cust_ref,voudate,billno;


END ;;
