CREATE DEFINER=`root`@`%` PROCEDURE `spacc_morethan90dayslist`()
BEGIN
  -- select repr_name , cust_ref  from overdue_custlist ,  massal_customer ,massal_repr where c_code = cust_code and cust_repr = repr_code  order by  repr_name , cust_ref;  
  select repr_name , cust_ref  from massal_customer ,massal_repr where  cust_repr = repr_code  and cust_lock = 'Y' order by  repr_name , cust_ref;  
