CREATE DEFINER=`root`@`%` PROCEDURE `spacc_rep_amount_pending`(compcode int,fincode int,voutype varchar(3))
BEGIN
select accref_seqno,  accref_voudate , accref_vouno,cust_ref, acctrail_inv_value ,acctrail_adj_value , acctrail_inv_value -acctrail_adj_value balance from acc_ref , acc_trail , massal_customer where  acctrail_led_code = cust_code and acctrail_accref_seqno = accref_seqno and   accref_comp_code = compcode and accref_finid = fincode and accref_vou_type = voutype and acctrail_inv_value > acctrail_adj_value;
END ;;
DELIMITER ;
