DELIMITER ;;
CREATE DEFINER=`root`@`%` PROCEDURE `spacc_rep_ARagewise`(compcode varchar(10), finid tinyint,asondate date,ptype varchar(1),partycode varchar(500) )
BEGIN
if ptype = "A" then
	select  invh_party,dealer_name,q3.cust_ref, seqno , invno,  invdate,ledcode,sum(invamt) as invamt , sum(adjamt) as adjamt ,sum(preadj) as preadj , amtmode,invh_crd_days
	from 
	(
	 select acctrail_accref_seqno seqno , acctrail_inv_no invno, acctrail_inv_date invdate, acctrail_inv_value invamt, acctrail_adj_value adjamt, acctrail_led_code ledcode, acctrail_amtmode amtmode,0 as preadj
	 from acc_trail , acc_ref where acctrail_amtmode = "D" and  accref_seqno = acctrail_accref_seqno and   acctrail_inv_date <= asondate and  FIND_IN_SET(accref_comp_code, compcode)  and accref_finid  <= finid
	 
	 union all
	 
	 select acctrail_accref_seqno seqno , acctrail_inv_no invno, acctrail_inv_date invdate,  0 as invamt , 0  as adjamt, acctrail_led_code ledcode, acctrail_amtmode amtmode,recpay_amount as preadj from acc_ref a, acc_recpay_tran b , acc_trail c  where
	  acctrail_amtmode = "D" and  accref_seqno = acctrail_accref_seqno  and FIND_IN_SET(accref_comp_code, compcode)  and accref_finid  <= finid and  acctrail_accref_seqno = recpay_oaccref_seqno and accref_voudate <= asondate and recadjdate > asondate 
	  union all
	 select acctrail_accref_seqno seqno , acctrail_inv_no invno, acctrail_inv_date invdate,  0 as invamt , 0  as adjamt, acctrail_led_code ledcode, acctrail_amtmode amtmode,recpay_amount as preadj from acc_ref a, acc_recpay_tran b , acc_trail c  where
	  acctrail_amtmode = "D" and  accref_seqno = acctrail_accref_seqno and 
	 acctrail_accref_seqno = recpay_aaccref_seqno and accref_voudate <= asondate and recadjdate > asondate  and FIND_IN_SET(accref_comp_code, compcode)  and accref_finid  <= finid
	 
	 ) q1 , trnsal_invoice_header q2 , massal_customer q3 ,mas_dealer q4  ,  massal_repr q5  where 
	 q1. seqno = q2.invh_acc_refno and q2.invh_party =  q3.cust_code and q3.cust_dealer = q4.dealer_code   and q3.cust_repr = q5.repr_code
	 group by  invh_party,dealer_name,q3.cust_ref, seqno , invno,  invdate,ledcode, amtmode,invh_crd_days   having invamt-adjamt+preadj > 0 order by  dealer_name,q3.cust_ref, seqno , invno ;

elseif ptype = "G" then
	select  invh_party,dealer_name,q3.cust_ref, seqno , invno,  invdate,ledcode,sum(invamt) as invamt , sum(adjamt) as adjamt ,sum(preadj) as preadj , amtmode,invh_crd_days
	from 
	(
	 select acctrail_accref_seqno seqno , acctrail_inv_no invno, acctrail_inv_date invdate, acctrail_inv_value invamt, acctrail_adj_value adjamt, acctrail_led_code ledcode, acctrail_amtmode amtmode,0 as preadj
	 from acc_trail , acc_ref where acctrail_amtmode = "D" and  accref_seqno = acctrail_accref_seqno and   acctrail_inv_date <= asondate and  FIND_IN_SET(accref_comp_code, compcode)  and accref_finid  <= finid
	 
	 union all
	 
	 select acctrail_accref_seqno seqno , acctrail_inv_no invno, acctrail_inv_date invdate,  0 as invamt , 0  as adjamt, acctrail_led_code ledcode, acctrail_amtmode amtmode,recpay_amount as preadj from acc_ref a, acc_recpay_tran b , acc_trail c  where
	  acctrail_amtmode = "D" and  accref_seqno = acctrail_accref_seqno  and FIND_IN_SET(accref_comp_code, compcode)  and accref_finid  <= finid and  acctrail_accref_seqno = recpay_oaccref_seqno and accref_voudate <= asondate and recadjdate > asondate 
	  union all
	 select acctrail_accref_seqno seqno , acctrail_inv_no invno, acctrail_inv_date invdate,  0 as invamt , 0  as adjamt, acctrail_led_code ledcode, acctrail_amtmode amtmode,recpay_amount as preadj from acc_ref a, acc_recpay_tran b , acc_trail c  where
	  acctrail_amtmode = "D" and  accref_seqno = acctrail_accref_seqno and 
	 acctrail_accref_seqno = recpay_aaccref_seqno and accref_voudate <= asondate and recadjdate > asondate  and FIND_IN_SET(accref_comp_code, compcode)  and accref_finid  <= finid
	 
	 ) q1 , trnsal_invoice_header q2 , massal_customer q3 ,mas_dealer q4  ,  massal_repr q5  where 
	 q1. seqno = q2.invh_acc_refno and q2.invh_party =  q3.cust_code and q3.cust_dealer = q4.dealer_code   and q3.cust_repr = q5.repr_code
     and find_in_set(cust_dealer,partycode)
	 group by  invh_party,dealer_name,q3.cust_ref, seqno , invno,  invdate,ledcode, amtmode,invh_crd_days   having invamt-adjamt+preadj > 0 order by  dealer_name,q3.cust_ref, seqno , invno ;
     
     
     
elseif ptype = "P" then
	select  invh_party,dealer_name,q3.cust_ref, seqno , invno,  invdate,ledcode,sum(invamt) as invamt , sum(adjamt) as adjamt ,sum(preadj) as preadj , amtmode,invh_crd_days
	from 
	(
	 select acctrail_accref_seqno seqno , acctrail_inv_no invno, acctrail_inv_date invdate, acctrail_inv_value invamt, acctrail_adj_value adjamt, acctrail_led_code ledcode, acctrail_amtmode amtmode,0 as preadj
	 from acc_trail , acc_ref where acctrail_amtmode = "D" and  accref_seqno = acctrail_accref_seqno and   acctrail_inv_date <= asondate and  FIND_IN_SET(accref_comp_code, compcode)  and accref_finid  <= finid
	 
	 union all
	 
	 select acctrail_accref_seqno seqno , acctrail_inv_no invno, acctrail_inv_date invdate,  0 as invamt , 0  as adjamt, acctrail_led_code ledcode, acctrail_amtmode amtmode,recpay_amount as preadj from acc_ref a, acc_recpay_tran b , acc_trail c  where
	  acctrail_amtmode = "D" and  accref_seqno = acctrail_accref_seqno  and FIND_IN_SET(accref_comp_code, compcode)  and accref_finid  <= finid and  acctrail_accref_seqno = recpay_oaccref_seqno and accref_voudate <= asondate and recadjdate > asondate 
	  union all
	 select acctrail_accref_seqno seqno , acctrail_inv_no invno, acctrail_inv_date invdate,  0 as invamt , 0  as adjamt, acctrail_led_code ledcode, acctrail_amtmode amtmode,recpay_amount as preadj from acc_ref a, acc_recpay_tran b , acc_trail c  where
	  acctrail_amtmode = "D" and  accref_seqno = acctrail_accref_seqno and 
     	 acctrail_accref_seqno = recpay_aaccref_seqno and accref_voudate <= asondate and recadjdate > asondate  and FIND_IN_SET(accref_comp_code, compcode)  and accref_finid  <= finid
	 
	 ) q1 , trnsal_invoice_header q2 , massal_customer q3 ,mas_dealer q4  ,  massal_repr q5  where 
	 q1. seqno = q2.invh_acc_refno and q2.invh_party =  q3.cust_code and q3.cust_dealer = q4.dealer_code   and q3.cust_repr = q5.repr_code
     and find_in_set(invh_party,partycode) 
	 group by  invh_party,dealer_name,q3.cust_ref, seqno , invno,  invdate,ledcode, amtmode,invh_crd_days   having invamt-adjamt+preadj > 0 order by  dealer_name,q3.cust_ref, seqno , invno ;
     
end if; 
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `spacc_rep_BillAdjustment_Partywise` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`%` PROCEDURE `spacc_rep_BillAdjustment_Partywise`(compcode int,fincode int, fromdate date,todate date ,ledcode int ,drcr varchar(1) )
BEGIN
 select * from (
  select accref_seqno , accref_vouno , accref_voudate ,acctrail_inv_value, acctrail_inv_value-acctrail_adj_value balamt, acctrail_crdays , acctrail_gracedays,cust_ref from acc_ref ref 
 left join acc_trail trail 
 on ref.accref_seqno = trail.acctrail_accref_seqno
 join massal_customer mas
 on trail.acctrail_led_code = mas.cust_code and trail.acctrail_led_code =  ledcode 
 where accref_comp_code = compcode   and accref_finid = fincode  and accref_voudate between fromdate  and todate   and acctrail_amtmode = drcr and accref_vou_type !='GJV' ) ref
 left join (
 
 select ref_adjseqno , ref_docseqno , ref_docno, ref_docdate , ref_adjamount ,ref_adj_days  from acc_adjustments where ref_compcode = compcode and ref_finid = fincode and ref_adjseqno in (
  select accref_seqno  from acc_ref ref 
 left join acc_trail trail 
 on ref.accref_seqno = trail.acctrail_accref_seqno
 join massal_customer mas
 on trail.acctrail_led_code = mas.cust_code and trail.acctrail_led_code =  ledcode 
 where accref_comp_code = compcode   and accref_finid = fincode  and accref_voudate between fromdate  and todate   and acctrail_amtmode = drcr  -- and accref_vou_type !='GJV'
 )
 
 union all
 
 select ref_docseqno ref_adjseqno , ref_adjseqno ref_docseqno , ref_invno ref_docno, ref_invdate ref_docdate , ref_adjamount ,ref_adj_days  from acc_adjustments where ref_compcode = compcode and ref_finid = fincode and ref_docseqno in (
  select ref_docseqno  from acc_ref ref 
 left join acc_trail trail 
 on ref.accref_seqno = trail.acctrail_accref_seqno
 join massal_customer mas
 on trail.acctrail_led_code = mas.cust_code and trail.acctrail_led_code =  ledcode 
 where accref_comp_code = compcode   and accref_finid = fincode  and accref_voudate between fromdate  and todate   and acctrail_amtmode = drcr -- and  accref_vou_type !='GJV'
 
 
 ) 
 
 ) a1
 on  accref_seqno = ref_adjseqno;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
