CREATE DEFINER=`root`@`%` PROCEDURE `spacc_rep_column_report`()
BEGIN
/*
select cust_name, accref_vouno, accref_voudate,acctran_totamt from acc_ref a ,  acc_tran b , massal_customer l   where 
acctran_cramt > 0 and acctran_led_code = cust_code and accref_seqno = acctran_accref_seqno and accref_seqno in (
select accref_seqno from acc_ref ,  acc_tran where accref_seqno = acctran_accref_seqno and  accref_comp_code = 1 
and accref_finid =23 and accref_voudate between "2023-12-01" and "2023-12-31" and  acctran_led_code = 1783);
*/

 select * from (

select * from (
select accref_seqno ,cust_name Main_ledger_name ,accref_vou_type, accref_vouno, accref_voudate,accref_narration,acctran_totamt main_ledger_amt from acc_ref a ,  acc_tran b , massal_customer l   where 
acctran_led_code = cust_code and accref_seqno = acctran_accref_seqno and cust_type = 'G' and acctran_led_code = 1783 and accref_seqno in (
select accref_seqno from acc_ref ,  acc_tran where accref_seqno = acctran_accref_seqno and  accref_comp_code = 1
and accref_finid = 24 and accref_voudate between '2024-04-01' and '2024-04-30'and  acctran_led_code = 1783)  
) a1

join 
 (
select accref_seqno baccref_seqno ,cust_name ledger_name , acctran_totamt as ledgeramt from acc_ref a ,  acc_tran b , massal_customer l   where 
acctran_led_code = cust_code and accref_seqno = acctran_accref_seqno and cust_type = 'G' and acctran_led_code != 1783 and accref_seqno in (
select accref_seqno from acc_ref ,  acc_tran where accref_seqno = acctran_accref_seqno and  accref_comp_code = 1
and accref_finid = 24 and accref_voudate between '2024-04-01' and '2024-04-30'and  acctran_led_code = 1783)  
) b1 on  a1.accref_seqno = b1.baccref_seqno 

 join
(

select invh_acc_refno  accrefno , cust_ref, cust_gstin,  Cast(invh_totwt/1000 as decimal(18,3)) as Qty , invh_netamt as invamt, 'MTS' uom  from trnsal_invoice_header i, massal_customer where invh_party = cust_code and invh_comp_code =  1 and invh_date between '2024-04-01' and '2024-04-30' 
 union all
 select rech_acc_seqno  accrefno , cust_ref, cust_gstin,  Cast(rect_grnqty as decimal(18,3)) as Qty , rech_totalamount as invamt, 'MTS' uom   from trnrm_receipt_header, trnrm_receipt_trailer,massal_customer where rech_seqno = rect_hdseqno and rech_sup_code = cust_code and rech_compcode = 1 and rech_date between  '2024-04-01' and '2024-04-30' 
 union all
