/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`%` PROCEDURE `spacc_rep_column_report_VouType_Cash`(compcode int,fincode int,startdate date,enddate date)
BEGIN
WITH common_acc_seqno AS (
    SELECT accref_seqno  
    FROM acc_ref 
    JOIN acc_tran ON accref_seqno = acctran_accref_seqno 
    WHERE accref_comp_code = 1
      AND accref_finid = fincode 
      AND accref_voudate BETWEEN startdate AND enddate
      AND acctran_led_code = 2139 
    GROUP BY accref_seqno
),

jvheader AS (
    SELECT * FROM (
        SELECT 
            a.accref_seqno,
            a.accref_vouno,
            a.accref_voudate,
            l.cust_type AS ledtype,
            a.accref_seqno AS accrefno,
            CASE 
                WHEN accref_vou_type IN ('CHR', 'BKP') THEN l.cust_ref 
                ELSE 'CASH' 
            END AS cust_ref,
            l.cust_gstin,
            CASE 
                WHEN accref_vou_type IN ('CHR', 'BKP') THEN b.acctran_totamt 
                ELSE b.acctran_totamt * -1 
            END AS invamt,
            LEFT(a.accref_payref_no, 13) AS vou_refno,
            a.accref_payref_date AS billdate,
            a.accref_narration,
            b.acctran_serialno AS slno,
            ROW_NUMBER() OVER (PARTITION BY a.accref_vouno ORDER BY b.acctran_serialno) AS rn
        FROM 
            acc_ref a
        JOIN acc_tran b ON a.accref_seqno = b.acctran_accref_seqno
        JOIN massal_customer l ON b.acctran_led_code = l.cust_code
        WHERE 
            a.accref_comp_code = 1
            AND a.accref_finid = fincode
            AND a.accref_voudate BETWEEN startdate AND enddate
            AND a.accref_seqno IN (SELECT accref_seqno FROM common_acc_seqno)
    ) AS dedup
    WHERE rn = 1
),

jvledger AS (
    SELECT * FROM (
SELECT 
    a.accref_seqno AS acseqno, 
    l.cust_name AS ledger_name, 
    CASE 
                WHEN accref_vou_type IN ('CHR', 'BKP') THEN b.acctran_totamt 
                ELSE b.acctran_totamt * -1 
        
    END AS ledger_amt,
    b.acctran_serialno,
    ROW_NUMBER() OVER (
        PARTITION BY a.accref_seqno 
        ORDER BY b.acctran_serialno
    ) AS rn
FROM 
    acc_ref a
JOIN acc_tran b ON a.accref_seqno = b.acctran_accref_seqno
JOIN massal_customer l ON b.acctran_led_code = l.cust_code
WHERE 
    a.accref_comp_code = 1
    AND a.accref_finid = fincode  
    AND a.accref_voudate BETWEEN startdate AND enddate
    AND EXISTS (
        SELECT 1
        FROM acc_tran t
        WHERE 
            t.acctran_accref_seqno = a.accref_seqno
            AND t.acctran_led_code = 2139
    )
    AND (
        (a.accref_vou_type = 'CHR' AND b.acctran_serialno <> 1)
        OR
        (a.accref_vou_type <> 'CHR' AND b.acctran_serialno = 1)
    )
ORDER BY 
    a.accref_seqno, b.acctran_serialno
            
    ) AS dedup
    WHERE rn = 1
)

SELECT 
    jh.accref_seqno,
    jh.accref_vouno,
    jh.accref_voudate,
    jh.ledtype,
    jh.accrefno,
    jh.cust_ref,
    jh.cust_gstin,
