CREATE DEFINER=`root`@`%` PROCEDURE `spacc_rep_column_report_VouType_Others`(compcode int,fincode int,startdate date,enddate date,voutype varchar(30))
BEGIN
WITH jvheader AS (
    SELECT 
        a.accref_seqno,
        a.accref_vouno,
        a.accref_voudate,
        l.cust_type AS ledtype,
        a.accref_seqno AS accrefno,
        l.cust_ref,
        l.cust_gstin,
        b.acctran_totamt AS invamt,
        LEFT(a.accref_payref_no, 13) AS vou_refno,
        a.accref_payref_date AS billdate,
        a.accref_narration,
        b.acctran_serialno AS slno,
        ROW_NUMBER() OVER (PARTITION BY a.accref_vouno ORDER BY b.acctran_serialno) AS rn
    FROM 
        acc_ref a
    JOIN 
        acc_tran b ON a.accref_seqno = b.acctran_accref_seqno
    JOIN 
        massal_customer l ON b.acctran_led_code = l.cust_code
    WHERE 
    
        l.cust_type != 'G'
        AND accref_comp_code  = compcode AND  accref_finid = fincode
        AND find_in_set(a.accref_vou_type,voutype)
        AND a.accref_voudate BETWEEN startdate AND enddate

    UNION ALL        

    SELECT 
        accref_seqno,
        accref_vouno,
        accref_voudate,
        cust_type AS ledtype,
        accref_seqno AS accrefno,
        cust_ref,
        cust_gstin,
        acctran_totamt AS invamt, 
        LEFT(accref_payref_no, 13) AS vou_refno,
        accref_payref_date AS billdate,
        accref_narration,
        acctran_serialno AS slno,
        1 AS rn
    FROM 
        acc_ref a
    JOIN 
        acc_tran b ON accref_seqno = acctran_accref_seqno
    JOIN 
        massal_customer l ON acctran_led_code = cust_code
    WHERE 
        accref_comp_code  = compcode AND  accref_finid = fincode
        AND accref_voudate BETWEEN startdate AND enddate
        AND find_in_set(accref_vou_type,voutype)
        AND accref_seqno NOT IN (
            SELECT accref_seqno
            FROM acc_ref a
            JOIN acc_tran b ON a.accref_seqno = b.acctran_accref_seqno
            JOIN massal_customer l ON b.acctran_led_code = l.cust_code
            WHERE 
                cust_type != 'G'  
                and accref_comp_code  = compcode AND  accref_finid = fincode
                AND accref_voudate BETWEEN startdate AND enddate 
                AND find_in_set(accref_vou_type,voutype)
            GROUP BY accref_seqno
        )
        AND acctran_serialno = 1
),

jvledger AS (
    SELECT 
        accref_seqno AS acseqno, 
        cust_name AS ledger_name, 
        case when cust_name = "ROUNDED OFF" and acctran_dbamt > 0 then acctran_totamt *-1 
        else case when cust_name = "ROUNDED OFF" and acctran_cramt > 0 then acctran_totamt 
        else acctran_totamt end end as ledger_amt, 
        acctran_serialno  
    FROM 
        acc_ref 
    JOIN 
        acc_tran ON accref_seqno = acctran_accref_seqno
    JOIN 
        massal_customer ON acctran_led_code = cust_code
    WHERE 
        
        accref_comp_code  = compcode AND  accref_finid = fincode
        AND find_in_set(accref_vou_type,voutype)
        AND accref_finid = fincode
        AND accref_voudate BETWEEN startdate AND enddate
)

SELECT 
    jh.accref_seqno,
    jh.accref_vouno,
    jh.accref_voudate,
    jh.ledtype,
    jh.accrefno,
    jh.cust_ref,
    jh.cust_gstin,
    jh.invamt,
    jh.vou_refno,
    jh.billdate,
    jh.accref_narration,
    jh.slno,
    jl.ledger_name,
    jl.ledger_amt
FROM 
    jvheader jh
LEFT JOIN 
    jvledger jl ON jh.accref_seqno = jl.acseqno 
                 AND jl.acctran_serialno <> jh.slno
WHERE 
    jh.rn = 1
ORDER BY 
    jh.accref_voudate, 
    jh.accref_vouno;
END ;;
DELIMITER ;
