CREATE DEFINER=`root`@`%` PROCEDURE `spacc_rep_column_report_VouType_Sales`(compcode int,fincode int,startdate date,enddate date,voutype varchar(10))
BEGIN
WITH common_inv_seqno  AS (
select cust_ref,cust_gstin, accrefseqno, invh_date accref_voudate, invno accref_vouno, Qty, uom, invamt, vou_refno from(
select cust_ref,cust_gstin, invh_acc_refno  accrefseqno , invh_date, invh_invrefno invno ,  Cast(invh_totwt/1000 as decimal(18,3)) as Qty , invh_netamt as invamt, "MTS" uom , left(invh_our_ordno,6) as vou_refno   from trnsal_invoice_header i, massal_customer where invh_party = cust_code and invh_comp_code =  1 and invh_date  between '2025-06-01' and '2025-06-30' and invh_netamt > 0
union all
select cust_ref,cust_gstin, os_acc_seqno  accrefseqno , os_date invh_date, os_invno  invno ,  Cast(os_qty as decimal(18,3)) as Qty , os_netamt as invamt, uom_short_name uom , '' as vou_refno  from trn_other_sales , massal_customer , mas_othersales_item_master , mas_uom  where  os_item = salitem_code and salitem_uom = uom_code and  os_custcode = cust_code and os_compcode = 1 and os_date between '2025-06-01' and '2025-06-30' and os_netamt > 0 
) a1 order by invh_date,accrefseqno,invno
) ,

salesheader AS (
    SELECT 
        accref_seqno AS acseqno, 
        cust_name AS ledger_name, 
        case when cust_name = "ROUNDED OFF" and acctran_dbamt > 0 then acctran_totamt *-1 
        else case when cust_name = "ROUNDED OFF" and acctran_cramt > 0 then acctran_totamt 
        else acctran_totamt end end as ledger_amt 
    FROM 
        acc_ref 
    JOIN 
        acc_tran ON accref_seqno = acctran_accref_seqno
    JOIN 
        massal_customer ON acctran_led_code = cust_code
    WHERE 
        accref_comp_code = 1
		AND cust_type = 'G'  
        AND find_in_set(accref_vou_type,'GSI,OSI')
        AND accref_finid = 25
        AND accref_voudate BETWEEN '2025-06-01' and '2025-06-30'
)

SELECT 
     cust_ref, cust_gstin, accrefseqno, accref_voudate, accref_vouno, Qty, invamt, uom, vou_refno,
    ledger_name,
    ledger_amt

FROM 
    common_inv_seqno jh
LEFT JOIN 
    salesheader jl ON jh.accrefseqno = jl.acseqno
ORDER BY 
    jh.accref_voudate, 
    jh.accref_vouno;
 END ;;
DELIMITER ;
