CREATE DEFINER=`root`@`%` PROCEDURE `spacc_rep_desp_truckwise`(compcode int,fromdate date , todate date,opt int)
BEGIN
if opt = 1
then
select  'MILLS TRUCK' as trucktype , cust_ref , invh_invrefno, DATE_FORMAT(invh_date, '%d-%m-%Y')  invh_date, round((invh_totwt/1000),3) weight,cust_city, invh_delivery_city,invh_vehi_no  from trnsal_invoice_header , massal_customer where  invh_party = cust_code and invh_comp_code = compcode and invh_date between fromdate and todate and invh_vehi_no in (select truck_no from mas_mill_truck) order by invh_date;
else
select 'OTHERS TRUCK' as trucktype , cust_ref , invh_invrefno, DATE_FORMAT(invh_date, '%d-%m-%Y')  invh_date, round((invh_totwt/1000),3) weight,cust_city, invh_delivery_city,invh_vehi_no  from trnsal_invoice_header , massal_customer where  invh_party = cust_code and invh_comp_code = compcode and invh_date between fromdate and todate and invh_vehi_no not in (select truck_no from mas_mill_truck) order by invh_date;
end if;
END ;;
DELIMITER ;
