CREATE DEFINER=`root`@`%` PROCEDURE `spacc_rep_exp_vouprint`(compcode int,fincode int,vouno varchar(15))
BEGIN
select  *
from (
select  a.*,b.*,party.cust_code partyledcode,party.cust_name partyledname,party.cust_gstin,party.cust_panno,
party.cust_add1 addr1,
party.cust_add2 addr2,
party.cust_add3 addr3,
party.cust_city city,
party.cust_zip  pin,
tds.cust_code ledgercode,
tds.cust_name tdsname,
tax.cust_name taxname,
cgst.cust_name cgstledgername,
sgst.cust_name sgstledgername,
igst.cust_name igstledgername
from acc_expenses_header a, acc_expenses_trailer b,
massal_customer party,
massal_customer tds,
massal_customer tax,
massal_customer cgst,
massal_customer sgst,
massal_customer igst
where eh_expno = et_expno and  eh_compcode = et_compcode  and eh_fincode = et_fincode and
eh_compcode = compcode and eh_fincode = fincode and eh_partycode = party.cust_code and et_tdsledcode = tds.cust_code 
and et_taxable_code = tax.cust_code 
and et_cgst_ledcode = cgst.cust_code
and et_sgst_ledcode = sgst.cust_code
and et_igst_ledcode = igst.cust_code
and eh_expvouno = vouno
)a1; 
END ;;
DELIMITER ;
