DELIMITER ;;
CREATE DEFINER=`root`@`%` PROCEDURE `spacc_rep_gst_document_summary`(compcode int,fincode int,fromdate date , todate date )
BEGIN

select doc_num, doc_type,  num,  saltype, salestype, yr, from_no, to_no, totalnos, cancelled, (totalnos - cancelled)  netissues from
(


select "1" as doc_num,  priority,row_number() over(order by priority) as num, "Invoices for outward supply" doc_type, saltype,salestype,yr,
case when from_no > 99 then concat(saltype,'/',from_no,yr) else concat(saltype,'/',right(concat('00',from_no),3),yr) end as from_no,
case when to_no > 99 then concat(saltype,'/',to_no,yr) else concat(saltype,'/',right(concat('00',to_no),3),yr) end as to_no,
totalnos, cancelled, totalnos-cancelled  netissues 
from (

select saltype, case when saltype = "TN" then "TN GST SALES" else
case when saltype = "OS" then "OS IGST SALES" else
case when saltype = "SEZ" then "SEZ SALES" else
case when saltype = "TNOS" then "TN OS GST SALES" else 
case when saltype = "OSOS" then "OS OS IGST SALES" else
case when saltype = "SDN" then "DEBIT NOTE"
end end end end end end as salestype,
case when saltype = "TN" then "1" else
case when saltype = "OS" then "2" else
case when saltype = "TNOS" then "3" else 
case when saltype = "OSOS" then "4" else
case when saltype = "SDN" then "5" 
end end end end end as priority,yr,from_no,to_no,sum(totnos) totalnos,sum(cancelled) cancelled from
(
select h.* , case when t.cancelled > 0 then t.cancelled else 0 end as cancelled from 
(select invh_saltype saltype ,right(invh_invrefno,6) as yr, min(invh_no) from_no ,max(invh_no) to_no ,max(invh_no)+1-min(invh_no) totnos  from trnsal_invoice_header where invh_comp_code = compcode  and  invh_date between  fromdate and  todate group by invh_saltype,right(invh_invrefno,6)) h 

left join
(select invh_saltype , count(*) as cancelled from trnsal_invoice_header where invh_comp_code = compcode   and invh_netamt = 0 and  invh_date between  fromdate and  todate group by invh_saltype,right(invh_invrefno,6)) t 
on h.saltype = t.invh_saltype 

union all
select h.* , case when t.cancelled > 0 then t.cancelled else 0 end as cancelled from 
(select os_state_type saltype,right(os_invno,6) as yr,min(os_docno) from_no ,max(os_docno) to_no ,max(os_docno)+1-min(os_docno) totnos  from trn_other_sales  where os_compcode = compcode   and  os_date between fromdate and  todate and os_netamt > 0  group by os_state_type,right(os_invno,6) ) h
left join 
(select os_state_type saltype,right(os_invno,6) as yr, 0 from_no ,0  to_no ,0 totnos ,count(*) as cancelled  from trn_other_sales  where os_netamt =0 and os_compcode = compcode    and os_cancel = 'Y' and  os_date between fromdate and  todate group by os_state_type,right(os_invno,6)) t
on h.saltype = t.saltype 

union all

select h.* , case when t.cancelled > 0 then t.cancelled else 0 end as cancelled from 
(
select dbcr_type saltype ,right(dbcr_vouno,6) as yr, min(dbcr_no) from_no ,max(dbcr_no) to_no ,max(dbcr_no)+1-min(dbcr_no) totnos  from acc_dbcrnote_header where dbcr_comp_code = compcode  and  dbcr_date between  fromdate and  todate  and dbcr_type in ('SDN') and dbcr_party_type = 'C' group by dbcr_type,right(dbcr_vouno,6)
) h 
left join
(select dbcr_type saltype  , count(*) as cancelled from acc_dbcrnote_header where dbcr_comp_code = compcode and dbcr_value = 0 and  dbcr_date between  fromdate and  todate and dbcr_type in ('SDN') and dbcr_party_type = 'C'  group by dbcr_type,right(dbcr_vouno,6)) t 
on h.saltype = t.saltype 


) grp1 group by saltype,yr,from_no,to_no
) grp2

union all
select  doc_num,  priority,row_number() over(order by priority) as num, "DEBIT NOTE" doc_type, saltype,salestype,yr,
case when from_no > 99 then concat(saltype,'/',from_no,yr) else concat(saltype,'/',right(concat('00',from_no),3),yr) end as from_no,
case when to_no > 99 then concat(saltype,'/',to_no,yr) else concat(saltype,'/',right(concat('00',to_no),3),yr) end as to_no,
totnos, cancelled, totnos-cancelled  netissues 
from (
select '6' as doc_num , 6  priority, 6 num, h.* , case when t.cancelled > 0 then t.cancelled else 0 end as cancelled from 
(
select dbcr_type saltype ,'Debit Note' salestype,right(dbcr_vouno,6) as yr, min(dbcr_no) from_no ,max(dbcr_no) to_no ,max(dbcr_no)+1-min(dbcr_no) totnos  from acc_dbcrnote_header where dbcr_comp_code = compcode  and  dbcr_date between  fromdate and  todate  and dbcr_type in ('DNG') and dbcr_party_type != 'C' group by dbcr_type,right(dbcr_vouno,6)
) h 
left join
(select dbcr_type saltype  , count(*) as cancelled from acc_dbcrnote_header where dbcr_comp_code = compcode and dbcr_value = 0 and  dbcr_date between  fromdate and  todate and dbcr_type in ('DNG') and dbcr_party_type != 'C'  group by dbcr_type,right(dbcr_vouno,6)) t 
on h.saltype = t.saltype 
) grp3



union all
select 
doc_num, priority, num, doc_type, saltype, salestype, yr, max(from_no), max(to_no), sum(totalnos) totalnos, sum(cancelled) cancelled , sum(netissues) netissues
from
(
select  "7" as doc_num, "7" as priority,"7" as num, "Credit Note" doc_type, 'CNG' saltype,'CREDIT NOTE' salestype,0 yr,0 from_no,0 to_no, 0 as totalnos,count(*) as cancelled, 0 as netissues from acc_dbcrnote_header where dbcr_value = 0 and  dbcr_comp_code = compcode    and dbcr_finid = fincode   and dbcr_date between  fromdate and  todate and dbcr_type in ('CNG') and dbcr_party_type = 'C'
union all
select  "7" as doc_num, "7" as priority,"7"  as num, "Credit Note" doc_type, 'CNG' saltype,'CREDIT NOTE' salestype,0 yr,min(dbcr_vouno) from_no,max(dbcr_vouno) to_no,count(*) as totalnos,0 cancelled, count(*) as netissues from acc_dbcrnote_header where  dbcr_comp_code = compcode and dbcr_finid = fincode    and dbcr_date between  fromdate and  todate and dbcr_type in ('CNG') and dbcr_party_type = 'C'
) aa1
 group by doc_num, priority, num, doc_type, saltype, salestype, yr 
) a1 where (totalnos - cancelled)  > 0 ;

