select  "4" as doc_num, "3" as priority,row_number() over() as num,  "Debit Note" doc_type, 'DN' saltype,'DEBIT NOTE' salestype,0 yr,min(dbcr_vouno) from_no,max(dbcr_vouno) to_no,count(*) as totalnos,0 cancelled, count(*) as netissues from acc_dbcrnote_header where dbcr_value >0 and  dbcr_comp_code = compcode  and dbcr_finid = fincode and dbcr_date between  fromdate and  todate and dbcr_type in ('DNG')
union all
select  "5" as doc_num, "2" as priority,row_number() over() as num, "Credit Note" doc_type, 'CN' saltype,'CREDIT NOTE' salestype,0 yr,0 from_no,0 to_no, 0 as totalnos,count(*) as cancelled, 0 as netissues from acc_dbcrnote_header where dbcr_value = 0 and  dbcr_comp_code = compcode  and dbcr_finid = fincode and dbcr_date between  fromdate and  todate and dbcr_type in ('CNG')
union all
select  "4" as doc_num, "3" as priority,row_number() over() as num,  "Debit Note" doc_type, 'DN' saltype,'DEBIT NOTE' salestype,0 yr,0 from_no,0 to_no,0 as totalnos,count(*) as cancelled, 0 as netissues from acc_dbcrnote_header where dbcr_value = 0 and  dbcr_comp_code = compcode  and dbcr_finid = fincode and dbcr_date between  fromdate and  todate and dbcr_type in ('DNG')
) aa1
 group by doc_num, priority, num, doc_type, saltype, salestype, yr 
) a1;
*/
END ;;
DELIMITER ;
