/*!50003 DROP PROCEDURE IF EXISTS `spacc_rep_gst_document_summary_detailed` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`%` PROCEDURE `spacc_rep_gst_document_summary_detailed`(compcode int,fincode int,fromdate date , todate date ,vou_type varchar(4))
BEGIN

    
if vou_type = 'TN' OR vou_type = 'OS' then
	
    select  voudate , party,gstin ,voutype,vouno,uqc,totqty ,	totalamt,	taxableamt, igstamt, cgstamt, sgstamt,cessamt,invh_vouno
    from 
    (select  DATE_FORMAT(invh_date, '%d-%m-%Y') as voudate , cust_ref party,cust_gstin gstin ,case when invh_saltype = "TN" then "TN GST SALES" else "OS IGST SALES" end voutype,invh_invrefno vouno,'NTS' uqc,round(invh_totwt/1000,3)  as totqty ,
	invh_taxableamt+invh_sgst_amt+invh_cgst_amt+invh_igst_amt as totalamt,
	invh_taxableamt taxableamt, invh_igst_amt  igstamt, invh_cgst_amt cgstamt, invh_sgst_amt sgstamt,0 as cessamt,invh_vouno
	from trnsal_invoice_header a , massal_customer  b,  
	(select invt_compcode , invt_fincode ,invt_seqno,max(invt_hsncode) hsncode from trnsal_invoice_trailer where invt_compcode = compcode and invt_fincode = fincode group by  invt_compcode , invt_fincode ,invt_seqno) c
	where  invh_comp_code = invt_compcode and invh_fincode = invt_fincode and invh_seqno = invt_seqno  and  invh_party = cust_code and  invh_comp_code = compcode and invh_fincode = fincode and invh_date between fromdate and todate and invh_netamt > 0 and invh_saltype =  vou_type order by invh_date,invh_seqno 
    )a1 ;  
else
        if vou_type = 'TNOS' OR vou_type = 'OSOS' then
        select  voudate , party,gstin ,voutype,vouno,uqc,totqty ,totalamt,taxableamt, igstamt, cgstamt, sgstamt,cessamt,invh_vouno
        from
        (
        select  DATE_FORMAT(os_date, '%d-%m-%Y') as voudate , cust_name party,cust_gstin gstin ,case when os_state_type = "TNOS" then "TNOS GST SALES" else "OSOS IGST SALES" end voutype,os_invno vouno,'NTS' uqc,os_qty as totqty ,
		os_netamt as totalamt,os_taxable taxableamt, os_igst  igstamt, os_cgst cgstamt, os_sgst sgstamt,0 as cessamt,os_acvou_no invh_vouno		
        from trn_other_sales join  massal_customer on os_custcode = cust_code 
		join mas_othersales_item_master on os_item = salitem_code  
		where  os_compcode = compcode and os_fincode = fincode  and os_date between fromdate and todate  and os_state_type = vou_type order by os_date
        ) a1;    
        else
          if vou_type = 'CNG' then
			select  voudate , party,gstin ,voutype,vouno,uqc,totqty ,totalamt,taxableamt, igstamt, cgstamt, sgstamt,cessamt,invh_vouno
			from
			(
			select  DATE_FORMAT(dbcr_date, '%d-%m-%Y') as voudate , cust_name party,cust_gstin gstin ,"CNG"  voutype,dbcr_vouno vouno,'RS' uqc,dbcr_qty as totqty ,
		   
			dbcr_value as totalamt,dbcrt_taxable taxableamt, dbcrt_igstvalue  igstamt, dbcrt_cgstvalue cgstamt, dbcrt_sgstvalue sgstamt,0 as cessamt,dbcr_vouno invh_vouno from
			
			acc_dbcrnote_header , acc_dbcrnote_trailer , massal_customer where dbcr_partycode = cust_code and  dbcr_seqno = dbcrt_seqno and  dbcr_comp_code = compcode and dbcr_finid = fincode and dbcr_date between  fromdate and todate and dbcr_type = 'CNG' and dbcr_party_type = 'C'
			 )a1;  
        else
			  if vou_type = 'SDN' then
				select  voudate , party,gstin ,voutype,vouno,uqc,totqty ,totalamt,taxableamt, igstamt, cgstamt, sgstamt,cessamt,invh_vouno
				from
				(
				select  DATE_FORMAT(dbcr_date, '%d-%m-%Y') as voudate , cust_name party,cust_gstin gstin ,"SDN"  voutype,dbcr_vouno vouno,'RS' uqc,dbcr_qty as totqty ,
			   
				dbcr_value as totalamt,dbcrt_taxable taxableamt, dbcrt_igstvalue  igstamt, dbcrt_cgstvalue cgstamt, dbcrt_sgstvalue sgstamt,0 as cessamt,dbcr_vouno invh_vouno from
				
				acc_dbcrnote_header , acc_dbcrnote_trailer , massal_customer where dbcr_partycode = cust_code and  dbcr_seqno = dbcrt_seqno and  dbcr_comp_code = compcode and dbcr_finid = fincode and dbcr_date between  fromdate and todate and dbcr_type = 'SDN' and dbcr_party_type = 'C'
				 )a1;  
        else
			  if vou_type = 'DN' then
				select  voudate , party,gstin ,voutype,vouno,uqc,totqty ,totalamt,taxableamt, igstamt, cgstamt, sgstamt,cessamt,invh_vouno
				from
				(
				select  DATE_FORMAT(dbcr_date, '%d-%m-%Y') as voudate , cust_name party,cust_gstin gstin ,"DNG"  voutype,dbcr_vouno vouno,'RS' uqc,dbcr_qty as totqty ,
			   
				dbcr_value as totalamt,dbcrt_taxable taxableamt, dbcrt_igstvalue  igstamt, dbcrt_cgstvalue cgstamt, dbcrt_sgstvalue sgstamt,0 as cessamt,dbcr_vouno invh_vouno from
				
				acc_dbcrnote_header , acc_dbcrnote_trailer , massal_customer where dbcr_partycode = cust_code and  dbcr_seqno = dbcrt_seqno and  dbcr_comp_code = compcode and dbcr_finid = fincode and dbcr_date between  fromdate and todate and dbcr_type = 'DNG' and dbcr_party_type != 'C'
				 )a1;  
          end if; 		                 
          end if; 			
          end if; 
        end if; 
end if;    

END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `spacc_rep_hsnwise_sales` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`%` PROCEDURE `spacc_rep_hsnwise_sales`(compcode int,fincode int,fromdate date,todate date)
BEGIN

select 
 case when cust_gst_type = "R" then "B2B SUPPLIES" else "B2C SUPPLIES" end as supplytype , cust_gst_type,  sum(noofrec) noofrec, saltype,hsncode, max(descrip) descrip, 'GOODS' supply, uqc, sum(totalvalue) totalvalue, sum(qty) qty, sum(taxval) taxval , rt taxrate, sum(samt) samt, sum(camt) camt, sum(iamt) iamt , sum(samt) + sum(camt) + sum(iamt) totaltaxamt ,0 as cessamt, sum(taxval) + sum(samt) + sum(camt) + sum(iamt) subtotal
from 

(
select  cust_gst_type, sum(nos) noofrec,
saltype, hsncode, descrip, uqc, sum(totalvalue) totalvalue, sum(qty) qty, sum(txval) taxval , case when cgstper >0 then
cgstper+sgstper else igstper end as rt, sum(samt) samt, sum(camt) camt, sum(iamt) iamt
from 
(

select cust_gst_type, sum(nos) nos, saltype, hsncode, GROUP_CONCAT( DISTINCT  descrip)  descrip, uqc, sum(totalvalue) totalvalue,
 sum(qty) qty, sum(txval) txval,   max(cgstper) cgstper, max(sgstper) sgstper ,  max(igstper)  igstper, sum(samt) samt, sum(camt) camt, sum(iamt) iamt from (
 
 
select cust_gst_type, sum(nos) nos, saltype, hsncode, descrip, uqc, sum(totalvalue) totalvalue,
 sum(qty) qty, sum(txval) txval,   cgstper+sgstper+igstper gstper ,max(cgstper) cgstper, max(sgstper) sgstper ,  max(igstper)  igstper, sum(samt) samt, sum(camt) camt, sum(iamt) iamt from (
 
	select  cust_gst_type, count(*) as nos,'GS' saltype,hsncode,invh_taxtag,  min(vargrp_type_name) descrip , 'MTS' uqc,sum(invh_netamt-invh_tcs_amt) totalvalue,round(sum(invh_totwt)/1000,3) qty ,sum(invh_taxableamt) txval , max(invh_cgst_per) cgstper,max(invh_sgst_per) sgstper,max(invh_igst_per) igstper, sum(invh_sgst_amt) samt , sum(invh_cgst_amt) camt , sum(invh_igst_amt) iamt   from trnsal_invoice_header  h, (
    select invt_compcode,invt_fincode,invt_seqno,max(invt_hsncode) hsncode,min(vargrp_type_name) vargrp_type_name from trnsal_invoice_trailer , masprd_variety , masprd_type   where invt_compcode = 1  and invt_fincode = fincode   and invt_item =  var_groupcode and    var_typecode =  vargrp_type_code and   invt_compcode = 1  and invt_fincode = fincode  group by invt_compcode,invt_fincode,invt_seqno
	)  t , massal_customer c where invh_party = cust_code  and  
	invh_comp_code = invt_compcode and invh_fincode = invt_fincode and  invh_seqno = invt_seqno and
	invh_comp_code = 1  and invh_fincode = fincode  and  invh_date between fromdate and todate   and invh_netamt > 0 group by cust_gst_type, hsncode,invh_taxtag
    
    ) a1 group by     cust_gst_type, saltype, hsncode ,descrip, cgstper,sgstper,igstper 
 
 ) a2  group by     cust_gst_type, saltype, hsncode , gstper
    
   union all     
 
    
    select cust_gst_type, count(*) as nos,'OS' saltype, salitem_hsn hsncode, max(salitem_name) descrip,uom_short_name uqc,sum(os_netamt) totalvalue ,
    sum(qty) qty,sum(txval) txval,os_cgstper cgstper,os_sgstper sgstper,os_igstper igstper,sum(samt) samt,sum(camt) camt,sum(iamt) iamt  from
     (
	 select  cust_gst_type, salitem_hsn,salitem_name,os_netamt,os_cgstper,os_sgstper,os_igstper,sum(os_qty) as qty,sum(os_taxable) txval,sum(os_cgst) camt,sum(os_sgst) samt,sum(os_igst) iamt,uom_short_name
	 from trn_other_sales join  massal_customer on os_custcode = cust_code 
	 join mas_othersales_item_master on os_item = salitem_code
	 join mas_uom on  salitem_uom = uom_code
	 where os_netamt > 0 and  os_compcode = compcode and os_fincode = fincode and os_date between fromdate and todate  
	 group by cust_gst_type, salitem_hsn,salitem_name,os_netamt,os_cgstper,os_sgstper,os_igstper,uom_short_name
          ) hsn1  group by cust_gst_type, salitem_hsn,os_cgstper ,os_sgstper,os_igstper,uom_short_name
          
union all   
-- SALES RETURN - CREDIT NOTE    
select  cust_gst_type, count(*) as nos,saltype,hsncode,descrip,uqc,sum(dbcr_value)*-1 totalvalue,  dbcr_qty*-1 qty, sum(dbcrt_taxable*-1) txval, 
 dbcrt_cgstper cgstper,dbcrt_sgstper sgstper,dbcrt_igstper igstper,
sum(dbcrt_cgstvalue*-1) camt , sum(dbcrt_sgstvalue*-1) samt , sum(dbcrt_igstvalue*-1) iamt 
from (
select  cust_gst_type, 'GS' saltype , dbcr_hsncode hsncode,
case when dbcr_hsncode = '48059200' then 'PLASTERBOARD LINER PAPER' 
 when dbcr_hsncode = '48052500' then 'BLUE BOARD' 
  when dbcr_hsncode = '47062000' then 'RECYCLED PULP' else
'KRAFT PAPER' end as descrip, 'MTS' uqc, dbcr_value,  dbcr_qty, dbcrt_taxable, 
 dbcrt_cgstper , dbcrt_sgstper ,dbcrt_igstper ,
dbcrt_cgstvalue , dbcrt_sgstvalue , dbcrt_igstvalue
 from acc_dbcrnote_header h left join  acc_dbcrnote_trailer t on h.dbcr_seqno = t.dbcrt_seqno   
  join massal_customer on dbcr_partycode = cust_code 
where dbcr_comp_code = compcode and dbcr_date between  fromdate and todate  and dbcr_type = 'CNG' and (dbcrt_cgstledcode = 1644 or dbcrt_sgstledcode = 1645 or  dbcrt_igstledcode = 1646 or  dbcrt_igstledcode = 5133) 
and  dbcrt_cgstvalue + dbcrt_sgstvalue+ dbcrt_igstvalue > 0 and dbcr_party_type = 'C' and  dbcr_reason = 'SAL RETURN'
)a1 group by cust_gst_type, saltype,hsncode,descrip,uqc,dbcr_qty
,dbcrt_cgstper ,dbcrt_sgstper ,dbcrt_igstper
union all   
     -- OTHER CREDIT NOTES
select  cust_gst_type, count(*) as nos,saltype,hsncode,descrip,uqc,sum(dbcr_value)*-1 totalvalue,  0 qty, sum(dbcrt_taxable*-1) txval, 
 dbcrt_cgstper cgstper,dbcrt_sgstper sgstper,dbcrt_igstper igstper,
sum(dbcrt_cgstvalue*-1) camt , sum(dbcrt_sgstvalue*-1) samt , sum(dbcrt_igstvalue*-1) iamt 
from (
select  cust_gst_type,'CN' saltype , dbcr_hsncode hsncode,
case when dbcr_hsncode = '48059200' then 'PLASTERBOARD LINER PAPER' 
 when dbcr_hsncode = '48052500' then 'BLUE BOARD' 
  when dbcr_hsncode = '47062000' then 'RECYCLED PULP' else
'Kraft Paper' end as descrip, 'MTS' uqc, dbcr_value, dbcr_qty , dbcrt_taxable, 
 dbcrt_cgstper , dbcrt_sgstper ,dbcrt_igstper ,
dbcrt_cgstvalue , dbcrt_sgstvalue , dbcrt_igstvalue
 from acc_dbcrnote_header h left join  acc_dbcrnote_trailer t on h.dbcr_seqno = t.dbcrt_seqno   
  join massal_customer on dbcr_partycode = cust_code 
where dbcr_comp_code = compcode and dbcr_date between  fromdate and todate  and dbcr_type = 'CNG' and (dbcrt_cgstledcode = 1644 or dbcrt_sgstledcode = 1645 or  dbcrt_igstledcode = 1646 or  dbcrt_igstledcode = 5133) 
and  dbcrt_cgstvalue + dbcrt_sgstvalue+ dbcrt_igstvalue > 0 and dbcr_party_type = 'C' and  dbcr_reason != 'SAL RETURN'
)a1 group by cust_gst_type, saltype,hsncode,descrip,uqc,dbcr_qty
,dbcrt_cgstper ,dbcrt_sgstper ,dbcrt_igstper

union all   
-- debit note     
select  cust_gst_type, count(*) as nos,'CN' saltype , dbcr_hsncode hsncode, 
case when dbcr_hsncode = '48059200' then 'PLASTERBOARD LINER PAPER' 
 when dbcr_hsncode = '48052500' then 'BLUE BOARD' 
  when dbcr_hsncode = '47062000' then 'RECYCLED PULP' else
'Kraft Paper' end as descrip,
 'MTS' uqc, sum(dbcr_value) totalvalue,  sum(dbcr_qty) qty, sum(dbcrt_taxable) txval, 
 dbcrt_cgstper cgstper,dbcrt_sgstper sgstper,dbcrt_igstper igstper,
sum(dbcrt_cgstvalue) camt , sum(dbcrt_sgstvalue) samt , sum(dbcrt_igstvalue) iamt 
 from acc_dbcrnote_header h left join  acc_dbcrnote_trailer t on h.dbcr_seqno = t.dbcrt_seqno   
 join massal_customer on dbcr_partycode = cust_code 
where dbcr_comp_code = compcode and dbcr_date between fromdate and todate and dbcr_type = 'SDN' and (dbcrt_cgstledcode = 1644 or dbcrt_sgstledcode = 1645 or  dbcrt_igstledcode = 1646 or  dbcrt_igstledcode = 5133) 
and  dbcrt_cgstvalue + dbcrt_sgstvalue+ dbcrt_igstvalue > 0 and dbcr_party_type = 'C'
group by cust_gst_type, dbcr_hsncode,dbcrt_cgstper ,dbcrt_sgstper ,dbcrt_igstper
) a1 
group by cust_gst_type, saltype, hsncode, descrip, uqc,cgstper,sgstper,igstper
) aa1 
group by  cust_gst_type, saltype,hsncode,  uqc,rt order by cust_gst_type, hsncode; 


/*
select 
  sum(noofrec) noofrec, saltype,hsncode, max(descrip) descrip, 'GOODS' supply, uqc, sum(totalvalue) totalvalue, sum(qty) qty, sum(taxval) taxval , rt taxrate, sum(samt) samt, sum(camt) camt, sum(iamt) iamt , sum(samt) + sum(camt) + sum(iamt) totaltaxamt ,0 as cessamt, sum(taxval) + sum(samt) + sum(camt) + sum(iamt) subtotal
from 

(
select  sum(nos) noofrec,
saltype, hsncode, descrip, uqc, sum(totalvalue) totalvalue, sum(qty) qty, sum(txval) taxval , case when cgstper >0 then
cgstper+sgstper else igstper end as rt, sum(samt) samt, sum(camt) camt, sum(iamt) iamt
from 
(

 
 

select sum(nos) nos, saltype, hsncode, GROUP_CONCAT( DISTINCT  descrip)  descrip, uqc, sum(totalvalue) totalvalue,
 sum(qty) qty, sum(txval) txval,   max(cgstper) cgstper, max(sgstper) sgstper ,  max(igstper)  igstper, sum(samt) samt, sum(camt) camt, sum(iamt) iamt from (
 
 
select sum(nos) nos, saltype, hsncode, descrip, uqc, sum(totalvalue) totalvalue,
 sum(qty) qty, sum(txval) txval,   cgstper+sgstper+igstper gstper ,max(cgstper) cgstper, max(sgstper) sgstper ,  max(igstper)  igstper, sum(samt) samt, sum(camt) camt, sum(iamt) iamt from (
 
	select  count(*) as nos,'GS' saltype,hsncode,invh_taxtag,  min(vargrp_type_name) descrip , 'MTS' uqc,sum(invh_netamt-invh_tcs_amt) totalvalue,round(sum(invh_totwt)/1000,3) qty ,sum(invh_taxableamt) txval , max(invh_cgst_per) cgstper,max(invh_sgst_per) sgstper,max(invh_igst_per) igstper, sum(invh_sgst_amt) samt , sum(invh_cgst_amt) camt , sum(invh_igst_amt) iamt   from trnsal_invoice_header  h, (
    select invt_compcode,invt_fincode,invt_seqno,max(invt_hsncode) hsncode,min(vargrp_type_name) vargrp_type_name from trnsal_invoice_trailer , masprd_variety , masprd_type   where invt_compcode = 1  and invt_fincode = fincode   and invt_item =  var_groupcode and    var_typecode =  vargrp_type_code and   invt_compcode = 1  and invt_fincode = fincode  group by invt_compcode,invt_fincode,invt_seqno
	)  t where 
	invh_comp_code = invt_compcode and invh_fincode = invt_fincode and  invh_seqno = invt_seqno and
	invh_comp_code = 1  and invh_fincode = fincode  and  invh_date between fromdate and todate   and invh_netamt > 0 group by hsncode,invh_taxtag
    
    ) a1 group by     saltype, hsncode ,descrip, cgstper,sgstper,igstper 
 
 ) a2  group by     saltype, hsncode , gstper
    
   union all     
 
    
    select count(*) as nos,'OS' saltype, salitem_hsn hsncode, max(salitem_name) descrip,uom_short_name uqc,sum(os_netamt) totalvalue ,
    sum(qty) qty,sum(txval) txval,os_cgstper cgstper,os_sgstper sgstper,os_igstper igstper,sum(samt) samt,sum(camt) camt,sum(iamt) iamt  from
     (
	 select  salitem_hsn,salitem_name,os_netamt,os_cgstper,os_sgstper,os_igstper,sum(os_qty) as qty,sum(os_taxable) txval,sum(os_cgst) camt,sum(os_sgst) samt,sum(os_igst) iamt,uom_short_name
	 from trn_other_sales join  massal_customer on os_custcode = cust_code 
	 join mas_othersales_item_master on os_item = salitem_code
	 join mas_uom on  salitem_uom = uom_code
	 where os_netamt > 0 and  os_compcode = compcode and os_fincode = fincode and os_date between fromdate and todate  
	 group by salitem_hsn,salitem_name,os_netamt,os_cgstper,os_sgstper,os_igstper,uom_short_name
          ) hsn1  group by salitem_hsn,os_cgstper ,os_sgstper,os_igstper,uom_short_name
          
union all   
-- SALES RETURN - CREDIT NOTE    
