CREATE DEFINER=`root`@`%` PROCEDURE `spacc_rep_hsnwise_sales02052024`(compcode int,fincode int,fromdate date,todate date)
BEGIN
select 
  sum(noofrec) noofrec, saltype,hsncode, descrip, 'GOODS' supply, uqc, sum(totalvalue) totalvalue, sum(qty) qty, sum(taxval) taxval , rt taxrate, sum(samt) samt, sum(camt) camt, sum(iamt) iamt , sum(samt) + sum(camt) + sum(iamt) totaltaxamt ,0 as cessamt, sum(taxval) + sum(samt) + sum(camt) + sum(iamt) subtotal
from 
(
select  sum(nos) noofrec,
