(
	select  count(*) as nos,'GS' saltype,hsncode,GROUP_CONCAT( DISTINCT  vargrp_type_name) as descrip , 'MTS' uqc,sum(invh_netamt-invh_tcs_amt) totalvalue,round(sum(invh_totwt)/1000,3) qty ,sum(invh_taxableamt) txval , invh_cgst_per cgstper,invh_sgst_per sgstper,invh_igst_per igstper, sum(invh_sgst_amt) samt , sum(invh_cgst_amt) camt , sum(invh_igst_amt) iamt   from trnsal_invoice_header  h, (
    select invt_compcode,invt_fincode,invt_seqno,max(invt_hsncode) hsncode,vargrp_type_name from trnsal_invoice_trailer , masprd_variety , masprd_type   where invt_compcode = compcode and invt_fincode = fincode  and invt_item =  var_groupcode and    var_typecode =  vargrp_type_code and   invt_compcode = compcode and invt_fincode = fincode group by invt_compcode,invt_fincode,invt_seqno,vargrp_type_name 
	)  t where 
	invh_comp_code = invt_compcode and invh_fincode = invt_fincode and  invh_seqno = invt_seqno and
	invh_comp_code = compcode and invh_fincode = fincode and  invh_date between fromdate and todate and invh_netamt > 0 group by hsncode,invh_cgst_per,invh_sgst_per,invh_igst_per
    
    
    UNION ALL
    
    select count(*) as nos,'OS' saltype, salitem_hsn hsncode, salitem_name descrip,'MTS' uqc,sum(os_netamt) totalvalue ,
    sum(qty) qty,sum(txval) txval,os_cgstper cgstper,os_sgstper sgstper,os_igstper igstper,sum(samt) samt,sum(camt) camt,sum(iamt) iamt  from
     (
	 select  salitem_hsn,salitem_name,os_netamt,os_cgstper,os_sgstper,os_igstper,sum(os_qty) as qty,sum(os_taxable) txval,sum(os_cgst) camt,sum(os_sgst) samt,sum(os_igst) iamt
	 from trn_other_sales join  massal_customer on os_custcode = cust_code 
	 join mas_othersales_item_master on os_item = salitem_code
	 where os_netamt > 0 and  os_compcode = compcode and os_fincode = fincode and os_date between fromdate and todate  
	 group by salitem_hsn,salitem_name,os_netamt,os_cgstper,os_sgstper,os_igstper
          ) hsn1  group by salitem_hsn,salitem_name,os_cgstper ,os_sgstper,os_igstper
union all   
     
select  count(*) as nos,saltype,hsncode,descrip,uqc,sum(dbcr_value)*-1 totalvalue,  0 qty, sum(dbcrt_taxable*-1) txval, 
 dbcrt_cgstper cgstper,dbcrt_sgstper sgstper,dbcrt_igstper igstper,
sum(dbcrt_cgstvalue*-1) camt , sum(dbcrt_sgstvalue*-1) samt , sum(dbcrt_igstvalue*-1) iamt 
from (
select  'CN' saltype , dbcr_hsncode hsncode,
case when dbcr_hsncode = '48059200' then 'PLASTERBOARD /GYPSUM BOARD' 
 when dbcr_hsncode = '48052500' then 'BLUE BOARD BOARD' 
  when dbcr_hsncode = '47062000' then 'RECYCLED PULP' else
'Kraft Paper' end as descrip, 'MTS' uqc, dbcr_value,  0 qty, dbcrt_taxable, 
 dbcrt_cgstper , dbcrt_sgstper ,dbcrt_igstper ,
dbcrt_cgstvalue , dbcrt_sgstvalue , dbcrt_igstvalue
 from acc_dbcrnote_header h left join  acc_dbcrnote_trailer t on h.dbcr_seqno = t.dbcrt_seqno   
where dbcr_comp_code = compcode and dbcr_date between  fromdate and todate  and dbcr_type = 'CNG' and (dbcrt_cgstledcode = 1644 or dbcrt_sgstledcode = 1645 or  dbcrt_igstledcode = 1646) 
and  dbcrt_cgstvalue + dbcrt_sgstvalue+ dbcrt_igstvalue > 0 and dbcr_party_type = 'C'
)a1 group by saltype,hsncode,descrip,uqc
,dbcrt_cgstper ,dbcrt_sgstper ,dbcrt_igstper

union all   
-- debit note     
select  count(*) as nos,'CN' saltype , dbcr_hsncode hsncode, 
case when dbcr_hsncode = '48041900' then 'Kraft Paper' else
'Blue Board' 
end 

as descrip,
 'MTS' uqc, sum(dbcr_value) totalvalue,  0 qty, sum(dbcrt_taxable) txval, 
 dbcrt_cgstper cgstper,dbcrt_sgstper sgstper,dbcrt_igstper igstper,
sum(dbcrt_cgstvalue) camt , sum(dbcrt_sgstvalue) samt , sum(dbcrt_igstvalue) iamt 
 from acc_dbcrnote_header h left join  acc_dbcrnote_trailer t on h.dbcr_seqno = t.dbcrt_seqno   
where dbcr_comp_code = compcode and dbcr_date between fromdate and todate and dbcr_type = 'SDN' and (dbcrt_cgstledcode = 1644 or dbcrt_sgstledcode = 1645 or  dbcrt_igstledcode = 1646) 
and  dbcrt_cgstvalue + dbcrt_sgstvalue+ dbcrt_igstvalue > 0 and dbcr_party_type = 'C'
group by dbcr_hsncode,dbcrt_cgstper ,dbcrt_sgstper ,dbcrt_igstper
) a1 
group by saltype, hsncode, descrip, uqc,cgstper,sgstper,igstper
) aa1 
group by  saltype,hsncode, descrip, uqc,rt order by hsncode; 

