	 group by salitem_hsn,salitem_name,os_netamt,os_cgstper,os_sgstper,os_igstper,uom_short_name
          ) hsn1  group by salitem_hsn,os_cgstper ,os_sgstper,os_igstper,uom_short_name
          
union all   
-- SALES RETURN - CREDIT NOTE    
select  count(*) as nos,saltype,hsncode,descrip,uqc,sum(dbcr_value)*-1 totalvalue,  dbcr_qty*-1 qty, sum(dbcrt_taxable*-1) txval, 
 dbcrt_cgstper cgstper,dbcrt_sgstper sgstper,dbcrt_igstper igstper,
sum(dbcrt_cgstvalue*-1) camt , sum(dbcrt_sgstvalue*-1) samt , sum(dbcrt_igstvalue*-1) iamt 
from (
select  'GS' saltype , dbcr_hsncode hsncode,
case when dbcr_hsncode = '48059200' then 'PLASTERBOARD LINER PAPER' 
 when dbcr_hsncode = '48052500' then 'BLUE BOARD' 
  when dbcr_hsncode = '47062000' then 'RECYCLED PULP' else
'KRAFT PAPER' end as descrip, 'MTS' uqc, dbcr_value,  dbcr_qty, dbcrt_taxable, 
 dbcrt_cgstper , dbcrt_sgstper ,dbcrt_igstper ,
dbcrt_cgstvalue , dbcrt_sgstvalue , dbcrt_igstvalue
 from acc_dbcrnote_header h left join  acc_dbcrnote_trailer t on h.dbcr_seqno = t.dbcrt_seqno  
  join massal_customer on dbcr_partycode = cust_code and find_in_set(cust_gst_type,gsttype)
where dbcr_comp_code = compcode and dbcr_date between  fromdate and todate  and dbcr_type = 'CNG' and (dbcrt_cgstledcode = 1644 or dbcrt_sgstledcode = 1645 or  dbcrt_igstledcode = 1646 or  dbcrt_igstledcode = 5133) 
and  dbcrt_cgstvalue + dbcrt_sgstvalue+ dbcrt_igstvalue > 0 and dbcr_party_type = 'C' and  dbcr_reason = 'SAL RETURN'
)a1 group by saltype,hsncode,descrip,uqc,dbcr_qty
,dbcrt_cgstper ,dbcrt_sgstper ,dbcrt_igstper
union all   
     -- OTHER CREDIT NOTES
select  count(*) as nos,saltype,hsncode,descrip,uqc,sum(dbcr_value)*-1 totalvalue,  0 qty, sum(dbcrt_taxable*-1) txval, 
 dbcrt_cgstper cgstper,dbcrt_sgstper sgstper,dbcrt_igstper igstper,
sum(dbcrt_cgstvalue*-1) camt , sum(dbcrt_sgstvalue*-1) samt , sum(dbcrt_igstvalue*-1) iamt 
from (
select  'CN' saltype , dbcr_hsncode hsncode,
case when dbcr_hsncode = '48059200' then 'PLASTERBOARD LINER PAPER' 
 when dbcr_hsncode = '48052500' then 'BLUE BOARD' 
  when dbcr_hsncode = '47062000' then 'RECYCLED PULP' else
'KRAFT PAPER' end as descrip, 'MTS' uqc, dbcr_value, dbcr_qty , dbcrt_taxable, 
 dbcrt_cgstper , dbcrt_sgstper ,dbcrt_igstper ,
dbcrt_cgstvalue , dbcrt_sgstvalue , dbcrt_igstvalue
 from acc_dbcrnote_header h left join  acc_dbcrnote_trailer t on h.dbcr_seqno = t.dbcrt_seqno   
 join massal_customer on dbcr_partycode = cust_code and find_in_set(cust_gst_type,gsttype)
where dbcr_comp_code = compcode and dbcr_date between  fromdate and todate  and dbcr_type = 'CNG' and (dbcrt_cgstledcode = 1644 or dbcrt_sgstledcode = 1645 or  dbcrt_igstledcode = 1646 or  dbcrt_igstledcode = 5133) 
and  dbcrt_cgstvalue + dbcrt_sgstvalue+ dbcrt_igstvalue > 0 and dbcr_party_type = 'C' and  dbcr_reason != 'SAL RETURN'
)a1 group by saltype,hsncode,descrip,uqc,dbcr_qty
,dbcrt_cgstper ,dbcrt_sgstper ,dbcrt_igstper

union all   
-- debit note     
select  count(*) as nos,'CN' saltype , dbcr_hsncode hsncode, 
case when dbcr_hsncode = '48059200' then 'PLASTERBOARD LINER PAPER' 
 when dbcr_hsncode = '48052500' then 'BLUE BOARD' 
  when dbcr_hsncode = '47062000' then 'RECYCLED PULP' else
'KRAFT PAPER' end as descrip,
 'MTS' uqc, sum(dbcr_value) totalvalue,  0 qty, sum(dbcrt_taxable) txval, 
 dbcrt_cgstper cgstper,dbcrt_sgstper sgstper,dbcrt_igstper igstper,
sum(dbcrt_cgstvalue) camt , sum(dbcrt_sgstvalue) samt , sum(dbcrt_igstvalue) iamt 
 from acc_dbcrnote_header h left join  acc_dbcrnote_trailer t on h.dbcr_seqno = t.dbcrt_seqno
 join massal_customer on dbcr_partycode = cust_code and find_in_set(cust_gst_type,gsttype)
where dbcr_comp_code = compcode and dbcr_date between fromdate and todate and dbcr_type = 'SDN' and (dbcrt_cgstledcode = 1644 or dbcrt_sgstledcode = 1645 or  dbcrt_igstledcode = 1646 or  dbcrt_igstledcode = 5133) 
and  dbcrt_cgstvalue + dbcrt_sgstvalue+ dbcrt_igstvalue > 0 and dbcr_party_type = 'C'
group by dbcr_hsncode,dbcrt_cgstper ,dbcrt_sgstper ,dbcrt_igstper
) a1 
group by saltype, hsncode, descrip, uqc,cgstper,sgstper,igstper
) aa1 
group by  hsncode,  uqc,rt order by hsncode; 
*/

END ;;
DELIMITER ;
