DELIMITER ;;
CREATE DEFINER=`root`@`%` PROCEDURE `spacc_rep_hsnwise_sales_Abstract_02062025`(compcode int,fincode int,fromdate date,todate date)
BEGIN
select 
  sum(noofrec) noofrec, hsncode, max(descrip) descrip, 'GOODS' supply, uqc, sum(totalvalue) totalvalue, sum(qty) qty, sum(taxval) taxval , rt taxrate, sum(samt) samt, sum(camt) camt, sum(iamt) iamt , sum(samt) + sum(camt) + sum(iamt) totaltaxamt ,0 as cessamt, sum(taxval) + sum(samt) + sum(camt) + sum(iamt) subtotal
from 

(
select  sum(nos) noofrec,
saltype, hsncode, descrip, uqc, sum(totalvalue) totalvalue, sum(qty) qty, sum(txval) taxval , case when cgstper >0 then
cgstper+sgstper else igstper end as rt, sum(samt) samt, sum(camt) camt, sum(iamt) iamt
from 
(

 
 

select sum(nos) nos, saltype, hsncode, GROUP_CONCAT( DISTINCT  descrip)  descrip, uqc, sum(totalvalue) totalvalue,
 sum(qty) qty, sum(txval) txval,   max(cgstper) cgstper, max(sgstper) sgstper ,  max(igstper)  igstper, sum(samt) samt, sum(camt) camt, sum(iamt) iamt from (
 
 
select sum(nos) nos, saltype, hsncode, descrip, uqc, sum(totalvalue) totalvalue,
 sum(qty) qty, sum(txval) txval,   cgstper+sgstper+igstper gstper ,max(cgstper) cgstper, max(sgstper) sgstper ,  max(igstper)  igstper, sum(samt) samt, sum(camt) camt, sum(iamt) iamt from (
 
	select  count(*) as nos,'GS' saltype,hsncode,invh_taxtag,  min(vargrp_type_name) descrip , 'MTS' uqc,sum(invh_netamt-invh_tcs_amt) totalvalue,round(sum(invh_totwt)/1000,3) qty ,sum(invh_taxableamt) txval , max(invh_cgst_per) cgstper,max(invh_sgst_per) sgstper,max(invh_igst_per) igstper, sum(invh_sgst_amt) samt , sum(invh_cgst_amt) camt , sum(invh_igst_amt) iamt   from trnsal_invoice_header  h, (
    select invt_compcode,invt_fincode,invt_seqno,max(invt_hsncode) hsncode,min(vargrp_type_name) vargrp_type_name from trnsal_invoice_trailer , masprd_variety , masprd_type   where invt_compcode = 1  and invt_fincode = fincode   and invt_item =  var_groupcode and    var_typecode =  vargrp_type_code and   invt_compcode = 1  and invt_fincode = fincode  group by invt_compcode,invt_fincode,invt_seqno
	)  t where 
	invh_comp_code = invt_compcode and invh_fincode = invt_fincode and  invh_seqno = invt_seqno and
	invh_comp_code = 1  and invh_fincode = fincode  and  invh_date between fromdate and todate   and invh_netamt > 0 group by hsncode,invh_taxtag
    
    ) a1 group by     saltype, hsncode ,descrip, cgstper,sgstper,igstper 
 
 ) a2  group by     saltype, hsncode , gstper
    
   union all     
 
    
    select count(*) as nos,'OS' saltype, salitem_hsn hsncode, max(salitem_name) descrip,uom_short_name uqc,sum(os_netamt) totalvalue ,
    sum(qty) qty,sum(txval) txval,os_cgstper cgstper,os_sgstper sgstper,os_igstper igstper,sum(samt) samt,sum(camt) camt,sum(iamt) iamt  from
     (
	 select  salitem_hsn,salitem_name,os_netamt,os_cgstper,os_sgstper,os_igstper,sum(os_qty) as qty,sum(os_taxable) txval,sum(os_cgst) camt,sum(os_sgst) samt,sum(os_igst) iamt,uom_short_name
	 from trn_other_sales join  massal_customer on os_custcode = cust_code 
	 join mas_othersales_item_master on os_item = salitem_code
	 join mas_uom on  salitem_uom = uom_code
	 where os_netamt > 0 and  os_compcode = compcode and os_fincode = fincode and os_date between fromdate and todate  
	 group by salitem_hsn,salitem_name,os_netamt,os_cgstper,os_sgstper,os_igstper,uom_short_name
          ) hsn1  group by salitem_hsn,os_cgstper ,os_sgstper,os_igstper,uom_short_name
          
union all   
-- SALES RETURN - CREDIT NOTE    
select  count(*) as nos,saltype,hsncode,descrip,uqc,sum(dbcr_value)*-1 totalvalue,  dbcr_qty*-1 qty, sum(dbcrt_taxable*-1) txval, 
 dbcrt_cgstper cgstper,dbcrt_sgstper sgstper,dbcrt_igstper igstper,
sum(dbcrt_cgstvalue*-1) camt , sum(dbcrt_sgstvalue*-1) samt , sum(dbcrt_igstvalue*-1) iamt 
from (
select  'GS' saltype , dbcr_hsncode hsncode,
case when dbcr_hsncode = '48059200' then 'PLASTERBOARD LINER PAPER' 
 when dbcr_hsncode = '48052500' then 'BLUE BOARD' 
  when dbcr_hsncode = '47062000' then 'RECYCLED PULP' else
'KRAFT PAPER' end as descrip, 'MTS' uqc, dbcr_value,  dbcr_qty, dbcrt_taxable, 
 dbcrt_cgstper , dbcrt_sgstper ,dbcrt_igstper ,
dbcrt_cgstvalue , dbcrt_sgstvalue , dbcrt_igstvalue
 from acc_dbcrnote_header h left join  acc_dbcrnote_trailer t on h.dbcr_seqno = t.dbcrt_seqno   
where dbcr_comp_code = compcode and dbcr_date between  fromdate and todate  and dbcr_type = 'CNG' and (dbcrt_cgstledcode = 1644 or dbcrt_sgstledcode = 1645 or  dbcrt_igstledcode = 1646) 
and  dbcrt_cgstvalue + dbcrt_sgstvalue+ dbcrt_igstvalue > 0 and dbcr_party_type = 'C' and  dbcr_reason = 'SAL RETURN'
)a1 group by saltype,hsncode,descrip,uqc,dbcr_qty
,dbcrt_cgstper ,dbcrt_sgstper ,dbcrt_igstper
union all   
     -- OTHER CREDIT NOTES
select  count(*) as nos,saltype,hsncode,descrip,uqc,sum(dbcr_value)*-1 totalvalue,  0 qty, sum(dbcrt_taxable*-1) txval, 
 dbcrt_cgstper cgstper,dbcrt_sgstper sgstper,dbcrt_igstper igstper,
sum(dbcrt_cgstvalue*-1) camt , sum(dbcrt_sgstvalue*-1) samt , sum(dbcrt_igstvalue*-1) iamt 
from (
select  'CN' saltype , dbcr_hsncode hsncode,
case when dbcr_hsncode = '48059200' then 'PLASTERBOARD LINER PAPER' 
 when dbcr_hsncode = '48052500' then 'BLUE BOARD' 
  when dbcr_hsncode = '47062000' then 'RECYCLED PULP' else
'KRAFT PAPER' end as descrip, 'MTS' uqc, dbcr_value, dbcr_qty , dbcrt_taxable, 
 dbcrt_cgstper , dbcrt_sgstper ,dbcrt_igstper ,
dbcrt_cgstvalue , dbcrt_sgstvalue , dbcrt_igstvalue
 from acc_dbcrnote_header h left join  acc_dbcrnote_trailer t on h.dbcr_seqno = t.dbcrt_seqno   
where dbcr_comp_code = compcode and dbcr_date between  fromdate and todate  and dbcr_type = 'CNG' and (dbcrt_cgstledcode = 1644 or dbcrt_sgstledcode = 1645 or  dbcrt_igstledcode = 1646) 
and  dbcrt_cgstvalue + dbcrt_sgstvalue+ dbcrt_igstvalue > 0 and dbcr_party_type = 'C' and  dbcr_reason != 'SAL RETURN'
)a1 group by saltype,hsncode,descrip,uqc,dbcr_qty
,dbcrt_cgstper ,dbcrt_sgstper ,dbcrt_igstper

union all   
-- debit note     
select  count(*) as nos,'CN' saltype , dbcr_hsncode hsncode, 
case when dbcr_hsncode = '48059200' then 'PLASTERBOARD LINER PAPER' 
 when dbcr_hsncode = '48052500' then 'BLUE BOARD' 
  when dbcr_hsncode = '47062000' then 'RECYCLED PULP' else
'KRAFT PAPER' end as descrip,
 'MTS' uqc, sum(dbcr_value) totalvalue,  0 qty, sum(dbcrt_taxable) txval, 
 dbcrt_cgstper cgstper,dbcrt_sgstper sgstper,dbcrt_igstper igstper,
sum(dbcrt_cgstvalue) camt , sum(dbcrt_sgstvalue) samt , sum(dbcrt_igstvalue) iamt 
 from acc_dbcrnote_header h left join  acc_dbcrnote_trailer t on h.dbcr_seqno = t.dbcrt_seqno   
where dbcr_comp_code = compcode and dbcr_date between fromdate and todate and dbcr_type = 'SDN' and (dbcrt_cgstledcode = 1644 or dbcrt_sgstledcode = 1645 or  dbcrt_igstledcode = 1646) 
and  dbcrt_cgstvalue + dbcrt_sgstvalue+ dbcrt_igstvalue > 0 and dbcr_party_type = 'C'
group by dbcr_hsncode,dbcrt_cgstper ,dbcrt_sgstper ,dbcrt_igstper
) a1 
group by saltype, hsncode, descrip, uqc,cgstper,sgstper,igstper
) aa1 
group by  hsncode,  uqc,rt order by hsncode; 


END ;;
DELIMITER ;
