/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`%` PROCEDURE `spacc_rep_hsnwise_sales_Detailed`(compcode int,fincode int,fromdate date , todate date ,hsn varchar(8),vou_type varchar(2))
BEGIN
if vou_type = 'GS' then
	
    select  voudate , party,gstin ,voutype,vouno,uqc,totqty ,	totalamt,	taxableamt, igstamt, cgstamt, sgstamt,cessamt,invh_vouno
    from 
    (select  DATE_FORMAT(invh_date, '%d-%m-%Y') as voudate , cust_ref party,cust_gstin gstin ,case when invh_saltype = "TN" then "TN GST SALES" else "OS IGST SALES" end voutype,invh_invrefno vouno,'MTS' uqc,round(invh_totwt/1000,3)  as totqty ,
	invh_taxableamt+invh_sgst_amt+invh_cgst_amt+invh_igst_amt as totalamt,
	invh_taxableamt taxableamt, invh_igst_amt  igstamt, invh_cgst_amt cgstamt, invh_sgst_amt sgstamt,0 as cessamt,invh_vouno
	from trnsal_invoice_header a , massal_customer  b,  
	(select invt_compcode , invt_fincode ,invt_seqno,max(invt_hsncode) hsncode from trnsal_invoice_trailer where invt_hsncode = hsn and invt_compcode = compcode and invt_fincode = fincode group by  invt_compcode , invt_fincode ,invt_seqno) c
	where  invh_comp_code = invt_compcode and invh_fincode = invt_fincode and invh_seqno = invt_seqno  and  invh_party = cust_code and  invh_comp_code = compcode and invh_fincode = fincode and invh_date between fromdate and todate and invh_netamt > 0 and hsncode = hsn order by invh_date,invh_seqno 
    )a1  
    union all
		select  DATE_FORMAT(dbcr_date, '%d-%m-%Y') as voudate , cust_name party,cust_gstin gstin ,dbcr_type voutype,dbcr_vouno vouno,'MTS' uqc,dbcr_qty * -1 as totqty ,
        dbcr_value*-1 as totalamt,dbcrt_taxable*-1 taxableamt, dbcrt_igstvalue*-1  igstamt, dbcrt_cgstvalue*-1 cgstamt, dbcrt_sgstvalue*-1 sgstamt,0 as cessamt,dbcr_vouno invh_vouno from
        acc_dbcrnote_header , acc_dbcrnote_trailer , massal_customer where dbcr_partycode = cust_code and  dbcr_seqno = dbcrt_seqno and  dbcr_comp_code = compcode and dbcr_finid = fincode and dbcr_date between  fromdate and todate and dbcr_party_type = 'C' and dbcr_type in ('CNG')  and  dbcr_reason = 'SAL RETURN' and dbcr_hsncode = hsn;       
    
 else
    if vou_type = 'OS' then
        select  voudate , party,gstin ,voutype,vouno,uqc,totqty ,totalamt,taxableamt, igstamt, cgstamt, sgstamt,cessamt,invh_vouno
        from
        (
        select  DATE_FORMAT(os_date, '%d-%m-%Y') as voudate , cust_name party,cust_gstin gstin ,case when os_state_type = "TNOS" then "TNOS GST SALES" else "OSOS IGST SALES" end voutype,os_invno vouno,'MTS' uqc,os_qty as totqty ,
		-- os_taxable+os_sgst+os_cgst+os_igst as totalamt,os_taxable taxableamt, os_igst  igstamt, os_cgst cgstamt, os_sgst sgstamt,0 as cessamt,os_acvou_no invh_vouno		
        os_netamt as totalamt,os_taxable taxableamt, os_igst  igstamt, os_cgst cgstamt, os_sgst sgstamt,0 as cessamt,os_acvou_no invh_vouno		
        from trn_other_sales join  massal_customer on os_custcode = cust_code 
		join mas_othersales_item_master on os_item = salitem_code and salitem_hsn = hsn 
		where  os_compcode = compcode and os_fincode = fincode  and os_date between fromdate and todate  order by os_date
       ) a1;       
    else     
    if vou_type = 'CN' then
        select  voudate , party,gstin ,voutype,vouno,uqc,totqty ,totalamt,taxableamt, igstamt, cgstamt, sgstamt,cessamt,invh_vouno
        from
        (
        select  DATE_FORMAT(dbcr_date, '%d-%m-%Y') as voudate , cust_name party,cust_gstin gstin ,dbcr_type voutype,dbcr_vouno vouno,'MTS' uqc,dbcr_qty * -1 as totqty ,
        dbcr_value*-1 as totalamt,dbcrt_taxable*-1 taxableamt, dbcrt_igstvalue*-1  igstamt, dbcrt_cgstvalue*-1 cgstamt, dbcrt_sgstvalue*-1 sgstamt,0 as cessamt,dbcr_vouno invh_vouno from
        acc_dbcrnote_header , acc_dbcrnote_trailer , massal_customer where dbcr_partycode = cust_code and  dbcr_seqno = dbcrt_seqno and  dbcr_comp_code = compcode and dbcr_finid = fincode and dbcr_date between  fromdate and todate and dbcr_party_type = 'C' and dbcr_type in ('CNG')  and  dbcr_reason != 'SAL RETURN'  and dbcr_hsncode = hsn
        union all
        select  DATE_FORMAT(dbcr_date, '%d-%m-%Y') as voudate , cust_name party,cust_gstin gstin ,dbcr_type voutype,dbcr_vouno vouno,'MTS' uqc,dbcr_qty as totqty ,
        dbcr_value as totalamt,dbcrt_taxable taxableamt, dbcrt_igstvalue  igstamt, dbcrt_cgstvalue cgstamt, dbcrt_sgstvalue sgstamt,0 as cessamt,dbcr_vouno invh_vouno from
        acc_dbcrnote_header , acc_dbcrnote_trailer , massal_customer where dbcr_partycode = cust_code and  dbcr_seqno = dbcrt_seqno and  dbcr_comp_code = compcode and dbcr_finid = fincode and dbcr_date between  fromdate and todate and dbcr_party_type = 'C' and dbcr_type in ('SDN')   and dbcr_hsncode = hsn      
  )a1;
        
    else
        select  voudate , party,gstin ,voutype,vouno,uqc,totqty ,totalamt,taxableamt, igstamt, cgstamt, sgstamt,cessamt,invh_vouno
        from
        (
        select  DATE_FORMAT(os_date, '%d-%m-%Y') as voudate , cust_name party,cust_gstin gstin ,case when os_state_type = "TNOS" then "TNOS GST SALES" else "OSOS IGST SALES" end voutype,os_invno vouno,'MTS' uqc,os_qty as totqty ,

		-- os_taxable+os_sgst+os_cgst+os_igst as totalamt,os_taxable taxableamt, os_igst  igstamt, os_cgst cgstamt, os_sgst sgstamt,0 as cessamt,os_acvou_no invh_vouno		
        os_netamt as totalamt,os_taxable taxableamt, os_igst  igstamt, os_cgst cgstamt, os_sgst sgstamt,0 as cessamt,os_acvou_no invh_vouno		
        from trn_other_sales join  massal_customer on os_custcode = cust_code 
		join mas_othersales_item_master on os_item = salitem_code and salitem_hsn = hsn 
		where  os_compcode = compcode and os_fincode = fincode  and os_date between fromdate and todate  order by os_date
        ) a1;
    end if;
end if;
end if;

END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `spacc_rep_hsnwise_sales_finished` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`%` PROCEDURE `spacc_rep_hsnwise_sales_finished`(compcode int,fincode int,fromdate datetime , todate datetime ,hsn varchar(8))
BEGIN
select  DATE_FORMAT(invh_date, '%d-%m-%Y') as voudate , cust_ref party,cust_gstin gstin ,case when invh_saltype = "TN" then "TN GST SALES" else "OS IGST SALES" end voutype,invh_invrefno vouno,'NTS' uqc,round(invh_totwt/1000,3)  as totqty ,
invh_taxableamt+invh_sgst_amt+invh_cgst_amt+invh_igst_amt as totalamt,
invh_taxableamt taxableamt, invh_igst_amt  igstamt, invh_cgst_amt cgstamt, invh_sgst_amt sgstamt,0 as cessamt,invh_vouno
from trnsal_invoice_header a , massal_customer  b,  
(select invt_compcode , invt_fincode ,invt_seqno,max(invt_hsncode) hsncode from trnsal_invoice_trailer where invt_hsncode = hsn and invt_compcode = 1 and invt_fincode = 23 group by  invt_compcode , invt_fincode ,invt_seqno) c
where  invh_comp_code = invt_compcode and invh_fincode = invt_fincode and invh_seqno = invt_seqno  and  invh_party = cust_code and  invh_comp_code = compcode and invh_fincode = fincode and invh_date between fromdate and todate and invh_netamt > 0 order by invh_date,invh_seqno ;    
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `spacc_rep_hsnwise_sales_HSN_Detailed` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`%` PROCEDURE `spacc_rep_hsnwise_sales_HSN_Detailed`(compcode int,fincode int,fromdate date , todate date ,hsn varchar(8))
BEGIN
    select  voudate , party,gstin ,voutype,vouno,uqc,totqty ,	totalamt,	taxableamt, igstamt, cgstamt, sgstamt,cessamt,invh_vouno
    from 
    (select  DATE_FORMAT(invh_date, '%d-%m-%Y') as voudate , cust_ref party,cust_gstin gstin ,case when invh_saltype = "TN" then "TN GST SALES" else "OS IGST SALES" end voutype,invh_invrefno vouno,'MTS' uqc,round(invh_totwt/1000,3)  as totqty ,
	invh_taxableamt+invh_sgst_amt+invh_cgst_amt+invh_igst_amt as totalamt,
	invh_taxableamt taxableamt, invh_igst_amt  igstamt, invh_cgst_amt cgstamt, invh_sgst_amt sgstamt,0 as cessamt,invh_vouno
	from trnsal_invoice_header a , massal_customer  b,  
	(select invt_compcode , invt_fincode ,invt_seqno,max(invt_hsncode) hsncode from trnsal_invoice_trailer where invt_hsncode = hsn and invt_compcode = compcode and invt_fincode = fincode group by  invt_compcode , invt_fincode ,invt_seqno) c
	where  invh_comp_code = invt_compcode and invh_fincode = invt_fincode and invh_seqno = invt_seqno  and  invh_party = cust_code and  invh_comp_code = compcode and invh_fincode = fincode and invh_date between fromdate and todate and invh_netamt > 0 and hsncode = hsn order by invh_date,invh_seqno 
    )a1  
    union all
		select  DATE_FORMAT(dbcr_date, '%d-%m-%Y') as voudate , cust_name party,cust_gstin gstin ,dbcr_type voutype,dbcr_vouno vouno,'MTS' uqc,dbcr_qty * -1 as totqty ,
        dbcr_value*-1 as totalamt,dbcrt_taxable*-1 taxableamt, dbcrt_igstvalue*-1  igstamt, dbcrt_cgstvalue*-1 cgstamt, dbcrt_sgstvalue*-1 sgstamt,0 as cessamt,dbcr_vouno invh_vouno from
        acc_dbcrnote_header , acc_dbcrnote_trailer , massal_customer where dbcr_partycode = cust_code and  dbcr_seqno = dbcrt_seqno and  dbcr_comp_code = compcode and dbcr_finid = fincode and dbcr_date between  fromdate and todate and dbcr_party_type = 'C' and dbcr_type in ('CNG')  and  dbcr_reason = 'SAL RETURN' and dbcr_hsncode = hsn       
  union all     
        select  voudate , party,gstin ,voutype,vouno,uqc,totqty ,totalamt,taxableamt, igstamt, cgstamt, sgstamt,cessamt,invh_vouno
        from
        (
        select  DATE_FORMAT(os_date, '%d-%m-%Y') as voudate , cust_name party,cust_gstin gstin ,case when os_state_type = "TNOS" then "TNOS GST SALES" else "OSOS IGST SALES" end voutype,os_invno vouno,'MTS' uqc,os_qty as totqty ,
		-- os_taxable+os_sgst+os_cgst+os_igst as totalamt,os_taxable taxableamt, os_igst  igstamt, os_cgst cgstamt, os_sgst sgstamt,0 as cessamt,os_acvou_no invh_vouno		
        os_netamt as totalamt,os_taxable taxableamt, os_igst  igstamt, os_cgst cgstamt, os_sgst sgstamt,0 as cessamt,os_acvou_no invh_vouno		
        from trn_other_sales join  massal_customer on os_custcode = cust_code 
		join mas_othersales_item_master on os_item = salitem_code and salitem_hsn = hsn 
		where  os_compcode = compcode and os_fincode = fincode  and os_date between fromdate and todate  order by os_date
       ) a1       
  union all     
  
        select  voudate , party,gstin ,voutype,vouno,uqc,totqty ,totalamt,taxableamt, igstamt, cgstamt, sgstamt,cessamt,invh_vouno
        from
        (
        select  DATE_FORMAT(dbcr_date, '%d-%m-%Y') as voudate , cust_name party,cust_gstin gstin ,dbcr_type voutype,dbcr_vouno vouno,'MTS' uqc,dbcr_qty * -1 as totqty ,
        dbcr_value*-1 as totalamt,dbcrt_taxable*-1 taxableamt, dbcrt_igstvalue*-1  igstamt, dbcrt_cgstvalue*-1 cgstamt, dbcrt_sgstvalue*-1 sgstamt,0 as cessamt,dbcr_vouno invh_vouno from
        acc_dbcrnote_header , acc_dbcrnote_trailer , massal_customer where dbcr_partycode = cust_code and  dbcr_seqno = dbcrt_seqno and  dbcr_comp_code = compcode and dbcr_finid = fincode and dbcr_date between  fromdate and todate and dbcr_party_type = 'C' and dbcr_type in ('CNG')  and  dbcr_reason != 'SAL RETURN'  and dbcr_hsncode = hsn
        union all
        select  DATE_FORMAT(dbcr_date, '%d-%m-%Y') as voudate , cust_name party,cust_gstin gstin ,dbcr_type voutype,dbcr_vouno vouno,'MTS' uqc,dbcr_qty as totqty ,
        dbcr_value as totalamt,dbcrt_taxable taxableamt, dbcrt_igstvalue  igstamt, dbcrt_cgstvalue cgstamt, dbcrt_sgstvalue sgstamt,0 as cessamt,dbcr_vouno invh_vouno from
        acc_dbcrnote_header , acc_dbcrnote_trailer , massal_customer where dbcr_partycode = cust_code and  dbcr_seqno = dbcrt_seqno and  dbcr_comp_code = compcode and dbcr_finid = fincode and dbcr_date between  fromdate and todate and dbcr_party_type = 'C' and dbcr_type in ('SDN')   and dbcr_hsncode = hsn      
  )a1;
        
    

END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `spacc_rep_indent_datewise` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`%` PROCEDURE `spacc_rep_indent_datewise`(
compcode tinyint,
finid tinyint,
fromdate date,
todate date
)
BEGIN
SELECT
    trnpur_indent.ind_comp_code, trnpur_indent.ind_no, trnpur_indent.ind_date, trnpur_indent.ind_fin_code, trnpur_indent.ind_qty, trnpur_indent.ind_po_qty, trnpur_indent.ind_rec_qty, trnpur_indent.ind_due_date, trnpur_indent.ind_status, trnpur_indent.ind_remarks, trnpur_indent.ind_machine,
    maspur_item_header.item_name,
    mas_company.company_name,
    mas_dept.dept_name,
    mas_uom.uom_short_name
FROM
    { oj (((trnpur_indent trnpur_indent INNER JOIN mas_company mas_company ON
        trnpur_indent.ind_comp_code = mas_company.company_code)
     INNER JOIN mas_dept mas_dept ON
        trnpur_indent.ind_dept_code = mas_dept.dept_code)
     INNER JOIN maspur_item_header maspur_item_header ON
        trnpur_indent.ind_item_code = maspur_item_header.item_code)
     INNER JOIN mas_uom mas_uom ON
        maspur_item_header.item_uom = mas_uom.uom_code}
WHERE
    trnpur_indent.ind_comp_code = compcode AND
    trnpur_indent.ind_fin_code = finid AND
    trnpur_indent.ind_date >= fromdate AND
    trnpur_indent.ind_date <= todate; 
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `spacc_rep_json` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`%` PROCEDURE `spacc_rep_json`(compcode int,fincode int,fromdate date , todate date)
BEGIN
SET SESSION group_concat_max_len = 18446744073709551615;
select concat('{"gstin":"33AALCS4958D1Z7","fp":"',right(concat(0,month(fromdate),year(fromdate)),6),'",',group_concat(newjson),'}') jsonnew from (
select GROUP_CONCAT(concat('"',saltype,'":[',jsonnew,']')) newjson  from 
(
select saltype ,GROUP_CONCAT(jsonnew)  jsonnew from  (

-- -
select  saltype, concat('{"ctin":"',partygstin,'","inv":[' , SUBSTRING(jsonnew,1,length(jsonnew)-1)  ,']}' ) jsonnew from  (
select "b2b" saltype, partygstin,GROUP_CONCAT(gsinv SEPARATOR '')  jsonnew from  (
select cust_gstin partygstin,invh_date, 
 case when invh_igst_amt >0 then 
concat('{"inum":"',invh_invrefno,'",','"idt":"', DATE_FORMAT(invh_date, "%d-%m-%Y") ,'",',
'"val":',invh_netamt,',',
'"pos":"',left(cust_gstin,2),'",',
'"rchrg":"N",','"itms":[{"num":1,"itm_det":{"txval":',invh_taxableamt,',',
'"rt":',round(invh_igst_per,0),',','"iamt":',invh_igst_amt,',','"csamt":0.00}}],','"inv_typ":"R"},'
) 
else
concat('{"inum":"',invh_invrefno,'",','"idt":"', DATE_FORMAT(invh_date, "%d-%m-%Y") ,'",',
'"val":',invh_netamt,',','"pos":"',left(cust_gstin,2),'",','"rchrg":"N",','"itms":[{"num":1,"itm_det":{"txval":',invh_taxableamt,',',
'"rt":',round(invh_cgst_per+invh_sgst_per,0),',','"camt":',invh_cgst_amt,',','"samt":',invh_sgst_amt,',','"csamt":0.00}}],','"inv_typ":"R"},'
) end
as gsinv
from trnsal_invoice_header , massal_customer  where invh_party = cust_code and  invh_comp_code = compcode and invh_fincode = fincode and invh_netamt > 0 and invh_date between fromdate and todate 
-- -
union all

select partygstin,os_date, 
case when iamt >0 then 
concat('{"inum":"',os_invno,'",','"idt":"', DATE_FORMAT(os_date, "%d-%m-%Y") ,'",',
'"val":',val,',',
'"pos":"',left(partygstin,2),'",',
'"rchrg":"N",','"itms":[{"num":1,"itm_det":{"txval":',txval,',',
'"rt":',round(os_igstper,0),',','"iamt":',iamt,',','"csamt":0.00}}],','"inv_typ":"R"},'
) 
  else
  
  concat('{"inum":"',os_invno,'",','"idt":"', DATE_FORMAT(os_date, "%d-%m-%Y") ,'",',
'"val":',val,',','"pos":"',left(partygstin,2),'",','"rchrg":"N",','"itms":[{"num":1,"itm_det":{"txval":',txval,',',
'"rt":',round(os_sgstper+os_cgstper,0),',','"camt":',camt,',','"samt":',samt,',','"csamt":0.00}}],','"inv_typ":"R"},'
)
end gsinv
  from
( select  cust_gstin partygstin,os_invno,os_date,sum(round(os_netamt,0)) val,sum(os_taxable) txval , sum(os_igst) iamt , sum(os_cgst)  camt , sum(os_sgst) samt , 0  'csamt' ,os_cgstper,os_sgstper,os_igstper
 from trn_other_sales join  massal_customer on os_custcode = cust_code 
 where  os_compcode = compcode and os_fincode = fincode and os_date between fromdate and todate and cust_gst_type <> 'U' and os_netamt >0
 group by cust_gstin,os_invno,os_date ,os_cgstper,os_sgstper,os_igstper) fs1
 

)gsinv2  group by partygstin 

)gsinv3
-- b2cs
union all
select  "b2cs" saltype, 
case when iamt >0 then 
concat('{"rt":',round(os_igstper,0),',','"sply_ty":"INTER",',
'"pos":"',state_codeno,'",',
'"typ":"OE",',
'"txval":',txval,',',
'"iamt":',iamt,',','"csamt":0.00}'
) 
else
concat('{"rt":',round(os_cgstper+os_sgstper,0),',','"sply_ty":"INTRA",',
'"pos":"',state_codeno,'",',
'"typ":"OE",',
'"txval":',txval,',',
'"camt":',camt,',','"samt":',samt,',','"csamt":0.00}'
) 
 end as jsonnew
 from  (
 select  state_codeno,os_cgstper,os_sgstper,os_igstper,sum(os_taxable) txval , sum(os_igst) iamt , sum(os_cgst)  camt , sum(os_sgst) samt , 0  'csamt' 
 from trn_other_sales join  massal_customer on os_custcode = cust_code   left join mas_state on state_code = cust_state
 where  os_compcode = compcode and os_fincode = fincode and os_date between fromdate and todate and cust_gst_type = 'U' and os_netamt > 0
 group by state_codeno,os_cgstper,os_sgstper,os_igstper
) a1

union all

-- cdnr
select  saltype, concat('{"ctin":"',cust_gstin,'","nt":[' , SUBSTRING(jsonnew,1,length(jsonnew))  ,']}' ) jsonnew from  (

select "cdnr" saltype, cust_gstin,GROUP_CONCAT(cdnr SEPARATOR ',')  jsonnew from  (
select  cust_gstin,case when dbcrt_igstvalue > 0  then 
concat('{"ntty":"C",','"nt_num":"', dbcr_vouno,'",',
'"nt_dt":"', DATE_FORMAT(dbcr_date, "%d-%m-%Y") ,'",',
'"pos":"',left(cust_gstin,2),'",',
'"rchrg":"N",','"inv_typ":"R",',
'"val":',dbcr_value,',',
'"itms":[{"num":1,"itm_det":{"rt":',round(dbcrt_igstper,0),',"txval":',dbcrt_grossvalue,',',
'"iamt":',dbcrt_igstvalue,',','"csamt":0.00}}]}'
) 
else
concat('{"ntty":"C",','"nt_num":"', dbcr_vouno,'",',
'"nt_dt":"', DATE_FORMAT(dbcr_date, "%d-%m-%Y") ,'",',
'"pos":"',left(cust_gstin,2),'",',
'"rchrg":"N",','"inv_typ":"R",',
'"val":',dbcr_value,',',
'"itms":[{"num":1,"itm_det":{"rt":',round(dbcrt_cgstper+dbcrt_sgstper,0),',"txval":',dbcrt_grossvalue,',',
'"camt":',dbcrt_cgstvalue,',','"samt":',dbcrt_sgstvalue,',','"csamt":0.00}}]}'
) 
end 
as cdnr  from acc_dbcrnote_header h left join  acc_dbcrnote_trailer t on h.dbcr_seqno = t.dbcrt_seqno   
left join massal_customer on dbcr_partycode = cust_code 
where dbcr_comp_code = compcode and dbcr_date between fromdate and todate and dbcr_type = 'CNG' and (dbcrt_cgstledcode = 1644 or dbcrt_sgstledcode = 1645 or  dbcrt_igstledcode = 1646)  and  dbcrt_grossvalue > 0
)gsinv2  group by cust_gstin 

)gsinv3

-- -  
)gsinv4 group by saltype
) gstinv


union 

SELECT 
  CONCAT('"hsn":{',
    GROUP_CONCAT(
      CONCAT('"', supplytype, '":[', hsn, ']')
      SEPARATOR ','
    ),
  '}') AS hsn from (
select supplytype,group_concat(hsn) hsn from (
select  supplytype,
concat('{"num":',num,',','"hsn_sc":"', hsncode ,'",',
 '"txval":',txval,',',        
 '"iamt":',iamt,',',    
 '"camt":',camt,',',    
 '"samt":',samt,',', 
 '"csamt":',0.00,',', 
 '"desc":"",',    
 '"user_desc":"',descrip,'",',   
 '"uqc":"',uqc,'",'    
 '"qty":',qty,',',    
 '"rt":',rt,'}'
) as hsn from
(


select ROW_NUMBER() OVER (PARTITION BY supplytype ORDER BY hsncode) AS num, hsncode, supplytype ,  cust_gst_type , descrip, uqc, rt,  qty, txval ,  samt , camt, iamt, csamt from (
select 
case when cust_gst_type = "R" then "hsn_b2b" else "hsn_b2c" end as supplytype ,
cust_gst_type,
seqno,hsncode,  GROUP_CONCAT( DISTINCT  descrip) descrip, uqc, rt, Cast(sum(qty) as decimal(10,2)) as qty, sum(taxval) txval , sum(samt) samt , sum(camt) camt, sum(iamt)iamt, sum(csamt) csamt from 
(
 select 
 cust_gst_type,seqno, hsncode,   descrip, 'MTS' uqc,  rt , sum(qty) qty , sum(txval) taxval, sum(samt) samt , sum(camt) camt , sum(iamt) iamt, sum(csamt) csamt from
 (
 
select cust_gst_type,"1" as seqno, hsncode, min(vargrp_type_name)  descrip , 'MTS' uqc,invh_cgst_per+invh_sgst_per+invh_igst_per rt,round(sum(invh_totwt)/1000,2) qty ,sum(invh_taxableamt) txval , sum(invh_sgst_amt) samt , sum(invh_cgst_amt) camt , sum(invh_igst_amt) iamt , 0 csamt  from trnsal_invoice_header  h, (
    select invt_compcode,invt_fincode,invt_seqno,max(invt_hsncode) hsncode, min(vargrp_type_name)  vargrp_type_name from trnsal_invoice_trailer , masprd_variety , masprd_type   where invt_compcode = 1  and invt_fincode = fincode   and invt_item =  var_groupcode and    var_typecode =  vargrp_type_code and   invt_compcode = 1 and invt_fincode = fincode    group by invt_compcode,invt_fincode,invt_seqno
	)  t , massal_customer c where invh_party = cust_code  and 
	invh_comp_code = invt_compcode and invh_fincode = invt_fincode and  invh_seqno = invt_seqno and
	invh_comp_code = 1  and invh_fincode = fincode and  invh_date between fromdate and todate and invh_netamt > 0 group by cust_gst_type,hsncode,invh_cgst_per+invh_sgst_per+invh_igst_per 
    
    
     union all 
 select cust_gst_type,"1" as seqno,  hsncode hsn, descrip, 'MTS' uqc, 12 rt, dbcr_qty *- 1 qty, sum(dbcrt_grossvalue*-1) txval, sum(dbcrt_cgstvalue*-1) camt , sum(dbcrt_sgstvalue*-1) samt , sum(dbcrt_igstvalue*-1) iamt , 0 csamt 
from (
select  cust_gst_type,'CN' saltype , dbcr_hsncode hsncode,
case when dbcr_hsncode = '48059200' then 'PLASTERBOARD LINER PAPER' 
 when dbcr_hsncode = '48052500' then 'BLUE BOARD' 
  when dbcr_hsncode = '47062000' then 'RECYCLED PULP' else
'KRAFT PAPER' end as descrip, 'MTS' uqc, dbcr_value,  0 qty, dbcrt_taxable, dbcrt_grossvalue,
 dbcrt_cgstper , dbcrt_sgstper ,dbcrt_igstper ,dbcr_qty,
dbcrt_cgstvalue , dbcrt_sgstvalue , dbcrt_igstvalue
 from acc_dbcrnote_header h left join  acc_dbcrnote_trailer t on h.dbcr_seqno = t.dbcrt_seqno   
 join massal_customer on dbcr_partycode = cust_code 
where dbcr_comp_code = 1  and dbcr_date between  fromdate and todate   and dbcr_type = 'CNG' and (dbcrt_cgstledcode = 1644 or dbcrt_sgstledcode = 1645 or  dbcrt_igstledcode = 1646) 
and  dbcrt_cgstvalue + dbcrt_sgstvalue+ dbcrt_igstvalue > 0 and dbcr_party_type = 'C' and  dbcr_reason = 'SAL RETURN'
)a1 group by cust_gst_type,saltype,hsncode,descrip,uqc,dbcrt_cgstper ,dbcrt_sgstper ,dbcrt_igstper,dbcr_qty
     union all 
 select  cust_gst_type,"1" as seqno,  hsncode hsn, descrip, 'MTS' uqc, 12 rt, dbcr_qty  qty, sum(dbcrt_grossvalue) txval, sum(dbcrt_cgstvalue) camt , sum(dbcrt_sgstvalue) samt , sum(dbcrt_igstvalue) iamt , 0 csamt 
from (
select  cust_gst_type,'CN' saltype , dbcr_hsncode hsncode,
case when dbcr_hsncode = '48059200' then 'PLASTERBOARD LINER PAPER' 
 when dbcr_hsncode = '48052500' then 'BLUE BOARD' 
  when dbcr_hsncode = '47062000' then 'RECYCLED PULP' else
'KRAFT PAPER' end as descrip, 'MTS' uqc, dbcr_value,  0 qty, dbcrt_taxable, dbcrt_grossvalue,
 dbcrt_cgstper , dbcrt_sgstper ,dbcrt_igstper ,0 dbcr_qty,
dbcrt_cgstvalue , dbcrt_sgstvalue , dbcrt_igstvalue
 from acc_dbcrnote_header h left join  acc_dbcrnote_trailer t on h.dbcr_seqno = t.dbcrt_seqno   
 join massal_customer on dbcr_partycode = cust_code 
where dbcr_comp_code = 1  and dbcr_date between  fromdate and todate   and dbcr_type = 'SDN' and (dbcrt_cgstledcode = 1644 or dbcrt_sgstledcode = 1645 or  dbcrt_igstledcode = 1646) 
and  dbcrt_cgstvalue + dbcrt_sgstvalue+ dbcrt_igstvalue > 0 and dbcr_party_type = 'C' -- and  dbcr_reason = 'QTY DIFF'
)a1 group by cust_gst_type,saltype,hsncode,descrip,uqc,dbcrt_cgstper ,dbcrt_sgstper ,dbcrt_igstper,dbcr_qty
) aa1 group by cust_gst_type,seqno, hsncode, descrip ,rt

    union all    
    
     select  cust_gst_type,"2" as seqno,  salitem_hsn hscode,max(salitem_name) descrip,uom_short_name uqc ,os_cgstper+os_sgstper+os_igstper as rt,sum(os_qty) as qty,sum(os_taxable) txval,sum(os_cgst) camt,sum(os_sgst) samt,sum(os_igst) iamt , 0 as csamt
	 from trn_other_sales join  massal_customer on os_custcode = cust_code  
	 join mas_othersales_item_master on os_item = salitem_code
     join mas_uom on salitem_uom = uom_code
	 where  os_compcode = 1  and os_fincode = fincode and os_date between fromdate and todate  and os_netamt > 0
	 group by cust_gst_type,salitem_hsn,uom_short_name,os_cgstper,os_sgstper,os_igstper
    
        union all  

select cust_gst_type,"1" as seqno,  hsncode hsn, descrip, 'MTS' uqc, 12 rt, 0 qty, sum(dbcrt_grossvalue*-1) txval, sum(dbcrt_cgstvalue*-1) camt , sum(dbcrt_sgstvalue*-1) samt , sum(dbcrt_igstvalue*-1) iamt , 0 csamt 
from (
select  cust_gst_type,'CN' saltype , dbcr_hsncode hsncode,
case when dbcr_hsncode = '48059200' then 'PLASTERBOARD LINER PAPER' 
 when dbcr_hsncode = '48052500' then 'BLUE BOARD' 
  when dbcr_hsncode = '47062000' then 'RECYCLED PULP' else
'KRAFT PAPER' end as descrip, 'MTS' uqc, dbcr_value,  0 qty, dbcrt_taxable, dbcrt_grossvalue,
 dbcrt_cgstper , dbcrt_sgstper ,dbcrt_igstper ,
dbcrt_cgstvalue , dbcrt_sgstvalue , dbcrt_igstvalue
 from acc_dbcrnote_header h left join  acc_dbcrnote_trailer t on h.dbcr_seqno = t.dbcrt_seqno   
 join massal_customer on dbcr_partycode = cust_code 
where dbcr_comp_code = 1  and dbcr_date between  fromdate and todate   and dbcr_type = 'CNG' and (dbcrt_cgstledcode = 1644 or dbcrt_sgstledcode = 1645 or  dbcrt_igstledcode = 1646) 
and  dbcrt_cgstvalue + dbcrt_sgstvalue+ dbcrt_igstvalue > 0 and dbcr_party_type = 'C' and  dbcr_reason != 'SAL RETURN'
)a1 group by cust_gst_type,hsncode,descrip,uqc,dbcrt_cgstper ,dbcrt_sgstper ,dbcrt_igstper


) aa1 group by cust_gst_type,seqno,hsncode, uqc, rt order by cust_gst_type ,seqno


) aa2  order by supplytype,hsncode
) aaa2 group by supplytype,hsn
) aa3 group by supplytype



) aa3


 union 
select  concat('"doc_issue":{"doc_det" :[', GROUP_CONCAT(docsum2),']}') as docsummary  from  (
select  '1' as disporder, concat('{"doc_num":',doc_num,',','"doc_typ":"', doc_type ,'","docs":[',docsum1,']}') as docsum2 from
(
select doc_num,doc_type,GROUP_CONCAT(docsummary) docsum1  from (
select doc_num, doc_type, concat('{"num":',num,',"from":"',from_no,'","to":"',to_no,'","totnum":',totalnos
,',"cancel":',cancelled
,',"net_issue":',netissues,'}'
)
as
docsummary from (
select 
doc_num, priority, num, doc_type, saltype, salestype, yr, max(from_no) from_no,  max(to_no) to_no, sum(totalnos) totalnos, sum(cancelled) cancelled , sum(netissues) netissues
from
(
select  "1" as doc_num, "6" as priority,"1"  as num,  "Invoices for outward supply"  doc_type, 'DN' saltype,'DEBIT NOTE' salestype,0 yr,min(dbcr_vouno) from_no,max(dbcr_vouno) to_no,count(*) as totalnos,0 cancelled, count(*) as netissues from acc_dbcrnote_header where dbcr_value >0 and  dbcr_comp_code = 1  and dbcr_finid = 23 and dbcr_date between  '2023-07-01' and  '2023-07-31' and dbcr_type in ('DNG') and dbcr_party_type != 'C'
union all
select  "1" as doc_num, "6" as priority,"1"  as num,  "Invoices for outward supply"  doc_type, 'DN' saltype,'DEBIT NOTE' salestype,0 yr,0 from_no,0 to_no,0 as totalnos,count(*) as cancelled, 0 as netissues from acc_dbcrnote_header where dbcr_value = 0 and  dbcr_comp_code = 1  and dbcr_finid = 23 and dbcr_date between  '2023-07-01' and  '2023-07-31' and dbcr_type in ('DNG') and dbcr_party_type != 'C'
union all
select  "2" as doc_num, "7" as priority,"1" as num, "Credit Note" doc_type, 'CNG' saltype,'CREDIT NOTE' salestype,0 yr,0 from_no,0 to_no, 0 as totalnos,count(*) as cancelled, 0 as netissues from acc_dbcrnote_header where dbcr_value = 0 and  dbcr_comp_code = 1  and dbcr_finid = 23 and dbcr_date between  '2023-07-01' and  '2023-07-31' and dbcr_type in ('CNG') and dbcr_party_type = 'C'
union all
select  "2" as doc_num, "7" as priority,"1"  as num, "Credit Note" doc_type, 'CNG' saltype,'CREDIT NOTE' salestype,0 yr,min(dbcr_vouno) from_no,max(dbcr_vouno) to_no,count(*) as totalnos,0 cancelled, count(*) as netissues from acc_dbcrnote_header where dbcr_value >0 and  dbcr_comp_code = 1  and dbcr_finid = 23 and dbcr_date between  '2023-07-01' and  '2023-07-31' and dbcr_type in ('CNG') and dbcr_party_type = 'C'
union all
select  "3" as doc_num, "8" as priority,"1"  as num,  "Debit Note"  doc_type, 'DN' saltype,'DEBIT NOTE' salestype,0 yr,min(dbcr_vouno) from_no,max(dbcr_vouno) to_no,count(*) as totalnos,0 cancelled, count(*) as netissues from acc_dbcrnote_header where dbcr_value >0 and  dbcr_comp_code = 1  and dbcr_finid = 23 and dbcr_date between  '2023-07-01' and  '2023-07-31' and dbcr_type in ('DNG') and dbcr_party_type != 'C'
union all
select  "3" as doc_num, "8" as priority,"1"  as num,  "Debit Note"  doc_type, 'DN' saltype,'DEBIT NOTE' salestype,0 yr,0 from_no,0 to_no,0 as totalnos,count(*) as cancelled, 0 as netissues from acc_dbcrnote_header where dbcr_value = 0 and  dbcr_comp_code = 1  and dbcr_finid = 23 and dbcr_date between  '2023-07-01' and  '2023-07-31' and dbcr_type in ('DNG') and dbcr_party_type != 'C'

) a1  group by doc_num, priority, num, doc_type, saltype, salestype, yr 
union all
select "1" as doc_num,priority,row_number() over(order by priority)+1 as num, "Invoices for outward supply" doc_type, saltype,salestype,yr,
case when from_no > 99 then concat(saltype,'/',from_no,yr) else concat(saltype,'/',right(concat('00',from_no),3),yr) end as from_no,
case when to_no > 99 then concat(saltype,'/',to_no,yr) else concat(saltype,'/',right(concat('00',to_no),3),yr) end as to_no,
totalnos, cancelled, totalnos-cancelled  netissues 
from (

select saltype, case when saltype = "TN" then "TN GST SALES" else
case when saltype = "OS" then "OS IGST SALES" else
case when saltype = "TNOS" then "TN OS GST SALES" else 
case when saltype = "OSOS" then "OS OS IGST SALES"
end end end end as salestype,
case when saltype = "TN" then "2" else
case when saltype = "OS" then "3" else
case when saltype = "TNOS" then "4" else 
case when saltype = "OSOS" then "5"
end end end end as priority,yr,from_no,to_no,sum(totnos) totalnos,sum(cancelled) cancelled from
(
select h.* , case when t.cancelled > 0 then t.cancelled else 0 end as cancelled from 
(
select invh_saltype saltype ,right(invh_invrefno,6) as yr, min(invh_no) from_no ,max(invh_no) to_no ,max(invh_no)+1-min(invh_no) totnos  from trnsal_invoice_header where invh_comp_code = 1  and  invh_date between  '2023-07-01' and  '2023-07-31' group by invh_saltype,right(invh_invrefno,6)) h 
left join
(select invh_saltype , count(*) as cancelled from trnsal_invoice_header where invh_comp_code = 1  and invh_netamt = 0 and  invh_date between  '2023-07-01' and  '2023-07-31' group by invh_saltype,right(invh_invrefno,6)) t 
on h.saltype = t.invh_saltype 
union all
select h.* , case when t.cancelled > 0 then t.cancelled else 0 end as cancelled from 
(select os_state_type saltype,right(os_invno,6) as yr,min(os_docno) from_no ,max(os_docno) to_no ,max(os_docno)+1-min(os_docno) totnos  from trn_other_sales  where os_fincode = 23 and  os_date between '2023-07-01' and  '2023-07-31' and os_netamt > 0  group by os_state_type,right(os_invno,6) ) h
left join 
(select os_state_type saltype,right(os_invno,6) as yr, 0 from_no ,0  to_no ,0 totnos ,count(*) as cancelled  from trn_other_sales  where os_netamt =0 and os_fincode = 23 and os_cancel = 'Y' and  os_date between '2023-07-01' and  '2023-07-31' group by os_state_type,right(os_invno,6)) t
on h.saltype = t.saltype 
) grp1 group by saltype,yr,from_no,to_no
) grp2
) subgrp2 ) grp3 group by doc_num,doc_type ) grp4
) subgrp4 group by disporder

) aa41;     
END ;;
