DELIMITER ;;
CREATE DEFINER=`root`@`%` PROCEDURE `spacc_rep_json_08082023`(compcode int,fincode int,fromdate date , todate date)
BEGIN
SET SESSION group_concat_max_len = 18446744073709551615;
select concat('{"gstin":"33AALCS4958D1Z7","fp":"',right(concat(0,month(fromdate),year(fromdate)),6),'","gt":0.00,"cur_gt":0.00,',group_concat(newjson),'}') jsonnew from (
select GROUP_CONCAT(concat('"',saltype,'":[',jsonnew,']')) newjson  from 
(
select saltype ,GROUP_CONCAT(jsonnew)  jsonnew from  (

-- -
select  saltype, concat('{"ctin":"',partygstin,'","inv":[' , SUBSTRING(jsonnew,1,length(jsonnew)-1)  ,']}' ) jsonnew from  (
select "b2b" saltype, partygstin,GROUP_CONCAT(gsinv SEPARATOR '')  jsonnew from  (
select cust_gstin partygstin,invh_date, 
 case when invh_igst_amt >0 then 
concat('{"inum":"',invh_invrefno,'",','"idt":"', DATE_FORMAT(invh_date, "%d-%m-%Y") ,'",',
'"val":',invh_netamt,',',
'"pos":"',left(cust_gstin,2),'",',
'"rchrg":"N",','"itms":[{"num":1,"itm_det":{"txval":',invh_taxableamt,',',
'"rt":',round(invh_igst_per,0),',','"iamt":',invh_igst_amt,',','"csamt":0.00}}],','"inv_typ":"R"},'
) 
else
concat('{"inum":"',invh_invrefno,'",','"idt":"', DATE_FORMAT(invh_date, "%d-%m-%Y") ,'",',
'"val":',invh_netamt,',','"pos":"',left(cust_gstin,2),'",','"rchrg":"N",','"itms":[{"num":1,"itm_det":{"txval":',invh_taxableamt,',',
'"rt":',round(invh_cgst_per+invh_sgst_per,0),',','"camt":',invh_cgst_amt,',','"samt":',invh_sgst_amt,',','"csamt":0.00}}],','"inv_typ":"R"},'
) end
as gsinv
from trnsal_invoice_header , massal_customer  where invh_party = cust_code and  invh_comp_code = compcode and invh_fincode = fincode and invh_netamt > 0 and invh_date between fromdate and todate 
-- -
union all

select partygstin,os_date, 
case when iamt >0 then 
concat('{"inum":"',os_invno,'",','"idt":"', DATE_FORMAT(os_date, "%d-%m-%Y") ,'",',
'"val":',val,',',
'"pos":"',left(partygstin,2),'",',
'"rchrg":"N",','"itms":[{"num":1,"itm_det":{"txval":',txval,',',
'"rt":',round(os_igstper,0),',','"iamt":',iamt,',','"csamt":0.00}}],','"inv_typ":"R"},'
) 
  else
  
  concat('{"inum":"',os_invno,'",','"idt":"', DATE_FORMAT(os_date, "%d-%m-%Y") ,'",',
'"val":',val,',','"pos":"',left(partygstin,2),'",','"rchrg":"N",','"itms":[{"num":1,"itm_det":{"txval":',txval,',',
'"rt":',round(os_sgstper+os_cgstper,0),',','"camt":',camt,',','"samt":',samt,',','"csamt":0.00}}],','"inv_typ":"R"},'
)
end gsinv
  from
( select  sup_gstin partygstin,os_invno,os_date,sum(round(os_netamt,0)) val,sum(os_taxable) txval , sum(os_igst) iamt , sum(os_cgst)  camt , sum(os_sgst) samt , 0  'csamt' ,os_cgstper,os_sgstper,os_igstper
 from trn_other_sales join  maspur_supplier_master on os_custcode = sup_code 
 where  os_compcode = compcode and os_fincode = fincode and os_date between fromdate and todate and sup_gst_type <> 'U' and os_netamt >0
 group by sup_gstin,os_invno,os_date ,os_cgstper,os_sgstper,os_igstper) fs1
 

)gsinv2  group by partygstin 

)gsinv3
-- b2cs
union all
select  "b2cs" saltype, 
case when iamt >0 then 
concat('{"rt":',round(os_igstper,0),',','"sply_ty":"INTER",',
'"pos":"',state_codeno,'",',
'"typ":"OE",',
'"txval":',txval,',',
'"iamt":',iamt,',','"csamt":0.00}'
) 
else
concat('{"rt":',round(os_cgstper+os_sgstper,0),',','"sply_ty":"INTRA",',
'"pos":"',state_codeno,'",',
'"typ":"OE",',
'"txval":',txval,',',
'"camt":',camt,',','"samt":',samt,',','"csamt":0.00}'
) 
 end as jsonnew
 from  (
 select  state_codeno,os_cgstper,os_sgstper,os_igstper,sum(os_taxable) txval , sum(os_igst) iamt , sum(os_cgst)  camt , sum(os_sgst) samt , 0  'csamt' 
 from trn_other_sales join  maspur_supplier_master on os_custcode = sup_code   left join mas_state on state_code = sup_state
 where  os_compcode = compcode and os_fincode = fincode and os_date between fromdate and todate and sup_gst_type = 'U' and os_netamt > 0
 group by state_codeno,os_cgstper,os_sgstper,os_igstper
) a1

union all

-- cdnr
select  saltype, concat('{"ctin":"',led_gst_no,'","nt":[' , SUBSTRING(jsonnew,1,length(jsonnew))  ,']}' ) jsonnew from  (

select "cdnr" saltype, led_gst_no,GROUP_CONCAT(cdnr SEPARATOR ',')  jsonnew from  (
select  led_gst_no,case when dbcrt_igstvalue > 0  then 
concat('{"ntty":"C",','"nt_num":"', dbcr_vouno,'",',
'"nt_dt":"', DATE_FORMAT(dbcr_date, "%d-%m-%Y") ,'",',
'"pos":"',left(led_gst_no,2),'",',
'"rchrg":"N",','"inv_typ":"R",',
'"val":',dbcr_value,',',
'"itms":[{"num":1,"itm_det":{"rt":',round(dbcrt_igstper,0),',"txval":',dbcrt_grossvalue,',',
'"iamt":',dbcrt_igstvalue,',','"csamt":0.00}}]}'
) 
else
concat('{"ntty":"C",','"nt_num":"', dbcr_vouno,'",',
'"nt_dt":"', DATE_FORMAT(dbcr_date, "%d-%m-%Y") ,'",',
'"pos":"',left(led_gst_no,2),'",',
'"rchrg":"N",','"inv_typ":"R",',
'"val":',dbcr_value,',',
'"itms":[{"num":1,"itm_det":{"rt":',round(dbcrt_cgstper+dbcrt_sgstper,0),',"txval":',dbcrt_grossvalue,',',
'"camt":',dbcrt_cgstvalue,',','"samt":',dbcrt_sgstvalue,',','"csamt":0.00}}]}'
) 
end 
as cdnr  from acc_dbcrnote_header h left join  acc_dbcrnote_trailer t on h.dbcr_seqno = t.dbcrt_seqno   
left join acc_ledger_master on dbcr_partyledcode = led_code 
where dbcr_comp_code = compcode and dbcr_date between fromdate and todate and dbcr_type = 'CNG' and (dbcrt_cgstledcode = 1644 or dbcrt_sgstledcode = 1645 or  dbcrt_igstledcode = 1646) 
)gsinv2  group by led_gst_no 

)gsinv3

-- -  
)gsinv4 group by saltype
) gstinv


union 

select concat('"hsn":{"data":[',group_concat(hsn),']}') hsn from (
select 
concat('{"num":',num,',','"hsn_sc":"', hsncode ,'",',
 '"desc":"',descrip,'",',    
 '"uqc":"',uqc,'",'    
 '"qty":',qty,',',    
 '"rt":',rt,',',    
 '"txval":',txval,',',        
 '"iamt":',iamt,',',    
 '"camt":',camt,',',    
 '"samt":',samt,',',    
 '"csamt":0.00}'
) as hsn from
(
select row_number() over(order by seqno) as num,seqno,hsncode, descrip, uqc, rt, sum(qty) qty, sum(txval) txval , sum(samt) samt , sum(camt) camt, sum(iamt)iamt, sum(csamt) csamt from 
(
 select "1" as seqno, hsncode, vargrp_type_name descrip , 'MTS' uqc,invh_cgst_per+invh_sgst_per+invh_igst_per rt,round(sum(invh_totwt)/1000,3) qty ,sum(invh_taxableamt) txval , sum(invh_sgst_amt) samt , sum(invh_cgst_amt) camt , sum(invh_igst_amt) iamt , 0 csamt  from trnsal_invoice_header  h, (
    select invt_compcode,invt_fincode,invt_seqno,max(invt_hsncode) hsncode,vargrp_type_name from trnsal_invoice_trailer , masprd_variety , masprd_type   where invt_compcode = compcode and invt_fincode = fincode   and invt_item =  var_groupcode and    var_typecode =  vargrp_type_code and   invt_compcode = 1 and invt_fincode = fincode    group by invt_compcode,invt_fincode,invt_seqno,vargrp_type_name 
	)  t where 
	invh_comp_code = invt_compcode and invh_fincode = invt_fincode and  invh_seqno = invt_seqno and
	invh_comp_code = compcode and invh_fincode = fincode and  invh_date between fromdate and todate and invh_netamt > 0 group by hsncode,vargrp_type_name,invh_cgst_per+invh_sgst_per+invh_igst_per 
    
    union all    
    
     select  "2" as seqno,  salitem_hsn hscode,salitem_name descrip,uom_short_name uqc ,os_cgstper+os_sgstper+os_igstper as rt,sum(os_qty) as qty,sum(os_taxable) txval,sum(os_cgst) camt,sum(os_sgst) samt,sum(os_igst) iamt , 0 as csamt
	 from trn_other_sales join  maspur_supplier_master on os_custcode = sup_code 
	 join mas_othersales_item_master on os_item = salitem_code
     join mas_uom on salitem_uom = uom_code
	 where  os_compcode = compcode and os_fincode = fincode and os_date between fromdate and todate  and os_netamt > 0
	 group by salitem_hsn,salitem_name,uom_short_name,os_cgstper,os_sgstper,os_igstper
    
        union all  
    select "3" as seqno,  '48041900' hsn,'KraftPaper' descrip, 'OTH' uqc, 12 rt, 0 qty, sum(dbcrt_grossvalue*-1) txval, sum(dbcrt_cgstvalue*-1) camt , sum(dbcrt_sgstvalue*-1) samt , sum(dbcrt_igstvalue*-1) iamt , 0 csamt 
 from acc_dbcrnote_header h left join  acc_dbcrnote_trailer t on h.dbcr_seqno = t.dbcrt_seqno   
where dbcr_comp_code = compcode and dbcr_date between fromdate and todate and dbcr_type = 'CNG' and (dbcrt_cgstledcode = 1644 or dbcrt_sgstledcode = 1645 or  dbcrt_igstledcode = 1646) 
and  dbcrt_cgstvalue + dbcrt_sgstvalue+ dbcrt_igstvalue > 0
) aa1 group by seqno,hsncode, descrip, uqc, rt order by seqno
) aa2 
) aa3


union 
select concat('"doc_issue":{"doc_det":[',GROUP_CONCAT(docsum2),']}') docsum3 from (

select "doc_issue" saltype, concat('{"doc_num":',doc_num,',','"doc_typ":"', doc_type ,'","docs":[',docsum1,']}') as docsum2 from
(
select doc_num,doc_type,GROUP_CONCAT(docsummary) docsum1
from (
select 
doc_num, doc_type, concat('{"num":',num,',"from":"',from_no,'","to":"',to_no,'","totnum":',totalnos
,',"cancel":',cancelled
,',"net_issue":',netissues,'}'
)
as
docsummary 
from
(
select doc_num, doc_type,  num,  saltype, salestype, yr, from_no, to_no, totalnos, cancelled, netissues from
(
select "1" as doc_num, "1" as priority,row_number() over(order by saltype) as num, "Invoices for outward supply" doc_type, saltype,salestype,yr,
case when from_no > 99 then concat(saltype,'/',from_no,yr) else concat(saltype,'/',right(concat('00',from_no),3),yr) end as from_no,
case when to_no > 99 then concat(saltype,'/',to_no,yr) else concat(saltype,'/',right(concat('00',to_no),3),yr) end as to_no,
totalnos, cancelled, totalnos-cancelled  netissues 
from (
select saltype, case when saltype = "TN" then "TN GST SALES" else
case when saltype = "OS" then "OS IGST SALES" else
case when saltype = "TNOS" then "TN OS GST SALES" else 
case when saltype = "OSOS" then "OS OS IGST SALES"
end end end end as salestype,yr,from_no,to_no,sum(totnos) totalnos,sum(cancelled) cancelled from
(
select invh_saltype saltype ,right(invh_invrefno,6) as yr, min(invh_no) from_no ,max(invh_no) to_no ,max(invh_no)+1-min(invh_no) totnos ,0 as cancelled from trnsal_invoice_header where invh_comp_code = 1  and  invh_date between  fromdate and  todate group by invh_saltype,right(invh_invrefno,6)
union all
select invh_saltype saltype,right(invh_invrefno,6) as yr,0 from_no ,0 to_no ,0 as totnos ,count(*) as cancelled from trnsal_invoice_header where invh_comp_code = 1  and invh_netamt = 0 and  invh_date between  fromdate and  todate group by invh_saltype,right(invh_invrefno,6)
union all
select os_state_type saltype,right(os_invno,6) as yr,min(os_docno) from_no ,max(os_docno) to_no ,max(os_docno)+1-min(os_docno) totnos ,0 as cancelled  from trn_other_sales  where os_compcode = 1  and  os_date between  fromdate and  todate  group by os_state_type,right(os_invno,6)
union all
select os_state_type saltype,right(os_invno,6) as yr, 0 from_no ,0  to_no ,0 totnos ,count(*) as cancelled  from trn_other_sales  where os_netamt =0 and os_compcode = 1  and  os_date between  fromdate and  todate  group by os_state_type,right(os_invno,6)
) grp1 group by saltype,yr,from_no,to_no
) grp2
union all
select  "5" as doc_num, "2" as priority,row_number() over() as num, "Credit Note" doc_type, 'CN' saltype,'CREDIT NOTE' salestype,0 yr,min(dbcr_vouno) from_no,max(dbcr_vouno) to_no,count(*) as totalnos,0 cancelled, count(*) as netissues from acc_dbcrnote_header where dbcr_comp_code = compcode  and dbcr_finid = fincode and dbcr_date between  fromdate and  todate and dbcr_type in ('CNG')
union all
select  "4" as doc_num, "3" as priority,row_number() over() as num,  "Debit Note" doc_type, 'DN' saltype,'DEBIT NOTE' salestype,0 yr,min(dbcr_vouno) from_no,max(dbcr_vouno) to_no,count(*) as totalnos,0 cancelled, count(*) as netissues from acc_dbcrnote_header where dbcr_comp_code = compcode  and dbcr_finid = fincode and dbcr_date between  fromdate and  todate and dbcr_type in ('DNG')
) a1
) aa1 
) aa2 group by doc_num, doc_type
) aa3

) aa4

) aa41;     
END ;;
