CREATE DEFINER=`root`@`%` PROCEDURE `spacc_rep_json_abstract`(compcode int,fincode int,fromdate date , todate date)
BEGIN
SET SESSION group_concat_max_len = 18446744073709551615;
select concat('{"gstin":"33AALCS4958D1Z7","fp":"',right(concat(0,month(fromdate),year(fromdate)),6),'","gt":0.00,"cur_gt":0.00,',group_concat(hsn),'}') jsonnew from (

select concat('"hsn":{"data":[',group_concat(hsn),']}') hsn from (
select 
concat('{"num":',num,',','"hsn_sc":"', hsncode ,'",',
 '"desc":"',descrip,'",',    
 '"uqc":"',uqc,'",'    
 '"qty":',qty,',',    
 '"rt":',rt,',',    
 '"txval":',txval,',',        
 '"iamt":',iamt,',',    
 '"camt":',camt,',',    
 '"samt":',samt,',',    
 '"csamt":0.00}'
) as hsn from
(
select row_number() over(order by seqno) as num,seqno,hsncode, descrip, uqc, rt, Cast(sum(qty) as decimal(10,2)) as qty, sum(txval) txval , sum(samt) samt , sum(camt) camt, sum(iamt)iamt, sum(csamt) csamt from 
(
 select "1" as seqno, hsncode, vargrp_type_name descrip , 'MTS' uqc,invh_cgst_per+invh_sgst_per+invh_igst_per rt,round(sum(invh_totwt)/1000,2) qty ,sum(invh_taxableamt) txval , sum(invh_sgst_amt) samt , sum(invh_cgst_amt) camt , sum(invh_igst_amt) iamt , 0 csamt  from trnsal_invoice_header  h, (
    select invt_compcode,invt_fincode,invt_seqno,max(invt_hsncode) hsncode,vargrp_type_name from trnsal_invoice_trailer , masprd_variety , masprd_type   where invt_compcode = compcode and invt_fincode = fincode   and invt_item =  var_groupcode and    var_typecode =  vargrp_type_code and   invt_compcode = 1 and invt_fincode = fincode    group by invt_compcode,invt_fincode,invt_seqno,vargrp_type_name 
	)  t where 
	invh_comp_code = invt_compcode and invh_fincode = invt_fincode and  invh_seqno = invt_seqno and
	invh_comp_code = compcode and invh_fincode = fincode and  invh_date between fromdate and todate and invh_netamt > 0 group by hsncode,vargrp_type_name,invh_cgst_per+invh_sgst_per+invh_igst_per 
    
    union all    
    
     select  "2" as seqno,  salitem_hsn hscode,salitem_name descrip,uom_short_name uqc ,os_cgstper+os_sgstper+os_igstper as rt,sum(os_qty) as qty,sum(os_taxable) txval,sum(os_cgst) camt,sum(os_sgst) samt,sum(os_igst) iamt , 0 as csamt
	 from trn_other_sales join  maspur_supplier_master on os_custcode = sup_code 
	 join mas_othersales_item_master on os_item = salitem_code
     join mas_uom on salitem_uom = uom_code
	 where  os_compcode = compcode and os_fincode = fincode and os_date between fromdate and todate  and os_netamt > 0
	 group by salitem_hsn,salitem_name,uom_short_name,os_cgstper,os_sgstper,os_igstper
    
        union all  
    select "3" as seqno,  '48041900' hsn,'KraftPaper' descrip, 'OTH' uqc, 12 rt, 0 qty, sum(dbcrt_grossvalue*-1) txval, sum(dbcrt_cgstvalue*-1) camt , sum(dbcrt_sgstvalue*-1) samt , sum(dbcrt_igstvalue*-1) iamt , 0 csamt 
 from acc_dbcrnote_header h left join  acc_dbcrnote_trailer t on h.dbcr_seqno = t.dbcrt_seqno   
where dbcr_comp_code = compcode and dbcr_date between fromdate and todate and dbcr_type = 'CNG' and (dbcrt_cgstledcode = 1644 or dbcrt_sgstledcode = 1645 or  dbcrt_igstledcode = 1646) 
and  dbcrt_cgstvalue + dbcrt_sgstvalue+ dbcrt_igstvalue > 0
) aa1 group by seqno,hsncode, descrip, uqc, rt order by seqno
) aa2 
) aa3



 union 
select  concat('"doc_issue":{"doc_det" :[', GROUP_CONCAT(docsum2),']}') as docsummary  from  (
select  '1' as disporder, concat('{"doc_num":',doc_num,',','"doc_typ":"', doc_type ,'","docs":[',docsum1,']}') as docsum2 from
(
select doc_num,doc_type,GROUP_CONCAT(docsummary) docsum1  from (
select doc_num, doc_type, concat('{"num":',num,',"from":"',from_no,'","to":"',to_no,'","totnum":',totalnos
,',"cancel":',cancelled
,',"net_issue":',netissues,'}'
)
as
docsummary from (
select 
doc_num, priority, num, doc_type, saltype, salestype, yr, max(from_no) from_no,  max(to_no) to_no, sum(totalnos) totalnos, sum(cancelled) cancelled , sum(netissues) netissues
from
(
select  "1" as doc_num, "6" as priority,"1"  as num,  "Invoices for outward supply"  doc_type, 'DN' saltype,'DEBIT NOTE' salestype,0 yr,min(dbcr_vouno) from_no,max(dbcr_vouno) to_no,count(*) as totalnos,0 cancelled, count(*) as netissues from acc_dbcrnote_header where dbcr_value >0 and  dbcr_comp_code = 1  and dbcr_finid = fincode and dbcr_date between  fromdate and  todate and dbcr_type in ('DNG') and dbcr_party_type != 'C'
union all
select  "1" as doc_num, "6" as priority,"1"  as num,  "Invoices for outward supply"  doc_type, 'DN' saltype,'DEBIT NOTE' salestype,0 yr,0 from_no,0 to_no,0 as totalnos,count(*) as cancelled, 0 as netissues from acc_dbcrnote_header where dbcr_value = 0 and  dbcr_comp_code = 1  and dbcr_finid = fincode and dbcr_date between  fromdate and  todate and dbcr_type in ('DNG') and dbcr_party_type != 'C'
union all
