(
select invh_saltype saltype ,right(invh_invrefno,6) as yr, min(invh_no) from_no ,max(invh_no) to_no ,max(invh_no)+1-min(invh_no) totnos  from trnsal_invoice_header where invh_comp_code = 1  and  invh_date between  fromdate and  todate group by invh_saltype,right(invh_invrefno,6)) h 
left join
(select invh_saltype , count(*) as cancelled from trnsal_invoice_header where invh_comp_code = 1  and invh_netamt = 0 and  invh_date between  fromdate and  todate group by invh_saltype,right(invh_invrefno,6)) t 
on h.saltype = t.invh_saltype 
union all
select h.* , case when t.cancelled > 0 then t.cancelled else 0 end as cancelled from 
(select os_state_type saltype,right(os_invno,6) as yr,min(os_docno) from_no ,max(os_docno) to_no ,max(os_docno)+1-min(os_docno) totnos  from trn_other_sales  where os_fincode = fincode and  os_date between fromdate and  todate and os_netamt > 0  group by os_state_type,right(os_invno,6) ) h
left join 
(select os_state_type saltype,right(os_invno,6) as yr, 0 from_no ,0  to_no ,0 totnos ,count(*) as cancelled  from trn_other_sales  where os_netamt =0 and os_fincode = fincode and os_cancel = 'Y' and  os_date between fromdate and  todate group by os_state_type,right(os_invno,6)) t
on h.saltype = t.saltype 
