BEGIN
SET SESSION group_concat_max_len = 18446744073709551615;
select concat('{"gstin":"33AALCS4958D1Z7","fp":"',right(concat(0,month(fromdate),year(fromdate)),6),'",',group_concat(docsummary),'}') jsonnew from (

select  concat('"doc_issue":{"doc_det" :[', GROUP_CONCAT(docsum2),']}') as docsummary  from  (
select  '1' as disporder, concat('{"doc_num":',doc_num,',','"doc_typ":"', doc_type ,'","docs":[',docsum1,']}') as docsum2 from
(
