select doc_num, doc_type, concat('{"num":',num,',"from":"',from_no,'","to":"',to_no,'","totnum":',totalnos
,',"cancel":',cancelled
,',"net_issue":',netissues,'}'
)
as
docsummary from (
select doc_num, doc_type,  num,  saltype, salestype, yr, from_no, to_no, totalnos, cancelled, (totalnos - cancelled)  netissues from
(


select "1" as doc_num,  priority,row_number() over(order by priority) as num, "Invoices for outward supply" doc_type, saltype,salestype,yr,
