SELECT 
  CONCAT('"hsn":{',
    GROUP_CONCAT(
      CONCAT('"', supplytype, '":[', hsn, ']')
      SEPARATOR ','
    ),
  '}') AS hsn from (
select supplytype,group_concat(hsn) hsn from (
select  supplytype,
concat('{"num":',num,',','"hsn_sc":"', hsncode ,'",',
 '"txval":',txval,',',        
 '"iamt":',iamt,',',    
 '"camt":',camt,',',    
