(
 select 
 seqno, hsncode,   descrip, 'MTS' uqc,  rt , sum(qty) qty , sum(txval) taxval, sum(samt) samt , sum(camt) camt , sum(iamt) iamt, sum(csamt) csamt from
 (
 
