CREATE DEFINER=`root`@`%` PROCEDURE `spacc_rep_ledger_code`(
compcode int,
fincode int,
ledgercode int,
repmonth int
)
BEGIN
select * from  acc_ref, acc_tran , acc_ledger_master where accref_seqno = acctran_accref_seqno and  acctran_led_code = led_code and 
accref_comp_code = compcode and  accref_finid = fincode and 
month(accref_voudate) = repmonth and acctran_led_code = ledgercode;
END ;;
