	END IF;
    
        
	IF NOT EXISTS( SELECT NULL
				FROM INFORMATION_SCHEMA.COLUMNS
				WHERE table_name = @table_name   
		 AND column_name = 'VEHICLE MAINTENANCE GST 28%')  THEN
		 
		 set @qry1:= concat("ALTER TABLE ",newtablename ," ADD `VEHICLE MAINTENANCE GST 28%` int(1) NOT NULL default '0'");
		 prepare stmt3 from @qry1 ;
