CREATE DEFINER=`root`@`%` PROCEDURE `spacc_rep_ledger_column_report27072024`(compcode int,fincode int,startdate date,enddate date,ledcode int,tablename varchar(50))
BEGIN

declare  newtablename varchar(20);
set newtablename = tablename;
SET SESSION group_concat_max_len =  18446744073709551615;
set @ledtype = 'G';
set @compcode = compcode;
set @fincode = fincode;
set @startdate = startdate;
set @enddate = enddate;
set @lcode = ledcode;
SET @sql = NULL;

set @table_name = tablename;
set @table_name2 = tablename;

set @table_name = tablename;

SET @tabledelete := CONCAT('DROP TABLE ',tablename);
 IF EXISTS (SELECT NULL
             FROM   information_schema.tables t
             WHERE  t.table_schema = database()
             AND    t.table_name = tablename)
  THEN
 
    /* Dynamically allocated and run statement. */
    PREPARE stmt2 FROM @tabledelete;
    EXECUTE stmt2;
    DEALLOCATE PREPARE stmt2;
  END IF;
  
 SELECT
  GROUP_CONCAT(DISTINCT
    CONCAT(
      'sum(case when ledger_name = ''',
      dt,
      ''' then ledger_amt else 0 end) AS `',
      dt, '`'
    )
  ) INTO @sql
from
(
select ledger_name as dt  from 
(
  select * , value1/Qty  as rate from (
  select accref_seqno ,ledger_name ,case when accref_vou_type = "GSI" then "General Sales" else
case when accref_vou_type = "OSI" then "Other Sales" else
case when accref_vou_type = "CNG" then "Credit Note" else
case when accref_vou_type = "DNG" or  accref_vou_type = "SDN"  then "Debit Note" else
case when accref_vou_type = "PWP" then "Local-WP" else
case when accref_vou_type = "PIW" then "Import-WP" else
case when accref_vou_type = "PGS" then "Stores" else
case when accref_vou_type = "PFU" then "Fuel" else accref_vou_type
end end  end end end end end end as accref_vou_type, accref_vouno, accref_voudate,accref_narration,
case when accref_vou_type = 'CNG' and ledger_name !="ROUNDED OFF" then ledger_amt * -1 else
case when ledger_name ="ROUNDED OFF" and acctran_dbamt >0 then ledger_amt else
case when ledger_name ="ROUNDED OFF" and acctran_cramt >0 then ledger_amt  * -1 else
ledger_amt end end end as ledger_amt

 from (
select accref_seqno ,replace(cust_name,".","")  ledger_name ,accref_vou_type, accref_vouno, accref_voudate,accref_narration,acctran_totamt ledger_amt ,acctran_dbamt,acctran_cramt
from acc_ref a ,  acc_tran b , massal_customer l   where 
cust_type = "G" and acctran_led_code = cust_code and accref_seqno = acctran_accref_seqno  and accref_seqno in (
select accref_seqno from acc_ref ,  acc_tran where accref_seqno = acctran_accref_seqno and  accref_comp_code = compcode
and accref_finid = fincode and accref_voudate between startdate and enddate and  acctran_led_code = ledcode)  
) aa1
) a1
left join
(
select dbcr_accseqno  accrefno , cust_ref, cust_gstin,  0 as Qty , case when dbcr_type = "CNG" then dbcrt_value*-1 else dbcrt_value end  as invamt, "" uom, case when dbcr_type = "CNG" then  dbcrt_grossvalue*-1 else dbcrt_grossvalue end as value1 , left(dbcrt_inv_no,13) as vou_refno   from acc_dbcrnote_header dh, acc_dbcrnote_trailer dt, massal_customer where dbcr_seqno = dbcrt_seqno and  dbcr_partycode = cust_code 
and dbcr_comp_code =  compcode and dbcr_date  between startdate and enddate
union all
select invh_acc_refno  accrefno , cust_ref, cust_gstin,  Cast(invh_totwt/1000 as decimal(18,3)) as Qty , invh_netamt as invamt, "MTS" uom, invh_taxableamt value1 ,left(invh_our_ordno,6) as vou_refno from trnsal_invoice_header i, massal_customer where invh_party = cust_code and invh_comp_code =  compcode and invh_date  between startdate and enddate
union all
select rech_acc_seqno  accrefno , cust_ref, cust_gstin,  sum(rect_grnqty)  as Qty , max(rech_totalamount) as invamt, "MTS" uom , max(rech_itemvalue) value1 , rech_billno as vou_refno   from trnrm_receipt_header, trnrm_receipt_trailer,massal_customer where rech_seqno = rect_hdseqno and rech_sup_code = cust_code and rech_compcode = compcode and rech_date between  startdate and enddate
group by rech_acc_seqno,  accrefno , cust_ref, cust_gstin,rech_billno
union all
select rech_acc_seqno  accrefno , cust_ref, cust_gstin,  sum(rect_grnqty)  as Qty , max(rech_totalamount) as invamt, "MTS" uom , max(rech_itemvalue) value1 , rech_billno as vou_refno  from trnfu_receipt_header, trnfu_receipt_trailer,massal_customer where rech_seqno = rect_hdseqno and rech_sup_code = cust_code and rech_compcode = compcode and rech_date between  startdate and enddate
group by rech_acc_seqno,  accrefno , cust_ref, cust_gstin,rech_billno
union all
select os_acc_seqno  accrefno , cust_ref, cust_gstin,  sum(os_qty)  as Qty , max(os_netamt) as invamt, "MTS" uom ,
 sum(os_taxable) value1 , '' as vou_refno from trn_other_sales , massal_customer where os_custcode = cust_code and os_compcode = compcode and os_date between   startdate and enddate
 group by os_acc_seqno , cust_ref, cust_gstin
 union all
 select minh_acc_seqno  accrefno , cust_ref, cust_gstin,  sum(mint_accept_qty)  as Qty , max(minh_value) as invamt, uom_short_name uom ,
 sum(minh_gross_value) value1 ,minh_bill_no as vou_refno  from trnpur_min_header h, trnpur_min_trailer t, massal_customer c ,maspur_item_header i , mas_uom u where 
mint_item_code = item_code and item_uom = uom_code  and
minh_sup_code = cust_code and minh_comp_code = mint_comp_code and  minh_fin_code = mint_fin_code and minh_minno = mint_minno
and minh_comp_code = compcode and minh_mindate between startdate and enddate 
 group by minh_acc_seqno , cust_ref, cust_gstin,uom_short_name,minh_bill_no
)b1 
 on  a1.accref_seqno = b1.accrefno order by accref_seqno
)t1 
 order by ledger_name ) d;



SET @sql 
  = CONCAT('create table ' ,@table_name ,' as select accref_seqno,  accref_vou_type, accref_vouno,  DATE_FORMAT(accref_voudate, "%d-%m-%Y") as accrefvoudate ,accref_voudate, vou_refno,accref_narration,  accrefno, cust_ref, cust_gstin, Qty, invamt, uom, value1, rate ,', @sql, ' from 
  (
  select * , case when value1 >0 and Qty >0 then value1/Qty else 0 end as rate from (
  select accref_seqno ,ledger_name ,case when accref_vou_type = "GSI" then "General Sales" else
case when accref_vou_type = "OSI" then "Other Sales" else
case when accref_vou_type = "CNG" then "Credit Note" else
case when accref_vou_type = "DNG" or  accref_vou_type = "SDN"  then "Debit Note" else
case when accref_vou_type = "PWP" then "Local-WP" else
case when accref_vou_type = "PIW" then "Import-WP" else
case when accref_vou_type = "PGS" then "Stores" else
case when accref_vou_type = "PFU" then "Fuel" else accref_vou_type
end end  end end end end end end as accref_vou_type, accref_vouno, accref_voudate,accref_narration,
case when accref_vou_type = "CNG" and ledger_name !="ROUNDED OFF" then ledger_amt * -1 else
case when ledger_name ="ROUNDED OFF" and acctran_dbamt >0 then ledger_amt else
case when ledger_name ="ROUNDED OFF" and acctran_cramt >0 then ledger_amt * -1  else
ledger_amt end end end as ledger_amt

 from (
select accref_seqno ,replace(cust_name,".","")  ledger_name ,accref_vou_type, accref_vouno, accref_voudate,accref_narration,acctran_totamt ledger_amt ,acctran_dbamt,acctran_cramt from acc_ref a ,  acc_tran b , massal_customer l   where 
cust_type = "G" and acctran_led_code = cust_code and accref_seqno = acctran_accref_seqno  and accref_seqno in (
select accref_seqno from acc_ref ,  acc_tran where accref_seqno = acctran_accref_seqno and  accref_comp_code = @compcode
and accref_finid = @fincode and accref_voudate between @startdate and @enddate and  acctran_led_code = @lcode)  
)aa1
) a1
left join
(

select dbcr_accseqno  accrefno , cust_ref, cust_gstin,  0 as Qty , case when dbcr_type = "CNG" then dbcrt_value*-1 else dbcrt_value end  as invamt, "" uom, case when dbcr_type = "CNG" then  dbcrt_grossvalue*-1 else dbcrt_grossvalue end as value1 , left(dbcrt_inv_no,13) as vou_refno   from acc_dbcrnote_header dh, acc_dbcrnote_trailer dt, massal_customer where dbcr_seqno = dbcrt_seqno and  dbcr_partycode = cust_code 
and dbcr_comp_code =  @compcode and dbcr_date  between @startdate and @enddate
union all
select invh_acc_refno  accrefno , cust_ref, cust_gstin,  Cast(invh_totwt/1000 as decimal(18,3)) as Qty , invh_netamt as invamt, "MTS" uom, invh_taxableamt value1 ,left(invh_our_ordno,6) as vou_refno  from trnsal_invoice_header i, massal_customer where invh_party = cust_code and invh_comp_code =  @compcode and invh_date  between @startdate and @enddate
union all
select rech_acc_seqno  accrefno , cust_ref, cust_gstin,  sum(rect_grnqty)  as Qty , max(rech_totalamount) as invamt, "MTS" uom , max(rech_itemvalue) value1 , rech_billno as vou_refno  from trnrm_receipt_header, trnrm_receipt_trailer,massal_customer where rech_seqno = rect_hdseqno and rech_sup_code = cust_code and rech_compcode = @compcode and rech_date between  @startdate and @enddate
