union all
select rech_acc_seqno  accrefno , cust_ref, cust_gstin,  sum(rect_grnqty)  as Qty , max(rech_totalamount) as invamt, "MTS" uom , max(rech_itemvalue) value1 ,rech_billno as vou_refno from trnfu_receipt_header, trnfu_receipt_trailer,massal_customer where rech_seqno = rect_hdseqno and rech_sup_code = cust_code and rech_compcode = @compcode and rech_date between  @startdate and @enddate
