		 AND column_name = 'VEHICLE MAINTENANCE IGST 18%')  THEN
		 
		 set @qry1:= concat("ALTER TABLE ",newtablename ," ADD `VEHICLE MAINTENANCE IGST 18%` int(1) NOT NULL default '0'");
		 prepare stmt3 from @qry1 ;
		 execute stmt3 ;
	END IF;
            
   
    end if;

	END IF;
    

end if;

        	IF NOT EXISTS( SELECT NULL
				FROM INFORMATION_SCHEMA.COLUMNS
				WHERE table_name = @table_name   
		 AND column_name = 'ROUNDED OFF')  THEN
		 
		 set @qry1:= concat("ALTER TABLE ",newtablename ," ADD `ROUNDED OFF` int(1) NOT NULL default '0'");
		 prepare stmt3 from @qry1 ;
		 execute stmt3 ;
	END IF;
/*
    IF NOT EXISTS( SELECT NULL
				FROM INFORMATION_SCHEMA.COLUMNS
				WHERE table_name = @table_name   
		 AND column_name = 'WASTE PAPER PURCHASE-IMPORT')  THEN
		 
		 set @qry1:= concat("ALTER TABLE ",newtablename ," ADD `WASTE PAPER PURCHASE-IMPORT` int(1) NOT NULL default '0'");
		 prepare stmt3 from @qry1 ;
		 execute stmt3 ;
	END IF;  
*/   


END ;;
