CREATE DEFINER=`root`@`%` PROCEDURE `spacc_rep_ledger_column_report_voucher`(compcode int,fincode int,startdate date,enddate date,tablename varchar(50),voutype varchar(20))
BEGIN

declare  newtablename varchar(50);
declare  voutype2 varchar(20);
set newtablename = tablename;
SET SESSION group_concat_max_len =  18446744073709551615;
set @ledtype = 'G';
set @compcode = compcode;
set @fincode = fincode;
set @startdate = startdate;
set @enddate = enddate;
set @voutype = voutype;



SET @sql = NULL;

set @table_name = tablename;
set @table_name2 = tablename;

set @table_name = tablename;

SET @tabledelete := CONCAT('DROP TABLE ',tablename);
 IF EXISTS (SELECT NULL
             FROM   information_schema.tables t
             WHERE  t.table_schema = database()
             AND    t.table_name = tablename)
  THEN
 
    /* Dynamically allocated and run statement. */
    PREPARE stmt2 FROM @tabledelete;
    EXECUTE stmt2;
    DEALLOCATE PREPARE stmt2;
  END IF;

 SELECT
  GROUP_CONCAT(DISTINCT
    CONCAT(
      'sum(case when ledger_name = ''',
      dt,
      ''' then ledger_amt else 0 end) AS `',
      dt, '`'
    )
  ) INTO @sql
from
(
select ledger_name as dt  from 
(
select 
accref_seqno,case  when ledger_name = 'TCS @0.1% COLLECTED' then 'TCS @01% COLLECTED' else 
case when ledger_name = 'INPUT CGST@2.5%' then 'INPUT CGST@205%' else 
case when ledger_name = 'INPUT SGST@2.5%' then 'INPUT SGST@205%' else 
ledger_name end end end as ledger_name, 
case when accref_vou_type = "GSI" then "General Sales" else
case when accref_vou_type = "OSI" then "Other Sales" else
case when accref_vou_type = "CNG" then "Credit Note" else
case when accref_vou_type = "DNG" or  accref_vou_type = "SDN"  then "Debit Note" else
case when accref_vou_type = "PWP" then "Local-WP" else
case when accref_vou_type = "PIW" then "Import-WP" else
case when accref_vou_type = "PGS" then "Stores" else
case when accref_vou_type = "PFU" then "Fuel" else accref_vou_type
end end  end end end end end end as accref_vou_type, accref_vouno, accref_voudate, accref_narration, 
case when accref_vou_type in ("CNG","CNN","DNG","DNN") and  ledger_name != "ROUNDED OFF" then ledger_amt*-1 else ledger_amt  end as ledger_amt  , 
ledtype, accrefno, cust_ref, cust_gstin, Qty, invamt, uom, value1, vou_refno,billdate, rate
 from (
select * , case when value1 >0  and Qty > 0 then value1/Qty else 0 end   as rate from (
select accref_seqno ,cust_name ledger_name ,
accref_vou_type, accref_vouno, accref_voudate,accref_narration,accref_payref_date billdate ,
case when cust_name ="ROUNDED OFF" and accref_vou_type in ('DNN','DNG','SDN') and acctran_dbamt >0 then acctran_totamt * -1 else
case when cust_name ="ROUNDED OFF"  and accref_vou_type in ('DNN','DNG','SDN') and acctran_cramt >0 then acctran_totamt  else
case when cust_name ="ROUNDED OFF" and accref_vou_type in ('CNN','CNG') and acctran_dbamt >0 then acctran_totamt else
case when cust_name ="ROUNDED OFF"  and accref_vou_type in ('CNN','CNG') and acctran_cramt >0 then acctran_totamt * -1  else
acctran_totamt end end  end end  as ledger_amt
from acc_ref a ,  acc_tran b , massal_customer l   where 
cust_type = 'G' and acctran_led_code = cust_code and accref_seqno = acctran_accref_seqno  and accref_seqno in (
select accref_seqno from acc_ref ,  acc_tran where accref_seqno = acctran_accref_seqno and  accref_comp_code = compcode
and accref_finid = fincode and accref_voudate between startdate and enddate and  FIND_IN_SET(accref_vou_type, voutype) > 0)  
) a1
left join
(


select dbcr_party_type  as ledtype, dbcr_accseqno  accrefno , cust_ref, cust_gstin,  0 as Qty , 
case when dbcr_party_type = "C" and dbcr_type = "CNG" then dbcrt_value
else case when dbcr_party_type = "S" and dbcr_type = "DNG" then dbcrt_value  else dbcrt_value end end as invamt,
 "" uom ,
case when dbcr_party_type = "C" and dbcr_type = "CNG" then dbcrt_grossvalue
else case when dbcr_party_type = "S" and dbcr_type = "DNG" then dbcrt_grossvalue  else dbcrt_grossvalue end end as value1,
 left(dbcrt_inv_no,13) as vou_refno   
from acc_dbcrnote_header dh, acc_dbcrnote_trailer dt, massal_customer where dbcr_seqno = dbcrt_seqno and  dbcr_partycode = cust_code 
and dbcr_comp_code = compcode and dbcr_date  between startdate and enddate and  FIND_IN_SET(dbcr_type, voutype)


)b1 
 on  a1.accref_seqno = b1.accrefno order by accref_seqno
)c1 
)t1   
 order by ledger_name ) d;



SET @sql 
  = CONCAT('create table ' ,@table_name ,' as select accref_seqno,  accref_vou_type, accref_vouno,  DATE_FORMAT(accref_voudate, "%d-%m-%Y") as accrefvoudate ,accref_voudate, vou_refno,billdate,accref_narration,  accrefno, cust_ref, cust_gstin, Qty, invamt, uom, value1, rate ,', @sql, ' from 
  (
select 
accref_seqno,case  when ledger_name = "TCS @0.1% COLLECTED" then "TCS @01% COLLECTED" else 
case when ledger_name = "INPUT CGST@2.5%" then "INPUT CGST@205%" else 
case when ledger_name = "INPUT SGST@2.5%" then "INPUT SGST@205%" else 
ledger_name end end end as ledger_name, 
case when accref_vou_type = "GSI" then "General Sales" else
case when accref_vou_type = "OSI" then "Other Sales" else
case when accref_vou_type = "CNG" then "Credit Note" else
case when accref_vou_type = "DNG" or  accref_vou_type = "SDN"  then "Debit Note" else
case when accref_vou_type = "PWP" then "Local-WP" else
case when accref_vou_type = "PIW" then "Import-WP" else
case when accref_vou_type = "PGS" then "Stores" else
case when accref_vou_type = "PFU" then "Fuel" else accref_vou_type
end end  end end end end end end as accref_vou_type, accref_vouno, accref_voudate, accref_narration, 
case when accref_vou_type in ("CNG","CNN","DNG","DNN") and  ledger_name != "ROUNDED OFF" then ledger_amt else ledger_amt  end as ledger_amt  , 
ledtype, accrefno, cust_ref, cust_gstin, Qty, invamt, uom, value1, vou_refno,billdate, rate
 from (
select * , case when value1 >0 and Qty >0 then value1/Qty else 0 end as rate from (
select accref_seqno ,cust_name ledger_name ,
accref_vou_type, accref_vouno, accref_voudate,accref_narration,accref_payref_date billdate ,
case when cust_name ="ROUNDED OFF" and accref_vou_type in ("DNN","DNG","SDN") and acctran_dbamt >0 then acctran_totamt * -1 else
case when cust_name ="ROUNDED OFF"  and accref_vou_type in ("DNN","DNG","SDN") and acctran_cramt >0 then acctran_totamt  else
case when cust_name ="ROUNDED OFF" and accref_vou_type in ("CNN","CNG") and acctran_dbamt >0 then acctran_totamt else
case when cust_name ="ROUNDED OFF"  and accref_vou_type in ("CNN","CNG") and acctran_cramt >0 then acctran_totamt * -1  else
case when cust_type = "S" and  accref_vou_type in ("DNG","DNN")  then acctran_totamt  else
case when cust_type = "C" and  accref_vou_type in ("CNG","CNN")  then acctran_totamt   else
acctran_totamt end end end end  end end  as ledger_amt
from acc_ref a ,  acc_tran b , massal_customer l   where 
cust_type = "G" and acctran_led_code = cust_code and accref_seqno = acctran_accref_seqno  and accref_seqno in (
select accref_seqno from acc_ref ,  acc_tran where accref_seqno = acctran_accref_seqno and  accref_comp_code = @compcode
and accref_finid = @fincode and accref_voudate between @startdate and @enddate and  FIND_IN_SET(accref_vou_type, @voutype) > 0 )  
) a1
left join
(


select dbcr_party_type  as ledtype, dbcr_accseqno  accrefno , cust_ref, cust_gstin,  0 as Qty , 
case when dbcr_party_type = "C" and dbcr_type = "CNG" then dbcrt_value 
else case when dbcr_party_type = "S" and dbcr_type = "DNG" then dbcrt_value  else dbcrt_value end end as invamt,
 "" uom ,
case when dbcr_party_type = "C" and dbcr_type = "CNG" then dbcrt_grossvalue 
else case when dbcr_party_type = "S" and dbcr_type = "DNG" then dbcrt_grossvalue  else dbcrt_grossvalue end end as value1,
 left(dbcrt_inv_no,13) as vou_refno  
from acc_dbcrnote_header dh, acc_dbcrnote_trailer dt, massal_customer where dbcr_seqno = dbcrt_seqno and  dbcr_partycode = cust_code 
and dbcr_comp_code = @compcode and dbcr_date between @startdate and @enddate and  FIND_IN_SET(dbcr_type, @voutype)
)b1 
 on  a1.accref_seqno = b1.accrefno order by accref_seqno
)c1 
)t1 
  group by accref_seqno,  accref_vou_type, accref_vouno, vou_refno, accref_voudate, accref_narration,  accrefno, cust_ref, cust_gstin, Qty, invamt, uom, value1, rate;
  ');
  

 PREPARE stmt FROM @sql;
 EXECUTE stmt;
 DEALLOCATE PREPARE stmt;

IF voutype = "CNG" OR voutype = "CNN" THEN

    BEGIN
        DECLARE done INT DEFAULT FALSE;
        DECLARE colname VARCHAR(100);
        DECLARE colcount INT DEFAULT 0;

        DECLARE cur1 CURSOR FOR 
            SELECT col FROM (
                SELECT 'GST SALES @12% (DUPLEX)' AS col
                UNION ALL SELECT 'GST SALES@12%(PBL)'
                UNION ALL SELECT 'GST SALES @ 12%'
                UNION ALL SELECT 'GST SALES @ 12%(BLUE BOARD)'
                UNION ALL SELECT 'IGST SALES @ 12%(PBL)'
                UNION ALL SELECT 'IGST SALES @ 12%'


                UNION ALL SELECT 'GST SALES RETURN 12%'
				UNION ALL SELECT 'IGST SALES RETURN 12%'
                UNION ALL SELECT 'IGST SALES RETURN @12% (PBL)'
                                
                
                UNION ALL SELECT 'WASTE SALES GST 5%'
                UNION ALL SELECT 'WASTE SALES GST 18%'
                UNION ALL SELECT 'ELECTRICAL WASTE SALES GST 18%'
                
                UNION ALL SELECT 'ELECTRICAL WASTE SALES GST 18%'
                UNION ALL SELECT 'FLY ASH SALES-GST'
                UNION ALL SELECT 'FLY ASH SALES-IGST'

                UNION ALL SELECT 'IGST @5%'
                UNION ALL SELECT 'FREIGHT COLLECTED-GST'
                UNION ALL SELECT 'FREIGHT COLLECTED-IGST'
                
                UNION ALL SELECT 'TCS @01% COLLECTED'
                UNION ALL SELECT 'IGST@12% COLLECTED'
                             
                UNION ALL SELECT 'CGST'
                UNION ALL SELECT 'SGST'

                
                
                
            ) AS cols;

        DECLARE CONTINUE HANDLER FOR NOT FOUND SET done = TRUE;

        OPEN cur1;

        read_loop: LOOP
            FETCH cur1 INTO colname;
            IF done THEN
                LEAVE read_loop;
            END IF;

            -- Check column existence
            SELECT COUNT(*) INTO colcount 
            FROM INFORMATION_SCHEMA.COLUMNS 
            WHERE table_name = @table_name 
              AND table_schema = DATABASE()
              AND column_name = colname;

            IF colcount = 0 THEN
                SET @qry := CONCAT("ALTER TABLE ", newtablename, 
                                   " ADD `", colname, "` DECIMAL(12,2) NOT NULL DEFAULT '0'");
                PREPARE stmt2 FROM @qry;
                EXECUTE stmt2;
                DEALLOCATE PREPARE stmt2;
            END IF;
        END LOOP;

        CLOSE cur1;
    END;

ELSE  -- FOR DEBIT NOTE

    BEGIN
        DECLARE done INT DEFAULT FALSE;
        DECLARE colname VARCHAR(100);
        DECLARE colcount INT DEFAULT 0;

        DECLARE cur1 CURSOR FOR 
            SELECT col FROM (
                SELECT 'GST SALES @12% (DUPLEX)' AS col
                UNION ALL SELECT 'GST SALES@12%(PBL)'
                UNION ALL SELECT 'GST SALES @ 12%'
              
                UNION ALL SELECT 'GST SALES @ 12%(BLUE BOARD)'
                UNION ALL SELECT 'IGST SALES @ 12%(PBL)'
                UNION ALL SELECT 'IGST SALES @ 12%'


                UNION ALL SELECT 'GST SALES RETURN 12%'
				UNION ALL SELECT 'IGST SALES RETURN 12%'
                UNION ALL SELECT 'IGST SALES RETURN @12% (PBL)'
                                
                
                UNION ALL SELECT 'WASTE SALES GST 5%'
                UNION ALL SELECT 'WASTE SALES GST 18%'
                UNION ALL SELECT 'WASTE PAPER PURCHASE-IMPORT'
                UNION ALL SELECT 'WASTE PAPER-IGST 5%'        
                
                UNION ALL SELECT 'ELECTRICAL WASTE SALES GST 18%'
                
                
                UNION ALL SELECT 'FLY ASH SALES-GST'
                UNION ALL SELECT 'FLY ASH SALES-IGST'

                UNION ALL SELECT 'IGST @5%'
                UNION ALL SELECT 'FREIGHT COLLECTED-GST'
                UNION ALL SELECT 'FREIGHT COLLECTED-IGST'
                
                UNION ALL SELECT 'TCS @01% COLLECTED'
                UNION ALL SELECT 'IGST@12% COLLECTED'
                             
                UNION ALL SELECT 'CGST'
                UNION ALL SELECT 'SGST'


                UNION ALL SELECT 'CO GEN MACHINERY MAINTENANCE-GST 18%'
                UNION ALL SELECT 'CO GEN MACHINERY MAINTENANCE-GST 28%'
                UNION ALL SELECT 'CO GEN MACHINERY MAINTENANCE-IGST 18%'
                UNION ALL SELECT 'CO-GEN-MAINTENANCE EXEMPT'
                UNION ALL SELECT 'CO GEN MACHINERY MAINTENANCE-GST 12%'
                UNION ALL SELECT 'CO GEN MACHINERY MAINTENANCE-GST 5%'
                UNION ALL SELECT 'CO GEN MACHINERY MAINTENANCE -IGST 12%'
                UNION ALL SELECT 'CO GEN MACHINERY MAINTENANCE-IGST 5%'
                UNION ALL SELECT 'CO-GEN CHEMICAL GST 12%'
                UNION ALL SELECT 'CO-GEN CHEMICAL GST 18%'
                UNION ALL SELECT 'CO-GEN CHEMICAL GST 5%'
                UNION ALL SELECT 'CO-GEN COAL - IGST 5%'
                UNION ALL SELECT 'CO-GEN COAL-GST 5%'
                
				UNION ALL SELECT 'CHEMICAL-GST 18%'                
                UNION ALL SELECT 'CHEMICAL-IGST 18%'
                
                UNION ALL SELECT 'MACHINERY MAINTENANCE -IGST 18%'
				UNION ALL SELECT 'MACHINERY MAINTENANCE -IGST 12%'                   
                UNION ALL SELECT 'MACHINERY MAINTENANCE-GST 18%'
			    UNION ALL SELECT 'MACHINERY MAINTENANCE GST-12%'  

                           
                UNION ALL SELECT 'BUSINESS PROMOTION EXPENSES -IGST 18%'
                UNION ALL SELECT 'BUSINESS PROMOTION EXPENSES GST-12%'

                UNION ALL SELECT 'INPUT CGST@205%'
                UNION ALL SELECT 'INPUT SGST@205%'      
                UNION ALL SELECT 'INPUT -CGST @ 6%'
                UNION ALL SELECT 'INPUT -SGST @ 6%'
                UNION ALL SELECT 'INPUT IGST @18%'                

                UNION ALL SELECT 'INPUT CGST @9%'
                UNION ALL SELECT 'INPUT SGST @9%'
                UNION ALL SELECT 'INPUT CGST@14%'
                UNION ALL SELECT 'INPUT SGST@14%'        
                UNION ALL SELECT 'INPUT -IGST @ 12%'     
                UNION ALL SELECT 'INPUT -IGST@5%'         
             
                UNION ALL SELECT 'OTHER CHARGES'
                UNION ALL SELECT 'PACKING CHARGES-GST'
				UNION ALL SELECT 'PACKING -GST 18%'
                UNION ALL SELECT 'PACKING CHARGES - IGST'        
                
                UNION ALL SELECT 'FREIGHT INWARD RCM GST'                
                UNION ALL SELECT 'FREIGHT INWARD -GST'
                UNION ALL SELECT 'FREIGHT INWARD - IGST'

                UNION ALL SELECT 'TCS PAID-PURCHASE'

                UNION ALL SELECT 'VEHICLE MAINTENANCE GST 18%'
                UNION ALL SELECT 'VEHICLE MAINTENANCE GST 28%'                



                UNION ALL SELECT 'BIO FUEL GST -5%'   
				UNION ALL SELECT 'BIO FUEL GST 12%'
                
                UNION ALL SELECT 'REBATE AND DISCOUNT RECEIVED'
                UNION ALL SELECT 'CREDIT NOTE TO BE RECEIVED'
                UNION ALL SELECT 'CREDIT NOTE TO BE RECEIVED-PURCHASE-GST'
                UNION ALL SELECT 'CREDIT NOTE TO BE RECEIVED-PURCHASE-IGST'


                UNION ALL SELECT 'INTEREST TO BE RECEIVED'

                UNION ALL SELECT 'SUNDRY EXPENSE'

                    
            ) AS cols;

        DECLARE CONTINUE HANDLER FOR NOT FOUND SET done = TRUE;

        OPEN cur1;

        read_loop: LOOP
            FETCH cur1 INTO colname;
            IF done THEN
                LEAVE read_loop;
            END IF;

            -- Check column existence
            SELECT COUNT(*) INTO colcount 
            FROM INFORMATION_SCHEMA.COLUMNS 
            WHERE table_name = @table_name 
              AND table_schema = DATABASE()
              AND column_name = colname;

            IF colcount = 0 THEN
                SET @qry := CONCAT("ALTER TABLE ", newtablename, 
                                   " ADD `", colname, "` DECIMAL(12,2) NOT NULL DEFAULT '0'");
                PREPARE stmt2 FROM @qry;
                EXECUTE stmt2;
                DEALLOCATE PREPARE stmt2;
            END IF;
        END LOOP;

        CLOSE cur1;
    END;
END IF;

    BEGIN
        DECLARE done INT DEFAULT FALSE;
        DECLARE colname VARCHAR(100);
        DECLARE colcount INT DEFAULT 0;

        DECLARE cur1 CURSOR FOR 
            SELECT col FROM (
                SELECT 'ROUNDED OFF' AS col
                UNION ALL SELECT 'REBATE AND DISCOUNT PAID'
                UNION ALL SELECT 'BAD DEBTS - WRITE OFF'
            ) AS cols;
            
                    DECLARE CONTINUE HANDLER FOR NOT FOUND SET done = TRUE;

        OPEN cur1;

        read_loop: LOOP
            FETCH cur1 INTO colname;
            IF done THEN
                LEAVE read_loop;
            END IF;

            -- Check column existence
            SELECT COUNT(*) INTO colcount 
            FROM INFORMATION_SCHEMA.COLUMNS 
            WHERE table_name = @table_name 
              AND table_schema = DATABASE()
              AND column_name = colname;

            IF colcount = 0 THEN
                SET @qry := CONCAT("ALTER TABLE ", newtablename, 
                                   " ADD `", colname, "` DECIMAL(12,2) NOT NULL DEFAULT '0'");
                PREPARE stmt2 FROM @qry;
                EXECUTE stmt2;
                DEALLOCATE PREPARE stmt2;
            END IF;
        END LOOP;

        CLOSE cur1;
    END;    
END ;;
DELIMITER ;
