DELIMITER ;;
CREATE DEFINER=`root`@`%` PROCEDURE `spacc_rep_ledger_column_report_voucher_JV`(compcode int,fincode int,startdate date,enddate date,tablename varchar(50))
BEGIN

declare  newtablename varchar(50);

set newtablename = tablename;
SET SESSION group_concat_max_len =  18446744073709551615;
set @compcode = compcode;
set @fincode = fincode;
set @startdate = startdate;
set @enddate = enddate;



SET @sql = NULL;

set @table_name = tablename;
set @table_name2 = tablename;

set @table_name = tablename;

SET @tabledelete := CONCAT('DROP TABLE ',tablename);
 IF EXISTS (SELECT NULL
             FROM   information_schema.tables t
             WHERE  t.table_schema = database()
             AND    t.table_name = tablename)
  THEN
 
    /* Dynamically allocated and run statement. */
    PREPARE stmt2 FROM @tabledelete;
    EXECUTE stmt2;
    DEALLOCATE PREPARE stmt2;
  END IF;
  
 SELECT
  GROUP_CONCAT(DISTINCT
    CONCAT(
      'sum(case when ledger_name = ''',
      dt,
      ''' then ledger_amt else 0 end) AS `',
      dt, '`'
    )
  ) INTO @sql
from
(
select ledger_name as dt  from 
(
WITH jvheader AS (
    SELECT 
        a.accref_seqno,
        a.accref_vouno,
        a.accref_voudate,
        l.cust_type AS ledtype,
        a.accref_seqno AS accrefno,
        l.cust_ref,
        l.cust_gstin,
        b.acctran_totamt AS invamt,
        LEFT(a.accref_payref_no, 13) AS vou_refno,
        a.accref_payref_date AS billdate,
        a.accref_narration,
        b.acctran_serialno AS slno,
        ROW_NUMBER() OVER (PARTITION BY a.accref_vouno ORDER BY b.acctran_serialno) AS rn
    FROM 
        acc_ref a
    JOIN 
        acc_tran b ON a.accref_seqno = b.acctran_accref_seqno
    JOIN 
        massal_customer l ON b.acctran_led_code = l.cust_code
    WHERE 
        l.cust_type != 'G'
        AND a.accref_vou_type = 'GJV'
        AND a.accref_voudate BETWEEN startdate AND enddate

    UNION ALL        

    SELECT 
        accref_seqno,
        accref_vouno,
        accref_voudate,
        cust_type AS ledtype,
        accref_seqno AS accrefno,
        cust_ref,
        cust_gstin,
        acctran_totamt AS invamt, 
        LEFT(accref_payref_no, 13) AS vou_refno,
        accref_payref_date AS billdate,
        accref_narration,
        acctran_serialno AS slno,
        1 AS rn
    FROM 
        acc_ref a
    JOIN 
        acc_tran b ON accref_seqno = acctran_accref_seqno
    JOIN 
        massal_customer l ON acctran_led_code = cust_code
    WHERE 
        accref_comp_code = 1 
        AND accref_voudate BETWEEN startdate AND enddate
        AND accref_vou_type = 'GJV' 
        AND accref_seqno NOT IN (
            SELECT accref_seqno
            FROM acc_ref a
            JOIN acc_tran b ON a.accref_seqno = b.acctran_accref_seqno
            JOIN massal_customer l ON b.acctran_led_code = l.cust_code
            WHERE 
                cust_type != 'G'  
                AND accref_comp_code = 1 
                AND accref_voudate BETWEEN startdate AND enddate 
                AND accref_vou_type = 'GJV'
            GROUP BY accref_seqno
        )
        AND acctran_serialno = 1
),

jvledger AS (
    SELECT 
        accref_seqno AS acseqno, 
        cust_name AS ledger_name, 
        acctran_totamt AS ledger_amt, 
        acctran_serialno  
    FROM 
        acc_ref 
    JOIN 
        acc_tran ON accref_seqno = acctran_accref_seqno
    JOIN 
        massal_customer ON acctran_led_code = cust_code
    WHERE 
        accref_comp_code = 1
        AND accref_vou_type = 'GJV'
        AND accref_finid = fincode
        AND accref_voudate BETWEEN startdate AND enddate
)

SELECT 
    jh.accref_seqno,
    jh.accref_vouno,
    jh.accref_voudate,
    jh.ledtype,
    jh.accrefno,
    jh.cust_ref,
    jh.cust_gstin,
    jh.invamt,
    jh.vou_refno,
    jh.billdate,
    jh.accref_narration,
    jh.slno,
    jl.ledger_name,
    jl.ledger_amt
FROM 
    jvheader jh
LEFT JOIN 
    jvledger jl ON jh.accref_seqno = jl.acseqno 
                 AND jl.acctran_serialno <> jh.slno
WHERE 
    jh.rn = 1
ORDER BY 
    jh.accref_voudate, 
    jh.accref_vouno
)t1 
 order by ledger_name ) d;



SET @sql 
  = CONCAT('create table ' ,@table_name ,' as   select 
	accref_seqno, accref_voudate, accref_vouno, cust_ref, cust_gstin, invamt, vou_refno, billdate,  accref_narration, ', @sql, ' from 
  (
WITH jvheader AS (
    SELECT 
        a.accref_seqno,
        a.accref_vouno,
        a.accref_voudate,
        l.cust_type AS ledtype,
        a.accref_seqno AS accrefno,
        l.cust_ref,
        l.cust_gstin,
        b.acctran_totamt AS invamt,
        LEFT(a.accref_payref_no, 13) AS vou_refno,
        a.accref_payref_date AS billdate,
        a.accref_narration,
        b.acctran_serialno AS slno,
        ROW_NUMBER() OVER (PARTITION BY a.accref_vouno ORDER BY b.acctran_serialno) AS rn
    FROM 
        acc_ref a
    JOIN 
        acc_tran b ON a.accref_seqno = b.acctran_accref_seqno
    JOIN 
        massal_customer l ON b.acctran_led_code = l.cust_code
    WHERE 
        l.cust_type != "G"
        AND a.accref_vou_type = "GJV"
        AND a.accref_voudate BETWEEN @startdate AND @enddate

    UNION ALL        

    SELECT 
        accref_seqno,
        accref_vouno,
        accref_voudate,
        cust_type AS ledtype,
        accref_seqno AS accrefno,
        cust_ref,
        cust_gstin,
        acctran_totamt AS invamt, 
        LEFT(accref_payref_no, 13) AS vou_refno,
        accref_payref_date AS billdate,
        accref_narration,
        acctran_serialno AS slno,
        1 AS rn
    FROM 
        acc_ref a
    JOIN 
        acc_tran b ON accref_seqno = acctran_accref_seqno
    JOIN 
        massal_customer l ON acctran_led_code = cust_code
    WHERE 
        accref_comp_code = 1 
        AND accref_voudate BETWEEN @startdate AND @enddate
        AND accref_vou_type = "GJV" 
        AND accref_seqno NOT IN (
            SELECT accref_seqno
            FROM acc_ref a
            JOIN acc_tran b ON a.accref_seqno = b.acctran_accref_seqno
            JOIN massal_customer l ON b.acctran_led_code = l.cust_code
            WHERE 
                cust_type != "G"  
                AND accref_comp_code = 1 
                AND accref_voudate BETWEEN @startdate AND @enddate 
                AND accref_vou_type = "GJV"
            GROUP BY accref_seqno
        )
        AND acctran_serialno = 1
),

jvledger AS (
    SELECT 
        accref_seqno AS acseqno, 
        cust_name AS ledger_name, 
        acctran_totamt AS ledger_amt, 
        acctran_serialno  
    FROM 
        acc_ref 
    JOIN 
        acc_tran ON accref_seqno = acctran_accref_seqno
    JOIN 
        massal_customer ON acctran_led_code = cust_code
    WHERE 
        accref_comp_code = 1
        AND accref_vou_type = "GJV"
        AND accref_finid = @fincode
        AND accref_voudate BETWEEN @startdate AND @enddate
)

SELECT 
    jh.accref_seqno,
    jh.accref_vouno,
    jh.accref_voudate,
    jh.ledtype,
    jh.accrefno,
    jh.cust_ref,
    jh.cust_gstin,
    jh.invamt,
    jh.vou_refno,
    jh.billdate,
    jh.accref_narration,
    jh.slno,
    jl.ledger_name,
    jl.ledger_amt
FROM 
    jvheader jh
LEFT JOIN 
    jvledger jl ON jh.accref_seqno = jl.acseqno 
                 AND jl.acctran_serialno <> jh.slno
WHERE 
    jh.rn = 1
ORDER BY 
    jh.accref_voudate, 
    jh.accref_vouno

)t1 
  group by 
   accref_seqno,  accref_voudate,accref_vouno,cust_ref, cust_gstin, invamt, vou_refno, billdate, accref_narration, ledtype  ;
  
  ');
  

 PREPARE stmt FROM @sql;
 EXECUTE stmt;
 DEALLOCATE PREPARE stmt;
 
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
