CREATE DEFINER=`root`@`%` PROCEDURE `spacc_rep_ledger_column_report_voucher_JV_TOBEDELTED`(compcode int,fincode int,startdate date,enddate date,tablename varchar(50))
BEGIN

declare  newtablename varchar(50);

set newtablename = tablename;
SET SESSION group_concat_max_len =  18446744073709551615;
set @compcode = compcode;
set @fincode = fincode;
set @startdate = startdate;
set @enddate = enddate;



SET @sql = NULL;

set @table_name = tablename;
set @table_name2 = tablename;

set @table_name = tablename;

SET @tabledelete := CONCAT('DROP TABLE ',tablename);
 IF EXISTS (SELECT NULL
             FROM   information_schema.tables t
             WHERE  t.table_schema = database()
             AND    t.table_name = tablename)
  THEN
 
    /* Dynamically allocated and run statement. */
    PREPARE stmt2 FROM @tabledelete;
    EXECUTE stmt2;
    DEALLOCATE PREPARE stmt2;
  END IF;
  
 SELECT
  GROUP_CONCAT(DISTINCT
    CONCAT(
      'sum(case when ledger_name = ''',
      dt,
      ''' then ledger_amt else 0 end) AS `',
      dt, '`'
    )
  ) INTO @sql
from
(
select ledger_name as dt  from 
(

select
 accref_seqno,  accref_voudate,accref_vouno,cust_ref, cust_gstin, invamt, vou_refno, billdate,  accref_narration,
 acseqno, ledger_name, sum(jvamt) ledger_amt, ledtype 
from (

select  acseqno, ledger_name, jvamt ,  ledtype,accref_seqno ,accref_vouno , accref_voudate , cust_ref, cust_gstin, invamt,  vou_refno,billdate,slno,accref_narration from 
(

select accref_seqno, accref_vouno, accref_voudate, ledtype, accrefno, cust_ref ,  cust_gstin, invamt,  vou_refno, billdate , accref_narration, slno from (

select accref_seqno, accref_vouno, accref_voudate, ledtype, accrefno, max(cust_ref) cust_ref , max(cust_gstin) cust_gstin, invamt,  vou_refno, billdate , accref_narration,min(acctran_serialno) slno from (
select accref_seqno,accref_vouno , accref_voudate ,cust_type as ledtype, accref_seqno accrefno,cust_ref,cust_gstin, acctran_totamt  as invamt, 
  left(accref_payref_no,13) as vou_refno ,accref_payref_date billdate ,accref_narration,acctran_serialno
from acc_ref a ,  acc_tran b , massal_customer l   where 
cust_type != 'G'  and accref_comp_code = 1 and  acctran_led_code = cust_code and accref_seqno = acctran_accref_seqno and accref_voudate between startdate and enddate and  accref_vou_type = 'GJV'  and cust_gstin != ''
) a1 group by accref_seqno, accref_vouno, accref_voudate, ledtype, accrefno, invamt , vou_refno ,billdate,accref_narration


union all

select accref_seqno,accref_vouno , accref_voudate ,cust_type as ledtype, accref_seqno accrefno,cust_ref,cust_gstin, acctran_totamt  as invamt, 
  left(accref_payref_no,13) as vou_refno ,accref_payref_date billdate ,accref_narration,acctran_serialno slno
from acc_ref a ,  acc_tran b , massal_customer l   where 
 accref_comp_code = 1 and acctran_led_code = cust_code and accref_seqno = acctran_accref_seqno and accref_voudate between startdate and enddate and  accref_vou_type = "GJV" 
and accref_seqno not in (
select accref_seqno
from acc_ref a ,  acc_tran b , massal_customer l   where 
cust_type != "G"  and accref_comp_code = 1 and  acctran_led_code = cust_code and accref_seqno = acctran_accref_seqno  and accref_voudate between startdate and enddate and  accref_vou_type = "GJV"   and cust_gstin != ''
group by accref_seqno) and acctran_serialno =1 

) aa1 group by accref_seqno, accref_vouno, accref_voudate, ledtype, accrefno, cust_ref, cust_gstin, invamt , vou_refno ,billdate,accref_narration,slno


 ) jv1
left join 

(

select accref_seqno acseqno, cust_name ledger_name, acctran_totamt jvamt , acctran_serialno  from acc_ref ,  acc_tran , massal_customer  where accref_seqno = acctran_accref_seqno and  accref_comp_code = 1
and accref_vou_type = 'GJV'  and acctran_led_code = cust_code and  accref_comp_code = 1 and accref_finid = 25 and accref_voudate between startdate and enddate 

) jv2
on jv1.accref_seqno = jv2.acseqno  and acctran_serialno <> slno order by accref_voudate ,acseqno
) aa2 
group by  
accref_seqno,  accref_voudate,accref_vouno,cust_ref, cust_gstin, invamt, vou_refno, billdate, accref_narration,
 acseqno, ledger_name, ledtype 
)t1 
 order by ledger_name ) d;



SET @sql 
  = CONCAT('create table ' ,@table_name ,' as   select 
	accref_seqno, accref_voudate, accref_vouno, cust_ref, cust_gstin, invamt, vou_refno, billdate,  accref_narration, acseqno
    ,', @sql, ' from 
  (
  
select
 accref_seqno,  accref_voudate,accref_vouno,cust_ref, cust_gstin, invamt, vou_refno, billdate,  accref_narration,
 acseqno, ledger_name, sum(jvamt) ledger_amt, ledtype 
from (

select  acseqno, ledger_name, jvamt ,  ledtype,accref_seqno ,accref_vouno , accref_voudate , cust_ref, cust_gstin, invamt,  vou_refno,billdate,slno,accref_narration from 
(

select accref_seqno, accref_vouno, accref_voudate, ledtype, accrefno, cust_ref ,  cust_gstin, invamt,  vou_refno, billdate , accref_narration, slno from (

select accref_seqno, accref_vouno, accref_voudate, ledtype, accrefno, max(cust_ref) cust_ref , max(cust_gstin) cust_gstin, invamt,  vou_refno, billdate , accref_narration,min(acctran_serialno) slno from (
select accref_seqno,accref_vouno , accref_voudate ,cust_type as ledtype, accref_seqno accrefno,cust_ref,cust_gstin, acctran_totamt  as invamt, 
  left(accref_payref_no,13) as vou_refno ,accref_payref_date billdate ,accref_narration,acctran_serialno
from acc_ref a ,  acc_tran b , massal_customer l   where 
cust_type != "G"  and accref_comp_code = 1 and  acctran_led_code = cust_code and accref_seqno = acctran_accref_seqno and accref_voudate between @startdate and @enddate and  accref_vou_type = "GJV"  and cust_gstin != ""
) a1 group by accref_seqno, accref_vouno, accref_voudate, ledtype, accrefno, invamt , vou_refno ,billdate,accref_narration


union all

select accref_seqno,accref_vouno , accref_voudate ,cust_type as ledtype, accref_seqno accrefno,cust_ref,cust_gstin, acctran_totamt  as invamt, 
  left(accref_payref_no,13) as vou_refno ,accref_payref_date billdate ,accref_narration,acctran_serialno slno
from acc_ref a ,  acc_tran b , massal_customer l   where accref_comp_code = 1 and 
 acctran_led_code = cust_code and accref_seqno = acctran_accref_seqno and accref_voudate between @startdate and @enddate and  accref_vou_type = "GJV" 
and accref_seqno not in (
select accref_seqno
from acc_ref a ,  acc_tran b , massal_customer l   where 
cust_type != "G"  and  accref_comp_code = 1 and  acctran_led_code = cust_code and accref_seqno = acctran_accref_seqno and accref_voudate between @startdate and @enddate and  accref_vou_type = "GJV"   and cust_gstin != "" 
group by accref_seqno) and acctran_serialno =1 

) aa1 group by accref_seqno, accref_vouno, accref_voudate, ledtype, accrefno, cust_ref, cust_gstin, invamt , vou_refno ,billdate,accref_narration,slno


 ) jv1
left join 

(

select accref_seqno acseqno, cust_name ledger_name, acctran_totamt jvamt , acctran_serialno  from acc_ref ,  acc_tran , massal_customer  where accref_seqno = acctran_accref_seqno and  accref_comp_code = 1
and accref_vou_type = "GJV"  and acctran_led_code = cust_code and  accref_comp_code = 1 and accref_finid = 25 and accref_voudate between @startdate and @enddate 

) jv2
on jv1.accref_seqno = jv2.acseqno  and acctran_serialno <> slno order by accref_voudate ,acseqno
) aa2 
group by  
accref_seqno,  accref_voudate,accref_vouno,cust_ref, cust_gstin, invamt, vou_refno, billdate, accref_narration,
 acseqno, ledger_name, ledtype 

)t1 
  group by 
   accref_seqno,  accref_voudate,accref_vouno,cust_ref, cust_gstin, invamt, vou_refno, billdate, accref_narration, acseqno, ledtype  ;
  
  ');
  

 PREPARE stmt FROM @sql;
 EXECUTE stmt;
 DEALLOCATE PREPARE stmt;
 
END ;;
DELIMITER ;
