DELIMITER ;;
CREATE DEFINER=`root`@`%` PROCEDURE `spacc_rep_ledger_month`(
compcode int,
fincode int,
ledgercode int
)
BEGIN
select cust_name led_name,month(accref_voudate) rmonth ,MONTHNAME(accref_voudate)  rmonthname,sum(acctran_dbamt) debit , sum(acctran_cramt) credit   from  acc_ref, acc_tran , massal_customer where accref_seqno = acctran_accref_seqno and  acctran_led_code = cust_code and 
accref_comp_code = compcode and  accref_finid = fincode and 
acctran_led_code = ledgercode group by cust_name,month(accref_voudate),MONTHNAME(accref_voudate);
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `spacc_rep_m100days_coll_due` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`%` PROCEDURE `spacc_rep_m100days_coll_due`(fincode int, repcode int)
BEGIN
select coll.*,case when due.overdue is null then 0 else due.overdue end as overdue   from 
(
select repr_name,cust_name ,
sum(Apr) Apr,
sum(May) May,
sum(Jun) Jun,
sum(Jul) Jul,
sum(Aug) Aug,
sum(Sep) Sep,
sum(Oct) Oct,
sum(Nov) Nov,
sum(Dece) Dece,
sum(Jan) Jan,
sum(Feb) Feb,
sum(Mar) Mar
 from
(select repr_name,cust_name 
, case when collmonth = 4 then sum(collamt) else 0 end as Apr
, case when collmonth = 5 then sum(collamt) else 0 end as May
, case when collmonth = 6 then sum(collamt) else 0 end as Jun
, case when collmonth = 7 then sum(collamt) else 0 end as Jul
, case when collmonth = 8 then sum(collamt) else 0 end as Aug
, case when collmonth = 9 then sum(collamt) else 0 end as Sep
, case when collmonth = 10 then sum(collamt) else 0 end as Oct
, case when collmonth = 11 then sum(collamt) else 0 end as Nov
, case when collmonth = 12 then sum(collamt) else 0 end as Dece
, case when collmonth = 1 then sum(collamt) else 0 end as Jan
, case when collmonth = 2 then sum(collamt) else 0 end as Feb
, case when collmonth = 3 then sum(collamt) else 0 end as Mar

 from (
select repr_name,cust_name ,collyear, collmonth,invmonth, sum(refamount) as collamt from (

select * from 
(
select accref_seqno,accref_vouno,accref_voudate,accref_paymode, accref_payref_no , accref_payref_date ,acctran_totamt,
 ref_invno refpartyinvno,ref_invdate refpartyinvdate, ref_adjvouno refpurchaseno, ref_adjamount refamount,acctrail_crdays+acctrail_gracedays acctrail_crdays,acctrail_inv_value,cust_code,cust_name,
 DATEDIFF( accref_voudate, ref_invdate) as noofdays , DATEDIFF( accref_voudate, ref_invdate)-(acctrail_crdays+acctrail_gracedays) as daysfromduedate,repr_name  ,year(accref_voudate) collyear, month(accref_voudate) collmonth, concat(MONTHNAME(accref_voudate) ,'-' ,year(accref_voudate)) as invmonth 
 from acc_ref ref left join acc_tran trn
 on ref.accref_seqno = trn.acctran_accref_seqno
 left join acc_adjustments adj 
 on ref.accref_seqno = adj.ref_docseqno
 left join acc_trail trail 
 on adj.ref_adjseqno = trail.acctrail_accref_seqno 
 join massal_customer mas
 on trn.acctran_led_code = mas.cust_code and cust_type = 'C' and acctran_cramt > 0 
 join massal_repr repr  on   repr.repr_code = mas.cust_repr and repr_accgrp = repcode
 where accref_comp_code = 1 and accref_finid = fincode  and accref_vou_type in ('BKR')  order by refpartyinvdate desc
 )a1 
 
) a1 where noofdays >= 100  group by repr_name,cust_name,collyear, collmonth,invmonth order by cust_name, collyear,collmonth

) aa1 group by repr_name,cust_name ,collmonth
) aa2  group by repr_name,cust_name  
) coll
left join 
(select repr_name,cust_name,sum(balamt) overdue from (
select acctrail_inv_date,accref_voudate,acctrail_crdays,acctrail_gracedays,
cust_name, DATEDIFF( curdate(),accref_voudate) as noofdays ,repr_name,  
acctrail_inv_value - acctrail_adj_value balamt
 from acc_ref ref 
 left join acc_trail trail 
 on ref.accref_seqno  = trail.acctrail_accref_seqno 
 join massal_customer mas
 on trail.acctrail_led_code = mas.cust_code and cust_type = 'C' and acctrail_amtmode = 'D' 
 join massal_repr repr  on   repr.repr_code = mas.cust_repr and repr_accgrp = repcode
 where accref_comp_code = 1 and accref_vou_type in ('GSI')  and acctrail_inv_value > acctrail_adj_value 
 )a1 where noofdays >= 100 group by repr_name,cust_name 
) due on coll.repr_name = due.repr_name and  coll.cust_name = due.cust_name;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `spacc_rep_Monthwise_CashBank` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`%` PROCEDURE `spacc_rep_Monthwise_CashBank`(compcode int,fincode int, startdate date, enddate date ,ledcode int )
BEGIN
select year(accref_voudate) repyear,month(accref_voudate) repmonth,UPPER(monthname(accref_voudate)) as rmonth  , sum(acctran_cramt)   dramt ,  sum(acctran_dbamt) cramt  from ( 
select * from acc_ref ref  join acc_tran tran on  
tran.acctran_accref_seqno = ref.accref_seqno   where  
acctran_led_code <> ledcode and  accref_comp_code = compcode  and accref_finid = fincode and
accref_voudate between startdate and enddate and  acctran_accref_seqno in 
 (  select acctran_accref_seqno from acc_ref ref  join acc_tran tran on  tran.acctran_accref_seqno = ref.accref_seqno   where  acctran_led_code = ledcode and  accref_comp_code = compcode and accref_finid = fincode and
 accref_voudate between startdate and enddate group by acctran_accref_seqno)
 ) a1 group by repyear,repmonth,upper(monthname(accref_voudate)) order by repyear,repmonth;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
