/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`%` PROCEDURE `spacc_rep_Purchase_Register`(compcode int,startdate date,enddate date,purtype varchar(3))
BEGIN

if purtype = "FU"  then
	select * from (
	select  rech_seqno,rech_no,rech_date,c.cust_name ,  c.cust_gstin,rech_billno, rech_billdate, p.cust_name purledger,
	 rech_itemvalue, rech_cgst_per, rech_cgst_amt, rech_sgst_per, rech_sgst_amt, rech_igst_per, rech_igst_amt, rech_handling_pmt, rech_handling_cgstper, rech_handling_sgstper, rech_handling_cgstamt, rech_handling_sgstamt, rech_tcs_per, rech_tcs_amt, rech_cess_pmt, rech_cess_amount, rech_freight, rech_othcharges, rech_roundingoff, rech_totalamount,
	 rect_seqno,itmh_name,rect_grnqty , rect_itemrate,rect_itemvalue
	  from trnfu_receipt_header h, trnfu_receipt_trailer t, massal_customer c ,massal_customer p , masfu_item_header i  
	where h.rech_seqno = t.rect_hdseqno and h.rech_sup_code = c.cust_code and 
	h.rech_sup_code = c.cust_code and 
	h.rech_purgrp = p.cust_code and 
	t.rect_item_code = i.itmh_code and
	h.rech_compcode =  compcode and h.rech_date between  startdate and enddate) a1;
    
	elseif purtype = "WP"  then
	
        select * from (
		select  rech_seqno,rech_no,rech_date,c.cust_name ,  c.cust_gstin,rech_billno, rech_billdate, p.cust_name purledger,
		 rech_itemvalue, rech_cgst_per, rech_cgst_amt, rech_sgst_per, rech_sgst_amt, rech_igst_per, rech_igst_amt, 
		 -- rech_handling_pmt, rech_handling_cgstper, rech_handling_sgstper, rech_handling_cgstamt, rech_handling_sgstamt, 
		 rech_tcs_per, rech_tcs_amt, 
		 -- rech_cess_pmt, rech_cess_amount,rech_othcharges,
		 rech_freight,  rech_roundingoff, rech_totalamount,
		 rect_seqno,itmh_name,rect_grnqty , rect_itemrate,rect_itemvalue
		  from trnrm_receipt_header h, trnrm_receipt_trailer t, massal_customer c ,masrm_item_header i  ,massal_customer p 
		where h.rech_seqno = t.rect_hdseqno and h.rech_sup_code = c.cust_code and 
		h.rech_sup_code = c.cust_code and 
		 h.rech_purledger = p.cust_code and 
		t.rect_item_code = i.itmh_code and
		h.rech_compcode = compcode and h.rech_date between   startdate and enddate) a1;
   else
	select * from (
	select minh_mindate,minh_minno , cust.cust_name,minh_bill_no , minh_bill_date ,  led.cust_name purledger,item_name,
	mint_recdqty_bill,mint_unit_rate,mint_value,mint_igst_per,mint_igst_amt,mint_cgst_per,mint_cgst_amt,mint_sgst_per,mint_sgst_amt,minh_round_off,minh_value,mint_pfamt,mint_tcs_amt,mint_others
	  from trnpur_min_header h, trnpur_min_trailer t , massal_customer cust, massal_customer led ,maspur_item_header  where
	h.minh_sup_code = cust.cust_code and 
	t.mint_purgroup = led.cust_code and 
	t.mint_item_code =item_code and
	h.minh_comp_code = t.mint_comp_code and 
	h.minh_fin_code  = t.mint_fin_code and
	h.minh_minno     = t.mint_minno and 
	minh_comp_code = compcode  and 
	minh_mindate between startdate and enddate
	)a1 order by minh_mindate, minh_minno;

   end if;   
   

END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `spacc_rep_pur_vouprint` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`%` PROCEDURE `spacc_rep_pur_vouprint`(compcode int,fincode int,vouno varchar(15),dept varchar(1))
BEGIN
 if dept = 'A' then
     select * from  acc_direct_purchase , massal_customer where cust_code = pur_partycode and 
     pur_compcode = compcode and pur_finid = fincode and pur_vouno = vouno;

 else
      select * from (
select main.* , party.* , tax.cust_name purchase_ledname  , cgst.cust_name cgst_ledname , sgst.cust_name sgst_ledname , igst.cust_name igst_ledname 
      from  str_debit_note main , massal_customer party,
      massal_customer tax ,
      massal_customer cgst,
      massal_customer sgst,
      massal_customer igst      
      where 
      pur_taxledger = tax.cust_code and
      pur_cgst_ledger = cgst.cust_code and
      pur_sgst_ledger = sgst.cust_code and
      pur_igst_ledger = igst.cust_code and      
      party.cust_code = pur_partycode and 
     pur_compcode = compcode and pur_finid = fincode and pur_vouno = vouno
     ) a;
     
 end if;

END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `spacc_rep_receivablesagewise` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`%` PROCEDURE `spacc_rep_receivablesagewise`(compcode tinyint, asondate date)
BEGIN
select * from (
 select accref_seqno,accref_vouno,accref_voudate,accref_payref_no,accref_payref_date,
 d.cust_ref,acctrail_led_code,acctrail_inv_value,acctrail_adj_value, 
 acctrail_inv_value- acctrail_adj_value balamt,
 acctrail_amtmode,
 e.repr_name,acctrail_crdays
 ,  DATE_FORMAT(DATE_ADD(acctrail_inv_date, INTERVAL acctrail_crdays DAY) ,'%d-%m-%Y') as  duedate,
 DATEDIFF( asondate, DATE_ADD(acctrail_inv_date, INTERVAL acctrail_crdays DAY))  as oddays

from acc_ref a, acc_trail c , massal_customer d, massal_repr e where 
accref_seqno = acctrail_accref_seqno 
and c.acctrail_led_code = d.cust_code and d.cust_repr = e.repr_code
and acctrail_inv_value > acctrail_adj_value and acctrail_adj_value >= 0
and accref_comp_code = compcode 
and accref_voudate<= asondate
order by e.repr_name, d.cust_ref ) aa where balamt > 0 ;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `spacc_rep_receivables_outstanding` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`%` PROCEDURE `spacc_rep_receivables_outstanding`(compcode int, fromdate date,todate date,ledcode int,repcode int , overdue varchar(1) ,ptgd varchar(4) )
BEGIN
    select * from (
	select repr_name, repr_code, led_name, cust_add1, cust_add2, cust_add3, cust_city, cust_state, cust_zip, acctrail_led_code, acctrail_inv_no, acctrail_inv_date, max(acctrail_inv_value) acctrail_inv_value, max(acctrail_adj_value) acctrail_adj_value, sum(adjamt) adjamt, acctrail_crdays,acctrail_gracedays, duedate, oddays, acctrail_amtmode, accref_seqno,accref_vouno, accref_voudate from
    (
	   select repr_name,repr_code,cust_ref led_name,cust_add1, cust_add2, cust_add3, cust_city, cust_state,cust_zip,acctrail_led_code, acctrail_inv_no,  acctrail_inv_date, acctrail_inv_value, acctrail_adj_value, 0 adjamt ,
       acctrail_crdays ,acctrail_gracedays,  DATE_FORMAT(DATE_ADD(accref_voudate, INTERVAL acctrail_crdays DAY) ,'%d-%m-%Y') as  duedate,
       CASE WHEN ptgd = 'PT'THEN 
        DATEDIFF(todate, DATE_ADD(ref.accref_voudate, INTERVAL trail.acctrail_crdays DAY))
        ELSE DATEDIFF(todate, DATE_ADD(ref.accref_voudate, INTERVAL trail.acctrail_crdays + trail.acctrail_gracedays DAY))
        END AS oddays,
        acctrail_amtmode,accref_seqno,accref_vouno, accref_voudate
	    from acc_ref ref  left join acc_trail trail 
		on ref.accref_seqno = trail.acctrail_accref_seqno join massal_customer mas 
		on trail.acctrail_led_code = mas.cust_code and acctrail_inv_value > acctrail_adj_value -- and  mas.cust_type = 'C'					  
		join massal_repr repr on cust_repr = repr.repr_code  
		where accref_comp_code = compcode and accref_voudate <= todate -- and acctrail_amtmode = 'D' -- and (accref_vou_type = 'GSI'  or left(accref_vou_type,2) = 'DN')   
        and  (ledcode <= 0 OR acctrail_led_code = ledcode)
        and (repcode <= 0 OR repr_accgrp = repcode)
        
		union all
                     
		select repr_name,repr_code,cust_ref led_name,cust_add1, cust_add2, cust_add3, cust_city, cust_state,cust_zip,acctrail_led_code, acctrail_inv_no,  acctrail_inv_date, acctrail_inv_value, acctrail_adj_value, ref_adjamount  adjamt, 
		acctrail_crdays , acctrail_gracedays, DATE_FORMAT(DATE_ADD(accref_voudate, INTERVAL acctrail_crdays DAY) ,'%d-%m-%Y') as  duedate,
        CASE WHEN ptgd = 'PT'THEN 
        DATEDIFF(todate, DATE_ADD(ref2.accref_voudate, INTERVAL trail.acctrail_crdays DAY))
        ELSE DATEDIFF(todate, DATE_ADD(ref2.accref_voudate, INTERVAL trail.acctrail_crdays + trail.acctrail_gracedays DAY))
        END AS oddays,
        acctrail_amtmode,ref_adjseqno accref_seqno,accref_vouno, accref_voudate
		from acc_adjustments ref  left join acc_trail trail 
		on ref.ref_adjseqno = trail.acctrail_accref_seqno join massal_customer mas 
		on trail.acctrail_led_code = mas.cust_code	
        left join acc_ref ref2 on ref.ref_adjseqno =  ref2.accref_seqno                           
		join massal_repr repr on cust_repr = repr.repr_code    and acctrail_led_code =  ref_ledcode
		where ref_compcode = compcode and ref_adjvoudate  <= todate  and ref_docdate > todate -- and ref_adjvoutype = 'GSI'  and acctrail_amtmode = 'D'                            
        and  (ledcode <= 0 OR acctrail_led_code = ledcode)
        and (repcode <= 0 OR repr_accgrp = repcode)
) a1                     
group by repr_name, repr_code, led_name, cust_add1, cust_add2, cust_add3, cust_city, cust_state, cust_zip, acctrail_led_code, acctrail_inv_no, acctrail_inv_date, acctrail_crdays,acctrail_gracedays, duedate, oddays, acctrail_amtmode, accref_seqno,accref_vouno, accref_voudate 
) aa where  (overdue <> 'Y' OR oddays > 0)  order by accref_voudate asc  ,acctrail_inv_no;
END ;;
