group by repr_name, repr_code, led_name, cust_add1, cust_add2, cust_add3, cust_city, cust_state, cust_zip, acctrail_led_code, acctrail_inv_no, acctrail_inv_date, acctrail_crdays, acctrail_gracedays,duedate, oddays, acctrail_amtmode, accref_seqno ,accref_vouno, accref_voudate 
	 
				  ) aa order by accref_voudate asc , acctrail_inv_no;  
			  end if;   
		end if;

	end if;
end if;    
END ;;
