/*!50003 DROP PROCEDURE IF EXISTS `spacc_rep_receivables_outstanding_Bills_Agewise` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`%` PROCEDURE `spacc_rep_receivables_outstanding_Bills_Agewise`(compcode int, fromdate date,todate date,ledcode int,repcode int , overdue varchar(1) ,ptgd varchar(4) , 
agedays1 int,
agedays2 int,
agedays3 int,
agedays4 int )
BEGIN
SET @cond_rep := '';
SET @cond_led := '';
SET @cond_overdue := '';

IF repcode <> 0 THEN
    SET @cond_rep = CONCAT(' AND grp_code = ', repcode);
END IF;

IF ledcode <> 0 THEN
    SET @cond_led = CONCAT(' AND acctrail_led_code = ', ledcode);
END IF;


IF overdue = "Y" THEN
    SET @cond_overdue = CONCAT(' where oddays >= 0 ');     
END IF;

SET @tod := todate;

SET @agedays1 := agedays1;
SET @agedays2 := agedays2;
SET @agedays3 := agedays3;
SET @agedays4 := agedays4;


  DROP TABLE IF EXISTS tmp_AR_Agewise;
  
  
SET @sql = CONCAT(   "CREATE  TABLE tmp_AR_Agewise AS ", "
SELECT * ,
	case when oddays<= @agedays1 then  acctrail_inv_value- acctrail_adj_value + adjamt else 0 end as Agegrp1,
	case when oddays > @agedays1 and  oddays<= @agedays2 then  acctrail_inv_value- acctrail_adj_value + adjamt else 0 end as Agegrp2,
	case when oddays > @agedays2 and  oddays<= @agedays3 then  acctrail_inv_value- acctrail_adj_value + adjamt else 0 end as Agegrp3,
	case when oddays > @agedays3 and  oddays<= @agedays4 then  acctrail_inv_value- acctrail_adj_value + adjamt else 0 end as Agegrp4,
	case when oddays > @agedays4 then  acctrail_inv_value- acctrail_adj_value + adjamt else 0 end as Agegrp5
FROM (
SELECT * FROM (
  SELECT repr_name, repr_code, led_name,
         acctrail_led_code, acctrail_inv_no, acctrail_inv_date,
         MAX(acctrail_inv_value) acctrail_inv_value,
         MAX(acctrail_adj_value) acctrail_adj_value,
         SUM(adjamt) adjamt, acctrail_crdays, duedate, oddays, acctrail_amtmode, accref_seqno
  FROM (
    SELECT grp_name repr_name, grp_code repr_code, cust_ref led_name, cust_add1, cust_add2, cust_add3,
           cust_city, cust_state, cust_zip, acctrail_led_code, acctrail_inv_no, acctrail_inv_date,
           acctrail_inv_value, acctrail_adj_value, 0 adjamt,
           acctrail_crdays,
           CASE WHEN '", ptgd, "' = 'PT' 
           THEN DATE_ADD(acctrail_inv_date, INTERVAL acctrail_crdays DAY) 
           ELSE DATE_ADD(acctrail_inv_date, INTERVAL acctrail_crdays+acctrail_gracedays DAY)          
           END AS duedate,
		   CASE WHEN '", ptgd, "' = 'PT' 
           THEN DATEDIFF(@tod, DATE_ADD(acctrail_inv_date, INTERVAL acctrail_crdays DAY))
           ELSE DATEDIFF(@tod, DATE_ADD(acctrail_inv_date, INTERVAL acctrail_crdays+acctrail_gracedays DAY))  
           END AS oddays,           
           acctrail_amtmode, accref_seqno
    FROM acc_ref ref
    LEFT JOIN acc_trail trail ON ref.accref_seqno = trail.acctrail_accref_seqno
    JOIN massal_customer mas ON trail.acctrail_led_code = mas.cust_code and  mas.cust_type = 'C'
    JOIN acc_group_master repr ON cust_acc_group = repr.grp_code
    WHERE accref_comp_code = 1
      AND accref_voudate <= @tod
      AND acctrail_amtmode = 'D'
      AND acctrail_inv_value > acctrail_adj_value
      AND accref_vou_type IN ('GSI', 'SDN', 'OPB')
      ", @cond_rep, @cond_led, "
    UNION ALL
    SELECT grp_name repr_name, grp_code repr_code, cust_ref led_name, cust_add1, cust_add2, cust_add3,
           cust_city, cust_state, cust_zip, acctrail_led_code, acctrail_inv_no, acctrail_inv_date,
           acctrail_inv_value, acctrail_adj_value, ref_adjamount adjamt,
           acctrail_crdays,
           CASE WHEN '", ptgd, "' = 'PT' 
           THEN DATE_ADD(acctrail_inv_date, INTERVAL acctrail_crdays DAY)
           ELSE DATE_ADD(acctrail_inv_date, INTERVAL acctrail_crdays+acctrail_gracedays DAY)          
           END AS duedate,
		   CASE WHEN '", ptgd, "' = 'PT' 
           THEN DATEDIFF(@tod, DATE_ADD(acctrail_inv_date, INTERVAL acctrail_crdays DAY))
           ELSE DATEDIFF(@tod, DATE_ADD(acctrail_inv_date, INTERVAL acctrail_crdays+acctrail_gracedays  DAY))  
           END AS oddays,           
           acctrail_amtmode, ref_adjseqno accref_seqno
    FROM acc_adjustments ref
    LEFT JOIN acc_trail trail ON ref.ref_adjseqno = trail.acctrail_accref_seqno
    JOIN massal_customer mas ON trail.acctrail_led_code = mas.cust_code
    JOIN acc_group_master repr ON cust_acc_group = repr.grp_code
    WHERE ref_compcode = 1
      AND ref_invdate <= @tod
      AND ref_docdate > @tod
      AND ref_adjvoutype IN ('GSI', 'SDN', 'CNG', 'GJV', 'OPB')
      ", @cond_rep, @cond_led, "
  ) a1 ", @cond_overdue, "
  GROUP BY repr_name, repr_code, led_name, cust_add1, cust_add2, cust_add3, cust_city, cust_state, cust_zip,
           acctrail_led_code, acctrail_inv_no, acctrail_inv_date, acctrail_crdays, duedate, oddays, acctrail_amtmode, accref_seqno
) aa 
ORDER BY accref_seqno ) ab");

PREPARE stmt FROM @sql;
EXECUTE stmt;
DEALLOCATE PREPARE stmt;
select * from tmp_AR_Agewise;   
    
END ;;
DELIMITER ;
