CREATE DEFINER=`root`@`%` PROCEDURE `spacc_rep_receivables_outstanding_Bills_Agewise_Report`()
BEGIN
  select  * from tmp_AR_Agewise order by led_name,acctrail_inv_date,acctrail_inv_no;
END ;;
