CREATE DEFINER=`root`@`%` PROCEDURE `spacc_rep_receivables_Overdue_and_Collection`(compcode int, fromdate date,todate date,repcode int )
BEGIN
		   select * from (
			 select repr_name,  repr_code, led_name, cust_add1, cust_add2, cust_add3, cust_city, cust_state, cust_zip, acctrail_led_code, acctrail_inv_no, acctrail_inv_date, max(acctrail_inv_value) acctrail_inv_value, max(acctrail_adj_value) acctrail_adj_value, sum(adjamt) adjamt, acctrail_crdays, duedate, oddays, acctrail_amtmode, accref_seqno from
			 (
				select grp_name repr_name, grp_code repr_code,cust_ref led_name,cust_add1, cust_add2, cust_add3, cust_city, cust_state,cust_zip,acctrail_led_code, acctrail_inv_no,  acctrail_inv_date, acctrail_inv_value, acctrail_adj_value, 0 adjamt ,
				acctrail_gracedays+acctrail_crdays acctrail_crdays ,  DATE_FORMAT(DATE_ADD(acctrail_inv_date, INTERVAL acctrail_gracedays+acctrail_crdays DAY) ,'%d-%m-%Y') as  duedate,
				 DATEDIFF(todate, DATE_ADD(acctrail_inv_date, INTERVAL acctrail_gracedays+acctrail_crdays  DAY))  as oddays,acctrail_amtmode,accref_seqno
				 from acc_ref ref  left join acc_trail trail 
				 on ref.accref_seqno = trail.acctrail_accref_seqno join massal_customer mas 
				 on trail.acctrail_led_code = mas.cust_code and acctrail_inv_value > acctrail_adj_value -- and  mas.cust_type = 'C'					  
				 join acc_group_master repr on cust_acc_group = repr.grp_code
				 where accref_comp_code = 1 and accref_voudate <= todate  and acctrail_amtmode = 'D'  and  accref_vou_type  in ( 'GSI', 'SDN', 'OPB')   
				 and grp_code =  repcode 
				 
				union all
				 
				select grp_name repr_name, grp_code repr_code,cust_ref led_name,cust_add1, cust_add2, cust_add3, cust_city, cust_state,cust_zip,acctrail_led_code, acctrail_inv_no,  acctrail_inv_date, acctrail_inv_value, acctrail_adj_value, ref_adjamount  adjamt, 
				acctrail_gracedays+acctrail_crdays acctrail_crdays ,  DATE_FORMAT(DATE_ADD(acctrail_inv_date, INTERVAL acctrail_gracedays+acctrail_crdays DAY) ,'%d-%m-%Y') as  duedate,
				 DATEDIFF( todate, DATE_ADD(acctrail_inv_date, INTERVAL acctrail_gracedays+acctrail_crdays  DAY))  as oddays,acctrail_amtmode,ref_adjseqno accref_seqno
				 from acc_adjustments ref  left join acc_trail trail 
				 on ref.ref_adjseqno = trail.acctrail_accref_seqno join massal_customer mas 
				 on trail.acctrail_led_code = mas.cust_code					  
				 join acc_group_master repr on cust_acc_group = repr.grp_code and acctrail_led_code =  ref_ledcode
				 where ref_compcode = 1 and ref_invdate <= todate and ref_docdate > todate   
				 and grp_code =  repcode                     
			 ) a1                     
			 group by repr_name , repr_code , led_name, cust_add1, cust_add2, cust_add3, cust_city, cust_state, cust_zip, acctrail_led_code, acctrail_inv_no, acctrail_inv_date, acctrail_crdays, duedate, oddays, acctrail_amtmode, accref_seqno 
			  ) aa   order by accref_seqno;
END ;;
DELIMITER ;
