CREATE DEFINER=`root`@`%` PROCEDURE `spacc_rep_receivables_Partywise_All_outstanding`(compcode tinyint, asondate date ,repcode int ,overdue varchar(1),dueopt varchar(4) )
BEGIN
if dueopt = 'PT' then
	if overdue = 'Y' then    
		if repcode = 1000 then
			select grp_name,grp_code,ledname,acctrail_led_code, sum(balamt) balanceamt,cust_smsno,cust_overdue_msg,min(oddays) minday, max(oddays) maxday ,cust_email  from (
			 select accref_seqno,accref_vouno,accref_voudate,accref_payref_no,accref_payref_date,
			 d.cust_name ledname ,acctrail_led_code,acctrail_inv_value,acctrail_adj_value, 
             case when acctrail_amtmode = 'D' then acctrail_inv_value- acctrail_adj_value else (acctrail_inv_value- acctrail_adj_value) * -1 end as balamt,
			 acctrail_amtmode,e.grp_code, e.grp_name,acctrail_crdays ,  DATE_FORMAT(DATE_ADD(acctrail_inv_date, INTERVAL acctrail_crdays DAY) ,'%d-%m-%Y') as  duedate,
			 DATEDIFF( asondate, DATE_ADD(acctrail_inv_date, INTERVAL acctrail_crdays DAY))  as oddays,cust_smsno,cust_overdue_msg,cust_email 

			from acc_ref a, acc_trail c , massal_customer d, acc_group_master e where 
			accref_seqno = acctrail_accref_seqno 
			and c.acctrail_led_code = d.cust_code  and d.cust_acc_group = e.grp_code and e.grp_parent_code = 24
			and acctrail_inv_value > acctrail_adj_value and acctrail_adj_value >= 0
			and accref_comp_code = compcode 
			and accref_voudate<= asondate  and acctrail_amtmode = 'D' -- and accref_vou_type in ( 'GSI' ,'DNG','DNN')
			order by  d.cust_name ) aa   where  oddays > 0 group by grp_name,grp_code,ledname,acctrail_led_code,cust_smsno,cust_overdue_msg,cust_email   order  by grp_name,ledname ;
		elseif repcode = 2000 then
			select ledname,acctrail_led_code, sum(balamt) balanceamt,cust_smsno,cust_overdue_msg,min(oddays) minday, max(oddays) maxday ,cust_email  from (
			 select accref_seqno,accref_vouno,accref_voudate,accref_payref_no,accref_payref_date,
			 d.cust_name ledname ,acctrail_led_code,acctrail_inv_value,acctrail_adj_value, 
             case when acctrail_amtmode = 'D' then acctrail_inv_value- acctrail_adj_value else (acctrail_inv_value- acctrail_adj_value) * -1 end as balamt,
			 acctrail_amtmode,e.grp_code, e.grp_name,acctrail_crdays ,  DATE_FORMAT(DATE_ADD(acctrail_inv_date, INTERVAL acctrail_crdays DAY) ,'%d-%m-%Y') as  duedate,
			 DATEDIFF( asondate, DATE_ADD(acctrail_inv_date, INTERVAL acctrail_crdays DAY))  as oddays,cust_smsno,cust_overdue_msg,cust_email  

			from acc_ref a, acc_trail c , massal_customer d, acc_group_master e where 
			accref_seqno = acctrail_accref_seqno 
			and c.acctrail_led_code = d.cust_code  and d.cust_acc_group = e.grp_code and e.grp_parent_code = 24
			and acctrail_inv_value > acctrail_adj_value and acctrail_adj_value >= 0
			and accref_comp_code = compcode 
			and accref_voudate <= asondate   and acctrail_amtmode = 'D' -- and accref_vou_type in ( 'GSI' ,'DNG','DNN')
			order by  d.cust_name ) aa   where  oddays > 0 group by ledname,acctrail_led_code,cust_smsno,cust_overdue_msg,cust_email   order  by ledname ;
		else

select grp_name,grp_code,ledname,acctrail_led_code, sum(balamt) balanceamt,cust_smsno,cust_overdue_msg ,min(oddays) minday, max(oddays) maxday ,cust_email from (
select grp_name,grp_code,ledname,acctrail_led_code, accref_vouno,
case when acctrail_amtmode = 'D' then acctrail_inv_value- acctrail_adj_value + adjamt else   (acctrail_inv_value- acctrail_adj_value+adjamt) * -1 end as balamt,
cust_smsno,cust_overdue_msg ,oddays ,cust_email from (
select accref_seqno, accref_vouno, accref_voudate, accref_payref_no, accref_payref_date, ledname, acctrail_led_code, max(acctrail_inv_value) acctrail_inv_value, max(acctrail_adj_value) acctrail_adj_value  , sum(adjamt) adjamt, acctrail_amtmode, grp_code, grp_name, acctrail_crdays, duedate, oddays, cust_smsno, cust_overdue_msg, cust_email
from (
			 select accref_seqno,accref_vouno,accref_voudate,accref_payref_no,accref_payref_date,
			 d.cust_name ledname ,acctrail_led_code,acctrail_inv_value,acctrail_adj_value,  0 adjamt,            
			 acctrail_amtmode,e.grp_code, e.grp_name,acctrail_crdays ,  DATE_FORMAT(DATE_ADD(acctrail_inv_date, INTERVAL acctrail_crdays+ acctrail_gracedays  DAY) ,'%d-%m-%Y') as  duedate,
			 DATEDIFF( asondate, DATE_ADD(acctrail_inv_date, INTERVAL acctrail_crdays DAY))  as oddays,cust_smsno,cust_overdue_msg ,cust_email 
			from acc_ref a, acc_trail c , massal_customer d, acc_group_master e where 
			accref_seqno = acctrail_accref_seqno 
			and c.acctrail_led_code = d.cust_code and  d.cust_acc_group = e.grp_code and e.grp_parent_code = 24
			and acctrail_inv_value > acctrail_adj_value and acctrail_adj_value >= 0
			and accref_comp_code = compcode   
			and accref_voudate<= asondate  and grp_code = repcode  
			
            union all
            
            select ref_adjseqno accref_seqno,ref_adjvouno accref_vouno,ref_invdate accref_voudate,ref_invno accref_payref_no,ref_invdate accref_payref_date,
			 d.cust_name ledname ,acctrail_led_code, acctrail_inv_value,  acctrail_adj_value, ref_adjamount  adjamt,              
			 acctrail_amtmode,e.grp_code, e.grp_name,acctrail_crdays ,  DATE_FORMAT(DATE_ADD(acctrail_inv_date, INTERVAL acctrail_crdays+ acctrail_gracedays  DAY) ,'%d-%m-%Y') as  duedate,
			 DATEDIFF( asondate, DATE_ADD(acctrail_inv_date, INTERVAL acctrail_crdays DAY))  as oddays,cust_smsno,cust_overdue_msg, cust_email
			from acc_adjustments a, acc_trail c , massal_customer d, acc_group_master e where 
			ref_adjseqno = acctrail_accref_seqno 
			and c.acctrail_led_code = d.cust_code  and d.cust_acc_group = e.grp_code and e.grp_parent_code = 24
			and ref_compcode = compcode  and grp_code = repcode
			and ref_invdate <= asondate and ref_docdate >  asondate  and ref_adjvoutype = 'GSI'  and acctrail_amtmode = 'D'  -- and grp_code = 109          
            ) aa   
group by accref_seqno, accref_vouno, accref_voudate, accref_payref_no, accref_payref_date, ledname, acctrail_led_code,  acctrail_amtmode, grp_code, grp_name, acctrail_crdays, duedate, oddays, cust_smsno, cust_overdue_msg, cust_email            
order by ledname
) a1 
)a2 where  oddays > 0   group by             
grp_name,grp_code,ledname,acctrail_led_code, cust_smsno,cust_overdue_msg ,cust_email order by ledname;
            
			end if;    
	else 
	-- ALL OUTSTANDING
		if repcode = 1000 then
			select grp_name,grp_code,ledname,acctrail_led_code, sum(balamt) balanceamt,cust_smsno,cust_overdue_msg ,min(oddays) minday, max(oddays) maxday ,cust_email from (
			 select accref_seqno,accref_vouno,accref_voudate,accref_payref_no,accref_payref_date,
			 d.cust_name ledname ,acctrail_led_code,acctrail_inv_value,acctrail_adj_value, 
             case when acctrail_amtmode = 'D' then acctrail_inv_value- acctrail_adj_value else (acctrail_inv_value- acctrail_adj_value) * -1 end as balamt,
			 acctrail_amtmode,e.grp_code, e.grp_name,acctrail_crdays ,  DATE_FORMAT(DATE_ADD(acctrail_inv_date, INTERVAL acctrail_crdays DAY) ,'%d-%m-%Y') as  duedate,
			 DATEDIFF( asondate, DATE_ADD(acctrail_inv_date, INTERVAL acctrail_crdays DAY))  as oddays,cust_smsno,cust_overdue_msg ,cust_email 

			from acc_ref a, acc_trail c , massal_customer d, acc_group_master e where 
			accref_seqno = acctrail_accref_seqno 
			and c.acctrail_led_code = d.cust_code  and d.cust_acc_group = e.grp_code and e.grp_parent_code = 24
			and acctrail_inv_value > acctrail_adj_value and acctrail_adj_value >= 0
			and accref_comp_code = compcode 
			and accref_voudate<= asondate  --  and acctrail_amtmode = 'D' and accref_vou_type in ( 'GSI' ,'DNG','DNN')
			order by  d.cust_name ) aa   where balamt != 0   group by grp_name,grp_code,ledname,acctrail_led_code,cust_smsno,cust_overdue_msg,cust_email   order  by grp_name,ledname ;
		elseif repcode = 2000 then
			select ledname,acctrail_led_code, sum(balamt) balanceamt,cust_smsno,cust_overdue_msg,min(oddays) minday, max(oddays) maxday ,cust_email   from (
			 select accref_seqno,accref_vouno,accref_voudate,accref_payref_no,accref_payref_date,
			 d.cust_name ledname ,acctrail_led_code,acctrail_inv_value,acctrail_adj_value, 
             case when acctrail_amtmode = 'D' then acctrail_inv_value- acctrail_adj_value else (acctrail_inv_value- acctrail_adj_value) * -1 end as balamt,
			 acctrail_amtmode,e.grp_code, e.grp_name,acctrail_crdays ,  DATE_FORMAT(DATE_ADD(acctrail_inv_date, INTERVAL acctrail_crdays DAY) ,'%d-%m-%Y') as  duedate,
			 DATEDIFF( asondate, DATE_ADD(acctrail_inv_date, INTERVAL acctrail_crdays DAY))  as oddays,cust_smsno,cust_overdue_msg ,cust_email 

			from acc_ref a, acc_trail c , massal_customer d, acc_group_master e where 
			accref_seqno = acctrail_accref_seqno 
			and c.acctrail_led_code = d.cust_code  and d.cust_acc_group = e.grp_code and e.grp_parent_code = 24
			and acctrail_inv_value > acctrail_adj_value and acctrail_adj_value >= 0
			and accref_comp_code = compcode 
			and accref_voudate<= asondate   --  and acctrail_amtmode = 'D' and accref_vou_type in ( 'GSI' ,'DNG','DNN')
			order by  d.cust_name ) aa   where balamt != 0   group by ledname,acctrail_led_code,cust_smsno,cust_overdue_msg,cust_email   order  by ledname ;
		else
        
     select grp_name,grp_code,ledname,acctrail_led_code, sum(balamt) balanceamt,cust_smsno,cust_overdue_msg ,min(oddays) minday, max(oddays) maxday ,cust_email from (
select grp_name,grp_code,ledname,acctrail_led_code, accref_vouno,
case when acctrail_amtmode = 'D' then acctrail_inv_value- acctrail_adj_value + adjamt else   (acctrail_inv_value- acctrail_adj_value+adjamt) * -1 end as balamt,
cust_smsno,cust_overdue_msg ,oddays ,cust_email from (
select accref_seqno, accref_vouno, accref_voudate, accref_payref_no, accref_payref_date, ledname, acctrail_led_code, max(acctrail_inv_value) acctrail_inv_value, max(acctrail_adj_value) acctrail_adj_value  , sum(adjamt) adjamt, acctrail_amtmode, grp_code, grp_name, acctrail_crdays, duedate, oddays, cust_smsno, cust_overdue_msg, cust_email
from (
			 select accref_seqno,accref_vouno,accref_voudate,accref_payref_no,accref_payref_date,
			 d.cust_name ledname ,acctrail_led_code,acctrail_inv_value,acctrail_adj_value,  0 adjamt,            
			 acctrail_amtmode,e.grp_code, e.grp_name,acctrail_crdays ,  DATE_FORMAT(DATE_ADD(acctrail_inv_date, INTERVAL acctrail_crdays+ acctrail_gracedays  DAY) ,'%d-%m-%Y') as  duedate,
			 DATEDIFF( asondate, DATE_ADD(acctrail_inv_date, INTERVAL acctrail_crdays+ acctrail_gracedays  DAY))  as oddays,cust_smsno,cust_overdue_msg ,cust_email 
			from acc_ref a, acc_trail c , massal_customer d, acc_group_master e where 
			accref_seqno = acctrail_accref_seqno 
			and c.acctrail_led_code = d.cust_code and  d.cust_acc_group = e.grp_code and e.grp_parent_code = 24
			and acctrail_inv_value > acctrail_adj_value and acctrail_adj_value >= 0
			and accref_comp_code = compcode  
			and accref_voudate<= asondate  and grp_code = repcode 
			
            union all
            
            select ref_adjseqno accref_seqno,ref_adjvouno accref_vouno,ref_invdate accref_voudate,ref_invno accref_payref_no,ref_invdate accref_payref_date,
			 d.cust_name ledname ,acctrail_led_code, acctrail_inv_value,  acctrail_adj_value, ref_adjamount  adjamt,              
			 acctrail_amtmode,e.grp_code, e.grp_name,acctrail_crdays ,  DATE_FORMAT(DATE_ADD(acctrail_inv_date, INTERVAL acctrail_crdays+ acctrail_gracedays  DAY) ,'%d-%m-%Y') as  duedate,
			 DATEDIFF( asondate, DATE_ADD(acctrail_inv_date, INTERVAL acctrail_crdays+ acctrail_gracedays  DAY))  as oddays,cust_smsno,cust_overdue_msg, cust_email
			from acc_adjustments a, acc_trail c , massal_customer d, acc_group_master e where 
