			and accref_voudate<= asondate  and grp_code = repcode  and acctrail_amtmode = 'D' 
			
            union all
            
            select ref_adjseqno accref_seqno,ref_adjvouno accref_vouno,ref_invdate accref_voudate,ref_invno accref_payref_no,ref_invdate accref_payref_date,
			 d.cust_name ledname ,acctrail_led_code, acctrail_inv_value,  acctrail_adj_value, ref_adjamount  adjamt,              
			 acctrail_amtmode,e.grp_code, e.grp_name,acctrail_crdays ,  DATE_FORMAT(DATE_ADD(acctrail_inv_date, INTERVAL acctrail_crdays+ acctrail_gracedays  DAY) ,'%d-%m-%Y') as  duedate,
			 DATEDIFF( asondate, DATE_ADD(acctrail_inv_date, INTERVAL acctrail_crdays+ acctrail_gracedays  DAY))  as oddays,cust_smsno,cust_overdue_msg, cust_email
			from acc_adjustments a, acc_trail c , massal_customer d, acc_group_master e where 
			ref_adjseqno = acctrail_accref_seqno 
			and c.acctrail_led_code = d.cust_code  and d.cust_acc_group = e.grp_code and e.grp_parent_code = 24
			and ref_compcode = compcode  and grp_code = repcode
			and ref_invdate <= asondate and ref_docdate >  asondate  and ref_adjvoutype = 'GSI'  and acctrail_amtmode = 'D'  -- and grp_code = 109          
