group by accref_seqno, accref_vouno, accref_voudate, accref_payref_no, accref_payref_date, ledname, acctrail_led_code,  acctrail_amtmode, grp_code, grp_name, acctrail_crdays, duedate, oddays, cust_smsno, cust_overdue_msg, cust_email            
order by ledname
) a1 
)a2 where balamt != 0     group by             
grp_name,grp_code,ledname,acctrail_led_code, cust_smsno,cust_overdue_msg ,cust_email order by ledname;
      
			end if;    
	end if;
end if;

        
    END ;;
