		else
		select grp_name,grp_code,ledname,acctrail_led_code, sum(balamt) balanceamt,cust_smsno,cust_overdue_msg ,min(oddays) minday, max(oddays) maxday ,cust_email from (
			 select accref_seqno,accref_vouno,accref_voudate,accref_payref_no,accref_payref_date,
			 d.cust_name ledname ,acctrail_led_code,acctrail_inv_value,acctrail_adj_value, 
             case when acctrail_amtmode = 'D' then acctrail_inv_value- acctrail_adj_value else (acctrail_inv_value- acctrail_adj_value) * -1 end as balamt,
			 acctrail_amtmode,e.grp_code, e.grp_name,acctrail_crdays ,  DATE_FORMAT(DATE_ADD(acctrail_inv_date, INTERVAL acctrail_crdays+ acctrail_gracedays  DAY) ,'%d-%m-%Y') as  duedate,
			 DATEDIFF( asondate, DATE_ADD(acctrail_inv_date, INTERVAL acctrail_crdays+ acctrail_gracedays  DAY))  as oddays,cust_smsno,cust_overdue_msg ,cust_email 
			from acc_ref a, acc_trail c , massal_customer d, acc_group_master e where 
			accref_seqno = acctrail_accref_seqno 
			and c.acctrail_led_code = d.cust_code and  d.cust_acc_group = e.grp_code and e.grp_parent_code = 24
			and acctrail_inv_value > acctrail_adj_value and acctrail_adj_value >= 0
			and accref_comp_code = compcode 
			and accref_voudate<= asondate  and grp_code = repcode -- and acctrail_amtmode = 'D' 
			order by  d.cust_name ) aa   where balamt > 0   group by grp_name,grp_code,ledname,acctrail_led_code,cust_smsno,cust_overdue_msg,cust_email   order  by grp_name,ledname;
			end if;    
	end if;
end if;

        
    END ;;
DELIMITER ;
