CREATE DEFINER=`root`@`%` PROCEDURE `spacc_rep_receivables_Party_overdue_outstanding`(compcode int, fromdate date,todate date,ledcode int,repcode int,dueopt varchar(4))
BEGIN
if dueopt = 'PT' then
	if (repcode = 0) then
	   if ledcode = 0 then
		   select * from (
				select repr_name,repr_code,cust_ref  led_name,acctrail_led_code, acctrail_inv_no,  acctrail_inv_date, acctrail_inv_value, acctrail_adj_value, 
				 acctrail_crdays , acctrail_gracedays,   DATE_FORMAT(DATE_ADD(acctrail_inv_date, INTERVAL acctrail_crdays DAY) ,'%d-%m-%Y') as  duedate,
				 DATEDIFF( todate, DATE_ADD(acctrail_inv_date, INTERVAL acctrail_crdays DAY))  as oddays,acctrail_amtmode,accref_seqno,accref_vouno
				 from acc_ref ref  left join acc_trail trail 
				 on ref.accref_seqno = trail.acctrail_accref_seqno and acctrail_inv_value > acctrail_adj_value 
				 join massal_customer cust on cust.cust_code = trail.acctrail_led_code  
				 join massal_repr repr on cust.cust_repr = repr.repr_code  
				 where accref_comp_code = 1 and accref_voudate <=  todate and acctrail_amtmode = 'D' -- and (accref_vou_type = 'GSI'  or left(accref_vou_type,2) = 'DN') 
			  ) aa where oddays > 0  order by accref_seqno;
		 else
		   select * from (
				select repr_name,repr_code,cust_ref  led_name,acctrail_led_code, acctrail_inv_no,  acctrail_inv_date, acctrail_inv_value, acctrail_adj_value, 
				 acctrail_crdays , acctrail_gracedays,   DATE_FORMAT(DATE_ADD(acctrail_inv_date, INTERVAL acctrail_crdays DAY) ,'%d-%m-%Y') as  duedate,
				 DATEDIFF( todate, DATE_ADD(acctrail_inv_date, INTERVAL acctrail_crdays DAY)) as oddays,acctrail_amtmode,accref_seqno,accref_vouno
				 from acc_ref ref  left join acc_trail trail 
                 on ref.accref_seqno = trail.acctrail_accref_seqno and acctrail_inv_value > acctrail_adj_value 
				 join massal_customer cust on cust.cust_code = trail.acctrail_led_code  
				 join massal_repr repr on cust.cust_repr = repr.repr_code  
				 where accref_comp_code = 1 and accref_voudate <= todate  and acctrail_amtmode = 'D' -- and  (accref_vou_type = 'GSI'  or left(accref_vou_type,2) = 'DN')
				 and acctrail_led_code = ledcode 
			  ) aa where oddays > 0  order by accref_seqno;  
		  end if;   
	else
	   if ledcode = 0 then
		   select * from (
				select repr_name,repr_code,cust_ref  led_name,acctrail_led_code, acctrail_inv_no,  acctrail_inv_date, acctrail_inv_value, acctrail_adj_value, 
				 acctrail_crdays , acctrail_gracedays,   DATE_FORMAT(DATE_ADD(acctrail_inv_date, INTERVAL acctrail_crdays DAY) ,'%d-%m-%Y') as  duedate,
				 DATEDIFF( todate, DATE_ADD(acctrail_inv_date, INTERVAL acctrail_crdays DAY))  as oddays,acctrail_amtmode,accref_seqno,accref_vouno
				 from acc_ref ref  left join acc_trail trail 
                 on ref.accref_seqno = trail.acctrail_accref_seqno and acctrail_inv_value > acctrail_adj_value 
				 join massal_customer cust on cust.cust_code = trail.acctrail_led_code  
				 join massal_repr repr on cust.cust_repr = repr.repr_code  
				 where accref_comp_code = 1 and accref_voudate <= todate and acctrail_amtmode = 'D' -- and (accref_vou_type = 'GSI'  or left(accref_vou_type,2) = 'DN')   
				 and repr_code =  repcode
			  ) aa where oddays > 0  order by accref_seqno;
		 else
		   select * from (
				select repr_name,repr_code,cust_ref  led_name,acctrail_led_code, acctrail_inv_no,  acctrail_inv_date, acctrail_inv_value, acctrail_adj_value, 
				 acctrail_crdays , acctrail_gracedays,   DATE_FORMAT(DATE_ADD(acctrail_inv_date, INTERVAL acctrail_crdays DAY) ,'%d-%m-%Y') as  duedate,
				 DATEDIFF( todate, DATE_ADD(acctrail_inv_date, INTERVAL acctrail_crdays DAY))  as oddays,acctrail_amtmode,accref_seqno,accref_vouno
				 from acc_ref ref  left join acc_trail trail 
                 on ref.accref_seqno = trail.acctrail_accref_seqno and acctrail_inv_value > acctrail_adj_value 
				 join massal_customer cust on cust.cust_code = trail.acctrail_led_code  
				 join massal_repr repr on cust.cust_repr = repr.repr_code  
				 where accref_comp_code = 1 and accref_voudate <= todate and acctrail_amtmode = 'D' -- and (accref_vou_type = 'GSI'  or left(accref_vou_type,2) = 'DN') 
				 and acctrail_led_code = ledcode and repr_code =  repcode
			  ) aa where oddays > 0  order by accref_seqno;  
		  end if;   
	end if;
else
	if (repcode = 0) then
	   if ledcode = 0 then
		   select * from (
				select repr_name,repr_code,cust_ref  led_name,acctrail_led_code, acctrail_inv_no,  acctrail_inv_date, acctrail_inv_value, acctrail_adj_value, 
				 acctrail_crdays , acctrail_gracedays,   DATE_FORMAT(DATE_ADD(acctrail_inv_date, INTERVAL acctrail_crdays+acctrail_gracedays DAY) ,'%d-%m-%Y') as  duedate,
				 DATEDIFF( todate, DATE_ADD(acctrail_inv_date, INTERVAL acctrail_crdays+acctrail_gracedays DAY))  as oddays,acctrail_amtmode,accref_seqno,accref_vouno
				 from acc_ref ref  left join acc_trail trail 
                 on ref.accref_seqno = trail.acctrail_accref_seqno and acctrail_inv_value > acctrail_adj_value 
				 join massal_customer cust on cust.cust_code = trail.acctrail_led_code  
				 join massal_repr repr on cust.cust_repr = repr.repr_code  
				 where accref_comp_code = 1 and accref_voudate <=  todate and acctrail_amtmode = 'D' -- and (accref_vou_type = 'GSI'  or left(accref_vou_type,2) = 'DN') 
			  ) aa where oddays > 0  order by accref_seqno;
		 else
		   select * from (
				select repr_name,repr_code,cust_ref  led_name,acctrail_led_code, acctrail_inv_no,  acctrail_inv_date, acctrail_inv_value, acctrail_adj_value, 
				 acctrail_crdays , acctrail_gracedays,   DATE_FORMAT(DATE_ADD(acctrail_inv_date, INTERVAL acctrail_crdays+acctrail_gracedays DAY) ,'%d-%m-%Y') as  duedate,
				 DATEDIFF( todate, DATE_ADD(acctrail_inv_date, INTERVAL acctrail_crdays+acctrail_gracedays DAY)) as oddays,acctrail_amtmode,accref_seqno,accref_vouno
				 from acc_ref ref  left join acc_trail trail 
                 on ref.accref_seqno = trail.acctrail_accref_seqno and acctrail_inv_value > acctrail_adj_value 
				 join massal_customer cust on cust.cust_code = trail.acctrail_led_code  
				 join massal_repr repr on cust.cust_repr = repr.repr_code  
				 where accref_comp_code = 1 and accref_voudate <= todate  and acctrail_amtmode = 'D' -- and  (accref_vou_type = 'GSI'  or left(accref_vou_type,2) = 'DN')
				 and acctrail_led_code = ledcode 
			  ) aa where oddays > 0  order by accref_seqno;  
		  end if;   
	else
	   if ledcode = 0 then
		   select * from (
				select repr_name,repr_code,cust_ref  led_name,acctrail_led_code, acctrail_inv_no,  acctrail_inv_date, acctrail_inv_value, acctrail_adj_value, 
				 acctrail_crdays , acctrail_gracedays,   DATE_FORMAT(DATE_ADD(acctrail_inv_date, INTERVAL acctrail_crdays+acctrail_gracedays DAY) ,'%d-%m-%Y') as  duedate,
				 DATEDIFF( todate, DATE_ADD(acctrail_inv_date, INTERVAL acctrail_crdays+acctrail_gracedays DAY))  as oddays,acctrail_amtmode,accref_seqno,accref_vouno
				 from acc_ref ref  left join acc_trail trail 
                 on ref.accref_seqno = trail.acctrail_accref_seqno and acctrail_inv_value > acctrail_adj_value 
				 join massal_customer cust on cust.cust_code = trail.acctrail_led_code  
				 join massal_repr repr on cust.cust_repr = repr.repr_code  
				 where accref_comp_code = 1 and accref_voudate <= todate and acctrail_amtmode = 'D' -- and (accref_vou_type = 'GSI'  or left(accref_vou_type,2) = 'DN')   
				 and repr_code =  repcode
			  ) aa where oddays > 0  order by accref_seqno;
		 else
		   select * from (
				select repr_name,repr_code,cust_ref  led_name,acctrail_led_code, acctrail_inv_no,  acctrail_inv_date, acctrail_inv_value, acctrail_adj_value, 
				 acctrail_crdays , acctrail_gracedays,   DATE_FORMAT(DATE_ADD(acctrail_inv_date, INTERVAL acctrail_crdays+acctrail_gracedays DAY) ,'%d-%m-%Y') as  duedate,
				 DATEDIFF( todate, DATE_ADD(acctrail_inv_date, INTERVAL acctrail_crdays+acctrail_gracedays DAY))  as oddays,acctrail_amtmode,accref_seqno,accref_vouno
				 from acc_ref ref  left join acc_trail trail 
				 on ref.accref_seqno = trail.acctrail_accref_seqno join acc_ledger_master mas 
                 on ref.accref_seqno = trail.acctrail_accref_seqno and acctrail_inv_value > acctrail_adj_value 
				join massal_customer cust on cust.cust_code = trail.acctrail_led_code  
				 join massal_repr repr on cust.cust_repr = repr.repr_code  
				 where accref_comp_code = 1 and accref_voudate <= todate and acctrail_amtmode = 'D' -- and (accref_vou_type = 'GSI'  or left(accref_vou_type,2) = 'DN') 
				 and acctrail_led_code = ledcode and repr_code =  repcode
			  ) aa where oddays > 0  order by accref_seqno;  
		  end if;   
	end if;
end if;      
END ;;
