CREATE DEFINER=`root`@`%` PROCEDURE `spacc_rep_receivables_RepAbstract`(compcode tinyint, asondate date)
BEGIN
select repr_name,repr_code, sum(balamt) balanceamt from (
 select accref_seqno,accref_vouno,accref_voudate,accref_payref_no,accref_payref_date,
 d.cust_ref,acctrail_led_code,acctrail_inv_value,acctrail_adj_value, 
 acctrail_inv_value- acctrail_adj_value balamt,
 acctrail_amtmode,
 e.repr_name,acctrail_crdays
 ,  DATE_FORMAT(DATE_ADD(acctrail_inv_date, INTERVAL acctrail_crdays DAY) ,'%d-%m-%Y') as  duedate,
 DATEDIFF( asondate, DATE_ADD(acctrail_inv_date, INTERVAL acctrail_crdays DAY))  as oddays

from acc_ref a, acc_trail c , massal_customer d, massal_repr e where 
accref_seqno = acctrail_accref_seqno 
and c.acctrail_led_code = d.cust_code and d.cust_repr = e.repr_code
and acctrail_inv_value > acctrail_adj_value and acctrail_adj_value >= 0
and accref_comp_code = compcode 
and accref_voudate<= asondate  and accref_vou_type = 'GSI' 
order by e.repr_name, d.cust_ref ) aa   where balamt > 0  and oddays > 0 group by repr_name,repr_code ;
END ;;
DELIMITER ;
