CREATE DEFINER=`root`@`%` PROCEDURE `spacc_rep_receivables_Rep_overdue_Abstract`(compcode tinyint, asondate date,dueopt varchar(4))
BEGIN

if dueopt = 'PT' then
select grp_name,grp_code, sum(balanceamt) balanceamt from (
	select grp_name,grp_code, sum(balamt) balanceamt from (
    select accref_seqno,accref_vouno,accref_voudate,accref_payref_no,accref_payref_date,
	 d.cust_ref,acctrail_led_code,acctrail_inv_value,acctrail_adj_value, 
     case when acctrail_amtmode = 'D' then acctrail_inv_value- acctrail_adj_value else (acctrail_inv_value- acctrail_adj_value) * -1 end as balamt,
	 acctrail_amtmode,e.grp_code,  e.grp_name,acctrail_crdays ,acctrail_gracedays,  DATE_FORMAT(DATE_ADD(acctrail_inv_date, INTERVAL acctrail_crdays DAY) ,'%d-%m-%Y') as  duedate,
	 DATEDIFF( asondate, DATE_ADD(acctrail_inv_date, INTERVAL acctrail_crdays DAY))  as oddays
	from acc_ref a, acc_trail c , massal_customer d, acc_group_master e where 
	accref_seqno = acctrail_accref_seqno   and grp_parent_code != 98 
	and c.acctrail_led_code = d.cust_code and d.cust_acc_group = e.grp_code and e.grp_parent_code = 24
	and acctrail_inv_value > acctrail_adj_value and acctrail_adj_value >= 0
	and accref_comp_code = compcode  and accref_vou_type  in ('GSI','OPB')
	and accref_voudate<= asondate  and acctrail_amtmode = 'D'  -- and cust_type = 'C'
	order by e.grp_name, d.cust_ref ) aa   where balamt > 0  and oddays > 0 group by grp_name,grp_code
  
    union all
    
    select grp_name , grp_code , sum(ref_adjamount) as balanceamt from acc_adjustments c , massal_customer d, acc_group_master e where 
    c.ref_ledcode = d.cust_code and d.cust_acc_group = e.grp_code and e.grp_parent_code = 24 and
    ref_invdate <= asondate and ref_docdate >  asondate  and ref_adjvoutype = 'GSI' 
    group by  grp_name , grp_code    
     ) a1 group by  grp_name , grp_code order by  grp_name;   
else
select grp_name,grp_code, sum(balanceamt) balanceamt from (
	select grp_name,grp_code, sum(balamt) balanceamt from (
	 select accref_seqno,accref_vouno,accref_voudate,accref_payref_no,accref_payref_date,
	 d.cust_ref,acctrail_led_code,acctrail_inv_value,acctrail_adj_value, 
     case when acctrail_amtmode = 'D' then acctrail_inv_value- acctrail_adj_value else (acctrail_inv_value- acctrail_adj_value) * -1 end as balamt,
	 acctrail_amtmode,e.grp_code,  e.grp_name,acctrail_crdays , acctrail_gracedays,  DATE_FORMAT(DATE_ADD(acctrail_inv_date, INTERVAL acctrail_crdays+ acctrail_gracedays DAY) ,'%d-%m-%Y') as  duedate,
	 DATEDIFF( asondate, DATE_ADD(acctrail_inv_date, INTERVAL acctrail_crdays+ acctrail_gracedays DAY))  as oddays

	from acc_ref a, acc_trail c , massal_customer d, acc_group_master e where 
	accref_seqno = acctrail_accref_seqno  and grp_parent_code != 98 
	and c.acctrail_led_code = d.cust_code and d.cust_acc_group = e.grp_code and e.grp_parent_code = 24
	and acctrail_inv_value > acctrail_adj_value and acctrail_adj_value >= 0
	and accref_comp_code = compcode  and accref_vou_type  in ('GSI','OPB')
	and accref_voudate<= asondate  and acctrail_amtmode = 'D' -- and cust_type = 'C'
	order by e.grp_name, d.cust_ref ) aa   where balamt > 0  and oddays > 0 group by grp_name,grp_code 
    
    union all
    select grp_name , grp_code , sum(ref_adjamount) as balanceamt from acc_adjustments c , massal_customer d, acc_group_master e where 
    c.ref_ledcode = d.cust_code and d.cust_acc_group = e.grp_code and e.grp_parent_code = 24 and
    ref_invdate <= asondate and ref_docdate >  asondate  and ref_adjvoutype = 'GSI' 
    group by  grp_name , grp_code    
    ) a1 group by  grp_name , grp_code order by  grp_name;
end if;
