CREATE DEFINER=`root`@`%` PROCEDURE `spacc_rep_rep_party_overdue_days_abstract`(compcode int, todate date,repcode int ,repdays int)
BEGIN
if repcode  = 0 then
select repr_name,repr_code,sum(acctrail_inv_value-acctrail_adj_value) as balamt from (

		select repr_name,repr_code,cust_name  led_name,acctrail_led_code, acctrail_inv_no,  acctrail_inv_date, acctrail_inv_value, acctrail_adj_value, 
		 acctrail_crdays ,  DATE_FORMAT(DATE_ADD(acctrail_inv_date, INTERVAL acctrail_crdays DAY) ,'%d-%m-%Y') as  duedate,
		 DATEDIFF( todate, acctrail_inv_date)  as agedays,acctrail_amtmode,accref_seqno
		 from acc_ref ref  left join acc_trail trail 
		 on ref.accref_seqno = trail.acctrail_accref_seqno join acc_ledger_master mas 
		 on trail.acctrail_led_code = mas.led_code  and acctrail_inv_value > acctrail_adj_value and  mas.led_type = 'C'
		 join massal_customer cust on cust.cust_code = trail.acctrail_led_code  
		 join massal_repr repr on cust.cust_repr = repr.repr_code  
		 where accref_comp_code = compcode and accref_voudate <=  todate and acctrail_amtmode = 'D' 
		 and acctrail_inv_value > acctrail_adj_value
         
         ) aa where agedays > repdays  group by repr_name,repr_code order by repr_name ;         
else
select repr_name,led_name ,acctrail_led_code led_code ,sum(acctrail_inv_value-acctrail_adj_value) as balamt, max(agedays) agedays    from (

		select repr_name,repr_code,cust_name  led_name,acctrail_led_code, acctrail_inv_no,  acctrail_inv_date, acctrail_inv_value, acctrail_adj_value, 
		 acctrail_crdays ,  DATE_FORMAT(DATE_ADD(acctrail_inv_date, INTERVAL acctrail_crdays DAY) ,'%d-%m-%Y') as  duedate,
		 DATEDIFF( todate, acctrail_inv_date)  as agedays,acctrail_amtmode,accref_seqno
		 from acc_ref ref  left join acc_trail trail 
		 on ref.accref_seqno = trail.acctrail_accref_seqno join acc_ledger_master mas 
		 on trail.acctrail_led_code = mas.led_code  and acctrail_inv_value > acctrail_adj_value and  mas.led_type = 'C'
		 join massal_customer cust on cust.cust_code = trail.acctrail_led_code  
		 join massal_repr repr on cust.cust_repr = repr.repr_code  
		 where accref_comp_code = compcode and accref_voudate <=  todate and acctrail_amtmode = 'D' 
		 and repr_code = repcode and acctrail_inv_value > acctrail_adj_value
         ) aa where agedays > repdays  group by repr_name,led_name,acctrail_led_code order by led_name ;         
         
end if;
/*
if repcode  = 0 then
	   select repr_name,repr_code,sum(acctrail_inv_value-acctrail_adj_value) as balamt ,max(oddays) maxday from (
		select repr_name,repr_code,cust_ref  led_name,acctrail_led_code, acctrail_inv_no,  acctrail_inv_date, acctrail_inv_value, acctrail_adj_value, 
		 acctrail_crdays ,  DATE_FORMAT(DATE_ADD(acctrail_inv_date, INTERVAL acctrail_crdays DAY) ,'%d-%m-%Y') as  duedate,
		 DATEDIFF( todate, DATE_ADD(acctrail_inv_date, INTERVAL acctrail_crdays DAY))  as oddays,acctrail_amtmode,accref_seqno
		 from acc_ref ref  left join acc_trail trail 
		 on ref.accref_seqno = trail.acctrail_accref_seqno join acc_ledger_master mas 
		 on trail.acctrail_led_code = mas.led_code  and acctrail_inv_value > acctrail_adj_value and  mas.led_type = 'C'
		 join massal_customer cust on cust.cust_led_code = trail.acctrail_led_code  
		 join massal_repr repr on cust.cust_repr = repr.repr_code  
		 where accref_comp_code = compcode and accref_voudate <=  todate and acctrail_amtmode = 'D' -- and (accref_vou_type = 'GSI'  or left(accref_vou_type,2) = 'DN') 			  
		 and acctrail_inv_value > acctrail_adj_value ) aa where oddays > repdays  group by repr_name,repr_code order by repr_name ;        
else
select repr_name,led_name ,acctrail_led_code led_code ,sum(acctrail_inv_value-acctrail_adj_value) as balamt,min(oddays) minday  ,max(oddays) maxday   from (
		select repr_name,repr_code,cust_name  led_name,acctrail_led_code, acctrail_inv_no,  acctrail_inv_date, acctrail_inv_value, acctrail_adj_value, 
		 acctrail_crdays ,  DATE_FORMAT(DATE_ADD(acctrail_inv_date, INTERVAL acctrail_crdays DAY) ,'%d-%m-%Y') as  duedate,
		 DATEDIFF( todate, DATE_ADD(acctrail_inv_date, INTERVAL acctrail_crdays DAY))  as oddays,acctrail_amtmode,accref_seqno
		 from acc_ref ref  left join acc_trail trail 
		 on ref.accref_seqno = trail.acctrail_accref_seqno join acc_ledger_master mas 
		 on trail.acctrail_led_code = mas.led_code  and acctrail_inv_value > acctrail_adj_value and  mas.led_type = 'C'
		 join massal_customer cust on cust.cust_led_code = trail.acctrail_led_code  
		 join massal_repr repr on cust.cust_repr = repr.repr_code  
		 where accref_comp_code = compcode and accref_voudate <=  todate and acctrail_amtmode = 'D' -- and (accref_vou_type = 'GSI'  or left(accref_vou_type,2) = 'DN') 			  
		 and repr_code = repcode and acctrail_inv_value > acctrail_adj_value ) aa where oddays > repdays  group by repr_name,led_name,acctrail_led_code order by led_name ;         
end if;  
*/
       
END ;;
