CREATE DEFINER=`root`@`%` PROCEDURE `spacc_rep_sal_vouprint`(compcode int,fincode int,vouno varchar(12))
BEGIN
select * from  acc_direct_sales , massal_customer where cust_code = sal_partycode and
  sal_compcode = compcode and sal_finid = fincode  and sal_vouno = vouno;

END ;;
