			and accref_comp_code = 1
			and accref_voudate > asondate and accref_voudate <= collupto   and acctrail_amtmode = 'D'  and accref_vou_type  = 'GSI' and grp_code = repcode
        
            union all

            select ref_adjseqno accref_seqno,ref_invno accref_vouno,ref_invdate accref_voudate, ref_invno accref_payref_no,ref_invdate accref_payref_date,
			 d.cust_name ledname ,acctrail_led_code,acctrail_inv_value,acctrail_adj_value, 
             case when acctrail_amtmode = 'D' then acctrail_inv_value- acctrail_adj_value else (acctrail_inv_value- acctrail_adj_value) * -1 end as balamt, ref_adjamount  adjamt, 
			 acctrail_amtmode,e.grp_code, e.grp_name, acctrail_crdays+ acctrail_gracedays  acctrail_crdays ,  DATE_FORMAT(DATE_ADD(acctrail_inv_date, INTERVAL acctrail_crdays+ acctrail_gracedays  DAY) ,'%d-%m-%Y') as  duedate,
			 DATEDIFF(asondate, DATE_ADD(acctrail_inv_date, INTERVAL acctrail_crdays+ acctrail_gracedays  DAY))  as oddays,
             DATEDIFF(asondate, acctrail_inv_date)  as agedays
			from acc_adjustments a, acc_trail c , massal_customer d, acc_group_master e where 
            ref_compcode = compcode and ref_invdate <= asondate and ref_docdate > asondate and ref_adjvoutype = 'GSI' and
			ref_adjseqno = acctrail_accref_seqno 
			and c.acctrail_led_code = d.cust_code  and d.cust_acc_group = e.grp_code and e.grp_parent_code = 24						
			and acctrail_amtmode = 'D'  and grp_code = repcode
            
)a1 group by  accref_seqno, accref_payref_no, accref_payref_date, ledname, acctrail_led_code, 
grp_code, grp_name	             

)a2   -- where acctrail_led_code not in  (select l_custcode from massal_longpending_customers)  
group by  accref_seqno,  accref_payref_no, accref_payref_date, ledname, acctrail_led_code, grp_code, grp_name	 
) aa1
  left join       
        (
        select ref_ledcode,ref_docdate ,ref_invno,sum(ref_adjamount) preadjamt from acc_adjustments  , massal_customer d, acc_group_master e 
        where ref_ledcode = d.cust_code  and d.cust_acc_group = e.grp_code and e.grp_parent_code = 24   and grp_code = repcode and  
        ref_docdate between collfromdate  and colltodate and ref_adjvoutype = 'GSI' group by ref_ledcode,ref_docdate ,ref_invno
        ) bb1
        on aa1.acctrail_led_code = bb1.ref_ledcode and aa1.accref_payref_no =  bb1.ref_invno  order by  ledname
        ) aa3
union all
        select accref_seqno,accref_payref_no,accref_payref_date,
			 d.cust_name ledname ,acctrail_led_code,0 acctrail_inv_value, 0 acctrail_adj_value, 0 adjamt ,
             0  balamt,  0 currentbalance,
			 e.grp_code, e.grp_name, acctrail_crdays+ acctrail_gracedays  acctrail_crdays ,  DATE_FORMAT(DATE_ADD(acctrail_inv_date, INTERVAL acctrail_crdays+ acctrail_gracedays  DAY) ,'%d-%m-%Y') as  duedate,
			 DATEDIFF(accref_voudate , DATE_ADD(acctrail_inv_date, INTERVAL acctrail_crdays+ acctrail_gracedays  DAY))  as oddays,
             DATEDIFF(accref_voudate, acctrail_inv_date)  as agedays,
             acctrail_led_code ref_ledcode, accref_voudate ref_docdate, accref_vouno ref_invno, acctrail_inv_value- acctrail_adj_value  preadjamt , 'ALL'  as due_type  
			from acc_ref a, acc_trail c , massal_customer d, acc_group_master e where 
			accref_seqno = acctrail_accref_seqno 
			and c.acctrail_led_code = d.cust_code  and d.cust_acc_group = e.grp_code and e.grp_parent_code = 24
			and accref_comp_code = compcode
			and acctrail_inv_value > acctrail_adj_value and acctrail_adj_value >= 0
			and accref_voudate between  collfromdate  and collupto and    acctrail_amtmode = 'C'  and accref_vou_type  = 'BKR' and grp_code = repcode order by  ledname;
                       
   

END ;;
