CREATE DEFINER=`root`@`%` PROCEDURE `spacc_rep_Target_Outstanding_Customer_Abstract`(compcode int,asondate date,collfromdate date,colltodate date,repcode int,rdays int)
BEGIN


select accref_seqno, accref_payref_no, accref_payref_date, ledname, acctrail_led_code, acctrail_inv_value, 
