CREATE DEFINER=`root`@`%` PROCEDURE `spacc_rep_Target_Outstanding_LessThan7days`(compcode int,asondate date,collfromdate date,colltodate date,repcode int,duetype varchar(1))
BEGIN

if duetype = 'L' then
	select accref_seqno, accref_payref_no, accref_payref_date, ledname, acctrail_led_code, acctrail_inv_value, 
	case when preadjamt  = null then acctrail_adj_value-preadjamt else acctrail_adj_value end as acctrail_adj_value,
	case when preadjamt  is null then balamt  else balamt end as balamt,currentbalance,
	grp_code, grp_name, acctrail_crdays, duedate, oddays, agedays, 
	case when preadjamt  is null then 0 else ref_ledcode end as ref_ledcode, 
	case when preadjamt  is null then '' else ref_docdate end as ref_docdate, 
	case when preadjamt  is null then 0 else ref_invno end as ref_invno ,
	case when preadjamt  is null then 0 else preadjamt end as preadjamt 
	from (

			select * from (  
				select * from (
				
	select accref_seqno, accref_payref_no, accref_payref_date, ledname, acctrail_led_code, acctrail_inv_value , acctrail_adj_value -  adjamt  acctrail_adj_value ,  adjamt ,
	 acctrail_inv_value - acctrail_adj_value + adjamt  balamt,
    acctrail_inv_value - acctrail_adj_value currentbalance,
	 grp_code, grp_name, max(acctrail_crdays) acctrail_crdays, max(duedate) duedate, max(oddays) oddays, max(agedays) agedays from
	(    
				
	select accref_seqno, accref_payref_no, accref_payref_date, ledname, acctrail_led_code, max(acctrail_inv_value) acctrail_inv_value, max(acctrail_adj_value) acctrail_adj_value, sum(adjamt) adjamt , grp_code, grp_name, max(acctrail_crdays) acctrail_crdays, max(duedate) duedate, max(oddays) oddays, max(agedays) agedays from
	(            
				
				select accref_seqno,accref_vouno,accref_voudate,accref_payref_no,accref_payref_date,
				 d.cust_name ledname ,acctrail_led_code,acctrail_inv_value,acctrail_adj_value, 
				 case when acctrail_amtmode = 'D' then acctrail_inv_value- acctrail_adj_value else (acctrail_inv_value- acctrail_adj_value) * -1 end as balamt, 0 adjamt ,
				 acctrail_amtmode,e.grp_code, e.grp_name, acctrail_crdays+ acctrail_gracedays  acctrail_crdays ,  DATE_FORMAT(DATE_ADD(acctrail_inv_date, INTERVAL acctrail_crdays+ acctrail_gracedays  DAY) ,'%d-%m-%Y') as  duedate,
				 DATEDIFF(asondate, DATE_ADD(acctrail_inv_date, INTERVAL acctrail_crdays+ acctrail_gracedays  DAY))  as oddays,
				 DATEDIFF( asondate, acctrail_inv_date)  as agedays
				from acc_ref a, acc_trail c , massal_customer d, acc_group_master e where 
				accref_seqno = acctrail_accref_seqno 
				and c.acctrail_led_code = d.cust_code  and d.cust_acc_group = e.grp_code and e.grp_parent_code = 24
				and accref_comp_code = 1 
				and acctrail_inv_value > acctrail_adj_value and acctrail_adj_value >= 0
				and accref_voudate<= asondate  and acctrail_amtmode = 'D'  and grp_code = repcode and accref_vou_type  ='GSI' 
			
				union all

				select ref_adjseqno accref_seqno,ref_invno accref_vouno,ref_invdate accref_voudate, ref_invno accref_payref_no,ref_invdate accref_payref_date,
				 d.cust_name ledname ,acctrail_led_code,acctrail_inv_value,acctrail_adj_value, 
				 case when acctrail_amtmode = 'D' then acctrail_inv_value- acctrail_adj_value else (acctrail_inv_value- acctrail_adj_value) * -1 end as balamt, ref_adjamount  adjamt, 
				 acctrail_amtmode,e.grp_code, e.grp_name, acctrail_crdays+ acctrail_gracedays  acctrail_crdays ,  DATE_FORMAT(DATE_ADD(acctrail_inv_date, INTERVAL acctrail_crdays+ acctrail_gracedays  DAY) ,'%d-%m-%Y') as  duedate,
				 DATEDIFF(asondate, DATE_ADD(acctrail_inv_date, INTERVAL acctrail_crdays+ acctrail_gracedays  DAY))  as oddays,
				 DATEDIFF(asondate, acctrail_inv_date)  as agedays
				from acc_adjustments a, acc_trail c , massal_customer d, acc_group_master e where 
				ref_compcode = 1 and ref_invdate <= asondate and ref_docdate > asondate and ref_adjvoutype = 'GSI' and
				ref_adjseqno = acctrail_accref_seqno 
				and c.acctrail_led_code = d.cust_code  and d.cust_acc_group = e.grp_code and e.grp_parent_code = 24						
				and acctrail_amtmode = 'D'  and grp_code =  repcode
				
	)a1 group by  accref_seqno, accref_payref_no, accref_payref_date, ledname, acctrail_led_code, 
	grp_code, grp_name	             

	)a2   where acctrail_led_code  in  (select l_custcode from massal_longpending_customers)  group by  accref_seqno,  accref_payref_no, accref_payref_date, ledname, acctrail_led_code, 
	grp_code, grp_name	                          
		   
		   
		   
				
				) aa   where  (oddays > 0  or acctrail_crdays <=7)
			)aa1 left join       
			(
			select ref_ledcode,ref_docdate ,ref_invno,sum(ref_adjamount) preadjamt from acc_adjustments  , massal_customer d, acc_group_master e 
			where 
				ref_ledcode = d.cust_code  and d.cust_acc_group = e.grp_code and e.grp_parent_code = 24   and grp_code = repcode and  
			ref_invdate <= asondate and (ref_docdate between collfromdate and colltodate) and ref_adjvoutype = 'GSI' group by ref_ledcode,ref_docdate ,ref_invno
			) bb1
			on acctrail_led_code = ref_ledcode and accref_payref_no =   ref_invno
	) cc1 order by ledname,accref_payref_date;

else
select * from (
select accref_seqno, accref_payref_no, accref_payref_date, ledname, acctrail_led_code, acctrail_inv_value, 
case when preadjamt  = null then acctrail_adj_value-preadjamt else acctrail_adj_value end as acctrail_adj_value,
case when preadjamt  is null then balamt  else balamt end as balamt,currentbalance,
 grp_code, grp_name, acctrail_crdays, duedate, oddays, agedays, 
case when preadjamt  is null then 0 else ref_ledcode end as ref_ledcode, 
case when preadjamt  is null then '' else ref_docdate end as ref_docdate, 
case when preadjamt  is null then 0 else ref_invno end as ref_invno ,
case when preadjamt  is null then 0 else preadjamt end as preadjamt 
from (

        select * from (  
			select * from (
            
select accref_seqno, accref_payref_no, accref_payref_date, ledname, acctrail_led_code, acctrail_inv_value , acctrail_adj_value -  adjamt  acctrail_adj_value ,  adjamt ,
acctrail_inv_value - acctrail_adj_value + adjamt  balamt,
acctrail_inv_value - acctrail_adj_value currentbalance,
 grp_code, grp_name, max(acctrail_crdays) acctrail_crdays, max(duedate) duedate, max(oddays) oddays, max(agedays) agedays from
(    
            
select accref_seqno, accref_payref_no, accref_payref_date, ledname, acctrail_led_code, max(acctrail_inv_value) acctrail_inv_value, max(acctrail_adj_value) acctrail_adj_value, sum(adjamt) adjamt , grp_code, grp_name, max(acctrail_crdays) acctrail_crdays, max(duedate) duedate, max(oddays) oddays, max(agedays) agedays from
(            
            
            select accref_seqno,accref_vouno,accref_voudate,accref_payref_no,accref_payref_date,
			 d.cust_name ledname ,acctrail_led_code,acctrail_inv_value,acctrail_adj_value, 
             case when acctrail_amtmode = 'D' then acctrail_inv_value- acctrail_adj_value else (acctrail_inv_value- acctrail_adj_value) * -1 end as balamt, 0 adjamt ,
			 acctrail_amtmode,e.grp_code, e.grp_name, acctrail_crdays+ acctrail_gracedays  acctrail_crdays ,  DATE_FORMAT(DATE_ADD(acctrail_inv_date, INTERVAL acctrail_crdays+ acctrail_gracedays  DAY) ,'%d-%m-%Y') as  duedate,
			 DATEDIFF(asondate, DATE_ADD(acctrail_inv_date, INTERVAL acctrail_crdays+ acctrail_gracedays  DAY))  as oddays,
             DATEDIFF( asondate, acctrail_inv_date)  as agedays
			from acc_ref a, acc_trail c , massal_customer d, acc_group_master e where 
			accref_seqno = acctrail_accref_seqno 
			and c.acctrail_led_code = d.cust_code  and d.cust_acc_group = e.grp_code and e.grp_parent_code = 24
			and accref_comp_code = 1 
			and acctrail_inv_value > acctrail_adj_value and acctrail_adj_value >= 0
			and accref_voudate<= asondate  and acctrail_amtmode = 'D'  and grp_code = repcode and accref_vou_type  ='GSI' 
		
            union all

            select ref_adjseqno accref_seqno,ref_invno accref_vouno,ref_invdate accref_voudate, ref_invno accref_payref_no,ref_invdate accref_payref_date,
			 d.cust_name ledname ,acctrail_led_code,acctrail_inv_value,acctrail_adj_value, 
             case when acctrail_amtmode = 'D' then acctrail_inv_value- acctrail_adj_value else (acctrail_inv_value- acctrail_adj_value) * -1 end as balamt, ref_adjamount  adjamt, 
			 acctrail_amtmode,e.grp_code, e.grp_name, acctrail_crdays+ acctrail_gracedays  acctrail_crdays ,  DATE_FORMAT(DATE_ADD(acctrail_inv_date, INTERVAL acctrail_crdays+ acctrail_gracedays  DAY) ,'%d-%m-%Y') as  duedate,
			 DATEDIFF(asondate, DATE_ADD(acctrail_inv_date, INTERVAL acctrail_crdays+ acctrail_gracedays  DAY))  as oddays,
             DATEDIFF(asondate, acctrail_inv_date)  as agedays
			from acc_adjustments a, acc_trail c , massal_customer d, acc_group_master e where 
            ref_compcode = 1 and ref_invdate <= asondate and ref_docdate > asondate and ref_adjvoutype = 'GSI' and
			ref_adjseqno = acctrail_accref_seqno 
			and c.acctrail_led_code = d.cust_code  and d.cust_acc_group = e.grp_code and e.grp_parent_code = 24						
			and acctrail_amtmode = 'D'  and grp_code =  repcode
            
)a1 group by  accref_seqno, accref_payref_no, accref_payref_date, ledname, acctrail_led_code, 
grp_code, grp_name	             

)a2   where acctrail_led_code not in  (select l_custcode from massal_longpending_customers)  group by  accref_seqno,  accref_payref_no, accref_payref_date, ledname, acctrail_led_code, 
grp_code, grp_name	                          
       
       
       
            
            ) aa   where  (oddays > 0  or acctrail_crdays <=7)
        )aa1 left join       
        (
        select ref_ledcode,ref_docdate ,ref_invno,sum(ref_adjamount) preadjamt from acc_adjustments  , massal_customer d, acc_group_master e 
        where 
        	ref_ledcode = d.cust_code  and d.cust_acc_group = e.grp_code and e.grp_parent_code = 24   and grp_code = repcode and  
        ref_invdate <= asondate and (ref_docdate between collfromdate and colltodate) and ref_adjvoutype = 'GSI' group by ref_ledcode,ref_docdate ,ref_invno
        ) bb1
        on acctrail_led_code = ref_ledcode and accref_payref_no =   ref_invno
) cc1 order by ledname,accref_payref_date
) dd1 where acctrail_crdays <= 7;
end if;    
END ;;
