CREATE DEFINER=`root`@`%` PROCEDURE `spacc_rep_tds_groupwise`(compcode int,fincode int,fromdate date,todate date )
BEGIN
	select cust_name ,cust_code, sum(et_tdsamount) tdsamount from acc_expenses_header a, acc_expenses_trailer b,
	massal_customer ledger
	where eh_expno = et_expno and  eh_compcode = et_compcode  and eh_fincode = et_fincode and
	eh_compcode = compcode and eh_fincode = fincode and et_tdsledcode = ledger.cust_code
	and eh_voudate between fromdate and todate and  et_tdsamount >0 group by cust_name,cust_code;

END ;;
DELIMITER ;
