/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`%` PROCEDURE `spacc_rep_trialbalanceclosingcredit`(

finid int,

compcode int,

fromdate datetime,

todate datetime

)
BEGIN
select 

acctran_led_code,led_name,sup_grp_name,sum(Obdebit) as curbal_obdbamt,sum(Obcredit) as curbal_obcramt,sum(debit) as debit,

sum(credit) as credit,sum(Obdebit)-sum(Obcredit)+sum(debit)-sum(credit) as closing, sup_grp_name as grp


from

 (

 select  led_name,led_grp_code as grpcode,grp_name sup_grp_name,curbal_comp_code as accref_comp_code,curbal_finid as accref_finid,

curbal_led_code as acctran_led_code,curbal_obdbamt as Obdebit, curbal_obcramt as Obcredit,

0 as debit,0 as credit 

from acc_current_balance,acc_ledger_master, maspur_supplier_master a , acc_group_master b where 

curbal_finid = finid and (curbal_obdbamt+curbal_obcramt)>0 and curbal_led_code = led_code
and curbal_led_code = sup_led_code and a.sup_acc_group = b.grp_code
-- and led_comp_code=compcode 
and curbal_comp_code = compcode

union all 

 select led_name,led_grp_code as grpcode, grp_name sup_grp_name,accref_comp_code,accref_finid,acctran_led_code,

0 as Obdebit, 0 as Obcredit,

acctran_dbamt as debit,acctran_cramt as credit 

from acc_ref,acc_tran,acc_ledger_master, maspur_supplier_master a , acc_group_master b where 

accref_comp_code= compcode and accref_seqno = acctran_accref_seqno and

accref_finid= finid and

accref_voudate>= fromdate and accref_voudate<= todate and 

acctran_led_code = sup_led_code and a.sup_acc_group = b.grp_code and

acctran_led_code = led_code   

) tt

group by acctran_led_code ,led_name,sup_grp_name

having sum(Obdebit)-sum(Obcredit)+sum(debit)-sum(credit)<>0

order by grp,led_name;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `spacc_rep_trialbalanceclosingdebit` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`%` PROCEDURE `spacc_rep_trialbalanceclosingdebit`(

finid int,

compcode int,

fromdate datetime,

todate datetime

)
BEGIN
select 

acctran_led_code,led_name,cust_name,repr_name,sum(Obdebit) as curbal_obdbamt,sum(Obcredit) as curbal_obcramt,sum(debit) as debit,
sum(credit) as credit,sum(Obdebit)-sum(Obcredit)+sum(debit)-sum(credit) as closing

from

 (

 select  repr_name,cust_name,led_name,led_grp_code as grpcode,curbal_comp_code as accref_comp_code,curbal_finid as accref_finid,

curbal_led_code as acctran_led_code,curbal_obdbamt as Obdebit, curbal_obcramt as Obcredit,

0 as debit,0 as credit 

from acc_current_balance,acc_ledger_master, massal_customer a ,massal_repr where  cust_repr =  repr_code and

curbal_finid= finid and (curbal_obdbamt+curbal_obcramt)>0 and curbal_led_code = led_code
and curbal_led_code = a.cust_led_code 
and curbal_comp_code = compcode
union all 

select repr_name,cust_name,led_name,led_grp_code as grpcode,accref_comp_code,accref_finid,acctran_led_code,

0 as Obdebit, 0 as Obcredit,

acctran_dbamt as debit,acctran_cramt as credit 

from acc_ref,acc_tran,acc_ledger_master, massal_customer a ,massal_repr where  cust_repr =  repr_code and

accref_comp_code= compcode and accref_seqno = acctran_accref_seqno and

accref_finid= finid and

accref_voudate>= fromdate and accref_voudate<= todate and 

acctran_led_code = a.cust_led_code and 

acctran_led_code = led_code   

) tt

group by acctran_led_code,led_name ,cust_name,repr_name

having sum(Obdebit)-sum(Obcredit)+sum(debit)-sum(credit)<>0

order by led_name;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
