CREATE DEFINER=`root`@`%` PROCEDURE `spacc_rep_voucher_history`(compcode int,fincode int,fromdate datetime,todate datetime)
BEGIN
select * from acc_voucher_logs , acc_ref , userMaster where accvou_userid = usr_code  and accvou_seqno = accref_seqno
 and accref_comp_code = compcode  and accref_finid = fincode and accvou_date >= fromdate and  accvou_date < todate;
END ;;
