DELIMITER ;;
CREATE DEFINER=`root`@`%` PROCEDURE `spacc_rep_voucher_modification_history`(compcode int,fincode int,seqno int)
BEGIN
 select 'Current Details' rectype ,accref_vouno,accref_voudate entrydate,accref_voudate,cust_name ,acctran_dbamt, acctran_cramt  from acc_ref ref , acc_tran trn , massal_customer mas where acctran_led_code = cust_code and ref.accref_seqno = trn.acctran_accref_seqno and  ref.accref_seqno = seqno
 union all
 select 'Old Details' rectype ,accref_vouno,modified_date entrydate,accref_voudate,cust_name ,acctran_dbamt, acctran_cramt  from acc_ref ref , acc_correction_tran trn , massal_customer mas where acctran_led_code = cust_code and ref.accref_seqno = trn.acctran_accref_seqno and  ref.accref_seqno = seqno and  acctran_totamt > 0;
 END ;;
DELIMITER ;
