CREATE DEFINER=`root`@`%` PROCEDURE `spacc_rep_WPAdjust_CreditNote_Adjusted`(compcode int,fincode int, vouno varchar(17))
BEGIN
select * from acc_dbcrnote_header join massal_customer on dbcr_partycode = cust_code 
left join  acc_dbcrnote_trailer_Credit_Note_Adjustments on  dbcr_seqno =  dbcn_seqno
left join  acc_adjustments on dbcn_adj_seqno = ref_slno left join  acc_ref on accref_seqno = ref_adjseqno where
dbcr_type = 'CNG' and dbcr_finid = fincode and dbcr_comp_code = compcode and dbcr_vouno = vouno;
END ;;
