CREATE DEFINER=`root`@`%` PROCEDURE `spacc_rep_WPAdjust_CreditNote_Adjusted_Datewise`(compcode int,fincode int, fromdate date,todate date ,ledcode int )
BEGIN
select * from acc_dbcrnote_header join massal_customer on dbcr_partycode = cust_code and   dbcr_partycode = ledcode
left join  acc_dbcrnote_trailer_Credit_Note_Adjustments on  dbcr_seqno =  dbcn_seqno
