CREATE DEFINER=`root`@`%` PROCEDURE `spacc_rep_WPAdjust_CreditNote_List`(compcode int,fincode int, fromdate date,todate date,ledcode int)
BEGIN
select dbcr_seqno, dbcr_vouno,dbcr_date,DATE_FORMAT(dbcr_date, '%d-%m-%Y') as voudate , dbcr_value from (
select * from acc_dbcrnote_header join massal_customer on dbcr_partycode = cust_code left join  acc_dbcrnote_trailer_Credit_Note_Adjustments on  dbcr_seqno =  dbcn_seqno left join  acc_adjustments on dbcn_adj_seqno = ref_slno where   
dbcr_type = 'CNG' and dbcr_finid = fincode and dbcr_comp_code = compcode and dbcr_date between fromdate and todate and dbcr_partycode = ledcode ) a1 group by dbcr_seqno,dbcr_vouno,dbcr_date,dbcr_value  order by dbcr_date asc ,dbcr_vouno;
END ;;
