CREATE DEFINER=`root`@`%` PROCEDURE `spacc_tally_collection`(fromdate date,todate date,ctype varchar(1))
BEGIN
select  c_date,c_invno,c_collamt,invh_invrefno,invh_date,cust_ref,repr_name ,c_type from acc_collections , trnsal_invoice_header , massal_customer ,massal_repr where c_invno = invh_invrefno and invh_comp_code = 1 and invh_party = cust_code and cust_repr = repr_code
 and c_date between fromdate and todate and  c_type = ctype
 union all
   select c_date,c_invno,c_collamt,'' invh_invrefno,c_date invh_date, c_party cust_ref, repr_name,c_type  from acc_collections a left join massal_customer b on trim(c_party) = trim(cust_name)
 left join massal_repr c  on  c.repr_code = b.cust_repr where   c_date between fromdate and todate  and  c_type = ctype and left(c_invno,3) not in ('TN/','OS/');
 
 
END ;;
