CREATE DEFINER=`root`@`%` PROCEDURE `spfu_del_receipt_trailer`( 
p_rect_compcode int,
p_rect_fincode int,
p_rect_hdseqno int,
p_rect_ordhdseqno int)
BEGIN
DECLARE NOT_FOUND INT DEFAULT 0;
declare v_rect_seqno int; declare v_rect_lotno int; declare v_rect_item_code int;  
        declare v_rect_grnqty numeric(10,3);  
        declare v_rect_costrate numeric(14,5);  
        declare v_rect_millqty numeric(13,3);  
        declare v_rect_totqty numeric(13,3);
declare cur_receipttrailer cursor for 

	select rect_seqno,rect_lotno,rect_item_code,rect_grnqty,rect_costrate ,rect_millqty 
	from trnfu_receipt_trailer where rect_hdseqno=p_rect_hdseqno;
DECLARE CONTINUE HANDLER FOR NOT FOUND SET NOT_FOUND = 1;
open cur_receipttrailer;
fetch cur_receipttrailer into v_rect_seqno, v_rect_lotno, v_rect_item_code,
		v_rect_grnqty,v_rect_costrate,v_rect_millqty;
while NOT_FOUND=0
do
		set v_rect_totqty=v_rect_grnqty;	
        call spfu_upd_orderreceiptdets( p_rect_ordhdseqno,v_rect_item_code,v_rect_totqty,1);
	    set v_rect_grnqty = (v_rect_grnqty * (-1));
	    
        call spfu_insupd_stockdetails( p_rect_compcode,v_rect_lotno,
		 v_rect_item_code,v_rect_grnqty);
            
            call spfu_upd_itemtrailer_avgrate( p_rect_compcode,p_rect_fincode,
                      v_rect_item_code,v_rect_grnqty,v_rect_costrate,1);

	fetch cur_receipttrailer into v_rect_seqno, v_rect_lotno, v_rect_item_code,
		 v_rect_grnqty, v_rect_costrate,v_rect_millqty;
end while;
close cur_receipttrailer;
delete from trnfu_receipt_trailer where rect_hdseqno=p_rect_hdseqno;

END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
