CREATE DEFINER=`root`@`%` PROCEDURE `spfu_insupd_lotitemstock`(stkcompcode numeric(3,0),  
stkfincode int,  
stklotno int,  
stkitemcode int,  
stkqty numeric(10,3),  
stkvalue numeric(14,2),  
stkusrcode int  
)
begin
declare stkcnt int;
declare stkseqno int;
declare mascnt int;
declare mas_seqno int;  

declare oldqty decimal(8,1);
declare cloqty decimal(8,1);
declare cloval decimal(15,2);            
select count(*) into stkcnt from trnfu_stockdetails where stk_compcode=stkcompcode and 
						       stk_lotno=stklotno and stk_itemcode=stkitemcode;             
if stkcnt <= 0  
then
SET stkseqno = (select IFNULL(max(stk_seqno),0)+1 as stk_seqno from trnfu_stockdetails);

 insert into trnfu_stockdetails(stk_seqno,stk_compcode,stk_lotno,stk_itemcode,stk_qty)  
 values  (stkseqno, stkcompcode, stklotno, stkitemcode, stkqty);  
     
 update masfu_item_trailer set itmt_opqty= itmt_opqty + stkqty,itmt_opvalue= itmt_opvalue + stkvalue ,  itmt_clqty= itmt_clqty + stkqty,itmt_clvalue= itmt_clvalue + stkvalue  where  itmt_compcode=stkcompcode and itmt_fincode=stkfincode and itmt_hdcode=stkitemcode;  

   set cloqty = (select itmt_clqty   from masfu_item_trailer  where itmt_compcode = stkcompcode and itmt_fincode = stkfincode and itmt_hdcode = stkitemcode);
   set cloval = (select itmt_clvalue from masfu_item_trailer  where itmt_compcode = stkcompcode and itmt_fincode = stkfincode and itmt_hdcode = stkitemcode);
    if cloval >0 and cloqty > 0 
    then
    update masfu_item_trailer set itmt_avgrate = itmt_clvalue / itmt_clqty where  itmt_compcode=stkcompcode and itmt_fincode=stkfincode and itmt_hdcode=stkitemcode;       
    end if;  
else  
    
   set stkseqno = (select stk_seqno  from trnfu_stockdetails  where stk_compcode = stkcompcode and stk_lotno = stklotno and stk_itemcode = stkitemcode );
   set oldqty = (select stk_qty  from trnfu_stockdetails  where stk_compcode = stkcompcode and stk_lotno = stklotno and stk_itemcode = stkitemcode and stk_seqno = stkseqno);
   
   update trnfu_stockdetails set stk_qty  = stkqty  where stk_compcode = stkcompcode and stk_lotno = stklotno and stk_itemcode = stkitemcode and stk_seqno = stkseqno;  
   
   
   update masfu_item_trailer set itmt_opqty= itmt_opqty - oldqty + stkqty,itmt_opvalue= itmt_opvalue + stkvalue , itmt_clqty= itmt_clqty + stkqty,itmt_clvalue= itmt_clvalue + stkvalue  where  itmt_compcode=stkcompcode and itmt_fincode=stkfincode and itmt_hdcode=stkitemcode;  

   -- update masrm_item_trailer set itmt_avgrate = itmt_clvalue / itmt_clqty where  itmt_compcode=stkcompcode and itmt_fincode=stkfincode and itmt_hdcode=stkitemcode;       
      set cloqty = (select itmt_clqty     from masfu_item_trailer  where itmt_compcode = stkcompcode and itmt_fincode = stkfincode and itmt_hdcode = stkitemcode);
   set cloval = (select itmt_clvalue  from masfu_item_trailer  where itmt_compcode = stkcompcode and itmt_fincode = stkfincode and itmt_hdcode = stkitemcode);
    if cloval >0 and cloqty > 0 
    then
    update masfu_item_trailer set itmt_avgrate = itmt_clvalue / itmt_clqty where  itmt_compcode=stkcompcode and itmt_fincode=stkfincode and itmt_hdcode=stkitemcode;       
    end if;
   
   
end if ; 
  

end ;;
DELIMITER ;
