CREATE DEFINER=`root`@`%` PROCEDURE `spfu_ins_issret_trailer`(
					p_hdseqno	int,
					p_seqno	int,
					p_itmcode	int,
					p_qty		numeric	(13,3),
					p_rate		numeric	(14,2),
					p_values	numeric	(14,2),
