CREATE DEFINER=`root`@`%` PROCEDURE `spfu_itemdetails`( 
p_stk_compcode numeric(3,0),p_stk_fincode int)
begin

select itmh_name, itmh_code from masfu_item_header , masfu_item_trailer where itmh_code = itmt_hdcode and itmt_compcode = p_stk_compcode and itmt_fincode = p_stk_fincode and itmt_clqty > 0 group by 
itmh_name, itmh_code  order by itmh_name;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
