CREATE DEFINER=`root`@`%` PROCEDURE `spfu_lot_itemstock`(p_stk_compcode int,p_stk_fincode int,p_stk_lotno int,item int )
BEGIN

select 
	b.itmh_code,b.itmh_name 'itmh_name',a.stk_qty 'stock',
    c.itmt_avgrate, a.stk_qty_bags as 'stock_bags'
from 
	trnfu_stockdetails a, masfu_item_header b,masfu_item_trailer c 
where 
	stk_compcode=p_stk_compcode and stk_lotno=p_stk_lotno 
    and b.itmh_code = a.stk_itemcode and c.itmt_hdcode = a.stk_itemcode 
    and	c.itmt_compcode = p_stk_compcode and c.itmt_fincode = p_stk_fincode and itmh_code = item;
END ;;
DELIMITER ;
