DELIMITER ;;
CREATE DEFINER=`root`@`%` PROCEDURE `spfu_rep_datewiseissue`(compcode int,finid int, fromdate date,todate date)
BEGIN
SELECT
    mas_company.company_name,
    trnfu_issue_header.issh_compcode, trnfu_issue_header.issh_fincode, trnfu_issue_header.issh_no, trnfu_issue_header.issh_date,
    trnfu_issue_trailer.isst_qty, trnfu_issue_trailer.isst_rate, trnfu_issue_trailer.isst_values,
    masfu_item_header.itmh_name

FROM
    { oj ((mas_company  
    INNER JOIN trnfu_issue_header trnfu_issue_header ON
        mas_company.company_code = trnfu_issue_header.issh_compcode)
     INNER JOIN trnfu_issue_trailer trnfu_issue_trailer ON
        trnfu_issue_header.issh_seqno = trnfu_issue_trailer.isst_hdseqno)
     INNER JOIN masfu_item_header masfu_item_header ON
        trnfu_issue_trailer.isst_itmcode = masfu_item_header.itmh_code}
WHERE
    trnfu_issue_header.issh_compcode = compcode AND
    trnfu_issue_header.issh_fincode = finid AND
	trnfu_issue_header.issh_date>= fromdate AND
	trnfu_issue_header.issh_date<=  todate 
ORDER BY
    trnfu_issue_header.issh_no ASC;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
