DELIMITER ;;
CREATE DEFINER=`root`@`%` PROCEDURE `spfu_rep_datewisereceipt`(rechcompcode int,fromdate datetime(3),todate datetime(3))
BEGIN
SELECT
    mas_company.company_name,
    trnfu_receipt_header.rech_compcode,
    trnfu_receipt_header.rech_no, trnfu_receipt_header.rech_date, 
    trnfu_receipt_header.rech_billno, trnfu_receipt_header.rech_billdate,
    trnfu_receipt_trailer.rect_seqno, trnfu_receipt_trailer.rect_billqty,
    trnfu_receipt_trailer.rect_itemrate, trnfu_receipt_trailer.rect_grnqty,
     trnfu_receipt_trailer.rect_millqty, trnfu_receipt_trailer.rect_totdedqty,
    trnfu_receipt_trailer.rect_itemvalue, trnfu_receipt_header.rech_totalamount,
    trnfu_receipt_trailer.rect_costvalue,     trnfu_receipt_header.rech_truckno,
    massal_customer.cust_ref, masfu_item_header.itmh_name
FROM
    { oj (((mas_company  INNER JOIN trnfu_receipt_header trnfu_receipt_header ON
        mas_company.company_code = trnfu_receipt_header.rech_compcode)
     INNER JOIN massal_customer massal_customer ON
        trnfu_receipt_header.rech_sup_code = massal_customer.cust_code)
     INNER JOIN trnfu_receipt_trailer trnfu_receipt_trailer ON
    trnfu_receipt_header.rech_seqno = trnfu_receipt_trailer.rect_hdseqno)
     INNER JOIN masfu_item_header masfu_item_header ON
        trnfu_receipt_trailer.rect_item_code = masfu_item_header.itmh_code}
WHERE
   trnfu_receipt_header.rech_date>= fromdate  
   and trnfu_receipt_header.rech_date<=  todate
   and trnfu_receipt_header.rech_compcode = rechcompcode
ORDER BY
    trnfu_receipt_header.rech_no ASC;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `spfu_rep_freight` */;
