DELIMITER ;;
CREATE DEFINER=`root`@`%` PROCEDURE `spfu_rep_freight`(rechseqno int)
BEGIN
SELECT
*
FROM
    { oj (trnfu_receipt_trailer )
     INNER JOIN trnfu_receipt_header trnfu_receipt_header ON
        trnfu_receipt_trailer.rect_hdseqno = trnfu_receipt_header.rech_seqno}
WHERE
    trnfu_receipt_header.rech_seqno = rechseqno
ORDER BY
    trnfu_receipt_trailer.rect_seqno ASC;
END ;;
DELIMITER ;
