CREATE DEFINER=`root`@`%` PROCEDURE `spfu_rep_grn`(rechcompcode int, rechfincode int, rechno varchar(10))
BEGIN
select * from (
SELECT
mas_company.*,
trnfu_receipt_header.*,
massal_customer.*,
mas_state.*,
trnfu_order_header.*,
trnfu_receipt_trailer.*,
masfu_item_header.*,
entry.usr_name enteredby , 
case when rech_modified_by = 0 then  '' else concat("Modified By ", modified.usr_name , " on " , DATE_FORMAT(rech_modified_on, '%d-%m-%Y %H:%i:%s') ) end as modifiedby 
FROM
    { oj (((((((mas_company mas_company INNER JOIN trnfu_receipt_header trnfu_receipt_header ON
        mas_company.company_code = trnfu_receipt_header.rech_compcode)
     INNER JOIN massal_customer massal_customer ON
        trnfu_receipt_header.rech_sup_code = massal_customer.cust_code)
     INNER JOIN mas_state mas_state ON
        massal_customer.cust_state = mas_state.state_code)
     INNER JOIN trnfu_order_header trnfu_order_header ON
        trnfu_receipt_header.rech_ordhdseqno = trnfu_order_header.ordh_seqno)
     INNER JOIN trnfu_receipt_trailer trnfu_receipt_trailer ON
        trnfu_receipt_header.rech_seqno = trnfu_receipt_trailer.rect_hdseqno)
     INNER JOIN masfu_item_header masfu_item_header ON
        trnfu_receipt_trailer.rect_item_code = masfu_item_header.itmh_code)
      INNER JOIN userMaster entry ON
         entry.usr_code = trnfu_receipt_header.rech_usr_code)
      INNER JOIN userMaster modified ON
         modified.usr_code = trnfu_receipt_header.rech_modified_by             
        }
WHERE
    trnfu_receipt_header.rech_no = rechno AND
    trnfu_receipt_header.rech_compcode = rechcompcode AND
    trnfu_receipt_header.rech_fincode = rechfincode
-- GROUP BY trnfu_receipt_header.rech_no
ORDER BY
    trnfu_receipt_header.rech_no ASC,
    trnfu_receipt_trailer.rect_seqno ASC
) a1;    
END ;;
DELIMITER ;
