CREATE DEFINER=`root`@`%` PROCEDURE `spfu_rep_issue_date_Itemwise`(compcode int,fromdate date,todate date)
BEGIN
select  issh_date,itmh_name ,isst_itemtype , sum(isst_qty) qty , sum(isst_values) value from trnfu_issue_header, trnfu_issue_trailer, 
masfu_item_header where 
isst_itmcode = itmh_code and 
issh_seqno = isst_hdseqno and  issh_compcode = compcode and issh_date between fromdate  and  todate
group by issh_date, itmh_name ,isst_itemtype order by issh_date,itmh_name  desc;
END ;;
