/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`%` PROCEDURE `spfu_rep_item_ledger`(compcode int,fromdate date,todate date,itemcode int)
BEGIN
select * from (
select 'GRN' as trntype,DATE_FORMAT(rech_date, '%d-%m-%Y')  docdate,rech_no docno,cust_name supname ,itmh_name itemname, itmh_code, rect_grnqty qty,rect_itemvalue itemvalue, 
Cast(rect_itemrate as decimal(8,2)) as itemrate , rect_costvalue costvalue , 
Cast(rect_costrate as decimal(8,2)) as costrate 
from trnfu_receipt_header,trnfu_receipt_trailer , massal_customer,masfu_item_header where rech_sup_code = cust_code and rect_item_code =  itmh_code and rech_seqno = rect_hdseqno and  rech_date >= fromdate and rech_date<=  todate  and rech_compcode = compcode and rect_item_code = itemcode
union all
select 'ISSUE' as trntype,DATE_FORMAT(issh_date, '%d-%m-%Y')   docdate,issh_no docno,'ISSUE' supname ,itmh_name itemname, itmh_code, isst_qty qty,isst_values itemvalue, 
Cast(isst_rate as decimal(8,2)) as itemrate ,isst_values itemvalue, 
Cast(isst_rate as decimal(8,2)) as costrate   from trnfu_issue_header ,trnfu_issue_trailer ,masfu_item_header where  isst_itmcode =  itmh_code and  issh_seqno = isst_hdseqno AND issh_compcode = compcode AND issh_date >= fromdate  AND issh_date <=  todate  and isst_itmcode = itemcode 

) a1 order by docdate,trntype,docno;
END ;;
DELIMITER ;
