CREATE DEFINER=`root`@`%` PROCEDURE `spfu_rep_purchaseorder`(ordhcompcode int, ordhfincode int, ordhno varchar(100))
BEGIN


SELECT  * FROM
    mas_company mas_company INNER JOIN trnfu_order_header trnfu_order_header ON
        mas_company.company_code = trnfu_order_header.ordh_compcode
     INNER JOIN trnfu_order_trailer trnfu_order_trailer ON
        trnfu_order_header.ordh_seqno = trnfu_order_trailer.ordt_hdseqno
     INNER JOIN massal_customer massal_customer ON
        trnfu_order_header.ordh_sup_code = massal_customer.cust_code
     INNER JOIN mas_terms mas_terms ON
        trnfu_order_header.ordh_paymode = mas_terms.term_code 
     INNER JOIN mas_transport mas_transport ON
        trnfu_order_header.ordh_carriagetype = mas_transport.carr_code          
     INNER JOIN mas_state mas_state ON
        mas_state.state_code = massal_customer.cust_state        
     INNER JOIN masfu_item_header masfu_item_header ON
        trnfu_order_trailer.ordt_item_code = masfu_item_header.itmh_code
     INNER JOIN userMaster userMaster ON
        trnfu_order_header.ordh_usr_code = userMaster.usr_code         
WHERE
    trnfu_order_header.ordh_compcode = ordhcompcode AND
    trnfu_order_header.ordh_fincode = ordhfincode AND
    trnfu_order_header.ordh_no IN (ordhno)
ORDER BY
    trnfu_order_header.ordh_no ASC;

   
/*
SELECT
    mas_company.company_code, mas_company.company_name, mas_company.company_gst,
    trnfu_order_header.ordh_compcode, trnfu_order_header.ordh_fincode, 
    trnfu_order_header.ordh_no,trnfu_order_header.ordh_date, trnfu_order_header.ordh_preparedby,
    trnfu_order_header.ordh_refno,trnfu_order_header.ordh_refdate,trnfu_order_header.ordh_terms,
    trnfu_order_header.ordh_creditdays, mas_terms.term_name,mas_transport.carr_name,
    trnfu_order_header.ordh_remarks, trnfu_order_header.ordh_cgstper, 
    trnfu_order_header.ordh_sgstper, trnfu_order_header.ordh_igstper, 
    trnfu_order_header.ordh_handling_cgstper, 
    trnfu_order_header.ordh_handling_sgstper,
    trnfu_order_header.ordh_wef_date, trnfu_order_header.ordh_cess_pmt,
 --   vewfu_latestorderamnd_header.amnh_wef_date,
    vewfu_orderreceipt_order.stat, vewfu_orderreceipt_order.ordt_qty, 
    vewfu_orderreceipt_order.ordt_unit_rate, vewfu_orderreceipt_order.ordt_item_value,
    massal_customer.sup_name, massal_customer.sup_addr1, 
    massal_customer.sup_addr2, massal_customer.sup_addr3, 
    massal_customer.sup_city, massal_customer.sup_zip, 
    massal_customer.sup_gstin, masfu_item_header.itmh_name, masfu_item_header.itmh_code,
    masfu_item_header.itmh_hsncode,
    trnfu_order_header.ordh_total_mois,
    trnfu_order_header.ordh_mois_tol,
    trnfu_order_header.ordh_inh_mois,
    trnfu_order_header.ordh_vol_meter,
    trnfu_order_header.ordh_fixed_carbon,
    trnfu_order_header.ordh_sulpher,
    trnfu_order_header.ordh_gcv_adb,
    trnfu_order_header.ordh_gcv_adbtol,
    trnfu_order_header.ordh_gcv_arb,
    trnfu_order_header.ordh_gcv_arbtol,
    trnfu_order_header.ordh_ash,
    trnfu_order_header.ordh_vessal,
    trnfu_order_header.ordh_size,
	trnfu_order_header.ordh_cess_pmt,
    trnfu_order_header.ordh_handling_mt,
    trnfu_order_header.ordh_handling_cgstper,
    trnfu_order_header.ordh_handling_sgstper,
     trnfu_order_header.ordh_totalvalue,
    trnfu_order_header.ordh_tcs,mas_state.state_name, mas_state.state_codeno,ordt_moisper,ordt_finesper,ordt_sandper

FROM
    { oj ((((((mas_company mas_company INNER JOIN trnfu_order_header trnfu_order_header ON
        mas_company.company_code = trnfu_order_header.ordh_compcode)
 --    INNER JOIN vewfu_latestorderamnd_header vewfu_latestorderamnd_header ON
--        trnfu_order_header.ordh_seqno = vewfu_latestorderamnd_header.amnh_ordhdseqno)
     INNER JOIN vewfu_orderreceipt_order vewfu_orderreceipt_order ON
        trnfu_order_header.ordh_seqno = vewfu_orderreceipt_order.ordt_hdseqno)
     INNER JOIN massal_customer massal_customer ON
        trnfu_order_header.ordh_sup_code = massal_customer.sup_code)
     INNER JOIN mas_terms mas_terms ON
        trnfu_order_header.ordh_paymode = mas_terms.term_code) 
     INNER JOIN mas_transport mas_transport ON
        trnfu_order_header.ordh_carriagetype = mas_transport.carr_code)          
     INNER JOIN mas_state mas_state ON
        mas_state.state_code = massal_customer.sup_state)        
     INNER JOIN masfu_item_header masfu_item_header ON
        vewfu_orderreceipt_order.ordt_item_code = masfu_item_header.itmh_code}
WHERE
    trnfu_order_header.ordh_compcode = ordhcompcode AND
    trnfu_order_header.ordh_fincode = ordhfincode AND
    trnfu_order_header.ordh_no IN (ordhno)
ORDER BY
    trnfu_order_header.ordh_no ASC,
    vewfu_orderreceipt_order.stat ASC;
 */   
    
END ;;
