/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`%` PROCEDURE `spfu_rep_stock_abstract`(
p_comp_code int,  
p_fin_code int,  
p_fst_date datetime(3),  
p_op_date datetime(3),  
p_from_date datetime(3),  
p_to_date datetime(3),  
p_rtype int)
begin  
if p_rtype = 1 
then
select company_name,itmh_name ,itmh_code, (itmt_opqty   + op_rect_qty -  op_recret_qty -  op_is_qty    + op_ir_qty  - op_sale_qty + rect_qty  - recret_qty  - is_qty + ir_qty - sale_qty) as cloqty,  
(itmt_opvalue + op_rect_val -  op_recret_val -  op_is_value  + op_ir_value - op_sale_value + rect_val - recret_val  - is_value +  ir_value - sale_value) as clovalue,
(itmt_opvalue + op_rect_val -  op_recret_val -  op_is_value  + op_ir_value - op_sale_value + rect_val - recret_val  - is_value +  ir_value - sale_value) / (itmt_opqty   + op_rect_qty -  op_recret_qty -  op_is_qty    + op_ir_qty  - op_sale_qty + rect_qty  - recret_qty  - is_qty + ir_qty - sale_qty) as avgrate
from (
select company_name,itmh_name,itmh_code,itmt_opqty,itmt_opvalue,
ifnull(opre.op_rect_qty,0) as op_rect_qty,ifnull(opre.op_rect_val,0) as op_rect_val,  
ifnull(oprr.op_recret_qty,0) as op_recret_qty,ifnull(oprr.op_recret_val,0) as op_recret_val,
ifnull(opis.op_is_qty,0) as op_is_qty,ifnull(opis.op_is_value,0) as op_is_value,  
ifnull(opir.op_ir_qty,0) as op_ir_qty,ifnull(opir.op_ir_value,0) as op_ir_value,
ifnull(opsale.op_sale_qty,0) as op_sale_qty,ifnull(opsale.op_sale_value,0) as op_sale_value,  
ifnull(re.rect_qty,0) as rect_qty,ifnull(re.rect_val,0) as rect_val,
ifnull(rr.recret_qty,0) as recret_qty,ifnull(rr.recret_val,0) as recret_val,
ifnull(iss.is_qty,0) as is_qty,  
ifnull(iss.is_value,0) as is_value,ifnull(isr.ir_qty,0) as ir_qty,
ifnull(isr.ir_value,0) as ir_value ,ifnull(sale.sale_qty,0) as sale_qty,
ifnull(sale.sale_value,0) as sale_value from  
masfu_item_trailer d
left outer join  
(select rech_compcode,rect_item_code,ifnull(sum(rect_grnqty),0) as op_rect_qty ,
ifnull(sum(rect_costvalue),0) as op_rect_val   
from trnfu_receipt_header,trnfu_receipt_trailer   
where rech_seqno = rect_hdseqno and rech_compcode = p_comp_code 
and rech_fincode = p_fin_code and rech_date >= p_fst_date and rech_date < p_op_date  
group by rech_compcode,rech_fincode,rect_item_code) opre on
  d.itmt_hdcode =opre.rect_item_code
  
 left outer join
(select rerh_compcode,rert_itemcode,ifnull(sum(rert_qty),0) as op_recret_qty,
ifnull(sum(rert_totitemvalue),0) as op_recret_val  
from trnfu_receiptret_header,trnfu_receiptret_trailer   
where rerh_seqno = rert_hdseqno and rerh_compcode = p_comp_code 
and rerh_fincode = p_fin_code and rerh_date >= p_fst_date and rerh_date < p_op_date  
group by rerh_compcode,rerh_fincode,rert_itemcode) oprr on
  d.itmt_hdcode = oprr.rert_itemcode
  
   left outer join
(select issh_compcode,isst_itmcode ,ifnull(sum(isst_qty),0) as op_is_qty,
ifnull(sum(isst_values),0) as op_is_value   
from trnfu_issue_header ,trnfu_issue_trailer   
where issh_seqno = isst_hdseqno and issh_compcode = p_comp_code 
and issh_fincode = p_fin_code and issh_date >= p_fst_date and issh_date < p_op_date  
group by issh_compcode,isst_itmcode) opis on
  d.itmt_hdcode = opis.isst_itmcode
   left outer join
(select isrh_compcode,isrt_itemcode ,ifnull(sum(isrt_qty),0) as op_ir_qty,
ifnull(sum(isrt_values),0) as op_ir_value   
from trnfu_issret_header ,trnfu_issret_trailer   
where isrh_seqno = isrt_hdseqno and isrh_compcode = p_comp_code 
and isrh_fincode = p_fin_code and isrh_date >= p_fst_date and isrh_date < p_op_date  
group by isrh_compcode,isrt_itemcode) opir on
  d.itmt_hdcode = opir.isrt_itemcode
   left outer join
(select salh_compcode,salt_itemcode,ifnull(sum(salt_qty),0) as op_sale_qty,
ifnull(sum(salt_value),0) as op_sale_value  
from trnfu_salenote_header, trnfu_salenote_trailer  
where salh_seqno = salt_hdseqno and salh_compcode = p_comp_code 
and salh_fincode = p_fin_code and salh_date >= p_fst_date and salh_date < p_op_date  
group by salh_compcode,salt_itemcode) opsale on
  d.itmt_hdcode = opsale.salt_itemcode
   left outer join
(select rech_compcode,rect_item_code,ifnull(sum(rect_grnqty),0) as rect_qty ,
ifnull(sum(rect_costvalue),0) as rect_val   
from trnfu_receipt_header,trnfu_receipt_trailer   
where rech_seqno = rect_hdseqno and rech_compcode = p_comp_code 
and rech_fincode = p_fin_code and rech_date >= p_from_date and rech_date <= p_to_date  
group by rech_compcode,rech_fincode,rect_item_code) re on
  d.itmt_hdcode = re.rect_item_code
   left outer join
(select rerh_compcode,rert_itemcode,ifnull(sum(rert_qty),0) as recret_qty,
ifnull(sum(rert_totitemvalue),0) as recret_val  
from trnfu_receiptret_header,trnfu_receiptret_trailer   
where rerh_seqno = rert_hdseqno and rerh_compcode = p_comp_code 
and rerh_fincode = p_fin_code and rerh_date >= p_from_date and rerh_date <= p_to_date  
group by rerh_compcode,rerh_fincode,rert_itemcode) rr on
  d.itmt_hdcode = rr.rert_itemcode
   left outer join
(select issh_compcode,isst_itmcode ,ifnull(sum(isst_qty),0) as is_qty,
ifnull(sum(isst_values),0) as is_value   
from trnfu_issue_header ,trnfu_issue_trailer   
where issh_seqno = isst_hdseqno and issh_compcode = p_comp_code 
and issh_fincode = p_fin_code and issh_date >= p_from_date and issh_date <= p_to_date  
group by issh_compcode,isst_itmcode) iss on
d.itmt_hdcode = iss.isst_itmcode  
   left outer join
(select isrh_compcode,isrt_itemcode ,ifnull(sum(isrt_qty),0) as ir_qty,
ifnull(sum(isrt_values),0) as ir_value   
from trnfu_issret_header ,trnfu_issret_trailer   
where isrh_seqno = isrt_hdseqno and isrh_compcode = p_comp_code 
and isrh_fincode = p_fin_code and isrh_date >= p_from_date and isrh_date <= p_to_date  
group by isrh_compcode,isrt_itemcode) isr on
	d.itmt_hdcode = isr.isrt_itemcode 
   left outer join
(select salh_compcode,salt_itemcode,ifnull(sum(salt_qty),0) as sale_qty,
ifnull(sum(salt_value),0) as sale_value  
from trnfu_salenote_header, trnfu_salenote_trailer  
where salh_seqno = salt_hdseqno and salh_compcode = p_comp_code 
and salh_fincode = p_fin_code and salh_date >= p_from_date and salh_date <= p_to_date  
group by salh_compcode,salt_itemcode) sale on
	d.itmt_hdcode = sale.salt_itemcode
   inner join
masfu_item_header c on c.itmh_code = d.itmt_hdcode
   inner join mas_company e  
where   
d.itmt_compcode = p_comp_code and  
d.itmt_fincode = p_fin_code and  
e.company_code = p_comp_code
 ) a1 where itmt_opqty + op_rect_qty + op_is_qty+rect_qty +is_qty > 0 order by itmh_name;    
else

select company_name,itmh_name ,itmh_code, (itmt_opqty   + op_rect_qty -  op_recret_qty -  op_is_qty    + op_ir_qty  - op_sale_qty + rect_qty  - recret_qty  - is_qty + ir_qty - sale_qty) as cloqty,  
(itmt_opvalue + op_rect_val -  op_recret_val -  op_is_value  + op_ir_value - op_sale_value + rect_val - recret_val  - is_value +  ir_value - sale_value) as clovalue ,
(itmt_opvalue + op_rect_val -  op_recret_val -  op_is_value  + op_ir_value - op_sale_value + rect_val - recret_val  - is_value +  ir_value - sale_value) / (itmt_opqty   + op_rect_qty -  op_recret_qty -  op_is_qty    + op_ir_qty  - op_sale_qty + rect_qty  - recret_qty  - is_qty + ir_qty - sale_qty) as avgrate
from (
SELECT 
    company_name,
    itmh_name,itmh_code,
    itmt_opqty,
    itmt_opvalue,
    IFNULL(opre.op_rect_qty, 0) AS op_rect_qty,
    IFNULL(opre.op_rect_val, 0) AS op_rect_val,
    IFNULL(oprr.op_recret_qty, 0) AS op_recret_qty,
    IFNULL(oprr.op_recret_val, 0) AS op_recret_val,
    IFNULL(opis.op_is_qty, 0) AS op_is_qty,
    IFNULL(opis.op_is_value, 0) AS op_is_value,
    IFNULL(opir.op_ir_qty, 0) AS op_ir_qty,
    IFNULL(opir.op_ir_value, 0) AS op_ir_value,
    IFNULL(opsale.op_sale_qty, 0) AS op_sale_qty,
    IFNULL(opsale.op_sale_value, 0) AS op_sale_value,
    IFNULL(re.rect_qty, 0) AS rect_qty,
    IFNULL(re.rect_val, 0) AS rect_val,
    IFNULL(rr.recret_qty, 0) AS recret_qty,
    IFNULL(rr.recret_val, 0) AS recret_val,
    IFNULL(iss.is_qty, 0) AS is_qty,
    IFNULL(iss.is_value, 0) AS is_value,
    IFNULL(isr.ir_qty, 0) AS ir_qty,
    IFNULL(isr.ir_value, 0) AS ir_value,
    IFNULL(sale.sale_qty, 0) AS sale_qty,
    IFNULL(sale.sale_value, 0) AS sale_value
FROM
    (SELECT 
        itmt_hdcode,
            itmt_compcode,
            itmt_fincode,
            SUM(itmt_opqty) AS itmt_opqty,
            SUM(itmt_opvalue) AS itmt_opvalue,
            SUM(itmt_clqty) AS itmt_clqty,
            SUM(itmt_clvalue) AS itmt_clvalue,
            SUM(itmt_avgrate) AS itmt_avgrate
    FROM
        (SELECT 
        *
    FROM
        masfu_item_trailer
    WHERE
        itmt_fincode = p_fin_code
            AND itmt_compcode = p_comp_code UNION ALL SELECT 
        *
    FROM
        masfu_item_trailer
    WHERE
        itmt_fincode = p_fin_code
            AND itmt_compcode = p_comp_code) aa
    GROUP BY itmt_hdcode ,  itmt_compcode , itmt_fincode) d
        LEFT OUTER JOIN
    (SELECT 
        rech_compcode,
            rect_item_code,
            IFNULL(SUM(rect_grnqty), 0) AS op_rect_qty,
            IFNULL(SUM(rect_costvalue), 0) AS op_rect_val
    FROM
        trnfu_receipt_header, trnfu_receipt_trailer
    WHERE
        rech_seqno = rect_hdseqno
            AND rech_compcode = p_comp_code
            AND rech_fincode = p_fin_code
            AND rech_date >= p_fst_date
            AND rech_date < p_op_date
    GROUP BY rech_compcode , rech_fincode , rect_item_code) opre ON d.itmt_hdcode = opre.rect_item_code
        LEFT OUTER JOIN
    (SELECT 
        rerh_compcode,
            rert_itemcode,
            IFNULL(SUM(rert_qty), 0) AS op_recret_qty,
            IFNULL(SUM(rert_totitemvalue), 0) AS op_recret_val
    FROM
        trnfu_receiptret_header, trnfu_receiptret_trailer
    WHERE
        rerh_seqno = rert_hdseqno
            AND rerh_compcode = p_comp_code
            AND rerh_fincode = p_fin_code
            AND rerh_date >= p_fst_date
            AND rerh_date < p_op_date
    GROUP BY rerh_compcode , rerh_fincode , rert_itemcode) oprr ON d.itmt_hdcode = oprr.rert_itemcode
        LEFT OUTER JOIN
    (SELECT 
        issh_compcode,
            isst_itmcode,
            IFNULL(SUM(isst_qty), 0) AS op_is_qty,
            IFNULL(SUM(isst_values), 0) AS op_is_value
    FROM
        trnfu_issue_header, trnfu_issue_trailer
    WHERE
        issh_seqno = isst_hdseqno
            AND issh_compcode = p_comp_code
            AND issh_fincode = p_fin_code
            AND issh_date >= p_fst_date
            AND issh_date < p_op_date
    GROUP BY issh_compcode , isst_itmcode) opis ON d.itmt_hdcode = opis.isst_itmcode
        LEFT OUTER JOIN
    (SELECT 
        isrh_compcode,
            isrt_itemcode,
            IFNULL(SUM(isrt_qty), 0) AS op_ir_qty,
            IFNULL(SUM(isrt_values), 0) AS op_ir_value
    FROM
        trnfu_issret_header, trnfu_issret_trailer
    WHERE
        isrh_seqno = isrt_hdseqno
            AND isrh_compcode = p_comp_code
            AND isrh_fincode = p_fin_code
            AND isrh_date >= p_fst_date
            AND isrh_date < p_op_date
    GROUP BY isrh_compcode , isrt_itemcode) opir ON d.itmt_hdcode = opir.isrt_itemcode
        LEFT OUTER JOIN
    (SELECT 
        salh_compcode,
            salt_itemcode,
            IFNULL(SUM(salt_qty), 0) AS op_sale_qty,
            IFNULL(SUM(salt_value), 0) AS op_sale_value
    FROM
        trnfu_salenote_header, trnfu_salenote_trailer
    WHERE
        salh_seqno = salt_hdseqno
            AND salh_compcode = p_comp_code
            AND salh_fincode = p_fin_code
            AND salh_date >= p_fst_date
            AND salh_date < p_op_date
    GROUP BY salh_compcode , salt_itemcode) opsale ON d.itmt_hdcode = opsale.salt_itemcode
        LEFT OUTER JOIN
    (SELECT 
        rech_compcode,
            rect_item_code,
            IFNULL(SUM(rect_grnqty), 0) AS rect_qty,
            IFNULL(SUM(rect_costvalue), 0) AS rect_val
    FROM
        trnfu_receipt_header, trnfu_receipt_trailer
    WHERE
        rech_seqno = rect_hdseqno
            AND rech_compcode = p_comp_code
            AND rech_fincode = p_fin_code
            AND rech_date >= p_from_date
            AND rech_date <= p_to_date
    GROUP BY rech_compcode , rech_fincode , rect_item_code) re ON d.itmt_hdcode = re.rect_item_code
        LEFT OUTER JOIN
    (SELECT 
        rerh_compcode,
            rert_itemcode,
            IFNULL(SUM(rert_qty), 0) AS recret_qty,
            IFNULL(SUM(rert_totitemvalue), 0) AS recret_val
    FROM
        trnfu_receiptret_header, trnfu_receiptret_trailer
    WHERE
        rerh_seqno = rert_hdseqno
            AND rerh_compcode = p_comp_code
            AND rerh_fincode = p_fin_code
            AND rerh_date >= p_from_date
            AND rerh_date <= p_to_date
    GROUP BY rerh_compcode , rerh_fincode , rert_itemcode) rr ON d.itmt_hdcode = rr.rert_itemcode
        LEFT OUTER JOIN
    (SELECT 
        issh_compcode,
            isst_itmcode,
            IFNULL(SUM(isst_qty), 0) AS is_qty,
            IFNULL(SUM(isst_values), 0) AS is_value
    FROM
        trnfu_issue_header, trnfu_issue_trailer
    WHERE
        issh_seqno = isst_hdseqno
            AND issh_compcode = p_comp_code
            AND issh_fincode = p_fin_code
            AND issh_date >= p_from_date
            AND issh_date <= p_to_date
    GROUP BY issh_compcode , isst_itmcode) iss ON d.itmt_hdcode = iss.isst_itmcode
        LEFT OUTER JOIN
    (SELECT 
        isrh_compcode,
            isrt_itemcode,
            IFNULL(SUM(isrt_qty), 0) AS ir_qty,
            IFNULL(SUM(isrt_values), 0) AS ir_value
    FROM
        trnfu_issret_header, trnfu_issret_trailer
    WHERE
        isrh_seqno = isrt_hdseqno
            AND isrh_compcode = p_comp_code
            AND isrh_fincode = p_fin_code
            AND isrh_date >= p_from_date
            AND isrh_date <= p_to_date
    GROUP BY isrh_compcode , isrt_itemcode) isr ON d.itmt_hdcode = isr.isrt_itemcode
        LEFT OUTER JOIN
    (SELECT 
        salh_compcode,
            salt_itemcode,
            IFNULL(SUM(salt_qty), 0) AS sale_qty,
            IFNULL(SUM(salt_value), 0) AS sale_value
    FROM
        trnfu_salenote_header, trnfu_salenote_trailer
    WHERE
        salh_seqno = salt_hdseqno
            AND salh_compcode = p_comp_code
            AND salh_fincode = p_fin_code
            AND salh_date >= p_from_date
            AND salh_date <= p_to_date
    GROUP BY salh_compcode , salt_itemcode) sale ON d.itmt_hdcode = sale.salt_itemcode
        INNER JOIN
    masfu_item_header c ON c.itmh_code = d.itmt_hdcode
        INNER JOIN
    mas_company e
WHERE
    d.itmt_compcode = p_comp_code
        AND d.itmt_fincode = p_fin_code
        AND e.company_code = p_comp_code
 ) a1 where itmt_opqty + op_rect_qty + op_is_qty+rect_qty +is_qty > 0 order by itmh_name;  
end if;


END ;;
DELIMITER ;
