CREATE DEFINER=`root`@`%` PROCEDURE `spfu_sel_issret`( p_ret_compcode int,p_ret_fincode int,p_ret_no int)
begin

select 
a.*,l.lot_refno,b.isrh_type,b.isrh_date,b.isrh_remarks,b.isrh_seqno,i.itmh_name,s.stk_qty,s.stk_qty_bags 
from 
trnfu_issret_trailer a, trnfu_issret_header b, masfu_item_header i, trnfu_stockdetails s ,  mas_lot l 
where 
b.isrh_no = p_ret_no and b.isrh_compcode = p_ret_compcode and 
b.isrh_fincode = p_ret_fincode and a.isrt_hdseqno = b.isrh_seqno and 
l.lot_code = a.isrt_lotseqno and
a.isrt_itemcode = i.itmh_code and s.stk_compcode = p_ret_compcode and 
a.isrt_itemcode = s.stk_itemcode and a.isrt_lotseqno = s.stk_lotno;

END ;;
