CREATE DEFINER=`root`@`%` PROCEDURE `spfu_sel_itemlotdetails`(  
 p_stk_compcode int,  
 p_stk_fincode int,  
 p_stk_itemcode int,
 p_stk_lotcode int
)
begin  
  /*mod on jan 8th*/
-- SQLINES LICENSE FOR EVALUATION USE ONLY
select    
b.lot_code,lot_refno,a.stk_qty 'stock',c.itmt_avgrate,c.itmt_clqty,d.itmh_type as 'type',c.itmt_clvalue as 'value'
  
from   
trnfu_stockdetails a,mas_lot b, masfu_item_trailer c,masfu_item_header d  
  
where stk_compcode = p_stk_compcode and stk_itemcode = p_stk_itemcode and b.lot_code = a.stk_lotno and  
 c.itmt_hdcode = a.stk_itemcode and c.itmt_compcode = p_stk_compcode and c.itmt_fincode = p_stk_fincode and   
 c.itmt_hdcode = d.itmh_code and a.stk_lotno = p_stk_lotcode;  

END ;;
