CREATE DEFINER=`root`@`%` PROCEDURE `spfu_sel_item_details`( p_compcode int, p_fincode int)
begin

select 
	a.itmh_name,a.itmh_code
from 
	 masfu_item_header a,masfu_item_trailer b 
where 
	itmt_compcode=p_compcode and b.itmt_fincode = p_fincode and a.itmh_code = b.itmt_hdcode
order by
	a.itmh_code;
    
END ;;
