DELIMITER ;;
CREATE DEFINER=`root`@`%` PROCEDURE `spfu_sel_item_details1`( p_compcode int, p_fincode int)
begin

select 
	a.itmh_code,a.itmh_name 'Item Name',b.itmt_clqty 'Stock',
    case when b.itmt_avgrate =0 then ifnull(c.isst_rate,0) 
    else b.itmt_avgrate end  as itmt_avgrate ,b.itmt_clbags as 'stock_bags'
from 
	 masfu_item_trailer b 
     inner join masfu_item_header a on a.itmh_code = b.itmt_hdcode
     left outer join 
	(select issh_compcode,issh_fincode,isst_itmcode,max(isst_hdseqno) as isst_hdseqno,
    max(isst_rate) isst_rate from trnfu_issue_header h,trnfu_issue_trailer t 
    where h.issh_seqno=t.isst_hdseqno
	group by issh_compcode,issh_fincode,isst_itmcode) c on 
    c.issh_compcode=b.itmt_compcode and c.issh_fincode=b.itmt_fincode 
    and c.isst_itmcode=b.itmt_hdcode
where 
	b.itmt_compcode=p_compcode and b.itmt_fincode = p_fincode 
order by
	a.itmh_code;
END ;;
