CREATE DEFINER=`root`@`%` PROCEDURE `spfu_sel_lotitem_stock_bk`( 
p_stk_compcode int,p_stk_fincode int,p_stk_lotno int,p_stk_itemcode int)
begin    

select a.*,b.stk_qty 'Stock',b.stk_qty_bags as 'Bags'   
from trnfu_stockdetails_bk b  
left outer join masfu_stockdetails_bk a ON
a.stk_compcode = b.stk_compcode and  
 a.stk_lotseqno = b.stk_lotno and  
 a.stk_itemcode = b.stk_itemcode
where b.stk_compcode = p_stk_compcode and  
 b.stk_lotno = p_stk_lotno and  
 b.stk_itemcode = p_stk_itemcode and  
 a.stk_fincode = p_stk_fincode; 
END ;;
