CREATE DEFINER=`root`@`%` PROCEDURE `spfu_sel_ordhead`(

p_ordh_compcode	int,
p_ordh_fincode 		int	,
p_ordh_seqno  int /* =0 */ )
begin
if p_ordh_seqno = '' then set p_ordh_seqno = 0; end if;
if p_ordh_seqno = 0 then 

select ordh_no,ordh_seqno from trnfu_order_header where ordh_compcode =  p_ordh_compcode  and ordh_fincode = p_ordh_fincode and
          ordh_status <> 'X' order by ordh_no desc;	
else


select ordh_no,ordh_seqno from trnfu_order_header where ordh_compcode =  p_ordh_compcode  and ordh_fincode = p_ordh_fincode 
	and ordh_seqno =  p_ordh_seqno order by ordh_no desc;
end if;

END ;;
DELIMITER ;
