CREATE DEFINER=`root`@`%` PROCEDURE `spfu_sel_orditem_dets`(
	p_ordt_hdseqno int,p_ordt_item_code int,p_status varchar(1)/* ='N' */ )
BEGIN
-- SQLINES LICENSE FOR EVALUATION USE ONLY
select ordt_item_code,ordt_purgrp,sum(ordt_qty) as ordt_qty,coalesce(max(tol_per),0) as tol_per,
(sum(ordt_qty)*coalesce(max(tol_per),0)/100) as tol_all_qty ,
sum(ordt_pen_qty)as ordt_pen_qty,max(ordt_unit_rate) as ordt_unit_rate, 
 max(ordt_moisper) as ordt_moisper
from trnfu_order_trailer,(select poqt_tolper as tol_per from mas_qtytolerance 
where poqt_code in(select max(poqt_code) from mas_qtytolerance where poqt_type='L')) a
where ordt_hdseqno=p_ordt_hdseqno and ordt_item_code=p_ordt_item_code and 
(ordt_status in ('O','P') or p_status='E')
group by ordt_item_code,ordt_purgrp;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
