CREATE DEFINER=`root`@`%` PROCEDURE `spfu_sel_ordno`(
p_ordno  int,
p_gin_compcode int,
p_fin_code	   int)
BEGIN

select a.*,b.*,d.*,e.*,g.*, f.cust_name purledger from trnfu_order_header a, trnfu_order_trailer b,  
massal_customer d, masfu_item_header e , massal_customer f , mas_area g
where a.ordh_seqno = b.ordt_hdseqno  and a.ordh_sup_code = d.cust_code 
and b.ordt_item_code = e.itmh_code  and ordh_purledger = f.cust_code 
and a.ordh_seqno = b.ordt_hdseqno and a.ordh_no =  p_ordno 
and b.ordt_areacode = g.area_code
and a.ordh_compcode = p_gin_compcode and a.ordh_fincode = p_fin_code;

END ;;
DELIMITER ;
