CREATE DEFINER=`root`@`%` PROCEDURE `spfu_sel_partyorders`(
	p_ordh_compcode numeric(3,0),
	p_ordh_fincode int ,
	p_ordh_sup_code int,
	p_fetch_type tinyint unsigned/* =0 */ )
BEGIN

select CONCAT((case ordh_amndstatus when 'N' then '' else 'A-' end),ltrim(rtrim(convert(ordh_no, char)))) as 'ord_no',ordh_seqno 
from trnfu_order_header  
where 	ordh_status in ('N','O','P',case when p_fetch_type=1 then 'C' else '' end ) and
	ordh_compcode=p_ordh_compcode 

AND 	
	ordh_sup_code =p_ordh_sup_code;
END ;;
