CREATE DEFINER=`root`@`%` PROCEDURE `spfu_sel_pending_grnlist`(
p_rech_compcode int,p_rech_fincode int)
begin

select rech_no,rech_seqno 
from trnfu_receipt_header 
where
      rech_acctflag !='Y' and 
      rech_compcode = p_rech_compcode and
      rech_fincode = p_rech_fincode
order by rech_no desc;
END ;;
