DELIMITER ;;
CREATE DEFINER=`root`@`%` PROCEDURE `spfu_sel_receiptheader_new`(      
p_rech_seqno int)
begin         
select h.*,s.sup_type,s.sup_name as sup_name,f.sup_name as frt_sup_name,
f2.sup_name as handling_sup_name,s.sup_code as sup_code,f.sup_code as frt_sup_code,
s.sup_led_code as sup_led_code,s.sup_taxcode,f.sup_led_code as frt_sup_led_code, 
t.tax_ledcode, f2.sup_led_code as handling_led_code 
 
from   
{ oj ((((trnfu_receipt_header  h

INNER JOIN maspur_supplier_master s ON s.sup_code=h.rech_sup_code)
LEFT OUTER JOIN maspur_supplier_master f ON h.rech_frpartycode=f.sup_code) 
LEFT OUTER JOIN maspur_supplier_master f2 ON h.rech_handling_party =f2.sup_code)
INNER JOIN trnfu_order_header o ON o.ordh_seqno=h.rech_ordhdseqno )}
INNER JOIN mas_tax t
where   
rech_seqno=p_rech_seqno 
 and s.sup_taxcode = t.tax_code;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
