CREATE DEFINER=`root`@`%` PROCEDURE `spfu_sel_recheddet`( 
p_rech_seqno int)
begin 

select a.*,b.ordh_mois_tol,s.sup_type, concat(ltrim(rtrim(convert(b.ordh_no, char)))) as ordh_no
from trnfu_receipt_header a,trnfu_order_header b,maspur_supplier_master s
