/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`%` PROCEDURE `spfu_sel_recitems`( 

p_stk_compcode numeric(3,0),p_rect_hdseqno int,p_ordt_hdseqno int/* =0 */ ,p_rerh_seqno int/* =0 */ )
begin 
if p_ordt_hdseqno<>0 
then
-- For Edit GRN

	select d.itmh_name as 'party_item',b.itmh_name as 'grn_item',c.lot_refno as 'lot_no',
		(e.ordt_pen_qty+a.rect_millqty)-(ifnull(g.rert_qty,0))-(case when e.ordt_rec_qty>e.ordt_qty then e.ordt_rec_qty-e.ordt_qty else 0 end)  as 'ordqty',a.rect_grnqty,f.stk_qty,
		(case when (a.rect_grnqty-f.stk_qty)<2 then 1
		     else (a.rect_grnqty-f.stk_qty) end) as rect_minqty, a.* ,b.itmh_ledcode ,a.rect_grnqty as act_rect_qty
	from trnfu_receipt_trailer a
    inner join masfu_item_header b ON a.rect_item_code=b.itmh_code
    inner join mas_lot c ON a.rect_lotno=c.lot_code
    inner join
	(select b.itmh_name,a.rect_hdseqno,rect_seqno from trnfu_receipt_trailer a,
		masfu_item_header b
		where rect_hdseqno=p_rect_hdseqno  and a.rect_partyitemcode=b.itmh_code) d 
        ON (a.rect_hdseqno=d.rect_hdseqno and 
		a.rect_seqno=d.rect_seqno)
	left outer join
	(select ordt_item_code,sum(ordt_qty) as ordt_qty,sum(ordt_rec_qty) as ordt_rec_qty,
    sum(ordt_pen_qty)as ordt_pen_qty from trnfu_order_trailer
		where ordt_hdseqno=p_ordt_hdseqno
		group by ordt_item_code) e ON (a.rect_item_code = e.ordt_item_code)
	inner join trnfu_stockdetails f on (a.rect_lotno=f.stk_lotno 
    and a.rect_item_code=f.stk_itemcode and
		f.stk_compcode=p_stk_compcode)
	left outer join (select rerh_grnseqno,rert_rectseqno,rert_itemcode,
    sum(rert_qty) as rert_qty from trnfu_receiptret_header h,trnfu_receiptret_trailer t 
    where h.rerh_seqno=t.rert_hdseqno 
	group by rerh_grnseqno,rert_rectseqno,rert_itemcode) g 
    ON a.rect_hdseqno=g.rerh_grnseqno and a.rect_seqno = g.rert_rectseqno
	where a.rect_hdseqno=p_rect_hdseqno 
	order by a.rect_seqno;
else
	if p_rerh_seqno=0

	then

   	select d.itmh_name+case when a.rect_item_code=a.rect_partyitemcode 
				then '' else CONCAT(' Deg. to ',b.itmh_name) end as 'grn_item',
		c.lot_refno as 'lot_no',(case when (a.rect_grnqty-ifnull(e.ret_qty,0))>f.stk_qty then f.stk_qty 
		else (a.rect_grnqty-ifnull(e.ret_qty,0)) end) as rect_grnqty,
		(case when (a.rect_grnbags-ifnull(e.ret_bags,0))>f.stk_qty_bags then f.stk_qty_bags else a.rect_grnbags
		end) as rect_grnbags,a.rect_seqno,a.rect_item_code,a.rect_partyitemcode,
		a.rect_lotno,a.rect_itemrate-a.rect_rateded  as rect_itemrate,a.rect_edper,a.rect_freightvalue,b.itmh_ledcode ,a.rect_grnqty as act_rect_qty
	   from trnfu_receipt_trailer a,masfu_item_header b,mas_lot c,
	   (select b.itmh_name,a.rect_hdseqno,rect_seqno from trnfu_receipt_trailer a,
		masfu_item_header b
		where rect_hdseqno=p_rect_hdseqno  and a.rect_partyitemcode=b.itmh_code) d,
	   (select rert_itemcode,rert_lotseqno,sum(rert_qty) as ret_qty,
		sum(rert_bags) as ret_bags  from 
		(select rert_itemcode,rert_lotseqno,rert_qty,rert_bags 
		from trnfu_receiptret_trailer 
		where rert_hdseqno in (select rerh_seqno from trnfu_receiptret_header 
			       where rerh_grnseqno=p_rect_hdseqno)
		union all
		select rect_item_code as rert_itemcode,rect_lotno as rert_lotseqno,
			0 as ret_qty,0 as ret_bags
		from trnfu_receipt_trailer where rect_hdseqno=p_rect_hdseqno) a
	   group by rert_itemcode,rert_lotseqno) e,
	   trnfu_stockdetails f
	   where a.rect_hdseqno=p_rect_hdseqno and a.rect_status='' and 
		a.rect_item_code=b.itmh_code and a.rect_lotno=c.lot_code and 
		(a.rect_hdseqno=d.rect_hdseqno and a.rect_seqno=d.rect_seqno) and
		(a.rect_item_code=e.rert_itemcode and a.rect_lotno=e.rert_lotseqno) and 
		(a.rect_lotno=f.stk_lotno and a.rect_item_code=f.stk_itemcode and
		f.stk_compcode=p_stk_compcode)
	   order by a.rect_seqno;
	else

   	select d.itmh_name+case when a.rect_item_code=a.rect_partyitemcode 
				then '' else CONCAT(' Deg. to ',b.itmh_name) end as 'grn_item',
		c.lot_refno as 'lot_no',(case when a.rect_grnqty-ifnull(e.ret_qty,0)>f.stk_qty then f.stk_qty 
		else a.rect_grnqty-ifnull(e.ret_qty,0) end) as rect_grnqty,
		(case when (a.rect_grnbags-ifnull(e.ret_bags,0))>f.stk_qty_bags then f.stk_qty_bags 
		else a.rect_grnbags-ifnull(e.ret_bags,0) end) as rect_grnbags,
		a.rect_seqno,a.rect_item_code,a.rect_partyitemcode,a.rect_lotno,
		a.rect_itemrate-a.rect_rateded  as rect_itemrate,a.rect_edper,a.rect_freightvalue,b.itmh_ledcode ,a.rect_grnqty as act_rect_qty
	   from trnfu_receipt_trailer a,masfu_item_header b,mas_lot c,
	   (select b.itmh_name,a.rect_hdseqno,rect_seqno from trnfu_receipt_trailer a,
		masfu_item_header b
		where rect_hdseqno=p_rect_hdseqno  and a.rect_partyitemcode=b.itmh_code) d,
	   (select rert_itemcode,rert_lotseqno,sum(rert_qty) as ret_qty,
		sum(rert_bags) as ret_bags  from 
		(select rert_itemcode,rert_lotseqno,rert_qty,rert_bags 
		from trnfu_receiptret_trailer 
		where rert_hdseqno in (select rerh_seqno from trnfu_receiptret_header 
			       where rerh_grnseqno=p_rect_hdseqno and rerh_seqno<>p_rerh_seqno)
		union all
		select rect_item_code as rert_itemcode,rect_lotno as rert_lotseqno,
			0 as ret_qty,0 as ret_bags
		from trnfu_receipt_trailer where rect_hdseqno=p_rect_hdseqno) a
	   group by rert_itemcode,rert_lotseqno) e,
	   trnfu_stockdetails f
	   where a.rect_hdseqno=p_rect_hdseqno and a.rect_status='' and 
		a.rect_item_code=b.itmh_code and a.rect_lotno=c.lot_code and 
		(a.rect_hdseqno=d.rect_hdseqno and a.rect_seqno=d.rect_seqno) and 
		(a.rect_item_code=e.rert_itemcode and a.rect_lotno=e.rert_lotseqno) and
		(a.rect_lotno=f.stk_lotno and a.rect_item_code=f.stk_itemcode and
		f.stk_compcode=p_stk_compcode)
	   order by a.rect_seqno;
	end if;
end if;

END ;;
DELIMITER ;
