CREATE DEFINER=`root`@`%` PROCEDURE `spfu_update_order`(  
p_ordh_seqno  int,            
p_ordh_compcode  int,            
p_ordh_fincode  int,            
p_ordh_no  int,   
p_ordh_date  datetime,                  
p_ordh_sup_code int,    
p_ordh_refno  varchar(30),   
p_ordh_refdate  datetime,                              
p_ordh_terms  varchar(60),            
p_ordh_carriagetype int,            
p_ordh_paymode  int,            
p_ordh_creditdays int,            
p_ordh_remarks  varchar(250),            
p_ordh_cgstper  numeric (5,2),          
p_ordh_sgstper  numeric (5,2),          
p_ordh_igstper  numeric (5,2),          
p_ordh_cess_pmt numeric(5,2),
p_ordh_handling_mt numeric(14,2),            
p_ordh_handling_cgstper numeric(5,2),        
p_ordh_handling_sgstper numeric(5,2),
p_ordh_tcs numeric(5,2),        
p_ordh_roundingoff numeric(5,2),            
p_ordh_totalvalue numeric(14,2),            
p_ordh_status  varchar(1),            
p_ordh_amndstatus varchar(1),            
p_ordh_amndposeqno   int,            
p_ordh_usr_code int,            
p_ordh_entry_date datetime(3),            
p_ordh_wef_date datetime(3) ,           
p_ordh_mois  numeric(5,2),        
p_ordh_mois_tol varchar(10),        
p_ordh_inh_mois varchar(10),        
p_ordh_vol_matter varchar(10),        
p_ordh_fixed_carbon varchar(20),        
p_ordh_sulpher varchar(10),        
p_ordh_gcvadb  int,        
p_ordh_gcvadb_tol  int,        
p_ordh_gcvarb  int,        
p_ordh_gcvarb_tol  int,        
p_ordh_ash varchar(20),        
p_ordh_vessal varchar(20),        
p_ordh_size varchar(20),
p_ordh_purledger  int ,
p_roundneed varchar(1)       
)
BEGIN        
update trnfu_order_header set         
ordh_sup_code = p_ordh_sup_code,        
ordh_date= p_ordh_date,     
ordh_refno = p_ordh_refno ,
ordh_refdate  = p_ordh_refdate, 
ordh_terms= p_ordh_terms,        
ordh_carriagetype= p_ordh_carriagetype,        
ordh_paymode= p_ordh_paymode,        
ordh_creditdays= p_ordh_creditdays,        
ordh_remarks= p_ordh_remarks,        
ordh_cgstper = p_ordh_cgstper,    
ordh_sgstper = p_ordh_sgstper,    
ordh_igstper = p_ordh_igstper,    
ordh_handling_cgstper=p_ordh_handling_cgstper,
ordh_handling_sgstper=p_ordh_handling_sgstper,
ordh_roundinff=p_ordh_roundingoff,        
ordh_totalvalue=p_ordh_totalvalue,        
ordh_status=p_ordh_status,        
ordh_amndstatus=p_ordh_amndstatus,        
ordh_amndposeqno=p_ordh_amndposeqno,        
ordh_usr_code=p_ordh_usr_code,        
ordh_entry_date=p_ordh_entry_date,      
ordh_handling_mt =p_ordh_handling_mt,       
ordh_total_mois = p_ordh_mois ,
ordh_mois_tol = p_ordh_mois_tol , 
ordh_inh_mois = p_ordh_inh_mois, 
ordh_vol_matter =p_ordh_vol_matter, 
ordh_fixed_carbon = p_ordh_fixed_carbon, 
ordh_sulpher = p_ordh_sulpher,
ordh_gcv_adb = p_ordh_gcvadb, 
ordh_gcv_adbtol = p_ordh_gcvadb_tol,
ordh_gcv_arb = p_ordh_gcvarb ,
ordh_gcv_arbtol = p_ordh_gcvarb_tol, 
ordh_ash = p_ordh_ash, 
ordh_vessal =p_ordh_vessal, 
ordh_cess_pmt = p_ordh_cess_pmt, 
ordh_tcs =  p_ordh_tcs,
ordh_purledger = p_ordh_purledger,
ordh_roundneed = p_roundneed 
where ordh_seqno = p_ordh_seqno;        
    
        
delete from trnfu_order_trailer where ordt_hdseqno = p_ordh_seqno;        

END ;;
