DELIMITER ;;
CREATE DEFINER=`root`@`%` PROCEDURE `spfu_upd_issret_stock`(  p_seqno int)
begin
declare not_found int default 0;
declare v_isrh_seqno int;  declare v_isrh_compcode int;  
declare v_isrh_fincode int; declare v_isrt_itemcode int;  
declare v_isrt_qty numeric(13,3);  declare v_isrt_values numeric(14,2);  
DECLARE reverse_cursor CURSOR FOR select  h.isrh_seqno,h.isrh_compcode,h.isrh_fincode,isrt_itemcode,isrt_qty,isrt_values
					from     trnfu_issret_header h, trnfu_issret_trailer t
					where  h.isrh_seqno = t.isrt_hdseqno and  h.isrh_seqno = p_seqno;
 declare continue handler for not found set not_found = 1;

        OPEN reverse_cursor;
 
            issstk: LOOP
			FETCH reverse_cursor INTO v_isrh_seqno,v_isrh_compcode,v_isrh_fincode,
            v_isrt_itemcode,v_isrt_qty,v_isrt_values;
                 IF not_found=1 THEN
                        LEAVE issstk;
                 END IF;     
                 -- cursor loop statements
/*                 
	update trnfu_stockdetails set 	stk_qty = stk_qty - v_isrt_qty,
             		       			stk_qty_bags =  stk_qty_bags - v_isrt_bags
             		      		where 	stk_compcode = v_isrh_compcode and
		            		              stk_lotno = v_isrt_lotseqno and
		                  		stk_itemcode = v_isrt_itemcode;
*/
	update masfu_item_trailer set 	itmt_clqty = itmt_clqty -  v_isrt_qty,
		                    		itmt_clvalue = itmt_clvalue - v_isrt_values
                    			 where	itmt_hdcode = v_isrt_itemcode and
                    				itmt_compcode = v_isrh_compcode and
                   				itmt_fincode = v_isrh_fincode;

            END LOOP issstk;
          
        CLOSE reverse_cursor;

SET not_found=0;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
