DELIMITER ;;
CREATE DEFINER=`root`@`%` PROCEDURE `spfu_upd_issue_stock`(p_seqno int)
begin
declare not_found int default 0;
declare v_issh_seqno int;  
declare v_issh_compcode int;  
declare v_issh_fincode int; 
declare v_isst_itmcode int;  
declare v_isst_qty numeric(13,3);  
declare v_isst_values numeric(14,2);  

DECLARE reverse_cursor CURSOR FOR 
select  h.issh_seqno,h.issh_compcode,h.issh_fincode,isst_itmcode,isst_qty,
isst_values
from     trnfu_issue_header h, trnfu_issue_trailer t
where  h.issh_seqno = t.isst_hdseqno and  h.issh_seqno = p_seqno;
 declare continue handler for not found set not_found = 1;

        OPEN reverse_cursor;
 
            issstk: LOOP
                 FETCH reverse_cursor INTO v_issh_seqno,v_issh_compcode,v_issh_fincode,
v_isst_itmcode,v_isst_qty,v_isst_values;
                 IF not_found=1 THEN
                        LEAVE issstk;
                 END IF;     
                 -- cursor loop statements
              /*
	update trnfu_stockdetails set 	stk_qty = stk_qty + v_isst_qty
             		      		where 	stk_compcode = v_issh_compcode and
		            		              stk_lotno = v_isst_lotseqno and
		                  		stk_itemcode = v_isst_itmcode;
*/
	update masfu_item_trailer set 	itmt_clqty = itmt_clqty +  v_isst_qty,
		                    		itmt_clvalue = itmt_clvalue + v_isst_values
                    			 where	itmt_hdcode = v_isst_itmcode and
                    				itmt_compcode = v_issh_compcode and
                   				itmt_fincode = v_issh_fincode;
            END LOOP issstk;
          
        CLOSE reverse_cursor;

SET not_found=0;
END ;;
DELIMITER ;
