CREATE DEFINER=`root`@`%` PROCEDURE `spfu_upd_itemtrailer_avgrate`(
p_itmt_compcode int,p_itmt_fincode int,p_itmt_hdcode int,
p_qty numeric(13,3),p_value numeric(14,2)/* =0 */ ,
p_updtype tinyint unsigned/* =0 */ )
begin

declare v_curqty numeric(13,3);  
declare v_curval numeric(14,2);  
declare v_itmt_avgrate numeric(14,5);
declare cur_itmt_avgrate numeric(14,5);

select itmt_clqty,itmt_clvalue,itmt_avgrate into v_curqty, v_curval, v_itmt_avgrate 
from masfu_item_trailer
where 
itmt_hdcode=p_itmt_hdcode and
itmt_compcode=p_itmt_compcode and
itmt_fincode=p_itmt_fincode;


update masfu_item_trailer 
set itmt_clqty = v_curqty + p_qty,
    itmt_clvalue = v_curval + p_value    
where itmt_hdcode=p_itmt_hdcode and
itmt_compcode=p_itmt_compcode and itmt_fincode=p_itmt_fincode;
    
update masfu_item_trailer 
set itmt_avgrate = case when itmt_clvalue > 0 and itmt_clqty > 0 then Cast(itmt_clvalue/itmt_clqty as decimal(18,5))   else 0 end
where itmt_hdcode=p_itmt_hdcode and
itmt_compcode=p_itmt_compcode and itmt_fincode=p_itmt_fincode;
/*
declare v_curqty numeric(13,3);  
declare v_curval numeric(14,2);  
declare v_itmt_avgrate numeric(14,5);
declare cur_itmt_avgrate numeric(14,5);

select itmt_clqty,itmt_clvalue,itmt_avgrate into v_curqty, v_curval, v_itmt_avgrate 
from masfu_item_trailer
where 
itmt_hdcode=p_itmt_hdcode and
itmt_compcode=p_itmt_compcode and
itmt_fincode=p_itmt_fincode;
if p_updtype>0
then
	if (v_curqty+p_qty) > 0
	then
		set cur_itmt_avgrate=round((v_curval + (p_qty * p_rate))/(v_curqty + p_qty),5);
	else
		set cur_itmt_avgrate=0;
	end if;
end if;
update masfu_item_trailer 
set itmt_clqty = v_curqty + p_qty,
    itmt_clvalue = round(((v_curqty + p_qty)*cur_itmt_avgrate),2),
    itmt_avgrate = cur_itmt_avgrate
where 
itmt_hdcode=p_itmt_hdcode and
itmt_compcode=p_itmt_compcode and
itmt_fincode=p_itmt_fincode;
*/

END ;;
DELIMITER ;
