CREATE DEFINER=`root`@`%` PROCEDURE `spfu_upd_orderreceiptdets`(
	p_ordt_hdseqno		int,
	p_rect_item_code	int,
	p_rect_qty		numeric(13,3),
	p_trantype		tinyint unsigned)
BEGIN
DECLARE NOT_FOUND INT DEFAULT 0;
declare v_penqty 		numeric(14,2);
declare v_penrec_qty		numeric(14,2);
declare	v_rec_qty		numeric(13,3);
declare	v_ord_qty		numeric(13,3);
declare v_pen_qty		numeric(13,3);
declare v_can_qty		numeric(13,3);

DECLARE receipt_cursor CURSOR FOR (select ordt_rec_qty,ordt_qty,ordt_pen_qty,ordt_can_qty  from trnfu_order_trailer  where ordt_hdseqno=p_ordt_hdseqno and ordt_item_code=p_rect_item_code );
DECLARE CONTINUE HANDLER FOR NOT FOUND SET NOT_FOUND = 1;
set v_penqty=p_rect_qty;	

OPEN receipt_cursor;
	recptstk: LOOP
		FETCH receipt_cursor INTO v_rec_qty,v_ord_qty,v_pen_qty,v_can_qty;
                 IF NOT_FOUND=1 THEN
                        LEAVE recptstk;
                 END IF; 


			if  v_penqty>0 
			then
				if p_trantype=0 
				then
					set v_penrec_qty=v_pen_qty;
					if v_penrec_qty >= v_penqty 
					then
						update trnfu_order_trailer set ordt_rec_qty=ordt_rec_qty+v_penqty where ordt_hdseqno=p_ordt_hdseqno and ordt_item_code=p_rect_item_code;
						/*update trnfu_indent_trailer set indt_grnqty=indt_grnqty+v_penqty where indt_hdseqno=v_indh_seqno and indt_itmh_code=p_rect_item_code;*/
						set v_penqty=0;
					else
						set v_penqty=v_penqty-v_penrec_qty;
						update trnfu_order_trailer set ordt_rec_qty=ordt_rec_qty+v_penrec_qty where ordt_hdseqno=p_ordt_hdseqno and ordt_item_code=p_rect_item_code;
						/*update trnfu_indent_trailer set indt_grnqty=indt_grnqty+v_penrec_qty where indt_hdseqno=v_indh_seqno and indt_itmh_code=p_rect_item_code;*/
					end if;
				else
					set v_penrec_qty=v_rec_qty;
					if v_penrec_qty >= v_penqty 
					then
						update trnfu_order_trailer set ordt_rec_qty=ordt_rec_qty-v_penqty where ordt_hdseqno=p_ordt_hdseqno and ordt_item_code=p_rect_item_code;
						/*update trnfu_indent_trailer set indt_grnqty=indt_grnqty-v_penqty where indt_hdseqno=v_indh_seqno and indt_itmh_code=p_rect_item_code;*/
						set v_penqty=0;
					else
						set v_penqty=v_penqty-v_penrec_qty;
						update trnfu_order_trailer set ordt_rec_qty=ordt_rec_qty-v_penrec_qty where ordt_hdseqno=p_ordt_hdseqno  and ordt_item_code=p_rect_item_code;
						/*update trnfu_indent_trailer set indt_grnqty=indt_grnqty-v_penrec_qty where indt_hdseqno=v_indh_seqno and indt_itmh_code=p_rect_item_code;*/
					end if;
				end if; 	

			end if;

          

	update trnfu_order_trailer set ordt_pen_qty=case when ordt_qty-(ordt_rec_qty+ordt_can_qty)>0 then ordt_qty-(ordt_rec_qty+ordt_can_qty) else 0 end where ordt_hdseqno=p_ordt_hdseqno and ordt_item_code=p_rect_item_code;

	update trnfu_order_trailer set ordt_status='O' where ordt_qty=ordt_pen_qty and ordt_hdseqno=p_ordt_hdseqno and  ordt_item_code=p_rect_item_code;
	update trnfu_order_trailer set ordt_status='P' where ordt_qty<>ordt_pen_qty and ordt_hdseqno=p_ordt_hdseqno and ordt_item_code=p_rect_item_code;
	update trnfu_order_trailer set ordt_status='C' where ordt_pen_qty=0 and ordt_hdseqno=p_ordt_hdseqno and ordt_item_code=p_rect_item_code;
	
	/*update trnfu_indent_trailer set indt_status='C' where indt_qty<=indt_grnqty and indt_hdseqno=v_indh_seqno and indt_itmh_code=p_rect_item_code;
	update trnfu_indent_trailer set indt_status='P' where indt_qty>indt_grnqty and indt_hdseqno=v_indh_seqno and indt_itmh_code=p_rect_item_code; 
	
	update trnfu_indent_header set indh_status='P' where indh_seqno=indh_seqno and indh_seqno in(
	select indt_hdseqno from trnfu_indent_trailer where indt_hdseqno=v_indh_seqno and indt_status='P');	

	update trnfu_indent_header set indh_status='C' where indh_seqno=indh_seqno and indh_seqno not in(
	select indt_hdseqno from trnfu_indent_trailer where indt_hdseqno=v_indh_seqno and indt_status in('P','O'));	*/
 
END LOOP recptstk;                 
CLOSE receipt_cursor;

SET NOT_FOUND=0;

update trnfu_order_header set ordh_status='P' where ordh_seqno=p_ordt_hdseqno and ordh_seqno in(
select ordt_hdseqno from trnfu_order_trailer where ordt_hdseqno=p_ordt_hdseqno and ordt_status='P');

update trnfu_order_header set ordh_status='C' where ordh_seqno=p_ordt_hdseqno and ordh_seqno not in(
select ordt_hdseqno from trnfu_order_trailer where ordt_hdseqno=p_ordt_hdseqno and ordt_status in('P','O'));

END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
