CREATE DEFINER=`root`@`%` PROCEDURE `spfu_upd_order_amend`(  
p_ordseqno         int,  
p_amndseqno     int,  
p_amnddate     datetime(3),  
p_wefdate        datetime(3))
begin  
insert into trnfu_orderamnd_header select p_amndseqno,p_amnddate,ordh_seqno, ordh_compcode,
 ordh_fincode, ordh_no, ordh_date, ordh_sup_code, ordh_refno, ordh_refdate,
ordh_terms, ordh_carriagetype, ordh_paymode, ordh_creditdays, ordh_remarks, ordh_cgstper, ordh_sgstper,
ordh_igstper, ordh_cess_pmt, ordh_handling_mt, ordh_handling_cgstper, ordh_handling_sgstper, ordh_tcs,
ordh_roundinff, ordh_totalvalue, ordh_status, ordh_usr_code, ordh_entry_date, ordh_wef_date, ordh_total_mois, 
ordh_mois_tol, ordh_inh_mois, ordh_vol_meter, ordh_fixed_carbon, ordh_sulpher, ordh_gcv_adb, ordh_gcv_adbtol,
ordh_gcv_arb, ordh_gcv_arbtol, ordh_ash, ordh_vessal
from trnfu_order_header where ordh_seqno = p_ordseqno;  
  
insert into trnfu_orderamnd_trailer select p_amndseqno,ordt_seqno,ordt_item_code,
ordt_qty,ordt_rec_qty,ordt_can_qty, ordt_pen_qty,ordt_unit_rate,ordt_item_value  from trnfu_order_trailer where ordt_hdseqno = p_ordseqno;  
  
END ;;
