p_rech_handling_cgstamt numeric(10,2),  p_rech_handling_sgstamt numeric(10,2),
p_rech_tcs_per numeric(5,2),    
p_rech_tcs_amt numeric(9,2),    
p_rech_cess_pmt numeric(5,2),      
p_rech_cess_amount numeric(9,2),                   
p_rech_freight numeric(12,2),              
p_rech_othcharges numeric(14,2),              
p_rech_roundingoff numeric(3,2),              
p_rech_totalamount numeric(12,2),              
p_rech_billno varchar(20),              
p_rech_billdate datetime(3),              
