rech_cgst_amt = p_rech_cgst_amt,   
rech_sgst_per = p_rech_sgst_per,       
rech_sgst_amt = p_rech_sgst_amt,       
rech_igst_per = p_rech_igst_per ,       
rech_igst_amt = p_rech_igst_amt,       
rech_freight =p_rech_freight,              
rech_othcharges=p_rech_othcharges,              
rech_roundingoff =p_rech_roundingoff,              
rech_totalamount =p_rech_totalamount,              
rech_billno =p_rech_billno,              
rech_billdate =p_rech_billdate,              
rech_handling_pmt = p_rech_handling_mt ,              
