CREATE DEFINER=`root`@`%` PROCEDURE `spgs_rep_grncash`(mintcompcode int, mintfincode int, minno int)
BEGIN
SELECT
    trnpur_min_header.minh_minno, trnpur_min_header.minh_mindate, trnpur_min_header.minh_type, trnpur_min_header.minh_bill_no, trnpur_min_header.minh_bill_date, trnpur_min_header.minh_value, trnpur_min_header.minh_carrier, trnpur_min_header.minh_remarks, trnpur_min_header.minh_geno, trnpur_min_header.minh_gedate, trnpur_min_header.minh_lrno, trnpur_min_header.minh_lrdate,
    trnpur_min_trailer.mint_comp_code, trnpur_min_trailer.mint_minno, trnpur_min_trailer.mint_fin_code, trnpur_min_trailer.mint_rcvd_qty, trnpur_min_trailer.mint_unit_rate, trnpur_min_trailer.mint_freight, trnpur_min_trailer.mint_value, trnpur_min_trailer.mint_mod_status, trnpur_min_trailer.mint_cr_status, trnpur_min_trailer.mint_slno, trnpur_min_trailer.mint_disamt, trnpur_min_trailer.mint_pfamt, trnpur_min_trailer.mint_sstval, trnpur_min_trailer.mint_educessval, trnpur_min_trailer.mint_vatstatus, trnpur_min_trailer.mint_cgst_amt, trnpur_min_trailer.mint_sgst_amt, trnpur_min_trailer.mint_igst_amt, trnpur_min_trailer.mint_inward_amt, trnpur_min_trailer.mint_tax_freight, trnpur_min_trailer.mint_tax_freight2,
    mas_company.company_name, mas_company.company_add1, mas_company.company_zipcode,
    maspur_supplier_master.sup_refname, maspur_supplier_master.sup_type, maspur_supplier_master.sup_gstin,
    maspur_item_header.item_name,
    mas_uom.uom_short_name,
    mas_hsncode.hsn_code,
    acc_ledger_master_2.led_name,
    acc_ledger_master.led_name,
    acc_ledger_master_1.led_name
FROM
    { oj (((((((((trnpur_min_header  
    INNER JOIN mas_company mas_company ON
        trnpur_min_header.minh_comp_code = mas_company.company_code)
     INNER JOIN trnpur_min_trailer trnpur_min_trailer ON
        trnpur_min_header.minh_comp_code = trnpur_min_trailer.mint_comp_code AND
    trnpur_min_header.minh_minno = trnpur_min_trailer.mint_minno AND
    trnpur_min_header.minh_mindate = trnpur_min_trailer.mint_mindate AND
    trnpur_min_header.minh_fin_code = trnpur_min_trailer.mint_fin_code AND
    trnpur_min_header.minh_sup_code = trnpur_min_trailer.mint_sup_code)
     INNER JOIN maspur_item_header maspur_item_header ON
        trnpur_min_trailer.mint_item_code = maspur_item_header.item_code)
     INNER JOIN maspur_supplier_master maspur_supplier_master ON
        trnpur_min_trailer.mint_sup_code = maspur_supplier_master.sup_code)
     INNER JOIN maspur_group maspur_group ON
        maspur_item_header.item_group_code = maspur_group.grp_code)
     INNER JOIN mas_hsncode mas_hsncode ON
        maspur_item_header.item_hsncode = mas_hsncode.hsn_sno)
     INNER JOIN mas_uom mas_uom ON
        maspur_item_header.item_uom = mas_uom.uom_code)
     INNER JOIN acc_ledger_master acc_ledger_master ON
        maspur_group.grp_tngst_code = acc_ledger_master.led_code)
     INNER JOIN acc_ledger_master acc_ledger_master_1 ON
        maspur_group.grp_cst_code = acc_ledger_master_1.led_code)
     INNER JOIN acc_ledger_master acc_ledger_master_2 ON
        maspur_group.grp_imp_code = acc_ledger_master_2.led_code}
WHERE
    trnpur_min_trailer.mint_comp_code = mintcompcode AND
    trnpur_min_trailer.mint_fin_code = mintfincode AND
    trnpur_min_trailer.mint_minno = minno
ORDER BY
    trnpur_min_trailer.mint_minno ASC,
    trnpur_min_trailer.mint_slno ASC;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
