CREATE DEFINER=`root`@`%` PROCEDURE `spgs_rep_storeledger`(compcode int, finid int)
BEGIN
SELECT
    tmp_pur_store_ledger.type, tmp_pur_store_ledger.doc_no, tmp_pur_store_ledger.doc_date, tmp_pur_store_ledger.rec_qty, tmp_pur_store_ledger.rec_val, tmp_pur_store_ledger.iss_qty, tmp_pur_store_ledger.iss_val, tmp_pur_store_ledger.iss_cr_status,
    maspur_supplier_master.sup_name,
    mas_cost_center.cost_name,
    tmp_pur_op_value.item_code, tmp_pur_op_value.op_rec_qty, tmp_pur_op_value.op_rec_val, tmp_pur_op_value.op_ret_rec_qty, tmp_pur_op_value.op_ret_rec_val, tmp_pur_op_value.op_adjm_qty, tmp_pur_op_value.op_adjm_val, tmp_pur_op_value.op_iss_qty, tmp_pur_op_value.op_iss_val, tmp_pur_op_value.op_ret_iss_qty, tmp_pur_op_value.op_ret_iss_val, tmp_pur_op_value.op_adjp_qty, tmp_pur_op_value.op_adjp_val,
    maspur_item_header.item_code, maspur_item_header.item_name,
    maspur_item_trailer.item_comp_code, maspur_item_trailer.item_avg_rate, maspur_item_trailer.item_stock, maspur_item_trailer.item_yr_opqty, maspur_item_trailer.item_yr_opval, maspur_item_trailer.item_fin_code,
    mas_uom.uom_short_name,
    maspur_subgroup.subgrp_name  ,
	maspur_group.grp_name 
FROM
    { oj (((((((tmp_pur_store_ledger tmp_pur_store_ledger LEFT OUTER JOIN mas_cost_center mas_cost_center ON
        tmp_pur_store_ledger.iss_party = mas_cost_center.cost_code)
     INNER JOIN tmp_pur_op_value tmp_pur_op_value ON
        tmp_pur_store_ledger.item_code = tmp_pur_op_value.item_code)
     LEFT OUTER JOIN maspur_supplier_master maspur_supplier_master ON
        tmp_pur_store_ledger.party = maspur_supplier_master.sup_code)
     INNER JOIN maspur_item_trailer maspur_item_trailer ON
        tmp_pur_op_value.item_code = maspur_item_trailer.item_code)
     INNER JOIN maspur_item_header maspur_item_header ON
        tmp_pur_op_value.item_code = maspur_item_header.item_code)
     INNER JOIN maspur_subgroup maspur_subgroup ON
        maspur_item_header.item_group_code = maspur_subgroup.subgrp_code)
     INNER JOIN maspur_group maspur_group ON
        maspur_group.grp_code = maspur_subgroup.subgrp_grpcode)     
        
     INNER JOIN mas_uom mas_uom ON
        maspur_item_header.item_uom = mas_uom.uom_code}
WHERE
    maspur_item_trailer.item_comp_code = compcode AND
    maspur_item_trailer.item_fin_code = finid AND
    tmp_pur_op_value.item_code > 0
ORDER BY
    maspur_group.grp_name ASC,
    maspur_subgroup.subgrp_name  ASC,
    maspur_item_header.item_code ASC,
    tmp_pur_store_ledger.doc_date ASC;
END ;;
DELIMITER ;
