CREATE DEFINER=`root`@`%` PROCEDURE `spimp_rep_contract`(
compcode int,    
fincode int,
ordno int
)
BEGIN
select * from (
select a.*,b.*,d.*,f.* ,g.sup_code agent_code,g.sup_name agent_name,h.country_name,
i.port_name orginport,j.port_name arrivalport
 from trnirm_order_header a, trnirm_order_trailer b,  maspur_supplier_master d,   masrm_item_header  f ,
maspur_supplier_master g,
mas_country h,
mas_port i,
mas_port j
where ordh_originport = i.port_code and 
ordh_arrivalport = j.port_code and 
a.ordh_origincountry = h.country_code and
a. ordh_agent_code = g.sup_code and 
 a.ordh_seqno = b.ordt_hdseqno 
and a.ordh_sup_code = d.sup_code and b.ordt_item_code = f.itmh_code and     a.ordh_seqno = b.ordt_hdseqno    
and a.ordh_no = ordno and a.ordh_compcode = compcode and a.ordh_fincode = fincode)a1;
END ;;
DELIMITER ;
