BEGIN
select * from trnirm_invoice_header , trnirm_invoice_trailer ,trnirm_order_header ,masrm_item_header , maspur_supplier_master  where   
invh_sup_code = sup_code and invt_item_code = itmh_code and invh_poseqno = ordh_seqno and invh_seqno = invt_hdseqno and 
