CREATE DEFINER=`root`@`%` PROCEDURE `spirm_del_invqty`(
	p_ordt_hdseqno		int,
    p_invseqno	int
	)
BEGIN
DECLARE NOT_FOUND INT DEFAULT 0;
declare v_itemcode   int;
declare v_invqty	 numeric(14,2);


DECLARE group_cursor CURSOR FOR (select invt_item_code ,invt_qty  from trnirm_invoice_trailer  where invt_hdseqno=p_invseqno );
DECLARE CONTINUE HANDLER FOR NOT FOUND SET NOT_FOUND = 1;
set  NOT_FOUND =0;

set v_invqty=v_invqty;	
OPEN group_cursor;

while(not NOT_FOUND) do


FETCH group_cursor INTO v_itemcode, v_invqty;

if  not NOT_FOUND then
	if  v_invqty>0 
	then
		update trnirm_order_trailer set ordt_inv_qty=ordt_inv_qty-v_invqty, ordt_pen_qty=ordt_pen_qty+v_invqty where ordt_hdseqno=p_ordt_hdseqno and ordt_item_code=v_itemcode;
	end if;
end if; 
end while;
close group_cursor;  
delete from trnirm_invoice_trailer where invt_hdseqno = p_invseqno;

END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
