if  not NOT_FOUND then
  -- set  @test = concat( v_rect_grnqty,'-',@test);
  call spirm_remove_port_qty( p_rect_invseqno,v_rect_item_code, v_rect_billqty,v_rect_millqty,v_rect_grnqty);
