CREATE DEFINER=`root`@`%` PROCEDURE `spirm_del_receipt_qty`(
 p_rect_compcode int,
 p_rect_fincode int,
 p_rect_hdseqno int,
 p_rect_ordhdseqno int,
 p_rect_invseqno int
 )
BEGIN
DECLARE NOT_FOUND INT DEFAULT 0;  
declare v_rect_seqno int; 
declare v_rect_lotno int; 
declare v_rect_item_code int;  
declare v_rect_partyitemcode int;  
declare v_rect_billqty numeric(10,3);  
declare v_rect_grnqty numeric(10,3);  
declare v_rect_costrate numeric(14,5);  
declare v_rect_millqty numeric(13,3);  
declare v_rect_degqty numeric(13,3);  
declare v_rect_totqty numeric(13,3);  

declare cur_receipttrailer 
cursor for   
 select rect_seqno,rect_lotno,rect_item_code,rect_partyitemcode,rect_billqty,rect_grnqty, rect_costrate,rect_millqty,rect_degqty  
 from trnirm_receipt_trailer 
 where rect_hdseqno=p_rect_hdseqno;
 
DECLARE CONTINUE HANDLER FOR NOT FOUND SET NOT_FOUND = 1; 
set  NOT_FOUND =0;
open cur_receipttrailer;  

while(not NOT_FOUND) do

fetch cur_receipttrailer into v_rect_seqno, v_rect_lotno, v_rect_item_code,  
  v_rect_partyitemcode, v_rect_billqty, v_rect_grnqty,  v_rect_costrate,v_rect_millqty,v_rect_degqty; 

if  not NOT_FOUND then
    update trnirm_order_trailer set ordt_rec_qty=ordt_rec_qty - v_rect_grnqty where ordt_hdseqno=p_rect_ordhdseqno and ordt_item_code=v_rect_item_code;	
end if;
  
end while;

close cur_receipttrailer;  

END ;;
DELIMITER ;
