CREATE DEFINER=`root`@`%` PROCEDURE `spirm_del_receipt_trailer`(
 p_rect_compcode int,
 p_rect_fincode int,
 p_rect_hdseqno int,
 p_rect_ordhdseqno int)
BEGIN
DECLARE NOT_FOUND INT DEFAULT 0;  
declare v_rect_seqno int; 
declare v_rect_lotno int; 
declare v_rect_item_code int;  
declare v_rect_partyitemcode int;  
declare v_rect_grnqty numeric(10,3);  
declare v_rect_costrate numeric(14,5);  
declare v_rect_millqty numeric(13,3);  
declare v_rect_degqty numeric(13,3);  
declare v_rect_totqty numeric(13,3);  

declare cur_receipttrailer 
cursor for   
 select rect_seqno,rect_lotno,rect_item_code,rect_partyitemcode,rect_grnqty, rect_costrate,rect_millqty,rect_degqty  
 from trnirm_receipt_trailer 
 where rect_hdseqno=p_rect_hdseqno;
 
DECLARE CONTINUE HANDLER FOR NOT FOUND SET NOT_FOUND = 1; 
set  NOT_FOUND =0;
open cur_receipttrailer;  

while(not NOT_FOUND) do

fetch cur_receipttrailer into v_rect_seqno, v_rect_lotno, v_rect_item_code,  
  v_rect_partyitemcode, v_rect_grnqty,  v_rect_costrate,v_rect_millqty,v_rect_degqty; 

if  not NOT_FOUND then
     
--     if v_rect_item_code=v_rect_partyitemcode  
--     then  
--         set v_rect_totqty=v_rect_grnqty+v_rect_degqty;   
--         call spirm_upd_orderreceiptdets( p_rect_ordhdseqno,v_rect_item_code,v_rect_totqty,1);  
--     end if;  
     
     set v_rect_grnqty = (v_rect_grnqty * (-1));  
           
     call sprm_insupd_stockdetails(p_rect_compcode,v_rect_lotno, v_rect_item_code,
            v_rect_grnqty);  
              
	  call sprm_upd_itemtrailer_avgrate( p_rect_compcode,p_rect_fincode,  
                      v_rect_item_code,v_rect_grnqty,v_rect_costrate,1);  

end if;
  
end while;
 
close cur_receipttrailer;  
 delete from trnirm_receipt_trailer where rect_hdseqno=p_rect_hdseqno;   

END ;;
