CREATE DEFINER=`root`@`%` PROCEDURE `spirm_ins_receipt_header`(      
p_rech_seqno  int,      
p_rech_compcode int,      
p_rech_fincode  int,      
p_rech_no  int,      
p_rech_sup_code int,      
p_rech_ordhdseqno  int,      
p_rech_invhdseqno int,      
p_rech_agent_code int,      
p_rech_date  datetime(3),      
p_rech_wtcardno int,      
p_rech_area_code smallint,  
p_rech_truck  varchar(20),        
p_rech_itemvalue numeric(14,2),      
p_rech_freight  numeric(14,2),      
p_rech_roundingoff numeric(3,2),      
p_rech_totalamount numeric(14,2),      
p_rech_billno  varchar(20),      
p_rech_billdate  datetime(3),      
p_rech_billvalue  numeric(14,2),      
p_rech_customduty numeric(14,2),      
p_rech_clearingchrg numeric(14,2),      
p_rech_usr_code int,      
p_rech_entry_date datetime(3),      
p_rech_cgst numeric(10,2),      
p_rech_sgst numeric(10,2),      
p_rech_igst numeric(10,2),      
p_rech_geno varchar(20),        
p_rech_gedate datetime(3))
begin      
insert into trnirm_receipt_header       
(
rech_seqno, rech_compcode, rech_fincode, rech_no, rech_sup_code, rech_ordhdseqno, rech_invhdseqno,
 rech_agent_code, rech_date, rech_wtcardno, rech_area_code, rech_truckno, rech_itemvalue, rech_freight, 
 rech_roundingoff, rech_totalamount, rech_billno, rech_billdate, rech_billvalue, rech_customduty, 
 rech_clearingchrg, rech_vouno, rech_acctflag, rech_accdate, rech_status, rech_usr_code, rech_entry_date, 
 rech_cgst, rech_sgst, rech_igst, rech_geno, rech_gedate
)      
values      
(p_rech_seqno,p_rech_compcode,p_rech_fincode,p_rech_no,p_rech_sup_code,p_rech_ordhdseqno, p_rech_invhdseqno,     
p_rech_agent_code,p_rech_date,p_rech_wtcardno,p_rech_area_code,p_rech_truck,p_rech_itemvalue,p_rech_freight,
p_rech_roundingoff,p_rech_totalamount,p_rech_billno, p_rech_billdate,p_rech_billvalue ,p_rech_customduty,
p_rech_clearingchrg, '','N',p_rech_entry_date,'',p_rech_usr_code,p_rech_entry_date,
p_rech_cgst,p_rech_sgst,p_rech_igst,p_rech_geno ,p_rech_gedate);

END ;;
