CREATE DEFINER=`root`@`%` PROCEDURE `spirm_remove_port_qty`(
 invseqno int,
 itemcode int,
 portwt decimal(10,3),
 millwt decimal(10,3),
 grnwt decimal(10,3)
 )
BEGIN
    update trnirm_invoice_trailer set invt_portqty=invt_portqty - portwt ,  invt_millqty=invt_millqty - millwt ,  invt_recqty=invt_recqty - grnwt  where invt_hdseqno=invseqno and invt_item_code=itemcode;    
   END ;;
