CREATE DEFINER=`root`@`%` PROCEDURE `spirm_sel_recheddet`( 
	p_rech_seqno int)
begin 
	select a.*,s.sup_type, ordh_no,
    b.ordh_date,invh_invoiceno,invh_invoicerefno,invh_clearing,invh_clearing,invh_agent,
