CREATE DEFINER=`root`@`%` PROCEDURE `spirm_upd_orderreceiptdets`(
	p_ordt_hdseqno		int,
	p_rect_item_code	int,
	p_rect_qty		numeric(13,3),
	p_trantype		tinyint unsigned,
    p_invseqno	int
    )
BEGIN
DECLARE NOT_FOUND INT DEFAULT 0;
declare v_penqty 		numeric(14,2);
declare v_penrec_qty		numeric(14,2);
declare	v_rec_qty		numeric(13,3);
declare	v_ord_qty		numeric(13,3);
declare v_pen_qty		numeric(13,3);
declare v_can_qty		numeric(13,3);

DECLARE group_cursor CURSOR FOR (select ordt_rec_qty,ordt_qty,ordt_pen_qty,ordt_can_qty  from trnirm_order_trailer  where ordt_hdseqno=p_ordt_hdseqno and ordt_item_code=p_rect_item_code );
DECLARE CONTINUE HANDLER FOR NOT FOUND SET NOT_FOUND = 1;
set v_penqty=p_rect_qty;	

OPEN group_cursor;
FETCH group_cursor INTO v_rec_qty,v_ord_qty,v_pen_qty,v_can_qty;

while NOT_FOUND=0 
do
	if  v_penqty>0 
	then
	if p_trantype=0 
	then
		set v_penrec_qty=v_pen_qty;
		if v_penrec_qty >= v_penqty 
		then
			update trnirm_order_trailer set ordt_rec_qty=ordt_rec_qty+v_penqty where ordt_hdseqno=p_ordt_hdseqno and ordt_item_code=p_rect_item_code;
			/*update trnrm_indent_trailer set indt_grnqty=indt_grnqty+v_penqty where  indt_itmh_code=p_rect_item_code;*/
			set v_penqty=0;
		else
			set v_penqty=v_penqty-v_penrec_qty;
			update trnirm_order_trailer set ordt_rec_qty=ordt_rec_qty+v_penrec_qty where ordt_hdseqno=p_ordt_hdseqno and ordt_item_code=p_rect_item_code;
			/*update trnrm_indent_trailer set indt_grnqty=indt_grnqty+v_penrec_qty where indt_hdseqno=v_indh_seqno and indt_itmh_code=p_rect_item_code;*/
		end if;
	else
		set v_penrec_qty=v_rec_qty;
		if v_penrec_qty >= v_penqty 
		then
			update trnirm_order_trailer set ordt_rec_qty=ordt_rec_qty-v_penqty where ordt_hdseqno=p_ordt_hdseqno and ordt_item_code=p_rect_item_code;
			/*update trnrm_indent_trailer set indt_grnqty=indt_grnqty-v_penqty where indt_hdseqno=v_indh_seqno and indt_itmh_code=p_rect_item_code;*/
			set v_penqty=0;
		else
			set v_penqty=v_penqty-v_penrec_qty;
			update trnirm_order_trailer set ordt_rec_qty=ordt_rec_qty-v_penrec_qty where ordt_hdseqno=p_ordt_hdseqno and ordt_item_code=p_rect_item_code;
			/*update trnrm_indent_trailer set indt_grnqty=indt_grnqty-v_penrec_qty where indt_hdseqno=v_indh_seqno and indt_itmh_code=p_rect_item_code;*/
		end if;
	end if; 	

	end if;

	/* SQLINES DEMO *** ending qty */

	update trnirm_order_trailer set ordt_pen_qty=case when ordt_qty-(ordt_rec_qty+ordt_can_qty)>0 then ordt_qty-(ordt_rec_qty+ordt_can_qty) else 0 end  where ordt_hdseqno=p_ordt_hdseqno     and ordt_item_code=p_rect_item_code;


    
  
  
	/* SQLINES DEMO *** ailer status */

	update trnirm_order_trailer set ordt_status='O' where ordt_qty=ordt_pen_qty and ordt_hdseqno=p_ordt_hdseqno and ordt_item_code=p_rect_item_code;
	update trnirm_order_trailer set ordt_status='P' where ordt_qty<>ordt_pen_qty and ordt_hdseqno=p_ordt_hdseqno and ordt_item_code=p_rect_item_code;
	update trnirm_order_trailer set ordt_status='C' where ordt_pen_qty=0 and ordt_hdseqno=p_ordt_hdseqno and  ordt_item_code=p_rect_item_code;
	
	/*
	update trnrm_indent_trailer set indt_status='C' where indt_qty<=indt_grnqty and indt_hdseqno=v_indh_seqno and indt_itmh_code=p_rect_item_code;
	update trnrm_indent_trailer set indt_status='P' where indt_qty>indt_grnqty and indt_hdseqno=v_indh_seqno and indt_itmh_code=p_rect_item_code; 
	

	update trnrm_indent_header set indh_status='P' where indh_seqno=indh_seqno and indh_seqno in(
	select indt_hdseqno from trnrm_indent_trailer where indt_hdseqno=v_indh_seqno and indt_status='P');	

	update trnrm_indent_header set indh_status='C' where indh_seqno=indh_seqno and indh_seqno not in(
	select indt_hdseqno from trnrm_indent_trailer where indt_hdseqno=v_indh_seqno and indt_status in('P','O'));	
*/
	FETCH group_cursor INTO v_rec_qty,v_ord_qty,v_pen_qty,v_can_qty;
	if NOT_FOUND<>0 and v_penqty>0 and p_trantype=0
	then
		update trnirm_order_trailer set ordt_rec_qty=ordt_rec_qty+v_penqty where ordt_hdseqno=p_ordt_hdseqno and ordt_item_code=p_rect_item_code;
	end if;

end while; 

close group_cursor;
-- CHECK 14082022

 if p_trantype =0 then  
  update trnirm_invoice_trailer set invt_recqty=invt_recqty+p_rect_qty where invt_hdseqno=p_invseqno and invt_item_code=p_rect_item_code;    
 else  
  update trnirm_invoice_trailer set invt_recqty=invt_recqty-p_rect_qty where invt_hdseqno=p_invseqno and invt_item_code=p_rect_item_code;    
 end if; 
update trnirm_order_header set ordh_status='P' where ordh_seqno=p_ordt_hdseqno and ordh_seqno in(
select ordt_hdseqno from trnirm_order_trailer where ordt_hdseqno=p_ordt_hdseqno and ordt_status='P');

update trnirm_order_header set ordh_status='C' where ordh_seqno=p_ordt_hdseqno and ordh_seqno not in(
select ordt_hdseqno from trnirm_order_trailer where ordt_hdseqno=p_ordt_hdseqno and ordt_status in('P','O'));

END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `spirm_upd_receipt_header` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`%` PROCEDURE `spirm_upd_receipt_header`(  
p_rech_seqno int,            
p_rech_date datetime(3),  
p_rech_wtcardno  int,            
p_rech_area_code smallint,   
p_rech_truckno varchar(20),
p_rech_freighttype varchar(1),          
p_rech_itemvalue numeric(12,2),     
p_rech_sgst_per numeric(5,2),     
p_rech_sgst_amt numeric(12,2),         
p_rech_cgst_per numeric(5,2),     
p_rech_cgst_amt numeric(12,2),          
p_rech_igst_per numeric(5,2),     
p_rech_igst_amt numeric(12,2),          
p_rech_tcs_per numeric(5,2),     
p_rech_tcs_amt numeric(12,2),
p_rech_freight numeric(12,2),          
p_rech_otheramt numeric(12,2),  
p_rech_roundingoff numeric(3,2),        
p_rech_totalamount numeric(12,2),  
p_rech_billno varchar(20),          
p_rech_billdate datetime(3),          
p_rech_billvalue numeric(14,2) ,
p_rech_geno int,
p_rech_gedate  datetime       

)
begin            
update trnirm_receipt_header set            
rech_date =p_rech_date,            
rech_area_code =p_rech_area_code,    
rech_wtcardno  = p_rech_wtcardno, 
rech_truckno = p_rech_truckno,      
rech_itemvalue =p_rech_itemvalue,            
-- rech_tcs_per =p_rech_tcs_per,            
-- rech_tcs_amt =p_rech_tcs_amt,
-- rech_sgst_per =p_rech_sgst_per,       
 -- rech_sgst_amt =p_rech_sgst_amt,            
 -- rech_cgst_per =p_rech_cgst_per,       
 -- rech_cgst_amt =p_rech_cgst_amt,            
 -- rech_igst_per =p_rech_igst_per,       
 -- rech_igst_amt =p_rech_igst_amt,  
 rech_freight =p_rech_freight,            
  rech_roundingoff =p_rech_roundingoff,            
  rech_totalamount =p_rech_totalamount,            
  rech_billno =p_rech_billno,            
  rech_billdate =p_rech_billdate,            
  rech_billvalue=p_rech_billvalue,            
 -- rech_otheramt =  p_rech_otheramt,  
 rech_geno = p_rech_geno,rech_gedate = p_rech_gedate               
where rech_seqno = p_rech_seqno and rech_status='' and rech_acctflag='N';
END ;;
