CREATE DEFINER=`root`@`%` PROCEDURE `spirm_upd_receipt_qty`(
	p_ordt_hdseqno		int,
	p_rect_item_code	int,
	p_rect_qty		numeric(13,3),
    p_port_qty		numeric(13,3),
	p_mill_qty		numeric(13,3),
    p_invseqno	int
    )
BEGIN
	update trnirm_order_trailer set ordt_rec_qty=ordt_rec_qty+p_rect_qty where ordt_hdseqno=p_ordt_hdseqno and ordt_item_code=p_rect_item_code;
	update trnirm_invoice_trailer set invt_portqty=invt_portqty+p_port_qty , invt_millqty=invt_millqty+p_mill_qty , invt_recqty=invt_recqty+p_rect_qty  where invt_hdseqno=p_invseqno and invt_item_code=p_rect_item_code;    
 END ;;
