/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`%` PROCEDURE `spprd_rep_gsmwise_prodn`(compcode int,fincode int,fromdate date, todate date)
BEGIN
select prd_date, DATE_FORMAT(prd_date, '%d-%m-%Y') as proddate, sum(gsm100) gsm100  , sum(gsm101_120) gsm101_120, sum(gsm121_140) gsm121_140, sum(gsm141_150) gsm141_150, sum(gsm151_180) gsm151_180, sum(gsm181_200) gsm181_200, sum(gsm201_220) gsm201_220, sum(gsm221_240) gsm221_240, sum(gsm241_250) gsm241_250, sum(gsm251_270) gsm251_270, sum(gsm271_280) gsm271_280, sum(gsm281_300) gsm281_300, sum(gsm301_320) gsm301_320, sum(abovegsm_320) abovegsm_320 , sum(rollwt) dayprodn
from (
select prd_date , case when var_gsm <=100 then rollwt else 0 end gsm100, 
case when var_gsm >100 and  var_gsm <=120  then rollwt else 0 end gsm101_120,
case when var_gsm >121 and  var_gsm <=140  then rollwt else 0 end gsm121_140,
case when var_gsm >141 and  var_gsm <=150  then rollwt else 0 end gsm141_150,
case when var_gsm >151 and  var_gsm <=180  then rollwt else 0 end gsm151_180,
case when var_gsm >181 and  var_gsm <=200  then rollwt else 0 end gsm181_200,
case when var_gsm >201 and  var_gsm <=220  then rollwt else 0 end gsm201_220,
case when var_gsm >221 and  var_gsm <=240  then rollwt else 0 end gsm221_240,
case when var_gsm >241 and  var_gsm <=250  then rollwt else 0 end gsm241_250,
case when var_gsm >251 and  var_gsm <=270  then rollwt else 0 end gsm251_270,
case when var_gsm >271 and  var_gsm <=280  then rollwt else 0 end gsm271_280,
case when var_gsm >281 and  var_gsm <=300  then rollwt else 0 end gsm281_300,
case when var_gsm >301 and  var_gsm <=320  then rollwt else 0 end gsm301_320,
case when var_gsm >320 then rollwt else 0 end abovegsm_320,
rollwt
from(select prd_date , var_gsm,sum(prd_rollwt) rollwt from trn_dayprod_roll_details , masprd_variety where prd_variety = var_groupcode  and prd_date between fromdate and todate  and  prd_compcode = compcode  and prd_fincode = fincode  group by prd_date , var_gsm) a1
) ab1 group by prd_date ORDER by prd_date ;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
