CREATE DEFINER=`root`@`%` PROCEDURE `spprd_rep_monthwise_prodn`(compcode int,fincode int,fromdate date, todate date)
BEGIN
select UPPER(monthname(prdh_date)) as rmonth ,sum(prdh_prodn) as mcprodwt from 
trn_dayprod_header where prdh_compcode = compcode and prdh_fincode = fincode and prdh_date >= fromdate and prdh_date <= todate  group by UPPER(monthname(prdh_date)); 
END ;;
