CREATE DEFINER=`root`@`%` PROCEDURE `spprod_chemical_consumption`(compcode int,fincode int,startdate datetime, enddate datetime)
BEGIN
select * , DATE_FORMAT( iss_date, '%d-%m-%Y') as issdate from trn_dayprod_chemicals_cons join maspur_item_header on iss_item_code = item_code 
join mas_uom on  item_uom = uom_code
where iss_comp_code = compcode and iss_fin_code = fincode and iss_date between startdate  and enddate order by iss_slno;
END ;;
