 prdhid int, prdhcompcode int , prdhfincode int, prdhdate date , prdhshift varchar(1), 
 prdhspvrcode int,prdhoperator int, prdhppno int,  prdhavlmins int,
 prdhrunmins  int, prdhdownmins int, prdhprodn decimal(6,3),prdhopenpulp decimal(6,3), 
 prdhclosepulp decimal(6,3), prdhopenbroke decimal(6,3), prdhclosebroke decimal(6,3), prdhpower decimal(6,3), prdhsteam decimal(6,3)
)
BEGIN
 delete from trn_dayprod_roll_details where prd_seqno = prdhid and prd_compcode = prdhcompcode  and  prd_fincode = prdhfincode  and  prd_date = prdhdate and  prd_shift = prdhshift; 
  
 -- delete from trn_dayprod_roll_variety_details where prdv_seqno = prdhid  and  prdv_fincode = prdhfincode; 
 
 delete from trn_dayprod_downtime where prds_id = prdhid  and  prds_fincode = prdhfincode and prds_compcode = prdhcompcode; 
 
 update trn_dayprod_header  set prdh_spvrcode = prdhspvrcode ,  prdh_operator = prdhoperator ,  prdh_ppno = prdhppno ,   prdh_avlmins = prdhavlmins,  prdh_runmins =  prdhrunmins,  prdh_downmins = prdhdownmins,  prdh_prodn = prdhprodn  where prdh_id = prdhid and prdh_compcode = prdhcompcode and  prdh_fincode = prdhfincode and prdh_date = prdhdate and prdh_shift = prdhshift;
  
END ;;
