DELIMITER ;;
CREATE DEFINER=`root`@`%` PROCEDURE `sppur_debit_notelist`(compcode int,fincode int, fromdate date,todate date,vtype varchar(3))
BEGIN
select voudate,DATE_FORMAT(voudate, '%d-%m-%Y') as voucherdate,dntype, voutype, vouno,  cust_name, billno, DATE_FORMAT(billdate, '%d-%m-%Y') as billdate, debitamt ,seqno from
(
select dntype, voutype, vouno, voudate, cust_name, billno, billdate, debitamt ,0 seqno from
(select 'stores' as dntype,left(pur_vouno,3) voutype, pur_vouno vouno,pur_date voudate,cust_name,pur_billno billno,pur_billdate billdate,pur_totalamount  debitamt from str_debit_note , massal_customer  where pur_partycode = cust_code and pur_compcode = compcode and pur_finid = fincode and pur_date between fromdate and todate )
st group by dntype, voutype, vouno, voudate, cust_name, billno, billdate, debitamt

union all

select dntype, voutype, vouno, voudate, cust_name, billno, billdate, debitamt,seqno from 
(select 'stores-Ret' as dntype,left(debh_vouno,3) voutype, debh_vouno vouno,debh_date voudate,cust_name,debh_billno billno,debh_billdate billdate,debh_netamount  debitamt , debh_no seqno    from trnpur_grn_ret_header , massal_customer  where debh_supcode = cust_code and debh_comp_code = compcode and debh_fin_code = fincode and debh_date between fromdate and todate)
str group by dntype, voutype, vouno, voudate, cust_name, billno, billdate, debitamt,seqno

union all

select dntype, voutype, vouno, voudate, cust_name, billno, billdate, debitamt  ,0 seqno from
(select 'fuel' as dntype,left(qc_fuel_debitnote_no,3) voutype, qc_fuel_debitnote_no vouno,qc_fuel_debitnote_date voudate,cust_name,qc_fuel_billno billno,qc_fuel_billdate billdate,qc_fuel_debitamount  debitamt  from trn_qc_fuel_inspection , massal_customer where qc_fuel_supcode = cust_code and qc_fuel_compcode = compcode and qc_fuel_fincode = fincode and qc_fuel_dn_raised = 'Y'  and qc_fuel_debitnote_date between fromdate and todate 
)
fu group by dntype, voutype, vouno, voudate, cust_name, billno, billdate, debitamt

union all
select dntype, voutype, vouno, voudate, cust_name, billno, billdate, debitamt  ,0 seqno  from
(select 'wp' as dntype,left(qc_rm_debitnote_no,3) voutype, qc_rm_debitnote_no vouno,qc_rm_debitnote_date voudate,cust_name,qc_rm_billno billno,qc_rm_billdate billdate,qc_rm_debitamount  debitamt  from trn_qc_rm_inspection , massal_customer where qc_rm_supcode = cust_code and qc_rm_compcode = compcode and qc_rm_fincode = fincode and qc_rm_dn_raised = 'Y'   and qc_rm_debitnote_date between fromdate and todate)
wp group by dntype, voutype, vouno, voudate, cust_name, billno, billdate, debitamt
) final where voutype = vtype  order by voudate,vouno,seqno;

END ;;
DELIMITER ;
