CREATE DEFINER=`root`@`%` PROCEDURE `sppur_dept_indent`( comp_code  numeric(3,0),  fin_code  int ,dept int )
BEGIN
if dept = 0  then
select mc.company_id 'Company',dp.dept_name,ind_no 'Indent',ih.item_name 'ItemDescription',ind_qty 'Quantity',ind_value 'Value',ind_due_date 'DueDate',    
 ind_comp_code,ind_fin_code,ind_item_code ,'N' as ApproveYN from trnpur_indent,mas_company mc,maspur_item_header ih,mas_dept dp     
 where ind_hod_auth = 'N' and ind_comp_code = mc.company_code and ind_item_code = ih.item_code and ind_dept_code = dp.dept_code and ind_cancel_status <> 'C'  and ind_comp_code = comp_code and ind_fin_code = fin_code   
order by ind_no,item_name;
 else
 select mc.company_id 'Company',dp.dept_name,ind_no 'Indent',ih.item_name 'ItemDescription',ind_qty 'Quantity',ind_value 'Value',ind_due_date 'DueDate',    
 ind_comp_code,ind_fin_code,ind_item_code ,'N' as ApproveYN from trnpur_indent,mas_company mc,maspur_item_header ih,mas_dept dp     
 where ind_hod_auth = 'N' and ind_comp_code = mc.company_code and ind_item_code = ih.item_code and ind_dept_code = dp.dept_code and ind_cancel_status <> 'C'  and ind_comp_code = comp_code and ind_fin_code = fin_code   
 and ind_dept_code = dept  order by ind_no,item_name;  
 end if; 
END ;;
