CREATE DEFINER=`root`@`%` PROCEDURE `sppur_frm_voucher`(compcode int,finid int,vouno int,fromdate date,todate date, bank varchar(3) )
BEGIN
if  vouno >0 then
   select  * from trn_frm where f_compcode= compcode and f_fincode= finid  and f_frm_no = vouno order by f_sno;
else
select  * from trn_frm where f_compcode= compcode and f_fincode= finid and f_bank = bank and f_frm_date between fromdate and todate order by f_frm_no,f_sno;
end if;
END ;;
