BEGIN
select * from trnpur_min_header, trnpur_min_trailer , maspur_item_header , mas_uom  , massal_customer where minh_sup_code = cust_code and mint_item_code = item_code and uom_code = item_uom and
minh_comp_code = mint_comp_code and minh_fin_code = mint_fin_code  and minh_minno = mint_minno and 
