CREATE DEFINER=`root`@`%` PROCEDURE `sppur_ind_details_items`( companycode numeric (3,0), fincode  int, indno numeric(6,0))
BEGIN
 select  ind_item_code as ptr_item_code ,item_name ,ind_date         
 from      trnpur_indent , maspur_item_header   
 where  
           ind_hod_auth = 'Y' and          
            ind_cancel_status <> 'C' and          
           (ind_qty - ind_rec_qty)  > 0 and          
           ind_comp_code = companycode  and          
           ind_fin_code = fincode and                     
           ind_no = indno and           
           ind_item_code = item_code 
 group by  ind_item_code,item_name ,ind_date order by  item_name;  
END ;;
