CREATE DEFINER=`root`@`%` PROCEDURE `sppur_ins_item_trailer`( compcode int, itemcode int)
BEGIN
   DECLARE done1 INT DEFAULT FALSE;
    DECLARE vfincode INT;
    DECLARE vfinyear INT;
    declare finyear cursor for select fin_code from mas_finyear where fin_code >=24;
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET done1 = TRUE;
	OPEN finyear;
       ins_loop1: LOOP
		FETCH finyear INTO vfincode;
		IF done1 THEN
        	  LEAVE ins_loop1;
		END IF;
        insert into maspur_item_trailer values(compcode, vfincode,itemcode, 0, 0, 0, 0, 0, NULL , NULL,0);
	 END loop;
     CLOSE finyear;
END ;;
DELIMITER ;
