CREATE DEFINER=`root`@`%` PROCEDURE `sppur_ins_item_trailer_newfinyear`( compcode int)
BEGIN
   DECLARE done1 INT DEFAULT FALSE;
    DECLARE icode INT;
    DECLARE vfinyear INT;
    declare itemcode cursor for select item_code from maspur_item_header;
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET done1 = TRUE;
	OPEN itemcode;
       ins_loop1: LOOP
		FETCH itemcode INTO icode;
		IF done1 THEN
        	  LEAVE ins_loop1;
		END IF;
        insert into maspur_item_trailer values(compcode, 23,icode, 0, 0, 0, 0, 0, 0, NULL , NULL);
	 END loop;
     CLOSE itemcode;
END ;;
