CREATE DEFINER=`root`@`%` PROCEDURE `sppur_ins_order_amendment`(phdcompcode int,  phdfincode int ,   phdpono varchar(10),   
  amndno int,   amnddate datetime )
BEGIN

DECLARE Not_found INT DEFAULT 0;
declare indno	int;
declare ifincode int;
declare icode	int;
declare	qty	numeric(13,3);

DECLARE group_cursor CURSOR FOR (select ptr_ind_fin_code,ptr_ind_no,ptr_item_code,ptr_ord_qty 
from trnpur_purchase_trailer where ptr_comp_code=phdcompcode and ptr_fin_code=phdfincode and ptr_pono=phdpono);
DECLARE CONTINUE HANDLER FOR NOT FOUND 
SET Not_found = 1;

OPEN group_cursor;
cursor_loop:LOOP
 FETCH group_cursor INTO ifincode,indno,icode,qty;
 IF Not_found=1 THEN
 LEAVE cursor_loop;
 CLOSE group_cursor;
 END IF;
 		update trnpur_indent set ind_po_qty = ind_po_qty - qty where ind_comp_code =phdcompcode 
		and ind_fin_code =ifincode and ind_no =indno and ind_item_code=icode;
END LOOP cursor_loop;
CLOSE group_cursor;
SET Not_found=0;

insert into trnpur_amendment_header  select amndno,amnddate,phd_comp_code, phd_pono, phd_fin_code, phd_podate, phd_dept, phd_sup_code, phd_credit_days, phd_transport, phd_pay_terms, phd_dely_point, phd_other_ref, phd_spl_instruction, phd_advance, phd_roundoff, phd_total, phd_amnd_status, phd_cancel_status, phd_cancel_reason, phd_tol, phd_ent_date, phd_party_refno, phd_party_refdate, phd_prepared_by, phd_deliverydate, phd_freight, phd_round_needed
from trnpur_purchase_header where phd_comp_code = phdcompcode  
and phd_fin_code = phdfincode and phd_pono = phdpono  ; 
  
insert into trnpur_amendment_trailer select amndno,amnddate,
ptr_comp_code, ptr_fin_code, ptr_pono, ptr_podate, ptr_item_code, ptr_slno, ptr_ind_fin_code, ptr_ind_no, ptr_unit_rate, ptr_ord_qty, ptr_rec_qty, ptr_discount, ptr_pf_per, ptr_freight_amt, ptr_oth_amt, ptr_disval, ptr_pfval, ptr_cgst_per, ptr_cgst_amt, ptr_sgst_per, ptr_sgst_amt, ptr_igst_per, ptr_igst_amt, ptr_tcs_per, ptr_tcs_amt, ptr_frt2, ptr_rebate, ptr_remarks, ptr_close_status, ptr_status, ptr_purgroup
from trnpur_purchase_trailer where ptr_comp_code =phdcompcode   
and ptr_fin_code = phdfincode and ptr_pono =  phdpono ;

delete from trnpur_purchase_trailer where ptr_comp_code =phdcompcode   
and ptr_fin_code = phdfincode and ptr_pono =  phdpono;

delete from trnpur_purchase_header where phd_comp_code = phdcompcode  
and phd_fin_code = phdfincode and phd_pono = phdpono; 

END ;;
DELIMITER ;
