CREATE DEFINER=`root`@`%` PROCEDURE `sppur_pending_indent`( comp_code numeric(3,0),fin_code int)
BEGIN
 select     ind_no ,ind_fin_code    
 from        trnpur_indent     
 where     ind_comp_code = comp_code and    
           ind_fin_code = fin_code and    
                 ind_qty > ind_rec_qty and    
                ind_hod_auth = 'Y'  and  -- ind_po_qty = 0 and  
    ind_cancel_status <> 'C' and ind_fin_code >=22    
 group by ind_no,ind_fin_code    
 order by ind_no,ind_fin_code;   
END ;;
