CREATE DEFINER=`root`@`%` PROCEDURE `sppur_pending_po`(company_code numeric(3,0),fin_code int,sup_code numeric(6,0) ,grnstatus varchar(10))
BEGIN
if grnstatus = "Add" then
	select t.ptr_pono as ind_no,t.ptr_fin_code as ind_fin_code
	from 
			 trnpur_purchase_trailer t,trnpur_purchase_header h
	where 
			 ptr_comp_code = phd_comp_code and ptr_fin_code = phd_fin_code and
			 ptr_pono = h.phd_pono and
			 phd_cancel_status = '' and ptr_close_status <> 'C' and (ptr_ord_qty-ptr_rec_qty)> 0 and
			 phd_sup_code = sup_code  and
			 ptr_comp_code = company_code  
	and      ptr_fin_code = fin_code 
	group by t.ptr_pono,t.ptr_fin_code
	order by ptr_pono,t.ptr_fin_code;
else
	select t.ptr_pono as ind_no,t.ptr_fin_code as ind_fin_code
	from 
			 trnpur_purchase_trailer t,trnpur_purchase_header h
	where 
			 ptr_comp_code = phd_comp_code and ptr_fin_code = phd_fin_code and
			 ptr_pono = h.phd_pono and			
			 phd_sup_code = sup_code  and
			 ptr_comp_code = company_code  
	and      ptr_fin_code = fin_code 
	group by t.ptr_pono,t.ptr_fin_code
	order by ptr_pono,t.ptr_fin_code;
end if; 
END ;;
