CREATE DEFINER=`root`@`%` PROCEDURE `sppur_rep_address`(ledtype varchar(1),scode int)
BEGIN
if scode = 0 then
    select * from massal_customer , acc_group_master,mas_state where cust_state = state_code  and  cust_acc_group = grp_code and cust_type = ledtype;
else
   select * from massal_customer , acc_group_master,mas_state where cust_state = state_code  and  cust_acc_group = grp_code and cust_code = scode;
end if;    
END ;;
