CREATE DEFINER=`root`@`%` PROCEDURE `sppur_rep_group_po_pending`(compcode int ,fincode int , fromdate date,todate date ,grpcode int ,grpname varchar(100)  )
BEGIN
select item_code,item_name,uom_short_name,cast(sum(pend_qty) as decimal(10,3))  pend_qty ,
cast(sum(pend_value) as decimal(10,2))  pend_value ,
cast( sum(pend_value)/sum(pend_qty)  as decimal(10,5))  rate  from ( 
  select item_code,item_name,uom_short_name, sum(ptr_ord_qty)-sum(ptr_rec_qty) 
 as pend_qty, sum(ptr_ord_qty)*ptr_unit_rate as pend_value from trnpur_purchase_header, trnpur_purchase_trailer , 
 maspur_item_header ,  mas_uom where uom_code =  item_uom and  phd_comp_code = ptr_comp_code and  phd_fin_code = ptr_fin_code 
 and phd_pono = ptr_pono and  ptr_item_code = item_code and phd_comp_code = compcode and phd_fin_code = fincode and 
 ptr_ord_qty - ptr_rec_qty  > 0  and ptr_close_status = '' and item_group_code in 
 (select subgrp_code from maspur_subgroup  where subgrp_grpcode = grpcode)  and 
 phd_podate between fromdate and todate  group by item_code,item_name,uom_short_name ,ptr_unit_rate 
 ) a1 group by item_code,item_name,uom_short_name  order by item_name;
 /*
select item_code,item_name,uom_short_name,pend_qty,cast(pend_value as decimal(10,2)) pend_value,
cast(pend_value/pend_qty as decimal(10,2) )as rate from (select item_code,item_name,uom_short_name, 
sum(ptr_ord_qty)-sum(ptr_rec_qty)  as pend_qty, sum(ptr_ord_qty)*ptr_unit_rate as pend_value from 
trnpur_purchase_header, trnpur_purchase_trailer , maspur_item_header , mas_uom where uom_code =  item_uom 
and  phd_comp_code = ptr_comp_code and  phd_fin_code = ptr_fin_code and phd_pono = ptr_pono and
 ptr_item_code = item_code and phd_comp_code = compcode and phd_fin_code = fincode and
 ptr_ord_qty - ptr_rec_qty  > 0  and ptr_close_status = '' and 
 item_group_code in (select subgrp_code from maspur_subgroup  where subgrp_grpcode = grpcode) and phd_podate between fromdate and todate group by item_code,item_name,ptr_unit_rate) a1 order by item_name;
 */
END ;;
DELIMITER ;
