CREATE DEFINER=`root`@`%` PROCEDURE `sppur_rep_indent`(compcode int,finid int,indno int)
BEGIN
SELECT
    trnpur_indent.ind_comp_code, trnpur_indent.ind_no, trnpur_indent.ind_date, trnpur_indent.ind_fin_code, trnpur_indent.ind_type, 
    trnpur_indent.ind_slno, trnpur_indent.ind_qty, trnpur_indent.ind_value, trnpur_indent.ind_po_qty, trnpur_indent.ind_rec_qty, 
    trnpur_indent.ind_due_date, trnpur_indent.ind_remarks, trnpur_indent.ind_machine, trnpur_indent.ind_prepared_by, trnpur_indent.ind_purpose, trnpur_indent.ind_stock,
    maspur_item_header.item_name,
    mas_dept.dept_name,
    mas_section.section_name,
    mas_company.company_name, mas_company.company_add1, mas_company.company_city,
    mas_equipment.equip_name,
    mas_uom.uom_name,
    maspur_item_trailer.item_stock, ind_std_lifetime, ind_act_lifetime, ind_reason
    
FROM
    { oj ((((((trnpur_indent trnpur_indent INNER JOIN mas_dept mas_dept ON
        trnpur_indent.ind_dept_code = mas_dept.dept_code)
     INNER JOIN mas_section mas_section ON
        trnpur_indent.ind_section = mas_section.section_code)
     INNER JOIN mas_company mas_company ON
        trnpur_indent.ind_comp_code = mas_company.company_code)
     INNER JOIN mas_equipment mas_equipment ON
        trnpur_indent.ind_equip = mas_equipment.equip_code)
     INNER JOIN maspur_item_header maspur_item_header ON
        trnpur_indent.ind_item_code = maspur_item_header.item_code)
     INNER JOIN mas_uom mas_uom ON
        maspur_item_header.item_uom = mas_uom.uom_code)
     INNER JOIN maspur_item_trailer maspur_item_trailer ON
        maspur_item_header.item_code = maspur_item_trailer.item_code and
        trnpur_indent.ind_comp_code = maspur_item_trailer.item_comp_code
        and  maspur_item_trailer.item_fin_code = finid
        }
WHERE
    trnpur_indent.ind_comp_code = compcode AND
    trnpur_indent.ind_fin_code = finid AND
    trnpur_indent.ind_no = indno
ORDER BY
    mas_section.section_name ASC,
    mas_equipment.equip_name ASC,
    trnpur_indent.ind_slno ASC;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
