CREATE DEFINER=`root`@`%` PROCEDURE `sppur_rep_partywise_orderstatus`(fromdate date,todate date,compcode int)
BEGIN
SELECT
    trnpur_purchase_header.phd_comp_code, trnpur_purchase_header.phd_pono, trnpur_purchase_header.phd_podate, trnpur_purchase_header.phd_cancel_status,
 trnpur_purchase_trailer.ptr_unit_rate, trnpur_purchase_trailer.ptr_ord_qty, trnpur_purchase_trailer.ptr_rec_qty,  trnpur_purchase_trailer.ptr_discount, trnpur_purchase_trailer.ptr_pf_per, trnpur_purchase_trailer.ptr_freight_amt, trnpur_purchase_trailer.ptr_oth_amt, trnpur_purchase_trailer.ptr_close_status, trnpur_purchase_trailer.ptr_disval, trnpur_purchase_trailer.ptr_pfval,  trnpur_purchase_trailer.ptr_cgst_amt, trnpur_purchase_trailer.ptr_sgst_amt, trnpur_purchase_trailer.ptr_igst_amt,
    maspur_supplier_master.sup_code, maspur_supplier_master.sup_name,
    mas_company.company_name,
    maspur_item_header.item_name,
    mas_uom.uom_short_name
FROM
    { oj ((((trnpur_purchase_header trnpur_purchase_header INNER JOIN maspur_supplier_master maspur_supplier_master ON
        trnpur_purchase_header.phd_sup_code = maspur_supplier_master.sup_code)
     INNER JOIN mas_company mas_company ON
        trnpur_purchase_header.phd_comp_code = mas_company.company_code)
     INNER JOIN trnpur_purchase_trailer trnpur_purchase_trailer ON
        trnpur_purchase_header.phd_comp_code = trnpur_purchase_trailer.ptr_comp_code AND
    trnpur_purchase_header.phd_pono = trnpur_purchase_trailer.ptr_pono AND
    trnpur_purchase_header.phd_podate = trnpur_purchase_trailer.ptr_podate AND
    trnpur_purchase_header.phd_fin_code = trnpur_purchase_trailer.ptr_fin_code)
     INNER JOIN maspur_item_header maspur_item_header ON
        trnpur_purchase_trailer.ptr_item_code = maspur_item_header.item_code)
     INNER JOIN mas_uom mas_uom ON
        maspur_item_header.item_uom = mas_uom.uom_code}
WHERE
    trnpur_purchase_header.phd_podate >= fromdate AND
    trnpur_purchase_header.phd_podate <= todate AND
    trnpur_purchase_header.phd_comp_code = compcode AND
    (trnpur_purchase_header.phd_cancel_status = '' OR
    trnpur_purchase_header.phd_cancel_status <> '' AND
    trnpur_purchase_trailer.ptr_rec_qty > 0) AND
    (trnpur_purchase_trailer.ptr_close_status = '' OR
    trnpur_purchase_trailer.ptr_close_status <> '' AND
    trnpur_purchase_trailer.ptr_rec_qty > 0)
ORDER BY
    maspur_supplier_master.sup_name ASC,
    trnpur_purchase_header.phd_pono ASC;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
