CREATE DEFINER=`root`@`%` PROCEDURE `sppur_rep_pending_indent`(
compcode tinyint,
finid tinyint,
fromdate date,
todate date)
BEGIN
SELECT
    trnpur_indent.ind_comp_code, trnpur_indent.ind_no, trnpur_indent.ind_date, trnpur_indent.ind_fin_code, trnpur_indent.ind_qty, trnpur_indent.ind_value, trnpur_indent.ind_bal_qty,
    mas_company.company_name,
    maspur_item_header.item_name,
    mas_uom.uom_name,
    mas_department.department_name
FROM
    { oj ((((trnpur_indent trnpur_indent INNER JOIN maspur_item_header maspur_item_header ON
        trnpur_indent.ind_item_code = maspur_item_header.item_code)
     INNER JOIN mas_dept mas_dept ON
        trnpur_indent.ind_dept_code = mas_dept.dept_code)
     INNER JOIN mas_company mas_company ON
        trnpur_indent.ind_comp_code = mas_company.company_code)
     INNER JOIN mas_department mas_department ON
        mas_dept.dept_code = mas_department.department_linkcode)
     INNER JOIN mas_uom mas_uom ON
        maspur_item_header.item_uom = mas_uom.uom_code}
WHERE
    trnpur_indent.ind_comp_code = compcode AND
    trnpur_indent.ind_fin_code = finid AND
    trnpur_indent.ind_date >= fromdate AND
    trnpur_indent.ind_date <= todate

ORDER BY
    mas_department.department_name ASC,
    trnpur_indent.ind_no ASC;
END ;;
DELIMITER ;
