DELIMITER ;;
CREATE DEFINER=`root`@`%` PROCEDURE `sppur_rep_podatewise`(compcode int,finid int,fromdate date, todate date)
BEGIN
SELECT
    trnpur_purchase_header.phd_comp_code, trnpur_purchase_header.phd_pono, trnpur_purchase_header.phd_podate, trnpur_purchase_header.phd_fin_code, trnpur_purchase_header.phd_total,
    trnpur_purchase_trailer.ptr_pono, trnpur_purchase_trailer.ptr_podate, trnpur_purchase_trailer.ptr_ord_qty,trnpur_purchase_trailer.ptr_unit_rate,trnpur_purchase_trailer.ptr_cgst_amt,trnpur_purchase_trailer.ptr_sgst_amt,trnpur_purchase_trailer.ptr_igst_amt,trnpur_purchase_trailer.ptr_tcs_amt,
    mas_company.company_name,
    maspur_supplier_master.sup_name,
    trnpur_indent.ind_no, trnpur_indent.ind_qty,
    maspur_item_header.item_name,
    mas_uom.uom_short_name
FROM
    { oj (((((trnpur_purchase_header trnpur_purchase_header INNER JOIN mas_company mas_company ON
        trnpur_purchase_header.phd_comp_code = mas_company.company_code)
     INNER JOIN maspur_supplier_master maspur_supplier_master ON
        trnpur_purchase_header.phd_sup_code = maspur_supplier_master.sup_code)
     INNER JOIN trnpur_purchase_trailer trnpur_purchase_trailer ON
        trnpur_purchase_header.phd_comp_code = trnpur_purchase_trailer.ptr_comp_code AND
    trnpur_purchase_header.phd_pono = trnpur_purchase_trailer.ptr_pono AND
    trnpur_purchase_header.phd_podate = trnpur_purchase_trailer.ptr_podate AND
    trnpur_purchase_header.phd_fin_code = trnpur_purchase_trailer.ptr_fin_code)
     INNER JOIN trnpur_indent trnpur_indent ON
    trnpur_purchase_trailer.ptr_ind_no = trnpur_indent.ind_no AND
    trnpur_purchase_trailer.ptr_ind_fin_code = trnpur_indent.ind_fin_code AND
    trnpur_purchase_trailer.ptr_item_code = trnpur_indent.ind_item_code)
     INNER JOIN maspur_item_header maspur_item_header ON
        trnpur_indent.ind_item_code = maspur_item_header.item_code)
     INNER JOIN mas_uom mas_uom ON
        maspur_item_header.item_uom = mas_uom.uom_code}
WHERE
    trnpur_purchase_header.phd_comp_code = compcode AND
    trnpur_purchase_header.phd_fin_code = finid AND
    trnpur_purchase_header.phd_podate >= fromdate AND
    trnpur_purchase_header.phd_podate <= todate
ORDER BY
    trnpur_purchase_header.phd_pono ASC;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
