CREATE DEFINER=`root`@`%` PROCEDURE `sppur_rep_pohistory`(compcode int,finid int,fromdate date, todate date)
BEGIN
select * from trnpur_purchase_header
join trnpur_purchase_trailer on phd_comp_code = ptr_comp_code and phd_fin_code = ptr_fin_code and phd_pono = ptr_pono 
join massal_customer on  phd_sup_code = cust_code
join maspur_item_header on  ptr_item_code = item_code
join mas_uom on ptr_uom =  uom_code
 left join 
(select * from trnpur_min_header , trnpur_min_trailer where minh_comp_code = mint_comp_code and
minh_fin_code = mint_fin_code and minh_minno = mint_minno and minh_type = 'P' and minh_comp_code =  1) grn on 
 ptr_item_code = mint_item_code and 
 minh_comp_code = phd_comp_code and
 minh_fin_code = phd_fin_code and
 phd_pono = mint_pono  and
 phd_podate = mint_podate
 where phd_comp_code = compcode and phd_fin_code = finid and  phd_podate  between fromdate and todate order by  phd_podate asc , cast(phd_pono as unsigned) asc;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
