DELIMITER ;;
CREATE DEFINER=`root`@`%` PROCEDURE `sppur_rep_po_gstdetails`(pocompcode int, pofincode int, pono int)
BEGIN
select gstledger,sum(gstamt) gstamt from (
select tax_cgstledger gstledger ,ptr_cgst_amt as gstamt  from trnpur_purchase_trailer , mas_purchasetax where ptr_comp_code = pocompcode and  ptr_fin_code = pofincode and ptr_pono = pono and ptr_cgst_per + ptr_sgst_per + ptr_igst_per = tax_gst
union all 
select tax_sgstledger gstledger ,ptr_sgst_amt as gstamt  from trnpur_purchase_trailer , mas_purchasetax where ptr_comp_code = pocompcode and  ptr_fin_code = pofincode and ptr_pono = pono and ptr_cgst_per + ptr_sgst_per + ptr_igst_per = tax_gst
union all 
select tax_igstledger gstledger ,ptr_igst_amt as gstamt  from trnpur_purchase_trailer , mas_purchasetax where ptr_comp_code = pocompcode and  ptr_fin_code = pofincode and ptr_pono = pono and ptr_cgst_per + ptr_sgst_per + ptr_igst_per = tax_gst
 )aa where gstamt > 0 group by gstledger;
END ;;
DELIMITER ;
