CREATE DEFINER=`root`@`%` PROCEDURE `sppur_rep_purchaseorder`(phdpono varchar(10), phdfincode int, phdcompcode int)
BEGIN
SELECT
    trnpur_purchase_header.phd_comp_code, trnpur_purchase_header.phd_pono,
    trnpur_purchase_header.phd_podate, trnpur_purchase_header.phd_fin_code, trnpur_purchase_header.phd_credit_days, trnpur_purchase_header.phd_dely_point, trnpur_purchase_header.phd_other_ref, 
    trnpur_purchase_header.phd_spl_instruction, trnpur_purchase_header.phd_prepared_by, 
    trnpur_purchase_header.phd_roundoff, trnpur_purchase_header.phd_total, trnpur_purchase_header.phd_amnd_status, trnpur_purchase_header.phd_party_refno, trnpur_purchase_header.phd_party_refdate, 
     trnpur_purchase_trailer.ptr_slno, trnpur_purchase_trailer.ptr_unit_rate, trnpur_purchase_trailer.ptr_ord_qty, trnpur_purchase_trailer.ptr_discount, trnpur_purchase_trailer.ptr_pf_per, trnpur_purchase_trailer.ptr_freight_amt, trnpur_purchase_trailer.ptr_oth_amt, trnpur_purchase_trailer.ptr_ind_no, trnpur_purchase_trailer.ptr_disval, trnpur_purchase_trailer.ptr_pfval, 
     trnpur_purchase_trailer.ptr_cgst_per, trnpur_purchase_trailer.ptr_cgst_amt, trnpur_purchase_trailer.ptr_sgst_per, trnpur_purchase_trailer.ptr_sgst_amt, trnpur_purchase_trailer.ptr_igst_per, trnpur_purchase_trailer.ptr_igst_amt, trnpur_purchase_trailer.ptr_frt2,
    massal_customer.cust_name, massal_customer.cust_add1, massal_customer.cust_add2, massal_customer.cust_add3, massal_customer.cust_city, massal_customer.cust_zip, massal_customer.cust_panno, massal_customer.cust_gstin,
    mas_transport.carr_name, mas_company.company_code, mas_company.company_name,mas_company.company_gst,
 maspur_item_header.item_name, mas_state.state_name, mas_state.state_codeno,
     mas_uom.uom_short_name, item_hsncode, trnpur_purchase_trailer.ptr_remarks, trnpur_purchase_header.phd_deliverydate, trnpur_purchase_header.phd_freight, userM.usr_name, trnpur_purchase_header.phd_pay_terms , dept_headname,phd_amend_date,phd_amend_no
     
FROM
    { oj (((((((((trnpur_purchase_header trnpur_purchase_header INNER JOIN massal_customer massal_customer ON
        trnpur_purchase_header.phd_sup_code = massal_customer.cust_code)
     INNER JOIN mas_transport mas_transport ON
        trnpur_purchase_header.phd_transport = mas_transport.carr_code)
     INNER JOIN mas_company mas_company ON
        trnpur_purchase_header.phd_comp_code = mas_company.company_code)
	 INNER JOIN userMaster  userM ON
        trnpur_purchase_header.phd_prepared_by = userM.usr_code)
     INNER JOIN trnpur_purchase_trailer trnpur_purchase_trailer ON
        trnpur_purchase_header.phd_comp_code = trnpur_purchase_trailer.ptr_comp_code AND
    trnpur_purchase_header.phd_pono = trnpur_purchase_trailer.ptr_pono AND
    trnpur_purchase_header.phd_fin_code = trnpur_purchase_trailer.ptr_fin_code)
     INNER JOIN mas_state mas_state ON
        massal_customer.cust_state = mas_state.state_code)
     INNER JOIN maspur_item_header maspur_item_header ON
        trnpur_purchase_trailer.ptr_item_code = maspur_item_header.item_code)
     INNER JOIN mas_uom mas_uom ON
        trnpur_purchase_trailer.ptr_uom = mas_uom.uom_code)
     INNER JOIN mas_dept mas_dept ON  
        trnpur_purchase_header.phd_dept = mas_dept.dept_code)
       
        }
WHERE
    trnpur_purchase_header.phd_pono = phdpono AND
    trnpur_purchase_header.phd_fin_code = phdfincode AND
    trnpur_purchase_header.phd_comp_code = phdcompcode 

ORDER BY
    trnpur_purchase_trailer.ptr_slno ASC;

END ;;
DELIMITER ;
