DELIMITER ;;
CREATE DEFINER=`root`@`10.0.0.251` PROCEDURE `sppur_sel_indent_details`( compcode numeric (3,0), fincode int, indno numeric (6,0))
BEGIN
select * from (
select a1.*,item_avg_rate,item_stock from (
select a.*,b.item_name as item_name,c.app_name as app_name,e.*,f.* ,g.*                     
from trnpur_indent a, maspur_item_header b,maspur_approval c, mas_section e , mas_equipment f ,mas_uom g
 ,mas_dept i                   
Where
      a.ind_comp_code = compcode                
      and a.ind_fin_code = fincode 
      and a.ind_no = indno                     
      and a.ind_approval_status = c.app_code   
      and a.ind_section = e.section_code                   
      and a.ind_equip = f.equip_code
      and a.ind_item_code = b.item_code                       
      and a.ind_dept_code = i.dept_code
      and b.item_uom      = g.uom_code order by ind_slno
      )a1 left outer join
      maspur_item_trailer b1 on a1.ind_item_code = b1.item_code and ind_comp_code = item_comp_code and ind_fin_code = item_fin_code
) aa2 order by  ind_slno;   
      
      
/*
select a.*,b.item_name as item_name,c.app_name as app_name,e.*,f.* ,g.*,item_avg_rate,item_stock                      
from trnpur_indent a, maspur_item_header b,maspur_approval c, mas_section e , mas_equipment f ,mas_uom g
 ,maspur_item_trailer h,mas_dept i                   
Where
      a.ind_comp_code = compcode                   
      and a.ind_fin_code = fincode 
      and a.ind_no = indno                     
      and a.ind_approval_status = c.app_code   
      and a.ind_section = e.section_code                   
      and a.ind_equip = f.equip_code
      and a.ind_item_code = b.item_code                       
      and a.ind_dept_code = i.dept_code
      and a.ind_comp_code = h.item_comp_code                   
      and a.ind_fin_code  = h.item_fin_code 
      and b.item_code     = h.item_code
      and b.item_uom      = g.uom_code order by ind_slno;
*/      
END ;;
DELIMITER ;
