CREATE DEFINER=`root`@`%` PROCEDURE `sppur_sel_mindetails`(comp_code numeric (3,0),fin_code int,min_no varchar(15) )
BEGIN
select  t.*,i.item_code, item_name, item_group_code,item_qcchk ,uom_short_name, item_hsncode,     
h.minh_minno,minh_type, minh_bill_no,minh_bill_date,minh_remarks,minh_carrier,      
mint_cr_status,minh_credit_days,minh_geno, minh_gedate,minh_lrno,minh_lrdate,minh_accupd,minh_value,
led.cust_name led_name,mint_purgroup,minh_roundneeded,s.cust_ref,s.cust_code,s.cust_state,minh_vou_no,minh_acc_seqno,tax.*,minh_cgst_pm,minh_sgst_pm,minh_igst_pm,minh_tot_tcs,minh_round_off,minh_acc_seqno,mint_item_unit, minh_grn_status ,acctrail_adj_value
from  trnpur_min_trailer t,trnpur_min_header h,maspur_item_header i,      
mas_uom u,maspur_subgroup g,massal_customer s ,massal_customer led ,mas_purchasetax tax  ,  acc_trail acc  
where  t.mint_item_code = i.item_code and  mint_comp_code = minh_comp_code and       
mint_fin_code = minh_fin_code        
 and h.minh_minno = t.mint_minno  and i.item_uom 	= u.uom_code and      
 i.item_group_code = g.subgrp_code and mint_sup_code = s.cust_code         
 and mint_comp_code = comp_code         
 and mint_fin_code = fin_code      
 and mint_minno = min_no  
 -- and minh_purtype = mint_purtype
 and mint_purgroup = led.cust_code
 and mint_cgst_per+mint_sgst_per+mint_igst_per = tax_gst
   and minh_acc_seqno = acctrail_accref_seqno
 order by mint_slno;
/*
select  t.*,i.item_code, item_name, item_group_code,item_qcchk ,uom_short_name, item_hsncode,     
h.minh_minno,minh_type, minh_bill_no,minh_bill_date,minh_remarks,minh_carrier,      
mint_cr_status,minh_credit_days,sup_type,minh_geno, minh_gedate,minh_lrno,minh_lrdate,minh_accupd,
led_name,mint_purgroup,minh_roundneeded,sup_refname,sup_led_code,minh_vou_no,tax.*
from  trnpur_min_trailer t,trnpur_min_header h,maspur_item_header i,      
mas_uom u,maspur_subgroup g,maspur_supplier_master s ,acc_ledger_master led ,mas_purchasetax tax      
where  t.mint_item_code = i.item_code and  mint_comp_code = minh_comp_code and       
mint_fin_code = minh_fin_code        
 and h.minh_minno = t.mint_minno  and i.item_uom = u.uom_code and      
 i.item_group_code = g.subgrp_code and mint_sup_code = s.sup_code         
 and mint_comp_code = comp_code         
 and mint_fin_code = fin_code        
 and mint_minno = min_no   
 and minh_purtype = mint_purtype
 and minh_purtype = purtype
 and mint_purgroup = led_code
 and mint_cgst_per+mint_sgst_per+mint_igst_per = tax_gst
 order by mint_slno;*/
END ;;
DELIMITER ;
