CREATE DEFINER=`root`@`%` PROCEDURE `sppur_sel_po_viewdetail`( compcode  numeric(3,0),   fincode  int,   pono  varchar(10))
BEGIN

 select  a.*,b.item_name,c.* ,d.*,e.cust_name led_name,u.*, i.ind_qty,uom.*
 from  trnpur_purchase_trailer a, maspur_item_header b, trnpur_purchase_header c,massal_customer d , massal_customer e, userMaster u,mas_uom uom ,
 trnpur_indent i
 where  phd_prepared_by = u.usr_code and ptr_item_code = b.item_code and ptr_comp_code = phd_comp_code and  phd_sup_code = d.cust_code and
 ptr_fin_code = phd_fin_code and ptr_pono = phd_pono and   ptr_purgroup = e.cust_code and
 ptr_comp_code = ind_comp_code and  
 ind_fin_code =  ptr_ind_fin_code and
 ind_no = ptr_ind_no and 
 ind_item_code = ptr_item_code and 
 ptr_comp_code = compcode and  
 ptr_fin_code = fincode and  
 ptr_pono = pono and 
 ptr_uom = uom_code
 order by ptr_slno;
 
/*
 select  a.*,b.item_name,c.* ,d.*,e.cust_name led_name,u.*
 from  trnpur_purchase_trailer a, maspur_item_header b, trnpur_purchase_header c,massal_customer d , massal_customer e, userMaster u
 where  phd_prepared_by = u.usr_code and ptr_item_code = b.item_code and ptr_comp_code = phd_comp_code and  phd_sup_code = d.cust_code and
 ptr_fin_code = phd_fin_code and ptr_pono = phd_pono and   ptr_purgroup = e.cust_code and
 ptr_comp_code = compcode and  
 ptr_fin_code = fincode and  
 ptr_pono = pono 
 order by ptr_slno;
 */

END ;;
