CREATE DEFINER=`root`@`%` PROCEDURE `sppur_upd_minheader`(
  minhcompcode int,     
  minhminno varchar(12),      
  minhmindate datetime,      
  minhfincode int,      
  minhbillno varchar(20),      
  minhbilldate datetime,      
  minhgrossvalue numeric(15,2),      
  minhroundoff numeric(5,2),  
  minhroundneed varchar(1),  
  minhvalue numeric(15,2),      
  minhcarrier varchar(50),      
  minhremarks text,     
  minhcreditdays int, 
  minhgeno varchar(20),        
  minhgedate datetime ,       
  minhlrno varchar(20),        
  minhlrdate datetime,
  p_tcsauto varchar(1) ,
  minhcgstpm numeric(10,2),  
  minhsgstpm numeric(10,2),  
  minhigstpm numeric(10,2),  
  minhtottcs  numeric(10,2),
  minhgrnstatus varchar(1) ,
  accseqno int,
  minhtottransport  numeric(10,2) ,
  userid int,
  modifydate datetime ,
  minhtype  varchar(1) 
)
BEGIN
 update trnpur_min_header set minh_gross_value = minhgrossvalue,      
                         minh_value = minhvalue,      
                         minh_round_off = minhroundoff, 
                         minh_roundneeded =  minhroundneed,
                         minh_carrier = minhcarrier,      
                         minh_remarks = minhremarks,      
                         minh_credit_days = minhcreditdays,     
                         minh_mindate = minhmindate,  
                         minh_acc_date = minhmindate,                              
                         minh_bill_no   =  minhbillno,      
                         minh_bill_date = minhbilldate,       
                         minh_geno   = minhgeno,       
                         minh_gedate = minhgedate,     
                         minh_lrno   = minhlrno,       
                         minh_lrdate = minhlrdate,                         
                         minh_tcs_automatic = p_tcsauto,    
                         minh_cgst_pm = minhcgstpm,
                         minh_sgst_pm = minhsgstpm,
                         minh_igst_pm = minhigstpm,
                         minh_tot_tcs = minhtottcs,
                          minh_grn_status  = minhgrnstatus ,
                          minh_acc_seqno = accseqno ,
                          minh_tot_transport = minhtottransport,
                          minh_modified_by = userid,
                          minh_modified_date = modifydate,
                          minh_type  = minhtype
              where minh_minno =  minhminno      
                         and minh_comp_code = minhcompcode      
                         and minh_fin_code = minhfincode;
                     
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
