CREATE DEFINER=`root`@`%` PROCEDURE `sppur_upd_mintrailer`( 
   mintvoutype varchar(3), 
   mintcomp_code numeric(3,0),                    
   mintminno varchar(12),                    
   mintmindate datetime,                    
   mintfin_code int,                    
   mintpono varchar(10),                    
   mintpodate datetime,                    
   mintsup_code numeric(6,0),                    
   mintitem_code numeric(6,0),                    
   mintinv_qty  numeric(15,3),                    
   mintrcvd_qty numeric(15,3),     
   mintaccept_qty numeric(15,3),  
   mintrej_qty numeric(15,3),                    
   mintunit_rate numeric(12,4),                    
   mintcost_rate numeric(13,5),                    
   mintpack_per numeric(5,3),                    
   mintothers numeric(10,2),                    
   mintfreight numeric(10,2),                    
   mintdiscount numeric(5,3),                    
   mintotherspm  numeric(10,2),                    
   mintvalue numeric(18,2),                    
   mintind_fin_code int,                    
   mintind_no numeric(6,0),                    
                 
   mintcr_status char,                    
               
   mintslno int,                    
   mintdisamt numeric(14,2),                    
   mintpfamt numeric(14,2),                    
   mintcgst_per  numeric(5,1),                        
   mintcgst_amt  numeric(9,2),                        
   mintsgst_per  numeric(5,1),                        
   mintsgst_amt  numeric(9,2),                        
   mintigst_per  numeric(5,1),                        
   mintigst_amt  numeric(9,2),                       
   minttcsper numeric(5,2),  
   minttcsamt numeric(8,2) ,
   mintrebate numeric(8,2) ,
   mintpurgroup int,
   mintcgstledcode numeric(6,0),         
   mintsgstledcode numeric(6,0),         
   mintigstledcode numeric(6,0)         
   )
BEGIN
update  trnpur_min_trailer                     
set mint_inv_qty = mintinv_qty, mint_rcvd_qty = mintrcvd_qty, mint_accept_qty = mintaccept_qty,                     
mint_mindate = mintmindate,mint_unit_rate = mintunit_rate, mint_others = mintothers,                     
mint_discount = mintdiscount, mint_pack_per = mintpack_per,                    
mint_value = mintvalue, mint_cost_rate = mintcost_rate, mint_freight = mintfreight,mint_cr_status = mintcr_status,                     
mint_disamt=mintdisamt,mint_pfamt=mintpfamt,
mint_otherspm = mintotherspm,
mint_cgst_per  = mintcgst_per,            
mint_cgst_amt  = mintcgst_amt,            
mint_sgst_per  = mintsgst_per,            
mint_sgst_amt  = mintsgst_amt,            
mint_igst_per  = mintigst_per,            
mint_igst_amt  = mintigst_amt,          
mint_tcs_per  = minttcsper,
mint_tcs_amt  = minttcsamt ,
mint_rebate  = mintrebate ,
mint_purgroup = mintpurgroup ,
mint_cgst_ledcode  = mintcgstledcode,
mint_sgst_ledcode  = mintsgstledcode,
mint_igst_ledcode  = mintigstledcode
,mint_item_code = mintitem_code     
where    mint_comp_code = mintcomp_code                     
             and mint_fin_code = mintfin_code                    
             and mint_minno = mintminno                    
             and mint_item_code = mintitem_code                    
             and mint_pono = mintpono                
             and mint_ind_fin_code = mintind_fin_code                    
             and mint_ind_no = mintind_no                    
             and mint_slno = mintslno;            
             
END ;;
DELIMITER ;
