CREATE DEFINER=`root`@`%` PROCEDURE `spqc_chemical_inspection`(compcode int,fincode int,entryno int)
BEGIN
	select trn.* , mascust.cust_ref ,masitem.item_name,masparam.qc_cd_param_name,masmeasure.*
    from trn_qc_chemical_inspection trn , massal_customer mascust , maspur_item_header masitem,  masqc_cd_parameters masparam , masqc_measuring_methods masmeasure
	 where qc_cd_supcode = cust_code and qc_cd_itemcode = item_code and 
	 trn.qc_cd_param_code = masparam.qc_cd_param_code and
	 trn.qc_cd_measuring_code =  masmeasure.qc_measuring_code and 
	 qc_cd_compcode = compcode and qc_cd_fincode = fincode and qc_cd_entryno = entryno;
END ;;
