CREATE DEFINER=`root`@`%` PROCEDURE `spqc_fuel_DebitNote`(compcode int,fincode int,vouno varchar(15),fromdate date,todate date)
BEGIN

if vouno <> '0'  then
select * from (
select a.*,b.*,c.*,d.* ,deg.itmh_name as deg_item_name  from trn_qc_fuel_inspection a, masfu_item_header b ,massal_customer c , mas_area d,
masfu_item_header deg where qc_fuel_degrade_item = deg.itmh_code  and  qc_fuel_area = area_code and  qc_fuel_supcode = cust_code and a.qc_fuel_itemcode = b.itmh_code and 
qc_fuel_compcode = compcode and qc_fuel_fincode = fincode and qc_fuel_debitnote_no = vouno)a1;
else
select * from (
select a.*,b.*,c.*,d.* ,deg.itmh_name deg_item_name  from trn_qc_fuel_inspection a, masfu_item_header b ,massal_customer c , mas_area d,
masfu_item_header deg where qc_fuel_degrade_item = deg.itmh_code  and  qc_fuel_area = area_code and  qc_fuel_supcode = cust_code and a.qc_fuel_itemcode = b.itmh_code and 
qc_fuel_compcode = compcode and qc_fuel_fincode = fincode and qc_fuel_debitnote_date between fromdate and todate)a1;
end if;
/*
if vouno <> '0'  then
select * from trn_qc_fuel_inspection , masfu_item_header,massal_customer , mas_area where  qc_fuel_area = area_code and  qc_fuel_supcode = cust_code and qc_fuel_itemcode = itmh_code and 
qc_fuel_compcode = compcode and qc_fuel_fincode = fincode and qc_fuel_debitnote_no = vouno;
else
select * from trn_qc_fuel_inspection , masfu_item_header,massal_customer , mas_area where  qc_fuel_area = area_code and  qc_fuel_supcode = cust_code and qc_fuel_itemcode = itmh_code and 
qc_fuel_compcode = compcode and qc_fuel_fincode = fincode and  qc_fuel_debitnote_date between fromdate and todate;
end if;
*/

END ;;
