CREATE DEFINER=`root`@`%` PROCEDURE `spqc_fuel_inspection`(compcode int,fincode int,entryno int,fromdate date,todate date)
BEGIN
/*
if entryno > 0 then
select * from trn_qc_fuel_inspection , masfu_item_header,massal_customer , mas_area where  qc_fuel_area = area_code and  qc_fuel_supcode = cust_code and qc_fuel_itemcode = itmh_code and 
qc_fuel_compcode = compcode and qc_fuel_fincode = fincode and qc_fuel_entryno = entryno;
else
select * from trn_qc_fuel_inspection , masfu_item_header,massal_customer , mas_area where  qc_fuel_area = area_code and  qc_fuel_supcode = cust_code and qc_fuel_itemcode = itmh_code and 
qc_fuel_compcode = compcode and qc_fuel_fincode = fincode and  qc_fuel_ticketdate between fromdate and todate;
end if;
*/
if entryno > 0 then
select * from (
select t.*,i1.*,i2.itmh_name degrde_item_name,c.*,a.* from trn_qc_fuel_inspection t , masfu_item_header i1 , masfu_item_header i2 ,massal_customer c , mas_area  a where
 t.qc_fuel_degrade_item = i2.itmh_code and
 t.qc_fuel_area = a.area_code 
 and  t.qc_fuel_supcode = c.cust_code and t.qc_fuel_itemcode = i1.itmh_code and 
t.qc_fuel_compcode = compcode and t.qc_fuel_fincode = fincode and t.qc_fuel_entryno = entryno) a1;

else
select * from (
select t.*,i1.*,i2.itmh_name degrde_item_name,c.*,a.* from trn_qc_fuel_inspection t , masfu_item_header i1 , masfu_item_header i2 ,massal_customer c , mas_area  a where
 t.qc_fuel_degrade_item = i2.itmh_code and
 t.qc_fuel_area = a.area_code 
 and  t.qc_fuel_supcode = c.cust_code and t.qc_fuel_itemcode = i1.itmh_code and 
t.qc_fuel_compcode = compcode and t.qc_fuel_fincode = fincode and  qc_fuel_ticketdate between fromdate and todate) a1;
end if;

END ;;
