BEGIN
select cust_ref ,itmh_name, sum(qc_fuel_acceptqty)/1000 acceptedqty  from trn_qc_fuel_inspection , massal_customer , masfu_item_header , mas_area where qc_fuel_area = area_code and qc_fuel_itemcode = itmh_code and qc_fuel_supcode = cust_code 
