/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`%` PROCEDURE `spqc_fuel_partywiseArrivals_dayreport`(compcode int,finid int, fromdate date,todate date)
BEGIN

select   orderprint,cust_name,itmh_name, itmh_code , cast(sum(current_day) as  decimal(10,3))  current_day,
 cast(sum(cur_purvalue) as  decimal(10,2))  cur_purvalue,
 cast(sum(upto_previous_day)  as  decimal(10,3))  upto_previous_day ,
 cast(sum(pre_purvalue) as  decimal(10,2))  pre_purvalue,
 case when  sum(cur_purvalue) > 0 then cast(sum(cur_purvalue)/sum(current_day) as  decimal(10,2)) else 0 end as cur_avgrate,
 case when  sum(pre_purvalue) > 0 then cast(sum(pre_purvalue)/sum(upto_previous_day) as  decimal(10,2)) else 0 end as pre_avgrate,
  cast(sum(current_day)+sum(upto_previous_day)  as  decimal(10,3))  upto_current_day
 

 from 
(
select '1' orderprint,  cust_name,itmh_name, itmh_code , 0 as current_day,0 as cur_purvalue,0 as cur_avgrate, cast(sum(qc_fuel_acceptqty/1000) as decimal(10,3)) upto_previous_day ,cast(sum(qc_fuel_acceptqty/1000 * qc_fuel_itemrate) as decimal(10,2)) pre_purvalue  , cast(sum(qc_fuel_acceptqty/1000 * qc_fuel_itemrate) /sum(qc_fuel_acceptqty/1000)  as decimal(8,0)) prev_avgrate 
from trn_qc_fuel_inspection , massal_customer , masfu_item_header , mas_area where qc_fuel_area = area_code and qc_fuel_itemcode = itmh_code and qc_fuel_supcode = cust_code 
and qc_fuel_fincode = finid and qc_fuel_compcode = compcode  and qc_fuel_ticketdate >= fromdate and qc_fuel_ticketdate < todate
group by cust_name,itmh_name, itmh_code 
union all
select  '1' orderprint, cust_name,itmh_name, itmh_code , cast(sum(qc_fuel_acceptqty/1000) as decimal(10,3)) current_day ,cast(sum(qc_fuel_acceptqty/1000 * qc_fuel_itemrate) as decimal(10,2)) cur_purvalue , cast(sum(qc_fuel_acceptqty/1000 * qc_fuel_itemrate) /sum(qc_fuel_acceptqty/1000)  as decimal(8,0)) cur_avgrate,0 as upto_previous_day,0 as prev_purvalue, 0 as prev_avgrate
 from trn_qc_fuel_inspection , massal_customer , masfu_item_header , mas_area where qc_fuel_area = area_code and qc_fuel_itemcode = itmh_code and qc_fuel_supcode = cust_code 
and qc_fuel_fincode = finid and qc_fuel_compcode = compcode   and qc_fuel_ticketdate =  todate
group by cust_name,itmh_name, itmh_code 

union all


select  '2' orderprint, concat('Up to Date ', DATE_FORMAT( todate-1, '%d-%m-%Y')  ) cust_name,itmh_name, itmh_code , cast(sum(qc_fuel_acceptqty/1000) as decimal(10,3)) current_day ,cast(sum(qc_fuel_acceptqty/1000 * qc_fuel_itemrate) as decimal(10,2)) cur_purvalue,  cast(sum(qc_fuel_acceptqty/1000 * qc_fuel_itemrate) /sum(qc_fuel_acceptqty/1000)  as decimal(8,0)) cur_avgrate, 0 as upto_previous_day  , 0 as prev_purvalue , 0 as prev_avgrate
 from trn_qc_fuel_inspection , massal_customer , masfu_item_header , mas_area where qc_fuel_area = area_code and qc_fuel_itemcode = itmh_code and qc_fuel_supcode = cust_code 
and qc_fuel_fincode = finid and qc_fuel_compcode = compcode   and  qc_fuel_ticketdate >= fromdate and qc_fuel_ticketdate < todate
group by cust_name,itmh_name, itmh_code 


union all
select  '3' orderprint, 'NET TOTAL'  cust_name,itmh_name, itmh_code , cast(sum(qc_fuel_acceptqty/1000) as decimal(10,3)) current_day ,cast(sum(qc_fuel_acceptqty/1000 * qc_fuel_itemrate) as decimal(10,2)) cur_purvalue,  cast(sum(qc_fuel_acceptqty/1000 * qc_fuel_itemrate) /sum(qc_fuel_acceptqty/1000)  as decimal(8,0)) cur_avgrate, 0 as upto_previous_day  , 0 as prev_purvalue , 0 as prev_avgrate
 from trn_qc_fuel_inspection , massal_customer , masfu_item_header , mas_area where qc_fuel_area = area_code and qc_fuel_itemcode = itmh_code and qc_fuel_supcode = cust_code 
and qc_fuel_fincode = finid and qc_fuel_compcode = compcode   and  qc_fuel_ticketdate >= fromdate and qc_fuel_ticketdate <= todate
group by cust_name,itmh_name, itmh_code 
) aa1 group by  orderprint,cust_name,itmh_name, itmh_code order by orderprint, cust_name;

END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
