CREATE DEFINER=`root`@`%` PROCEDURE `spqc_fuel_party_itemwise_abstract`(compcode int,finid int, fromdate date,todate date)
BEGIN
select  cust_name, itmh_name, sum(qc_fuel_ticketwt/1000) as ticketwt  ,sum(qc_fuel_mois_arb_qty/1000) as mosiwt  ,
sum(qc_fuel_fines_qty/1000) as fineswt , sum(qc_fuel_sand_qty/1000) as sandwt  ,sum(qc_fuel_acceptqty/1000) as acceptedwt ,
 sum(qc_fuel_acceptqty/1000*qc_fuel_itemrate) as itemvalue,
 sum(qc_fuel_acceptqty*qc_fuel_itemrate)/sum(qc_fuel_acceptqty)  as avgrate
 from trn_qc_fuel_inspection , massal_customer , masfu_item_header , mas_area where qc_fuel_area = area_code and qc_fuel_itemcode = itmh_code and qc_fuel_supcode = cust_code 
and qc_fuel_fincode = finid and qc_fuel_compcode = compcode  and qc_fuel_ticketdate between  fromdate and todate
group by cust_name,itmh_name;
END ;;
DELIMITER ;
