DELIMITER ;;
CREATE DEFINER=`root`@`%` PROCEDURE `spqc_rm_arrivals_datewise`(compcode int,finid int, fromdate date,todate date,rmtype int)
BEGIN
select  orderprint, cust_name, itmh_name,itmh_code, area_code, area_name,sum(curdate_grnwt)/1000  as curdate_grnwt, sum(curdate_grnvalue) as curdate_grnvalue,
case when  sum(curdate_grnvalue) > 0 and sum(curdate_grnwt) > 0 then  sum(curdate_grnvalue) /sum(curdate_grnwt)  else 0 end as curdate_avgrate,
 sum(uptopreviousdate_grnwt)/1000 as uptopreviousdate_grnwt,sum(uptopreviousdate_grnvalue) as  uptopreviousdate_grnvalue ,
sum(uptodate_grnwt)/1000 as uptodate_grnwt ,sum(uptodate_grnvalue) as  uptodate_grnvalue ,
case when  sum(uptodate_grnvalue) > 0 and sum(uptodate_grnwt) > 0 then  sum(uptodate_grnvalue) /sum(uptodate_grnwt)  else 0 end as uptodate_avgrate
 from 
(
select  '1' orderprint, cust_name, itmh_name,itmh_code, area_code, area_name,sum(qc_rm_acceptqty)  as curdate_grnwt, sum(qc_rm_acceptqty/1000 * qc_rm_rate) as curdate_grnvalue,0 as uptopreviousdate_grnwt,0 as uptopreviousdate_grnvalue ,0 as uptodate_grnwt, 0 as uptodate_grnvalue     from trn_qc_rm_inspection , massal_customer , masrm_item_header , mas_area where qc_rm_area = area_code and qc_rm_itemcode = itmh_code and qc_rm_supcode = cust_code 
and itmh_type =rmtype and qc_rm_fincode = finid and qc_rm_compcode = compcode and  qc_rm_ticketdate = todate group by cust_name,itmh_name,itmh_code, area_code, area_name

union all

select  '1' orderprint, cust_name, itmh_name,itmh_code, area_code, area_name,0 as curdate_grnwt, 0 as curdate_grnvalue, sum(qc_rm_acceptqty)  as uptopreviousdate_grnwt, sum(qc_rm_acceptqty/1000 * qc_rm_rate)  as uptopreviousdate_grnvalue ,0 as uptodate_grnwt, 0 as uptodate_grnvalue      
from trn_qc_rm_inspection , massal_customer , masrm_item_header , mas_area where qc_rm_area = area_code and qc_rm_itemcode = itmh_code and qc_rm_supcode = cust_code 
and itmh_type =rmtype and qc_rm_fincode = finid and qc_rm_compcode = compcode and  qc_rm_ticketdate >= fromdate and  qc_rm_ticketdate < todate group by cust_name,itmh_name,itmh_code, area_code, area_name

union all

select  '1' orderprint, cust_name, itmh_name, itmh_code,area_code, area_name,0 as curdate_grnwt, 0 as curdate_grnvalue, 0  as uptopreviousdate_grnwt, 0 as uptopreviousdate_grnvalue,
 sum(qc_rm_acceptqty)  as uptodate_grnwt, sum(qc_rm_acceptqty/1000 * qc_rm_rate)  as uptodate_grnvalue    
 from trn_qc_rm_inspection , massal_customer , masrm_item_header , mas_area where qc_rm_area = area_code and qc_rm_itemcode = itmh_code and qc_rm_supcode = cust_code 
and itmh_type =rmtype and qc_rm_fincode = finid and qc_rm_compcode = compcode and  qc_rm_ticketdate >= fromdate and  qc_rm_ticketdate <=todate group by cust_name,itmh_name,itmh_code, area_code, area_name

union all
select '2' orderprint, concat('Up to Date ', DATE_FORMAT( todate-1, '%d-%m-%Y') ) cust_name, itmh_name,itmh_code, area_code, area_name,sum(qc_rm_acceptqty)   as curdate_grnwt, 0  as curdate_grnvalue, 0  as uptopreviousdate_grnwt, 0 as uptopreviousdate_grnvalue ,0 as uptodate_grnwt, 0 as uptodate_grnvalue      
from trn_qc_rm_inspection , masrm_item_header , mas_area where qc_rm_area = area_code and qc_rm_itemcode = itmh_code 
and itmh_type =rmtype and qc_rm_fincode = finid and qc_rm_compcode = compcode and  qc_rm_ticketdate >= fromdate and  qc_rm_ticketdate < todate group by cust_name,itmh_name,itmh_code, area_code, area_name

union all
select '3' orderprint, 'NET TOTAL' cust_name, itmh_name,itmh_code , area_code, area_name , sum(qc_rm_acceptqty)  as curdate_grnwt, 0 as curdate_grnvalue, 0 as uptopreviousdate_grnwt, 0 as uptopreviousdate_grnvalue ,0 as uptodate_grnwt, 0 as uptodate_grnvalue      
from trn_qc_rm_inspection , masrm_item_header , mas_area where qc_rm_area = area_code and qc_rm_itemcode = itmh_code 
and itmh_type =rmtype and qc_rm_fincode = finid and qc_rm_compcode = compcode and  qc_rm_ticketdate >= fromdate and  qc_rm_ticketdate <= todate group by cust_name,itmh_name,itmh_code, area_code, area_name


)a  group by orderprint,cust_name,itmh_name,itmh_code, area_code, area_name order by orderprint,cust_name;

END ;;
DELIMITER ;
