DELIMITER ;;
CREATE DEFINER=`root`@`%` PROCEDURE `spqc_rm_arrivals_Monthwise_Abs`(compcode int,finid int, fromdate date,todate date,rmtype int)
BEGIN
select ryear,rmonth , rmonthname , itmh_name,itmh_code, sum(qty) qty, sum(grnvalue) grnvalue from
(

select  year(qc_rm_ticketdate) ryear, month(qc_rm_ticketdate) rmonth, ucase(monthname(qc_rm_ticketdate)) rmonthname, itmh_name,itmh_code,qc_rm_acceptqty/1000 qty , qc_rm_acceptqty/1000 * qc_rm_rate  as grnvalue 
from trn_qc_rm_inspection , masrm_item_header where qc_rm_itemcode = itmh_code 
and itmh_type =  rmtype and qc_rm_fincode = finid and qc_rm_compcode = compcode and  qc_rm_ticketdate between fromdate and todate

) a1 group by ryear,rmonth , rmonthname , itmh_name,itmh_code;

END ;;
