case when dayofmonth(qc_rm_ticketdate) = 20 then sum(qc_rm_acceptqty)  else 0 end as day20_grnwt, case when dayofmonth(qc_rm_ticketdate) = 20 then sum(qc_rm_acceptqty/1000 * qc_rm_rate)  else 0 end as day20_grnvalue, 
case when dayofmonth(qc_rm_ticketdate) = 21 then sum(qc_rm_acceptqty)  else 0 end as day21_grnwt, case when dayofmonth(qc_rm_ticketdate) = 21 then sum(qc_rm_acceptqty/1000 * qc_rm_rate)  else 0 end as day21_grnvalue, 
case when dayofmonth(qc_rm_ticketdate) = 22 then sum(qc_rm_acceptqty)  else 0 end as day22_grnwt, case when dayofmonth(qc_rm_ticketdate) = 22 then sum(qc_rm_acceptqty/1000 * qc_rm_rate)  else 0 end as day22_grnvalue, 
case when dayofmonth(qc_rm_ticketdate) = 23 then sum(qc_rm_acceptqty)  else 0 end as day23_grnwt, case when dayofmonth(qc_rm_ticketdate) = 23 then sum(qc_rm_acceptqty/1000 * qc_rm_rate)  else 0 end as day23_grnvalue, 
case when dayofmonth(qc_rm_ticketdate) = 24 then sum(qc_rm_acceptqty)  else 0 end as day24_grnwt, case when dayofmonth(qc_rm_ticketdate) = 24 then sum(qc_rm_acceptqty/1000 * qc_rm_rate)  else 0 end as day24_grnvalue, 
case when dayofmonth(qc_rm_ticketdate) = 25 then sum(qc_rm_acceptqty)  else 0 end as day25_grnwt, case when dayofmonth(qc_rm_ticketdate) = 25 then sum(qc_rm_acceptqty/1000 * qc_rm_rate)  else 0 end as day25_grnvalue, 
case when dayofmonth(qc_rm_ticketdate) = 26 then sum(qc_rm_acceptqty)  else 0 end as day26_grnwt, case when dayofmonth(qc_rm_ticketdate) = 26 then sum(qc_rm_acceptqty/1000 * qc_rm_rate)  else 0 end as day26_grnvalue, 
case when dayofmonth(qc_rm_ticketdate) = 27 then sum(qc_rm_acceptqty)  else 0 end as day27_grnwt, case when dayofmonth(qc_rm_ticketdate) = 27 then sum(qc_rm_acceptqty/1000 * qc_rm_rate)  else 0 end as day27_grnvalue, 
case when dayofmonth(qc_rm_ticketdate) = 28 then sum(qc_rm_acceptqty)  else 0 end as day28_grnwt, case when dayofmonth(qc_rm_ticketdate) = 28 then sum(qc_rm_acceptqty/1000 * qc_rm_rate)  else 0 end as day28_grnvalue, 
case when dayofmonth(qc_rm_ticketdate) = 29 then sum(qc_rm_acceptqty)  else 0 end as day29_grnwt, case when dayofmonth(qc_rm_ticketdate) = 29 then sum(qc_rm_acceptqty/1000 * qc_rm_rate)  else 0 end as day29_grnvalue, 
case when dayofmonth(qc_rm_ticketdate) = 30 then sum(qc_rm_acceptqty)  else 0 end as day30_grnwt, case when dayofmonth(qc_rm_ticketdate) = 30 then sum(qc_rm_acceptqty/1000 * qc_rm_rate)  else 0 end as day30_grnvalue, 
case when dayofmonth(qc_rm_ticketdate) = 31 then sum(qc_rm_acceptqty)  else 0 end as day31_grnwt, case when dayofmonth(qc_rm_ticketdate) = 31 then sum(qc_rm_acceptqty/1000 * qc_rm_rate)  else 0 end as day31_grnvalue, 
sum(qc_rm_acceptqty)  as total_grnwt, sum(qc_rm_acceptqty/1000 * qc_rm_rate) as total_grnvalue   from trn_qc_rm_inspection , massal_customer , masrm_item_header , mas_area where qc_rm_area = area_code and qc_rm_itemcode = itmh_code and qc_rm_supcode = cust_code 
and qc_rm_fincode = finid and qc_rm_compcode = compcode and  qc_rm_ticketdate between fromdate and todate
group by cust_name,qc_rm_ticketdate
) a group by cust_name  order by cust_name;

END ;;
DELIMITER ;
