CREATE DEFINER=`root`@`%` PROCEDURE `spqc_rm_inspection`(compcode int,fincode int,entryno int,fromdate date,todate date)
BEGIN
if todate < '2023-10-01' then
	if entryno > 0 then
	select * from trn_qc_rm_inspection , masrm_item_header,massal_customer, mas_area where 
	qc_rm_supcode = cust_code and qc_rm_itemcode = itmh_code and  qc_rm_area = area_code and 
	qc_rm_compcode = compcode and qc_rm_fincode = fincode and qc_rm_entryno = entryno  order by qc_rm_slno;
	ELSE
	select * from trn_qc_rm_inspection , masrm_item_header,massal_customer, mas_area where 
	qc_rm_supcode = cust_code and qc_rm_itemcode = itmh_code and  qc_rm_area = area_code and 
	qc_rm_compcode = compcode and qc_rm_fincode = fincode and qc_rm_ticketdate between fromdate and todate ;
	END IF;
else
	if entryno > 0 then
	select * from trn_qc_rm_inspection , masrm_item_header,massal_customer, mas_area where 
	qc_rm_supcode = cust_code and qc_rm_itemcode = itmh_code and  qc_rm_area = area_code and 
	qc_rm_compcode = compcode and qc_rm_fincode = fincode and qc_rm_entryno = entryno  and qc_rm_rate > 0 order by qc_rm_slno;
	ELSE
	select * from trn_qc_rm_inspection , masrm_item_header,massal_customer, mas_area where 
	qc_rm_supcode = cust_code and qc_rm_itemcode = itmh_code and  qc_rm_area = area_code and 
	qc_rm_compcode = compcode and qc_rm_fincode = fincode and qc_rm_ticketdate between fromdate and todate  and qc_rm_rate > 0;
	END IF;

end if;

END ;;
DELIMITER ;
