CREATE DEFINER=`root`@`%` PROCEDURE `spqc_rm_party_itemwise_abstract`(compcode int,finid int, fromdate date,todate date)
BEGIN
select  cust_name,case when itmh_type = 2 then 'IMPORT' else 'LOCAL' end as rmtype, itmh_name,sum(qc_rm_ticketwt/1000) as tickewt ,
sum(qc_rm_millboard/1000) as milboard ,
sum(qc_rm_act_moisure_qty/1000) as actmoiswt ,
sum(qc_rm_moisqty/1000) as moiswt ,
sum(qc_rm_degradeqty/1000) as degradewt ,
sum(qc_rm_rejectqty/1000) as rejectwt ,
sum(qc_rm_acceptqty/1000) as acceptwt, 
sum(qc_rm_acceptqty/1000*qc_rm_rate) as purvalue,
sum(qc_rm_acceptqty/1000*qc_rm_rate)/sum(qc_rm_acceptqty)  as avgrate
from trn_qc_rm_inspection , massal_customer , masrm_item_header , mas_area where qc_rm_area = area_code and qc_rm_itemcode = itmh_code and qc_rm_supcode = cust_code 
and qc_rm_fincode = finid and qc_rm_compcode = compcode and qc_rm_ticketdate between fromdate and todate
group by cust_name,rmtype,itmh_name;
END ;;
DELIMITER ;
