/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`%` PROCEDURE `sprep_Areawise_despatch_Prodn_pending`(compcode int ,fincode int , AsonDate date )
BEGIN

select area_name, cust_ref, sum(stk_wt) stk_wt , sum(prodnpending)  prodnpending , sum(L8Days) L8Days, sum(M7L16Days) M7L16Days, sum(M15L30Days) M15L30Days, sum(M30Days) M30Days  , 
case when sum(prodnpending) = 0  then 1 else 2 end as printorder from (
select 
area_name, cust_ref, sum(stk_wt) stk_wt, diffdays,sum(prodnpending) prodnpending,case when diffdays < 8 then sum(stk_wt) else 0 end as L8Days,
case when diffdays > 7 and diffdays <= 15   then sum(stk_wt) else 0 end as M7L16Days,
case when diffdays > 15 and diffdays <= 30   then sum(stk_wt) else 0 end as M15L30Days,
case when diffdays > 30 then sum(stk_wt) else 0 end as M30Days
 from
(
					select area_name,cust_ref , stk_sono , stk_var_code , stk_wt /1000 stk_wt, DATEDIFF( AsonDate, stk_ent_date)  as diffdays , 0 prodnpending 
                     from trnsal_finish_stock , trnsal_order_header , massal_customer,
					massal_variety , masprd_variety ,masprd_type ,massal_shade , massal_area ,massal_repr  
					where cust_repr = repr_code and  cust_area =  area_code and  var_shade = shade_shortcode and 
					stk_comp_code = ordh_comp_code and 
					stk_sono = ordh_sono and  
					ordh_party = cust_code and  cust_code not in (2151,4886)  and 
                    stk_destag = '' and
			-- 	    CHAR_LENGTH(ordh_sono) = 6 and 
            --  	( stk_destag = '' o r  (stk_destag <> '' and  stk_desdt > todate ) or  (stk_deltag = 'T' and  stk_deldate > todate) )  and                    
					stk_var_code = var_code and
					var_grpcode = var_groupcode  and  
					vargrp_type_code = var_typecode and 
					stk_ent_date <= AsonDate and 
					stk_comp_code = compcode  and  stk_finyear <= fincode  
                    
                union all
                
                select area_name,cust_ref ,stk_sono, stk_var_code , 0 stk_wt,0 diffdays , prodnpending_qty prodnpending from (
