			case when ordt_clo_stat = '' or  ordt_clo_stat = 'N'  then ordt_qty -  ordt_fin_wt else 0 end as prodnpending_qty , 
			case when ordt_clo_stat = ''  or  ordt_clo_stat = 'N' then ordt_qty * 0.05  else  ordt_fin_wt * 0.05 end as tolarance  
			from trnsal_order_header, trnsal_order_trailer , massal_customer  , massal_area  , massal_variety where 	
