CREATE DEFINER=`root`@`%` PROCEDURE `sprep_dc_vou_print`(compcode int,fincode int,dcno int)
BEGIN
select * from trn_delivery_challan  h, trn_delivery_challan_reellist r ,  massal_customer  ,massal_variety ,masprd_variety , masprd_type
where h.dc_cutter = cust_code
and r.dc_size = var_code
and var_grpcode = var_groupcode 
and var_typecode = vargrp_type_code and h.dc_seqno = r.dc_seqno 
and h.dc_comp_code = compcode and h.dc_fincode = fincode and h.dc_no = dcno;
END ;;
