CREATE DEFINER=`root`@`%` PROCEDURE `sprep_despatchpending_godown_stock`(
compcode int ,fincode int  , asondate date  , reeloption varchar(10)
)
BEGIN

declare fixcondition varchar(100);


if reeloption = "A" then
  set fixcondition = 'F,B';
else
    set fixcondition = reeloption; 
end if;    

select  * from(
			select * , case when (var_inchcm = 'I' and  var_size2 > 16)  then  'F'  else case when (var_inchcm = 'C' and var_size2 > 41)  then 'F' else 'B' end end as reeltype   from trnsal_finish_stock , trnsal_order_header , massal_customer,
			massal_variety , masprd_variety ,masprd_type, massal_repr
			where
            cust_repr = repr_code and 
			stk_comp_code = ordh_comp_code and 
			stk_sono = ordh_sono and  
			ordh_party = cust_code and -- stk_destag = '' and
			( stk_destag = '' or  (stk_destag <> '' and  stk_desdt > asondate ) or  (stk_deltag = 'T' and  stk_deldate > asondate) )  and                
			stk_var_code = var_code and
			var_grpcode = var_groupcode  and 			
			vargrp_type_code = var_typecode   and
			stk_ent_date <= asondate and  ordh_party =  2151 and
			stk_comp_code = compcode  and  stk_finyear <= fincode 
) a1  where  FIND_IN_SET(reeltype,fixcondition);   
END ;;
