CREATE DEFINER=`root`@`%` PROCEDURE `sprep_despatchpending_Repwise`(compcode int ,fincode int , fromdate date , todate date, asondate date , dateopt int,repcode int)
BEGIN
if repcode = 0 then
	if dateopt = 1 then
				select * from trnsal_finish_stock , trnsal_order_header , massal_customer,
				massal_variety , masprd_variety ,masprd_type ,massal_shade , massal_area ,massal_repr  
				where cust_repr = repr_code and  cust_area =  area_code and  var_shade = shade_shortcode and 
				stk_comp_code = ordh_comp_code and 
		--  	stk_finyear >= ordh_fincode and
				stk_sono = ordh_sono and  
				ordh_party = cust_code and  cust_code <> 2151 and 
				stk_destag = '' and
		--  	( stk_destag = '' o r  (stk_destag <> '' and  stk_desdt > todate ) or  (stk_deltag = 'T' and  stk_deldate > todate) )  and                    
				stk_var_code = var_code and
				var_grpcode = var_groupcode  and  
				vargrp_type_code = var_typecode and 
				stk_ent_date <= asondate and 
				stk_comp_code = compcode  and  stk_finyear <= fincode  ;		
	else
				select * from trnsal_finish_stock , trnsal_order_header , massal_customer,
				massal_variety , masprd_variety ,masprd_type ,massal_shade , massal_area ,massal_repr  
				where cust_repr = repr_code and  cust_area =  area_code and  var_shade = shade_shortcode and 
				stk_comp_code = ordh_comp_code and 
-- 				stk_finyear >= ordh_fincode and
				stk_sono = ordh_sono and  
				ordh_party = cust_code and  cust_code <> 612 and 
				stk_destag = '' and
		--  	( stk_destag = '' o r  (stk_destag <> '' and  stk_desdt > todate ) or  (stk_deltag = 'T' and  stk_deldate > todate) )  and                    
				stk_var_code = var_code and
				var_grpcode = var_groupcode  and  
				vargrp_type_code = var_typecode and 
				stk_ent_date >= fromdate and 
				stk_ent_date <= todate and 
				stk_comp_code = compcode  and  stk_finyear <= fincode ;		
	end if;   
else 
	if dateopt = 1 then
				select * from trnsal_finish_stock , trnsal_order_header , massal_customer,
				massal_variety , masprd_variety ,masprd_type ,massal_shade , massal_area ,massal_repr  
				where cust_repr = repr_code and  cust_area =  area_code and  var_shade = shade_shortcode and 
				stk_comp_code = ordh_comp_code and 
	-- 			stk_finyear >= ordh_fincode and
				stk_sono = ordh_sono and  
							cust_repr = repcode and
				ordh_party = cust_code and  cust_code <> 2151 and 
				stk_destag = '' and
		--  	( stk_destag = '' o r  (stk_destag <> '' and  stk_desdt > todate ) or  (stk_deltag = 'T' and  stk_deldate > todate) )  and                    
				stk_var_code = var_code and
				var_grpcode = var_groupcode  and  
				vargrp_type_code = var_typecode and 
				stk_ent_date <= asondate and 
				stk_comp_code = compcode  and  stk_finyear <= fincode  ;		
	else
				select * from trnsal_finish_stock , trnsal_order_header , massal_customer,
				massal_variety , masprd_variety ,masprd_type ,massal_shade , massal_area ,massal_repr  
				where cust_repr = repr_code and  cust_area =  area_code and  var_shade = shade_shortcode and 
				stk_comp_code = ordh_comp_code and 
-- 				stk_finyear >= ordh_fincode and
				stk_sono = ordh_sono and  
				ordh_party = cust_code and  cust_code <> 612 and 
							cust_repr = repcode and
				stk_destag = '' and
		--  	( stk_destag = '' o r  (stk_destag <> '' and  stk_desdt > todate ) or  (stk_deltag = 'T' and  stk_deldate > todate) )  and                    
				stk_var_code = var_code and
				var_grpcode = var_groupcode  and  
				vargrp_type_code = var_typecode and 
				stk_ent_date >= fromdate and 
				stk_ent_date <= todate and 
				stk_comp_code = compcode  and  stk_finyear <= fincode ;		
	end if;                  
end if;                  
END ;;
DELIMITER ;
