CREATE DEFINER=`root`@`%` PROCEDURE `sprep_dn_detials`(compcode int,fincode int,fromdate datetime , todate datetime)
BEGIN
select * from trn_delivery_note a,  massal_customer b, massal_variety c ,masprd_variety d,massal_repr e where   cust_repr = repr_code and c.var_grpcode = d.var_groupcode and  a.dn_custcode = b.cust_code and a.dn_size = c.var_code and a.dn_fincode = fincode  and a.dn_comp_code = compcode  and dn_date between fromdate and todate;
END ;;
