CREATE DEFINER=`root`@`%` PROCEDURE `sprep_prod_machine_efficiency`(compcode int, fincode int,startdate date, enddate date )
BEGIN
 select  spvr_name, prdh_shift,DATE_FORMAT(prd_date, '%d-%m-%Y') as prddate, prd_date ,round(var_gsm,0) var_gsm,sum(prd_rollwt) actprodn , sum(prd_runmins) runmins ,
 sum(prd_breakmins) breakmins ,tspeed,tprdn_hr,tdeckle,tprdn_min ,
round(tprdn_min * sum(prd_runmins),3)   as tar_prodn,round(avg(prd_speed),0) runspeed ,round(avg(prd_deckle),0) rundeckle
 from 
 trn_dayprod_header, 
 trn_dayprod_roll_details , masprd_variety , masprd_target , mas_supervisor  where
 spvr_code = prdh_operator and
 prd_date = prdh_date and prdh_shift = prd_shift and
 prd_compcode = prdh_compcode and prd_fincode =  prdh_fincode and
  tgsm = var_gsm and 
 prd_variety = var_groupcode  and prd_date between startdate and enddate and  prd_compcode = compcode and prd_fincode = fincode  
 group by spvr_name, prdh_shift,prd_date , var_gsm,tspeed,tprdn_hr,tdeckle,tprdn_min  order by prdh_date, prdh_shift, spvr_name;
END ;;
DELIMITER ;
