CREATE DEFINER=`root`@`%` PROCEDURE `sprep_prod_rollwise_deckle_loss`(compcode int, fincode int,fromdate date, todate date)
BEGIN
select  prd_date,DATE_FORMAT(prd_date, '%d-%m-%Y') as prdh_date,prd_shift,prd_rollno,var_desc quality,  prd_deckle, prd_rwdeck, cast((prd_deckle - prd_rwdeck) as decimal(5,1)) as lossdeck,
cast(cast((prd_deckle - prd_rwdeck) as decimal(5,1))/prd_deckle*100 as decimal(5,2)) as loss_per
from trn_dayprod_roll_details , masprd_variety  where prd_variety = var_groupcode and prd_compcode = compcode and  prd_fincode =  fincode and  prd_date between fromdate and todate
order by prd_date,prd_shift,prd_rollno;  
END ;;
DELIMITER ;
