CREATE DEFINER=`root`@`%` PROCEDURE `sprep_prod_roll_finished`(compcode int, fincode int,fromdate date, todate date)
BEGIN
select  *  from  (select date_format(prd_date,"%y%m")  as yymm ,  prd_compcode ,prd_fincode,  prd_rollno,sum(prd_rollwt) as prd_rollwt  from trn_dayprod_roll_details where prd_compcode = compcode and prd_fincode =fincode and   prd_date between fromdate and  todate group by 
prd_compcode ,prd_fincode,  prd_rollno,date_format(prd_date,"%y%m") ) a  , 
trnsal_finish_stock b , massal_variety c ,masprd_variety d ,trnsal_order_header e,massal_customer f
where stk_sono = ordh_sono  and ordh_party = cust_code and prd_rollno = stk_rollno and 
substr(yymm,1,2)  =  substr(stk_yymm,1,2) and 
substr(yymm,3,2) = substr(stk_yymm,3,2) and 
stk_var_code = var_code and
var_grpcode = var_groupcode and stk_source = 'R' and
prd_compcode = stk_comp_code and prd_fincode = stk_finyear order by prd_rollno;  
END ;;
DELIMITER ;
