CREATE DEFINER=`root`@`%` PROCEDURE `sprep_prod_roll_fin_abstract`(compcode int, fincode int,fromdate date, todate date)
BEGIN
/*
select a1.*,case when b1.reason is NULL then '' else b1.reason end as prd_reason , prd_deckle,prd_rwdeck from 
(select prd_rollno ,var_desc , prd_rollwt ,sum(stk_wt)/1000 as finwt  from 
(select date_format(prd_date,"%y%m")  as yymm ,  prd_compcode ,prd_fincode,  prd_rollno,sum(prd_rollwt) as prd_rollwt from trn_dayprod_roll_details where prd_compcode = compcode and prd_fincode =  fincode and   prd_date between fromdate and todate group by 
prd_compcode ,prd_fincode,  prd_rollno,date_format(prd_date,"%y%m")) a 
left join trnsal_finish_stock b  on
a.prd_rollno = b.stk_rollno and 
a.yymm  = b.stk_yymm
left join massal_variety c on
b.stk_var_code = c.var_code 
left join masprd_variety d on
c.var_grpcode =  d.var_groupcode 
group  by prd_rollno ,var_desc,prd_rollwt
)a1 left join 
(select prd_rollno,var_desc ,prd_deckle,prd_rwdeck ,GROUP_CONCAT(prd_reason)  as reason from trn_dayprod_roll_details , masprd_variety  where prd_variety = var_groupcode and prd_compcode = compcode and prd_fincode =  fincode and   prd_date between fromdate and todate group by 
prd_rollno,prd_deckle,prd_rwdeck,var_desc) b1
on a1.prd_rollno = b1.prd_rollno and a1.var_desc = b1.var_desc;
*/
select a1.*,case when b1.reason is NULL then '' else b1.reason end as prd_reason , prd_deckle,prd_rwdeck from 
(select prd_rollno ,var_desc , prd_rollwt ,sum(stk_wt)/1000 as finwt  from 
(select date_format(prd_date,"%y%m")  as yymm ,  prd_compcode ,prd_fincode,  prd_rollno,sum(prd_rollwt) as prd_rollwt from trn_dayprod_roll_details where prd_compcode = compcode and prd_fincode =  fincode and   prd_date between fromdate and todate group by 
prd_compcode ,prd_fincode,  prd_rollno,date_format(prd_date,"%y%m")) a 
left join trnsal_finish_stock b  on
a.prd_rollno = b.stk_rollno and 
a.yymm  = b.stk_yymm
left join massal_variety c on
b.stk_var_code = c.var_code 
left join masprd_variety d on
c.var_grpcode =  d.var_groupcode 
group  by prd_rollno ,var_desc,prd_rollwt
)a1 left join 
(select prd_rollno,var_desc ,avg(prd_deckle) prd_deckle,avg(prd_rwdeck) prd_rwdeck ,GROUP_CONCAT(prd_reason)  as reason from trn_dayprod_roll_details , masprd_variety  where prd_variety = var_groupcode and prd_compcode = compcode and prd_fincode =  fincode and   prd_date between fromdate and todate group by 
prd_rollno,var_desc) b1
on a1.prd_rollno = b1.prd_rollno  and a1.var_desc = b1.var_desc;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
