DELIMITER ;;
CREATE DEFINER=`root`@`%` PROCEDURE `sprep_prod_roll_fin_abstract_new`(compcode int, fincode int,fromdate date, todate date)
BEGIN
select yymm , prd_rollno,prd_rollwt , prd_deckle, prd_rwdeck , reason ,sum(stk_wt)/1000 as finwt  from
(
select date_format(prd_date,"%y%m")  as yymm , prd_rollno,sum(prd_rollwt) prd_rollwt ,avg(prd_deckle) prd_deckle,avg(prd_rwdeck) prd_rwdeck ,GROUP_CONCAT(prd_reason)  as reason from trn_dayprod_roll_details , masprd_variety  where prd_variety = var_groupcode and prd_compcode = compcode and prd_fincode =  fincode and   prd_date between fromdate and todate  group by prd_date,prd_rollno
) a
left join trnsal_finish_stock b  on
a.prd_rollno = b.stk_rollno and 
a.yymm  = b.stk_yymm
 group by yymm , prd_rollno,prd_rollwt , prd_deckle, prd_rwdeck , reason order by prd_rollno;
 END ;;
DELIMITER ;
