CREATE DEFINER=`root`@`%` PROCEDURE `sprep_prod_roll_pending`(compcode int, fincode int,fromdate date, todate date)
BEGIN
select prd_date,prd_rollno,prd_variety,var_desc,sum(prd_rollwt) as rollwt  from trn_dayprod_roll_details , masprd_variety where prd_compcode = compcode and prd_fincode = fincode and  prd_date between fromdate and todate 
and prd_variety = var_groupcode and  prd_rollno  not in (select stk_rollno from trnsal_finish_stock where stk_comp_code = compcode and stk_finyear = fincode  and  
substr(stk_yymm,1,2) = date_format(fromdate,"%y")  and 
substr(stk_yymm,3,2) = date_format(fromdate,"%m")  
group by  stk_rollno)
group by prd_date,prd_rollno,prd_variety,var_desc;
END ;;
