CREATE DEFINER=`root`@`%` PROCEDURE `sprep_sal_b2binvoices`(compcode int ,fromdate date,todate date)
BEGIN
select  left(cust_ref,20) as cust_ref ,cust_gstin,count(*) as voucount ,sum(invh_taxableamt) as taxable,
sum(invh_igst_amt) as igst,
sum(invh_cgst_amt) as cgst,
sum(invh_sgst_amt) as sgst,
sum(invh_netamt) as invamt
from trnsal_invoice_header ,massal_customer 
where invh_comp_code = compcode and invh_party = cust_code and invh_date between fromdate and todate group by cust_ref ,cust_gstin order by cust_ref;
END ;;
