CREATE DEFINER=`root`@`%` PROCEDURE `sprep_sal_qualitywise`(compcode int ,fincode int , fromdate date,todate date,
quality varchar(200), customer varchar(1000) , qlyopt int ,custopt int)
BEGIN
-- if qlyopt = 0 and custopt = 0 then
	select month(invh_date) as despmonth,
	case when left(var_desc,4) =   "KP00" then  left(var_desc,2)   else left(var_desc,4) end as bf,
    case when left(var_desc,4) =   "KP00" then concat(left(var_desc,2),' ',substr(var_desc,8,6))  else var_desc end as quality ,var_gsm,cust_ref, Cast(sum(invt_wt)/1000  as Decimal(10,3))  as qty ,sum(invt_value) as beforetax from trnsal_invoice_header , massal_customer, trnsal_invoice_trailer , massal_variety , masprd_variety where 
	invh_party = cust_code and
	invh_seqno = invt_seqno and 
	invh_comp_code = invt_compcode and 
	invh_fincode = invt_fincode and 
	invt_var = var_code and
	var_grpcode = var_groupcode and
	invh_comp_code = compcode and invh_fincode = fincode and 
	invh_date between fromdate and todate
    -- and find_in_set(left(var_desc,4),quality) and find_in_set(cust_ref,customer) 
	group  by month(invh_date), var_desc,var_gsm,cust_ref order  by var_desc;
-- end if;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
