/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`%` PROCEDURE `sprep_sal_rep_custwise`(compcode int ,fincode int , fromdate date,todate date,repcode int ,partygrp int 
 , mm int,yy int
 )
BEGIN
if partygrp = 0 then
	if repcode = 0 then
		select 
		  cast(DATE_FORMAT(todate ,'%Y-%m-01 00:00:00') as date)   monthStartdate, cast(DATE_FORMAT(todate ,'%Y-%m-%d 00:00:00') as date) monthEnddate, repr_name,cust_ref,cust_cr_days,cust_desp_target,  cast(invh_date as date) invh_date ,Cast(sum(invt_wt)/1000  as Decimal(10,3))  as weight, cust_noof_visits,cust_payperf 
		from trnsal_invoice_header , massal_customer, trnsal_invoice_trailer , massal_variety , masprd_variety , massal_repr where 
		cust_repr = repr_code and
		invh_party = cust_code and
		invh_seqno = invt_seqno and 
		invh_comp_code = invt_compcode and 
		invh_fincode = invt_fincode and 
		invt_var = var_code and
		var_grpcode = var_groupcode and
		invh_comp_code = compcode and invh_fincode = fincode  and 
		invh_date between fromdate and todate 
		group  by repr_name,cust_ref,invh_date,cust_cr_days,cust_desp_target, cust_noof_visits,cust_payperf ;
	else
        select  cast(DATE_FORMAT(todate ,'%Y-%m-01 00:00:00') as date)  monthStartdate, cast(DATE_FORMAT(todate ,'%Y-%m-%d 00:00:00') as date)  monthEnddate, repr_name,cust_ref,massal_target.cust_cr_days,cust_desp_target,  cast(invh_date as date) invh_date , weight, cust_noof_visits,cust_payperf , cust_grade from 
		(
        select  
        invh_party , cast(invh_date as date) invh_date ,Cast(sum(invt_wt)/1000  as Decimal(10,3))  as weight 
		from trnsal_invoice_header , massal_customer, trnsal_invoice_trailer , massal_variety , masprd_variety , massal_repr where 
		cust_repr = repr_code and
		invh_party = cust_code and
		invh_seqno = invt_seqno and 
		invh_comp_code = invt_compcode and 
		invh_fincode = invt_fincode and 
		invt_var = var_code and
		var_grpcode = var_groupcode and
		invh_comp_code = compcode and invh_fincode = fincode  and 
		cust_repr = repcode and
		invh_date between fromdate and todate 
		group  by invh_party,invh_date)  a  
        right join massal_customer 	on  a.invh_party = massal_customer.cust_code
        join massal_repr  on massal_customer.cust_repr = massal_repr.repr_code and  massal_customer.cust_repr = repcode 
		left join massal_target  on massal_customer.cust_code = massal_target.customer_code  and massal_target.rmonth = mm and  massal_target.ryear = yy
        group by  monthStartdate, monthEnddate, repr_name,cust_ref,massal_target.cust_cr_days,cust_desp_target,  invh_date , weight, cust_noof_visits,cust_payperf, cust_grade ;  
	end if;
else
    if partygrp = 1 then
     
			select 
            cast(DATE_FORMAT(todate ,'%Y-%m-01 00:00:00') as date)   monthStartdate, cast(DATE_FORMAT(todate ,'%Y-%m-%d 00:00:00') as date) monthEnddate,
			repr_name,cust_group_name ,massal_target.cust_cr_days,cust_desp_target,  cast(invh_date as date) invh_date , weight, cust_noof_visits,cust_payperf, cust_grade 
            from  
            (
            select  
