CREATE DEFINER=`root`@`%` PROCEDURE `sprep_sal_rep_cust_grpwise`(compcode int ,fincode int , fromdate date,todate date,partygrp int )
BEGIN
        select 
        repr_name, cust_ref ,cust_cr_days,cust_desp_target,  cast(invh_date as date) invh_date ,Cast(sum(invt_wt)/1000  as Decimal(10,3))  as weight, cust_noof_visits,cust_payperf 
		from trnsal_invoice_header , massal_customer, trnsal_invoice_trailer , massal_variety , masprd_variety , massal_repr ,vewsal_custgroup where 
		cust_repr = repr_code and
		invh_party = cust_code and
		cust_partygroup = cust_group_code and 
		invh_seqno = invt_seqno and 
		invh_comp_code = invt_compcode and 
		invh_fincode = invt_fincode and 
		invt_var = var_code and
		var_grpcode = var_groupcode and
		invh_comp_code = 1 and invh_fincode = 22 and 
		invh_date between '2022-04-01' and '2022-06-17' and  cust_partygroup = 514      
		group  by repr_name,cust_ref,invh_date,cust_cr_days,cust_desp_target, cust_noof_visits,cust_payperf ;
END ;;
