			invh_date between  fromdate and todate 
			and ((massal_variety.var_inchcm = 'I' and  massal_variety.var_size2 <=16)  or
			(massal_variety.var_inchcm = 'C' and  massal_variety.var_size2 <=41))   
			group by month(invh_date) ,var_bf,var_gsm,var_shade,var_inchcm,var_size2


			union all
			
			select month(stk_ent_date) repmonth,var_bf,var_gsm,var_shade,var_inchcm,var_size2,0 as wt, sum(stk_wt)/1000 stkwt from trnsal_finish_stock,massal_variety,masprd_variety
			where stk_var_code = var_code 
			and	var_grpcode = var_groupcode and length(stk_sono) = 6
			and stk_destag = '' and stk_comp_code = 1 and ((massal_variety.var_inchcm = 'I' and  massal_variety.var_size2 <=16)  or
			(massal_variety.var_inchcm = 'C' and  massal_variety.var_size2 <=41))    group by  month(stk_ent_date),var_bf,var_gsm,var_shade,var_inchcm,var_size2
	 ) aa1 group by repmonth,var_bf, var_gsm, var_shade, var_inchcm, var_size2 ;   
	 
	else if stkopt = "F" then

	  select  repmonth,var_bf, var_gsm,var_shade,var_inchcm,var_size2,sum(wt) as wt , sum(stkwt) as stkwt from 
	(        
			select month(invh_date) repmonth,var_bf, var_gsm,var_shade,var_inchcm,var_size2,sum(invt_wt)/1000 as wt , 0 as stkwt
			from trnsal_invoice_header , massal_customer, trnsal_invoice_trailer , massal_variety , masprd_variety , massal_repr where 
			cust_repr = repr_code and
			invh_party = cust_code and
			invh_seqno = invt_seqno and 
			invh_comp_code = invt_compcode and 
			invh_fincode = invt_fincode and 
			invt_var = var_code and
			var_grpcode = var_groupcode and
			invh_comp_code = compcode and invh_fincode = fincode  and 
			invh_date between  fromdate and todate 
			and ((massal_variety.var_inchcm = 'I' and  massal_variety.var_size2 >16)  or
			(massal_variety.var_inchcm = 'C' and  massal_variety.var_size2 >41))  
			group by month(invh_date) ,var_bf,var_gsm,var_shade,var_inchcm,var_size2
	  

			
			union all
			
			select month(stk_ent_date) repmonth,var_bf,var_gsm,var_shade,var_inchcm,var_size2,0 as wt, sum(stk_wt)/1000 stkwt from trnsal_finish_stock,massal_variety,masprd_variety
			where stk_var_code = var_code 
			and	var_grpcode = var_groupcode and length(stk_sono) = 6
			and stk_destag = '' and stk_comp_code = 1 
			and ((massal_variety.var_inchcm = 'I' and  massal_variety.var_size2 >16)  or
			(massal_variety.var_inchcm = 'C' and  massal_variety.var_size2 >41)) 
			group by  month(stk_ent_date),var_bf,var_gsm,var_shade,var_inchcm,var_size2
	 ) aa1 group by repmonth, var_bf,var_gsm, var_shade, var_inchcm, var_size2 ;   
		
	else
	  select  repmonth,var_bf, var_gsm,var_shade,var_inchcm,var_size2,sum(wt) as wt , sum(stkwt) as stkwt from 
	(        
			select month(invh_date) repmonth,var_bf, var_gsm,var_shade,var_inchcm,var_size2,sum(invt_wt)/1000 as wt , 0 as stkwt
			from trnsal_invoice_header , massal_customer, trnsal_invoice_trailer , massal_variety , masprd_variety , massal_repr where 
			cust_repr = repr_code and
			invh_party = cust_code and
			invh_seqno = invt_seqno and 
			invh_comp_code = invt_compcode and 
			invh_fincode = invt_fincode and 
			invt_var = var_code and
			var_grpcode = var_groupcode and
			invh_comp_code =  compcode and invh_fincode = fincode and 
			invh_date between  fromdate and todate  
			group by month(invh_date) ,var_bf,var_gsm,var_shade,var_inchcm,var_size2
			  
			union all
			
			select month(stk_ent_date) repmonth,var_bf,var_gsm,var_shade,var_inchcm,var_size2,0 as wt, sum(stk_wt)/1000 stkwt from trnsal_finish_stock,massal_variety,masprd_variety
			where stk_var_code = var_code 
			and	var_grpcode = var_groupcode
			and stk_destag = '' and stk_comp_code = 1         
			group by  month(stk_ent_date),var_bf,var_gsm,var_shade,var_inchcm,var_size2
	 ) aa1 group by repmonth,var_bf, var_gsm, var_shade, var_inchcm, var_size2 ;   
	  
	end if;        
	end if;     
-- II
else 
	if stkopt = "B" then
	 select  repmonth,var_bf, var_gsm,var_shade,var_inchcm,var_size2,sum(wt) as wt , sum(stkwt) as stkwt from 
	(        


			select month(dn_date) repmonth,var_bf,var_gsm,var_shade,var_inchcm,var_size2, sum(dn_wt)/1000 wt , 0 as stkwt from trn_delivery_note,massal_variety,masprd_variety
			where dn_size = var_code 
			and	var_grpcode = var_groupcode
			 and dn_comp_code = compcode and dn_date between  fromdate and todate   and ((massal_variety.var_inchcm = 'I' and  massal_variety.var_size2 <=16)  or
			(massal_variety.var_inchcm = 'C' and  massal_variety.var_size2 <=41))    group by  month(dn_date),var_bf,var_gsm,var_shade,var_inchcm,var_size2
			
		 
			
			union all
			
			select month(stk_ent_date) repmonth,var_bf,var_gsm,var_shade,var_inchcm,var_size2,0 as wt, sum(stk_wt)/1000 stkwt from trnsal_finish_stock,massal_variety,masprd_variety
			where stk_var_code = var_code 
			and	var_grpcode = var_groupcode
			and stk_destag = '' and stk_comp_code = 1 and ((massal_variety.var_inchcm = 'I' and  massal_variety.var_size2 <=16)  or
			(massal_variety.var_inchcm = 'C' and  massal_variety.var_size2 <=41))    group by  month(stk_ent_date),var_bf,var_gsm,var_shade,var_inchcm,var_size2
	 ) aa1 group by repmonth,var_bf, var_gsm, var_shade, var_inchcm, var_size2 ;   
	 
	else if stkopt = "F" then

	  select  repmonth,var_bf, var_gsm,var_shade,var_inchcm,var_size2,sum(wt) as wt , sum(stkwt) as stkwt from 
	(        


			select month(dn_date) repmonth,var_bf,var_gsm,var_shade,var_inchcm,var_size2, sum(dn_wt)/1000 wt , 0 as stkwt from trn_delivery_note,massal_variety,masprd_variety
			where dn_size = var_code 
