CREATE DEFINER=`root`@`%` PROCEDURE `sprep_sample_vou_print`(compcode int,fincode int,dcno int)
BEGIN
select * from trnsal_sample ,  massal_customer  ,massal_variety ,masprd_variety , masprd_type
where rs_customer = cust_code
and rs_sizecode = var_code
and var_grpcode = var_groupcode 
and var_typecode = vargrp_type_code 
and rs_compcode = compcode and rs_finyear = fincode and rs_entno = dcno;
END ;;
