CREATE DEFINER=`root`@`%` PROCEDURE `sprep_stores_delivery_challan`(compcode int,fincode int,dctype char(1),dcno int)
BEGIN
/*

 select * from trnpur_deliverychallan_header a,trnpur_deliverychallan_trailer b,maspur_supplier_master c ,mas_item_master d , mas_uom e 
where item_uom = uom_code and dch_comp_code = dct_comp_code and dch_fincode = dct_fincode and dch_no = dct_no  and dch_type = dct_type and dct_item_code = item_code and  dch_party = sup_code 
 and dch_comp_code = compcode and dch_fincode = fincode and dch_type = dctype and dch_no = dcno;
*/ 
select * from trnpur_deliverychallan_header a,trnpur_deliverychallan_trailer b,massal_customer c ,maspur_item_header d , mas_uom e 
where item_uom = uom_code and dch_comp_code = dct_comp_code and dch_fincode = dct_fincode and dch_no = dct_no  and dch_type = dct_type and dct_item_code = item_code and  dch_party = cust_code 
 and dch_comp_code = compcode and dch_fincode = fincode and dch_type = dctype and dch_no = dcno;
END ;;
