CREATE DEFINER=`root`@`%` PROCEDURE `sprep_stores_return_pendinglist`(compcode int,fincode int,asondate date,fromdate date,todate date,opt int)
BEGIN
if opt = 1 then
	select * , DATE_ADD(dch_date, INTERVAL dch_return_days day) duedate , DATEDIFF( curdate(),dch_date) oddays,
	DATE_FORMAT(dch_date, '%d-%m-%Y') dc_date, DATE_FORMAT(DATE_ADD(dch_date, INTERVAL dch_return_days day), '%d-%m-%Y')  duedate2 , dct_issqty -dct_recqty pendqty
	from trnpur_deliverychallan_header a,trnpur_deliverychallan_trailer b,massal_customer c ,maspur_item_header d , mas_uom e , mas_department f
	where  dch_dept = department_code and  item_uom = uom_code and dch_comp_code = dct_comp_code and dch_fincode = dct_fincode and dch_no = dct_no  and dch_type = dct_type and dct_item_code = item_code and  dch_party = cust_code 
	and dch_comp_code = compcode and dch_fincode <= fincode and dch_type = 'R' and dch_date <= asondate
	and dct_issqty > dct_recqty order by department_name; 
else if opt = 2 then
	select * , DATE_ADD(dch_date, INTERVAL dch_return_days day) duedate , DATEDIFF( curdate(),dch_date) oddays,
	DATE_FORMAT(dch_date, '%d-%m-%Y') dc_date, DATE_FORMAT(DATE_ADD(dch_date, INTERVAL dch_return_days day), '%d-%m-%Y')  duedate2 , dct_issqty -dct_recqty pendqty
	from trnpur_deliverychallan_header a,trnpur_deliverychallan_trailer b,massal_customer c ,maspur_item_header d , mas_uom e , mas_department f
	where  dch_dept = department_code and  item_uom = uom_code and dch_comp_code = dct_comp_code and dch_fincode = dct_fincode and dch_no = dct_no  and dch_type = dct_type and dct_item_code = item_code and  dch_party = cust_code 
	and dch_comp_code = compcode and dch_fincode <= fincode and dch_type = 'R' and dch_date <= asondate
	and dct_issqty > dct_recqty order by dch_date;     
else
	select * , DATE_ADD(dch_date, INTERVAL dch_return_days day) duedate , DATEDIFF( curdate(),dch_date) oddays,
	DATE_FORMAT(dch_date, '%d-%m-%Y') dc_date, DATE_FORMAT(DATE_ADD(dch_date, INTERVAL dch_return_days day), '%d-%m-%Y')  duedate2 , dct_issqty -dct_recqty pendqty
	from trnpur_deliverychallan_header a,trnpur_deliverychallan_trailer b,massal_customer c ,maspur_item_header d , mas_uom e , mas_department f
	where  dch_dept = department_code and  item_uom = uom_code and dch_comp_code = dct_comp_code and dch_fincode = dct_fincode and dch_no = dct_no  and dch_type = dct_type and dct_item_code = item_code and  dch_party = cust_code 
	and dch_comp_code = compcode and dch_fincode = fincode and dch_type = 'R' and dch_date between fromdate and todate
	order by department_name; 
end if;
end if;
END ;;
DELIMITER ;
