CREATE DEFINER=`root`@`%` PROCEDURE `sprm_insupd_stockdetails`(
p_stk_compcode int,
p_stk_lotno int,
p_stk_itemcode int,
p_stk_qty numeric(10,3)
)
begin 
declare v_stkcnt int;  declare v_stk_seqno int;

select count(*) into v_stkcnt from trnrm_stockdetails 
where stk_compcode=p_stk_compcode and stk_lotno=p_stk_lotno and 
stk_itemcode=p_stk_itemcode;

if v_stkcnt <= 0
then

	SET v_stk_seqno = (select IFNULL(max(stk_seqno),0)+1 as stk_seqno from trnrm_stockdetails);
	insert into trnrm_stockdetails(
	stk_seqno,stk_compcode,stk_lotno,stk_itemcode,stk_qty
    )
	values 
	(v_stk_seqno,p_stk_compcode,p_stk_lotno,p_stk_itemcode,
    p_stk_qty);

else
	update trnrm_stockdetails set stk_qty = stk_qty + p_stk_qty
			where stk_compcode=p_stk_compcode and 
				stk_lotno=p_stk_lotno and 
				stk_itemcode=p_stk_itemcode;
end if;
END ;;
DELIMITER ;
