CREATE DEFINER=`root`@`%` PROCEDURE `sprm_ins_issret_trailer_new`(
	p_hdseqno	int,
	p_seqno	tinyint unsigned,
	p_vartype	int,
	p_itmcode	int,
	p_qty		numeric	(13,3),
	p_rate		numeric	(14,2),
	p_values	numeric	(14,2),
	p_company	int,
	p_fincode	int
	)
begin
	insert into trnrm_issret_trailer (isrt_hdseqno, isrt_seqno, isrt_varty, isrt_itemcode, isrt_qty, isrt_rate, isrt_values)
	values  (p_hdseqno, p_seqno,   p_vartype, p_itmcode,p_qty,p_rate, p_values);
/*
 call sprm_insupd_stockdetails( p_company,p_lotseqno,p_itmcode,p_qty,
p_billqty,p_bags); 
  */
	update masrm_item_trailer set 	itmt_clqty = itmt_clqty + p_qty,
					itmt_clbillqty = itmt_clbillqty + p_billqty,
                    itmt_clvalue = itmt_clvalue +  p_values,
					itmt_clbags = itmt_clbags + p_bags
					where  itmt_hdcode = p_itmcode and
						   itmt_compcode = p_company and
						   itmt_fincode = p_fincode;  
END ;;
DELIMITER ;
