DELIMITER ;;
CREATE DEFINER=`root`@`%` PROCEDURE `sprm_ins_issue_trailer`(
     p_company int,  
	 p_fincode int,  
     p_hdseqno int,  
     p_seqno tinyint unsigned,  
     p_itmcode int,  
     p_vartype int,  
     p_qty  numeric (13,3),  
     p_rate  numeric (14,2),  
     p_values numeric (14,2)  
)
begin  
 insert into trnrm_issue_trailer (isst_hdseqno, isst_seqno, isst_itmcode, isst_varty, isst_qty, isst_rate, isst_values  )  
 values  (p_hdseqno,   p_seqno,    p_itmcode,   p_vartype,    
 p_qty,    p_rate,   p_values);  
 /* 
  update trnrm_stockdetails set stk_qty = case when stk_qty -  p_qty <0 then 0 
  else stk_qty -  p_qty end  
	 where stk_compcode=p_company and   
	 stk_lotno=p_lotseqno and stk_itemcode=p_itmcode;   
*/     
  update masrm_item_trailer set  itmt_clqty = case when itmt_clqty - p_qty<0 then 0 
  else itmt_clqty - p_qty end ,  

     itmt_clvalue = case when itmt_clvalue - p_values <0 then 0 
     else  itmt_clvalue - p_values end  

                    where  itmt_hdcode = p_itmcode and  
                  itmt_compcode = p_company and  
                  itmt_fincode = p_fincode;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `sprm_ins_item_trailer` */;
