/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`%` PROCEDURE `sprm_ins_item_trailer`( compcode int, itemcode int)
BEGIN
   DECLARE done1 INT DEFAULT FALSE;
    DECLARE vfincode INT;
    DECLARE vfinyear INT;
    declare finyear cursor for select fin_code from mas_finyear where fin_code >=22;
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET done1 = TRUE;
	OPEN finyear;
       ins_loop1: LOOP
		FETCH finyear INTO vfincode;
		IF done1 THEN
        	  LEAVE ins_loop1;
		END IF;
        insert into masrm_item_trailer values (itemcode, compcode,vfincode,0, 0, 0, 0, 0);
	 END loop;
     CLOSE finyear;
END ;;
DELIMITER ;
