CREATE DEFINER=`root`@`%` PROCEDURE `sprm_ins_receipt_header`(
p_rech_seqno int,          
p_rech_compcode int,          
p_rech_fincode int,          
p_rech_no varchar(12),          
p_rech_sup_code int,          
p_rech_ordhdseqno int,    
p_rech_crdays int,          
p_rech_date datetime(3),                
p_rech_area_code smallint,          
p_rech_truckno varchar(20),   
p_rech_freighttype varchar(1),          
p_rech_itemvalue numeric(12,2),          
p_rech_sgst_per numeric(5,2),     
p_rech_sgst_amt numeric(12,2),          
p_rech_cgst_per numeric(5,2),     
p_rech_cgst_amt numeric(12,2),          
p_rech_igst_per numeric(5,2),     
p_rech_igst_amt numeric(12,2),          
p_rech_tcs_per numeric(5,2),     
p_rech_tcs_amt numeric(12,2),          
p_rech_freight numeric(12,2),          
p_rech_otheramt numeric(12,2),  
p_rech_roundingoff numeric(3,2),          
p_rech_totalamount numeric(12,2),          
p_rech_billno varchar(40),          
p_rech_billdate datetime(3),          
p_rech_billvalue numeric(14,2),          
p_rech_usr_code int,          
p_rech_entry_date datetime(3),          
p_rech_geno varchar(20),          
p_rech_gedate datetime(3),
p_rech_acc_seqno numeric(10),
