p_paymode varchar(10),   
p_tcsround varchar(1),    
p_gstauto varchar(1) ,
p_others  numeric(8,2), 
p_others_ledger int,
p_grnstatus varchar(1)   
)
begin           
insert into trnrm_receipt_header(          
 rech_seqno, rech_compcode, rech_fincode, rech_no, rech_sup_code, rech_ordhdseqno ,rech_crdays,rech_date,
 rech_area_code,rech_truckno,rech_freighttype, rech_itemvalue, rech_sgst_per, rech_sgst_amt, rech_cgst_per, rech_cgst_amt,
 rech_igst_per, rech_igst_amt, rech_tcs_per, rech_tcs_amt, rech_freight, rech_otheramt ,rech_roundingoff, rech_totalamount,
 rech_billno, rech_billdate, rech_billvalue, rech_usr_code, rech_entry_date, rech_geno, rech_gedate, rech_acc_seqno,rech_roundneeded ,rech_qc_ins_no ,
 rech_purledger,rech_source,rech_accdate,rech_acctflag,rech_paymode,rech_tcs_round_yn,
