CREATE DEFINER=`root`@`%` PROCEDURE `sprm_rep_area_itemwise_arrivals`(compcode tinyint,finid tinyint,fromdate date,todate date)
BEGIN
SELECT
    vew_rm_receiptheadermerge.rech_seqno, vew_rm_receiptheadermerge.rech_compcode, vew_rm_receiptheadermerge.rech_fincode, vew_rm_receiptheadermerge.rech_no, vew_rm_receiptheadermerge.rech_date, vew_rm_receiptheadermerge.rech_freighttype, 
    vew_rm_receiptheadermerge.rech_itemvalue, 
    vew_rm_receiptheadermerge.rech_freight, vew_rm_receiptheadermerge.rech_roundingoff, vew_rm_receiptheadermerge.rech_cgst_per, vew_rm_receiptheadermerge.rech_sgst_per, vew_rm_receiptheadermerge.rech_igst_per, vew_rm_receiptheadermerge.rech_tcs_per,
    vew_rm_receipttrailermerge.rect_grnqty, vew_rm_receipttrailermerge.rect_itemvalue,
    maspur_supplier_master.sup_refname,
    mas_area.area_name,
    masrm_item_group.itmg_code
FROM
    { oj ((((vew_rm_receiptheadermerge vew_rm_receiptheadermerge INNER JOIN maspur_supplier_master maspur_supplier_master ON
        vew_rm_receiptheadermerge.rech_sup_code = maspur_supplier_master.sup_code)
     INNER JOIN vew_rm_receipttrailermerge vew_rm_receipttrailermerge ON
        vew_rm_receiptheadermerge.type = vew_rm_receipttrailermerge.type AND
    vew_rm_receiptheadermerge.rech_seqno = vew_rm_receipttrailermerge.rect_hdseqno)
     INNER JOIN mas_area mas_area ON
        maspur_supplier_master.sup_area = mas_area.area_code)
     INNER JOIN masrm_item_header masrm_item_header ON
        vew_rm_receipttrailermerge.rect_item_code = masrm_item_header.itmh_code)
     INNER JOIN masrm_item_group masrm_item_group ON
        masrm_item_header.itmh_group = masrm_item_group.itmg_code}
WHERE
    vew_rm_receiptheadermerge.rech_compcode = compcode AND
    vew_rm_receiptheadermerge.rech_fincode = finid AND
    vew_rm_receiptheadermerge.rech_date >= fromdate AND
    vew_rm_receiptheadermerge.rech_date <= todate
ORDER BY
    mas_area.area_name ASC,
    maspur_supplier_master.sup_refname ASC,
    vew_rm_receiptheadermerge.rech_seqno ASC;
END ;;
DELIMITER ;
