CREATE DEFINER=`root`@`%` PROCEDURE `sprm_rep_area_party_monthwise_Arrivals`(compcode tinyint,fromdate date,todate date)
BEGIN
select  mas_area_repgrp_name,mas_area_repgrp_code,year(rech_date) grnyear,month(rech_date) grnmonth, monthname(rech_date) grnmonthname,sum(rect_itemvalue) itemvalue1 , sum(rect_grnqty) grnqty ,sum(rect_itemvalue) / sum(rect_grnqty) avgrate    FROM
    { oj (((((trnrm_receipt_header trnrm_receipt_header INNER JOIN massal_customer massal_customer ON
        trnrm_receipt_header.rech_sup_code = massal_customer.cust_code  and  massal_customer.cust_taxtag !=3 )
     INNER JOIN trnrm_receipt_trailer trnrm_receipt_trailer ON
    trnrm_receipt_header.rech_seqno = trnrm_receipt_trailer.rect_hdseqno)
     INNER JOIN mas_area mas_area ON
        trnrm_receipt_header.rech_area_code = mas_area.area_code)
     INNER JOIN mas_area_report_group mas_area_report_group ON
        mas_area.area_report_group = mas_area_report_group.mas_area_repgrp_code)        
     INNER JOIN masrm_item_header masrm_item_header ON
        trnrm_receipt_trailer.rect_item_code = masrm_item_header.itmh_code)
}
WHERE
    trnrm_receipt_header.rech_compcode = 1 AND
    trnrm_receipt_header.rech_date >= fromdate AND
    trnrm_receipt_header.rech_date <= todate   
group by  mas_area_repgrp_name,mas_area_repgrp_code,year(rech_date) ,month(rech_date) , monthname(rech_date) order by  mas_area_repgrp_name;

END ;;
DELIMITER ;
