CREATE DEFINER=`root`@`%` PROCEDURE `sprm_rep_degrade`(
compcode tinyint,
finid tinyint,
fromdate date,
todate date
)
BEGIN
SELECT
    vew_rm_receiptheadermerge.type, vew_rm_receiptheadermerge.rech_seqno, vew_rm_receiptheadermerge.rech_compcode, vew_rm_receiptheadermerge.rech_fincode, vew_rm_receiptheadermerge.rech_no, vew_rm_receiptheadermerge.rech_date, vew_rm_receiptheadermerge.rech_billno, vew_rm_receiptheadermerge.rech_billdate,
    vew_rm_receipttrailermerge.rect_seqno, vew_rm_receipttrailermerge.rect_billqty, vew_rm_receipttrailermerge.rect_millqty, vew_rm_receipttrailermerge.rect_itemrate, vew_rm_receipttrailermerge.rect_moisper, vew_rm_receipttrailermerge.rect_moisqty, vew_rm_receipttrailermerge.rect_rejqty, vew_rm_receipttrailermerge.rect_totdedqty, vew_rm_receipttrailermerge.rect_degqty, vew_rm_receipttrailermerge.rect_grnqty,  vew_rm_receipttrailermerge.rect_costvalue,
    vew_rm_receipttrailermerge.rect_tareqty,
    vew_rm_receipttrailermerge.rect_lifelessqty,     
    maspur_supplier_master.sup_refname,
    trnrm_order_header.ordh_no, trnrm_order_header.ordh_date,
    masrm_item_header.itmh_name,
    partyitem_header.itmh_name as partyitem
FROM
    { oj ((((vew_rm_receiptheadermerge vew_rm_receiptheadermerge INNER JOIN maspur_supplier_master maspur_supplier_master ON
        vew_rm_receiptheadermerge.rech_sup_code = maspur_supplier_master.sup_code)
     INNER JOIN trnrm_order_header trnrm_order_header ON
        vew_rm_receiptheadermerge.rech_ordhdseqno = trnrm_order_header.ordh_seqno AND
    vew_rm_receiptheadermerge.rech_compcode = trnrm_order_header.ordh_compcode AND
    vew_rm_receiptheadermerge.rech_fincode = trnrm_order_header.ordh_fincode)
     INNER JOIN vew_rm_receipttrailermerge vew_rm_receipttrailermerge ON
        vew_rm_receiptheadermerge.type = vew_rm_receipttrailermerge.type AND
    vew_rm_receiptheadermerge.rech_seqno = vew_rm_receipttrailermerge.rect_hdseqno)
     INNER JOIN masrm_item_header partyitem_header ON
        vew_rm_receipttrailermerge.rect_partyitemcode = partyitem_header.itmh_code)
     INNER JOIN masrm_item_header masrm_item_header ON
        vew_rm_receipttrailermerge.rect_item_code = masrm_item_header.itmh_code}
WHERE
    vew_rm_receiptheadermerge.rech_compcode = compcode AND
    vew_rm_receiptheadermerge.rech_fincode = finid  AND
    vew_rm_receiptheadermerge.rech_date >= fromdate AND
    vew_rm_receiptheadermerge.rech_date <= todate;
END ;;
