DELIMITER ;;
CREATE DEFINER=`root`@`%` PROCEDURE `sprm_rep_grn`(rechcompcode int, rechfincode int, rechno varchar(12))
BEGIN
select * from (
SELECT
 mas_company.* ,massal_customer.*,trnrm_receipt_header.*,mas_state.*,mas_area.*,trnrm_order_header.*,trnrm_receipt_trailer.*,masrm_item_header.*,entry.usr_name enteredby , 
 case when rech_modified_by = 0 then  '' else concat("Modified By ", modified.usr_name , " on " , DATE_FORMAT(rech_modified_on, '%d-%m-%Y %H:%i:%s') ) end as modifiedby 
FROM
    { oj ((((((((mas_company mas_company INNER JOIN trnrm_receipt_header trnrm_receipt_header ON
        mas_company.company_code = trnrm_receipt_header.rech_compcode)
     INNER JOIN massal_customer massal_customer ON
        trnrm_receipt_header.rech_sup_code = massal_customer.cust_code)
     INNER JOIN mas_state mas_state ON
        massal_customer.cust_state = mas_state.state_code)        
     INNER JOIN trnrm_receipt_trailer trnrm_receipt_trailer ON
        trnrm_receipt_header.rech_seqno = trnrm_receipt_trailer.rect_hdseqno)
     INNER JOIN mas_area mas_area ON
        trnrm_receipt_header.rech_area_code = mas_area.area_code)
     INNER JOIN trnrm_order_header trnrm_order_header ON
        trnrm_receipt_header.rech_ordhdseqno = trnrm_order_header.ordh_seqno)
     INNER JOIN masrm_item_header masrm_item_header ON
        trnrm_receipt_trailer.rect_item_code = masrm_item_header.itmh_code )
      INNER JOIN userMaster entry ON
         entry.usr_code = trnrm_receipt_header.rech_usr_code)
      INNER JOIN userMaster modified ON
         modified.usr_code = trnrm_receipt_header.rech_modified_by                  
      }
WHERE
    trnrm_receipt_header.rech_compcode = rechcompcode AND
    trnrm_receipt_header.rech_fincode = rechfincode AND
    trnrm_receipt_header.rech_no = rechno
) a1;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
