CREATE DEFINER=`root`@`%` PROCEDURE `sprm_rep_issuereturn_register`(compcode int,finid int,fromdate date,todate date)
BEGIN
SELECT
    trnrm_issret_header.isrh_no, trnrm_issret_header.isrh_date,
    mas_company.company_name,
    trnrm_issret_trailer.isrt_qty, trnrm_issret_trailer.isrt_values,
    masprd_vartype.vartyp_name,
    masrm_item_header.itmh_name,
    mas_lot.lot_refno
FROM
     {oj ((((trnrm_issret_header  
	 INNER JOIN trnrm_issret_trailer trnrm_issret_trailer ON
        trnrm_issret_header.isrh_seqno = trnrm_issret_trailer.isrt_hdseqno)
     INNER JOIN mas_company mas_company ON
        trnrm_issret_header.isrh_compcode = mas_company.company_code)
     INNER JOIN masrm_item_header masrm_item_header ON
        trnrm_issret_trailer.isrt_itemcode = masrm_item_header.itmh_code)
     INNER JOIN mas_lot mas_lot ON
        trnrm_issret_trailer.isrt_lotseqno = mas_lot.lot_code)
     INNER JOIN masprd_vartype masprd_vartype ON
        trnrm_issret_trailer.isrt_vartype = masprd_vartype.vartyp_code}
WHERE
 trnrm_issret_header.isrh_date>= fromdate and
 trnrm_issret_header.isrh_date<= todate and
 trnrm_issret_header.isrh_compcode = compcode
 ORDER BY 
 trnrm_issret_header.isrh_date ASC,
 trnrm_issret_header.isrh_no ASC;
 
END ;;
DELIMITER ;
