CREATE DEFINER=`root`@`%` PROCEDURE `sprm_rep_issue_datewise_abstract`(compcode int,fromdate date,todate date)
BEGIN
select  DATE_FORMAT(issh_date, '%d-%m-%Y') as issdate,issh_date , sum(isst_qty) qty , sum(isst_values) value from trnrm_issue_header, trnrm_issue_trailer where issh_type = 'C' and issh_seqno = isst_hdseqno and  issh_compcode = compcode and issh_date between fromdate  and  todate
group by issh_date  order by issh_date desc;
END ;;
