CREATE DEFINER=`root`@`%` PROCEDURE `sprm_rep_issue_date_Itemwise`(compcode int,fromdate date,todate date,opt int)
BEGIN
if opt = 1 then
select  vargrp_type_name, itmh_name , sum(isst_qty) qty , sum(isst_values) value from trnrm_issue_header, trnrm_issue_trailer, masprd_type, masrm_item_header where 
isst_itmcode = itmh_code and 
isst_varty = vargrp_type_code and 
issh_type = 'C' and issh_seqno = isst_hdseqno and  issh_compcode = compcode and issh_date between fromdate  and  todate
group by vargrp_type_name,itmh_name  order by vargrp_type_name,itmh_name  desc;
else
select  issh_date, vargrp_type_name, itmh_name , sum(isst_qty) qty , sum(isst_values) value from trnrm_issue_header, trnrm_issue_trailer, masprd_type, masrm_item_header where 
isst_itmcode = itmh_code and 
isst_varty = vargrp_type_code and 
issh_type = 'C' and issh_seqno = isst_hdseqno and  issh_compcode = compcode and issh_date between fromdate  and  todate
group by issh_date , vargrp_type_name,itmh_name  order by issh_date, vargrp_type_name,itmh_name  desc;
end if;

END ;;
