CREATE DEFINER=`root`@`%` PROCEDURE `sprm_rep_issue_register`(compcode int,finid int,fromdate date,todate date)
BEGIN
SELECT
    trnrm_issue_header.issh_no, trnrm_issue_header.issh_date,
    mas_company.company_name,
    trnrm_issue_trailer.isst_qty, trnrm_issue_trailer.isst_values,
    masrm_item_header.itmh_name,
    mas_lot.lot_refno,
    mas_mis_prodvariety_group.mis_var_grpname
FROM
    { oj ((((trnrm_issue_header  
    INNER JOIN trnrm_issue_trailer trnrm_issue_trailer ON
        trnrm_issue_header.issh_seqno = trnrm_issue_trailer.isst_hdseqno)
     INNER JOIN mas_company mas_company ON
        trnrm_issue_header.issh_compcode = mas_company.company_code)
     INNER JOIN mas_lot mas_lot ON
        trnrm_issue_trailer.isst_lotseqno = mas_lot.lot_code)
     INNER JOIN mas_mis_prodvariety_group mas_mis_prodvariety_group ON
        trnrm_issue_trailer.isst_vartype = mas_mis_prodvariety_group.mis_var_grpcode)
     INNER JOIN masrm_item_header masrm_item_header ON
        trnrm_issue_trailer.isst_itmcode = masrm_item_header.itmh_code}
WHERE
       trnrm_issue_header.issh_date>= fromdate and
       trnrm_issue_header.issh_date<= todate and
	   trnrm_issue_header.issh_compcode = compcode
ORDER BY 
	trnrm_issue_header.issh_date ASC,
    trnrm_issue_header.issh_no ASC;
END ;;
DELIMITER ;
