CREATE DEFINER=`root`@`%` PROCEDURE `sprm_rep_item_ledger`(compcode int,fromdate date,todate date,itemcode int ,qtytype int)
BEGIN
select * from (
select 'GRN' as trntype,DATE_FORMAT(rech_date, '%d-%m-%Y')  docdate,rech_no docno,rech_billno billno,DATE_FORMAT(rech_billdate, '%d-%m-%Y')  billdate,cust_name supname ,itmh_name itemname, itmh_code,
 case when qtytype = 0 then rect_grnqty else rect_billqty end as  qty,
 case when qtytype = 0 then rect_itemvalue else rect_billvalue end as itemvalue, 
 case when qtytype = 0 then rect_billrate else rect_costrate end as rate 
 from trnrm_receipt_header,trnrm_receipt_trailer , massal_customer,masrm_item_header where rech_sup_code = cust_code and rect_item_code =  itmh_code and rech_seqno = rect_hdseqno and  rech_date >= fromdate and rech_date<=  todate  and rech_compcode = compcode and rect_item_code = itemcode
union all
select 'ISSUE' as trntype,DATE_FORMAT(issh_date, '%d-%m-%Y')   docdate,issh_date docno, '' billno,'' billdate, 'Issues' supname ,itmh_name itemname, itmh_code, isst_qty qty,isst_values itemvalue, isst_rate rate  from trnrm_issue_header ,trnrm_issue_trailer ,masrm_item_header where  isst_itmcode =  itmh_code and  issh_seqno = isst_hdseqno AND issh_compcode = compcode AND issh_date >= fromdate  AND issh_date <=  todate  and isst_hdseqno = itemcode 
) a1 order by docdate,trntype,docno;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
