     INNER JOIN masrm_item_header masrm_item_header ON
        vew_rm_receipttrailermerge.rect_item_code = masrm_item_header.itmh_code}
WHERE
 vew_rm_receiptheadermerge.rech_date >= fromdate 
 and vew_rm_receiptheadermerge.rech_date <= todate
 and vew_rm_receiptheadermerge.rech_compcode in (rechcompcode)
 group by massal_customer.cust_ref,massal_customer.cust_code  order by massal_customer.cust_ref;
else
SELECT
    massal_customer.cust_ref,massal_customer.cust_code,
    sum(vew_rm_receipttrailermerge.rect_grnqty) grnqty,
    sum(vew_rm_receipttrailermerge.rect_costvalue) grnvalue,
    round(sum(vew_rm_receipttrailermerge.rect_costvalue)/sum(vew_rm_receipttrailermerge.rect_grnqty),2) avgrate    
FROM
    { oj ((((vew_rm_receiptheadermerge vew_rm_receiptheadermerge INNER JOIN mas_finyear mas_finyear ON
        vew_rm_receiptheadermerge.rech_fincode = mas_finyear.fin_code)
     INNER JOIN vew_rm_receipttrailermerge vew_rm_receipttrailermerge ON
        vew_rm_receiptheadermerge.type = vew_rm_receipttrailermerge.type AND
    vew_rm_receiptheadermerge.rech_seqno = vew_rm_receipttrailermerge.rect_hdseqno)
     INNER JOIN massal_customer massal_customer ON
        vew_rm_receiptheadermerge.rech_sup_code = massal_customer.cust_code)    
--     INNER JOIN vew_rm_orderheadermerge vew_rm_orderheadermerge ON
--        vew_rm_receiptheadermerge.rech_ordhdseqno = vew_rm_orderheadermerge.ordh_seqno AND
--    vew_rm_receiptheadermerge.rech_compcode = vew_rm_orderheadermerge.ordh_compcode AND  vew_rm_receiptheadermerge.type =  vew_rm_orderheadermerge.potype AND
--    vew_rm_receiptheadermerge.rech_fincode = vew_rm_orderheadermerge.ordh_fincode)
     INNER JOIN mas_company mas_company ON
        vew_rm_receiptheadermerge.rech_compcode = mas_company.company_code)
     INNER JOIN masrm_item_header masrm_item_header ON
        vew_rm_receipttrailermerge.rect_item_code = masrm_item_header.itmh_code}
WHERE
 vew_rm_receiptheadermerge.rech_date >= fromdate 
 and vew_rm_receiptheadermerge.rech_date <= todate
 and vew_rm_receiptheadermerge.rech_compcode in (rechcompcode)
 and  vew_rm_receipttrailermerge.rect_item_code = itemcode 
  group by massal_customer.cust_ref,massal_customer.cust_code  order by massal_customer.cust_ref;
