CREATE DEFINER=`root`@`%` PROCEDURE `sprm_rep_item_party_GRNwise_receipt`(rechcompcode int,fromdate date,todate date ,itemcode int ,partycode int )
BEGIN
if itemcode = 0 then
SELECT
    masrm_item_header.itmh_name,massal_customer.cust_ref,massal_customer.cust_code,
    vew_rm_receiptheadermerge.rech_date,
    vew_rm_receiptheadermerge.rech_no,
    vew_rm_receiptheadermerge.rech_billno,
    vew_rm_receiptheadermerge.rech_billdate,
    vew_rm_receiptheadermerge.rech_truckno,    
    vew_rm_receipttrailermerge.rect_grnqty,
    vew_rm_receipttrailermerge.rect_itemrate,
    vew_rm_receipttrailermerge.rect_itemvalue , mas_area.area_name
FROM
    { oj (((((vew_rm_receiptheadermerge vew_rm_receiptheadermerge INNER JOIN mas_finyear mas_finyear ON
        vew_rm_receiptheadermerge.rech_fincode = mas_finyear.fin_code)
     INNER JOIN vew_rm_receipttrailermerge vew_rm_receipttrailermerge ON
        vew_rm_receiptheadermerge.type = vew_rm_receipttrailermerge.type AND
    vew_rm_receiptheadermerge.rech_seqno = vew_rm_receipttrailermerge.rect_hdseqno)
     INNER JOIN massal_customer massal_customer ON
        vew_rm_receiptheadermerge.rech_sup_code = massal_customer.cust_code)    
     INNER JOIN mas_company mas_company ON
        vew_rm_receiptheadermerge.rech_compcode = mas_company.company_code)
     INNER JOIN mas_area mas_area ON
        vew_rm_receiptheadermerge.rech_area_code = mas_area.area_code)        
     INNER JOIN masrm_item_header masrm_item_header ON
        vew_rm_receipttrailermerge.rect_item_code = masrm_item_header.itmh_code        }
WHERE
 vew_rm_receiptheadermerge.rech_date >= fromdate 
 and vew_rm_receiptheadermerge.rech_date <= todate
 and vew_rm_receiptheadermerge.rech_compcode in (rechcompcode)
  and vew_rm_receiptheadermerge.rech_sup_code = partycode
 order by rech_date,rech_no;
 else
 SELECT
    masrm_item_header.itmh_name,massal_customer.cust_ref,massal_customer.cust_code,
    vew_rm_receiptheadermerge.rech_date,
    vew_rm_receiptheadermerge.rech_no,
    vew_rm_receiptheadermerge.rech_billno,
    vew_rm_receiptheadermerge.rech_billdate,
    vew_rm_receiptheadermerge.rech_truckno,    
    vew_rm_receipttrailermerge.rect_grnqty,
    vew_rm_receipttrailermerge.rect_itemrate,
    vew_rm_receipttrailermerge.rect_itemvalue, mas_area.area_name
FROM
    { oj (((((vew_rm_receiptheadermerge vew_rm_receiptheadermerge INNER JOIN mas_finyear mas_finyear ON
        vew_rm_receiptheadermerge.rech_fincode = mas_finyear.fin_code)
     INNER JOIN vew_rm_receipttrailermerge vew_rm_receipttrailermerge ON
        vew_rm_receiptheadermerge.type = vew_rm_receipttrailermerge.type AND
    vew_rm_receiptheadermerge.rech_seqno = vew_rm_receipttrailermerge.rect_hdseqno)
     INNER JOIN massal_customer massal_customer ON
        vew_rm_receiptheadermerge.rech_sup_code = massal_customer.cust_code)    

     INNER JOIN mas_company mas_company ON
        vew_rm_receiptheadermerge.rech_compcode = mas_company.company_code)
     INNER JOIN mas_area mas_area ON
        vew_rm_receiptheadermerge.rech_area_code = mas_area.area_code)         
     INNER JOIN masrm_item_header masrm_item_header ON
        vew_rm_receipttrailermerge.rect_item_code = masrm_item_header.itmh_code}
WHERE
 vew_rm_receiptheadermerge.rech_date >= fromdate 
 and vew_rm_receiptheadermerge.rech_date <= todate
 and vew_rm_receiptheadermerge.rech_compcode in (rechcompcode)
 and  vew_rm_receipttrailermerge.rect_item_code = itemcode 
 and vew_rm_receiptheadermerge.rech_sup_code = partycode
 order by rech_date,rech_no;
end if;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `sprm_rep_partyeisereceipt` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
