/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`%` PROCEDURE `sprm_rep_partyeisereceipt`(compcode int,finid int, fromdate date, todate date)
BEGIN
SELECT
    vew_rm_receiptheadermerge.type, vew_rm_receiptheadermerge.rech_compcode,
    vew_rm_receiptheadermerge.rech_no, vew_rm_receiptheadermerge.rech_date,
    vew_rm_receiptheadermerge.rech_freighttype, 
    vew_rm_receiptheadermerge.rech_itemvalue,
    vew_rm_receiptheadermerge.rech_freight,
    vew_rm_receiptheadermerge.rech_billno, 
    vew_rm_receiptheadermerge.rech_billdate,
    massal_customer.cust_ref, massal_customer.cust_taxtag,
    vew_rm_receipttrailermerge.rect_grnqty,
    vew_rm_receipttrailermerge.rect_item_code,masrm_item_header.itmh_name
FROM
    { oj ((vew_rm_receiptheadermerge  
    INNER JOIN vew_rm_receipttrailermerge vew_rm_receipttrailermerge ON
        vew_rm_receiptheadermerge.type = vew_rm_receipttrailermerge.type AND
    vew_rm_receiptheadermerge.rech_seqno = vew_rm_receipttrailermerge.rect_hdseqno)
     INNER JOIN massal_customer massal_customer ON
        vew_rm_receiptheadermerge.rech_sup_code = massal_customer.cust_code)

	 INNER JOIN masrm_item_header ON
		vew_rm_receipttrailermerge.rect_item_code = masrm_item_header.itmh_code}
WHERE
    vew_rm_receiptheadermerge.rech_date >= fromdate and
    vew_rm_receiptheadermerge.rech_date <=  todate and
    vew_rm_receiptheadermerge.rech_compcode in (compcode)
ORDER BY
    massal_customer.cust_ref ASC,
    vew_rm_receiptheadermerge.rech_no ASC;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
