/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`%` PROCEDURE `sprm_rep_party_Item_monthwise_Arrivals`(compcode tinyint,fromdate date,todate date,purtype varchar(10))
BEGIN
select 
cust_ref,itmh_name,month(rech_date) repmonth, sum(rect_itemvalue)/1000 recptvalue , sum(rect_grnqty) recptqty ,(sum(rect_itemvalue) / sum(rect_grnqty))/1000 avgrate
 from trnrm_receipt_header trnrm_receipt_header INNER JOIN massal_customer massal_customer ON
        trnrm_receipt_header.rech_sup_code = massal_customer.cust_code -- and  massal_customer.cust_taxtag !=3 
     INNER JOIN trnrm_receipt_trailer trnrm_receipt_trailer ON
    trnrm_receipt_header.rech_seqno = trnrm_receipt_trailer.rect_hdseqno
    INNER JOIN masrm_item_header masrm_item_header ON
        trnrm_receipt_trailer.rect_item_code = masrm_item_header.itmh_code
WHERE
    trnrm_receipt_header.rech_compcode =  compcode AND
    trnrm_receipt_header.rech_date >= fromdate AND
    trnrm_receipt_header.rech_date <= todate AND (
            purtype = 'ALL'
            OR (purtype = 'LOCAL' AND cust_taxtag IN (1, 2))
            OR (purtype <> 'ALL' AND purtype <> 'LOCAL' AND cust_taxtag = 3)
        )   
group by cust_ref,itmh_name,month(rech_date)  order by cust_ref,itmh_name;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
