DELIMITER ;;
CREATE DEFINER=`root`@`%` PROCEDURE `sprm_rep_purchaseorder`(ordhcompcode int, ordhfincode int, ordhno int ,amendno int )
BEGIN
SELECT
    mas_company.company_code, mas_company.company_name, mas_company.company_gst,
    trnrm_order_header.ordh_compcode, trnrm_order_header.ordh_fincode, 
    trnrm_order_header.ordh_no,  trnrm_order_header.ordh_preparedby,
    trnrm_order_header.ordh_date, trnrm_order_header.ordh_creditdays, 
    mas_transport.carr_name, trnrm_order_header.ordh_refno,trnrm_order_header.ordh_refdate,
    trnrm_order_header.ordh_tcsper, trnrm_order_header.ordh_cgstper, 
    trnrm_order_header.ordh_sgstper, trnrm_order_header.ordh_igstper, mas_terms.term_name,
    maspur_supplier_master.sup_name, maspur_supplier_master.sup_addr1, maspur_supplier_master.sup_addr2, maspur_supplier_master.sup_addr3, maspur_supplier_master.sup_city, maspur_supplier_master.sup_zip, 
    maspur_supplier_master.sup_gstin,
    trnrm_order_trailer.ordt_seqno, trnrm_order_trailer.ordt_qty, 
    trnrm_order_trailer.ordt_unit_rate,trnrm_order_trailer.ordt_item_value,
    masrm_item_header.itmh_name, masrm_item_header.itmh_hsncode,mas_state.state_name, mas_state.state_codeno,area_name,area_code,ordt_moisper,ordt_status,ordt_amendno,ordt_wefdate,ordh_terms,ordh_wef,ordt_amenddate
FROM
    { oj ((((((mas_company  INNER JOIN trnrm_order_header trnrm_order_header ON
        mas_company.company_code = trnrm_order_header.ordh_compcode)
     INNER JOIN maspur_supplier_master maspur_supplier_master ON
        trnrm_order_header.ordh_sup_code = maspur_supplier_master.sup_code)
     INNER JOIN trnrm_order_trailer trnrm_order_trailer ON
        trnrm_order_header.ordh_seqno = trnrm_order_trailer.ordt_hdseqno)
        INNER JOIN mas_transport mas_transport ON
        trnrm_order_header.ordh_carriagetype = mas_transport.carr_code)          
     INNER JOIN mas_state mas_state ON
        mas_state.state_code = maspur_supplier_master.sup_state)    
     INNER JOIN mas_terms mas_terms ON
        trnrm_order_header.ordh_paymode = mas_terms.term_code)         
     INNER JOIN masrm_item_header masrm_item_header ON
        trnrm_order_trailer.ordt_item_code = masrm_item_header.itmh_code
     INNER JOIN mas_area mas_area ON
        trnrm_order_trailer.ordt_areacode = mas_area.area_code and 
        trnrm_order_trailer.ordt_amendno = amendno
        
        }
WHERE
    trnrm_order_header.ordh_compcode = ordhcompcode AND
    trnrm_order_header.ordh_fincode = ordhfincode AND
    trnrm_order_header.ordh_no = ordhno
ORDER BY
    trnrm_order_header.ordh_no ASC,
    trnrm_order_trailer.ordt_seqno ASC;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
