CREATE DEFINER=`root`@`%` PROCEDURE `sprm_rep_rate`(compcode int,fincode int,vouno int)
BEGIN
select * from masrm_supplier_rate join massal_customer on rm_rate_supcode = cust_code 
join masrm_item_header on rm_rate_itemcode = itmh_code
join mas_area on rm_rate_areacode = area_code where rm_rate_compcode = compcode and rm_rate_fincode = fincode and rm_rate_seqno = vouno;
END ;;
DELIMITER ;
