CREATE DEFINER=`root`@`%` PROCEDURE `sprm_rep_wb_tickets`(compcode int,fincode int,fromdate date,todate date,iname varchar(40))
BEGIN
/*
if iname = '0' then
   select * from trn_weight_card , mas_area where wc_area_code = area_code and  wc_compcode =  compcode and wc_fincode = fincode and wc_date between fromdate and todate ;
else 
   select * from trn_weight_card , mas_area where wc_area_code = area_code and  wc_compcode =  compcode and wc_fincode = fincode and wc_date between fromdate and todate and wc_item = iname;
end if;
*/
if iname = '0' then
   select * from trn_weight_card left join mas_area on wc_area_code = area_code left join mas_wb_item on  wc_item = item_name left join mas_wb_itemgroup on item_grpcode = item_group where wc_compcode =  compcode and wc_fincode = fincode and wc_date between fromdate and todate;
else 
   select * from trn_weight_card left join mas_area on wc_area_code = area_code left join mas_wb_item on  wc_item = item_name left join mas_wb_itemgroup on item_grpcode = item_group where wc_compcode =  compcode and wc_fincode = fincode and wc_date between fromdate and todate  and item_grpname = iname;
end if;

END ;;
DELIMITER ;
