CREATE DEFINER=`root`@`%` PROCEDURE `sprm_sel_amndorddets`( 
p_amnh_ordhdseqno int,p_amnt_item_code int,p_amnh_wedate datetime(3))
begin

select max(amnt_unit_rate) as amnt_unit_rate from trnrm_orderamnd_trailer 
where amnt_hdseqno=(select max(amnh_seqno) 
from trnrm_orderamnd_header 
where amnh_ordhdseqno=p_amnh_ordhdseqno and amnh_wedate<=p_amnh_wedate) 
and amnt_item_code=p_amnt_item_code 
having max(amnt_unit_rate) is not null;
END ;;
