CREATE DEFINER=`root`@`%` PROCEDURE `sprm_sel_issue`( 
p_iss_compcode int,p_iss_fincode int,p_iss_no int)
begin

select 
a.*,b.issh_type,b.issh_date,b.issh_seqno,i.itmh_name,it.*
from 
trnrm_issue_trailer a, trnrm_issue_header b, masrm_item_header i , masrm_item_trailer it
where 
b.issh_no = p_iss_no and b.issh_compcode = p_iss_compcode and b.issh_fincode = p_iss_fincode and 
a.isst_hdseqno = b.issh_seqno and a.isst_itmcode = i.itmh_code and 
