CREATE DEFINER=`root`@`%` PROCEDURE `sprm_sel_itemdetails`(itmhtype int)
BEGIN
IF itmhtype = '' THEN 
	SET itmhtype = 0; 
END IF;

IF itmhtype=0 THEN
    select itmh_name,itmh_code from masrm_item_header  where itmh_type<>3 order by itmh_name;
ELSEIF itmhtype=-1 THEN
    select itmh_name,itmh_code from masrm_item_header order by itmh_name;  
ELSE
    select itmh_name,itmh_code from masrm_item_header  where itmh_type = itmhtype order by itmh_name;
END IF;  
END ;;
DELIMITER ;
