  /*mod on jan 8th*/
-- SQLINES LICENSE FOR EVALUATION USE ONLY
select    
b.lot_code,lot_refno,a.stk_qty 'stock',c.itmt_avgrate,c.itmt_clqty,d.itmh_type as 'type',c.itmt_clvalue as 'value'
  
