 c.itmt_hdcode = a.stk_itemcode and c.itmt_compcode = p_stk_compcode and c.itmt_fincode = p_stk_fincode and   
 c.itmt_hdcode = d.itmh_code and a.stk_lotno = p_stk_lotcode;  

