CREATE DEFINER=`root`@`%` PROCEDURE `sprm_sel_orditem_dets`(ordthdseqno int,ordtitemcode int,status1 varchar(1))
BEGIN
select ordt_item_code,sum(ordt_qty) as ordt_qty,coalesce(max(tol_per),0) as tol_per,
(sum(ordt_qty)*coalesce(max(tol_per),0)/100) as tol_all_qty ,
sum(ordt_pen_qty)as ordt_pen_qty,max(ordt_unit_rate) as ordt_unit_rate, 
max(ordt_moisper) as ordt_moisper
from trnrm_order_trailer,(select poqt_tolper as tol_per from mas_qtytolerance 
where poqt_code in(select max(poqt_code) from mas_qtytolerance where poqt_type='L')) a
where ordt_hdseqno=ordthdseqno and ordt_item_code=ordtitemcode 
group by ordt_item_code;
END ;;
