CREATE DEFINER=`root`@`%` PROCEDURE `sprm_sel_ordno`(ordno int,
gincompcode  int,
fincode	   int)
BEGIN
select * from trnrm_order_header a, trnrm_order_trailer b,  maspur_supplier_master d, 
masrm_item_header e, mas_area f
where a.ordh_status <> 'C' and a.ordh_no =  ordno and a.ordh_compcode = gincompcode 
and a.ordh_fincode = fincode and a.ordh_seqno = b.ordt_hdseqno  
and a.ordh_sup_code = d.sup_code and b.ordt_item_code = e.itmh_code and  b.ordt_areacode = f.area_code
and a.ordh_seqno = b.ordt_hdseqno;
END ;;
