CREATE DEFINER=`root`@`%` PROCEDURE `sprm_sel_partyorders`(  
 p_ordh_compcode int,  
 p_ordh_fincode int ,  
 p_ordh_sup_code int,  
 p_fetch_type tinyint unsigned/* =0 */ )
BEGIN  
-- SQLINES LICENSE FOR EVALUATION USE ONLY
select CONCAT((case ordh_amndstatus when 'N' then '' else 'A-' end),ltrim(rtrim(convert(ordh_no, char)))) as 'ordh_no',ordh_seqno   
from trnrm_order_header    
where  ordh_status in ('O','P',case when p_fetch_type=1 then 'C' else '' end ) and  
 ordh_compcode = p_ordh_compcode and   
 ordh_sup_code = p_ordh_sup_code;

END ;;
