CREATE DEFINER=`root`@`%` PROCEDURE `sprm_sel_receiptheader`(p_rech_seqno int)
begin 
select h.*,t.rect_censtatus as censtatus,s.sup_type,s.sup_name as sup_name,f.sup_name as frt_sup_name,s.sup_code as sup_code,f.sup_code as frt_sup_code,s.sup_led_code as sup_led_code,f.sup_led_code as frt_sup_led_code from 
trnrm_receipt_header  h
INNER JOIN trnrm_receipt_trailer t ON t.rect_hdseqno = h.rech_seqno
INNER JOIN maspur_supplier_master s ON s.sup_code=h.rech_sup_code
LEFT OUTER JOIN maspur_supplier_master f ON f.sup_code =h.rech_frpartycode
INNER JOIN trnrm_order_header o ON o.ordh_seqno=h.rech_ordhdseqno
where  rech_seqno=p_rech_seqno
group by     h.rech_seqno   ; 
end ;;
DELIMITER ;
