CREATE DEFINER=`root`@`%` PROCEDURE `sprm_sel_recheddet`(   
p_rech_seqno int)
begin   
select a.*,s.sup_type, ordh_no
,ordh_tcsper,ordh_cgstper,ordh_sgstper,ordh_igstper ,s.sup_refname 
from trnrm_receipt_header a,trnrm_order_header b,maspur_supplier_master s  
where rech_seqno=p_rech_seqno and rech_status='' and s.sup_code=a.rech_sup_code and  
      (a.rech_ordhdseqno=b.ordh_seqno);
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `sprm_sel_recitems` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
