CREATE DEFINER=`root`@`%` PROCEDURE `sprm_sel_supitemrate`(supcode	int,
	itemcode	int)
BEGIN
select pitr_rate  from  masrm_party_itemrate 
				where pitr_sup_code=supcode and
				           pitr_item_code=itemcode;
END ;;
