CREATE DEFINER=`root`@`%` PROCEDURE `sprm_sel_tax`(party  numeric(6,0))
BEGIN
select * from maspur_supplier_master a, mas_tax b where a.sup_taxcode = b.tax_code and a.sup_code = party;     
END ;;
