union all      
select rerh_compcode as compcode, rert_itemcode as itemcode, 0 as opstk,0 as opval,0 as recpt_qty,0 as recpt_val,0 as iss_qty,0 as iss_val,0 as sal_qty,0 as sal_val, sum(rert_qty) as ret_qty,sum(rert_totitemvalue) as ret_val  from vew_rm_receiptret_headermerge h,vew_rm_receiptret_trailermerge  t  where h.type=t.type and rerh_seqno = rert_hdseqno and rerh_compcode in (p_comp_code1) and rerh_fincode = p_fin_code  and rerh_date >= p_from_date  and rerh_date <= p_to_date  group by rerh_compcode,rerh_fincode,rert_itemcode       
union all      
select issh_compcode as compcode , isst_itmcode as itemcode ,sum(isst_qty)*-1 as opstk,sum(isst_qty * isst_rate)*-1 as opval,0 as recpt_qty,0 as recpt_val,0 as iss_qty,0 as iss_val,0 as sal_qty,0 as sal_val,0 as ret_qty,0 as ret_val  from trnrm_issue_header ,trnrm_issue_trailer where issh_seqno = isst_hdseqno and issh_compcode in (p_comp_code1) and  issh_fincode = p_fin_code  and issh_date < p_from_date  group by issh_compcode ,isst_itmcode      
union all      
select issh_compcode as compcode , isst_itmcode as itemcode ,0 as opstk,0 as opval,0 as recpt_qty,0 as recpt_val,sum(isst_qty) as iss_qty,sum(isst_qty * isst_rate) as iss_val,0 as sal_qty,0 as sal_val,0 as ret_qty,0 as ret_val  from trnrm_issue_header ,trnrm_issue_trailer where issh_seqno = isst_hdseqno and issh_compcode in (p_comp_code1) and  issh_fincode = p_fin_code  and issh_date >= p_from_date  and issh_date <= p_to_date  group by issh_compcode ,isst_itmcode      
union all      
select isrh_compcode as compcode,isrt_itemcode as itemcode ,sum(isrt_qty) as opstk,sum(isrt_values) as op_value,   0 as recpt_qty,0 as recpt_val,0 as iss_qty,0 as iss_val,0 as sal_qty,0 as sal_val,0 as ret_qty,0 as ret_val from trnrm_issret_header ,trnrm_issret_trailer   where isrh_seqno = isrt_hdseqno and isrh_compcode in (p_comp_code1) and isrh_fincode = p_fin_code  and isrh_date < p_from_date  group by isrh_compcode ,isrt_itemcode      
union all      
select isrh_compcode as compcode,isrt_itemcode as itemcode ,0 as opstk,0 as op_value,   0 as recpt_qty,0 as recpt_val,sum(isrt_qty)*-1 as iss_qty,sum(isrt_values)*-1 as iss_val,0 as sal_qty,0 as sal_val,0 as ret_qty,0 as ret_val from trnrm_issret_header ,trnrm_issret_trailer   where isrh_seqno = isrt_hdseqno and isrh_compcode in (p_comp_code1) and isrh_fincode = p_fin_code  and isrh_date >= p_from_date  and isrh_date <= p_to_date group by isrh_compcode ,isrt_itemcode      
union all      
select salh_compcode as compcode, salt_itemcode as itemcode,sum(salt_qty) *-1 as opstk,sum(salt_value)*-1 as opval,0 as recpt_qty,0 as recpt_val,0 as iss_qty,0 as iss_val,0 as sal_qty,0 as sal_val,0 as ret_qty,0 as ret_val from trnrm_salenote_header, trnrm_salenote_trailer  where salh_seqno = salt_hdseqno and salh_compcode in (p_comp_code1) and salh_fincode = p_fin_code  and salh_date < p_from_date  group by salh_compcode,salt_itemcode       
union all      
select salh_compcode as compcode, salt_itemcode as itemcode, 0 as opstk,0 as opval,0 as recpt_qty,0 as recpt_val,0 as iss_qty,0 as iss_val,sum(salt_qty)  as sal_qty,sum(salt_value) as sal_val,0 as ret_qty,0 as ret_val from trnrm_salenote_header, trnrm_salenote_trailer  where salh_seqno = salt_hdseqno and salh_compcode in (p_comp_code1) and salh_fincode = p_fin_code  and salh_date >= p_from_date and salh_date  <= p_to_date group by salh_compcode,salt_itemcode      
) as aa inner join masrm_item_header b on aa.itemcode = b.itmh_code group by itmh_type,itmh_name,itemcode order by itmh_name;

END ;;
