union all      
select issh_compcode as compcode , isst_itmcode as itemcode ,sum(isst_qty)*-1 as opstk,sum(isst_qty * isst_rate)*-1 as opval,0 as recpt_qty,0 as recpt_val,0 as iss_qty,0 as iss_val,0 as sal_qty,0 as sal_val,0 as ret_qty,0 as ret_val  from trnrm_issue_header ,trnrm_issue_trailer, masrm_item_header  where itmh_type in (3) and isst_itmcode = itmh_code and issh_seqno = isst_hdseqno and issh_compcode in (p_comp_code1) and  issh_fincode = p_fin_code  and issh_date < p_from_date  group by issh_compcode,isst_itmcode      
union all      
select issh_compcode as compcode , isst_itmcode as itemcode ,0 as opstk,0 as opval,0 as recpt_qty,0 as recpt_val,sum(isst_qty) as iss_qty,sum(isst_qty * isst_rate) as iss_val,0 as sal_qty,0 as sal_val,0 as ret_qty,0 as ret_val  from trnrm_issue_header ,trnrm_issue_trailer , masrm_item_header   where itmh_type in (1,2) and isst_itmcode = itmh_code and issh_seqno = isst_hdseqno and issh_compcode in (p_comp_code1) and  issh_fincode = p_fin_code and issh_date >= p_from_date  and issh_date <= p_to_date  group by issh_compcode,isst_itmcode      
union all      
select issh_compcode as compcode , isst_itmcode as itemcode ,0 as opstk,0 as opval,0 as recpt_qty,0 as recpt_val,sum(isst_qty) as iss_qty,sum(isst_qty * isst_rate) as iss_val,0 as sal_qty,0 as sal_val,0 as ret_qty,0 as ret_val  from trnrm_issue_header ,trnrm_issue_trailer , masrm_item_header   where itmh_type in (3) and isst_itmcode = itmh_code and issh_seqno = isst_hdseqno and issh_compcode in (p_comp_code1) and  issh_fincode = p_fin_code  and issh_date >= p_from_date  and issh_date <= p_to_date  
  group by issh_compcode,isst_itmcode      
