CREATE DEFINER=`root`@`%` PROCEDURE `sprm_update_order`(ordhseqno  int,      
ordhcompcode int,      
ordhfincode  int,      
ordhno  int,         
ordhsupcode int,      
ordhdate  datetime,      
ordhcarriagetype int,      
ordhpaymode int,      
ordhcreditdays int,      
ordhremarks  varchar(250),      
ordhtcsper  numeric (6,3),      
ordhcgstper  numeric (5,2),      
ordhsgstper  numeric (5,2),      
ordhigstper  numeric (5,2),      
ordhitemvalue numeric(14,2),      
ordhroundingoff numeric(5,2),      
ordhtotalvalue numeric(14,2),      
ordhstatus  varchar(1),      
ordhamndstatus varchar(1),      
ordhamndposeqno  int,      
ordhusrcode int,      
ordhamenddate datetime)
BEGIN

update trnrm_order_header set ordh_sup_code = ordhsupcode, 
ordh_date= ordhdate, 
ordh_carriagetype= ordhcarriagetype, 
ordh_paymode= ordhpaymode,      
ordh_creditdays= ordhcreditdays, 
ordh_terms= ordhremarks,      
ordh_tcsper=ordhtcsper,      
ordh_cgstper = ordhcgstper,    
ordh_sgstper = ordhsgstper,    
ordh_igstper = ordhigstper,      
ordh_itemvalue=ordhitemvalue,      
ordh_roundingoff=ordhroundingoff,      
ordh_totalvalue=ordhtotalvalue,      
ordh_status=ordhstatus,      
ordh_amndstatus=ordhamndstatus,      
ordh_amndposeqno=ordhamndposeqno,      
ordh_usr_code=ordhusrcode,      
ordh_amndpodate=ordhamenddate where ordh_seqno = ordhseqno; 
    
-- delete from trnrm_order_trailer where ordt_hdseqno = ordhseqno;   


END ;;
