CREATE DEFINER=`root`@`%` PROCEDURE `sprm_upd_issh`(
	p_seq       	int,
	p_comp_code	numeric(3),
	p_fin_code	int,
	p_no		int,
	p_type		varchar(1),
	p_date		datetime(3),	
	p_value		numeric(14,2),
	p_usr		numeric(7))
begin
	update trnrm_issue_header set 
		issh_type = p_type,
		issh_date = p_date,
		issh_value=p_value,
		issh_usr_code = p_usr
	where
		issh_seqno = p_seq and	
	 	issh_compcode = p_comp_code and
		issh_fincode = p_fin_code and 
		issh_no= p_no;
END ;;
DELIMITER ;
