/*!50003 DROP PROCEDURE IF EXISTS `sprm_upd_itemtrailer_avgrate` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`%` PROCEDURE `sprm_upd_itemtrailer_avgrate`(
p_itmt_compcode int,p_itmt_fincode int,p_itmt_hdcode int,
p_qty numeric(13,3),p_rate numeric(14,5),
p_updtype tinyint unsigned/* =0 */ )
begin

declare v_curqty numeric(13,3);  
declare v_curbqty numeric(13,3);  
declare v_curval numeric(13,2);  
declare v_itmt_avgrate numeric(14,5);
declare cur_itmt_avgrate numeric(14,5);

select itmt_clqty,itmt_clvalue,itmt_avgrate into 
v_curqty,  v_curval, v_itmt_avgrate 
from masrm_item_trailer
where 
itmt_hdcode=p_itmt_hdcode and
itmt_compcode=p_itmt_compcode and
itmt_fincode=p_itmt_fincode;
if p_updtype>0
then
	if (v_curqty+p_qty) > 0
	then
		set cur_itmt_avgrate=round((v_curval + (p_qty * p_rate))/(v_curqty + p_qty),5);
	else
		set cur_itmt_avgrate=0;
	end if;
end if;
update masrm_item_trailer 
set itmt_clqty = v_curqty + p_qty,
    itmt_clvalue = round(((v_curqty + p_qty)*cur_itmt_avgrate),2),
    itmt_avgrate = cur_itmt_avgrate        
where 
itmt_hdcode=p_itmt_hdcode and
itmt_compcode=p_itmt_compcode and
itmt_fincode=p_itmt_fincode;

END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
