/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`%` PROCEDURE `sprm_upd_orderreceiptdets`(
	p_ordt_hdseqno		int,
	p_rect_item_code	int,
	p_rect_qty		numeric(13,3),
	p_trantype		tinyint unsigned)
BEGIN
DECLARE NOT_FOUND INT DEFAULT 0;
declare v_penqty 		numeric(14,2);
declare v_penrec_qty		numeric(14,2);
declare	v_rec_qty		numeric(13,3);
declare	v_ord_qty		numeric(13,3);
declare v_pen_qty		numeric(13,3);
declare v_can_qty		numeric(13,3);

DECLARE group_cursor CURSOR FOR (select ordt_rec_qty,ordt_qty,ordt_pen_qty,ordt_can_qty  from trnrm_order_trailer  where ordt_hdseqno=p_ordt_hdseqno and ordt_item_code=p_rect_item_code );
DECLARE CONTINUE HANDLER FOR NOT FOUND SET NOT_FOUND = 1;
set v_penqty=p_rect_qty;	

OPEN group_cursor;
FETCH group_cursor INTO v_rec_qty,v_ord_qty,v_pen_qty,v_can_qty;

while NOT_FOUND=0 
do
	if  v_penqty>0 
	then
	if p_trantype=0 
	then
		set v_penrec_qty=v_pen_qty;
		if v_penrec_qty >= v_penqty 
		then
			update trnrm_order_trailer set ordt_rec_qty=ordt_rec_qty+v_penqty where ordt_hdseqno=p_ordt_hdseqno and ordt_item_code=p_rect_item_code;
			/*update trnrm_indent_trailer set indt_grnqty=indt_grnqty+v_penqty where  indt_itmh_code=p_rect_item_code;*/
			set v_penqty=0;
		else
			set v_penqty=v_penqty-v_penrec_qty;
			update trnrm_order_trailer set ordt_rec_qty=ordt_rec_qty+v_penrec_qty where ordt_hdseqno=p_ordt_hdseqno and ordt_item_code=p_rect_item_code;
			/*update trnrm_indent_trailer set indt_grnqty=indt_grnqty+v_penrec_qty where indt_hdseqno=v_indh_seqno and indt_itmh_code=p_rect_item_code;*/
		end if;
	else
		set v_penrec_qty=v_rec_qty;
		if v_penrec_qty >= v_penqty 
		then
			update trnrm_order_trailer set ordt_rec_qty=ordt_rec_qty-v_penqty where ordt_hdseqno=p_ordt_hdseqno and ordt_item_code=p_rect_item_code;
			/*update trnrm_indent_trailer set indt_grnqty=indt_grnqty-v_penqty where indt_hdseqno=v_indh_seqno and indt_itmh_code=p_rect_item_code;*/
			set v_penqty=0;
		else
			set v_penqty=v_penqty-v_penrec_qty;
			update trnrm_order_trailer set ordt_rec_qty=ordt_rec_qty-v_penrec_qty where ordt_hdseqno=p_ordt_hdseqno and ordt_item_code=p_rect_item_code;
			/*update trnrm_indent_trailer set indt_grnqty=indt_grnqty-v_penrec_qty where indt_hdseqno=v_indh_seqno and indt_itmh_code=p_rect_item_code;*/
		end if;
	end if; 	

	end if;

	/* SQLINES DEMO *** ending qty */

	update trnrm_order_trailer set ordt_pen_qty=case when ordt_qty-(ordt_rec_qty+ordt_can_qty)>0 then ordt_qty-(ordt_rec_qty+ordt_can_qty) else 0 end  where ordt_hdseqno=p_ordt_hdseqno     and ordt_item_code=p_rect_item_code;

	/* SQLINES DEMO *** ailer status */

	update trnrm_order_trailer set ordt_status='O' where ordt_qty=ordt_pen_qty and ordt_hdseqno=p_ordt_hdseqno and ordt_item_code=p_rect_item_code;
	update trnrm_order_trailer set ordt_status='P' where ordt_qty<>ordt_pen_qty and ordt_hdseqno=p_ordt_hdseqno and ordt_item_code=p_rect_item_code;
	update trnrm_order_trailer set ordt_status='C' where ordt_pen_qty=0 and ordt_hdseqno=p_ordt_hdseqno and  ordt_item_code=p_rect_item_code;
	
	/*
	update trnrm_indent_trailer set indt_status='C' where indt_qty<=indt_grnqty and indt_hdseqno=v_indh_seqno and indt_itmh_code=p_rect_item_code;
	update trnrm_indent_trailer set indt_status='P' where indt_qty>indt_grnqty and indt_hdseqno=v_indh_seqno and indt_itmh_code=p_rect_item_code; 
	

	update trnrm_indent_header set indh_status='P' where indh_seqno=indh_seqno and indh_seqno in(
	select indt_hdseqno from trnrm_indent_trailer where indt_hdseqno=v_indh_seqno and indt_status='P');	

	update trnrm_indent_header set indh_status='C' where indh_seqno=indh_seqno and indh_seqno not in(
	select indt_hdseqno from trnrm_indent_trailer where indt_hdseqno=v_indh_seqno and indt_status in('P','O'));	
*/
	FETCH group_cursor INTO v_rec_qty,v_ord_qty,v_pen_qty,v_can_qty;
	if NOT_FOUND<>0 and v_penqty>0 and p_trantype=0
	then
		update trnrm_order_trailer set ordt_rec_qty=ordt_rec_qty+v_penqty where ordt_hdseqno=p_ordt_hdseqno and ordt_item_code=p_rect_item_code;
	end if;

end while; 

close group_cursor;

update trnrm_order_header set ordh_status='P' where ordh_seqno=p_ordt_hdseqno and ordh_seqno in(
select ordt_hdseqno from trnrm_order_trailer where ordt_hdseqno=p_ordt_hdseqno and ordt_status='P');

update trnrm_order_header set ordh_status='C' where ordh_seqno=p_ordt_hdseqno and ordh_seqno not in(
select ordt_hdseqno from trnrm_order_trailer where ordt_hdseqno=p_ordt_hdseqno and ordt_status in('P','O'));

END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
