CREATE DEFINER=`root`@`%` PROCEDURE `sprm_upd_order_amend`(ordseqno int,
amndseqno int,
amnddate  datetime,
wefdate   datetime)
BEGIN
insert into trnrm_orderamnd_header select amndseqno,amnddate,ordh_seqno,ordh_sup_code,
ordh_date,ordh_carriagetype, ordh_paymode, ordh_creditdays, ordh_terms, ordh_tcsper, ordh_cgstper, ordh_sgstper,
ordh_igstper, ordh_itemvalue, ordh_roundingoff, ordh_totalvalue, ordh_status,
ordh_usr_code, ordh_entry_date, ordh_wef_date from trnrm_order_header where ordh_seqno = ordseqno;

insert into trnrm_orderamnd_trailer select amndseqno,ordt_seqno,ordt_item_code,ordt_qty,ordt_rec_qty,ordt_can_qty,
ordt_pen_qty,ordt_unit_rate,ordt_item_value,ordt_moisper,ordt_tareper,ordt_outper,ordt_status
from trnrm_order_trailer where ordt_hdseqno = ordseqno;
END ;;
DELIMITER ;
