CREATE DEFINER=`root`@`%` PROCEDURE `sprm_weighbridge`(compcode int,fromdate datetime,todate datetime)
BEGIN
select *, 
case when t_wb_1st_loadtype = 'E' then t_wb_1st_weight else t_wb_2nd_weight end as emptywt,
case when t_wb_1st_loadtype = 'L' then t_wb_1st_weight else t_wb_2nd_weight end as loadwt
from trn_weighbridge_entry  where t_wb_2nd_time between fromdate  and todate and t_wb_compcode = compcode;

END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `sprm_weighbridge_item_arrivals` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
