/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`%` PROCEDURE `sprm_weighbridge_item_arrivals`(compcode int,fromdate datetime,todate datetime,grp varchar(10))
BEGIN
select *, 
case when t_wb_1st_loadtype = 'E' then t_wb_1st_weight else t_wb_2nd_weight end as emptywt,
case when t_wb_1st_loadtype = 'L' then t_wb_1st_weight else t_wb_2nd_weight end as loadwt
from trn_weighbridge_entry left join mas_wb_item  on  trim(t_wb_item) = trim(item_name) 
left join mas_wb_itemgroup on item_group = item_grpcode
where  t_wb_2nd_time between  fromdate  and  todate and t_wb_net_weight > 0 and t_wb_compcode = compcode and find_in_set(item_grpcode,grp);
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
