CREATE DEFINER=`root`@`%` PROCEDURE `sprm_weighbridge_ticket`(compcode int,ticketdate date,ticketno int)
BEGIN
select *, 
case when t_wb_1st_loadtype = 'E' then t_wb_1st_weight else t_wb_2nd_weight end as emptywt,
case when t_wb_1st_loadtype = 'L' then t_wb_1st_weight else t_wb_2nd_weight end as loadwt
from trn_weighbridge_entry  where DATE_FORMAT(t_wb_2nd_time,'%Y-%m-%d') =  ticketdate and  t_wb_ticketno = ticketno;

END ;;
DELIMITER ;
