CREATE DEFINER=`root`@`%` PROCEDURE `sprn_ins_item_trailer`( compcode int, itemcode int)
BEGIN
   DECLARE done1 INT DEFAULT FALSE;
    DECLARE vfincode INT;
    DECLARE vfinyear INT;
    declare finyear cursor for select fin_code from mas_finyear where fin_code >=22;
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET done1 = TRUE;
	OPEN finyear;
       ins_loop1: LOOP
		FETCH finyear INTO vfincode;
		IF done1 THEN
        	  LEAVE ins_loop1;
		END IF;
        insert into  masfu_item_trailer values (itemcode, compcode,vfincode,0, 0, 0, 0, 0);
	 END loop;
     CLOSE finyear;
END ;;
DELIMITER ;
