CREATE DEFINER=`root`@`%` PROCEDURE `spsalrep_Areawise_Production_Pending`(compcode int,fincode int,fromdate date , todate date , repcode int)
BEGIN
if repcode = 0 then
	select cust_city,repr_name,cust_ref,ordh_party, ordh_sono, ordh_sodate, sizecode, max(ordt_qty) ordt_qty, max(ordt_fin_wt) ordt_fin_wt,max(ordt_inv_wt) ordt_inv_wt, 
	sum(prodnpending_qty) prodnpending_qty, sum(tolarance) tolarance ,
	sum(desp_pending) desp_pending , var_desc,var_groupcode,var_size1,var_size2,var_shade,var_inchcm  from (
			select ordh_party ,ordh_sono ordh_sono , ordh_sodate ordh_sodate,ordt_var_code sizecode,
			case when ordt_clo_stat = '' or  ordt_clo_stat = 'N' then ordt_qty else ordt_fin_wt end as ordt_qty   , ordt_fin_wt, ordt_inv_wt , 0 as desp_pending ,
			case when ordt_clo_stat = '' or  ordt_clo_stat = 'N'  then ordt_qty -  ordt_fin_wt else 0 end as prodnpending_qty , 
			case when ordt_clo_stat = ''  or  ordt_clo_stat = 'N' then ordt_qty * 0.05  else  ordt_fin_wt * 0.05 end as tolarance  
			from trnsal_order_header, trnsal_order_trailer ,  massal_variety where 	
			ordt_var_code = var_code and var_unit = 1 and
			ordh_comp_code  = ordt_comp_code and
			ordh_fincode = ordt_fincode and 
			ordh_sono = ordt_sono and 
			 CHAR_LENGTH(ordh_sono) = 6 and 
			ordh_comp_code  = ordt_comp_code and
			ordh_fincode = ordt_fincode and 
			ordh_comp_code  = compcode and
		-- 	ordh_fincode = fincode and  -- ordt_qty  > ordt_fin_wt   and 
			ordh_sodate between fromdate and todate
			
			union all
			select ordh_party ,ordh_sono ordh_sono, ordh_sodate ordh_sodate, stk_var_code sizecode,  ordt_qty,  ordt_fin_wt, 
			 ordt_inv_wt , stk_wt/1000 desp_pending,0 prodnpending_qty , 0  tolarance from  trnsal_order_header, 
             (select stk_comp_code , stk_sono,stk_var_code , sum(stk_wt) stk_wt from  trnsal_finish_stock where  stk_comp_code =1 and stk_destag = ''
             group by stk_comp_code , stk_sono,stk_var_code) aa1  ,              
              trnsal_order_trailer where 
			ordh_comp_code  = stk_comp_code and
			ordh_sono = stk_sono and
		ordh_comp_code  = ordt_comp_code and
		ordh_fincode = ordt_fincode and 
		ordh_sono = ordt_sono and 
        ordt_var_code = stk_var_code and
                    
-- CHAR_LENGTH(ordh_sono) = 6 and 
			ordh_party not in (2151,4886) and
			ordh_comp_code  = compcode 
			
	) a1 , massal_customer , massal_variety , masprd_variety , massal_repr  where 
 	 (  desp_pending > 0 or  (prodnpending_qty > tolarance and prodnpending_qty > 0.200))	and  
    
    ordh_party = cust_code and 
			repr_code = cust_repr and 
		  sizecode = var_code  and 
			var_grpcode =  var_groupcode  and ordh_party not in (2151,4886) 
	group by cust_city,repr_name,cust_ref,ordh_party, ordh_sono, ordh_sodate, sizecode , var_desc,var_groupcode,var_size1,var_size2,var_shade,var_inchcm;  
else
	select cust_city,repr_name,cust_ref,ordh_party, ordh_sono, ordh_sodate, sizecode, sum(ordt_qty) ordt_qty, sum(ordt_fin_wt) ordt_fin_wt,sum(ordt_inv_wt) ordt_inv_wt, 
	sum(prodnpending_qty) prodnpending_qty, sum(tolarance) tolarance ,
	sum(desp_pending) desp_pending , var_desc,var_groupcode,var_size1,var_size2,var_shade,var_inchcm  from (
			select ordh_party ,ordh_sono ordh_sono , ordh_sodate ordh_sodate,ordt_var_code sizecode,
			case when ordt_clo_stat = ''  or  ordt_clo_stat = 'N' then ordt_qty else ordt_fin_wt end as ordt_qty   , ordt_fin_wt, ordt_inv_wt , 0 as desp_pending ,
			case when ordt_clo_stat = ''  or  ordt_clo_stat = 'N' then ordt_qty -  ordt_fin_wt else 0 end as prodnpending_qty , 
			case when ordt_clo_stat = ''  or  ordt_clo_stat = 'N' then ordt_qty * 0.05  else  ordt_fin_wt * 0.05 end as tolarance  
			from trnsal_order_header, trnsal_order_trailer ,  massal_variety where 	
            ordt_var_code = var_code and var_unit = 1 and
			ordh_comp_code  = ordt_comp_code and
			ordh_fincode = ordt_fincode and 
			ordh_sono = ordt_sono and 
			 CHAR_LENGTH(ordh_sono) = 6 and 
			ordh_comp_code  = ordt_comp_code and
			ordh_fincode = ordt_fincode and 
			ordh_comp_code  = compcode and
	-- 		ordh_fincode = fincode and  -- ordt_qty  > ordt_fin_wt   and 
			ordh_sodate between fromdate and todate
			
			union all
			select ordh_party ,ordh_sono ordh_sono, ordh_sodate ordh_sodate, stk_var_code sizecode, ordt_qty, ordt_fin_wt, 
			ordt_inv_wt , stk_wt/1000 desp_pending,0 prodnpending_qty , 0  tolarance from  trnsal_order_header, 
			(select stk_comp_code , stk_sono,stk_var_code , sum(stk_wt) stk_wt from  trnsal_finish_stock where  stk_comp_code =1 and stk_destag = ''
             group by stk_comp_code , stk_sono,stk_var_code) aa1  ,                
            trnsal_order_trailer  where 
			ordh_comp_code  = stk_comp_code and
			ordh_sono = stk_sono and
		ordh_comp_code  = ordt_comp_code and
		ordh_fincode = ordt_fincode and 
		ordh_sono = ordt_sono and 
        ordt_var_code = stk_var_code and
        
        
	-- CHAR_LENGTH(ordh_sono) = 6 and 
			ordh_party not in (2151,4886) and
			ordh_comp_code  = compcode 
			
	) a1 , massal_customer , massal_variety , masprd_variety , massal_repr  where 
	(  desp_pending > 0 or  (prodnpending_qty > tolarance and prodnpending_qty > 0.200))
	and  ordh_party = cust_code and 
			repr_code = cust_repr and 
		  sizecode = var_code  and 
			var_grpcode =  var_groupcode  and ordh_party not in (2151,4886) 
			and repr_code = repcode
	group by cust_city,repr_name,cust_ref,ordh_party, ordh_sono, ordh_sodate, sizecode , var_desc,var_groupcode,var_size1,var_size2,var_shade,var_inchcm;  
end if;

