CREATE DEFINER=`root`@`%` PROCEDURE `spsalrep_gst`(compcode int,fincode int,fromdate datetime , todate datetime ,invtype varchar(2))
BEGIN
if invtype = 'TN' then
   select * from trnsal_invoice_header  , massal_customer where   invh_party = cust_code and  invh_comp_code = compcode and invh_fincode = fincode  and invh_date between fromdate and todate and invh_saltype = 'TN' and invh_netamt > 0 order by invh_date,invh_seqno;
else 
     if invtype = 'OS' then
        select * from trnsal_invoice_header  , massal_customer where  invh_party = cust_code and  invh_comp_code = compcode and invh_fincode = fincode and invh_date between fromdate and todate and invh_saltype = 'OS' and invh_netamt > 0 order by invh_date,invh_seqno;    
     else
         select * from trnsal_invoice_header , massal_customer  where  invh_party = cust_code and  invh_comp_code = compcode and invh_fincode = fincode and invh_date between fromdate and todate and invh_netamt > 0 order by invh_date,invh_seqno ;    
     end if;
end if;
END ;;
