CREATE DEFINER=`root`@`%` PROCEDURE `spsalrep_OrderDatewisePending`(compcode int,fincode int,fromdate datetime , todate datetime )
BEGIN

    select cust_city,repr_name,cust_ref,cust_code,ordh_sono, ordh_sodate,var_desc,var_groupcode,var_size2,var_shade,var_inchcm ,ordt_qty , ordt_fin_wt, ordt_inv_wt , ordt_clo_stat, ordt_var_code ,var_bf , var_gsm from trnsal_order_header, trnsal_order_trailer , massal_customer , massal_variety , masprd_variety , massal_repr where 
	ordh_party = cust_code and 
	repr_code = cust_repr and 
	ordh_comp_code  = ordt_comp_code and
	ordh_fincode = ordt_fincode and 
	ordh_sono = ordt_sono and 
	CHAR_LENGTH(ordh_sono) = 6 and 
	ordh_comp_code  = ordt_comp_code and
	ordh_fincode = ordt_fincode and 
	ordt_var_code = var_code and 
	var_grpcode =  var_groupcode and 
	ordt_clo_stat != 'Y' and 
 --  ( ordt_qty > (ordt_inv_wt+ (ordt_qty*0.05)) or 
     ordt_qty > (ordt_inv_wt+ 0.100)  and
-- 	ordt_qty - (ordt_inv_wt+ (ordt_qty*0.05)) > 0.050  and
  --   ( ordt_fin_wt > ordt_inv_wt or ordt_fin_wt = 0 )  and 
	ordh_comp_code  = compcode and
	ordh_fincode = fincode and 
	ordh_sodate between  fromdate and todate;
END ;;
