CREATE DEFINER=`root`@`%` PROCEDURE `spsalrep_OrderStatus_With_Avgrate`(compcode int,fromdate date , todate date)
BEGIN
select repr_name,var_desc, sum(ordt_qty) orderqty, avg(ordt_rate) as avgrate from (
		select repr_name,cust_ref,cust_code,ordh_sono, ordh_sodate,ordh_refdt,var_desc,var_groupcode,var_size2,var_shade,var_inchcm ,ordt_qty , ordt_fin_wt, ordt_inv_wt , ordt_clo_stat , ordt_var_code  ,var_bf , var_gsm , ordt_stk_wt , ordt_stk_reels,ordt_rate from trnsal_order_header, trnsal_order_trailer , massal_customer , massal_variety , masprd_variety , massal_repr where 
		ordh_party = cust_code and 
		repr_code = cust_repr and 
		ordh_comp_code  = ordt_comp_code and
		ordh_fincode = ordt_fincode and 
		ordh_sono = ordt_sono and 
		ordh_comp_code  = ordt_comp_code and
		ordh_fincode = ordt_fincode and 
		ordt_var_code = var_code and 
		var_grpcode =  var_groupcode and 
		ordt_clo_stat = '' and 
		ordh_comp_code = compcode and
		ordh_sodate between fromdate   and todate
) a2 group by repr_name,var_desc  order by repr_name,var_desc ;
END ;;
