CREATE DEFINER=`root`@`%` PROCEDURE `spsalrep_Repw_Monthwise_Order`(compcode int,fromdate date , todate date ,repcode int )
BEGIN
	select repr_name,cust_ref, month(ordh_sodate) repmonth, sum(ordt_qty) weight   
    from trnsal_order_header, trnsal_order_trailer , massal_customer , massal_variety , masprd_variety , massal_repr where 
	ordh_party = cust_code and 
	repr_code = cust_repr and 
	ordh_comp_code  = ordt_comp_code and
	ordh_fincode = ordt_fincode and 
	ordh_sono = ordt_sono and 
	CHAR_LENGTH(ordh_sono) = 6 and 
	ordh_comp_code  = ordt_comp_code and
	ordh_fincode = ordt_fincode and 
	ordt_var_code = var_code and 
	var_grpcode =  var_groupcode and 
	ordh_comp_code  = compcode and
	repr_code = repcode and 
	ordh_sodate between fromdate and todate
    group by repr_name,repr_name,cust_ref, month(ordh_sodate);
END ;;
