CREATE DEFINER=`root`@`%` PROCEDURE `spsalrep_soprint`(compcode int ,fincode int ,fromno int,tono int )
BEGIN
select * from trnsal_order_header , trnsal_order_trailer, massal_customer,
massal_variety , masprd_variety ,masprd_type
where
ordt_comp_code = ordh_comp_code and
ordt_fincode = ordh_fincode and
ordt_sono = ordh_sono and 
ordh_party = cust_code and
ordt_var_code = var_code and
var_grpcode = var_groupcode  and
vargrp_type_code = var_typecode and
ordh_comp_code = compcode  and ordh_fincode = fincode and ordh_sono  between fromno and tono;

END ;;
