CREATE DEFINER=`root`@`%` PROCEDURE `spsal_invoice`(compcode int ,fincode int ,invno varchar(15) )
BEGIN
SELECT  * FROM
    trnsal_invoice_header a,
    trnsal_invoice_trailer b,
	massal_customer c,
     massal_variety d, masprd_variety e, masprd_type f  , mas_state g 
    , mas_delivery_state h , mas_dealer i , massal_shade j
WHERE 
    var_shade = shade_shortcode and
    invh_comp_code = compcode AND invh_fincode = fincode
    and invh_comp_code = invt_compcode AND invh_fincode = invt_fincode
        AND b.invt_var = d.var_code and d.var_grpcode = e.var_groupcode and e.var_typecode =  f.vargrp_type_code
        AND cust_state = g.state_code 
         AND invh_delivery_statecode = h.delivery_state_code
        AND invh_party = cust_code   
        AND cust_dealer = dealer_code   
        AND invh_seqno = invt_seqno
        AND invh_comp_code = compcode
        AND invh_invrefno = invno;
END ;;
DELIMITER ;
