CREATE DEFINER=`root`@`%` PROCEDURE `spsal_inv_order_update`(compcode int, sono varchar(1000)  , sizecode int)
BEGIN
  update trnsal_order_trailer set  ordt_des_tag = "T"  where  
  ordt_comp_code = compcode  
  and ordt_var_code =   sizecode and find_in_set(ordt_sono,sono);

    

END ;;
