CREATE DEFINER=`root`@`%` PROCEDURE `spsal_party_MonthwiseSales_Abstract`(compcode int,fincode int, startdate date,custcode int)
BEGIN
select cust_ref,UPPER(monthname(invh_date)) as rmonth,sum(invh_totwt)/1000 as despwt , sum(invh_netamt) as value1 from 
trnsal_invoice_header , massal_customer 
where invh_party = cust_code and invh_fincode=  fincode  and invh_comp_code= compcode  and invh_date >= startdate  and invh_date <=  curdate()  and invh_party = custcode group by cust_ref,UPPER(monthname(invh_date));
END ;;
