CREATE DEFINER=`root`@`%` PROCEDURE `spsal_prodplan`(compcode int ,ppno int )
BEGIN
select * from 
trn_prodplan_header INNER JOIN  massal_customer ON pp_party  = cust_code
INNER JOIN  masprd_variety ON pp_varcode  = var_groupcode
INNER JOIN  massal_variety ON pp_sizecode = var_code
INNER JOIN  mas_company ON pp_comp_code   = company_code
INNER JOIN  masprd_type ON  vargrp_type_code = var_typecode
WHERE
    pp_advno = ppno AND
    pp_comp_code = compcode;
END ;;
DELIMITER ;
