CREATE DEFINER=`root`@`%` PROCEDURE `spsal_prodplan_trailer`(compcode int ,ppno int )
BEGIN
select * from 
trn_prodplan_trailer 
INNER JOIN  trn_prodplan_trailer_remarks ON  ppt_advno = ppr_advno 
INNER JOIN  masprd_variety ON ppt_varcode  = var_groupcode
INNER JOIN  mas_company ON ppt_comp_code   = company_code
INNER JOIN  masprd_type ON  vargrp_type_code = var_typecode
WHERE
    ppt_comp_code  = ppr_comp_code and 
    ppt_fincode =  ppr_fincode  and 
    ppt_advno = ppno AND
    ppt_comp_code = compcode;
END ;;
