CREATE DEFINER=`root`@`%` PROCEDURE `spsal_Proforma_invoice`(compcode int ,fincode int ,invno int)
BEGIN
SELECT  * FROM
    trnsal_proforma_invoice a,
	massal_customer c,masprd_variety e, masprd_type f  , mas_state g , mas_delivery_state h 
WHERE
      invh_comp_code = compcode AND invh_fincode = fincode
      and invh_variety = e.var_groupcode and e.var_typecode =  f.vargrp_type_code
      AND cust_state = g.state_code 
      AND invh_delivery_state = h.delivery_state_code
      AND invh_party = cust_code   
      AND invh_no  = invno;
END ;;
