CREATE DEFINER=`root`@`%` PROCEDURE `spsal_reel_stock`(compcode int, stockdate date,reelopt varchar(1) ,custcode int )
BEGIN
if custcode = 0 then
	if reelopt = "A" then
		select   var_name,stk_yymm ,stk_rollno , stk_ent_date,
		cast(substring(stk_yymm,3,2) as unsigned) as emonth, case when length(stk_sr_no) = 10 then cast(substring(stk_sr_no,9,2) as unsigned) else 0 end as reelno ,  
		var_size2 , var_inchcm, var_shade,stk_sr_no,stk_wt ,stk_sono,stk_location,cust_ref  from trnsal_finish_stock  , massal_variety , trnsal_order_header , massal_customer  where 
		stk_sono = ordh_sono and ordh_party = cust_code and stk_comp_code = ordh_comp_code and 
		stk_var_code = var_code and stk_comp_code = compcode and 
		(stk_destag = '' or (stk_destag in ('T','D','S','R') and stk_desdt > stockdate) )  
		and  stk_ent_date <= stockdate  order by var_name;
	elseif  reelopt = "F" then
		select   var_name,stk_yymm ,stk_rollno , stk_ent_date,
		cast(substring(stk_yymm,3,2) as unsigned) as emonth, case when length(stk_sr_no) = 10 then cast(substring(stk_sr_no,9,2) as unsigned) else 0 end as reelno ,  
		 var_size2 , var_inchcm, var_shade,stk_sr_no,stk_wt ,stk_sono,stk_location,cust_ref  from trnsal_finish_stock  , massal_variety , trnsal_order_header , massal_customer   where 
		stk_sono = ordh_sono and ordh_party = cust_code and stk_comp_code = ordh_comp_code and 
		stk_var_code = var_code and stk_comp_code = compcode and 
		(stk_destag = '' or (stk_destag in ('T','D','S','R') and stk_desdt > stockdate) )  
		 and case when  var_inchcm = 'I' then var_size2 >16 else var_size2 >41 end
		and  stk_ent_date <= stockdate  order by var_name;
	else
		select   var_name,stk_yymm ,stk_rollno , stk_ent_date,
		cast(substring(stk_yymm,3,2) as unsigned) as emonth, case when length(stk_sr_no) = 10 then cast(substring(stk_sr_no,9,2) as unsigned) else 0 end as reelno ,  
		 var_size2 , var_inchcm, var_shade,stk_sr_no,stk_wt ,stk_sono,stk_location,cust_ref  from trnsal_finish_stock  , massal_variety , trnsal_order_header , massal_customer  where 
		stk_sono = ordh_sono and ordh_party = cust_code and  stk_comp_code = ordh_comp_code and    
		stk_var_code = var_code and stk_comp_code = compcode and 
		(stk_destag = '' or (stk_destag in ('T','D','S','R') and stk_desdt > stockdate) )  
		 and case when  var_inchcm = 'I' then var_size2 <=16 else var_size2 <=41 end
		and  stk_ent_date <= stockdate  order by var_name;
	end if;
else
	if reelopt = "A" then
		select   var_name,stk_yymm ,stk_rollno , stk_ent_date,
		cast(substring(stk_yymm,3,2) as unsigned) as emonth, case when length(stk_sr_no) = 10 then cast(substring(stk_sr_no,9,2) as unsigned) else 0 end as reelno ,  
		var_size2 , var_inchcm, var_shade,stk_sr_no,stk_wt ,stk_sono,stk_location,cust_ref  from trnsal_finish_stock  , massal_variety , trnsal_order_header , massal_customer  where 
		stk_sono = ordh_sono and ordh_party = cust_code and  ordh_party = 2151 and
		stk_var_code = var_code and stk_comp_code = compcode and stk_comp_code = ordh_comp_code and 
		(stk_destag = '' or (stk_destag in ('T','D','S','R') and stk_desdt > stockdate) )  
		and  stk_ent_date <= stockdate  order by var_name;
	elseif  reelopt = "F" then
		select   var_name,stk_yymm ,stk_rollno , stk_ent_date,
		cast(substring(stk_yymm,3,2) as unsigned) as emonth, case when length(stk_sr_no) = 10 then cast(substring(stk_sr_no,9,2) as unsigned) else 0 end as reelno ,  
		 var_size2 , var_inchcm, var_shade,stk_sr_no,stk_wt ,stk_sono,stk_location,cust_ref  from trnsal_finish_stock  , massal_variety , trnsal_order_header , massal_customer   where 
		stk_sono = ordh_sono and ordh_party = cust_code and ordh_party = 2151 and
		stk_var_code = var_code and stk_comp_code = compcode and  stk_comp_code = ordh_comp_code and 
		(stk_destag = '' or (stk_destag in ('T','D','S','R') and stk_desdt > stockdate) )  
		 and case when  var_inchcm = 'I' then var_size2 >16 else var_size2 >41 end
		and  stk_ent_date <= stockdate  order by var_name;
	else
		select   var_name,stk_yymm ,stk_rollno , stk_ent_date,
		cast(substring(stk_yymm,3,2) as unsigned) as emonth, case when length(stk_sr_no) = 10 then cast(substring(stk_sr_no,9,2) as unsigned) else 0 end as reelno ,  
		 var_size2 , var_inchcm, var_shade,stk_sr_no,stk_wt ,stk_sono,stk_location,cust_ref  from trnsal_finish_stock  , massal_variety , trnsal_order_header , massal_customer  where 
		stk_sono = ordh_sono and ordh_party = cust_code and  ordh_party = 2151 and   
		stk_var_code = var_code and stk_comp_code = compcode and stk_comp_code = ordh_comp_code and 
		(stk_destag = '' or (stk_destag in ('T','D','S','R') and stk_desdt > stockdate) )  
		 and case when  var_inchcm = 'I' then var_size2 <=16 else var_size2 <=41 end
		and  stk_ent_date <= stockdate  order by var_name;
	end if;
end if;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
