CREATE DEFINER=`root`@`%` PROCEDURE `spsal_reel_stock_size`(compcode int,sizecode int)
BEGIN
	select   var_name,stk_yymm ,stk_rollno , stk_ent_date,
	cast(substring(stk_yymm,3,2) as unsigned) as emonth, case when length(stk_sr_no) = 10 then cast(substring(stk_sr_no,9,2) as unsigned) else 0 end as reelno ,  
	 var_size2 , var_inchcm, var_shade,stk_sr_no,stk_wt ,stk_sono from trnsal_finish_stock  , massal_variety  where 
	stk_var_code = var_code and stk_comp_code = compcode and  stk_var_code = sizecode  and 
	stk_destag = '' order by stk_sr_no;
END ;;
