CREATE DEFINER=`root`@`%` PROCEDURE `spsal_rep_address`(ccode int)
BEGIN
if ccode = 0 then
    select * from massal_customer,mas_state,massal_repr where cust_state = state_code  and  cust_repr = repr_code; 
else
select * from massal_customer,mas_state,massal_repr where cust_state = state_code  and  cust_repr = repr_code and cust_code = ccode; 
end if;    
END ;;
