CREATE DEFINER=`root`@`%` PROCEDURE `spsal_rep_AllREPwiseOrder`(compcode int,fincode int,fromdate date, todate date)
BEGIN
select repr_name,repr_code,sum(ordt_qty) orderqty from trnsal_order_header , trnsal_order_trailer ,massal_customer , massal_variety ,massal_repr where 
cust_repr = repr_code and
ordt_var_code = var_code and ordh_comp_code = ordt_comp_code and ordh_fincode = ordt_fincode  and ordh_sono = ordt_sono  and ordh_party = cust_code and ordh_comp_code = compcode  and ordh_fincode = fincode and ordh_sodate >= fromdate and ordh_sodate <= todate 
-- and ordh_type  = 'F' 
group by repr_name,repr_code order by repr_name;
END ;;
DELIMITER ;
