CREATE DEFINER=`root`@`%` PROCEDURE `spsal_rep_AvgRate`(compcode int,fincode int,fromdate date , todate date )
BEGIN
	select  InvNo, invh_date, InvWt, Inv_Value, CD_Value , Inv_Value - CD_Value SalesValue , (Inv_Value - CD_Value)/InvWt AvgRate ,quality,cust_name from
	(
	select InvNo ,invh_date,InvWt, Inv_Value , case when CD_Value is NULL then 0 else CD_Value end as CD_Value , quality,cust_name from (
	select invh_invrefno InvNo, invh_date, sum(invt_wt/1000) InvWt, sum(invt_value) as Inv_Value , max(vargrp_type_name) quality,cust_name  from  trnsal_invoice_header , trnsal_invoice_trailer , masprd_variety , masprd_type , massal_customer where invh_party = cust_code and 
	 invt_item = var_groupcode and var_typecode = vargrp_type_code and 
	 invh_comp_code = invt_compcode and invh_fincode = invt_fincode and invh_seqno = invt_seqno  and 
	 invh_comp_code = compcode and invh_fincode = fincode  and invh_date between fromdate  and todate and invh_netamt > 0 
	group by invh_invrefno, invh_date,cust_name
	) a1
	left join 
	(select dbcrt_inv_no, dbcrt_grossvalue CD_Value from acc_dbcrnote_header , acc_dbcrnote_trailer_invoice where dbcr_type = 'CNG' and dbcr_seqno = dbcrt_seqno and  dbcr_comp_code = compcode and dbcr_finid = fincode and dbcr_date  >= fromdate -- between fromdate  and todate
	 ) b1 on InvNo = dbcrt_inv_no
	 )c1 order by invh_date, InvNo;    
END ;;
