CREATE DEFINER=`root`@`%` PROCEDURE `spsal_rep_bfwisesales`(compcode int,fincode int,fromdate date , todate date)
BEGIN
select case when var_bf = 0 then concat(vargrp_type_short_code,'00')  else concat(vargrp_type_short_code,var_bf)  end as quality , vargrp_type_short_code ,
vargrp_type_code,
round(sum(invt_wt)/1000,3) invwt,round(sum(invh_netamt/invh_totwt*invt_wt),0) as invvalue 
 from trnsal_invoice_header, trnsal_invoice_trailer,massal_variety,masprd_variety  ,masprd_type
where 
var_grpcode = var_groupcode and var_typecode =  vargrp_type_code  and 
invh_fincode = invt_fincode and invh_comp_code = invt_compcode and  invh_seqno = invt_seqno and 
invt_var = var_code and
    invh_comp_code = compcode AND
    invh_fincode = fincode AND
    invh_date >= fromdate AND
    invh_date <= todate
group by  vargrp_type_short_code,vargrp_type_code,var_bf order by quality;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
