DELIMITER ;;
CREATE DEFINER=`root`@`%` PROCEDURE `spsal_rep_bf_partywisesales`(compcode int,fincode int,fromdate date , todate date,optall int,optbf varchar(100))
BEGIN
if optall = 0 then
	select case when var_bf = 0 then concat(vargrp_type_short_code,'00')  else concat(vargrp_type_short_code,var_bf)  end as quality , vargrp_type_short_code ,
	vargrp_type_code,cust_ref,cust_code,
	round(sum(invt_wt)/1000,3) invwt,round(sum(invh_netamt/invh_totwt*invt_wt),0) as invvalue 
      ,round(sum((invh_taxableamt-invh_frt_amt)/invh_totwt*invt_wt),0) as taxable 
	 from trnsal_invoice_header, trnsal_invoice_trailer,massal_variety,masprd_variety  ,masprd_type,massal_customer
	where 
	invh_party = cust_code and var_grpcode = var_groupcode and var_typecode =  vargrp_type_code  and 
	invh_fincode = invt_fincode and invh_comp_code = invt_compcode and  invh_seqno = invt_seqno and 
	invt_var = var_code and
    invh_comp_code = compcode AND
	invh_fincode = fincode AND
	invh_date >= fromdate AND
	invh_date <= todate
	group by  vargrp_type_short_code,vargrp_type_code,var_bf,cust_ref,cust_code order by quality,cust_ref;
else
	select case when var_bf = 0 then concat(vargrp_type_short_code,'00')  else concat(vargrp_type_short_code,var_bf)  end as quality , vargrp_type_short_code ,
	vargrp_type_code,cust_ref,cust_code,
	round(sum(invt_wt)/1000,3) invwt,round(sum(invh_netamt/invh_totwt*invt_wt),0) as invvalue 
      ,round(sum((invh_taxableamt-invh_frt_amt)/invh_totwt*invt_wt),0) as taxable 
	from trnsal_invoice_header, trnsal_invoice_trailer,massal_variety,masprd_variety  ,masprd_type,massal_customer
	where 
	invh_party = cust_code and var_grpcode = var_groupcode and var_typecode =  vargrp_type_code  and 
	invh_fincode = invt_fincode and invh_comp_code = invt_compcode and  invh_seqno = invt_seqno and 
	invt_var = var_code and
	invh_comp_code = compcode AND
	invh_fincode = fincode AND
	invh_date >= fromdate AND
	invh_date <= todate and find_in_set(left(var_desc,4),optbf) 
    group by  vargrp_type_short_code,vargrp_type_code,var_bf,cust_ref,cust_code order by quality,cust_ref;
end if;
END ;;
DELIMITER ;
