CREATE DEFINER=`root`@`%` PROCEDURE `spsal_rep_bf_party_Invwisesales`(compcode int,fincode int,fromdate date , todate date,optall int,optbf varchar(100),custcode int )
BEGIN
if optall = 0 then

    select DATE_FORMAT(invh_date, '%d-%m-%Y') as  invh_date,invh_invrefno,round(sum(invt_wt)/1000,3) invwt,round(sum(invh_netamt/invh_totwt*invt_wt),0) as invvalue 
	 from trnsal_invoice_header, trnsal_invoice_trailer,massal_variety,masprd_variety  ,masprd_type,massal_customer
	where 
	invh_party = cust_code and var_grpcode = var_groupcode and var_typecode =  vargrp_type_code  and 
	invh_fincode = invt_fincode and invh_comp_code = invt_compcode and  invh_seqno = invt_seqno and 
	invt_var = var_code and
    invh_comp_code = compcode AND
	invh_fincode = fincode AND
	invh_date >= fromdate AND
	invh_date <= todate and
    invh_party = custcode
	group by  invh_date,invh_invrefno order by invh_date,invh_invrefno;
else
    select DATE_FORMAT(invh_date, '%d-%m-%Y') as  invh_date,invh_invrefno,round(sum(invt_wt)/1000,3) invwt,round(sum(invh_netamt/invh_totwt*invt_wt),0) as invvalue 
    from trnsal_invoice_header, trnsal_invoice_trailer,massal_variety,masprd_variety  ,masprd_type,massal_customer
	where 
	invh_party = cust_code and var_grpcode = var_groupcode and var_typecode =  vargrp_type_code  and 
	invh_fincode = invt_fincode and invh_comp_code = invt_compcode and  invh_seqno = invt_seqno and 
	invt_var = var_code and
	invh_comp_code = compcode AND
	invh_fincode = fincode AND
	invh_date >= fromdate AND
	invh_date <= todate  and invh_party = custcode and find_in_set(left(var_desc,4),optbf) 
    group by  invh_date,invh_invrefno order by invh_date,invh_invrefno;
end if;
END ;;
