/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`%` PROCEDURE `spsal_rep_bundle_receipt_datewise`(compcode int,
fincode int,fromdate date, todate date)
BEGIN
select * from (
select br_date,b.var_name original_size,c.var_name recd_size , sum(br_bundwt)/1000 weight from trnsal_bundle_receipt a, massal_variety b , massal_variety c
where 
br_originalsize = b.var_code and 
br_finishedsize = c.var_code and 
 br_comp_code = compcode and  br_fincode = fincode and br_date between fromdate and todate 
group by br_date,b.var_name,c.var_name ) a1;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
