/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`%` PROCEDURE `spsal_rep_dailysales`(stdate date, eddate date, salcompcode int)
BEGIN
SELECT
	trnsal_invoice_header.invh_invrefno,  trnsal_invoice_header.invh_no, trnsal_invoice_header.invh_date, trnsal_invoice_header.invh_netamt, 
    trnsal_invoice_header.invh_totwt,mas_company.company_name,trnsal_invoice_trailer.invt_wt,trnsal_invoice_trailer.invt_nos,
    massal_customer.cust_ref, massal_variety.var_name, massal_variety.var_size1, massal_variety.var_size2,
    masprd_variety.var_desc,masprd_variety.var_bf,masprd_variety.var_gsm ,massal_variety.var_shade ,massal_variety.var_inchcm
FROM
    { oj ((((trnsal_invoice_header trnsal_invoice_header INNER JOIN trnsal_invoice_trailer trnsal_invoice_trailer ON
    trnsal_invoice_header.invh_fincode = trnsal_invoice_trailer.invt_fincode and 
    trnsal_invoice_header.invh_seqno = trnsal_invoice_trailer.invt_seqno and 
        trnsal_invoice_header.invh_comp_code = trnsal_invoice_trailer.invt_compcode
        )
     INNER JOIN massal_customer massal_customer ON
        trnsal_invoice_header.invh_party = massal_customer.cust_code)
     INNER JOIN mas_company mas_company ON
        trnsal_invoice_header.invh_comp_code = mas_company.company_code)
     INNER JOIN massal_variety massal_variety ON
        trnsal_invoice_trailer.invt_var = massal_variety.var_code)
     INNER JOIN masprd_variety masprd_variety ON
        massal_variety.var_grpcode = masprd_variety.var_groupcode}
where
	trnsal_invoice_header.invh_date >=  stdate 
    AND  trnsal_invoice_header.invh_date <=  eddate 
    AND  trnsal_invoice_header.invh_comp_code = salcompcode;

END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `spsal_rep_daily_report` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`%` PROCEDURE `spsal_rep_daily_report`(compcode int,fromdate date , todate date)
BEGIN
select prtgrp,stk_shift,stk_rollno,
sum(IBitFinNos) IBitFinNos,sum(IFullFinNos) IFullFinNos, 
sum(IIBitFinNos) IIBitFinNos,sum(IIFullFinNos) IIFullFinNos, 
sum(IBitFinWt) IBitFinWt, sum(IFullFinWt) IFullFinWt,sum(IIBitFinWt) IIBitFinWt, sum(IIFullFinWt) IIFullFinWt,
sum(IBitSalesNos) IBitSalesNos,sum(IFullSalesNos) IFullSalesNos, 
sum(IIBitSalesNos) IIBitSalesNos,sum(IIFullSalesNos) IIFullSalesNos, 
sum(IBitSalesWt) IBitSalesWt, sum(IFullSalesWt) IFullSalesWt,sum(IIBitSalesWt) IIBitSalesWt, sum(IIFullSalesWt) IIFullSalesWt
 from (
select 0 prtgrp, stk_shift ,stk_rollno, 
case when length(stk_sono) = 6 and ((var_inchcm = 'I' and  var_size2 <=16 ) or  (var_inchcm = 'C' and var_size2 <=41)) then count(*) else 0 end as IBitFinNos, 
case when length(stk_sono) = 6 and ((var_inchcm = 'I' and  var_size2 > 16 ) or  (var_inchcm = 'C' and var_size2 > 41)) then count(*) else 0 end as IFullFinNos, 
case when length(stk_sono) <> 6 and ((var_inchcm = 'I' and  var_size2 <=16 ) or  (var_inchcm = 'C' and var_size2 <=41)) then count(*) else 0 end as IIBitFinNos, 
case when length(stk_sono) <> 6 and ((var_inchcm = 'I' and  var_size2 > 16 ) or  (var_inchcm = 'C' and var_size2 > 41)) then count(*) else 0 end as IIFullFinNos, 
case when length(stk_sono) = 6 and ((var_inchcm = 'I' and  var_size2 <=16 ) or  (var_inchcm = 'C' and var_size2 <=41)) then sum(stk_wt)/1000  else 0 end as IBitFinWt, 
case when length(stk_sono) = 6 and ((var_inchcm = 'I' and  var_size2 > 16 ) or  (var_inchcm = 'C' and var_size2 > 41)) then sum(stk_wt)/1000  else 0 end as IFullFinWt, 
case when length(stk_sono) <> 6 and ((var_inchcm = 'I' and  var_size2 <=16 ) or  (var_inchcm = 'C' and var_size2 <=41)) then sum(stk_wt)/1000  else 0 end as IIBitFinWt, 
case when length(stk_sono) <> 6 and ((var_inchcm = 'I' and  var_size2 > 16 ) or  (var_inchcm = 'C' and var_size2 > 41)) then sum(stk_wt)/1000  else 0 end as IIFullFinWt,
 0 IBitSalesNos,0 IFullSalesNos,0 IIBitSalesNos,0 IIFullSalesNos,0 IBitSalesWt,0 IFullSalesWt,0 IIBitSalesWt,0 IIFullSalesWt
 from trnsal_finish_stock , massal_variety where stk_var_code = var_code and stk_source = 'R' and stk_comp_code = compcode  and stk_ent_date between fromdate and todate 
 group by stk_shift,stk_rollno,stk_sono ,  var_inchcm , var_size2
 
 union all
 
 select 1 prtgrp, 'Z'  stk_shift,0 stk_rollno ,0 IBitFinNos, 0 IFullFinNos, 0 IIBitFinNos, 0 IIFullFinNos, 0 IBitFinWt, 0 IFullFinWt, 0 IIBitFinWt, 0 IIFullFinWt,
case when length(pckt_sono) = 6 and ((var_inchcm = 'I' and  var_size2 <=16 ) or  (var_inchcm = 'C' and var_size2 <=41)) then count(*) else 0 end as IBitSalesNos, 
case when length(pckt_sono) = 6 and ((var_inchcm = 'I' and  var_size2 > 16 ) or  (var_inchcm = 'C' and var_size2 > 41)) then count(*) else 0 end as IFullSalesNos, 
case when length(pckt_sono) <> 6 and ((var_inchcm = 'I' and  var_size2 <=16 ) or  (var_inchcm = 'C' and var_size2 <=41)) then count(*) else 0 end as IIBitSalesNos, 
case when length(pckt_sono) <> 6 and ((var_inchcm = 'I' and  var_size2 > 16 ) or  (var_inchcm = 'C' and var_size2 > 41)) then count(*) else 0 end as IIFullSalesNos, 
case when length(pckt_sono) = 6 and ((var_inchcm = 'I' and  var_size2 <=16 ) or  (var_inchcm = 'C' and var_size2 <=41)) then sum(pckt_wt)/1000  else 0 end as IBitSalesWt, 
case when length(pckt_sono) = 6 and ((var_inchcm = 'I' and  var_size2 > 16 ) or  (var_inchcm = 'C' and var_size2 > 41)) then sum(pckt_wt)/1000  else 0 end as IFullSalesWt, 
case when length(pckt_sono) <> 6 and ((var_inchcm = 'I' and  var_size2 <=16 ) or  (var_inchcm = 'C' and var_size2 <=41)) then sum(pckt_wt)/1000  else 0 end as IIBitSalesWt, 
case when length(pckt_sono) <> 6 and ((var_inchcm = 'I' and  var_size2 > 16 ) or  (var_inchcm = 'C' and var_size2 > 41)) then sum(pckt_wt)/1000  else 0 end as IIFullSalesWt
 from  trnsal_packslip_header ,trnsal_packslip_trailer ,massal_variety  where pckh_comp_code = pckt_comp_code and pckh_fincode = pckt_fincode and 
pckh_no = pckt_no and pckt_size = var_code and pckh_comp_code = 1 and  pckh_date = fromdate group by pckt_sono ,  var_inchcm , var_size2
 
