trnsal_reelweight_change , trnsal_finish_stock , massal_variety  where oldweight <> newweight and   
oldsize = var_code and comp_code = stk_comp_code and  srno = stk_sr_no   
and stk_ent_date <= fromdate and comp_code = compcode and  ent_date = fromdate
 group by oldsono ,  var_inchcm , var_size2
 
 union all 
 
  select 6 prtgrp, 'Z'  stk_shift,0 stk_rollno ,0 IBitFinNos, 0 IFullFinNos, 0 IIBitFinNos, 0 IIFullFinNos, 0 IBitFinWt, 0 IFullFinWt, 0 IIBitFinWt, 0 IIFullFinWt,
