/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`%` PROCEDURE `spsal_rep_datewise`(
compcode int,
fincode int,
fromdate date, todate date
)
BEGIN
-- select invh_date , round(sum(invh_totwt)/1000,3) invwt , sum(invh_netamt) invamt  from trnsal_invoice_header where invh_comp_code = compcode and invh_fincode = fincode and invh_date >= fromdate and invh_date <= todate
-- group by invh_date order by invh_Date;

select invh_date, sum(noofreels) noofreels , sum(invwt) invwt , sum(invamt) invamt , sum(fullreelwt) fullreelwt, sum(fullreelamt) fullreelamt , sum(fullreelnos) fullreelnos ,
sum(bitreelwt) bitreelwt, sum(bitreelamt) bitreelamt, sum(bitreelnos) bitreelnos
from (
select invh_date ,var_inchcm, var_size2, sum(invt_nos)  noofreels,round(sum(invt_wt)/1000,3) invwt , round(sum(invh_netamt/invh_totwt * invt_wt ),3) invamt, 
case when (var_inchcm = 'I' and var_size2 > 16) or (var_inchcm = 'C'  and var_size2 > 41) then  round(sum(invt_wt)/1000,3)   else 0 end  as fullreelwt,
case when (var_inchcm = 'I' and var_size2 > 16) or (var_inchcm = 'C'  and var_size2 > 41) then  round(sum(invh_netamt/invh_totwt * invt_wt ),3)    else 0 end  as fullreelamt, 
case when (var_inchcm = 'I' and var_size2 > 16) or (var_inchcm = 'C'  and var_size2 > 41) then  sum(invt_nos)  else 0 end  as fullreelnos,
case when (var_inchcm = 'I' and var_size2 <= 16) or (var_inchcm = 'C'  and var_size2 <=  41) then  round(sum(invt_wt)/1000,3)   else 0 end  as bitreelwt,
case when (var_inchcm = 'I' and var_size2 <= 16) or (var_inchcm = 'C'  and var_size2 <=  41)  then  round(sum(invh_netamt/invh_totwt * invt_wt ),3)    else 0 end  as bitreelamt, 
case when (var_inchcm = 'I' and var_size2 <= 16) or (var_inchcm = 'C'  and var_size2 <=  41)  then  sum(invt_nos)  else 0 end  as  bitreelnos
from trnsal_invoice_header ,trnsal_invoice_trailer,  massal_variety where 
invh_comp_code = invt_compcode and invh_fincode = invt_fincode and invh_seqno = invt_seqno and invt_var = var_code and
invh_comp_code = compcode and invh_fincode = fincode and invh_date >= fromdate and invh_date <= todate
group by invh_date,var_inchcm, var_size2 order by invh_date
) a1 group by invh_date order by invh_date;
END ;;
DELIMITER ;
