CREATE DEFINER=`root`@`%` PROCEDURE `spsal_rep_datewise_dc`(compcode int,fincode int,fromdate date, todate date)
BEGIN
select * from trn_delivery_challan h, trn_delivery_challan_reellist t , massal_variety v , masprd_variety p,massal_customer c
where  v.var_grpcode = p.var_groupcode and h.dc_seqno = t.dc_seqno and dc_size = var_code and dc_cutter = cust_code 
and dc_comp_code = compcode and  dc_fincode = fincode and dc_date between fromdate and todate;
END ;;
