DELIMITER ;;
CREATE DEFINER=`root`@`%` PROCEDURE `spsal_rep_DC_Pending`(compcode int,
fincode int,fromdate date, todate date)
BEGIN

select 
dc_seqno, dc_no, dc_date, dcs_size, dc_varsize, dcweight, br_dcdate, br_dcno, br_originalsize, bund_varsize, sum(recdweight) recdweight
from (
select * from 
(select dc_seqno,dc_no,dc_date,dcs_size,var_name as dc_varsize,sum(dcs_weight)/1000 dcweight from trn_delivery_challan ,  trn_delivery_challan_sizewise  , massal_variety  where  dcs_size = var_code and  dc_comp_code = compcode and  dc_fincode = fincode and dc_date between fromdate and todate and dc_seqno = dcs_seqno group by dc_seqno,dc_no,dc_date,dcs_size )a1
 left join
(select br_dcdate,br_dcno,br_originalsize,var_name as bund_varsize,sum(br_bundwt)/1000 recdweight from trnsal_bundle_receipt , massal_variety  where br_originalsize = var_code and br_fincode = fincode and br_comp_code = compcode group by br_dcdate,br_dcno,br_originalsize
 union all
 select dcrr_dcdate  br_dcdate, dcrr_seqno br_dcno, dccr_dcsize br_originalsize, var_name as  bund_varsize,  sum(dccr_wt/1000) recdweight from trn_delivery_challan_reel_receipt , massal_variety
where dccr_dcsize = var_code and  dcrr_comp_code = compcode  and dcrr_fincode = fincode   group by dcrr_dcdate,dcrr_seqno,dccr_dcsize
) b1
on a1.dc_date = b1.br_dcdate and a1.dc_seqno = b1.br_dcno  and a1.dcs_size = b1.br_originalsize
)aa1 group by dc_seqno, dc_no, dc_date, dcs_size, dc_varsize, dcweight, br_dcdate, br_dcno, br_originalsize, bund_varsize;

/*
select * from 
(select dc_seqno,dc_no,dc_date,dcs_size,var_name as dc_varsize,sum(dcs_weight)/1000 dcweight from trn_delivery_challan ,  trn_delivery_challan_sizewise  , massal_variety  where  dcs_size = var_code and  dc_comp_code = compcode and  dc_fincode = fincode and dc_date between fromdate and todate and dc_seqno = dcs_seqno group by dc_seqno,dc_no,dc_date,dcs_size )a1
 left join
(select br_dcdate,br_dcno,br_originalsize,var_name as bund_varsize,sum(br_bundwt)/1000 recdweight from trnsal_bundle_receipt , massal_variety  where br_originalsize = var_code and br_fincode = fincode and br_comp_code = compcode group by br_dcdate,br_dcno,br_originalsize
 union all
 select dcrr_dcdate  br_dcdate, dcrr_seqno br_dcno, dccr_dcsize br_originalsize, var_name as  bund_varsize,  sum(dccr_wt/1000) recdweight from trn_delivery_challan_reel_receipt , massal_variety
where dccr_dcsize = var_code and  dcrr_comp_code = compcode  and dcrr_fincode = fincode   group by dcrr_dcdate,dcrr_seqno,dccr_dcsize
) b1
on a1.dc_date = b1.br_dcdate and a1.dc_seqno = b1.br_dcno  and a1.dcs_size = b1.br_originalsize;
*/

END ;;
