CREATE DEFINER=`root`@`%` PROCEDURE `spsal_rep_finishedproduction`(compcode int,fromdate date, todate date)
BEGIN
SELECT
	*
FROM    
     trnsal_finish_stock  trnsal_finish_stock 
     INNER JOIN massal_variety massal_variety ON
       trnsal_finish_stock.stk_var_code = massal_variety.var_code 
	INNER JOIN masprd_variety masprd_variety ON
        massal_variety.var_grpcode = masprd_variety.var_groupcode
     join massal_shade shade on   massal_variety.var_shade  = shade.shade_shortcode
	 join masprd_type prdtype on prdtype.vargrp_type_code = masprd_variety.var_typecode
where
	trnsal_finish_stock.stk_ent_date >=   fromdate
    AND  trnsal_finish_stock.stk_ent_date <=  todate
    AND  trnsal_finish_stock.stk_comp_code = compcode
    AND stk_source = 'R'
    ;
 
END ;;
