/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`%` PROCEDURE `spsal_rep_GSTR1`(compcode int,fincode int,fromdate date , todate date ,gsttype varchar(1) )
BEGIN

if gsttype = 'R'  then
select 
printorder,saldate, cust_ref, vouchertype, voucherno, gstin, quantity, GrossTotal, osgstsalesvalue, igstamount, roundedoff, tngstsalesvalue, sgstamount, cgstamount, tcsamount, frt_Igst, frt_gst, flyashgst, wastegst
from 
(select case when invh_saltype = 'TN' then '1' else '2' end printorder, invh_date as saldate,cust_ref,case when invh_saltype = 'TN' then 'TN GST SALES' else 'OS IGST SALES' end  vouchertype,invh_invrefno voucherno,
cust_gstin  gstin, invh_totwt /1000  quantity , invh_netamt  GrossTotal,case when invh_igst_amt > 0 then invh_taxableamt else 0 end osgstsalesvalue,
case when invh_igst_amt > 0 then invh_igst_amt else 0 end  igstamount,invh_roff  roundedoff ,
case when invh_cgst_amt > 0 then invh_taxableamt else 0 end  tngstsalesvalue,case when invh_sgst_amt > 0 then invh_sgst_amt else 0 end  sgstamount,
case when invh_cgst_amt > 0 then invh_cgst_amt else 0 end cgstamount,case when invh_tcs_amt > 0 then invh_tcs_amt else 0 end tcsamount,
case when invh_saltype = 'OS' and invh_frt_amt > 0  then invh_frt_amt else 0 end frt_Igst,case when invh_saltype = 'TN' and invh_frt_amt > 0  then invh_frt_amt else 0 end  frt_gst,
0  flyashgst,0  wastegst from trnsal_invoice_header , massal_customer where  invh_party =cust_code and invh_comp_code = compcode  and invh_fincode = fincode and invh_date between fromdate and todate

union all

select case when os_state_type = 'TNOS' then '3' else '4' end printorder,os_date saldate, sup_refname cust_ref, case when os_state_type = 'TNOS' then 'TNOS GST SALES' else 'OSOS IGST SALES' end vouchertype,
os_invno voucherno, sup_gstin gstin, os_qty quantity, os_netamt GrossTotal, case when os_state_type = 'OSOS' then os_taxable else 0 end as osgstsalesvalue, os_igst, os_rounding roundedoff ,
case when os_state_type = 'TNOS' then  os_taxable else 0 end as tngstsalesvalue, os_sgst, os_cgst, 0 tcsamount, 0 frt_Igst, 0 frt_gst, 
 case when os_item = 1 then os_taxable else 0 end flyashgst,
 case when os_item <> 1 then os_taxable else 0 end wastegst  
from trn_other_sales ,maspur_supplier_master where os_custcode = sup_code and  os_compcode = compcode and os_fincode = fincode and os_date between fromdate and todate  and sup_gst_type = 'R' 

) ad1 order by printorder,saldate;

else

select 
printorder,saldate, cust_ref, vouchertype, voucherno, gstin, quantity, GrossTotal, osgstsalesvalue, igstamount, roundedoff, tngstsalesvalue, sgstamount, cgstamount, tcsamount, frt_Igst, frt_gst, flyashgst, wastegst
from 
(
select case when os_state_type = 'TNOS' then '3' else '4' end printorder,os_date saldate, sup_refname cust_ref, case when os_state_type = 'TNOS' then 'TNOS GST SALES' else 'OSOS IGST SALES' end vouchertype,
os_invno voucherno, sup_gstin gstin, os_qty quantity, os_netamt GrossTotal, case when os_state_type = 'OSOS' then os_taxable else 0 end as osgstsalesvalue, os_igst igstamount, os_rounding roundedoff ,
case when os_state_type = 'TNOS' then  os_taxable else 0 end as tngstsalesvalue, os_sgst sgstamount ,  os_cgst cgstamount, 0 tcsamount, 0 frt_Igst, 0 frt_gst, 
 case when os_item = 1 then os_taxable else 0 end flyashgst,
 case when os_item <> 1 then os_taxable else 0 end wastegst  
from trn_other_sales ,maspur_supplier_master where os_custcode = sup_code and  os_compcode = compcode and os_fincode = fincode and os_date between fromdate and todate  and sup_gst_type <> 'R' 

) ad1 order by printorder,saldate;
end if;

END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `spsal_rep_GSTR1_Abstract` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`%` PROCEDURE `spsal_rep_GSTR1_Abstract`(compcode int,fincode int,fromdate date , todate date )
BEGIN
select  '1' printorder, invh_date as saldate,cust_name,'B2B Invoices - 4A,4B,4C,6B,6C' vouchertype,invh_invrefno voucherno,cust_gstin  gstin, invh_netamt  GrossTotal, 
invh_taxableamt  salesvalue,invh_igst_amt igstamount,invh_roff  roundedoff ,invh_sgst_amt sgstamount,invh_cgst_amt cgstamount,invh_tcs_amt tcsamount,invh_frt_amt frt_gst
from trnsal_invoice_header , massal_customer where  invh_party =cust_code and invh_comp_code = compcode and invh_fincode = fincode and invh_netamt > 0 and invh_date between fromdate and todate  AND cust_gst_type = 'R'

union all
select  '2' printorder, invh_date as saldate,cust_name,'B2C(Small) Invoices' vouchertype,invh_invrefno voucherno,cust_gstin  gstin, invh_netamt  GrossTotal, 
invh_taxableamt  salesvalue,invh_igst_amt igstamount,invh_roff  roundedoff ,invh_sgst_amt sgstamount,invh_cgst_amt cgstamount,invh_tcs_amt tcsamount,invh_frt_amt frt_gst
from trnsal_invoice_header , massal_customer where  invh_party =cust_code and invh_comp_code = compcode and invh_fincode = fincode and invh_netamt > 0 and invh_date between fromdate and todate  AND cust_gst_type = 'U'

union all
select printorder,  saldate, cust_name, vouchertype, voucherno, gstin, sum(GrossTotal) GrossTotal , sum(salesvalue) salesvalue, sum(igstamount)igstamount, sum(roundedoff) roundedoff, sum(sgstamount) sgstamount, sum(cgstamount) cgstamount, sum(tcsamount) tcsamount, sum(frt_gst) frt_gst from (
select '1' printorder,os_date saldate,   cust_name, 'B2B Invoices - 4A,4B,4C,6B,6C'  vouchertype,
os_invno voucherno, cust_gstin gstin, os_netamt GrossTotal, os_taxable salesvalue, os_igst igstamount, os_rounding roundedoff ,
os_sgst sgstamount, os_cgst as cgstamount , 0 tcsamount, 0 frt_gst 
from trn_other_sales ,massal_customer where os_custcode = cust_code and os_compcode = compcode and os_fincode = fincode and cust_gst_type = 'R'
and os_date between fromdate and todate
) a group by printorder,  saldate, cust_name, vouchertype, voucherno, gstin
union all
select '2' printorder,os_date saldate, cust_name, 'B2C(Small) Invoices'  vouchertype,
os_invno voucherno, cust_gstin gstin, os_netamt GrossTotal, os_taxable salesvalue, os_igst igstamount, os_rounding roundedoff ,
os_sgst sgstamount, os_cgst as cgstamount , 0 tcsamount, 0 frt_gst 
from trn_other_sales ,massal_customer where os_custcode = cust_code and os_compcode = compcode and os_fincode = fincode and cust_gst_type <> 'R'
and os_date between fromdate and todate

union all
select  '3' printorder , dbcr_date saldate,cust_name, 'Credit/Debit Note' vouchertype ,
dbcr_vouno voucherno,cust_gstin,
dbcr_value , dbcrt_taxable salesvalue ,
dbcrt_igstvalue igstamount,
dbcrt_rounding roundedoff,
dbcrt_cgstvalue sgstamount,
dbcrt_sgstvalue cgstamount,
dbcrt_tcsvalue tcsamount,
0 frt_gst
from acc_dbcrnote_header , acc_dbcrnote_trailer , massal_customer where dbcr_value > 0 and  dbcr_type in ('SDN') and 
dbcr_partycode = cust_code and  dbcr_party_type = 'C' and dbcr_seqno = dbcrt_seqno and  
dbcr_comp_code = compcode and dbcr_finid = fincode and dbcr_date between fromdate and todate 

union all
select  '3' printorder , dbcr_date saldate,cust_name, 'Credit/Debit Note' vouchertype ,
dbcr_vouno voucherno,cust_gstin,
dbcr_value * -1 dbcr_value , dbcrt_taxable * -1  salesvalue ,
dbcrt_igstvalue * -1 as igstamount,
dbcrt_rounding as roundedoff,
dbcrt_cgstvalue * -1 as sgstamount,
dbcrt_sgstvalue * -1 as cgstamount,
dbcrt_tcsvalue  * -1 as tcsamount,
0 frt_gst
from acc_dbcrnote_header , acc_dbcrnote_trailer , massal_customer where dbcr_value > 0 and  dbcr_type in ('CNG') and 
dbcr_partycode = cust_code and  dbcr_party_type = 'C' and dbcr_seqno = dbcrt_seqno and  
dbcr_comp_code = compcode and dbcr_finid = fincode and dbcr_date between fromdate and todate;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `spsal_rep_GSTR1_Abstract_Main` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`%` PROCEDURE `spsal_rep_GSTR1_Abstract_Main`(compcode int,fincode int,fromdate date , todate date )
BEGIN

select printorder,gtype,vouchertype,count(*) voucount,sum(salesvalue) salesvalue, 
sum(igstamount) igstamount, 
sum(cgstamount) cgstamount, 
sum(sgstamount) sgstamount, 
0 cessamt,
sum(igstamount) + sum(cgstamount) + sum(sgstamount)  as taxamount ,
sum(GrossTotal) GrossTotal
from (
select  '1' printorder, 'b2b' gtype, invh_date as saldate,cust_name,'B2B Invoices - 4A,4B,4C,6B,6C' vouchertype,invh_invrefno voucherno,cust_gstin  gstin, invh_netamt  GrossTotal, 
invh_taxableamt  salesvalue,invh_igst_amt igstamount,invh_roff  roundedoff ,invh_sgst_amt sgstamount,invh_cgst_amt cgstamount,invh_tcs_amt tcsamount,invh_frt_amt frt_gst
from trnsal_invoice_header , massal_customer where  invh_party =cust_code and invh_comp_code = compcode and invh_fincode = fincode and invh_netamt > 0 and invh_date between fromdate and todate AND cust_gst_type = 'R'

union all
select  '2' printorder, 'b2c' gtype, invh_date as saldate,cust_name,'B2C(Small) Invoices' vouchertype,invh_invrefno voucherno,cust_gstin  gstin, invh_netamt  GrossTotal, 
invh_taxableamt  salesvalue,invh_igst_amt igstamount,invh_roff  roundedoff ,invh_sgst_amt sgstamount,invh_cgst_amt cgstamount,invh_tcs_amt tcsamount,invh_frt_amt frt_gst
from trnsal_invoice_header , massal_customer where  invh_party =cust_code and invh_comp_code = compcode and invh_fincode = fincode and invh_netamt > 0 and invh_date between fromdate and todate AND cust_gst_type = 'U'
union all
select printorder, gtype, saldate, cust_name, vouchertype, voucherno, gstin, sum(GrossTotal) GrossTotal , sum(salesvalue) salesvalue, sum(igstamount)igstamount, sum(roundedoff) roundedoff, sum(sgstamount) sgstamount, sum(cgstamount) cgstamount, sum(tcsamount) tcsamount, sum(frt_gst) frt_gst from (
select '1' printorder, 'b2b' gtype, os_date saldate,   cust_name, 'B2B Invoices - 4A,4B,4C,6B,6C'  vouchertype,
os_invno voucherno, cust_gstin gstin, os_netamt GrossTotal, os_taxable salesvalue, os_igst igstamount, os_rounding roundedoff ,
os_sgst sgstamount, os_cgst as cgstamount , 0 tcsamount, 0 frt_gst 
from trn_other_sales ,massal_customer where os_custcode = cust_code and os_compcode = compcode and os_fincode = fincode and cust_gst_type = 'R' and os_netamt > 0
and os_date between fromdate and todate
) a group by printorder, gtype, saldate, cust_name, vouchertype, voucherno, gstin
union all
select '2' printorder,'b2c' gtype, os_date saldate, cust_name, 'B2C(Small) Invoices'  vouchertype,
os_invno voucherno, cust_gstin gstin, os_netamt GrossTotal, os_taxable salesvalue, os_igst igstamount, os_rounding roundedoff ,
os_sgst sgstamount, os_cgst as cgstamount , 0 tcsamount, 0 frt_gst 
from trn_other_sales ,massal_customer where os_custcode = cust_code and os_compcode = compcode and os_fincode = fincode and cust_gst_type <> 'R' and os_netamt > 0
and os_date between fromdate and todate

union all
select  '3' printorder ,'cndn' gtype, dbcr_date saldate,cust_name, 'Credit/Debit Note' vouchertype ,
dbcr_vouno voucherno,cust_gstin,
dbcr_value , dbcrt_taxable salesvalue ,
dbcrt_igstvalue igstamount,
dbcrt_rounding roundedoff,
dbcrt_cgstvalue sgstamount,
dbcrt_sgstvalue cgstamount,
dbcrt_tcsvalue tcsamount,
0 frt_gst
from acc_dbcrnote_header , acc_dbcrnote_trailer , massal_customer where dbcr_value > 0 and  dbcr_type in ('SDN') and 
dbcr_partycode = cust_code and  dbcr_party_type = 'C' and dbcr_seqno = dbcrt_seqno and  
dbcr_comp_code = compcode and dbcr_finid = fincode and dbcr_date between fromdate and todate 

union all
select  '3' printorder ,'cndn' gtype, dbcr_date saldate,cust_name, 'Credit/Debit Note' vouchertype ,
dbcr_vouno voucherno,cust_gstin,
dbcr_value * -1 dbcr_value , dbcrt_taxable * -1  salesvalue ,
dbcrt_igstvalue * -1 as igstamount,
dbcrt_rounding as roundedoff,
dbcrt_cgstvalue * -1 as sgstamount,
dbcrt_sgstvalue * -1 as cgstamount,
dbcrt_tcsvalue  * -1 as tcsamount,
0 frt_gst
from acc_dbcrnote_header , acc_dbcrnote_trailer , massal_customer where dbcr_value > 0 and  dbcr_type in ('CNG') and 
dbcr_partycode = cust_code and  dbcr_party_type = 'C' and dbcr_seqno = dbcrt_seqno and  
dbcr_comp_code = compcode and dbcr_finid = fincode and dbcr_date between fromdate and todate
)a1 group by printorder,gtype,vouchertype order by printorder;

END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `spsal_rep_GSTR1_debit_credit_note` */;
