CREATE DEFINER=`root`@`%` PROCEDURE `spsal_rep_GSTR1_Details_DocumentWise`(compcode int,fincode int,fromdate date , todate date,gsttype varchar(4)  )
BEGIN
 if gsttype = 'b2b' then
select  
 cust_name,invh_date as saldate,DATE_FORMAT(invh_date, '%d-%m-%Y') as invdate,invh_invrefno voucherno,
 invh_taxableamt  salesvalue,invh_igst_amt igstamount,
 invh_cgst_amt cgstamount,
 invh_sgst_amt sgstamount,
 invh_netamt  invamount ,
 invh_vouno  invh_vouno 
 from trnsal_invoice_header , massal_customer where  invh_party =cust_code and invh_comp_code = compcode and invh_fincode = fincode and invh_netamt > 0 and invh_date between fromdate and todate AND cust_gst_type = 'R'
union all
select 
 cust_name,os_date as saldate,DATE_FORMAT(os_date, '%d-%m-%Y') as invdate, invh_invrefno voucherno,
 os_taxable  salesvalue,os_igst igstamount,
 os_cgst cgstamount,
 os_sgst sgstamount,
 os_netamt  invamount,
 os_acvou_no  invh_vouno 
 from trn_other_sales ,massal_customer where os_custcode = cust_code and os_compcode = compcode and os_fincode = fincode and cust_gst_type = 'R' 
and os_date between fromdate and todate;

elseif gsttype = 'b2c' then
select 
 cust_name,os_date as saldate,DATE_FORMAT(os_date, '%d-%m-%Y') as invdate,invh_invrefno voucherno,
 os_taxable  salesvalue,os_igst igstamount,
 os_cgst cgstamount,
 os_sgst sgstamount,
 os_netamt  invamount ,
 os_acvou_no  invh_vouno 
 from trn_other_sales ,massal_customer where os_custcode = cust_code and os_compcode = compcode and os_fincode = fincode and cust_gst_type <> 'R'
 and os_date between fromdate and todate 
 
 union all
  
  select  
 cust_name,invh_date as saldate,DATE_FORMAT(invh_date, '%d-%m-%Y') as invdate,invh_invrefno voucherno,
 invh_taxableamt  salesvalue,invh_igst_amt igstamount,
 invh_cgst_amt cgstamount,
 invh_sgst_amt sgstamount,
 invh_netamt  invamount ,
 invh_vouno  invh_vouno 
 from trnsal_invoice_header , massal_customer where  invh_party =cust_code and invh_comp_code = compcode and invh_fincode = fincode and invh_netamt > 0 and invh_date between fromdate and todate and  cust_gst_type = 'U';

else   -- if gsttype = 'cndn' then 
 select 
cust_name,dbcr_date saldate, DATE_FORMAT(dbcr_date, '%d-%m-%Y') as invdate,invh_invrefno voucherno,
dbcrt_taxable salesvalue ,
dbcrt_igstvalue igstamount,
dbcrt_cgstvalue cgstamount,
dbcrt_sgstvalue sgstamount,
dbcr_value  invamount ,
dbcr_vouno invh_vouno

from acc_dbcrnote_header , acc_dbcrnote_trailer , massal_customer where dbcr_value > 0 and  dbcr_type in ('SDN') and 
dbcr_partycode = cust_code and  dbcr_party_type = 'C' and dbcr_seqno = dbcrt_seqno and  
dbcr_comp_code = compcode and dbcr_finid = fincode and dbcr_date between fromdate and todate 

union all
 select 
cust_name,dbcr_date saldate, DATE_FORMAT(dbcr_date, '%d-%m-%Y') as invdate,invh_invrefno voucherno,
dbcrt_taxable salesvalue ,
dbcrt_igstvalue igstamount,
dbcrt_cgstvalue cgstamount,
dbcrt_sgstvalue sgstamount,
dbcr_value  invamount ,
dbcr_vouno invh_vouno

from acc_dbcrnote_header , acc_dbcrnote_trailer , massal_customer where dbcr_value > 0 and  dbcr_type in ('CNG') and 
dbcr_partycode = cust_code and  dbcr_party_type = 'C' and dbcr_seqno = dbcrt_seqno and  
dbcr_comp_code = compcode and dbcr_finid = fincode and dbcr_date between fromdate and todate ;

end if;

END ;;
