/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`%` PROCEDURE `spsal_rep_GSTR1_Ledgerwise_Credit_Note`(compcode int,fincode int,fromdate date , todate date,findledname varchar(60))
BEGIN
select a1.* from (
select  dbcr_vouno invh_invrefno, DATE_FORMAT(dbcr_date, '%d-%m-%Y')   invh_date , '4' as grp,'1' saltype, mas.cust_name, concat('LESS : CREDIT NOTE NOTE ',led.cust_name) as ledgername,dbcr_qty qty, dbcrt_taxable * -1 goodsValue,dbcrt_frtamt* -1 freight,
dbcrt_taxable * -1 taxable,
dbcrt_igstvalue * -1 igst,dbcrt_cgstvalue * -1  cgst,dbcrt_sgstvalue * -1 sgst,0 tcs,dbcr_value*-1 totalamt
 from acc_dbcrnote_header h, acc_dbcrnote_trailer t, massal_customer led , massal_customer mas  where  
 dbcr_partycode = mas.cust_code and 
 led.cust_code = dbcr_ledcode and  
 dbcr_seqno = dbcrt_seqno and dbcr_comp_code = compcode and dbcr_finid = fincode and dbcr_date between fromdate and todate and dbcr_type in ('CNG') and dbcr_party_type = 'C' and dbcrt_taxable >0
 ) a1 where ledgername = findledname;

END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
