CREATE DEFINER=`root`@`%` PROCEDURE `spsal_rep_GSTR1_Ledgerwise_Debit_Note`(compcode int,fincode int,fromdate date , todate date,findledname varchar(60))
BEGIN
select a1.* from (
select  dbcr_vouno invh_invrefno, DATE_FORMAT(dbcr_date, '%d-%m-%Y')   invh_date , '4' as grp,'1' saltype, mas.cust_name, concat('ADD : DEBIT NOTE ',led.cust_name) as ledgername,dbcr_qty qty, dbcrt_taxable  goodsValue,dbcrt_frtamt freight,
dbcrt_taxable  taxable,
dbcrt_igstvalue  igst,dbcrt_cgstvalue  cgst,dbcrt_sgstvalue  sgst,0 tcs,dbcr_value totalamt
 from acc_dbcrnote_header h, acc_dbcrnote_trailer t, massal_customer led , massal_customer mas  where  
 dbcr_partycode = mas.cust_code and 
 led.cust_code = dbcr_ledcode and  
 dbcr_seqno = dbcrt_seqno and dbcr_comp_code = compcode and dbcr_finid = fincode and dbcr_date between fromdate and todate and dbcr_type in ('SDN') and dbcr_party_type = 'C' and dbcrt_taxable >0
 ) a1 where ledgername = findledname;

END ;;
