DELIMITER ;;
CREATE DEFINER=`root`@`%` PROCEDURE `spsal_rep_GSTR1_Ledgerwise_OtherSales_Details`(compcode int,fincode int,fromdate date , todate date,findledname varchar(60))
BEGIN
select * from 
(
select DATE_FORMAT(os_date, '%d-%m-%Y')  invh_date,os_invno invh_invrefno,mas.cust_name cust_name,
os_qty qty,
os_value goodsValue,
0 freight,
os_value taxable,
os_igst igst,
os_cgst cgst,
os_sgst sgst,
0 tcs,
os_netamt totalamt,
case when os_igst > 0  then 2 else 1 end as saltype,
case when os_igst > 0 then os.cust_name else tn.cust_name  end as ledgername
from trn_other_sales h ,mas_othersales_item_master m , massal_customer tn , massal_customer os   , massal_customer mas
where os_custcode = mas.cust_code and os_item = salitem_code and  tn.cust_code = salitem_salesledcode_tn and os.cust_code = salitem_salesledcode_os and 
os_compcode = compcode and  os_fincode = fincode  and 
os_date between  fromdate and todate
) a1 where ledgername = findledname;
END ;;
DELIMITER ;
