/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`%` PROCEDURE `spsal_rep_GSTR1_Ledgwise_Details`(compcode int,fincode int,fromdate date , todate date)
BEGIN

select a2.*,a3.doclist from
(
select grp,saltype,ledgername,sum(qty) qty,
sum(goodsValue) goodsValue,
sum(freight) freight,
sum(taxable)  taxable,
sum(igst)  igst,
sum(cgst) cgst,
sum(sgst) sgst,
sum(igst)+sum(cgst)+sum(sgst) tottaxamt ,count(*) as  nos from 
(
select  '1' as grp,  case when invh_taxtag  = 2 then 1 else 2 end as saltype,
ledgername ,
 Cast(invh_totwt/1000 as decimal(18,3)) as qty,
Cast(invh_taxableamt-invh_frt_amt  as decimal(18,2)) as goodsValue,
invh_frt_amt freight,
invh_taxableamt taxable,
invh_igst_amt igst,
invh_cgst_amt cgst,
invh_sgst_amt sgst,
invh_tcs_amt tcs,
invh_netamt totalamt
from trnsal_invoice_header h, 
(
select  invt_compcode ,invt_fincode, invt_seqno , case when invh_taxtag  = 2 then max(tnled.cust_name) else max(osled.cust_name) end as ledgername from trnsal_invoice_header h,  trnsal_invoice_trailer t , masprd_variety v  ,
masprd_type ptype,
massal_customer tnled,
massal_customer osled
where  
invh_comp_code = invt_compcode and invh_fincode = invt_fincode and invh_seqno = invt_seqno and invt_item = var_groupcode
and var_typecode = vargrp_type_code and tn_sales_ledcode = tnled.cust_code and os_sales_ledcode = osled.cust_code 
and invh_comp_code = compcode and invh_fincode = fincode and  invh_date between fromdate and todate and invh_netamt > 0
group by invt_compcode ,invt_fincode, invt_seqno 
) tr
where  
invh_comp_code = invt_compcode and invh_fincode = invt_fincode and invh_seqno = invt_seqno
and invh_comp_code = compcode and invh_fincode =  fincode and  invh_date between fromdate and todate
union all
select '2' as grp, 
  case when os_igst > 0  then 2 else 1 end as saltype,
case when os_igst > 0 then os.cust_name else tn.cust_name  end as ledgername,os_qty qty,
os_value goodsValue,
0 freight,
os_value taxable,
os_igst igst,
os_cgst cgst,
os_sgst sgst,
0 tcs,
os_netamt totalamt
 from trn_other_sales h ,mas_othersales_item_master m , massal_customer tn , massal_customer os 
where os_item = salitem_code and  tn.cust_code = salitem_salesledcode_tn and os.cust_code = salitem_salesledcode_os and 
os_compcode = compcode and  os_fincode = fincode  and 
os_date between fromdate and todate and os_netamt > 0
union all
select '3' as grp,'1' saltype, concat('ADD : DEBIT NOTE ',cust_name) as ledgername,0  qty, dbcrt_taxable goodsValue,dbcrt_frtamt freight,
dbcrt_taxable taxable,
dbcrt_igstvalue igst,dbcrt_cgstvalue  cgst,dbcrt_sgstvalue sgst,0 tcs,0 totalamt
 from acc_dbcrnote_header , acc_dbcrnote_trailer , massal_customer  where  cust_code = dbcr_ledcode and  dbcr_seqno = dbcrt_seqno and dbcr_comp_code = compcode  and dbcr_finid = fincode and dbcr_date between  fromdate and todate and dbcr_type in ('SDN') and dbcr_party_type = 'C' and dbcrt_taxable >0
 union all
select '4' as grp,'1' saltype, concat('LESS : CREDIT NOTE NOTE ',cust_name) as ledgername,0 qty, dbcrt_taxable * -1 goodsValue,dbcrt_frtamt* -1 freight,
dbcrt_taxable * -1 taxable,
dbcrt_igstvalue * -1 igst,dbcrt_cgstvalue * -1  cgst,dbcrt_sgstvalue * -1 sgst,0 tcs,0 totalamt
 from acc_dbcrnote_header , acc_dbcrnote_trailer , massal_customer  where  cust_code = dbcr_ledcode and  dbcr_seqno = dbcrt_seqno and dbcr_comp_code = compcode  and dbcr_finid = fincode and dbcr_date between  fromdate and todate and dbcr_type in ('CNG') and dbcr_party_type = 'C' and dbcrt_taxable >0
) a1 group by grp,saltype,ledgername order by grp,saltype,ledgername
) a2 left join


(
select ledgername,group_concat(frominvno, case when toinvno != '' then concat(' TO ',toinvno) else '' end  ,' ',totnos order by frominvno) as doclist from
(
select ledgername,prefix,suffix, min(invh_no) startno, max(invh_no) endno ,
concat(prefix,min(invh_no) ,suffix) frominvno,
case when max(invh_no) > min(invh_no)  then concat(prefix,max(invh_no) ,suffix) else '' end as toinvno, 
case when max(invh_no) > min(invh_no)  then concat('= ', max(invh_no) - min(invh_no)+1,' NOS') else concat('= ',max(invh_no) - min(invh_no)+1,' NO') end as  totnos

from (select cr.*,
             row_number() over (partition by ledgername,prefix,suffix order by invh_no) as seqnum
      from (
select ledgername,left(invh_invrefno,3) prefix , right(invh_invrefno,6) suffix ,invh_no
from
(
select  invt_compcode ,invt_fincode, invt_seqno , case when invh_taxtag  = 2 then max(tnled.cust_name) else max(osled.cust_name) end as ledgername,
invh_invrefno ,invh_no from trnsal_invoice_header h,  trnsal_invoice_trailer t , masprd_variety v  ,
masprd_type ptype,
massal_customer tnled,
massal_customer osled
where  
invh_comp_code = invt_compcode and invh_fincode = invt_fincode and invh_seqno = invt_seqno and invt_item = var_groupcode
and var_typecode = vargrp_type_code and tn_sales_ledcode = tnled.cust_code and os_sales_ledcode = osled.cust_code 
and invh_comp_code = compcode and invh_fincode = fincode and  invh_date between fromdate and todate and invh_netamt > 0
group by invt_compcode ,invt_fincode, invt_seqno,invh_invrefno,invh_no order by ledgername,invh_no
) a1 group by ledgername,invh_no ,left(invh_invrefno,3) , right(invh_invrefno,6)            
)     cr
 ) cr
group by ledgername, prefix,suffix, (invh_no - seqnum) order by prefix,frominvno
)a1 group by ledgername



union all 
select ledgername,group_concat(frominvno, case when toinvno != '' then concat(' TO ',toinvno) else '' end  ,' ',totnos order by frominvno) as doclist from (
select ledgername,prefix,suffix, min(os_docno) startno, max(os_docno) endno ,
concat(prefix,min(os_docno) ,suffix) frominvno,
case when max(os_docno) > min(os_docno)  then concat(prefix,max(os_docno) ,suffix) else '' end as toinvno, 
case when max(os_docno) > min(os_docno)  then concat('= ', max(os_docno) - min(os_docno)+1,' NOS') else concat('= ',max(os_docno) - min(os_docno)+1,' NO') end as  totnos
from (

select cr.*,
             row_number() over (partition by ledgername,prefix,suffix order by os_docno) as seqnum
from (
select ledgername,left(os_invno,5) prefix , right(os_invno,6) suffix ,os_docno
from
(
select os_state_type,  os_invno , os_docno, case when os_state_type = 'TNOS' then tn.cust_name else os.cust_name end as ledgername from
trn_other_sales h ,mas_othersales_item_master m , massal_customer tn , massal_customer os 
where os_item = salitem_code and  tn.cust_code = salitem_salesledcode_tn and os.cust_code = salitem_salesledcode_os and 
os_compcode = compcode and  os_fincode = fincode and 
os_date between fromdate and todate
) a1 group by ledgername,os_docno ,left(os_invno,5) , right(os_invno,6) 
) cr 
 ) cr
group by ledgername, prefix,suffix, (os_docno - seqnum) order by prefix,frominvno
)a1 group by ledgername

union all

select ledgername,group_concat(startno, case when endno != startno then concat(' TO ',endno) else '' end  ,' ',totnos order by startno) as doclist from (
select ledgername, min(dbcr_no) startno, max(dbcr_no) endno ,
case when max(dbcr_no) > min(dbcr_no)  then concat('= ', max(dbcr_no) - min(dbcr_no)+1,' NOS') else concat('= ',max(dbcr_no) - min(dbcr_no)+1,' NO') end as  totnos
from (

select cr.*,
             row_number() over (partition by ledgername order by dbcr_no) as seqnum
from (
select concat('ADD : DEBIT NOTE ',cust_name) as ledgername,dbcr_no
 from acc_dbcrnote_header , acc_dbcrnote_trailer , massal_customer  where  cust_code = dbcr_ledcode and  dbcr_seqno = dbcrt_seqno and
 dbcr_comp_code = compcode  and dbcr_finid = fincode and dbcr_date between  fromdate and todate and dbcr_type in ('SDN') and dbcr_party_type = 'C' and dbcrt_taxable >0
)cr
 ) cr
group by ledgername, (dbcr_no - seqnum) order by ledgername
)a1 group by ledgername

union all
/*
select ledgername,group_concat('CNG-',startno, case when endno != startno then concat(' TO ','CNG-',endno) else '' end  ,' ',totnos order by startno) as doclist from (
select ledgername, min(dbcr_no) startno, max(dbcr_no) endno ,
case when max(dbcr_no) > min(dbcr_no)  then concat('= ', max(dbcr_no) - min(dbcr_no)+1,' NOS') else concat('= ',max(dbcr_no) - min(dbcr_no)+1,' NO') end as  totnos
from (

select cr.*,
             row_number() over (partition by ledgername order by dbcr_no) as seqnum
from (
select concat('LESS : CREDIT NOTE NOTE ',cust_name) as ledgername,dbcr_no
 from acc_dbcrnote_header , acc_dbcrnote_trailer , massal_customer  where  cust_code = dbcr_ledcode and  dbcr_seqno = dbcrt_seqno and
 dbcr_comp_code = compcode  and dbcr_finid = fincode and dbcr_date between  fromdate and todate and dbcr_type in ('CNG') and dbcr_party_type = 'C' and dbcrt_taxable >0
)cr
 ) cr
group by ledgername, (dbcr_no - seqnum) order by ledgername
)a1 group by ledgername
*/
select ledgername ,group_concat(doclist) doclist
from (
select ledgername , case when processed = "A" then doclist else concat('         CANCELLED : ',doclist)  end as doclist  from (
select ledgername,processed,group_concat('CNG-',startno, case when endno != startno then concat(' TO ','CNG-',endno) else '' end  ,' ',totnos order by startno) as doclist from (

select ledgername,processed, min(dbcr_no) startno, max(dbcr_no) endno ,
case when max(dbcr_no) > min(dbcr_no)  then concat('= ', max(dbcr_no) - min(dbcr_no)+1,' NOS') else concat('= ',max(dbcr_no) - min(dbcr_no)+1,' NO') end as  totnos
from (

select cr.*,
             row_number() over (partition by ledgername,processed order by  dbcr_no) as seqnum
from (
 select concat('LESS : CREDIT NOTE NOTE ',cust_name) as ledgername,'A' processed, dbcr_no
 from acc_dbcrnote_header , acc_dbcrnote_trailer , massal_customer  where  cust_code = dbcr_ledcode and  dbcr_seqno = dbcrt_seqno and
 dbcr_comp_code = compcode and dbcr_finid = fincode and dbcr_date between  fromdate and todate  and dbcr_type in ('CNG') and dbcr_party_type = 'C' and dbcrt_taxable >0
 union all
 select concat('LESS : CREDIT NOTE NOTE ',cust_name) as ledgername, 'C' processed, dbcr_no
 from acc_dbcrnote_header , acc_dbcrnote_trailer , massal_customer  where  cust_code = dbcr_ledcode and  dbcr_seqno = dbcrt_seqno and
 dbcr_comp_code = compcode  and dbcr_finid = fincode and dbcr_date between  fromdate and todate  and dbcr_type in ('CNG') and dbcr_party_type = 'C' and dbcrt_taxable =0
 
 )cr
 ) cr
group by ledgername,processed,(dbcr_no - seqnum) order by ledgername



)a1 group by ledgername,processed
)a2 group by ledgername,processed
)a4 group by ledgername
) a3 on a2.ledgername = a3.ledgername


;
END ;;
DELIMITER ;
