DELIMITER ;;
CREATE DEFINER=`root`@`%` PROCEDURE `spsal_rep_GSTR1_otherthan_sales`(compcode int,fincode int,fromdate date , todate date , gstrtype varchar(1) )
BEGIN

if gstrtype = 'C' then
select dbcr_date ,cust_ref, case when dbcr_type = 'SDN' then 'Debit Note' else 'Credit Note' end vouchertype ,dbcr_vouno,cust_gstin,
dbcr_value , 0 as rebate,dbcrt_rounding,
case when cust_state <> 24 then dbcrt_grossvalue else 0 end as osvalue,
case when cust_state <> 24 then dbcrt_igstvalue else 0 end as osigst,
case when cust_state = 24 then dbcrt_grossvalue else 0 end as tnvalue,
case when cust_state = 24 then dbcrt_cgstvalue else 0 end as tncgst,
case when cust_state = 24 then dbcrt_sgstvalue else 0 end as tnsgst,
dbcrt_tcsvalue
from acc_dbcrnote_header , acc_dbcrnote_trailer , massal_customer where dbcr_type in ('CNG') and 
dbcr_partycode = cust_code and  dbcr_party_type = 'C' and dbcr_seqno = dbcrt_seqno and  
dbcr_comp_code = compcode  and dbcr_finid = fincode and dbcr_date between  fromdate and todate

union all 

select reth_date dbcr_date ,cust_ref, 'Sales Return' vouchertype ,reth_invno dbcr_vouno,cust_gstin,
reth_amt dbcr_value , 0 as rebate, reth_roff dbcrt_rounding,
case when cust_state <> 24 then reth_taxable else 0 end as osvalue,
case when cust_state <> 24 then reth_igst_amt else 0 end as osigst,
case when cust_state = 24 then reth_taxable else 0 end as tnvalue,
case when cust_state = 24 then reth_cgst_amt else 0 end as tncgst,
case when cust_state = 24 then reth_cgst_amt else 0 end as tnsgst,
0 dbcrt_tcsvalue
from trnsal_salret_header , massal_customer  where  reth_cust = cust_code  and   reth_comp_code = compcode and reth_fincode = fincode and reth_date between fromdate and todate;

else
if gstrtype = 'D' then
select dbcr_date ,cust_ref, case when dbcr_type = 'SDN' then 'Debit Note' else 'Credit Note' end vouchertype ,dbcr_vouno,cust_gstin,
dbcr_value , 0 as rebate,dbcrt_rounding,
case when cust_state <> 24 then dbcrt_grossvalue else 0 end as osvalue,
case when cust_state <> 24 then dbcrt_igstvalue else 0 end as osigst,
case when cust_state = 24 then dbcrt_grossvalue else 0 end as tnvalue,
case when cust_state = 24 then dbcrt_cgstvalue else 0 end as tncgst,
case when cust_state = 24 then dbcrt_sgstvalue else 0 end as tnsgst,
dbcrt_tcsvalue
from acc_dbcrnote_header , acc_dbcrnote_trailer , massal_customer where dbcr_type in ('SDN') and 
dbcr_partycode = cust_code and  dbcr_party_type = 'C' and dbcr_seqno = dbcrt_seqno and  
dbcr_comp_code = compcode  and dbcr_finid = fincode and dbcr_date between  fromdate and todate;

else

select dbcr_date ,sup_refname cust_ref, case when dbcr_type = 'SDN' then 'Debit Note' else 'Credit Note' end vouchertype ,dbcr_vouno,sup_gstin cust_gstin,
dbcr_value , 0 as rebate,dbcrt_rounding,
case when sup_state <> 24 then dbcrt_grossvalue else 0 end as osvalue,
case when sup_state <> 24 then dbcrt_igstvalue else 0 end as osigst,
case when sup_state = 24 then dbcrt_grossvalue else 0 end as tnvalue,
case when sup_state = 24 then dbcrt_cgstvalue else 0 end as tncgst,
case when sup_state = 24 then dbcrt_sgstvalue else 0 end as tnsgst,
dbcrt_tcsvalue
from acc_dbcrnote_header , acc_dbcrnote_trailer , maspur_supplier_master where dbcr_type in ('CNG') and 
dbcr_partycode = sup_code and  dbcr_party_type = 'S' and dbcr_seqno = dbcrt_seqno and  
dbcr_comp_code = compcode  and dbcr_finid = fincode and dbcr_date between  fromdate and todate;
end if;
end if;
END ;;
DELIMITER ;
