DELIMITER ;;
CREATE DEFINER=`root`@`%` PROCEDURE `spsal_rep_invwisesales`(compcode int,fincode int,fromdate date , todate date)
BEGIN
select invh_invrefno, invh_date,cust_ref,invh_totwt/1000 invwt,invh_netamt from  trnsal_invoice_header , massal_customer where invh_party = cust_code and invh_comp_code = compcode and
invh_fincode = fincode  and invh_date between fromdate  and todate and invh_netamt > 0  order by invh_date, invh_seqno;

END ;;
DELIMITER ;
