DELIMITER ;;
CREATE DEFINER=`root`@`%` PROCEDURE `spsal_rep_monthwise`(compcode int,fincode int,fromdate date , todate date)
BEGIN
select repr_name , month(invh_date) repmonth,   round(sum(invh_totwt/1000),3) as weight   from trnsal_invoice_header , massal_customer,massal_repr where invh_party = cust_code and cust_repr = repr_code and 
invh_comp_code = compcode and invh_fincode = fincode and invh_date between fromdate and todate group by repr_name , month(invh_date); 
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
