DELIMITER ;;
CREATE DEFINER=`root`@`%` PROCEDURE `spsal_rep_MonthwiseSales_Abstract`(compcode int,fincode int, startdate date, enddate date ,opt int )
BEGIN
if opt = 1 then
select UPPER(monthname(accref_voudate)) as rmonth  , sum(acctran_dbamt) dramt ,  sum(acctran_cramt) cramt  from acc_ref ref  join acc_tran tran on  
tran.acctran_accref_seqno = ref.accref_seqno   join massal_customer mas on  tran.acctran_led_code = mas.cust_code 	 where  
accref_vou_type  in ('GSI','OSI') and  accref_comp_code = compcode  and accref_finid = fincode and accref_voudate between startdate and  enddate  and cust_type <> 'G'  group by upper(monthname(accref_voudate));
else
select UPPER(monthname(accref_voudate)) as rmonth  , sum(acctran_dbamt) dramt ,  sum(acctran_cramt) cramt  from acc_ref ref  join acc_tran tran on  
tran.acctran_accref_seqno = ref.accref_seqno   join massal_customer mas on  tran.acctran_led_code = mas.cust_code 	 where  
accref_vou_type  in ('PSP','PSC','PLW','PIW','PFU','PDE','PUR','PGS','PWP') and  accref_comp_code = compcode  and accref_finid = fincode and accref_voudate between startdate and  enddate  and cust_type <> 'G'  group by upper(monthname(accref_voudate));
end if;
END ;;
DELIMITER ;
