/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`%` PROCEDURE `spsal_rep_Monthwise_finished_despatched`(compcode int,fincode int, startdate date)
BEGIN
  select rmonth,sum(finwt) as finwt,sum(despwt) as despwt,sum(value1) as value1 from ( select UPPER(monthname(invh_date)) as rmonth,  0 as finwt, sum(invt_wt)/1000 as despwt , sum(invt_value) as value1 from trnsal_invoice_header a , trnsal_invoice_trailer b 
  where a.invh_fincode= b.invt_fincode  and a.invh_comp_code = b.invt_compcode and a.invh_seqno = b.invt_seqno and  
  a.invh_fincode= fincode    and a.invh_comp_code= compcode and invh_date >= startdate and invh_date <= curdate() group by UPPER(monthname(invh_date)) 
  union all 
  select UPPER(monthname(stk_ent_date)) as rmonth ,sum(stk_wt/1000) as finwt ,0 as despwt, 0 as value1  from trnsal_finish_stock where 
  stk_comp_code = compcode and stk_finyear = fincode   and stk_ent_date >= startdate and stk_ent_date <= curdate() 
  group by UPPER(monthname(stk_ent_date)) ) a group by rmonth;
END ;;
DELIMITER ;
