/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`%` PROCEDURE `spsal_rep_month_bf_abstract`(compcode int,fincode int,fromdate date , todate date )
BEGIN
select ryear, rmonth, rmonthname,sum(bf0) bf0,
 sum(bf14_upto180) bf14_upto180 , sum(bf14_a180_bf16b180) bf14_a180_bf16b180, sum(bf16_a180_bf18b180) bf16_a180_bf18b180, sum(bf18_a180_bf20b350) bf18_a180_bf20b350, sum(bf_above20) bf_above20 ,sum(salqty) salqty from
(
select ryear,  rmonth,rmonthname,
case when var_bf = 0 then salqty else 0 end as bf0,
case when var_bf = 14 and var_gsm <=150 then salqty else 0 end as bf14_upto180,
case when (var_bf = 14 and var_gsm > 150) or (var_bf = 16 and var_gsm <= 150)   then salqty else 0 end as bf14_a180_bf16b180,
case when (var_bf = 16 and var_gsm > 150) or (var_bf = 18 and var_gsm <= 150)   then salqty else 0 end as bf16_a180_bf18b180,
case when (var_bf = 18 and var_gsm > 150) or (var_bf = 20 and var_gsm <= 150)   then salqty else 0 end as bf18_a180_bf20b350,
case when (var_bf = 20  and var_gsm >150) or var_bf > 20 then salqty else 0 end as bf_above20,
 salqty
from (
select year(invh_date) ryear, month(invh_date) rmonth ,monthname(invh_date) rmonthname ,var_bf,var_gsm,
Cast(sum(invt_wt/1000) as decimal(18,3)) as salqty
from (
SELECT
invh_date , var_bf,var_gsm, invt_wt
FROM
    mas_company mas_company INNER JOIN trnsal_invoice_header trnsal_invoice_header ON
        mas_company.company_code = trnsal_invoice_header.invh_comp_code
     INNER JOIN massal_customer massal_customer ON
        trnsal_invoice_header.invh_party = massal_customer.cust_code
        INNER JOIN trnsal_invoice_trailer trnsal_invoice_trailer ON
       trnsal_invoice_header.invh_fincode = trnsal_invoice_trailer.invt_fincode and trnsal_invoice_header.invh_comp_code = trnsal_invoice_trailer.invt_compcode and  trnsal_invoice_header.invh_seqno = trnsal_invoice_trailer.invt_seqno
     INNER JOIN massal_variety massal_variety ON
        trnsal_invoice_trailer.invt_var = massal_variety.var_code
     INNER JOIN masprd_variety masprd_variety ON
        trnsal_invoice_trailer.invt_item = masprd_variety.var_groupcode
WHERE
    trnsal_invoice_header.invh_comp_code = compcode AND
    trnsal_invoice_header.invh_fincode = fincode AND
    trnsal_invoice_header.invh_date >= fromdate AND
    trnsal_invoice_header.invh_date <= todate and invh_netamt > 0

-- union all 
    
-- select dn_date invh_date , var_bf,var_gsm, dn_wt invt_wt from trn_delivery_note , massal_variety , masprd_variety where var_grpcode = var_groupcode and dn_size = var_code and dn_comp_code = compcode and dn_fincode = fincode and dn_date between fromdate and todate   

        )  aa group by year(invh_date),month(invh_date),monthname(invh_date) ,var_bf,var_gsm 
)aa2        
)aa3 group by  ryear, rmonth,rmonthname;
END ;;
DELIMITER ;
