DELIMITER ;;
CREATE DEFINER=`root`@`%` PROCEDURE `spsal_rep_Month_partywise_despatched`(compcode int,fincode int, startdate date , enddate date)
BEGIN
select cust_code,cust_ref ,round(sum(invt_wt)/1000,3) as despwt , sum(invt_value) as value1 from 
trnsal_invoice_header a , trnsal_invoice_trailer b , massal_customer c where  a.invh_party = cust_code 
and a.invh_fincode= b.invt_fincode  and a.invh_comp_code = b.invt_compcode and a.invh_seqno = b.invt_seqno 
and  a.invh_fincode= fincode  and a.invh_comp_code= compcode and invh_date >= startdate and invh_date <= enddate 
group by cust_code,cust_ref order  by cust_ref;
END ;;
DELIMITER ;
