/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`%` PROCEDURE `spsal_rep_Month_Purchase_Details`(compcode int,fincode int, startdate date, enddate date)
BEGIN

select DATE_FORMAT(accref_voudate, '%d-%m-%Y') as voudate, cust_name,
  accref_vou_type voutype,accref_vouno , accref_payref_no, acctran_dbamt ,  acctran_cramt  , accref_vou_type   , 
  cust_code ,accref_seqno ,accseqno, taxable, cgstamt, sgstamt, igstamt, tdsamt ,cust_gstin  from (
select  * from acc_ref ref  join acc_tran tran on  tran.acctran_accref_seqno = ref.accref_seqno 
  join massal_customer mas on  tran.acctran_led_code = mas.cust_code where  accref_vou_type  in  ('PSP','PSC','PLW','PIW','PFU','PDE','PUR','PGS','PWP') and  
  accref_comp_code = compcode and accref_finid = fincode  and accref_voudate between startdate and  enddate  and cust_type <> 'G' order by accref_voudate,accref_seqno    
) a1 left join 
(
 select minh_acc_seqno accseqno, sum(mint_value) taxable,sum(mint_cgst_amt) cgstamt,sum(mint_sgst_amt) sgstamt,sum(mint_igst_amt) igstamt ,0 as tdsamt  from trnpur_min_header ,    trnpur_min_trailer 
  where  minh_comp_code = mint_comp_code and  minh_fin_code = mint_fin_code and
    minh_minno = mint_minno and 
  minh_comp_code = compcode and  minh_fin_code = fincode and  minh_mindate between startdate and  enddate  group by  minh_acc_seqno
union all  
select rech_acc_seqno accseqno, rech_itemvalue taxable,rech_cgst_amt  cgstamt, rech_sgst_amt sgstamt, rech_igst_amt igstamt ,0 as tdsamt from trnrm_receipt_header where rech_compcode = compcode and  rech_fincode = fincode and  rech_date between startdate and  enddate  
union all  
select rech_acc_seqno accseqno, rech_itemvalue taxable,rech_cgst_amt  cgstamt, rech_sgst_amt sgstamt, rech_igst_amt igstamt,0 as tdsamt  from trnfu_receipt_header where rech_compcode = compcode and  rech_fincode = fincode and  rech_date between startdate and  enddate  
union all
select pur_accseqno accseqno, pur_taxvalue taxable, pur_cgst_amt cgstamt, pur_sgst_amt sgstamt, pur_igst_amt igstamt ,0 as tdsamt from acc_direct_purchase where pur_compcode = compcode and pur_finid = fincode and pur_date between   startdate and  enddate 
union all
select eh_seqno accseqno, eh_taxable taxable, eh_cgstamount cgstamt, eh_sgstamount sgstamt, eh_igstamount igstamt , eh_tdsamount tdsamt from acc_expenses_header
where eh_compcode = compcode and   eh_fincode = fincode and eh_voudate between startdate and  enddate ) b1
 on a1.accref_seqno = b1.accseqno order by accref_voudate,accref_seqno;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `spsal_rep_Month_Sales_Details` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
