/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`%` PROCEDURE `spsal_rep_Month_Sales_Details`(compcode int,fincode int, startdate date, enddate date)
BEGIN

   select  DATE_FORMAT(accref_voudate, '%d-%m-%Y') as voudate, cust_name,
   case when accref_vou_type = 'GSI' then case when left(accref_payref_no,2) = 'TN' THEN  'TN GST Sales' else 'OS IGST Sales' end else case when left(accref_payref_no,2) = 'TN' THEN  'Other GST Sales' else 'Other IGST Sales' end end  as voutype, 
   accref_payref_no, acctran_dbamt ,  acctran_cramt  , accref_vou_type   , cust_code ,accref_vouno ,accref_seqno , accseqno, invh_saltype, invh_frt_rate, invh_frt_amt, invh_taxableamt, invh_sgst_amt, invh_cgst_amt, invh_igst_amt, invwt , cust_gstin  from 
(select * from acc_ref ref  join acc_tran tran on  tran.acctran_accref_seqno = ref.accref_seqno   
   join massal_customer mas on  tran.acctran_led_code = mas.cust_code where  accref_vou_type  in ('GSI','OSI') and
   accref_comp_code = compcode and accref_finid = fincode and accref_voudate between startdate and  enddate  and cust_type <> 'G' 
) a1  left join 

(select invh_acc_refno accseqno, invh_saltype, invh_frt_rate , invh_frt_amt,  invh_taxableamt, invh_sgst_amt,invh_cgst_amt, invh_igst_amt,invh_totwt/1000 invwt from trnsal_invoice_header where  invh_comp_code = compcode and invh_fincode = fincode and invh_date between startdate and  enddate
union all
select os_acc_seqno accseqno, os_state_type invh_saltype, 0 invh_frt_rate , 0 invh_frt_amt, os_taxable invh_taxableamt, os_sgst invh_sgst_amt, os_cgst invh_cgst_amt,os_igst invh_igst_amt,os_qty invwt from trn_other_sales where os_compcode = compcode and os_fincode = fincode and os_date between startdate and  enddate 
)  b1
 on a1.accref_seqno = b1.accseqno order by accref_voudate,accref_seqno;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `spsal_rep_Order_History` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`%` PROCEDURE `spsal_rep_Order_History`(compcode int,fincode int,fromdate date, todate date)
BEGIN
 select * from 
(select  ordh_sono , ordh_sodate ,  cust_name , var_desc , shade_shortname , sum(ordt_qty) ordt_qty  , sum(ordt_fin_wt) ordt_fin_wt from trnsal_order_header , trnsal_order_trailer ,massal_customer , massal_variety , masprd_variety , massal_shade where 
var_grpcode = var_groupcode and var_shade = shade_shortcode and 
ordt_var_code = var_code and ordh_comp_code = ordt_comp_code and ordh_fincode = ordt_fincode  and ordh_sono = ordt_sono  and 
ordh_party = cust_code and ordh_comp_code = compcode and ordh_fincode = fincode and ordh_sodate >= fromdate and ordh_sodate <= todate and length(ordh_sono) = 6 
group by  ordh_sono , ordh_sodate ,  cust_name , var_desc , shade_shortname) ordh
left join (
select  pckt_sono,pckt_sodate, pack_variety , pack_shade,   GROUP_CONCAT(pckh_invno ORDER BY pckh_invno SEPARATOR ', ') AS pckh_invno, sum(invwt) invwt, 
sum(with1day) with1day,
sum(with1_4days) with1_4days,
sum(with5_7days) with5_7days,
sum(with8_10days) with8_10days,
sum(above10days) above10days
from (
select  pckt_sono,pckt_sodate,var_desc pack_variety , shade_shortname  pack_shade, pckh_date , pckh_invno ,     CAST(SUM(pckt_wt)/1000.0 AS DECIMAL(18,3)) AS invwt, 
case when datediff(pckh_date,pckt_sodate) = 0 then CAST(SUM(pckt_wt)/1000.0 AS DECIMAL(18,3))  else 0 end  as with1day,
case when datediff(pckh_date,pckt_sodate) > 0  and datediff(pckh_date,pckt_sodate) <= 4  then  CAST(SUM(pckt_wt)/1000.0 AS DECIMAL(18,3))  else 0 end  as with1_4days,
case when datediff(pckh_date,pckt_sodate) > 4  and datediff(pckh_date,pckt_sodate) <= 7  then CAST(SUM(pckt_wt)/1000.0 AS DECIMAL(18,3)) else 0 end  as with5_7days,
case when datediff(pckh_date,pckt_sodate) > 8  and datediff(pckh_date,pckt_sodate) <= 10  then CAST(SUM(pckt_wt)/1000.0 AS DECIMAL(18,3))  else 0 end  as with8_10days,
case when datediff(pckh_date,pckt_sodate) > 10 then CAST(SUM(pckt_wt)/1000.0 AS DECIMAL(18,3))  else 0 end  as above10days
 from trnsal_packslip_header , trnsal_packslip_trailer , massal_variety , masprd_variety , massal_shade where
var_grpcode = var_groupcode and var_shade = shade_shortcode and 
pckt_size = var_code and
  pckh_comp_code = pckt_comp_code and  pckh_fincode = pckt_fincode and pckh_no = pckt_no and
pckh_comp_code = compcode  and pckh_fincode = fincode  and pckt_sodate between  fromdate and todate group by pckt_sono,pckt_sodate,var_desc, shade_shortname,pckh_date,pckh_invno
) a1 group by pckt_sono,pckt_sodate,pack_variety, pack_shade
) pack on ordh_sono = pckt_sono and var_desc = pack_variety and shade_shortname =  pack_shade 

order by  ordh_sodate , ordh_sono;
 
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `spsal_rep_order_vs_despatch` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`%` PROCEDURE `spsal_rep_order_vs_despatch`()
BEGIN
select * from tmp_order_desp , massal_variety , masprd_variety where itemcode = var_code and var_grpcode = var_groupcode order by sodate;
/*
select * from
(
select * from
(
select cust_ref, ordh_sono,ordh_sodate,ordt_var_code ,ordt_qty from trnsal_order_header ,trnsal_order_trailer , massal_customer where  ordh_party = cust_code and ordh_comp_code = ordt_comp_code and ordh_fincode = ordt_fincode and ordh_sono = ordt_sono and ordh_comp_code = compcode and ordh_sodate between fromdate and todate
) ord
left join
(
select pckh_date, pckt_sono,pckt_size,sum(pckt_wt)/1000  desp_qty from trnsal_packslip_header , trnsal_packslip_trailer where pckt_comp_code = pckh_comp_code and pckh_fincode = pckt_fincode and pckh_no = pckt_no and pckh_comp_code = compcode  and pckt_sodate between fromdate and todate group by pckh_date,pckt_sono,pckt_size
) slip 
on ordh_sono = pckt_sono and  ordt_var_code = pckt_size
) a1 join massal_variety on ordt_var_code = var_code order by ordh_sodate,ordh_sono,var_name;
*/
END ;;
