CREATE DEFINER=`root`@`%` PROCEDURE `spsal_rep_partywise`(
compcode int,fincode int,fromdate date, todate date
)
BEGIN
select cust_ref ,invh_date, invh_seqno, invh_invrefno , round(sum(invh_totwt)/1000,3) invwt , sum(invh_netamt) invamt  from trnsal_invoice_header ,massal_customer 
where invh_party = cust_code and  invh_comp_code = compcode and invh_fincode = fincode and invh_date >= fromdate and invh_date <= todate
group by cust_ref ,invh_date, invh_seqno, invh_invrefno  order by cust_ref;
END ;;
