CREATE DEFINER=`root`@`%` PROCEDURE `spsal_rep_partywise_sales`(compcode int,fincode int,fromdate datetime , todate datetime ,partytype varchar(1), custcodelist varchar(100) )
BEGIN
if partytype = "A" then 
SELECT
    mas_company.company_name,
    trnsal_invoice_header.invh_comp_code, trnsal_invoice_header.invh_fincode, trnsal_invoice_header.invh_no, trnsal_invoice_header.invh_date, trnsal_invoice_header.invh_netamt, trnsal_invoice_header.invh_totwt,
    trnsal_invoice_header.invh_seqno, trnsal_invoice_trailer.invt_wt, trnsal_invoice_trailer.invt_urate,trnsal_invoice_trailer.invt_value,trnsal_invoice_header.invh_our_ordno,
    massal_customer.cust_code, massal_customer.cust_ref,
    masprd_variety.var_desc,masprd_variety.var_bf,masprd_variety.var_gsm,
    massal_variety.var_name, massal_variety.var_unit, massal_variety.var_size1, massal_variety.var_size2,massal_variety.var_shade ,massal_variety.var_inchcm,
    trnsal_invoice_header.invh_cgst_amt,  trnsal_invoice_header.invh_sgst_amt,  trnsal_invoice_header.invh_igst_amt,  trnsal_invoice_header.invh_insamt,  trnsal_invoice_header.invh_frt_amt ,
    trnsal_invoice_header.invh_crd_days , trnsal_invoice_header.invh_invrefno  , trnsal_invoice_header.invh_grace_days
FROM
    { oj ((((mas_company mas_company INNER JOIN trnsal_invoice_header trnsal_invoice_header ON
        mas_company.company_code = trnsal_invoice_header.invh_comp_code)
     INNER JOIN massal_customer massal_customer ON
        trnsal_invoice_header.invh_party = massal_customer.cust_code)
     INNER JOIN trnsal_invoice_trailer trnsal_invoice_trailer ON
       trnsal_invoice_header.invh_fincode = trnsal_invoice_trailer.invt_fincode and trnsal_invoice_header.invh_comp_code = trnsal_invoice_trailer.invt_compcode and  trnsal_invoice_header.invh_seqno = trnsal_invoice_trailer.invt_seqno)
     INNER JOIN massal_variety massal_variety ON
        trnsal_invoice_trailer.invt_var = massal_variety.var_code)
     INNER JOIN masprd_variety masprd_variety ON
        trnsal_invoice_trailer.invt_item = masprd_variety.var_groupcode}
WHERE
    trnsal_invoice_header.invh_comp_code = compcode AND
    trnsal_invoice_header.invh_fincode = fincode AND
    trnsal_invoice_header.invh_date >= fromdate AND
    trnsal_invoice_header.invh_date <= todate and 
        invh_netamt > 0
ORDER BY
    massal_customer.cust_code ASC,
    massal_variety.var_name ASC,
    trnsal_invoice_header.invh_seqno ASC;
else
SELECT
    mas_company.company_name,
    trnsal_invoice_header.invh_comp_code, trnsal_invoice_header.invh_fincode, trnsal_invoice_header.invh_no, trnsal_invoice_header.invh_date, trnsal_invoice_header.invh_netamt, trnsal_invoice_header.invh_totwt,
    trnsal_invoice_header.invh_seqno, trnsal_invoice_trailer.invt_wt, trnsal_invoice_trailer.invt_urate,trnsal_invoice_trailer.invt_value,trnsal_invoice_header.invh_our_ordno,
    massal_customer.cust_code, massal_customer.cust_ref,
    masprd_variety.var_desc,masprd_variety.var_bf,masprd_variety.var_gsm,
    massal_variety.var_name, massal_variety.var_unit, massal_variety.var_size1, massal_variety.var_size2,massal_variety.var_shade ,massal_variety.var_inchcm,
    trnsal_invoice_header.invh_cgst_amt,  trnsal_invoice_header.invh_sgst_amt,  trnsal_invoice_header.invh_igst_amt,  trnsal_invoice_header.invh_insamt,  trnsal_invoice_header.invh_frt_amt ,
    trnsal_invoice_header.invh_crd_days , trnsal_invoice_header.invh_invrefno   , trnsal_invoice_header.invh_grace_days
FROM
    { oj ((((mas_company mas_company INNER JOIN trnsal_invoice_header trnsal_invoice_header ON
        mas_company.company_code = trnsal_invoice_header.invh_comp_code)
     INNER JOIN massal_customer massal_customer ON
        trnsal_invoice_header.invh_party = massal_customer.cust_code)
     INNER JOIN trnsal_invoice_trailer trnsal_invoice_trailer ON
       trnsal_invoice_header.invh_comp_code = trnsal_invoice_trailer.invt_compcode and trnsal_invoice_header.invh_fincode = trnsal_invoice_trailer.invt_fincode and   trnsal_invoice_header.invh_seqno = trnsal_invoice_trailer.invt_seqno)
     INNER JOIN massal_variety massal_variety ON
        trnsal_invoice_trailer.invt_var = massal_variety.var_code)
     INNER JOIN masprd_variety masprd_variety ON
        trnsal_invoice_trailer.invt_item = masprd_variety.var_groupcode}
WHERE
    trnsal_invoice_header.invh_comp_code = compcode AND
    trnsal_invoice_header.invh_fincode = fincode AND
    trnsal_invoice_header.invh_date >= fromdate AND
    trnsal_invoice_header.invh_date <= todate  and find_in_set(invh_party,custcodelist)   
ORDER BY
    massal_customer.cust_code ASC,
    massal_variety.var_name ASC,
    trnsal_invoice_header.invh_seqno ASC;    
end if;    
END ;;
DELIMITER ;
