DELIMITER ;;
CREATE DEFINER=`root`@`%` PROCEDURE `spsal_rep_rate`(compcode int, fincode int, repcode int)
BEGIN
/*
	select * from (
    select   * from massal_rate a , massal_customer b ,
	massal_repr c
	where  cust_repr = repr_code and rate_vartype =  1 and rate_shade = 'NAT' and 
    repr_code = repcode and rate_cust = cust_code and  rate_comp_code = 1 and rate_fincode <= fincode and rate_appr_date >= '2024-08-08' and rate_approved = 'Y' 
	order by repr_code asc , cust_ref asc
    ) a1 ,
(
select cust,max(year_rate) as maxcode from
(select  concat(rate_fincode, right(concat('000',rate_code),4)) as year_rate, rate_fincode , rate_cust cust,rate_appr_date apprdate, rate_code  from massal_rate where  rate_comp_code = 1 and rate_fincode <= fincode and rate_appr_date >= '2024-08-08' and rate_approved = 'Y' 
) b1 group by cust
)c1 where  a1.rate_cust =  c1.cust and a1.rate_fincode = left(maxcode,2)  and a1.rate_code = right(maxcode,4) ;
*/  


	select 
     rate_comp_code,rate_fincode,rate_code,rate_appr_date,
    repr_name, cust_name,area_name,
    rate_price_terms, rate_grace_days,
    rate_bf14, rate_bf16, rate_bf18,rate_bf20, rate_bf22, rate_bf24,
     rate_bf26,  rate_bf28,  rate_bf30,  rate_bf32,  rate_rate, rate_bitreel,rate_code,cust_lock
    from (
    select   * from massal_rate a , massal_customer b ,
	massal_repr c , massal_area d
	where  cust_area = area_code and cust_repr = repr_code and rate_vartype =  1 and rate_shade = 'NAT' and 
    repr_code = repcode and rate_cust = cust_code and  rate_comp_code = 1 and rate_fincode <= fincode and rate_appr_date >= '2024-08-08' and rate_approved = 'Y' 
	order by repr_code asc , cust_ref asc
    ) a1 ,
(
select cust,max(year_rate) as maxcode from
(select  concat(rate_fincode, right(concat('000',rate_code),4)) as year_rate, rate_fincode , rate_cust cust,rate_appr_date apprdate, rate_code  from massal_rate where  rate_comp_code = 1 and rate_fincode <= fincode and rate_appr_date >= '2024-08-08' and rate_approved = 'Y' 
) b1 group by cust
)c1 where  a1.rate_cust =  c1.cust and a1.rate_fincode = left(maxcode,2)  and a1.rate_code = right(maxcode,4) 
  
  
  union all
  
select 
   1 as rate_comp_code,25 rate_fincode,100000 as rate_code, curdate() rate_appr_date,
	repr_name, cust_name, area_name,
    10000 as rate_price_terms,  0 as rate_grace_days,
     0 as rate_bf14,  0 as rate_bf16, 0 as rate_bf18, 0 as rate_bf20, 0 as rate_bf22, 0 as rate_bf24,
      0 as rate_bf26,  0 as rate_bf28,  0 as rate_bf30,  0 as rate_bf32, 0 as  rate_rate,  0 as rate_bitreel,10000 as rate_code,cust_lock
   
from massal_customer join massal_area  on  cust_area = area_code 
join   massal_repr on  cust_repr = repr_code and  cust_repr = repcode  and cust_type = 'C' 
and cust_code not in (
	select rate_cust from (
    select   * from massal_rate a , massal_customer b ,
	massal_repr c 
	where  cust_repr = repr_code and rate_vartype =  1 and rate_shade = 'NAT' and 
    repr_code = repcode and rate_cust = cust_code and  rate_comp_code = 1 and rate_fincode <= fincode and rate_appr_date >= '2024-08-08' and rate_approved = 'Y' 
	order by repr_code asc , cust_ref asc
    ) a1 ,
(
select cust,max(year_rate) as maxcode from
(select  concat(rate_fincode, right(concat('000',rate_code),4)) as year_rate, rate_fincode , rate_cust cust,rate_appr_date apprdate, rate_code  from massal_rate where  rate_comp_code = 1 and rate_fincode <= fincode and rate_appr_date >= '2024-08-08' and rate_approved = 'Y' 
) b1 group by cust
)c1 where  a1.rate_cust =  c1.cust and a1.rate_fincode = left(maxcode,2)  and a1.rate_code = right(maxcode,4)  group by rate_cust
)  ; 

    
END ;;
DELIMITER ;
