DELIMITER ;;
CREATE DEFINER=`root`@`%` PROCEDURE `spsal_rep_REPwiseOrder`(compcode int,fincode int,fromdate date, todate date,repcode int)
BEGIN
select repr_name, DATE_FORMAT(ordh_sodate, '%d-%m-%Y') as  ordh_sodate,cust_code, cust_ref, ordh_sono,var_name ,var_size2 , var_shade,var_inchcm,ordt_qty,ordt_rate,ordt_fin_wt,ordt_inv_wt 
 from trnsal_order_header , trnsal_order_trailer ,massal_customer , massal_variety ,massal_repr where cust_repr = repr_code and ordt_var_code = var_code and ordh_comp_code = ordt_comp_code and ordh_fincode = ordt_fincode  and ordh_sono = ordt_sono  and ordh_party = cust_code and
 ordh_comp_code = compcode and ordh_fincode = fincode and ordh_sodate >= fromdate and ordh_sodate <= todate and cust_repr = repcode order by ordh_sodate desc;
END ;;
DELIMITER ;
