DELIMITER ;;
CREATE DEFINER=`root`@`%` PROCEDURE `spsal_rep_salesreturn`(compcode int,fincode int,fromdate date , todate date )
BEGIN
  select reth_date,cust_ref,reth_invno,reth_invdate,reth_amt,reth_taxable,reth_cgst_per,reth_cgst_amt,
  reth_sgst_per,reth_sgst_amt,
  reth_igst_per,reth_igst_amt,
  var_name,rett_urate,sum(rett_return_wt/1000) weight
  from trnsal_salret_header a, trnsal_salret_trailer b , massal_variety c , masprd_variety d , massal_customer e where 
  a.reth_cust = e.cust_code and
  c.var_grpcode = d.var_groupcode and b.rett_var = c.var_code and  a.reth_no = b.rett_no and a.reth_fincode = b.rett_fincode  
  and a.reth_comp_code = compcode and a.reth_fincode = fincode and a.reth_date between fromdate and  todate 
  group by 
  reth_date,cust_ref,reth_invno,reth_invdate,reth_amt,reth_taxable,reth_cgst_per,reth_cgst_amt,
  reth_sgst_per,reth_sgst_amt,
  reth_igst_per,reth_igst_amt,var_name,rett_urate;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
