DELIMITER ;;
CREATE DEFINER=`root`@`%` PROCEDURE `spsal_rep_salvage`(compcode int,fincode int,fromdate date , todate date)
BEGIN
select t.*,  b.var_name as oldsizename , c.var_name as newsizename  from trnsal_salvage t
left join massal_variety b  on t.oldsize = b.var_code 
left join massal_variety c  on t.newsize = c.var_code 
where oldsize <> newsize and 
comp_code = compcode and fin_code = fincode and ent_date >= fromdate  and ent_date <= todate;
 -- union 
 -- select '1' comp_code, '22' fin_code, 100000 ent_no,todate ent_date, 0 oldreelno, 0 oldweight, 0 oldsono, 0 oldsize,0 newreelno,0 newweight, 0 newsono,0  newsize,''  oldsizename,'' newsizename;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
