DELIMITER ;;
CREATE DEFINER=`root`@`%` PROCEDURE `spsal_rep_shade_stock`(compcode int,shade varchar(2),
bf int,gsm int,optbfgsm varchar(3))
BEGIN
if shade = 'A'
then
    if  optbfgsm = "A" then
		select var_bf,var_gsm,var_name,var_size2,var_shade,var_inchcm,var_code,round(sum(stk_wt)/1000,3) as stock_qty ,count(*) as reels 
		from trnsal_finish_stock , massal_variety  , masprd_variety  where  var_grpcode = var_groupcode and  stk_comp_code =compcode and stk_destag = '' 
		and stk_var_code = var_code  
		group by var_bf,var_gsm,var_name,var_size2,var_shade,var_inchcm,var_code order by var_bf,var_gsm,var_name,var_size2,var_shade,var_inchcm,var_code;
    else   
        if  optbfgsm = "GSM"  then
			select var_bf,var_gsm,var_name,var_size2,var_shade,var_inchcm,var_code,round(sum(stk_wt)/1000,3) as stock_qty ,count(*) as reels 
			from trnsal_finish_stock , massal_variety  , masprd_variety  where  var_grpcode = var_groupcode and  stk_comp_code =compcode and stk_destag = '' 
			and stk_var_code = var_code  and var_gsm = gsm
			group by var_bf,var_gsm,var_name,var_size2,var_shade,var_inchcm,var_code order by var_bf,var_gsm,var_name,var_size2,var_shade,var_inchcm,var_code;
	    else
			select var_bf,var_gsm,var_name,var_size2,var_shade,var_inchcm,var_code,round(sum(stk_wt)/1000,3) as stock_qty ,count(*) as reels 
			from trnsal_finish_stock , massal_variety  , masprd_variety  where  var_grpcode = var_groupcode and  stk_comp_code =compcode and stk_destag = '' 
			and stk_var_code = var_code  and var_bf = bf
			group by var_bf,var_gsm,var_name,var_size2,var_shade,var_inchcm,var_code order by var_bf,var_gsm,var_name,var_size2,var_shade,var_inchcm,var_code;
        end if;		
    end if;
else
    if  optbfgsm = "A" then
		select var_bf,var_gsm,var_name,var_size2,var_shade,var_inchcm,var_code,round(sum(stk_wt)/1000,3) as stock_qty ,count(*) as reels 
		from trnsal_finish_stock , massal_variety  , masprd_variety  where  var_grpcode = var_groupcode and  stk_comp_code =compcode and stk_destag = '' 
		and stk_var_code = var_code  and var_shade = shade
		group by var_bf,var_gsm,var_name,var_size2,var_shade,var_inchcm,var_code order by var_bf,var_gsm,var_name,var_size2,var_shade,var_inchcm,var_code;
    else   
        if  optbfgsm = "GSM" then
			select var_bf,var_gsm,var_name,var_size2,var_shade,var_inchcm,var_code,round(sum(stk_wt)/1000,3) as stock_qty ,count(*) as reels 
			from trnsal_finish_stock , massal_variety  , masprd_variety  where  var_grpcode = var_groupcode and  stk_comp_code =compcode and stk_destag = '' 
			and stk_var_code = var_code and var_shade = shade and var_gsm = gsm
			group by var_bf,var_gsm,var_name,var_size2,var_shade,var_inchcm,var_code order by var_bf,var_gsm,var_name,var_size2,var_shade,var_inchcm,var_code;
	    else
			select var_bf,var_gsm,var_name,var_size2,var_shade,var_inchcm,var_code,round(sum(stk_wt)/1000,3) as stock_qty ,count(*) as reels 
			from trnsal_finish_stock , massal_variety  , masprd_variety  where  var_grpcode = var_groupcode and  stk_comp_code =compcode and stk_destag = '' 
			and stk_var_code = var_code and var_shade = shade  and var_bf = bf
			group by var_bf,var_gsm,var_name,var_size2,var_shade,var_inchcm,var_code order by var_bf,var_gsm,var_name,var_size2,var_shade,var_inchcm,var_code;
        end if;		
    end if;	
end if;

END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `spsal_rep_sizechange` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
