CREATE DEFINER=`root`@`%` PROCEDURE `spsal_rep_sizechange`(compcode int,fincode int,fromdate date , todate date)
BEGIN
select * from (
select t.*,  b.var_name oldsizename , c.var_name newsizename  from trnsal_reelweight_change t
left join massal_variety b  on t.oldsize = b.var_code 
left join massal_variety c  on t.newsize = c.var_code 
where oldsize <> newsize and 
comp_code = compcode and fin_code = fincode and ent_date >= fromdate  and ent_date <= todate ) a1;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `spsal_rep_size_month_wise_sales` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`%` PROCEDURE `spsal_rep_size_month_wise_sales`(compcode int,reelopt varchar(10),fromdate date , todate date,saleoption varchar(10))
BEGIN
declare fixcondition varchar(100);
declare fixcondition_sales varchar(100);

if reelopt = "A" then
  set fixcondition = "'F','B'";
else
    set fixcondition = reelopt; 
end if;    

if saleoption = "ALL" then
  set fixcondition_sales = 'A,B';
else
    set fixcondition_sales = saleoption; 
end if;   


select  sales,  itemcode ,  vargrp_type_short_code , var_bf , var_gsm , var_inchcm,var_size2, var_shade,
reeltype,   
sum(desp_apr) apr_desp
,sum(desp_may) may_desp,sum(desp_jun) jun_desp,sum(desp_jul) jul_desp,sum(desp_aug) aug_desp,sum(desp_sep) sep_desp
,sum(desp_oct) oct_desp,sum(desp_nov) nov_desp,sum(desp_dec) dec_desp,sum(desp_jan) jan_desp,sum(desp_feb) feb_desp,sum(desp_mar) mar_desp ,sum(totdesp) as totdesp,sum(stk) stk
from
(
select  'A' as sales, invt_var itemcode ,  vargrp_type_short_code , var_bf , var_gsm , var_inchcm,var_size2, var_shade,
case when (var_inchcm = 'I' and  var_size2 > 16)  then  'F'  else case when (var_inchcm = 'C' and var_size2 > 41)  then 'F' else 'B' end end as reeltype,   
case when month(invh_date) = 4 then sum(invt_wt)/1000 else 0 end as desp_apr,
case when month(invh_date) = 5 then sum(invt_wt)/1000 else 0 end as desp_may,
case when month(invh_date) = 6 then sum(invt_wt)/1000 else 0 end as desp_jun,
case when month(invh_date) = 7 then sum(invt_wt)/1000 else 0 end as desp_jul,
case when month(invh_date) = 8 then sum(invt_wt)/1000 else 0 end as desp_aug,
case when month(invh_date) = 9 then sum(invt_wt)/1000 else 0 end as desp_sep,
case when month(invh_date) = 10 then sum(invt_wt)/1000 else 0 end as desp_oct,
case when month(invh_date) = 11 then sum(invt_wt)/1000 else 0 end as desp_nov,
case when month(invh_date) = 12 then sum(invt_wt)/1000 else 0 end as desp_dec,
case when month(invh_date) = 1 then sum(invt_wt)/1000 else 0 end as desp_jan,
case when month(invh_date) = 2 then sum(invt_wt)/1000 else 0 end as desp_feb,
case when month(invh_date) = 3 then sum(invt_wt)/1000 else 0 end as desp_mar,
sum(invt_wt)/1000 as totdesp ,0 stk
 from 
 trnsal_invoice_header , trnsal_invoice_trailer,
 massal_variety , masprd_variety , masprd_type  where
invh_fincode = invt_fincode and  invh_comp_code = invt_compcode and  invh_seqno = invt_seqno and 
 vargrp_type_code =  var_typecode and 
var_grpcode = var_groupcode and
invt_var = var_code and invh_comp_code = compcode and invh_date  between   fromdate and todate
group by invt_var,vargrp_type_short_code , var_bf , var_gsm , var_inchcm,var_size2,invh_date,var_shade

union all

select  'A' as sales, stk_var_code itemcode, vargrp_type_short_code , var_bf , var_gsm , var_inchcm,var_size2, var_shade, 
case when (var_inchcm = 'I' and  var_size2 > 16)  then  'F'  else case when (var_inchcm = 'C' and var_size2 > 41)  then 'F' else 'B' end end as reeltype,   
0 desp_apr, 0 desp_may,0 desp_jun, 0 desp_jul, 0 desp_aug,  0 desp_sep,  0 desp_oct, 0 desp_nov, 0 desp_dec,0 desp_jan,0 desp_feb,0 desp_mar, 0 totdesp,sum(stk_wt)/1000 stk
from trnsal_finish_stock , 
 massal_variety , masprd_variety , masprd_type  where
 vargrp_type_code =  var_typecode and 
var_grpcode = var_groupcode and
stk_var_code = var_code and stk_comp_code = compcode and stk_destag =  ''  and length(stk_sono) = 6
group by stk_var_code,vargrp_type_short_code , var_bf , var_gsm , var_inchcm,var_size2,var_shade

union all

select  'B' as sales, stk_var_code itemcode, vargrp_type_short_code , var_bf , var_gsm , var_inchcm,var_size2, var_shade, 
case when (var_inchcm = 'I' and  var_size2 > 16)  then  'F'  else case when (var_inchcm = 'C' and var_size2 > 41)  then 'F' else 'B' end end as reeltype,   
0 desp_apr, 0 desp_may,0 desp_jun, 0 desp_jul, 0 desp_aug,  0 desp_sep,  0 desp_oct, 0 desp_nov, 0 desp_dec,0 desp_jan,0 desp_feb,0 desp_mar, 0 totdesp,sum(stk_wt)/1000 stk
from trnsal_finish_stock , 
 massal_variety , masprd_variety , masprd_type  where
 vargrp_type_code =  var_typecode and 
var_grpcode = var_groupcode and
stk_var_code = var_code and stk_comp_code = compcode and stk_destag =  ''  and length(stk_sono) <> 6
group by stk_var_code,vargrp_type_short_code , var_bf , var_gsm , var_inchcm,var_size2,var_shade

union all

select 'B' as sales,  dn_size itemcode ,vargrp_type_short_code , var_bf , var_gsm , var_inchcm,var_size2, var_shade,
 case when (var_inchcm = 'I' and  var_size2 > 16)  then  'F'  else case when (var_inchcm = 'C' and var_size2 > 41)  then 'F' else 'B' end end as reeltype,   
case when month(dn_date) = 4 then sum(dn_wt)/1000 else 0 end as desp_apr,
case when month(dn_date) = 5 then sum(dn_wt)/1000 else 0 end as desp_may,
case when month(dn_date) = 6 then sum(dn_wt)/1000 else 0 end as desp_jun,
case when month(dn_date) = 7 then sum(dn_wt)/1000 else 0 end as desp_jul,
case when month(dn_date) = 8 then sum(dn_wt)/1000 else 0 end as desp_aug,
case when month(dn_date) = 9 then sum(dn_wt)/1000 else 0 end as desp_sep,
case when month(dn_date) = 10 then sum(dn_wt)/1000 else 0 end as desp_oct,
case when month(dn_date) = 11 then sum(dn_wt)/1000 else 0 end as desp_nov,
case when month(dn_date) = 12 then sum(dn_wt)/1000 else 0 end as desp_dec,
case when month(dn_date) = 1 then sum(dn_wt)/1000 else 0 end as desp_jan,
case when month(dn_date) = 2 then sum(dn_wt)/1000 else 0 end as desp_feb,
case when month(dn_date) = 3 then sum(dn_wt)/1000 else 0 end as desp_mar,
sum(dn_wt)/1000 as totdesp , 0 as stk
 from 
 trn_delivery_note ,
 massal_variety , masprd_variety , masprd_type  where
 vargrp_type_code =  var_typecode and 
var_grpcode = var_groupcode and
dn_size = var_code and dn_comp_code = compcode and dn_date  between    fromdate and todate 
group by dn_size,vargrp_type_short_code , var_bf , var_gsm , var_inchcm,var_size2,dn_date,var_shade
) s1 where  FIND_IN_SET(reeltype,fixcondition) and FIND_IN_SET(sales,fixcondition_sales) 
group by sales,  itemcode ,  vargrp_type_short_code , var_bf , var_gsm , var_inchcm,var_size2, var_shade,reeltype  ;

