CREATE DEFINER=`root`@`%` PROCEDURE `spsal_rep_stock`(reelopt varchar(1))
BEGIN
if reelopt = "A" 
then
SELECT
    vew_sal_rt12stat.opstk,   vew_sal_rt12stat.stk_nos, vew_sal_rt12stat.stk_qty, vew_sal_rt12stat.prod_qty, vew_sal_rt12stat.sal_qty, vew_sal_rt12stat.salr_qty,
    mas_company.company_name,massal_variety.var_unit, 
    massal_variety.var_name, massal_variety.var_size1, massal_variety.var_size2,
    masprd_variety.var_desc,masprd_variety.var_bf,masprd_variety.var_gsm,masprd_type.vargrp_type_name, 
    vew_sal_rt12stat.opnos,vew_sal_rt12stat.prod_nos, vew_sal_rt12stat.sal_nos, vew_sal_rt12stat.salret_nos, vew_sal_rt12stat.wtchg_nos, vew_sal_rt12stat.pulp_nos,
    vew_sal_rt12stat.pulp_stk, vew_sal_rt12stat.salvage_stk, vew_sal_rt12stat.salvage_nos, vew_sal_rt12stat.wt_change, masprd_type.vargrp_type_short_code,massal_variety.var_shade,
    vew_sal_rt12stat.conv_qty, vew_sal_rt12stat.conv_nos, vew_sal_rt12stat.bund_qty, vew_sal_rt12stat.bund_nos,
    vew_sal_rt12stat.reel_qty, vew_sal_rt12stat.reel_nos, vew_sal_rt12stat.salvage_recpt_qty , vew_sal_rt12stat.salvage_recpt_nos ,vew_sal_rt12stat.sample_stk,vew_sal_rt12stat.sample_nos
    FROM 
    { oj ((vew_sal_rt12stat vew_sal_rt12stat INNER JOIN massal_variety massal_variety ON
        vew_sal_rt12stat.var_code = massal_variety.var_code)
     INNER JOIN mas_company mas_company ON
        vew_sal_rt12stat.comp_code = mas_company.company_code)
     INNER JOIN masprd_variety masprd_variety ON
        massal_variety.var_grpcode = masprd_variety.var_groupcode
     INNER JOIN masprd_type masprd_type ON
        masprd_type.vargrp_type_code = masprd_variety.var_typecode
        
        }
ORDER BY
    massal_variety.var_name ASC;
else if reelopt = "F" 
then
SELECT
    vew_sal_rt12stat.opstk,   vew_sal_rt12stat.stk_nos, vew_sal_rt12stat.stk_qty, vew_sal_rt12stat.prod_qty, vew_sal_rt12stat.sal_qty, vew_sal_rt12stat.salr_qty,
    mas_company.company_name,massal_variety.var_unit, 
    massal_variety.var_name, massal_variety.var_size1, massal_variety.var_size2,
    masprd_variety.var_desc,masprd_variety.var_bf,masprd_variety.var_gsm,masprd_type.vargrp_type_name, 
    vew_sal_rt12stat.opnos,vew_sal_rt12stat.prod_nos, vew_sal_rt12stat.sal_nos, vew_sal_rt12stat.salret_nos, vew_sal_rt12stat.wtchg_nos, vew_sal_rt12stat.pulp_nos,
    vew_sal_rt12stat.pulp_stk, vew_sal_rt12stat.salvage_stk, vew_sal_rt12stat.salvage_nos, vew_sal_rt12stat.wt_change, masprd_type.vargrp_type_short_code,massal_variety.var_shade,
    vew_sal_rt12stat.conv_qty, vew_sal_rt12stat.conv_nos, vew_sal_rt12stat.bund_qty, vew_sal_rt12stat.bund_nos,
    vew_sal_rt12stat.reel_qty, vew_sal_rt12stat.reel_nos, vew_sal_rt12stat.salvage_recpt_qty , vew_sal_rt12stat.salvage_recpt_nos ,vew_sal_rt12stat.sample_stk,vew_sal_rt12stat.sample_nos
    FROM 
    { oj ((vew_sal_rt12stat vew_sal_rt12stat INNER JOIN massal_variety massal_variety ON
        vew_sal_rt12stat.var_code = massal_variety.var_code)
     INNER JOIN mas_company mas_company ON
        vew_sal_rt12stat.comp_code = mas_company.company_code)
     INNER JOIN masprd_variety masprd_variety ON
        massal_variety.var_grpcode = masprd_variety.var_groupcode
     INNER JOIN masprd_type masprd_type ON
        masprd_type.vargrp_type_code = masprd_variety.var_typecode       
     }         where case when  massal_variety.var_inchcm = 'I' then massal_variety.var_size2 >16 else massal_variety.var_size2 >41 end 
ORDER BY
    massal_variety.var_name ASC;
else
SELECT
    vew_sal_rt12stat.opstk,   vew_sal_rt12stat.stk_nos, vew_sal_rt12stat.stk_qty, vew_sal_rt12stat.prod_qty, vew_sal_rt12stat.sal_qty, vew_sal_rt12stat.salr_qty,
    mas_company.company_name,massal_variety.var_unit, 
    massal_variety.var_name, massal_variety.var_size1, massal_variety.var_size2,
    masprd_variety.var_desc,masprd_variety.var_bf,masprd_variety.var_gsm,masprd_type.vargrp_type_name, 
    vew_sal_rt12stat.opnos,vew_sal_rt12stat.prod_nos, vew_sal_rt12stat.sal_nos, vew_sal_rt12stat.salret_nos, vew_sal_rt12stat.wtchg_nos, vew_sal_rt12stat.pulp_nos,
    vew_sal_rt12stat.pulp_stk, vew_sal_rt12stat.salvage_stk, vew_sal_rt12stat.salvage_nos, vew_sal_rt12stat.wt_change, masprd_type.vargrp_type_short_code,massal_variety.var_shade,
    vew_sal_rt12stat.conv_qty, vew_sal_rt12stat.conv_nos, vew_sal_rt12stat.bund_qty, vew_sal_rt12stat.bund_nos,
    vew_sal_rt12stat.reel_qty, vew_sal_rt12stat.reel_nos, vew_sal_rt12stat.salvage_recpt_qty , vew_sal_rt12stat.salvage_recpt_nos ,vew_sal_rt12stat.sample_stk,vew_sal_rt12stat.sample_nos
    FROM 
    { oj ((vew_sal_rt12stat vew_sal_rt12stat INNER JOIN massal_variety massal_variety ON
        vew_sal_rt12stat.var_code = massal_variety.var_code)
     INNER JOIN mas_company mas_company ON
        vew_sal_rt12stat.comp_code = mas_company.company_code)
     INNER JOIN masprd_variety masprd_variety ON
        massal_variety.var_grpcode = masprd_variety.var_groupcode
     INNER JOIN masprd_type masprd_type ON
        masprd_type.vargrp_type_code = masprd_variety.var_typecode
        
        } where case when  massal_variety.var_inchcm = 'I' then massal_variety.var_size2 <=16 else massal_variety.var_size2 <=41 end
ORDER BY
    massal_variety.var_name ASC;
end if;
end if;    
    
END ;;
DELIMITER ;
