CREATE DEFINER=`root`@`%` PROCEDURE `spsal_rep_stock_for_the_prod_period`(compcode int,startdate date,enddate date)
BEGIN
select repr_name,cust_ref,ordh_sodate,ordh_sono,var_name,stk_sr_no, stk_wt from trnsal_finish_stock join
trnsal_order_header on stk_sono = ordh_sono  join
massal_customer on ordh_party = cust_code join
massal_repr on cust_repr = repr_code join 
massal_variety on stk_var_code = var_code 
where stk_comp_code = compcode and stk_ent_date between startdate and enddate and stk_destag = ''
order by repr_name,cust_ref,ordh_sodate,ordh_sono,var_name,stk_sr_no;
END ;;
DELIMITER ;
