CREATE DEFINER=`root`@`%` PROCEDURE `spsal_rep_view_partywise_sales`(compcode int,fincode int,fromdate date , todate date ,custcode int )
select concat(year(invh_date),  right(concat('0',month(invh_date)),2) ) as ryear,cust_ref,UPPER(monthname(invh_date)) as rmonth,  invh_date , invh_party ,invh_invrefno , invh_netamt , invh_noofreels, invh_totwt /1000 as invh_totwt from 
trnsal_invoice_header a , trnsal_invoice_trailer b , massal_customer c where c.cust_code = a.invh_party and  
a.invh_fincode= b.invt_fincode  and a.invh_comp_code = b.invt_compcode 
and a.invh_seqno = b.invt_seqno and  a.invh_fincode=  fincode  and a.invh_comp_code= compcode  and invh_date >= fromdate and invh_date <=  todate  and invh_party = custcode group by cust_ref,UPPER(monthname(invh_date)), invh_date , invh_party ,invh_invrefno , invh_netamt , invh_noofreels, invh_totwt ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
