DELIMITER ;;
CREATE DEFINER=`root`@`%` PROCEDURE `spsal_rep_weightchange`(compcode int,fincode int,fromdate date , todate date)
BEGIN
select * from trnsal_reelweight_change , massal_variety ,trnsal_finish_stock  where
comp_code = stk_comp_code and fin_code >= stk_finyear and   srno  = stk_sr_no and  oldsize = var_code and oldweight <> newweight and 
comp_code = compcode and fin_code = fincode and ent_date >= fromdate  and ent_date <= todate;  
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
