CREATE DEFINER=`root`@`%` PROCEDURE `spsal_Target_Update`(
custcode int,
grade varchar(10),
target int,
crdays int,
payper dec(5,2),
visits int ,
repmonth int,
repyear int)
begin 
declare ccode  int; 

select count(*) into ccode from massal_target where customer_code =custcode and rmonth = repmonth and ryear = repyear;
if ccode  <= 0
then
	insert into massal_target(
    customer_code, cust_grade, cust_desp_target, cust_cr_days, cust_payperf, cust_noof_visits, rmonth, ryear )
    values (custcode, grade, target, crdays, payper, visits,repmonth,repyear);
else
    update massal_target set cust_grade = grade,cust_desp_target = target ,cust_cr_days = crdays , cust_noof_visits = visits ,cust_payperf = payper  where customer_code = custcode 
    and rmonth = repmonth and ryear = repyear;
    end if;

END ;;
DELIMITER ;
