CREATE DEFINER=`root`@`%` PROCEDURE `spst_rep_consumption`(compcode int,fincode int,startdate datetime, enddate datetime)
BEGIN
SELECT
    trnpur_item_issues.iss_comp_code, trnpur_item_issues.iss_type,trnpur_item_issues.iss_machine,  trnpur_item_issues.iss_no, trnpur_item_issues.iss_date, trnpur_item_issues.iss_fin_code, trnpur_item_issues.iss_qty, trnpur_item_issues.iss_rate,
    mas_equipment.equip_name,
    maspur_item_header.item_name,
    mas_section.section_name,
    mas_dept.dept_name,
    mas_uom.uom_short_name,
    mas_company.company_name
FROM
    { oj ((((trnpur_item_issues trnpur_item_issues INNER JOIN maspur_item_header maspur_item_header ON
        trnpur_item_issues.iss_item_code = maspur_item_header.item_code)
     INNER JOIN mas_section mas_section ON
        trnpur_item_issues.iss_section = mas_section.section_code)
     INNER JOIN mas_dept mas_dept ON
        trnpur_item_issues.iss_dept_code = mas_dept.dept_code)
     INNER JOIN mas_equipment mas_equipment ON
        trnpur_item_issues.iss_equip = mas_equipment.equip_code)
     INNER JOIN mas_uom mas_uom ON
        maspur_item_header.item_uom = mas_uom.uom_code
     INNER JOIN mas_company mas_company ON
        trnpur_item_issues.iss_comp_code = mas_company.company_code
        }
        
WHERE
    trnpur_item_issues.iss_comp_code =compcode AND
    trnpur_item_issues.iss_fin_code = fincode  AND
    trnpur_item_issues.iss_date >= startdate  AND
    trnpur_item_issues.iss_date <= enddate; 
  END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
