CREATE DEFINER=`root`@`%` PROCEDURE `spst_rep_datewisereceipt20082022`(compcode int,fromdate datetime, todate datetime)
BEGIN
SELECT
    trnpur_min_trailer.mint_minno, trnpur_min_trailer.mint_mindate, trnpur_min_trailer.mint_pono,  trnpur_min_trailer.mint_rcvd_qty, trnpur_min_trailer.mint_value, trnpur_min_trailer.mint_ind_no, trnpur_min_trailer.mint_cr_status,
    maspur_item_header.item_name,
    mas_company.company_name,
    trnpur_min_header.minh_comp_code, trnpur_min_header.minh_mindate, trnpur_min_header.minh_bill_no, trnpur_min_header.minh_bill_date,
    maspur_supplier_master.sup_refname, maspur_supplier_master.sup_type,
    mas_uom.uom_short_name,
    acc_ledger_master_imp.led_name,
    acc_ledger_master_tngst.led_name,
    acc_ledger_master.led_name
FROM
    { oj ((((((((trnpur_min_trailer trnpur_min_trailer INNER JOIN mas_company mas_company ON
        trnpur_min_trailer.mint_comp_code = mas_company.company_code)
     INNER JOIN trnpur_min_header trnpur_min_header ON
        trnpur_min_trailer.mint_comp_code = trnpur_min_header.minh_comp_code AND
    trnpur_min_trailer.mint_minno = trnpur_min_header.minh_minno AND
    trnpur_min_trailer.mint_mindate = trnpur_min_header.minh_mindate AND
    trnpur_min_trailer.mint_fin_code = trnpur_min_header.minh_fin_code AND
    trnpur_min_trailer.mint_sup_code = trnpur_min_header.minh_sup_code)
     INNER JOIN maspur_supplier_master maspur_supplier_master ON
        trnpur_min_trailer.mint_sup_code = maspur_supplier_master.sup_code)
     INNER JOIN maspur_item_header maspur_item_header ON
        trnpur_min_trailer.mint_item_code = maspur_item_header.item_code)
     INNER JOIN mas_uom mas_uom ON
        maspur_item_header.item_uom = mas_uom.uom_code)
     INNER JOIN maspur_group maspur_group ON
        maspur_item_header.item_group_code = maspur_group.grp_code)
     INNER JOIN acc_ledger_master acc_ledger_master_tngst ON
        maspur_group.grp_tngst_code = acc_ledger_master_tngst.led_code)
     INNER JOIN acc_ledger_master acc_ledger_master ON
        maspur_group.grp_cst_code = acc_ledger_master.led_code)
     INNER JOIN acc_ledger_master acc_ledger_master_imp ON
        maspur_group.grp_imp_code = acc_ledger_master_imp.led_code}
WHERE
    trnpur_min_header.minh_mindate >= fromdate AND
    trnpur_min_header.minh_mindate <= todate AND
    trnpur_min_header.minh_comp_code = compcode;
END ;;
DELIMITER ;
