CREATE DEFINER=`root`@`%` PROCEDURE `spst_rep_DCReceipt`(compcode int,fincode int ,vouno int)
BEGIN
select * from  trnpur_deliverychallan_header, trnpur_deliverychallan_receipt , trnpur_deliverychallan_trailer ,maspur_item_header  , mas_uom , massal_customer   where 
 dcr_party = cust_code and
 dct_item_code = item_code and item_uom = uom_code and 
 dch_comp_code = dct_comp_code and dch_fincode = dct_fincode and dch_no = dct_no and 
 dcr_comp_code = dct_comp_code and dcr_dcfincode = dct_fincode and dcr_dcno = dct_no and dch_type = 'R' and 
 dcr_itemcode = dct_item_code and  dcr_comp_code = compcode and dcr_fincode = fincode and dcr_no = vouno;
END ;;
DELIMITER ;
