CREATE DEFINER=`root`@`%` PROCEDURE `spst_rep_grn_gstdetails`(mintcompcode int, mintfincode int, minno  VARCHAR(20))
BEGIN
/*
select gstledger,sum(gstamt) gstamt from (
select tax_cgstledger gstledger ,mint_cgst_amt as gstamt  from trnpur_min_trailer , mas_purchasetax where mint_comp_code = mintcompcode and  mint_fin_code = mintfincode and mint_minno = minno and mint_cgst_per + mint_sgst_per + mint_igst_per = tax_gst
union all 
select tax_sgstledger gstledger ,mint_sgst_amt as gstamt  from trnpur_min_trailer , mas_purchasetax where mint_comp_code = mintcompcode and  mint_fin_code = mintfincode and  mint_minno = minno and mint_cgst_per + mint_sgst_per + mint_igst_per = tax_gst
union all 
select tax_igstledger gstledger ,mint_igst_amt gstamt  from trnpur_min_trailer , mas_purchasetax where mint_comp_code = mintcompcode and  mint_fin_code = mintfincode and mint_minno = minno and mint_cgst_per + mint_sgst_per + mint_igst_per = tax_gst
 )aa where gstamt > 0 group by gstledger;
 */
 select cust_name,acctran_dbamt,acctran_cramt  from acc_ref join acc_tran on  accref_seqno = acctran_accref_seqno
join massal_customer on  acctran_led_code = cust_code
where accref_comp_code = mintcompcode and accref_finid = mintfincode and accref_vouno = minno order by acctran_serialno;
END ;;
DELIMITER ;
