DELIMITER ;;
CREATE DEFINER=`root`@`%` PROCEDURE `spst_rep_grn_print`(mintcompcode int, mintfincode int, minno varchar(12) )
BEGIN
select * from (
SELECT trnpur_min_header.* ,  trnpur_min_trailer.*,mas_company.*,trnpur_purchase_header.*,massal_customer.*,
mas_state.* , mas_uom.* ,ledgermaster.cust_name led_name , UserEntry.usr_name EnteredBy , UserModify.usr_name ModifiedBy , maspur_item_header.* FROM
    { oj ((((((((((trnpur_min_header trnpur_min_header 
    INNER JOIN mas_company mas_company ON
        trnpur_min_header.minh_comp_code = mas_company.company_code)
     INNER JOIN trnpur_min_trailer trnpur_min_trailer ON
        trnpur_min_header.minh_comp_code = trnpur_min_trailer.mint_comp_code AND
    trnpur_min_header.minh_minno = trnpur_min_trailer.mint_minno AND
    trnpur_min_header.minh_mindate = trnpur_min_trailer.mint_mindate AND
    trnpur_min_header.minh_fin_code = trnpur_min_trailer.mint_fin_code AND
    trnpur_min_header.minh_sup_code = trnpur_min_trailer.mint_sup_code)
     INNER JOIN maspur_item_header maspur_item_header ON
        trnpur_min_trailer.mint_item_code = maspur_item_header.item_code)
     LEFT JOIN trnpur_purchase_header trnpur_purchase_header ON
        trnpur_min_trailer.mint_comp_code = trnpur_purchase_header.phd_comp_code AND
    trnpur_min_trailer.mint_pono = trnpur_purchase_header.phd_pono AND
    trnpur_min_trailer.mint_podate = trnpur_purchase_header.phd_podate)
     INNER JOIN massal_customer massal_customer ON
        trnpur_min_trailer.mint_sup_code = massal_customer.cust_code)
     INNER JOIN mas_state mas_state ON
        massal_customer.cust_state = mas_state.state_code)        
     INNER JOIN massal_customer ledgermaster ON
        trnpur_min_trailer.mint_purgroup  = ledgermaster.cust_code)
     INNER JOIN userMaster UserEntry ON
        trnpur_min_header.minh_entered_by  = UserEntry.usr_code)
     INNER JOIN userMaster UserModify ON
        trnpur_min_header.minh_modified_by  = UserModify.usr_code)        
     INNER JOIN mas_uom mas_uom ON
        maspur_item_header.item_uom  = mas_uom.uom_code)
        
        
}
WHERE
    trnpur_min_trailer.mint_comp_code = mintcompcode AND 
    trnpur_min_trailer.mint_fin_code = mintfincode AND
    trnpur_min_trailer.mint_minno = minno  and minh_grn_status = 'C'
ORDER BY
    trnpur_min_trailer.mint_minno ASC,
    trnpur_min_trailer.mint_slno ASC
)a1;
    
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
