CREATE DEFINER=`root`@`%` PROCEDURE `spst_rep_grn_return_print`(compcode int, fincode int, rrno int )
BEGIN
select * from (
select a1.* ,pur.cust_name purled_name, pur.cust_code purled_code, 
cgst.cust_name cgstled_name, cgst.cust_code cgstled_code,
sgst.cust_name sgstled_name, sgst.cust_code sgstled_code,
igst.cust_name igstled_name, igst.cust_code igstled_code,
othled.cust_name addnlled_name, othled.cust_code addnlled_code
 from 
(select gh.*,gt.*,sup.*,ih.*,uom.* from  trnpur_grn_ret_header gh,trnpur_grn_ret_trailer gt, massal_customer sup ,maspur_item_header ih,
 maspur_item_trailer it, mas_uom uom where 
debh_comp_code = debt_comp_code and debh_fin_code = debt_fin_code and debh_no=  debt_no and
debt_item_code = it.item_code and  debt_comp_code = it.item_comp_code and debt_fin_code = it.item_fin_code  and
 ih.item_code  = it.item_code and  ih.item_uom = uom.uom_code and
debh_supcode = cust_code and debh_comp_code = compcode and debh_fin_code = fincode and debh_no= rrno) a1

join massal_customer pur on a1.debt_pur_ledger = pur.cust_code
join massal_customer cgst on a1.debt_cgst_ledger = cgst.cust_code
join massal_customer sgst on a1.debt_sgst_ledger = sgst.cust_code
join massal_customer igst on a1.debt_igst_ledger = igst.cust_code
join massal_customer othled on a1.debh_addnl_ledcode = othled.cust_code
)b1;
END ;;
DELIMITER ;
