DELIMITER ;;
CREATE DEFINER=`root`@`%` PROCEDURE `spst_rep_indent_grn_print`(mintcompcode int, mintfincode int, minno varchar(12) )
BEGIN
/*
select * from (
select h.*,t.*,i.*,c.*,s.*,u.*, item.* ,led.cust_name led_name from trnpur_min_header h,  trnpur_min_trailer t ,
trnpur_indent i,massal_customer c,
mas_state s , mas_uom u ,maspur_item_header  item , massal_customer led
where
    h.minh_comp_code = t.mint_comp_code and 
    h.minh_fin_code = t.mint_fin_code and
    h.minh_minno = t.mint_minno and 
    h.minh_sup_code = c.cust_code and
    h.minh_type = 'I' and 
	h.minh_comp_code = i.ind_comp_code and 
    t.mint_ind_fin_code =  i.ind_fin_code and
    t.mint_ind_no = i.ind_no and
    t.mint_item_code = i.ind_item_code and
    c.cust_state = s.state_code and 
	item.item_uom = u.uom_code and
    t.mint_item_code  = item.item_code and
	t.mint_purgroup = led.cust_code and 
    minh_comp_code = mintcompcode and 
    minh_fin_code = mintfincode  and
    minh_minno = minno) a1 ; 
*/    
select * from (
select h.*,t.*,ind.*,c.*,s.*,u.*, item.* ,led.cust_name led_name  from trnpur_min_header h
join trnpur_min_trailer t on    h.minh_comp_code = t.mint_comp_code and 
    h.minh_fin_code = t.mint_fin_code and    h.minh_minno = t.mint_minno 
join massal_customer c on h.minh_sup_code = c.cust_code      
join massal_customer led on t.mint_purgroup = led.cust_code 
join mas_state s on  c.cust_state = s.state_code
join maspur_item_header item on   t.mint_item_code  = item.item_code 
join mas_uom u on item.item_uom = u.uom_code 
left join  trnpur_indent ind on     t.mint_ind_fin_code =  ind.ind_fin_code and     t.mint_ind_no = ind.ind_no and    t.mint_item_code = ind .ind_item_code 
where     minh_comp_code = mintcompcode and 
    minh_fin_code = mintfincode  and
    minh_minno = minno    and minh_grn_status = 'C'
    ) a1 ;     
    
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
