CREATE DEFINER=`root`@`%` PROCEDURE `spst_rep_minimum_stock`(compcode int, fincode int, dept int,grpcode int)
BEGIN
 select item_code, item_name, uom_short_name, sum(minstk_qty) minstk_qty , sum(item_stock) item_stock from (
 
 select ih.item_group_code, ih.item_code , ih.item_name,uom_short_name, 0 minstk_qty , item_stock  from  maspur_item_header ih 
 join maspur_item_trailer it  on ih.item_code = it.item_code and it.item_comp_code = compcode and  it.item_fin_code = fincode
 join mas_uom uom on ih.item_uom = uom.uom_code   where item_group_code = grpcode 
 
 union all
 
 select ih.item_group_code,ih.item_code , ih.item_name,uom_short_name, case when minstk_qty is null then 0 else minstk_qty end as minstk_qty , 0 item_stock from 
 maspur_item_header ih  join maspur_item_minimum_stock it on ih.item_code = it.minstk_itemcode  and minstk_dept =  dept and minstk_grpcode = grpcode
 join mas_uom uom on ih.item_uom = uom.uom_code  
) a1 where minstk_qty > 0  and item_group_code = grpcode group by  item_code, item_name, uom_short_name;
/*
 select item_code, item_name, uom_short_name, sum(minstk_qty) minstk_qty , sum(item_stock) item_stock   from (
 select ih.item_code , ih.item_name,uom_short_name, 0 minstk_qty , item_stock  from  maspur_item_header ih  join mas_uom uom on ih.item_uom = uom.uom_code   where item_group_code = grpcode  
 union all
 select ih.item_code , ih.item_name,uom_short_name, case when minstk_qty is null then 0 else minstk_qty end as minstk_qty ,0  item_stock   from 
 maspur_item_header ih   join maspur_item_trailer it  on ih.item_code = it.item_code and it.item_comp_code = compcode and  it.item_fin_code = fincode join maspur_item_minimum_stock it on ih.item_code = it.minstk_itemcode  and minstk_dept = dept 
 join mas_uom uom on ih.item_uom = uom.uom_code 
and minstk_grpcode = grpcode
) a1 where minstk_qty > 0 group by  item_code, item_name, uom_short_name;
*/
END ;;
DELIMITER ;
