CREATE DEFINER=`root`@`%` PROCEDURE `spst_rep_othersales`(compcode int,finid int,docno int)
BEGIN
SELECT
    trnpur_other_sales.os_compcode, trnpur_other_sales.os_fincode, trnpur_other_sales.os_docno, trnpur_other_sales.os_date, trnpur_other_sales.os_rate, trnpur_other_sales.os_qty, trnpur_other_sales.os_value, trnpur_other_sales.os_others, trnpur_other_sales.os_taxable, trnpur_other_sales.os_cgstper, trnpur_other_sales.os_cgst, trnpur_other_sales.os_sgstper, trnpur_other_sales.os_sgst, trnpur_other_sales.os_igstper, trnpur_other_sales.os_igst, trnpur_other_sales.os_netamt, trnpur_other_sales.os_vehno, trnpur_other_sales.os_partyref,
    mas_othersales_item_master.salitem_name, mas_othersales_item_master.salitem_hsn,
    mas_company.company_code, mas_company.company_name,
    mas_transport.carr_name, mas_transport.carr_gst,
    maspur_supplier_master.sup_name, maspur_supplier_master.sup_addr1, maspur_supplier_master.sup_addr2, maspur_supplier_master.sup_addr3, maspur_supplier_master.sup_city, maspur_supplier_master.sup_zip, maspur_supplier_master.sup_gstin,
    mas_state.state_name, mas_state.state_codeno,
    mas_uom.uom_name
FROM
    { oj (((((trnpur_other_sales trnpur_other_sales INNER JOIN mas_company mas_company ON
        trnpur_other_sales.os_compcode = mas_company.company_code)
     INNER JOIN mas_transport mas_transport ON
        trnpur_other_sales.os_transport = mas_transport.carr_code)
     INNER JOIN maspur_supplier_master maspur_supplier_master ON
        trnpur_other_sales.os_custcode = maspur_supplier_master.sup_code)
     INNER JOIN mas_othersales_item_master mas_othersales_item_master ON
        trnpur_other_sales.os_item = mas_othersales_item_master.salitem_code)
     INNER JOIN mas_uom mas_uom ON
        mas_othersales_item_master.salitem_uom = mas_uom.uom_code)
     INNER JOIN mas_state mas_state ON
        maspur_supplier_master.sup_state = mas_state.state_code}
WHERE
    trnpur_other_sales.os_compcode = compcode AND
    trnpur_other_sales.os_fincode = finid AND
    trnpur_other_sales.os_docno = docno;
END ;;
DELIMITER ;
