CREATE DEFINER=`root`@`%` PROCEDURE `spst_rep_othersales_detail`(compcode int,finid int,fromdate date,todate date)
BEGIN
 select * from trn_other_sales ,
 massal_customer , mas_othersales_item_master ,    mas_uom where  os_custcode = cust_code and os_item = salitem_code and 
 salitem_uom = uom_code and os_compcode = compcode and os_fincode = finid and os_date between fromdate  and todate;
END ;;
