CREATE DEFINER=`root`@`%` PROCEDURE `spst_rep_partywise_receipt`(compcode int,fincode int,startdate datetime, enddate datetime)
BEGIN
SELECT
    trnpur_min_trailer.mint_minno, trnpur_min_trailer.mint_mindate, trnpur_min_trailer.mint_pono, trnpur_min_trailer.mint_rcvd_qty, trnpur_min_trailer.mint_value, trnpur_min_trailer.mint_cr_status,
    trnpur_min_header.minh_comp_code, trnpur_min_header.minh_mindate, trnpur_min_header.minh_fin_code, trnpur_min_header.minh_bill_no, trnpur_min_header.minh_bill_date,
    mas_company.company_name,
    massal_customer.cust_name, massal_customer.cust_ref,
    maspur_item_header.item_name,
    mas_uom.uom_short_name
FROM
    { oj (((((trnpur_min_trailer trnpur_min_trailer INNER JOIN mas_company mas_company ON
        trnpur_min_trailer.mint_comp_code = mas_company.company_code)
     INNER JOIN massal_customer massal_customer ON
        trnpur_min_trailer.mint_sup_code = massal_customer.cust_code)
     INNER JOIN maspur_item_header maspur_item_header ON
        trnpur_min_trailer.mint_item_code = maspur_item_header.item_code)
     INNER JOIN trnpur_min_header trnpur_min_header ON
        trnpur_min_trailer.mint_comp_code = trnpur_min_header.minh_comp_code AND
    trnpur_min_trailer.mint_minno = trnpur_min_header.minh_minno AND
    trnpur_min_trailer.mint_mindate = trnpur_min_header.minh_mindate AND
    trnpur_min_trailer.mint_fin_code = trnpur_min_header.minh_fin_code AND
    trnpur_min_trailer.mint_sup_code = trnpur_min_header.minh_sup_code)
     INNER JOIN mas_uom mas_uom ON
        maspur_item_header.item_uom = mas_uom.uom_code)
}
WHERE
    trnpur_min_header.minh_comp_code = compcode AND
    trnpur_min_header.minh_fin_code = fincode AND
    trnpur_min_header.minh_mindate >= startdate AND
    trnpur_min_header.minh_mindate <= enddate 
ORDER BY
    massal_customer.cust_name ASC,
    trnpur_min_trailer.mint_minno ASC;
    
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
