/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`%` PROCEDURE `spst_rep_stock_groupsummary`(compcode int, finid int , fromdate date,todate date)
BEGIN
truncate table  group_summary;

insert into  group_summary  
select * from (
   select  'GS' grp_type , grp_name,cast(grp_code as unsigned) grp_code ,round(sum(op_qty),3) as op_qty , 
    case when  sum(op_value)  != 0 then 
    round(sum(op_value) / sum(op_qty),2)  else 0.00 end as op_rate, 
    round(sum(op_value),2) as op_value ,  
   round(sum(rec_qty),3) rec_qty, 
   case when  sum(rec_val)  != 0 then round(sum(rec_val) / sum(rec_qty),2)  else 0.00 end as rec_rate, 
   round(sum(rec_val),2) rec_val , 
   round(sum(iss_qty),3) iss_qty, 
    case when  sum(iss_val)  !=  0 then round(sum(iss_val) / sum(iss_qty),2)  else 0.00 end as iss_rate, 
   round(sum(iss_val),2) iss_val,  
   round(sum(op_qty) + sum(rec_qty)  - sum(iss_qty) ,3) as clo_qty,
    case when  sum(op_value) + sum(rec_val)  - sum(iss_val)  > 0 then round((sum(op_value) + sum(rec_val)  - sum(iss_val))  / (sum(op_qty) + sum(rec_qty)  + sum(iss_qty)),2)   else 0.00 end as clo_rate, 
   round(sum(op_value) + sum(rec_val)  - sum(iss_val),2) as clo_val
   
   from (
   select item_code , sum(op_qty) as op_qty , sum(op_value) as op_value ,  sum(rec_qty) rec_qty, sum(rec_val) rec_val , sum(iss_qty) iss_qty, sum(iss_val) iss_val  from (
  select op_item_code as item_code , sum(op_qty) as op_qty , sum(op_value) as op_value ,0 as rec_qty,0 as rec_val,0 as iss_qty,0 as iss_val
  from tmp_pur_op_value     group by op_item_code
  union all
  select item_code , 0 as op_qty , 0 as op_value , sum(rec_qty) rec_qty, sum(rec_val) rec_val , sum(iss_qty) iss_qty, sum(iss_val) iss_val  from tmp_pur_store_ledger
  group by item_code
  ) a1  group by item_code ) a2
     join maspur_item_header mas on a2.item_code = mas.item_code 
   join maspur_subgroup subgrp on mas.item_group_code =  subgrp.subgrp_code
   join maspur_group maingrp on maingrp.grp_code =  subgrp.subgrp_grpcode
   where op_value > 0 or rec_val != 0 or  iss_val !=0 group by grp_name,grp_code order by grp_name
)a1;
 
insert into  group_summary  
 select 'RM' grp_type ,  grp_name, cast(grp_code as unsigned) grp_code, opstk op_qty , 
  case when  opval  != 0 then round(opval / opstk,2) else  0 end as op_rate,
    round(opval,2) op_value, round(recpt_qty,3) rec_qty, 
  case when  recpt_val  != 0 then round(recpt_val / recpt_qty,2) else  0 end as rec_rate,
  round(recpt_val,2) rec_val, round(iss_qty,3) iss_qty,  
  case when  iss_val  != 0 then round(iss_val / iss_qty,2) else  0 end as iss_rate,
   round(iss_val,2), round(clo_qty,3) clo_qty, 
   case when  clo_val  != 0 then round(clo_val / clo_qty,2) else  0 end as clo_rate,
 round(clo_val,2) clo_val
 from (
 select       
"PURCHASE WASTE PAPER" grp_name,1000 grp_code  ,sum(opstk) as opstk,sum(opval) as opval,
sum(recpt_qty) as recpt_qty,sum(recpt_val) as recpt_val,sum(iss_qty) as iss_qty,
sum(iss_val) as iss_val,sum(sal_qty) as sal_qty,sum(sal_val) as sal_val,
sum(ret_qty) as ret_qty, sum(ret_val) as ret_val,  
(sum(opval)+sum(recpt_val)+sum(iss_val)+sum(sal_val)+sum(ret_val)) as tot,
(sum(opstk)+sum(recpt_qty)+sum(iss_qty)+sum(sal_qty)+sum(ret_qty)) as clo_qty,
(sum(opval)+sum(recpt_val)+sum(iss_val)+sum(sal_val)+sum(ret_val)) as clo_val          
from      
(select itmt_compcode as compcode,itmt_hdcode as itemcode,itmt_opqty as opstk,itmt_opvalue as opval,0 as recpt_qty,0 as recpt_val,0 as iss_qty,0 as iss_val,0 as sal_qty,0 as sal_val,0 as ret_qty,0 as ret_val from masrm_item_trailer where itmt_compcode in 
  (compcode) and itmt_fincode = finid  and itmt_opqty >0      
union all      
select rech_compcode as compcode,rect_item_code as itemcode, sum(rect_grnqty) as opstk,sum(rect_costvalue) as opval,0 as recpt_qty,0 as recpt_val,0 as iss_qty,0 as iss_val,0 as sal_qty,0 as sal_val,0 as ret_qty,0 as ret_val  from vew_rm_receiptheadermerge h,vew_rm_receipttrailermerge  t  where h.type=t.type and rech_seqno = rect_hdseqno and  rech_compcode in (compcode) and rech_fincode = finid  and rech_date < fromdate  group by rech_compcode,rech_fincode,rect_item_code    
  
union all      
select rech_compcode as compcode,rect_item_code as itemcode, 0 as opstk,0 as opval,sum(rect_grnqty) as recpt_qty,sum(rect_costvalue) as recpt_val,0 as iss_qty,0 as iss_val,0 as sal_qty,0 as sal_val,0 as ret_qty,0 as ret_val  from vew_rm_receiptheadermerge h,vew_rm_receipttrailermerge  t  where h.type=t.type and rech_seqno = rect_hdseqno and  rech_compcode in (compcode) and rech_fincode = finid  and rech_date >= fromdate  and rech_date <= todate  group by rech_compcode,rech_fincode,rect_item_code      
union all      
select rerh_compcode as compcode,rert_itemcode as itemcode, sum(rert_qty)*-1 as opstk,sum(rert_totitemvalue)* -1 as opval,0 as recpt_qty,0 as recpt_val,0 as iss_qty,0 as iss_val,0 as sal_qty,0 as sal_val, 0 as ret_qty,0 as ret_val  from vew_rm_receiptret_headermerge h,vew_rm_receiptret_trailermerge  t  where h.type=t.type and rerh_seqno = rert_hdseqno and rerh_compcode in (compcode)  and rerh_fincode = finid  and rerh_date < fromdate   group by rerh_compcode,rerh_fincode,rert_itemcode       
union all      
select rerh_compcode as compcode, rert_itemcode as itemcode, 0 as opstk,0 as opval,0 as recpt_qty,0 as recpt_val,0 as iss_qty,0 as iss_val,0 as sal_qty,0 as sal_val, sum(rert_qty) as ret_qty,sum(rert_totitemvalue) as ret_val  from vew_rm_receiptret_headermerge h,vew_rm_receiptret_trailermerge  t  where h.type=t.type and rerh_seqno = rert_hdseqno and rerh_compcode in (compcode) and rerh_fincode = finid  and rerh_date >= fromdate  and rerh_date <= todate  group by rerh_compcode,rerh_fincode,rert_itemcode       
union all      
select issh_compcode as compcode , isst_itmcode as itemcode ,sum(isst_qty)*-1 as opstk,sum(isst_qty * isst_rate)*-1 as opval,0 as recpt_qty,0 as recpt_val,0 as iss_qty,0 as iss_val,0 as sal_qty,0 as sal_val,0 as ret_qty,0 as ret_val  from trnrm_issue_header ,trnrm_issue_trailer where issh_seqno = isst_hdseqno and issh_compcode in (compcode) and  issh_fincode = finid  and issh_date < fromdate  group by issh_compcode ,isst_itmcode      
union all      
select issh_compcode as compcode , isst_itmcode as itemcode ,0 as opstk,0 as opval,0 as recpt_qty,0 as recpt_val,sum(isst_qty) as iss_qty,sum(isst_qty * isst_rate) as iss_val,0 as sal_qty,0 as sal_val,0 as ret_qty,0 as ret_val  from trnrm_issue_header ,trnrm_issue_trailer where issh_seqno = isst_hdseqno and issh_compcode in (compcode) and  issh_fincode = finid  and issh_date >= fromdate  and issh_date <= todate  group by issh_compcode ,isst_itmcode      
union all      
select isrh_compcode as compcode,isrt_itemcode as itemcode ,sum(isrt_qty) as opstk,sum(isrt_values) as op_value,   0 as recpt_qty,0 as recpt_val,0 as iss_qty,0 as iss_val,0 as sal_qty,0 as sal_val,0 as ret_qty,0 as ret_val from trnrm_issret_header ,trnrm_issret_trailer   where isrh_seqno = isrt_hdseqno and isrh_compcode in (compcode) and isrh_fincode = finid  and isrh_date < fromdate  group by isrh_compcode ,isrt_itemcode      
union all      
select isrh_compcode as compcode,isrt_itemcode as itemcode ,0 as opstk,0 as op_value,   0 as recpt_qty,0 as recpt_val,sum(isrt_qty)*-1 as iss_qty,sum(isrt_values)*-1 as iss_val,0 as sal_qty,0 as sal_val,0 as ret_qty,0 as ret_val from trnrm_issret_header ,trnrm_issret_trailer   where isrh_seqno = isrt_hdseqno and isrh_compcode in (compcode) and isrh_fincode = finid  and isrh_date >= fromdate  and isrh_date <= todate group by isrh_compcode ,isrt_itemcode      
union all      
select salh_compcode as compcode, salt_itemcode as itemcode,sum(salt_qty) *-1 as opstk,sum(salt_value)*-1 as opval,0 as recpt_qty,0 as recpt_val,0 as iss_qty,0 as iss_val,0 as sal_qty,0 as sal_val,0 as ret_qty,0 as ret_val from trnrm_salenote_header, trnrm_salenote_trailer  where salh_seqno = salt_hdseqno and salh_compcode in (compcode) and salh_fincode = finid  and salh_date < fromdate  group by salh_compcode,salt_itemcode       
union all      
select salh_compcode as compcode, salt_itemcode as itemcode, 0 as opstk,0 as opval,0 as recpt_qty,0 as recpt_val,0 as iss_qty,0 as iss_val,sum(salt_qty)  as sal_qty,sum(salt_value) as sal_val,0 as ret_qty,0 as ret_val from trnrm_salenote_header, trnrm_salenote_trailer  where salh_seqno = salt_hdseqno and salh_compcode in (compcode) and salh_fincode = finid  and salh_date >= fromdate and salh_date  <= todate group by salh_compcode,salt_itemcode      
) as aa inner join masrm_item_header b on aa.itemcode = b.itmh_code 
) a2 ;

insert into  group_summary  
 select 'FU' grp_type ,  grp_name, cast(grp_code as unsigned) grp_code, opstk op_qty , 
  case when  opval  != 0 then round(opval / opstk,2) else  0 end as op_rate,
    round(opval,2) op_value, round(recpt_qty,3) rec_qty, 
  case when  recpt_val  != 0 then round(recpt_val / recpt_qty,2) else  0 end as rec_rate,
  round(recpt_val,2) rec_val, round(iss_qty,3) iss_qty,  
  case when  iss_val  != 0 then round(iss_val / iss_qty,2) else  0 end as iss_rate,
   round(iss_val,2), round(clo_qty,3) clo_qty, 
   case when  clo_val  != 0 then round(clo_val / clo_qty,2) else  0 end as clo_rate,
 round(clo_val,2) clo_val
 from (
 select       
"PURCHASE FUEL" grp_name,2000 grp_code  ,sum(opstk) as opstk,sum(opval) as opval,
sum(recpt_qty) as recpt_qty,sum(recpt_val) as recpt_val,sum(iss_qty) as iss_qty,
sum(iss_val) as iss_val,sum(sal_qty) as sal_qty,sum(sal_val) as sal_val,
sum(ret_qty) as ret_qty, sum(ret_val) as ret_val,  
(sum(opval)+sum(recpt_val)+sum(iss_val)+sum(sal_val)+sum(ret_val)) as tot,
(sum(opstk)+sum(recpt_qty)+sum(iss_qty)+sum(sal_qty)+sum(ret_qty)) as clo_qty,
(sum(opval)+sum(recpt_val)+sum(iss_val)+sum(sal_val)+sum(ret_val)) as clo_val          
from      
(select itmt_compcode as compcode,itmt_hdcode as itemcode,itmt_opqty as opstk,itmt_opvalue as opval,0 as recpt_qty,0 as recpt_val,0 as iss_qty,0 as iss_val,0 as sal_qty,0 as sal_val,0 as ret_qty,0 as ret_val from masfu_item_trailer where itmt_compcode in 
  (compcode) and itmt_fincode = finid  and itmt_opqty >0      
union all      
select rech_compcode as compcode,rect_item_code as itemcode, sum(rect_grnqty) as opstk,sum(rect_costvalue) as opval,0 as recpt_qty,0 as recpt_val,0 as iss_qty,0 as iss_val,0 as sal_qty,0 as sal_val,0 as ret_qty,0 as ret_val  from trnfu_receipt_header h,trnfu_receipt_trailer  t  where rech_seqno = rect_hdseqno and  rech_compcode in (compcode) and rech_fincode = finid  and rech_date < fromdate  group by rech_compcode,rech_fincode,rect_item_code    
  
union all      
select rech_compcode as compcode,rect_item_code as itemcode, 0 as opstk,0 as opval,sum(rect_grnqty) as recpt_qty,sum(rect_costvalue) as recpt_val,0 as iss_qty,0 as iss_val,0 as sal_qty,0 as sal_val,0 as ret_qty,0 as ret_val  from trnfu_receipt_header h,trnfu_receipt_trailer  t  where rech_seqno = rect_hdseqno and  rech_compcode in (compcode) and rech_fincode = finid  and rech_date >= fromdate  and rech_date <= todate  group by rech_compcode,rech_fincode,rect_item_code      
union all      
    
select issh_compcode as compcode , isst_itmcode as itemcode ,sum(isst_qty)*-1 as opstk,sum(isst_qty * isst_rate)*-1 as opval,0 as recpt_qty,0 as recpt_val,0 as iss_qty,0 as iss_val,0 as sal_qty,0 as sal_val,0 as ret_qty,0 as ret_val  from trnfu_issue_header ,trnfu_issue_trailer where issh_seqno = isst_hdseqno and issh_compcode in (compcode) and  issh_fincode = finid  and issh_date < fromdate  group by issh_compcode ,isst_itmcode      
union all      
select issh_compcode as compcode , isst_itmcode as itemcode ,0 as opstk,0 as opval,0 as recpt_qty,0 as recpt_val,sum(isst_qty) as iss_qty,sum(isst_qty * isst_rate) as iss_val,0 as sal_qty,0 as sal_val,0 as ret_qty,0 as ret_val  from trnfu_issue_header ,trnfu_issue_trailer where issh_seqno = isst_hdseqno and issh_compcode in (compcode) and  issh_fincode = finid  and issh_date >= fromdate  and issh_date <= todate  group by issh_compcode ,isst_itmcode      
union all      
select isrh_compcode as compcode,isrt_itemcode as itemcode ,sum(isrt_qty) as opstk,sum(isrt_values) as op_value,   0 as recpt_qty,0 as recpt_val,0 as iss_qty,0 as iss_val,0 as sal_qty,0 as sal_val,0 as ret_qty,0 as ret_val from trnfu_issret_header ,trnfu_issret_trailer   where isrh_seqno = isrt_hdseqno and isrh_compcode in (compcode) and isrh_fincode = finid  and isrh_date < fromdate  group by isrh_compcode ,isrt_itemcode      
union all      
select isrh_compcode as compcode,isrt_itemcode as itemcode ,0 as opstk,0 as op_value,   0 as recpt_qty,0 as recpt_val,sum(isrt_qty)*-1 as iss_qty,sum(isrt_values)*-1 as iss_val,0 as sal_qty,0 as sal_val,0 as ret_qty,0 as ret_val from trnfu_issret_header ,trnfu_issret_trailer   where isrh_seqno = isrt_hdseqno and isrh_compcode in (compcode) and isrh_fincode = finid  and isrh_date >= fromdate  and isrh_date <= todate group by isrh_compcode ,isrt_itemcode          

) as aa inner join masfu_item_header b on aa.itemcode = b.itmh_code 
) a2 ;

select * from group_summary;
END ;;
