/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`%` PROCEDURE `spst_rep_stock_groupsummary24032025`(compcode int, finid int , fromdate date,todate date)
BEGIN
   select  grp_name,grp_code ,sum(op_qty) as op_qty , 
    case when  sum(op_value)  != 0 then 
    round(sum(op_value) / sum(op_qty),2)  else 0.00 end as op_rate, 
    sum(op_value) as op_value ,  
   sum(rec_qty) rec_qty, 
   case when  sum(rec_val)  != 0 then round(sum(rec_val) / sum(rec_qty),2)  else 0.00 end as rec_rate, 
   round(sum(rec_val),2) rec_val , 
   sum(iss_qty) iss_qty, 
    case when  sum(iss_val)  !=  0 then round(sum(iss_val) / sum(iss_qty),2)  else 0.00 end as iss_rate, 
   round(sum(iss_val),2) iss_val,  
   sum(op_qty) + sum(rec_qty)  - sum(iss_qty)  as clo_qty,
    case when  sum(op_value) + sum(rec_val)  - sum(iss_val)  > 0 then round((sum(op_value) + sum(rec_val)  - sum(iss_val))  / (sum(op_qty) + sum(rec_qty)  + sum(iss_qty)),2)   else 0.00 end as clo_rate, 
   round(sum(op_value) + sum(rec_val)  - sum(iss_val),2) as clo_val
   
   from (
   select item_code , sum(op_qty) as op_qty , sum(op_value) as op_value ,  sum(rec_qty) rec_qty, sum(rec_val) rec_val , sum(iss_qty) iss_qty, sum(iss_val) iss_val  from (
  select op_item_code as item_code , sum(op_qty) as op_qty , sum(op_value) as op_value ,0 as rec_qty,0 as rec_val,0 as iss_qty,0 as iss_val
  from tmp_pur_op_value     group by op_item_code
  union all
  select item_code , 0 as op_qty , 0 as op_value , sum(rec_qty) rec_qty, sum(rec_val) rec_val , sum(iss_qty) iss_qty, sum(iss_val) iss_val  from tmp_pur_store_ledger
  group by item_code
  ) a1  group by item_code ) a2
     join maspur_item_header mas on a2.item_code = mas.item_code 
   join maspur_subgroup subgrp on mas.item_group_code =  subgrp.subgrp_code
   join maspur_group maingrp on maingrp.grp_code =  subgrp.subgrp_grpcode
   where op_value > 0 or rec_val != 0 or  iss_val !=0 group by grp_name,grp_code order by grp_name;
/*
select  grp_name, grp_code,round(op_qty,3) op_qty, round(op_rate,5) op_rate, round(op_value,2) op_value, 
round(rec_qty,3) rec_qty, round(rec_rate,5) rec_rate, round(rec_val,2) rec_val, 
round(iss_qty,3) iss_qty , ifnull(round(iss_rate,5),0) iss_rate , round(iss_val) iss_val, 
round(clo_qty,3) clo_qty, round(clo_rate,5) clo_rate, round(clo_val,2) clo_val   from (
select * from
(
select grp_name, grp_code,op_qty,  case when op_value > 0 then op_value / op_qty else 0 end op_rate, op_value, 
rec_qty , case when rec_val >0 then  rec_val /rec_qty else 0 end rec_rate, rec_val, 
iss_qty , case when iss_val >0 then  iss_val /iss_qty else 0 end iss_rate, iss_val, 
clo_qty , case when clo_val >0 then  clo_val /clo_qty else 0 end clo_rate, clo_val  from

(
SELECT

	maspur_group.grp_name, grp_code,
    sum(maspur_item_trailer.item_yr_opqty)+sum(tmp_pur_op_value.op_rec_qty) - sum(tmp_pur_op_value.op_ret_rec_qty) - sum(tmp_pur_op_value.op_adjm_qty) -   sum(tmp_pur_op_value.op_iss_qty) + sum(tmp_pur_op_value.op_ret_iss_qty) + sum(tmp_pur_op_value.op_adjp_qty) as op_qty ,
    sum(maspur_item_trailer.item_yr_opval)+sum(tmp_pur_op_value.op_rec_val) - sum(tmp_pur_op_value.op_ret_rec_val) - sum(tmp_pur_op_value.op_adjm_val) -   sum(tmp_pur_op_value.op_iss_val) + sum(tmp_pur_op_value.op_ret_iss_val) + sum(tmp_pur_op_value.op_adjp_val) as op_value,  
    sum(tmp_pur_store_ledger.rec_qty) rec_qty  , sum(tmp_pur_store_ledger.rec_val) rec_val, 
    sum(tmp_pur_store_ledger.iss_qty) iss_qty , sum(tmp_pur_store_ledger.iss_val) iss_val,
    sum(maspur_item_trailer.item_yr_opqty)+sum(tmp_pur_op_value.op_rec_qty) - sum(tmp_pur_op_value.op_ret_rec_qty) - sum(tmp_pur_op_value.op_adjm_qty) -   sum(tmp_pur_op_value.op_iss_qty) + sum(tmp_pur_op_value.op_ret_iss_qty) + sum(tmp_pur_op_value.op_adjp_qty)+ sum(tmp_pur_store_ledger.rec_qty) - sum(tmp_pur_store_ledger.iss_qty)   as clo_qty ,    
    sum(maspur_item_trailer.item_yr_opval)+sum(tmp_pur_op_value.op_rec_val) - sum(tmp_pur_op_value.op_ret_rec_val) - sum(tmp_pur_op_value.op_adjm_val) -   sum(tmp_pur_op_value.op_iss_val) + sum(tmp_pur_op_value.op_ret_iss_val) + sum(tmp_pur_op_value.op_adjp_val) + sum(tmp_pur_store_ledger.rec_val) - sum(tmp_pur_store_ledger.iss_val)  as clo_val  
FROM
    { oj ((((((tmp_pur_store_ledger tmp_pur_store_ledger 
     INNER JOIN tmp_pur_op_value tmp_pur_op_value ON
        tmp_pur_store_ledger.item_code = tmp_pur_op_value.item_code)
     LEFT OUTER JOIN massal_customer massal_customer ON
        tmp_pur_store_ledger.party = massal_customer.cust_code)
     INNER JOIN maspur_item_trailer maspur_item_trailer ON
        tmp_pur_op_value.item_code = maspur_item_trailer.item_code)
     INNER JOIN maspur_item_header maspur_item_header ON
        tmp_pur_op_value.item_code = maspur_item_header.item_code)
     INNER JOIN maspur_subgroup maspur_subgroup ON
        maspur_item_header.item_group_code = maspur_subgroup.subgrp_code)
     INNER JOIN maspur_group maspur_group ON
        maspur_group.grp_code = maspur_subgroup.subgrp_grpcode)     
        
     INNER JOIN mas_uom mas_uom ON
        maspur_item_header.item_uom = mas_uom.uom_code}
WHERE
    maspur_item_trailer.item_comp_code = compcode AND
    maspur_item_trailer.item_fin_code = finid AND
    tmp_pur_op_value.item_code > 0
    group by maspur_group.grp_name,maspur_group.grp_code
) a1 order by grp_name ) ab1

union all    
select       
"Purchase Waste Paper" grp_name,'2000' grp_code,
sum(opstk) as op_qty, sum(opval) / sum(opstk)  op_rate, sum(opval) as op_val,
sum(recpt_qty) as rec_qty, sum(recpt_val)/sum(recpt_qty) rec_rate,  sum(recpt_val) as rec_val,sum(iss_qty+sal_qty-ret_qty) as iss_qty,
sum(iss_val+sal_val-ret_val) / sum(iss_qty+sal_qty-ret_qty) iss_rate,
sum(iss_val+sal_val-ret_val) as iss_val,
sum(opstk)+sum(recpt_qty)+sum(iss_qty)+sum(sal_qty)+sum(ret_qty) as clo_qty,       
sum(opval)+sum(recpt_val)+sum(iss_val)+sum(sal_val)+sum(ret_val)/sum(opstk)+sum(recpt_qty)+sum(iss_qty)+sum(sal_qty)+sum(ret_qty) as clo_rate,
sum(opval)+sum(recpt_val)+sum(iss_val)+sum(sal_val)+sum(ret_val) as clo_val
from      
(
select itmt_compcode as compcode,itmt_hdcode as itemcode,itmt_opqty as opstk,itmt_opvalue as opval,0 as recpt_qty,0 as recpt_val,0 as iss_qty,0 as iss_val,0 as sal_qty,0 as sal_val,0 as ret_qty,0 as ret_val from masrm_item_trailer where itmt_compcode = compcode 
and itmt_fincode = finid  and itmt_opqty >0      
union all      
select rech_compcode as compcode,rect_item_code as itemcode, sum(rect_grnqty) as opstk,sum(rect_costvalue) as opval,0 as recpt_qty,0 as recpt_val,0 as iss_qty,0 as iss_val,0 as sal_qty,0 as sal_val,0 as ret_qty,0 as ret_val  from vew_rm_receiptheadermerge h,vew_rm_receipttrailermerge  t  where h.type=t.type and rech_seqno = rect_hdseqno and  rech_compcode = compcode and rech_fincode = finid  and rech_date < fromdate  group by rech_compcode,rech_fincode,rect_item_code    
 
union all      
select rech_compcode as compcode,rect_item_code as itemcode, 0 as opstk,0 as opval,sum(rect_grnqty) as recpt_qty,sum(rect_costvalue) as recpt_val,0 as iss_qty,0 as iss_val,0 as sal_qty,0 as sal_val,0 as ret_qty,0 as ret_val  from vew_rm_receiptheadermerge h,vew_rm_receipttrailermerge  t  where h.type=t.type and rech_seqno = rect_hdseqno and  rech_compcode = compcode and rech_fincode = finid and rech_date >= fromdate  and rech_date <= todate  group by rech_compcode,rech_fincode,rect_item_code      
union all      
select rerh_compcode as compcode,rert_itemcode as itemcode, sum(rert_qty)* - 1 as opstk,sum(rert_totitemvalue)* -compcode as opval,0 as recpt_qty,0 as recpt_val,0 as iss_qty,0 as iss_val,0 as sal_qty,0 as sal_val, 0 as ret_qty,0 as ret_val  from vew_rm_receiptret_headermerge h,vew_rm_receiptret_trailermerge  t  where h.type=t.type and rerh_seqno = rert_hdseqno and rerh_compcode  = compcode  and rerh_fincode = finid  and rerh_date < fromdate   group by rerh_compcode,rerh_fincode,rert_itemcode   
union all      
select rerh_compcode as compcode, rert_itemcode as itemcode, 0 as opstk,0 as opval,0 as recpt_qty,0 as recpt_val,0 as iss_qty,0 as iss_val,0 as sal_qty,0 as sal_val, sum(rert_qty) as ret_qty,sum(rert_totitemvalue) as ret_val  from vew_rm_receiptret_headermerge h,vew_rm_receiptret_trailermerge  t  where h.type=t.type and rerh_seqno = rert_hdseqno and rerh_compcode  = compcode and rerh_fincode = finid  and rerh_date >= fromdate  and rerh_date <= todate  group by rerh_compcode,rerh_fincode,rert_itemcode       
union all      
select issh_compcode as compcode , isst_itmcode as itemcode ,sum(isst_qty)* - 1 as opstk,sum(isst_qty * isst_rate)* - 1 as opval,0 as recpt_qty,0 as recpt_val,0 as iss_qty,0 as iss_val,0 as sal_qty,0 as sal_val,0 as ret_qty,0 as ret_val  from trnrm_issue_header ,trnrm_issue_trailer where issh_seqno = isst_hdseqno and issh_compcode  = compcode and  issh_fincode = finid  and issh_date < fromdate  group by issh_compcode ,isst_itmcode      
union all      
select issh_compcode as compcode , isst_itmcode as itemcode ,0 as opstk,0 as opval,0 as recpt_qty,0 as recpt_val,sum(isst_qty) as iss_qty,sum(isst_qty * isst_rate) as iss_val,0 as sal_qty,0 as sal_val,0 as ret_qty,0 as ret_val  from trnrm_issue_header ,trnrm_issue_trailer where issh_seqno = isst_hdseqno and issh_compcode  = compcode and  issh_fincode = finid  and issh_date >= fromdate  and issh_date <= todate  group by issh_compcode,isst_itmcode      
union all      
select isrh_compcode as compcode,isrt_itemcode as itemcode ,sum(isrt_qty) as opstk,sum(isrt_values) as op_value,   0 as recpt_qty,0 as recpt_val,0 as iss_qty,0 as iss_val,0 as sal_qty,0 as sal_val,0 as ret_qty,0 as ret_val from trnrm_issret_header ,trnrm_issret_trailer   where isrh_seqno = isrt_hdseqno and isrh_compcode  = compcode and isrh_fincode = finid  and isrh_date < fromdate  group by isrh_compcode,isrt_itemcode      
union all      
select isrh_compcode as compcode,isrt_itemcode as itemcode ,0 as opstk,0 as op_value,   0 as recpt_qty,0 as recpt_val,sum(isrt_qty)* - 1 as iss_qty,sum(isrt_values)* - 1 as iss_val,0 as sal_qty,0 as sal_val,0 as ret_qty,0 as ret_val from trnrm_issret_header ,trnrm_issret_trailer   where isrh_seqno = isrt_hdseqno and isrh_compcode  = compcode and isrh_fincode = finid  and isrh_date >= fromdate  and isrh_date <= todate group by isrh_compcode ,isrt_itemcode      
union all      
select salh_compcode as compcode, salt_itemcode as itemcode,sum(salt_qty) * - 1 as opstk,sum(salt_value)* - 1 as opval,0 as recpt_qty,0 as recpt_val,0 as iss_qty,0 as iss_val,0 as sal_qty,0 as sal_val,0 as ret_qty,0 as ret_val from trnrm_salenote_header, trnrm_salenote_trailer  where salh_seqno = salt_hdseqno and salh_compcode  = compcode and salh_fincode = finid  and salh_date < fromdate  group by salh_compcode,salt_itemcode      
union all      
select salh_compcode as compcode, salt_itemcode as itemcode, 0 as opstk,0 as opval,0 as recpt_qty,0 as recpt_val,0 as iss_qty,0 as iss_val,sum(salt_qty)  as sal_qty,sum(salt_value) as sal_val,0 as ret_qty,0 as ret_val from trnrm_salenote_header, trnrm_salenote_trailer  where salh_seqno = salt_hdseqno and salh_compcode  = compcode and salh_fincode = finid  and salh_date >= fromdate and salh_date  <= todate group by salh_compcode,salt_itemcode   
) as aa inner join masrm_item_header b on aa.itemcode = b.itmh_code
union all
select grp_name , '3000' grp_code,sum(itmt_opqty+op_rect_qty-op_recret_qty-op_is_qty+op_ir_qty-op_sale_qty) op_qty ,
sum(itmt_opvalue+op_rect_val-op_recret_val-op_is_value+op_ir_value-op_sale_value)  / sum(itmt_opqty+op_rect_qty-op_recret_qty-op_is_qty+op_ir_qty-op_sale_qty) op_rate,
 sum(itmt_opvalue+op_rect_val-op_recret_val-op_is_value+op_ir_value-op_sale_value) op_val,
sum(rect_qty-recret_qty) rec_qty, 
sum(rect_val-recret_val) / sum(rect_qty-recret_qty)  rec_rate,
sum(rect_val-recret_val) rec_val,
sum(is_qty+ir_qty-sale_qty) iss_qty,
sum(is_value+ir_value-sale_value) / sum(is_qty+ir_qty-sale_qty)  iss_rate,
sum(is_value+ir_value-sale_value) iss_val,
(sum(itmt_opqty+op_rect_qty-op_recret_qty-op_is_qty+op_ir_qty-op_sale_qty) + sum(rect_qty-recret_qty) - sum(is_value+ir_value-sale_value) ) clo_qty,
(sum(itmt_opvalue+op_rect_val-op_recret_val-op_is_value+op_ir_value-op_sale_value) +sum(rect_val-recret_val) - sum(is_value+ir_value-sale_value) ) / 
(sum(itmt_opqty+op_rect_qty-op_recret_qty-op_is_qty+op_ir_qty-op_sale_qty) + sum(rect_qty-recret_qty) - sum(is_value+ir_value-sale_value)) clo_rate,
(sum(itmt_opvalue+op_rect_val-op_recret_val-op_is_value+op_ir_value-op_sale_value) +sum(rect_val-recret_val) - sum(is_value+ir_value-sale_value) ) clo_val 
from (
select 
"Fuel Items"  grp_name,
itmt_opqty,itmt_opvalue,
ifnull(opre.op_rect_qty,0) as op_rect_qty,ifnull(opre.op_rect_val,0) as op_rect_val,  
ifnull(oprr.op_recret_qty,0) as op_recret_qty,ifnull(oprr.op_recret_val,0) as op_recret_val,
ifnull(opis.op_is_qty,0) as op_is_qty,ifnull(opis.op_is_value,0) as op_is_value,  
ifnull(opir.op_ir_qty,0) as op_ir_qty,ifnull(opir.op_ir_value,0) as op_ir_value,
ifnull(opsale.op_sale_qty,0) as op_sale_qty,ifnull(opsale.op_sale_value,0) as op_sale_value,  
ifnull(re.rect_qty,0) as rect_qty,ifnull(re.rect_val,0) as rect_val,
ifnull(rr.recret_qty,0) as recret_qty,ifnull(rr.recret_val,0) as recret_val,
ifnull(iss.is_qty,0) as is_qty,  
ifnull(iss.is_value,0) as is_value,ifnull(isr.ir_qty,0) as ir_qty,
ifnull(isr.ir_value,0) as ir_value ,ifnull(sale.sale_qty,0) as sale_qty,
ifnull(sale.sale_value,0) as sale_value from  
masfu_item_trailer d
left outer join  
(select rech_compcode,rect_item_code,ifnull(sum(rect_grnqty),0) as op_rect_qty ,
ifnull(sum(rect_costvalue),0) as op_rect_val   
from trnfu_receipt_header,trnfu_receipt_trailer   
where rech_seqno = rect_hdseqno and rech_compcode = compcode 
and rech_fincode = finid and rech_date >= fromdate and rech_date < fromdate  
group by rech_compcode,rech_fincode,rect_item_code) opre on
  d.itmt_hdcode =opre.rect_item_code
  
 left outer join
(select rerh_compcode,rert_itemcode,ifnull(sum(rert_qty),0) as op_recret_qty,
ifnull(sum(rert_totitemvalue),0) as op_recret_val  
from trnfu_receiptret_header,trnfu_receiptret_trailer   
where rerh_seqno = rert_hdseqno and rerh_compcode = compcode 
and rerh_fincode = finid and rerh_date >= fromdate and rerh_date < fromdate  
group by rerh_compcode,rerh_fincode,rert_itemcode) oprr on
  d.itmt_hdcode = oprr.rert_itemcode
  
   left outer join
(select issh_compcode,isst_itmcode ,ifnull(sum(isst_qty),0) as op_is_qty,
ifnull(sum(isst_values),0) as op_is_value   
from trnfu_issue_header ,trnfu_issue_trailer   
where issh_seqno = isst_hdseqno and issh_compcode = compcode 
and issh_fincode = finid and issh_date >= fromdate and issh_date < fromdate  
group by issh_compcode,isst_itmcode) opis on
  d.itmt_hdcode = opis.isst_itmcode
   left outer join
(select isrh_compcode,isrt_itemcode ,ifnull(sum(isrt_qty),0) as op_ir_qty,
ifnull(sum(isrt_values),0) as op_ir_value   
from trnfu_issret_header ,trnfu_issret_trailer   
where isrh_seqno = isrt_hdseqno and isrh_compcode = compcode 
and isrh_fincode = finid and isrh_date >= fromdate and isrh_date < fromdate  
group by isrh_compcode,isrt_itemcode) opir on
  d.itmt_hdcode = opir.isrt_itemcode
   left outer join
(select salh_compcode,salt_itemcode,ifnull(sum(salt_qty),0) as op_sale_qty,
ifnull(sum(salt_value),0) as op_sale_value  
from trnfu_salenote_header, trnfu_salenote_trailer  
where salh_seqno = salt_hdseqno and salh_compcode = compcode 
and salh_fincode = finid and salh_date >= fromdate and salh_date < fromdate  
group by salh_compcode,salt_itemcode) opsale on
  d.itmt_hdcode = opsale.salt_itemcode
   left outer join
(select rech_compcode,rect_item_code,ifnull(sum(rect_grnqty),0) as rect_qty ,
ifnull(sum(rect_costvalue),0) as rect_val   
from trnfu_receipt_header,trnfu_receipt_trailer   
where rech_seqno = rect_hdseqno and rech_compcode = compcode 
and rech_fincode = finid and rech_date >= fromdate and rech_date <= todate  
group by rech_compcode,rech_fincode,rect_item_code) re on
  d.itmt_hdcode = re.rect_item_code
   left outer join
(select rerh_compcode,rert_itemcode,ifnull(sum(rert_qty),0) as recret_qty,
ifnull(sum(rert_totitemvalue),0) as recret_val  
from trnfu_receiptret_header,trnfu_receiptret_trailer   
where rerh_seqno = rert_hdseqno and rerh_compcode = compcode 
and rerh_fincode = finid and rerh_date >= fromdate and rerh_date <= todate  
group by rerh_compcode,rerh_fincode,rert_itemcode) rr on
  d.itmt_hdcode = rr.rert_itemcode
   left outer join
(select issh_compcode,isst_itmcode ,ifnull(sum(isst_qty),0) as is_qty,
ifnull(sum(isst_values),0) as is_value   
from trnfu_issue_header ,trnfu_issue_trailer   
where issh_seqno = isst_hdseqno and issh_compcode = compcode 
and issh_fincode = finid and issh_date >= fromdate and issh_date <= todate  
group by issh_compcode,isst_itmcode) iss on
d.itmt_hdcode = iss.isst_itmcode  
   left outer join
(select isrh_compcode,isrt_itemcode ,ifnull(sum(isrt_qty),0) as ir_qty,
ifnull(sum(isrt_values),0) as ir_value   
from trnfu_issret_header ,trnfu_issret_trailer   
where isrh_seqno = isrt_hdseqno and isrh_compcode = compcode 
and isrh_fincode = finid and isrh_date >= fromdate and isrh_date <= todate  
group by isrh_compcode,isrt_itemcode) isr on
	d.itmt_hdcode = isr.isrt_itemcode 
   left outer join
(select salh_compcode,salt_itemcode,ifnull(sum(salt_qty),0) as sale_qty,
ifnull(sum(salt_value),0) as sale_value  
from trnfu_salenote_header, trnfu_salenote_trailer  
where salh_seqno = salt_hdseqno and salh_compcode = compcode 
and salh_fincode = finid and salh_date >= fromdate and salh_date <= todate  
group by salh_compcode,salt_itemcode) sale on
	d.itmt_hdcode = sale.salt_itemcode
   inner join
masfu_item_header c on c.itmh_code = d.itmt_hdcode
   inner join mas_company e  
where   
d.itmt_compcode = compcode and  
d.itmt_fincode = finid and  
e.company_code = compcode 
) a1 group by grp_name
)abc;
*/
END ;;
