/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`%` PROCEDURE `spst_rep_stock_itemwiseAll`(compcode int,finid int,fromdate date,todate date)
BEGIN
select  item_code, item_name , uom_short_name,
sum(item_yr_opqty) + sum(op_rec_qty) - sum(op_ret_rec_qty)-sum(op_adjm_qty)-sum(op_iss_qty) + sum(op_ret_iss_qty) + sum(op_adjp_qty) as closingstock,
sum(item_yr_opval) + sum(op_rec_val) - sum(op_ret_rec_val)-sum(op_adjm_val)-sum(op_iss_val) + sum(op_ret_iss_val) + sum(op_adjp_val) as closingvalue
from (
SELECT
maspur_item_trailer.item_comp_code, maspur_item_trailer.item_yr_opqty, maspur_item_trailer.item_yr_opval, maspur_item_trailer.item_fin_code,
    tmp_pur_op_value.item_code, tmp_pur_op_value.op_rec_qty, tmp_pur_op_value.op_rec_val, tmp_pur_op_value.op_ret_rec_qty, tmp_pur_op_value.op_ret_rec_val, tmp_pur_op_value.op_adjm_qty, tmp_pur_op_value.op_adjm_val, tmp_pur_op_value.op_iss_qty, tmp_pur_op_value.op_iss_val, tmp_pur_op_value.op_ret_iss_qty, tmp_pur_op_value.op_ret_iss_val, tmp_pur_op_value.op_adjp_qty, tmp_pur_op_value.op_adjp_val,
    mas_company.company_name,
    maspur_item_header.item_name,
    maspur_location.loc_name,
    mas_uom.uom_short_name,
    maspur_subgroup.subgrp_name,
	maspur_group.grp_name ,maspur_group.grp_code ,maspur_subgroup.subgrp_code
FROM
    { oj ((((((maspur_item_trailer maspur_item_trailer INNER JOIN mas_company mas_company ON
        maspur_item_trailer.item_comp_code = mas_company.company_code)
     INNER JOIN maspur_item_header maspur_item_header ON
        maspur_item_trailer.item_code = maspur_item_header.item_code)
     INNER JOIN maspur_location maspur_location ON
        maspur_item_trailer.item_loc_code = maspur_location.loc_code)
     INNER JOIN tmp_pur_op_value tmp_pur_op_value ON
        maspur_item_trailer.item_code = tmp_pur_op_value.item_code)
     INNER JOIN maspur_subgroup maspur_subgroup ON
        maspur_item_header.item_group_code = maspur_subgroup.subgrp_code)
     INNER JOIN maspur_group maspur_group ON
        maspur_group.grp_code = maspur_subgroup.subgrp_grpcode)           
     INNER JOIN mas_uom mas_uom ON
        maspur_item_header.item_uom = mas_uom.uom_code}
WHERE
    maspur_item_trailer.item_comp_code = compcode AND
    maspur_item_trailer.item_fin_code = finid AND
    tmp_pur_op_value.item_code > 0 
) a1 group by item_code, item_name ,uom_short_name having sum(item_yr_opval) + sum(op_rec_val) - sum(op_ret_rec_val)-sum(op_adjm_val)-sum(op_iss_val) + sum(op_ret_iss_val) + sum(op_adjp_val) > 0 order by item_name   ;
END ;;
DELIMITER ;
