CREATE DEFINER=`root`@`%` PROCEDURE `spst_rep_stock_item_Month_Abstract`(compcode int,finid int,itemcode int)
BEGIN
select item_code,rmonth, repyear ,repmon,sum(rec_qty) rec_qty, round(sum(rec_val),2) rec_val, sum(iss_qty) iss_qty , round(sum(iss_val),2) iss_val , sum(yropqty) yropqty,sum(yropval) yropval  from

(
select ih.item_code, '' as rmonth , 0 repyear ,0 repmon , 0 rec_qty  ,0  rec_val , 0 as iss_qty, 0 as iss_val , item_yr_opqty yropqty,item_yr_opval yropval   from maspur_item_header ih,  maspur_item_trailer it where ih.item_code = it.item_code and it.item_comp_code = compcode and item_fin_code = finid and ih.item_code = itemcode
union all
select mint_item_code item_code, UPPER(monthname(mint_mindate)) as rmonth , year(mint_mindate) repyear ,month (mint_mindate) repmon , sum(mint_rcvd_qty)  rec_qty  ,sum(mint_value)   rec_val , 0 as iss_qty, 0 as iss_val , 0 yropqty,0 yropval     
from trnpur_min_trailer where mint_comp_code = compcode and   mint_item_code = itemcode AND mint_fin_code = finid group by mint_item_code , UPPER(monthname(mint_mindate))  , year(mint_mindate) ,month (mint_mindate) 

union all
select debt_item_code item_code, UPPER(monthname(debt_date)) as rmonth ,   year(debt_date) repyear ,month (debt_date) repmon , sum(debt_qty)*-1 rec_qty , sum(debt_item_value) *-1 rec_val  ,0  iss_qty, 0 iss_val , 0 yropqty,0 yropval from  trnpur_grn_ret_trailer   where       
debt_comp_code = compcode and  debt_item_code =itemcode  and debt_fin_code = finid  group by debt_item_code , UPPER(monthname(debt_date)), year(debt_date) ,month (debt_date) 

union all
select  iss_item_code item_code, UPPER(monthname(iss_date)) as rmonth , year(iss_date) repyear ,month (iss_date) repmon ,  0 rec_qty , 0 rec_val ,
sum(iss_qty) iss_qty  ,sum((iss_qty * iss_rate) )  iss_val , 0 yropqty,0 yropval  from trnpur_item_issues  
where  iss_comp_code = compcode and  iss_fin_code  = finid and iss_type in ('IS','AM')  AND iss_item_code =itemcode
group by iss_item_code , UPPER(monthname(iss_date)), year(iss_date)  ,month (iss_date) 

union all
select  iss_item_code item_code, UPPER(monthname(iss_date)) as rmonth , year(iss_date) repyear ,month (iss_date) repmon ,   sum(iss_qty) rec_qty , sum((iss_qty * iss_rate) )  rec_val ,
0 iss_qty  ,0 iss_val , 0 yropqty,0 yropval  from trnpur_item_issues  
where  iss_comp_code = compcode and  iss_fin_code  = finid and iss_type in ('IR','AP')  AND iss_item_code =itemcode
group by iss_item_code , UPPER(monthname(iss_date))  , year(iss_date)  ,month (iss_date) 
) a1 group by item_code,rmonth, repyear ,repmon order by repyear asc,repmon asc;
END ;;
DELIMITER ;
