CREATE DEFINER=`root`@`%` PROCEDURE `spst_rep_stock_subgrp`(compcode int,finid int,fromdate date,todate date,grpcode int)
BEGIN

   select  subgrp_code, subgrp_name , sum(op_qty) as op_qty , 
