CREATE DEFINER=`root`@`%` PROCEDURE `spst_rep_stock_subgrp_item`(compcode int,finid int,fromdate date,todate date,grpcode int)
BEGIN
   select  grp_code, grp_name ,subgrp_code, subgrp_name,item_name,mas.item_code,  uom_short_name,
   sum(op_qty) + sum(rec_qty)  - sum(iss_qty)  as closingstock,
	sum(op_value) + sum(rec_val)  - sum(iss_val)  as closingvalue , sum(item_stock) item_stock , max(item_avg_rate) item_avg_rate
   
   from (
   select item_code , sum(op_qty) as op_qty , sum(op_value) as op_value ,  sum(rec_qty) rec_qty, sum(rec_val) rec_val , sum(iss_qty) iss_qty, sum(iss_val) iss_val  from (
  select op_item_code as item_code , sum(op_qty) as op_qty , sum(op_value) as op_value ,0 as rec_qty,0 as rec_val,0 as iss_qty,0 as iss_val
  from tmp_pur_op_value     group by op_item_code
  union all
  select item_code , 0 as op_qty , 0 as op_value , sum(rec_qty) rec_qty, sum(rec_val) rec_val , sum(iss_qty) iss_qty, sum(iss_val) iss_val  from tmp_pur_store_ledger
  group by item_code
  ) a1 group by item_code ) a2
     join maspur_item_header mas on a2.item_code = mas.item_code 
     join maspur_item_trailer trailer on a2.item_code = trailer.item_code and item_comp_code = compcode and item_fin_code = finid
   join maspur_subgroup subgrp on mas.item_group_code =  subgrp.subgrp_code
      join maspur_group maingrp on maingrp.grp_code = subgrp.subgrp_grpcode
   join mas_uom mas_uom on mas.item_uom = mas_uom.uom_code
   where op_value+rec_val-iss_val > 0 and maingrp.grp_code  = grpcode group by grp_code, grp_name ,subgrp_code, subgrp_name,item_name,mas.item_code order by item_name;
   
/*
