    maspur_item_trailer.item_comp_code, maspur_item_trailer.item_yr_opqty, maspur_item_trailer.item_yr_opval, maspur_item_trailer.item_fin_code,
    tmp_pur_op_value.op_item_code, 0 op_rec_qty, 0 op_rec_val, 0 op_ret_rec_qty, 0 op_ret_rec_val, 0 op_adjm_qty, 0 op_adjm_val, 0 op_iss_qty, 0 op_iss_val, 0 op_ret_iss_qty, 0 op_ret_iss_val, 0 op_adjp_qty, 0 op_adjp_val,
    mas_company.company_name,
    maspur_item_header.item_name,
    maspur_location.loc_name,
    mas_uom.uom_short_name,
    maspur_subgroup.subgrp_name,
	maspur_group.grp_name ,maspur_group.grp_code ,maspur_subgroup.subgrp_code, item_stock,item_avg_rate
FROM
    { oj ((((((maspur_item_trailer maspur_item_trailer INNER JOIN mas_company mas_company ON
        maspur_item_trailer.item_comp_code = mas_company.company_code)
     INNER JOIN maspur_item_header maspur_item_header ON
        maspur_item_trailer.item_code = maspur_item_header.item_code)
     INNER JOIN maspur_location maspur_location ON
        maspur_item_header.item_loc_code = maspur_location.loc_code)
     INNER JOIN tmp_pur_op_value tmp_pur_op_value ON
        maspur_item_trailer.item_code = tmp_pur_op_value.op_item_code)
     INNER JOIN maspur_subgroup maspur_subgroup ON
        maspur_item_header.item_group_code = maspur_subgroup.subgrp_code)
     INNER JOIN maspur_group maspur_group ON
        maspur_group.grp_code = maspur_subgroup.subgrp_grpcode)           
     INNER JOIN mas_uom mas_uom ON
        maspur_item_header.item_uom = mas_uom.uom_code}
WHERE
    maspur_item_trailer.item_comp_code = compcode AND
    maspur_item_trailer.item_fin_code = finid AND
    tmp_pur_op_value.op_item_code > 0 and maspur_group.grp_code = grpcode
) a1 group by grp_code, grp_name ,subgrp_code, subgrp_name,op_item_code, item_name ,uom_short_name having sum(item_yr_opval) + sum(op_rec_val) - sum(op_ret_rec_val)-sum(op_adjm_val)-sum(op_iss_val) + sum(op_ret_iss_val) + sum(op_adjp_val) > 0 order by  grp_name ,subgrp_name   ;

