/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`%` PROCEDURE `spst_rep_stores_stock_groupsummary`(compcode int, finid int)
BEGIN
select grp_name, grp_code,op_qty,  case when op_value > 0 then op_value / op_qty else 0 end op_rate, op_value, 
rec_qty , case when rec_val >0 then  rec_val /rec_qty else 0 end rec_rate, rec_val, 
iss_qty , case when iss_val >0 then  iss_val /iss_qty else 0 end iss_rate, iss_val, 
clo_qty , case when clo_val >0 then  clo_val /clo_qty else 0 end clo_rate, clo_val  from

(
SELECT

	maspur_group.grp_name, grp_code,
    sum(maspur_item_trailer.item_yr_opqty)+sum(tmp_pur_op_value.op_rec_qty) - sum(tmp_pur_op_value.op_ret_rec_qty) - sum(tmp_pur_op_value.op_adjm_qty) -   sum(tmp_pur_op_value.op_iss_qty) + sum(tmp_pur_op_value.op_ret_iss_qty) + sum(tmp_pur_op_value.op_adjp_qty) as op_qty ,
    sum(maspur_item_trailer.item_yr_opval)+sum(tmp_pur_op_value.op_rec_val) - sum(tmp_pur_op_value.op_ret_rec_val) - sum(tmp_pur_op_value.op_adjm_val) -   sum(tmp_pur_op_value.op_iss_val) + sum(tmp_pur_op_value.op_ret_iss_val) + sum(tmp_pur_op_value.op_adjp_val) as op_value,  
    sum(tmp_pur_store_ledger.rec_qty) rec_qty  , sum(tmp_pur_store_ledger.rec_val) rec_val, 
    sum(tmp_pur_store_ledger.iss_qty) iss_qty , sum(tmp_pur_store_ledger.iss_val) iss_val,
    sum(maspur_item_trailer.item_yr_opqty)+sum(tmp_pur_op_value.op_rec_qty) - sum(tmp_pur_op_value.op_ret_rec_qty) - sum(tmp_pur_op_value.op_adjm_qty) -   sum(tmp_pur_op_value.op_iss_qty) + sum(tmp_pur_op_value.op_ret_iss_qty) + sum(tmp_pur_op_value.op_adjp_qty)+ sum(tmp_pur_store_ledger.rec_qty) - sum(tmp_pur_store_ledger.iss_qty)   as clo_qty ,    
    sum(maspur_item_trailer.item_yr_opval)+sum(tmp_pur_op_value.op_rec_val) - sum(tmp_pur_op_value.op_ret_rec_val) - sum(tmp_pur_op_value.op_adjm_val) -   sum(tmp_pur_op_value.op_iss_val) + sum(tmp_pur_op_value.op_ret_iss_val) + sum(tmp_pur_op_value.op_adjp_val) + sum(tmp_pur_store_ledger.rec_val) - sum(tmp_pur_store_ledger.iss_val)  as clo_val  
FROM
    { oj (((((((tmp_pur_store_ledger tmp_pur_store_ledger LEFT OUTER JOIN mas_cost_center mas_cost_center ON
        tmp_pur_store_ledger.iss_party = mas_cost_center.cost_code)
     INNER JOIN tmp_pur_op_value tmp_pur_op_value ON
        tmp_pur_store_ledger.item_code = tmp_pur_op_value.item_code)
     LEFT OUTER JOIN maspur_supplier_master maspur_supplier_master ON
        tmp_pur_store_ledger.party = maspur_supplier_master.sup_code)
     INNER JOIN maspur_item_trailer maspur_item_trailer ON
        tmp_pur_op_value.item_code = maspur_item_trailer.item_code)
     INNER JOIN maspur_item_header maspur_item_header ON
        tmp_pur_op_value.item_code = maspur_item_header.item_code)
     INNER JOIN maspur_subgroup maspur_subgroup ON
        maspur_item_header.item_group_code = maspur_subgroup.subgrp_code)
     INNER JOIN maspur_group maspur_group ON
        maspur_group.grp_code = maspur_subgroup.subgrp_grpcode)     
        
     INNER JOIN mas_uom mas_uom ON
        maspur_item_header.item_uom = mas_uom.uom_code}
WHERE
    maspur_item_trailer.item_comp_code = compcode AND
    maspur_item_trailer.item_fin_code = finid AND
    tmp_pur_op_value.item_code > 0
    group by maspur_group.grp_name,maspur_group.grp_code
) a1    
    
ORDER BY
    grp_name ASC;    
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
