CREATE DEFINER=`root`@`%` PROCEDURE `spst_rep_stores_stock_SUBgroupsummary`(compcode int, finid int ,maingrpcode int, allitems int )
BEGIN
if allitems = 0 then
   select  subgrp_name,subgrp_code ,sum(op_qty) as op_qty , 
    case when  sum(op_value)  != 0 then round(sum(op_value) / sum(op_qty),2)  else 0 end as op_rate, 
    round(sum(op_value),2) as op_value ,  
   sum(rec_qty) rec_qty, 
   case when  sum(rec_val)  != 0 then round(sum(rec_val) / sum(rec_qty),2)  else 0 end as rec_rate, 
   round(sum(rec_val),2) rec_val , 
   sum(iss_qty) iss_qty, 
    case when  sum(iss_val)  != 0 then round(sum(iss_val) / sum(iss_qty),2)  else 0 end as iss_rate, 
   round(sum(iss_val),2) iss_val,  
   sum(op_qty) + sum(rec_qty)  - sum(iss_qty)  as clo_qty,
   case when  (sum(op_value) + sum(rec_val) - sum(iss_val))  > 0 then round( (sum(op_value) + sum(rec_val)  - sum(iss_val) )/ (sum(op_qty) + sum(rec_qty)  - sum(iss_qty) ),2)  else 0 end as clo_rate, 
   round(sum(op_value) + sum(rec_val)  - sum(iss_val),2)  as clo_val
   
   from (
   select item_code , sum(op_qty) as op_qty , sum(op_value) as op_value ,  sum(rec_qty) rec_qty, sum(rec_val) rec_val , sum(iss_qty) iss_qty, sum(iss_val) iss_val  from (
  select op_item_code as item_code , sum(op_qty) as op_qty , sum(op_value) as op_value ,0 as rec_qty,0 as rec_val,0 as iss_qty,0 as iss_val
  from tmp_pur_op_value     group by op_item_code
  union all
  select item_code , 0 as op_qty , 0 as op_value , sum(rec_qty) rec_qty, sum(rec_val) rec_val , sum(iss_qty) iss_qty, sum(iss_val) iss_val  from tmp_pur_store_ledger
  group by item_code
  ) a1 group by item_code ) a2
     join maspur_item_header mas on a2.item_code = mas.item_code 
   join maspur_subgroup subgrp on mas.item_group_code =  subgrp.subgrp_code
   join maspur_group maingrp on maingrp.grp_code =  subgrp.subgrp_grpcode
   where (op_value > 0 or rec_val != 0 or  iss_val != 0) and grp_code = maingrpcode group by subgrp_name,subgrp_code;
   
   
else
   
   select  subgrp_name,subgrp_code ,mas.item_name,mas.item_code ,sum(op_qty) as op_qty , 
    case when  sum(op_value)   != 0 then round(sum(op_value) / sum(op_qty),2)  else 0 end as op_rate, 
    round(sum(op_value),2) as op_value ,  
   sum(rec_qty) rec_qty, 
   case when  sum(rec_val)   != 0 then round(sum(rec_val) / sum(rec_qty),2)  else 0 end as rec_rate, 
   round(sum(rec_val),2) rec_val , 
   sum(iss_qty) iss_qty, 
    case when  sum(iss_val)   != 0 then round(sum(iss_val) / sum(iss_qty),2)  else 0 end as iss_rate, 
   round(sum(iss_val),2) iss_val,  
   sum(op_qty) + sum(rec_qty)  - sum(iss_qty)  as clo_qty,
   case when  (sum(op_value) + sum(rec_val) - sum(iss_val))  > 0 then round( (sum(op_value) + sum(rec_val)  - sum(iss_val) )/ (sum(op_qty) + sum(rec_qty)  - sum(iss_qty) ),2)  else 0 end as clo_rate, 
   round(sum(op_value) + sum(rec_val)  - sum(iss_val),2)  as clo_val
   
   from (
   select item_code , sum(op_qty) as op_qty , sum(op_value) as op_value ,  sum(rec_qty) rec_qty, sum(rec_val) rec_val , sum(iss_qty) iss_qty, sum(iss_val) iss_val  from (
  select op_item_code as item_code , sum(op_qty) as op_qty , sum(op_value) as op_value ,0 as rec_qty,0 as rec_val,0 as iss_qty,0 as iss_val
  from tmp_pur_op_value     group by op_item_code
  union all
  select item_code , 0 as op_qty , 0 as op_value , sum(rec_qty) rec_qty, sum(rec_val) rec_val , sum(iss_qty) iss_qty, sum(iss_val) iss_val  from tmp_pur_store_ledger
  group by item_code
  ) a1 group by item_code ) a2
     join maspur_item_header mas on a2.item_code = mas.item_code 
   join maspur_subgroup subgrp on mas.item_group_code =  subgrp.subgrp_code
   join maspur_group maingrp on maingrp.grp_code =  subgrp.subgrp_grpcode
   where (op_value > 0 or rec_val != 0 or  iss_val  != 0) and grp_code = maingrpcode group by subgrp_name,subgrp_code,mas.item_name,mas.item_code;   
end if;
/*
if allitems = 0 then
select subgrp_name,subgrp_code,op_qty,  case when op_value > 0 then op_value / op_qty else 0 end op_rate, op_value, 
rec_qty , case when rec_val >0 then  rec_val /rec_qty else 0 end rec_rate, rec_val, 
iss_qty , case when iss_val >0 then  iss_val /iss_qty else 0 end iss_rate, iss_val, 
