CREATE DEFINER=`root`@`%` PROCEDURE `sp_ins_weightcard`(
 p_wc_seqno  int,  
 p_wc_compcode int,  
 p_wc_fincode  int,  
 p_wc_no  int,  
 p_wc_date  datetime(3),  
 p_wc_unloading datetime,  
 p_wc_area_code smallint,  
 p_wc_sup_code  int,  
 p_wc_itemgrp  smallint,  
 p_wc_supervisor  int,  
