 p_wc_grosswt  numeric(10,1),  
 p_wc_tarewt  numeric(10,1),  
 p_wc_netwt  numeric(10,1),  
 p_wc_status  varchar(1),  
 p_wc_usr_code  int,  
 p_wc_entry_date datetime(3))
BEGIN   
insert into trn_weightcard(wc_seqno,wc_compcode,wc_fincode,wc_no,wc_date,wc_unloadingtime,wc_area_code,
wc_sup_code,wc_itemgrp,wc_supervisor,wc_vehicleno,wc_transportname, wc_wb_no ,wc_grosswt,  wc_tarewt,
wc_netwt,wc_status,wc_usr_code,wc_entry_date)   
values(p_wc_seqno,p_wc_compcode,p_wc_fincode,p_wc_no,p_wc_date,p_wc_unloading,p_wc_area_code,
p_wc_sup_code,p_wc_itemgrp,p_wc_supervisor,p_wc_vehicleno,p_wc_transportname, 
p_wc_wb_no ,p_wc_grosswt , p_wc_tarewt,p_wc_netwt,p_wc_status,p_wc_usr_code,p_wc_entry_date);  


END ;;
