CREATE DEFINER=`root`@`%` PROCEDURE `sp_pur_issue_details`(company_code numeric ,              
finyear_code numeric ,              
issue_no numeric ,              
issue_type varchar(2) )
BEGIN
select               
iss_date,              
iss_dept_code,             
iss_machine,      
iss_item_code,              
uom_short_name,  
item_name,            
item_stock ,              
item_avg_rate,              
iss_qty,              
iss_rate,  iss_value,                     
iss_section,      
iss_equip,      
section_name,      
equip_name,
iss_slno , iss_vou_refno         
from              
 trnpur_item_issues ,               
 maspur_item_header h,              
 maspur_item_trailer t,              
 mas_section b1,      
 mas_equipment b2,            
 mas_uom           
where               
 iss_comp_code = company_code and              
 iss_fin_code = finyear_code and              
 iss_no = issue_no and              
 iss_type = issue_type and              
 iss_item_code = h.item_code and              
 h.item_code = t.item_code and              
 t.item_comp_code = iss_comp_code and              
 t.item_fin_code = iss_fin_code and              
 iss_section = b1.section_code and       
 iss_equip = b2.equip_code and       
 item_uom = uom_code  
order by iss_slno;            
END ;;
DELIMITER ;
