/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`%` PROCEDURE `sp_pur_rep_item_storeledger`(compcode int, finid int,itemcode int)
BEGIN
SELECT
    grp_name, doctype,t.type, t.doc_no,t.doc_date,  DATE_FORMAT( t.doc_date, '%d-%m-%Y')  doc_date2, t.rec_qty, t.rec_val, t.iss_qty, t.iss_val, t.iss_cr_status,
    case when t.type = 'RE' then  mc.cust_name else 
    case when t.type = 'AP' then  'Adjustment Plus' else 
    case when t.type = 'AM' then  'Adjustment Minus' else 
    case when t.type = 'IS' then  'Issues' else 
    case when t.type = 'IR' then  'Issue Return' else   mc.cust_name  end end end end end as cust_name,      
    mi.item_code, mi.item_name,    
    mas_uom.uom_short_name , op_qty, op_value,
	round((t.rec_val + t.iss_val) / (t.rec_qty+t.iss_qty),2) as item_avg_rate  -- ,0 as itemstkval
   from  tmp_pur_store_ledger t left join  tmp_pur_op_value op
   on t.item_code = op_item_code
   join massal_customer mc on mc.cust_code = t.party
   join maspur_item_header mi on mi.item_code = t.item_code 
   join mas_uom mas_uom on mi.item_uom = mas_uom.uom_code
   join maspur_subgroup subgrp on mi.item_group_code =  subgrp.subgrp_code
   join maspur_group maingrp on maingrp.grp_code =  subgrp.subgrp_grpcode
   where t.item_code = itemcode order by doc_date,doctype,type;
/*

SELECT
    tmp_pur_store_ledger.type, tmp_pur_store_ledger.doc_no, tmp_pur_store_ledger.doc_date, tmp_pur_store_ledger.rec_qty, tmp_pur_store_ledger.rec_val, tmp_pur_store_ledger.iss_qty, tmp_pur_store_ledger.iss_val, tmp_pur_store_ledger.iss_cr_status,
    case when tmp_pur_store_ledger.type = 'RE' then  massal_customer.cust_name else 
    case when tmp_pur_store_ledger.type = 'AP' then  'Adjustment Plus' else 
    case when tmp_pur_store_ledger.type = 'AM' then  'Adjustment Minus' else 
    case when tmp_pur_store_ledger.type = 'IS' then  'Issues' else 
    case when tmp_pur_store_ledger.type = 'IR' then  'Issue Return' else   massal_customer.cust_name  end end end end end as cust_name,      
    maspur_item_header.item_code, maspur_item_header.item_name,
    maspur_item_trailer.item_comp_code, maspur_item_trailer.item_avg_rate, maspur_item_trailer.item_stock, maspur_item_trailer.item_yr_opqty, maspur_item_trailer.item_yr_opval, maspur_item_trailer.item_fin_code,
    mas_uom.uom_short_name,
    maspur_subgroup.subgrp_name  ,
	maspur_group.grp_name 
FROM
    { oj ((((((tmp_pur_store_ledger tmp_pur_store_ledger 
     INNER JOIN tmp_pur_op_value tmp_pur_op_value ON
        tmp_pur_store_ledger.item_code = tmp_pur_op_value.op_item_code)
     LEFT OUTER JOIN massal_customer massal_customer ON
        tmp_pur_store_ledger.party = massal_customer.cust_code)
     INNER JOIN maspur_item_trailer maspur_item_trailer ON
        tmp_pur_op_value.op_item_code = maspur_item_trailer.item_code)
     INNER JOIN maspur_item_header maspur_item_header ON
        tmp_pur_op_value.op_item_code = maspur_item_header.item_code)
     INNER JOIN maspur_subgroup maspur_subgroup ON
        maspur_item_header.item_group_code = maspur_subgroup.subgrp_code)
     INNER JOIN maspur_group maspur_group ON
        maspur_group.grp_code = maspur_subgroup.subgrp_grpcode)     
        
     INNER JOIN mas_uom mas_uom ON
        maspur_item_header.item_uom = mas_uom.uom_code}
WHERE
    maspur_item_trailer.item_comp_code = compcode AND
    maspur_item_trailer.item_fin_code = finid AND
	maspur_item_trailer.item_code = itemcode AND
    tmp_pur_op_value.op_item_code > 0;
    

---------------------------------------------
SELECT
    tmp_pur_store_ledger.type, tmp_pur_store_ledger.doc_no, tmp_pur_store_ledger.doc_date, tmp_pur_store_ledger.rec_qty, tmp_pur_store_ledger.rec_val, tmp_pur_store_ledger.iss_qty, tmp_pur_store_ledger.iss_val, tmp_pur_store_ledger.iss_cr_status,
    case when tmp_pur_store_ledger.type = 'RE' then  massal_customer.cust_name else 
    case when tmp_pur_store_ledger.type = 'AP' then  'Adjustment Plus' else 
    case when tmp_pur_store_ledger.type = 'AM' then  'Adjustment Minus' else 
    case when tmp_pur_store_ledger.type = 'IS' then  'Issues' else 
    case when tmp_pur_store_ledger.type = 'IR' then  'Issue Return' else   massal_customer.cust_name  end end end end end as cust_name,      
    tmp_pur_op_value.item_code, tmp_pur_op_value.op_rec_qty, tmp_pur_op_value.op_rec_val, tmp_pur_op_value.op_ret_rec_qty, tmp_pur_op_value.op_ret_rec_val, tmp_pur_op_value.op_adjm_qty, tmp_pur_op_value.op_adjm_val, tmp_pur_op_value.op_iss_qty, tmp_pur_op_value.op_iss_val, tmp_pur_op_value.op_ret_iss_qty, tmp_pur_op_value.op_ret_iss_val, tmp_pur_op_value.op_adjp_qty, tmp_pur_op_value.op_adjp_val,
    maspur_item_header.item_code, maspur_item_header.item_name,
    maspur_item_trailer.item_comp_code, maspur_item_trailer.item_avg_rate, maspur_item_trailer.item_stock, maspur_item_trailer.item_yr_opqty, maspur_item_trailer.item_yr_opval, maspur_item_trailer.item_fin_code,
    mas_uom.uom_short_name,
    maspur_subgroup.subgrp_name  ,
	maspur_group.grp_name 
FROM
    { oj ((((((tmp_pur_store_ledger tmp_pur_store_ledger 
     INNER JOIN tmp_pur_op_value tmp_pur_op_value ON
        tmp_pur_store_ledger.item_code = tmp_pur_op_value.item_code)
     LEFT OUTER JOIN massal_customer massal_customer ON
        tmp_pur_store_ledger.party = massal_customer.cust_code)
     INNER JOIN maspur_item_trailer maspur_item_trailer ON
        tmp_pur_op_value.item_code = maspur_item_trailer.item_code)
     INNER JOIN maspur_item_header maspur_item_header ON
        tmp_pur_op_value.item_code = maspur_item_header.item_code)
     INNER JOIN maspur_subgroup maspur_subgroup ON
        maspur_item_header.item_group_code = maspur_subgroup.subgrp_code)
     INNER JOIN maspur_group maspur_group ON
        maspur_group.grp_code = maspur_subgroup.subgrp_grpcode)     
        
     INNER JOIN mas_uom mas_uom ON
        maspur_item_header.item_uom = mas_uom.uom_code}
WHERE
    maspur_item_trailer.item_comp_code = compcode AND
    maspur_item_trailer.item_fin_code = finid AND
	maspur_item_trailer.item_code = itemcode AND
    tmp_pur_op_value.item_code > 0
ORDER BY
    maspur_group.grp_name ASC,
    maspur_subgroup.subgrp_name  ASC,
    maspur_item_header.item_code ASC,
    tmp_pur_store_ledger.doc_date ASC;
*/    
END ;;
DELIMITER ;
