CREATE DEFINER=`root`@`%` PROCEDURE `sp_pur_rep_storeledger_item`(p_company_code tinyint ,fincode tinyint , chkitemcode int, 
p_from_date date ,  
p_to_date date)
BEGIN

select b1.*,c1.*,mas.* ,mh.item_name from (
select item_comp_code, op_itemcode, sum(opqty) opqty , round(sum(opval),2) opvalue ,  case when sum(opval) > 0 then round(sum(opval) / sum(opqty),5) else 0 end oprate from (
select p_company_code item_comp_code , chkitemcode op_itemcode,  0 opqty, 0 opval 
union all
select item_comp_code , item_code op_itemcode,  item_yr_opqty opqty, item_yr_opval opval from maspur_item_trailer where
 item_comp_code = p_company_code and item_fin_code = fincode  AND item_code = chkitemcode
union all
select    mint_comp_code item_comp_code ,       
mint_item_code op_itemcode ,     
sum(mint_rcvd_qty)  opqty  ,sum(mint_value)   opval      
from trnpur_min_trailer where mint_comp_code = p_company_code  and   mint_mindate < p_from_date and mint_item_code = chkitemcode AND 
mint_fin_code = fincode  group by mint_comp_code , mint_item_code   

union all

select       
a.debt_comp_code item_comp_code ,       
a.debt_item_code op_itemcode,      
sum(a.debt_qty)  * -1 opqty,sum(a.debt_item_value) * -1 opval      
from  trnpur_grn_ret_trailer a  where       
a.debt_comp_code = p_company_code and  a.debt_date < p_from_date AND debt_item_code =chkitemcode  and 
a.debt_fin_code = fincode group by  a.debt_comp_code , a.debt_item_code       

union all

 select   
   iss_comp_code item_comp_code ,iss_item_code op_itemcode,
   sum(iss_qty) opqty  ,sum((iss_qty * iss_rate) )   opval    
   from   
   trnpur_item_issues  
   where  
   iss_comp_code = p_company_code and 
    iss_fin_code  = fincode and 
   iss_date < p_from_date   and
   iss_type in ('IR','AP') AND iss_item_code =chkitemcode
   group by iss_comp_code,iss_type,iss_no,iss_date,iss_equip,iss_item_code,iss_cr_status,iss_qty,iss_rate
  union all
  
  select   
   iss_comp_code item_comp_code ,iss_item_code op_itemcode,
   sum(iss_qty)*-1 opqty  ,sum((iss_qty * iss_rate) ) * -1  opval    
   from   
   trnpur_item_issues  
   where  
   iss_comp_code = p_company_code and  
   iss_fin_code  = fincode and 
   iss_date < p_from_date   and
   iss_type in ('IS','AM')  AND iss_item_code =chkitemcode
   group by iss_comp_code,iss_type,iss_no,iss_date,iss_equip,iss_item_code,iss_cr_status,iss_qty,iss_rate
) a1 group by item_comp_code, op_itemcode  
)b1
 join

(select   mint_comp_code compcode,minh_type as voutype,'RE' as doctype,mint_minno docno ,mint_mindate docdate,
mint_sup_code supcode ,mint_item_code item_code,
mint_rcvd_qty rec_qty,mint_value rec_val ,
0 as iss_qty,0 as iss_val,1 as sl_no,mint_unit_rate unitrate 
from   trnpur_min_trailer  , trnpur_min_header  where  minh_comp_code =  mint_comp_code and minh_fin_code = mint_fin_code and 
minh_minno = mint_minno and mint_comp_code = p_company_code and minh_fin_code = fincode  and  mint_mindate >= p_from_date and  mint_mindate <= p_to_date   and mint_item_code = chkitemcode 


union all
select   debt_comp_code compcode,'RR' as voutype,'RR' as doctype,debt_no docno,debt_date docdate,debh_supcode supcode,debt_item_code item_code,debt_qty*-1 as rec_qty,debt_item_value *-1 as 
rec_val,0 iss_qty,0 iss_val,2 as sl_no,debt_unit_rate unitrate
from   trnpur_grn_ret_header, trnpur_grn_ret_trailer where debh_comp_code = debt_comp_code  and debh_fin_code = debt_fin_code and debh_no = debt_no and 
debt_comp_code = p_company_code and  debt_date >= p_from_date and  debt_date <= p_to_date and debt_item_code =chkitemcode  

union all
   select   
   iss_comp_code compcode,iss_type voutype ,iss_type doctype ,iss_no docno,iss_date docdate,0 as supcode,iss_item_code item_code,
   case when iss_type in ('IR','AP') then iss_qty else 0 end as  rec_qty,
   case when iss_type in ('IR','AP') then Cast((iss_qty * iss_rate)  as decimal(18,2)) else 0 end as rec_val,
   case when iss_type in ('IS','AM') then iss_qty else 0 end as  iss_qty,
   case when iss_type in ('IS','AM') then Cast((iss_qty * iss_rate)  as decimal(18,2))  else 0 end as  iss_val,
   case when iss_type in ('IS','AM') then 3 else 4 end as  sl_no,iss_rate unitrate 
   from      trnpur_item_issues     where     iss_comp_code = p_company_code and     iss_date >= p_from_date and     iss_date <= p_to_date and  iss_item_code =chkitemcode
   )c1 on  b1.op_itemcode = c1.item_code 
    left join  massal_customer mas on  supcode  = cust_code 
    left join  maspur_item_header mh on mh.item_code = c1.item_code
    order by docdate,sl_no;   
END ;;
DELIMITER ;
