CREATE DEFINER=`root`@`%` PROCEDURE `sp_pur_store_ledger`(  
p_company_code tinyint ,  
p_from_date date ,  
p_to_date date)
BEGIN  
  
 DROP TABLE IF EXISTS tmp_pur_store_ledger;  

CREATE TABLE tmp_pur_store_ledger  
(  
comp_code tinyint ,  
type varchar(2),  
doc_no varchar(15),  
doc_date datetime(3),  
party int,  
item_code int ,  
rec_qty  numeric (18,3) ,  
rec_val  numeric (18,2) ,  
iss_qty  numeric(18,3),  
iss_val  numeric(18,2),  
sl_no int,  
iss_party int,  
iss_cr_status varchar(2) ,
avgrate   numeric(18,5),
doctype varchar(2) 
);  

INSERT INTO tmp_pur_store_ledger   

select   mint_comp_code,'RE' as type,mint_minno,mint_mindate,mint_sup_code,mint_item_code,mint_rcvd_qty,mint_value ,
0 as iss_qty,0 as iss_val,1 as sl_no,0 as iss_party,mint_cr_status ,mint_unit_rate unitrate , minh_type
from   trnpur_min_header , trnpur_min_trailer  where   minh_comp_code = mint_comp_code and minh_fin_code =  mint_fin_code and minh_minno = mint_minno and
mint_comp_code = p_company_code and  mint_mindate >= p_from_date  and  mint_mindate <= p_to_date;
/*
INSERT INTO tmp_pur_store_ledger   
select   
debt_comp_code,'RR' as type,debt_no,debt_date,debh_supcode,debt_item_code,0 as rec_qty,0 as 
rec_val,debt_qty,debt_item_value,2 as sl_no,0 as iss_party,'RR' debt_cr_status  ,debt_unit_rate unitrate
from   
trnpur_grn_ret_header, trnpur_grn_ret_trailer where debh_comp_code = debt_comp_code  and debh_fin_code = debt_fin_code and debh_no = debt_no and 
debt_comp_code = p_company_code and  
debt_date >= p_from_date and  
debt_date <= p_to_date;  
*/

INSERT INTO tmp_pur_store_ledger   
select   
debt_comp_code,'RR' as type,debt_no,debt_date,debh_supcode,debt_item_code,debt_qty*-1,debt_item_value*-1,0,0,2 as sl_no,0 as iss_party,'RR' debt_cr_status  ,debt_unit_rate unitrate ,'RR'
from   
trnpur_grn_ret_header, trnpur_grn_ret_trailer where debh_comp_code = debt_comp_code  and debh_fin_code = debt_fin_code and debh_no = debt_no and 
debt_comp_code = p_company_code and  
debt_date >= p_from_date and  
debt_date <= p_to_date;  

INSERT INTO tmp_pur_store_ledger   
   select   
   iss_comp_code,iss_type,iss_no,iss_date,0 as party,iss_item_code,
   case when iss_type in ('IR','AP') then iss_qty else 0 end as  rec_qty,
   case when iss_type in ('IR','AP') then Cast((iss_qty * iss_rate)  as decimal(18,2)) else 0 end as rec_val,
   case when iss_type in ('IS','AM') then iss_qty else 0 end as  iss_qty,
   case when iss_type in ('IS','AM') then Cast((iss_qty * iss_rate)  as decimal(18,2))  else 0 end as  iss_val,
   case when iss_type in ('IS','AM') then 3 else 4 end as  sl_no,
   iss_equip as iss_cost_code, iss_cr_status  ,iss_rate ,'IS' 
   from   
   trnpur_item_issues  
   where  
   iss_comp_code = p_company_code and  
   iss_date >= p_from_date and  
   iss_date <= p_to_date ;
  SET SQL_SAFE_UPDATES = 0;

  
 update tmp_pur_store_ledger set sl_no = 1 where type = 'RE';  
 update tmp_pur_store_ledger set sl_no = 2 where type = 'IR';   
 update tmp_pur_store_ledger set sl_no = 3 where type = 'AP';  
 update tmp_pur_store_ledger set sl_no = 4 where type = 'IS';  
 update tmp_pur_store_ledger set sl_no = 5 where type = 'DE';  
 update tmp_pur_store_ledger set sl_no = 6 where type = 'AM';  
 
 
   
/*  
 DROP TABLE IF EXISTS tmp_pur_store_ledger_cons;  

CREATE TABLE tmp_pur_store_ledger_cons  
(  
comp_code tinyint ,  
re_cap_val  numeric (18,3) ,  
re_rev_val  numeric (18,3) ,  
rr_cap_val  numeric (18,3) ,  
rr_rev_val  numeric (18,3) ,  
is_cap_val  numeric (18,3) ,  
is_rev_val  numeric (18,3) ,  
is_value numeric (18,3),  
ir_cap_val  numeric (18,3) ,  
ir_rev_val  numeric (18,3) ,  
ir_value numeric (18,3),  
ap_val  numeric (18,3) ,  
am_val  numeric (18,3)   
);  
  
  
INSERT INTO tmp_pur_store_ledger   
select   
mint_comp_code,'RE' as type,mint_minno,mint_mindate,mint_sup_code,mint_item_code,mint_rcvd_qty,mint_value ,
0 as iss_qty,0 as iss_val,0 as sl_no,0 as iss_party,mint_cr_status  
from   
trnpur_min_trailer  
where  
mint_comp_code = p_company_code and  
mint_mindate >= p_from_date and  
mint_mindate <= p_to_date  
group by mint_comp_code,mint_minno,mint_mindate,mint_sup_code,mint_item_code,mint_cr_status,mint_rcvd_qty,
mint_value,mint_ind_no;  
  
INSERT INTO tmp_pur_store_ledger   
select   
reciss_comp_code,reciss_type,reciss_doc_no,reciss_doc_date,reciss_party,reciss_item_code,reciss_item_qty,
(reciss_item_qty * reciss_item_rate) ,0 as iss_qty,0 as iss_val,0 as sl_no,0 as iss_party,' '  
from   
trnpur_item_rec_iss   
where  
reciss_comp_code = p_company_code and  
reciss_type = 'AP'  and  
reciss_doc_date >= p_from_date and  
reciss_doc_date <= p_to_date  
group by reciss_comp_code,reciss_type,reciss_doc_no,reciss_doc_date,reciss_party,reciss_item_code,
reciss_item_qty,reciss_item_rate;  
  
INSERT INTO tmp_pur_store_ledger   
select   
debt_comp_code,'RR' as type,debt_no,debt_date,debh_supcode,debt_item_code,0 as rec_qty,0 as 
rec_val,debt_qty,debt_value,0 as sl_no,0 as iss_party,'RR' debt_cr_status  
from   
trnpur_grn_ret_header, trnpur_grn_ret_trailer where debh_comp_code = debt_comp_code  and debh_fin_code = debt_fin_code and debh_no = debt_no and 
debt_comp_code = p_company_code and  
debt_date >= p_from_date and  
debt_date <= p_to_date  
group by debt_comp_code,debt_no,debt_date,debh_supcode,debt_item_code,debt_qty,
debh_grnno,debt_value,debt_slno;  
  
INSERT INTO tmp_pur_store_ledger   
select   
reciss_comp_code,reciss_type,reciss_doc_no,reciss_doc_date,reciss_party,reciss_item_code,
0 as rec_qty,0 as rec_val,reciss_item_qty,(reciss_item_qty * reciss_item_rate),0 as sl_no,0 as iss_party, ' '  
from   
trnpur_item_rec_iss   
where  
reciss_comp_code = p_company_code and  
reciss_type = 'AM'  and  
reciss_doc_date >= p_from_date and  
reciss_doc_date <= p_to_date  
group by reciss_comp_code,reciss_type,reciss_doc_no,reciss_doc_date,reciss_party,
reciss_item_code,reciss_item_qty,reciss_item_rate;  
  
   INSERT INTO tmp_pur_store_ledger   
   select   
   iss_comp_code,iss_type,iss_no,iss_date,0 as party,iss_item_code,0 as rec_qty,
   0 as rec_val,iss_qty,(iss_qty * iss_rate),0 as sl_no,iss_equip as iss_cost_code,'' iss_cr_status  
   from   
   trnpur_item_issues  
   where  
   iss_comp_code = p_company_code and  
   iss_type = 'IS'  and  
   iss_date >= p_from_date and  
   iss_date <= p_to_date  
   group by iss_comp_code,iss_type,iss_no,iss_date,iss_equip,iss_item_code,iss_cr_status,iss_qty,iss_rate;  


   INSERT INTO tmp_pur_store_ledger   
   select   
   iss_comp_code,iss_type,iss_no,iss_date,0 as party,iss_item_code,iss_qty,(iss_qty * iss_rate),
   0 as iss_qty,0 as iss_val,0 as sl_no,iss_equip as iss_cost_code,iss_cr_status   
   from   
   trnpur_item_issues  
   where  
   iss_comp_code = p_company_code and  
   iss_type = 'IR'  and  
   iss_date >= p_from_date and  
   iss_date <= p_to_date  
   group by iss_comp_code,iss_type,iss_no,iss_date,iss_equip,iss_item_code,
   iss_cr_status,iss_qty,iss_rate;   

   SET SQL_SAFE_UPDATES = 0;

  
 update tmp_pur_store_ledger set sl_no = 1 where type = 'RE';  
 update tmp_pur_store_ledger set sl_no = 2 where type = 'IR';   
 update tmp_pur_store_ledger set sl_no = 3 where type = 'AP';  
 update tmp_pur_store_ledger set sl_no = 4 where type = 'IS';  
