 update tmp_pur_store_ledger set sl_no = 6 where type = 'AM';  
 
 update tmp_pur_store_ledger set type = 'RR' where type = 'DE';  
  
insert into tmp_pur_store_ledger_cons  
select p_company_code, p.re_cap_val , q.re_rev_val , r.rr_cap_val , s.rr_rev_val , 
t.is_cap_val , u.is_rev_val , a.is_value, v.ir_cap_val , w.ir_rev_val, b.ir_value , 
x.ap_val, y.am_val  
from  
(select   
sum(mint_value) 're_cap_val'  
from trnpur_min_trailer  
where mint_comp_code = p_company_code and mint_cr_status = 'C' and mint_mindate >= p_from_date 
and mint_mindate <= p_to_date  
) p ,  
  
(select   
sum(mint_value) 're_rev_val'  
from trnpur_min_trailer  
where mint_comp_code = p_company_code and mint_cr_status = 'R' and mint_mindate >= p_from_date 
and mint_mindate <= p_to_date) q ,  
  
(select   
sum(debt_value) 'rr_cap_val'  
from trnpur_grn_ret_header, trnpur_grn_ret_trailer where debh_comp_code = debt_comp_code  and debh_fin_code = debt_fin_code and debh_no = debt_no and   
debt_comp_code = p_company_code  and debt_date >= p_from_date 
and debt_date <= p_to_date) r,  
  
(select   
sum(0) 'rr_rev_val'  
from trnpur_grn_ret_header, trnpur_grn_ret_trailer where debh_comp_code = debt_comp_code  and debh_fin_code = debt_fin_code and debh_no = debt_no and 
debt_comp_code = p_company_code and debt_date >= p_from_date 
and debt_date <= p_to_date) s,  
  
(select   
sum(iss_qty * iss_rate) 'is_cap_val'  
from trnpur_item_issues  
where iss_comp_code = p_company_code and iss_cr_status = 'C'  and iss_type = 'IS' 
and iss_date >= p_from_date and iss_date <= p_to_date) t,  
  
(select   
sum(iss_qty * iss_rate) 'is_rev_val'  
from trnpur_item_issues  
where iss_comp_code = p_company_code and iss_cr_status = 'R' and iss_type = 'IS' 
and iss_date >= p_from_date and iss_date <= p_to_date) u ,  
  
(select   
sum(iss_qty * iss_rate) 'is_value'  
from trnpur_item_issues  
where iss_comp_code = p_company_code and iss_type = 'IS' and iss_date >= p_from_date 
and iss_date <= p_to_date) a ,  
  
(select   
sum(iss_qty * iss_rate) 'ir_cap_val'  
from trnpur_item_issues  
where iss_comp_code = p_company_code and iss_cr_status = 'C' and iss_type = 'IR' 
and iss_date >= p_from_date and iss_date <= p_to_date) v,  
  
(select   
sum(iss_qty * iss_rate) 'ir_rev_val'  
from trnpur_item_issues  
where iss_comp_code = p_company_code and iss_cr_status = 'R' and iss_type = 'IR' 
and iss_date >= p_from_date and iss_date <= p_to_date) w ,  
  
(select   
sum(iss_qty * iss_rate) 'ir_value'  
from trnpur_item_issues  
where iss_comp_code = p_company_code and iss_type = 'IR' and iss_date >= p_from_date 
and iss_date <= p_to_date) b ,  
  
(select   
sum(reciss_item_qty * reciss_item_rate) 'ap_val'  
from trnpur_item_rec_iss  
where reciss_comp_code = p_company_code and reciss_type = 'AP' and reciss_doc_date >= p_from_date 
and reciss_doc_date <= p_to_date) x ,  
  
(select   
sum(reciss_item_qty * reciss_item_rate) 'am_val'  
from trnpur_item_rec_iss  
where reciss_comp_code = p_company_code and reciss_type = 'AM' and reciss_doc_date >= p_from_date 
and reciss_doc_date <= p_to_date) y;  
  
 UPDATE tmp_pur_store_ledger_cons SET re_cap_val = IFNULL(re_cap_val,0) ,re_rev_val = IFNULL(re_rev_val,0) ,  
 rr_cap_val = IFNULL(rr_cap_val,0) ,rr_rev_val = IFNULL(rr_rev_val,0) ,  
 is_cap_val = IFNULL(is_cap_val,0) ,is_rev_val = IFNULL(is_rev_val,0) ,  
 ir_cap_val = IFNULL(ir_cap_val,0) ,ir_rev_val = IFNULL(ir_rev_val,0) ,  
 is_value = ifnull(is_value,0) ,ir_value = ifnull(ir_value,0),  
 ap_val = IFNULL(ap_val,0) ,am_val = IFNULL(am_val,0);

   SET SQL_SAFE_UPDATES = 1;
*/

END ;;
