CREATE DEFINER=`root`@`%` PROCEDURE `sp_upd_weightcard`(   
 compcode int ,fincode int, ticketno int ,  supplier int , area int , vehicleno varchar(20),
 loadwt decimal(8,1) , emptywt decimal(8,1) , netwt decimal(8,1) , Acceptedwt decimal(8,1) , wttype varchar(1), itemcode int,itemname varchar(30)
 )
BEGIN   
 
update trn_weight_card set wc_sup_code=supplier , wc_area_code=area,wc_vehicleno=vehicleno,
wc_partyloadwt = loadwt , wc_partyemptywt = emptywt, wc_partynetwt = netwt, wc_acceptedwt = Acceptedwt, wt_type = wttype , wc_itemcode = itemcode, wc_item = itemname
where wc_compcode = compcode and wc_fincode = fincode and  wc_ticketno=ticketno;  

END ;;
