CREATE DEFINER=`root`@`%` PROCEDURE `temp`()
BEGIN
/*
   SET @sql = NULL;
SELECT
  GROUP_CONCAT(DISTINCT
    CONCAT(
      'MAX(CASE WHEN acctran_led_code = ''',
      acctran_led_code,
      ''' THEN ',
      acctran_totamt,
      ' END) AS ',
      CONCAT('`', acctran_led_code, '`')
    )
  ) INTO @sql
FROM acc_tran   where acctran_accref_seqno in (58763) ;

SET @sql = CONCAT('SELECT  acctran_accref_seqno, ', @sql, ' 
                  FROM    acc_tran  where acctran_accref_seqno in (58763) 
                  GROUP   BY acctran_accref_seqno');

PREPARE stmt FROM @sql;
EXECUTE stmt;
DEALLOCATE PREPARE stmt;               
*/


SET @sql = NULL;
SELECT
  GROUP_CONCAT(DISTINCT
    CONCAT(
      'MAX(CASE WHEN led_name = ''',
      led_name,
      ''' THEN ',
      ledgerAmt,
      ' END) AS ',
      CONCAT('`', led_name, '`')
    )
  ) INTO @sql
FROM (select accref_voudate, acctran_accref_seqno, led_name, ledgercode,sum(ledgerAmt)  ledgerAmt from
(select accref_voudate,acctran_accref_seqno ,led_name,
acctran_led_code ledgercode,
acctran_totamt  ledgerAmt 
from acc_ref, acc_tran , acc_ledger_master where accref_comp_code = '1' and accref_finid = '23' and accref_voudate between '2024-01-01' and '2024-01-22' and accref_vou_type = 'BKP' and 
acctran_led_code = led_code and  accref_seqno = acctran_accref_seqno and acctran_led_code != 1653
)a1 group by accref_voudate, acctran_accref_seqno, led_name, ledgercode)a2;


PREPARE stmt FROM @sql;
EXECUTE stmt;
DEALLOCATE PREPARE stmt;               
END ;;
DELIMITER ;
