CREATE DEFINER=`root`@`%` PROCEDURE `test1`()
BEGIN
select cust_ref,case when acctran_dbamt > 0 then 'Debit' else 'Credit' end as group1, accref_vouno , accref_voudate , acctran_totamt
 from acc_ref join  acc_tran  on  accref_seqno =  acctran_accref_seqno 
join massal_customer  on acctran_led_code = cust_code 
left join  acc_adjustments on  accref_seqno = ref_docseqno and ref_ledcode = cust_code
where acctran_led_code = 512  and accref_voudate >= '2024-04-01' and accref_voudate <= '2024-12-31';
END ;;
DELIMITER ;
