/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`%` PROCEDURE `testtemp`(fromdate date,todate date)
BEGIN
SET @sql = NULL;
SELECT
  GROUP_CONCAT(DISTINCT
    CONCAT(
      'MAX(CASE WHEN cust_name = ''',
      cust_name,
      ''' THEN ',
      accref_seqno,
      ' END) AS ',
      CONCAT('`', cust_name, '`')
    )
  ) INTO @sql
FROM 
(
select accref_voudate , accref_vouno,accref_seqno ,cust_name,acctran_totamt from massal_customer , acc_ref, acc_tran where accref_seqno = acctran_accref_seqno and  accref_comp_code = 1 
and accref_finid =23 and accref_voudate between fromdate and  todate  and acctran_led_code = cust_code  and acctran_dbamt > 0 and acctran_accref_seqno in 
(select accref_seqno from acc_ref, acc_tran where accref_seqno = acctran_accref_seqno and  accref_comp_code = 1 
and accref_finid =23 and accref_voudate between fromdate and  todate  and acctran_led_code = 1756)) a1;

SET @sql = CONCAT('SELECT accref_seqno, ', @sql, ' 
                   FROM 
   (
select accref_voudate , accref_vouno,accref_seqno ,cust_name,acctran_totamt from massal_customer , acc_ref, acc_tran where accref_seqno = acctran_accref_seqno and  accref_comp_code = 1 
and accref_finid =23 and accref_voudate between fromdate and  todate and acctran_led_code = cust_code  and acctran_dbamt > 0 and acctran_accref_seqno in 
(select accref_seqno from acc_ref, acc_tran where accref_seqno = acctran_accref_seqno and  accref_comp_code = 1 
and accref_finid =23 and accref_voudate between fromdate and  todate  and acctran_led_code = 1756)) a1                
                   GROUP BY accref_seqno');

PREPARE stmt FROM @sql;
EXECUTE stmt;
DEALLOCATE PREPARE stmt;

END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
