CREATE DEFINER=`root`@`%` PROCEDURE `update_current_balance`()
BEGIN
    DECLARE done1 INT DEFAULT FALSE;
    DECLARE vcompcode INT;
    DECLARE vledcode INT;
    declare reccount int; 
 --   
    declare ledmaster cursor for select led_code,led_comp_code from acc_ledger_master order by led_code,led_comp_code;
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET done1 = TRUE;
    set reccount= 2026;	
	OPEN ledmaster;
       ins_loop1: LOOP
		FETCH ledmaster INTO vledcode,vcompcode;
		IF done1 THEN
        	  LEAVE ins_loop1;
		END IF;
        set reccount= reccount + 1;	 
        call acc_sp_inscurrent_balance(reccount,vledcode,'22',90);

   END loop;
     CLOSE ledmaster;
    
END ;;
